--
-- ADDR_LST_DTL_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ADDR_LST_DTL_VW
(ADDR_ROWID, ADDR_CAT, ADDR_TYP, CID_CODE, CID_SUB_CODE, 
 CID_CLMN_NM, CST_BR_CODE, ADDR_STS, RCRD_SQ, LST_RCRD_SQ, 
 SYS_CLMN_VAL, CLMN_VAL, CLMN_VAL_F, RTRN_CLMN_VAL, CID_NAME)
BEQUEATH DEFINER
AS 
SELECT addr_rowid,
           ADDR_CAT,
           ADDR_TYP,
           CID_CODE,
           CID_SUB_CODE,
           CID_CLMN_NM,
           CST_BR_CODE,
           ADDR_STS,
           RCRD_SQ,
           lst_RCRD_SQ,
           SYS_CLMN_VAL,
           CLMN_VAL,
           CLMN_VAL_F,
           RTRN_CLMN_VAL,
           Cid_addr_op_pkg.Get_cid_col_lbl (
               P_cntry_2_ltr   =>
                   NVL (CID_ADDR_OP_PKG.GET_USR_CNTRY_2_LTR_CODE, 'A'),
               P_lang_code    => NVL (CID_ADDR_OP_PKG.GET_USR_LANG_CODE, 'en'),
               P_lang_id      => NVL (CID_ADDR_OP_PKG.GET_USR_LANG_NO, 1),
               P_colmn_name   => CID_CLMN_NM,
               P_type         => 2)
               CID_NAME
      FROM (SELECT ROWID
                       addr_rowid,
                   ADDR_CAT,
                   ADDR_TYP,
                   CID_CODE,
                   CID_SUB_CODE,
                   CID_CLMN_NM,
                   CST_BR_CODE,
                   ADDR_STS,
                   RCRD_SQ,
                   MAX (RCRD_SQ)
                       KEEP (DENSE_RANK LAST ORDER BY RCRD_SQ)
                       OVER (PARTITION BY ADDR_CAT,
                                          ADDR_TYP,
                                          UPPER (CID_CLMN_NM),
                                          CST_BR_CODE)
                       lst_RCRD_SQ,
                   SYS_CLMN_VAL,
                   CLMN_VAL,
                   CLMN_VAL_F,
                   RTRN_CLMN_VAL
              FROM ADDR_LST_DTL
             WHERE     addr_cat =
                       NVL (cid_addr_op_pkg.get_usr_addr_cat, addr_cat)
                   AND addr_typ =
                       NVL (cid_addr_op_pkg.get_usr_addr_typ, addr_typ)
                   AND cst_br_code =
                       CASE
                           WHEN NVL (
                                    cid_addr_op_pkg.get_usr_addr_cst_br_code,
                                    '0') =
                                '0'
                           THEN
                               cst_br_code
                           ELSE
                               cid_addr_op_pkg.get_usr_addr_cst_br_code
                       END
                   AND CASE
                           WHEN NVL (cid_addr_op_pkg.get_usr_addr_rcrd_sq, 0) =
                                0
                           THEN
                               1
                           ELSE
                               CASE
                                   WHEN rcrd_sq <=
                                        cid_addr_op_pkg.get_usr_addr_rcrd_sq
                                   THEN
                                       1
                                   ELSE
                                       0
                               END
                       END =
                       1)
     WHERE RCRD_SQ = lst_RCRD_SQ;


--
-- AMS_V_USR_COD_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.AMS_V_USR_COD_PRV
(U_ID, USR_NAME, COD_TYP_NO, COD_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           C.COD_TYP_NO,
           C.COD_NO,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (C.COD_L_NM, C.COD_F_NM),
                   NVL (C.COD_F_NM, C.COD_L_NM))
               Type_NM,
           A.Add_Flag,
           A.View_Flag,
           A.Ad_U_Id,
           A.Ad_Date,
           1
               Rec_Src
      FROM AMS_COD_PRV A, User_R B, AMS_COD_DTL C
     WHERE     A.COD_TYP_NO = C.COD_TYP_NO
           AND A.COD_NO = C.COD_NO
           AND A.U_Id = B.U_Id
           AND (Add_Flag = 1 OR View_Flag = 1)
    UNION
    SELECT B.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           A.COD_TYP_NO,
           A.COD_NO,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (A.COD_L_NM, A.COD_F_NM),
                   NVL (A.COD_F_NM, A.COD_L_NM))
               Type_NM,
           0
               Add_Flag,
           0
               View_Flag,
           NULL
               Ad_U_Id,
           NULL
               Ad_Date,
           0
               Rec_Src
      FROM AMS_COD_DTL A, User_R B
     WHERE NOT EXISTS
               (SELECT 1
                  FROM AMS_COD_PRV
                 WHERE     COD_TYP_NO = A.COD_TYP_NO
                       AND COD_NO = A.COD_NO
                       AND U_Id = B.U_Id
                       AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.AMS_V_USR_COD_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';



