--
-- AQ$DOC_SYS_ID_Q_TBL_R  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.AQ$DOC_SYS_ID_Q_TBL_R
(QUEUE, NAME, ADDRESS, PROTOCOL, RULE, 
 RULE_SET, TRANSFORMATION)
BEQUEATH DEFINER
AS 
SELECT queue_name QUEUE, s.name NAME , address ADDRESS , protocol PROTOCOL, rule_condition RULE, ruleset_name RULE_SET, trans_name TRANSFORMATION  FROM "AQ$_DOC_SYS_ID_Q_TBL_S" s , sys.all_rules r WHERE (bitand(s.subscriber_type, 1) = 1) AND s.rule_name = r.rule_name and r.rule_owner = 'IAS20261'  WITH READ ONLY;


--
-- AQ$_DOC_SYS_ID_Q_TBL_F  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.AQ$_DOC_SYS_ID_Q_TBL_F
(Q_NAME, ROW_ID, MSGID, CORRID, PRIORITY, 
 STATE, DELAY, EXPIRATION, ENQ_TIME, ENQ_UID, 
 ENQ_TID, DEQ_TIME, DEQ_UID, DEQ_TID, RETRY_COUNT, 
 EXCEPTION_QSCHEMA, EXCEPTION_QUEUE, CSCN, DSCN, CHAIN_NO, 
 LOCAL_ORDER_NO, TIME_MANAGER_INFO, STEP_NO, USER_DATA, SENDER_NAME, 
 SENDER_ADDRESS, SENDER_PROTOCOL, DEQUEUE_MSGID, DELIVERY_MODE, SEQUENCE_NUM, 
 MSG_NUM, QUEUE_ID, USER_PROP, SUBSCRIBER_ID, SUBSCRIBER_NAME, 
 QUEUE_EVTID)
BEQUEATH DEFINER
AS 
SELECT  /*+ NO_MERGE (qo) USE_NL(iot) */ qt.q_name Q_NAME, qt.rowid ROW_ID, qt.msgid MSGID, qt.corrid CORRID, qt.priority PRIORITY, qt.state STATE, cast(FROM_TZ(qt.delay, '00:00') at time zone sessiontimezone as timestamp) DELAY, qt.expiration EXPIRATION, cast(FROM_TZ(qt.enq_time, '00:00') at time zone sessiontimezone as timestamp) ENQ_TIME, qt.enq_uid ENQ_UID, qt.enq_tid ENQ_TID, cast(FROM_TZ(qt.deq_time, '00:00') at time zone sessiontimezone as timestamp) DEQ_TIME, qt.deq_uid DEQ_UID, qt.deq_tid DEQ_TID, qt.retry_count RETRY_COUNT, qt.exception_qschema EXCEPTION_QSCHEMA, qt.exception_queue EXCEPTION_QUEUE, qt.cscn CSCN, qt.dscn DSCN, qt.chain_no CHAIN_NO, qt.local_order_no LOCAL_ORDER_NO, cast(FROM_TZ(qt.time_manager_info, '00:00') at time zone sessiontimezone as timestamp)   TIME_MANAGER_INFO, qt.step_no STEP_NO, qt.user_data USER_DATA, qt.sender_name SENDER_NAME, qt.sender_address SENDER_ADDRESS, qt.sender_protocol SENDER_PROTOCOL, qt.dequeue_msgid DEQUEUE_MSGID, 'PERSISTENT' DELIVERY_MODE, 0 SEQUENCE_NUM, 0 MSG_NUM, qo.qid QUEUE_ID, qt.user_prop USER_PROP, iot.subscriber# SUBSCRIBER_ID, iot.name SUBSCRIBER_NAME, iot.queue# QUEUE_EVTID FROM "DOC_SYS_ID_Q_TBL" qt, "AQ$_DOC_SYS_ID_Q_TBL_I" iot, SYS.ALL_INT_DEQUEUE_QUEUES qo WHERE qt.msgid=iot.msgid  and qt.q_name = qo.name  AND qo.owner = 'IAS20261' AND iot.msg_priority = qt.priority AND  iot.msg_enq_time = qt.enq_time AND  iot.msg_step_no = qt.step_no  AND iot.msg_local_order_no = qt.local_order_no AND   iot.msg_chain_no = qt.chain_no  WITH READ ONLY;


