CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_AR_TRANS_SEQ
(ONYX_DOC_TYP, DOC_TYP, DOC_TYP_NM, DOC_NO, REP_CODE, 
 BRN_NO, BILL_DOC_TYPE, TYP_NO, BANK_NO, W_CODE, 
 E_INVC_MTHD_NO)
