         , Doc_Typ
         ,Doc_Typ_Nm
         ,Doc_No
         ,Rep_Code
         ,Brn_No
         ,Bill_Doc_Type
         ,Typ_No
         ,Bank_No
         ,W_Code
         ,E_INVC_MTHD_NO
     From Table (Dts_Crt_Vw_Pkg.Dyn_Crt_Srl_Vw (0, 2))
   Union All
   Select 52 Onyx_Doc_Typ
         ,Doc_Typ
         ,Doc_Typ_Nm
         ,Doc_No
         ,Rep_Code
         ,Brn_No
         ,Bill_Doc_Type
         ,Typ_No
         ,Bank_No
         ,W_Code
         ,E_INVC_MTHD_NO
     From Table (Dts_Crt_Vw_Pkg.Dyn_Crt_Srl_Vw (1))
   Union All
   Select 53 Onyx_Doc_Typ
        ,Doc_Typ
         ,Doc_Typ_Nm
         ,Doc_No
         ,Rep_Code
         ,Brn_No
         ,Bill_Doc_Type
         ,Typ_No
         ,Bank_No
         ,W_Code
         ,E_INVC_MTHD_NO
     From Table (Dts_Crt_Vw_Pkg.Dyn_Crt_Srl_Vw (2))
   Union All
   Select Distinct 4 Onyx_Doc_Typ
                  ,Doc_Typ
                  ,Doc_Typ_Nm
                  ,Doc_No
                  ,Rep_Code
                  ,Brn_No
                  ,Bill_Doc_Type
                  ,Typ_No
                  ,Bank_No
                  ,W_Code
                  ,E_INVC_MTHD_NO
     From Table (Dts_Crt_Vw_Pkg.Dyn_Crt_Srl_Vw (3))
   Union All
   Select Distinct 5 Onyx_Doc_Typ
                  ,Doc_Typ
                  ,Doc_Typ_Nm
                  ,Doc_No
                  ,Rep_Code
                  ,Brn_No
                  ,Bill_Doc_Type
                  ,Typ_No
                  ,Bank_No
                  ,W_Code
                  ,E_INVC_MTHD_NO
     From Table (Dts_Crt_Vw_Pkg.Dyn_Crt_Srl_Vw (4))
   Union All
   Select Distinct 9 Onyx_Doc_Typ
          ,Doc_Typ
         ,Doc_Typ_Nm
         ,Doc_No
         ,Rep_Code
         ,Brn_No
         ,Bill_Doc_Type
         ,Typ_No
         ,Bank_No
         ,W_Code
