--
-- FAS_V_USR_GNR_INPT_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.FAS_V_USR_GNR_INPT_PRV
(U_ID, USR_NAME, INPT_TYP, INPT_TYP_NM, INPT_NO, 
 INPT_NM, ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Inpt_Typ,
          N.Form_Name Inpt_Typ_Nm,
          A.Inpt_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Typ_L_Nm, C.Typ_F_Nm),Nvl (C.Typ_F_Nm, C.Typ_L_Nm)) Typ_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          1 Rec_Src
     From Fas_Gnr_Inpt_Prv A, User_R B, Fas_V_Gnr_Inpt_Prv C, Ias_Form_Name N
    Where A.Inpt_No = C.Typ_No
          And A.Inpt_Typ = C.Inpt_Typ
          And C.Form_No = N.Form_No
          And N.Lang_no = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
          And A.U_Id = B.U_Id
          And (Add_Flag = 1 Or View_Flag = 1 )
  Union
 Select B.U_Id,
        Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
        A.Inpt_Typ,
        N.Form_Name Inpt_Typ_Nm,
        A.Typ_No,
        Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (A.Typ_L_Nm, A.Typ_F_Nm),Nvl (A.Typ_F_Nm, A.Typ_L_Nm)) Typ_Nm,
        0 Add_Flag,
        0 View_Flag,
        Null Ad_U_Id,
        Null Ad_Date,
        Null Up_U_Id,
        Null Up_Date,
        0 Rec_Src
   From Fas_V_Gnr_Inpt_Prv A, User_R B, Ias_Form_Name N
  Where A.Form_No = N.Form_No 
    And N.Lang_no = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
    And Not Exists
             (Select 1
                From Fas_Gnr_Inpt_Prv D
               Where D.Inpt_Typ = A.Inpt_Typ  And D.Inpt_No = A.Typ_No And  D.U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.FAS_V_USR_GNR_INPT_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.FAS_V_USR_GNR_INPT_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.FAS_V_USR_GNR_INPT_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- FMS_V_USR_COD_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.FMS_V_USR_COD_PRV
(U_ID, USR_NAME, COD_TYP_NO, COD_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           C.COD_TYP_NO,
           C.COD_NO,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (C.COD_L_NM, C.COD_F_NM),
                   NVL (C.COD_F_NM, C.COD_L_NM))
               Type_NM,
           A.Add_Flag,
           A.View_Flag,
           A.Ad_U_Id,
           A.Ad_Date,
           1
               Rec_Src
      FROM FMS_COD_PRV A, User_R B, FMS_COD_DTL C
     WHERE     A.COD_TYP_NO = C.COD_TYP_NO
           AND A.COD_NO = C.COD_NO
           AND A.U_Id = B.U_Id
           AND (Add_Flag = 1 OR View_Flag = 1)
    UNION
    SELECT B.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           A.COD_TYP_NO,
           A.COD_NO,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (A.COD_L_NM, A.COD_F_NM),
                   NVL (A.COD_F_NM, A.COD_L_NM))
               Type_NM,
           0
               Add_Flag,
           0
               View_Flag,
           NULL
               Ad_U_Id,
           NULL
               Ad_Date,
           0
               Rec_Src
      FROM FMS_COD_DTL A, User_R B
     WHERE NOT EXISTS
               (SELECT 1
                  FROM FMS_COD_PRV
                 WHERE     COD_TYP_NO = A.COD_TYP_NO
                       AND COD_NO = A.COD_NO
                       AND U_Id = B.U_Id
                       AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.FMS_V_USR_COD_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';



--
-- GET_ALERT_V  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GET_ALERT_V
(ID, ALRT_NO, LBL_NO, SYS_NO, FORM_NO, 
 ALRT_DAY, ALRT_PRD_TYP, ALRT_SLCT_WHR, ALRT_SLCT_ORDR, ALRT_HIDE, 
 RPRT_NM)
BEQUEATH DEFINER
AS 
SELECT ROWID
                 ID,
             ALRT_NO,
             IAS_Gen_Pkg.Get_Prompt (1, LBL_NO)
                 LBL_NO,
             SYS_NO,
             (SELECT N.FORM_NAME     NM
                FROM S_ERP_SYSTEM S, FORM_DETAIL F, IAS_FORM_NAME N
               WHERE     S.SYS_CODE = F.F_SYS
                     AND F.FORM_NO = N.FORM_NO
                     AND S.FORM_NO = N.FORM_NO
                     AND N.LANG_NO = 1
                     AND S.INACTIVE = 0
                     AND S.SYS_NO = S_ALRT_DATA_TMP.SYS_NO)
                 FORM_NO,
             ALRT_DAY,
             ALRT_PRD_TYP,
             ALRT_SLCT_WHR,
             ALRT_SLCT_ORDR,
             ALRT_HIDE,
             RPRT_NM
        FROM S_ALRT_DATA_TMP
       WHERE U_ID = 1
    ORDER BY ALRT_NO;


--
-- GLS_V_BILL_ADVNC_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_BILL_ADVNC_YR
(ROW_ID, UMARKER, DOC_SRL, DOC_NO, DOC_DATE, 
 AC_CODE, AC_CODE_DTL, C_CODE, C_NAME, CUR_CODE, 
