--
-- GLS_V_DIRCTORYS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_DIRCTORYS
(DIR_TYP, DIR_CODE, DIR_LINK_CODE, DIR_L_NM, DIR_F_NM, 
 AC_DTL_TYP, AC_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, DIR_LINK, 
 ACTIVE, INACTIVE, AD_DATE)
BEQUEATH DEFINER
AS 
SELECT M.DIR_TYP,D.DIR_CODE,DIR_LINK_CODE ,D.DIR_L_NM,D.DIR_F_NM ,M.AC_DTL_TYP,M.AC_CODE,M.AC_CODE_DTL,M.AC_CODE_DTL_SUB,M.DIR_LINK,m.ACTIVE,D.INACTIVE,D.AD_DATE
										         FROM GLS_DIRCTORYS_TYP M,GLS_DIRCTORYS D
										        WHERE M.DIR_TYP=D.DIR_TYP  
										        AND NVL(M.ACTIVE,0)=1 and 3=3;


--
