--
-- GNR_V_SUB_DOC_TYP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_V_SUB_DOC_TYP
(DOC_TYP, TYP_NO, TYP_L_NM, TYP_F_NM)
BEQUEATH DEFINER
AS 
SELECT "DOC_TYP",
             "TYP_NO",
             "TYP_L_NM",
             "TYP_F_NM"
        FROM (SELECT rq_doc_type                  doc_typ,
                     rq_type                      typ_no,
                     NVL (rq_name, rq_e_name)     typ_l_nm,
                     NVL (rq_e_name, rq_name)     typ_f_nm
                FROM ias_glrq_types
             UNION ALL
               SELECT 1                              doc_typ,
                     Jv_Type                        typ_no,
                     NVL (Jv_Name, Jv_E_Name)     typ_l_nm,
                     NVL (Jv_E_Name, Jv_Name)     typ_f_nm
                FROM Jv_Types
             UNION ALL
               SELECT decode(v_type,1,2,2,3)         doc_typ,
                     v_type_no                        typ_no,
                     NVL (v_type_a_name, v_type_e_name)     typ_l_nm,
                     NVL (v_type_e_name, v_type_a_name)     typ_f_nm
               FROM Ias_Vouchr_Type
             UNION ALL
              SELECT decode(NOTE_TYPE,1,21,2,22)         doc_typ,
                     NOTE_TYPE_NO                        typ_no,
                     NVL (NOTE_A_NAME, NOTE_E_NAME)     typ_l_nm,
                     NVL (NOTE_E_NAME, NOTE_A_NAME)     typ_f_nm
                FROM IAS_NOTE_TYPES
              UNION ALL
                SELECT 53                             doc_typ,
                     so_type                        typ_no,
                     NVL (so_a_name, so_e_name)     typ_l_nm,
                     NVL (so_e_name, so_a_name)     typ_f_nm
                FROM ias_sorder_types
              UNION ALL
                SELECT 52                             doc_typ,
                     qt_type                        typ_no,
                     NVL (qt_a_name, qt_e_name)     typ_l_nm,
                     NVL (qt_e_name, qt_a_name)     typ_f_nm
                FROM ias_quot_types 
              UNION ALL          
             SELECT 42                             doc_typ,
                     PO_type                        typ_no,
                     NVL (PO_A_NAME, PO_e_NAME)     typ_l_nm,
                     NVL (PO_e_NAME, PO_A_NAME)     typ_f_nm
                FROM IAS_PORDER_TYPES  
             UNION ALL          
             SELECT 31                             doc_typ,
                     REQ_TYPE                        typ_no,
                     NVL (REQ_NAME, REQ_E_NAME)     typ_l_nm,
                     NVL (REQ_E_NAME, REQ_NAME)     typ_f_nm
                FROM REQUEST_TYPES
                WHERE OUT_TRNSFR =2
                UNION ALL
             SELECT 136         doc_typ,
                   Typ_no       Type_no,
                   Typ_l_nm     Type_l_nm,
                   Typ_f_nm     Type_f_nm                  
                FROM Ias_ar_typs
                WHERE Ar_type_no = 9
               UNION ALL
            SELECT 40             doc_typ,
                   Pr_TYPE       TYPE_No,
                   Pr_A_NAME     Type_L_Nm,
                   Pr_E_NAME     Type_F_Nm                   
              FROM Ias_Preq_Types 
              UNION ALL
            SELECT 79      doc_typ,
                    STK_TYPE       TYPE_No,
                    STK_NAME     Type_L_Nm,
                    STK_E_NAME     Type_F_Nm                   
            FROM Ias_Stk_Adjst_Types
            WHERE NVL(RQ_STK_TYPE_FLG,0) = 1 ) x 
           ORDER BY x.doc_typ, x.typ_no;


--
-- GNR_V_USR_TAX_TYP_CLC_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_V_USR_TAX_TYP_CLC_PRV
(U_ID, USR_NAME, CLC_TYP_NO, CLC_TYP_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.CLC_TYP_NO,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.CLC_TYP_L_NM, C.CLC_TYP_F_NM),Nvl (C.CLC_TYP_F_NM, C.CLC_TYP_L_NM)) CLC_TYP_NM,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From GNR_TAX_TYP_CLC_PRV A, User_R B,GNR_TAX_TYP_CLC_MST C
    Where     A.U_Id = B.U_Id
          And A.CLC_TYP_NO = C.CLC_TYP_NO
          And (Add_Flag = 1 Or View_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.CLC_TYP_NO,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.CLC_TYP_L_NM, C.CLC_TYP_F_NM),Nvl (C.CLC_TYP_F_NM, C.CLC_TYP_L_NM)) CLC_TYP_NM,
          0 Add_Flg,
          0 View_Flg,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, GNR_TAX_TYP_CLC_MST C
    Where Not Exists
             (Select 1
                From GNR_TAX_TYP_CLC_PRV
               Where CLC_TYP_NO = C.CLC_TYP_NO And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.GNR_V_USR_TAX_TYP_CLC_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.GNR_V_USR_TAX_TYP_CLC_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.GNR_V_USR_TAX_TYP_CLC_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



