--
-- HPS_V_USR_DCTR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.HPS_V_USR_DCTR_PRV
(U_ID, USR_NAME, DCTR_NO, DCTR_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
																														          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																														                  1, NVL (b.u_a_name, b.u_e_name),
																														                  NVL (b.u_e_name, b.u_a_name)
																														                 ) usr_name,
																														          c.dctr_no,
																														          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																														                  1, NVL (c.dctr_l_nm, c.dctr_f_nm),
																														                  NVL (c.dctr_f_nm, c.dctr_l_nm)
																														                 ) dctr_nm,
																														          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
																														          1 rec_src
																														   FROM   hps_dctr_prv a,
																														          user_r b,
																														          hps_dctr c
																														   WHERE  a.u_id = b.u_id AND a.dctr_no = c.dctr_no
																														   UNION
																														   SELECT b.u_id,
																														          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																														                  1, NVL (b.u_a_name, b.u_e_name),
																														                  NVL (b.u_e_name, b.u_a_name)
																														                 ) usr_name,
																														          c.dctr_no,
																														          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																														                  1, NVL (c.dctr_l_nm, c.dctr_f_nm),
																														                  NVL (c.dctr_f_nm, c.dctr_l_nm)
																														                 ) dctr_nm,
																														          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
																														          NULL up_date, 0 rec_src
																														   FROM   user_r b,
																														          hps_dctr c
																														   WHERE  NOT EXISTS (
																														                   SELECT 1
																														                   FROM   hps_dctr_prv
																														                   WHERE  dctr_no = c.dctr_no AND u_id = b.u_id
																														                          AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.HPS_V_USR_DCTR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.HPS_V_USR_DCTR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.HPS_V_USR_DCTR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- HPS_V_USR_DEPT_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.HPS_V_USR_DEPT_PRV
(U_ID, USR_NAME, DEPT_NO, DEPT_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_name,
          c.DEPT_NO,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.dept_l_nm, c.dept_f_nm),
                  NVL (c.dept_f_nm, c.dept_l_nm)
                 ) dept_nm,
          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
          1 rec_src
   FROM   hps_dept_prv a,
          user_r b,
          hps_dept c
   WHERE  a.u_id = b.u_id AND a.dept_no = c.dept_no
   UNION
   SELECT b.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_name,
          c.dept_no,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.dept_l_nm, c.dept_f_nm),
                  NVL (c.dept_f_nm, c.dept_l_nm)
                 ) dept_nm,
          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
          NULL up_date, 0 rec_src
   FROM   user_r b,
          hps_dept c
   WHERE  NOT EXISTS (
               SELECT 1
               FROM   hps_dept_prv
               WHERE  DEPT_NO = c.DEPT_NO AND u_id = b.u_id
                      AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.HPS_V_USR_DEPT_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.HPS_V_USR_DEPT_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.HPS_V_USR_DEPT_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- HPS_V_USR_GNR_CODE_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.HPS_V_USR_GNR_CODE_PRV
(U_ID, USR_NAME, CODE_TYP, CODE_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
						          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
						          C.CODE_TYP,
						          C.CODE_NO,
						          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.CODE_L_NM, C.CODE_F_NM),Nvl (C.CODE_F_NM, C.CODE_L_NM)) Type_NM,
						          A.Add_Flag,
						          A.View_Flag,
						          A.Ad_U_Id,
						          A.Ad_Date,
						          1 Rec_Src
						     From HPS_GNR_CODE_PRV A, User_R B, HPS_GNR_CODE_DTL C
						    Where   A.CODE_TYP = C.CODE_TYP
						          And A.CODE_NO = C.CODE_NO
						          And A.U_Id = B.U_Id
						          And (Add_Flag = 1 Or View_Flag = 1)
						  Union
						 Select B.U_Id,
						          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
						          A.CODE_TYP,
						          A.CODE_NO,
						          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (A.CODE_L_NM, A.CODE_F_NM),Nvl (A.CODE_F_NM, A.CODE_L_NM)) Type_NM,
						          0 Add_Flag,
						          0 View_Flag,
						          Null Ad_U_Id,
						          Null Ad_Date,
						          0 Rec_Src
						     From HPS_GNR_CODE_DTL  A,User_R B
						    Where Not Exists
						             (Select 1
						                From HPS_GNR_CODE_PRV
						               Where CODE_TYP = A.CODE_TYP And CODE_NO = A.CODE_NO And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.HPS_V_USR_GNR_CODE_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';



