--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ADJST_INSTALLMENT_MST_YR
(ROW_ID, UMARKER, DOC_NO, DOC_SER, DOC_DATE, 
 DOC_TYPE_REF, DOC_NO_REF, DOC_SER_REF, DOC_DATE_REF, DOC_BRN_REF, 
 C_CODE, CC_CODE, PJ_NO, ACTV_NO, A_CY, 
 DOC_AMT_REF, DOC_DESC, REF_NO, DOC_SEQ, AUTO_ADJ_FLG, 
 AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, CMP_NO, 
 BRN_NO, BRN_YEAR, BRN_USR, UP_CNT, PR_REP, 
 AD_TRMNL_NM, UP_TRMNL_NM)
