AS 
SELECT ROWID ROW_ID,1 UMARKER , DOC_NO,DOC_SER,DOC_DATE,DOC_TYPE_REF,DOC_NO_REF,DOC_SER_REF,DOC_DATE_REF,DOC_BRN_REF,C_CODE,CC_CODE,PJ_NO,ACTV_NO,A_CY,DOC_AMT_REF,DOC_DESC,REF_NO,DOC_SEQ,AUTO_ADJ_FLG,AD_U_ID,AD_DATE,UP_U_ID,UP_DATE,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,UP_CNT,PR_REP,AD_TRMNL_NM,UP_TRMNL_NM FROM IAS20241.IAS_ADJST_INSTALLMENT_MST UNION ALL  SELECT ROWID ROW_ID,1 UMARKER , DOC_NO,DOC_SER,DOC_DATE,DOC_TYPE_REF,DOC_NO_REF,DOC_SER_REF,DOC_DATE_REF,DOC_BRN_REF,C_CODE,CC_CODE,PJ_NO,ACTV_NO,A_CY,DOC_AMT_REF,DOC_DESC,REF_NO,DOC_SEQ,AUTO_ADJ_FLG,AD_U_ID,AD_DATE,UP_U_ID,UP_DATE,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,UP_CNT,PR_REP,AD_TRMNL_NM,UP_TRMNL_NM FROM IAS20251.IAS_ADJST_INSTALLMENT_MST UNION ALL  SELECT ROWID ROW_ID,1 UMARKER , DOC_NO,DOC_SER,DOC_DATE,DOC_TYPE_REF,DOC_NO_REF,DOC_SER_REF,DOC_DATE_REF,DOC_BRN_REF,C_CODE,CC_CODE,PJ_NO,ACTV_NO,A_CY,DOC_AMT_REF,DOC_DESC,REF_NO,DOC_SEQ,AUTO_ADJ_FLG,AD_U_ID,AD_DATE,UP_U_ID,UP_DATE,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,UP_CNT,PR_REP,AD_TRMNL_NM,UP_TRMNL_NM FROM IAS20261.IAS_ADJST_INSTALLMENT_MST UNION ALL  SELECT ROWID ROW_ID,2 UMARKER , DOC_NO,DOC_SER,DOC_DATE,DOC_TYPE_REF,DOC_NO_REF,DOC_SER_REF,DOC_DATE_REF,DOC_BRN_REF,C_CODE,CC_CODE,PJ_NO,ACTV_NO,A_CY,DOC_AMT_REF,DOC_DESC,REF_NO,DOC_SEQ,AUTO_ADJ_FLG,AD_U_ID,AD_DATE,UP_U_ID,UP_DATE,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,UP_CNT,PR_REP,AD_TRMNL_NM,UP_TRMNL_NM FROM IAS_ADJST_INSTALLMENT_MST WHERE 1 = 2;


--
-- IAS_V_AP_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AP_TYPES
(AP_TYPE, TYPE_NO, TYPE_L_NM, TYPE_F_NM, AD_DATE, 
 AD_U_ID, UP_DATE, UP_U_ID)
BEQUEATH DEFINER
AS 
Select Ap_Type ,  TYPE_No , Type_L_Nm ,  Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID
From 
(
SELECT  1 Ap_Type , Pr_TYPE TYPE_No ,Pr_A_NAME Type_L_Nm , Pr_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  Ias_Preq_Types
Union All
SELECT  2 Ap_Type , Po_TYPE TYPE_No ,Po_A_NAME Type_L_Nm , Po_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  Ias_Porder_Types
Union All
SELECT 3 Ap_Type , GRN_TYPE TYPE_No ,GRN_A_NAME Type_L_Nm , GRN_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_GRN_TYPES
Union All
SELECT  4 Ap_Type , Bill_TYPE_No TYPE_No ,Type_L_NAME Type_L_Nm , Type_F_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  ias_Ap_Bill_Types
Union All
SELECT 6 ap_type, typ_no type_no, typ_l_name type_l_nm,typ_f_name type_f_nm, ad_date, ad_u_id, up_date, up_u_id  FROM   IAS_AP_TYPES
Union All
Select 16 Ap_Type, Add_Dsc_Typ_No Type_No, Type_L_Name Type_L_Nm,Type_F_Name Type_F_Nm, Ad_Date, Ad_U_Id, Up_Date, Up_U_Id  From Ias_Ap_Add_Dsc_Typ
);

COMMENT ON COLUMN IAS20261.IAS_V_AP_TYPES.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_AP_TYPES.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.IAS_V_AP_TYPES.UP_U_ID IS '760 - „⁄œ· «·”Ã·';



--
-- IAS_V_AUD_PRNT_REP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AUD_PRNT_REP
(PR_CNT, DOC_NO, DOC_TYP, BRN_NO, DOC_DATE, 
 REP_NM)
BEQUEATH DEFINER
AS 
SELECT COUNT (DOC_NO)     PR_CNT,
             DOC_NO,
             DOC_TYP,
             BRN_NO,
             DOC_DATE,
             REP_NM
        FROM IAS_AUD_PRNT_REP
    GROUP BY DOC_NO,
             DOC_TYP,
             BRN_NO,
             DOC_DATE,
             REP_NM;

