--
-- IAS_V_COSTING_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_COSTING_TYPES
(A_CODE, A_CODE_NAME)
BEQUEATH DEFINER
AS 
SELECT A_CODE, MIN (A_CODE_NAME) A_CODE_NAME
    FROM (SELECT A_CODE, A_CODE_NAME
          FROM COSTING_TYPES
               UNPIVOT ( (A_CODE, A_CODE_name)
                       FOR NAME_OF_A_CODE
                       IN ( (AC1_AC, AC1_NAME)
                         , (AC2_AC, AC2_NAME)
                         , (AC3_AC, AC3_NAME)
                         , (AC4_AC, AC4_NAME)
                         , (AC5_AC, AC5_NAME)
                         , (AC6_AC, AC5_NAME)
                         , (AC7_AC, AC7_NAME)
                         , (AC8_AC, AC8_NAME)
                         , (AC9_AC, AC9_NAME)
                         , (AC10_AC, AC10_NAME)
                         , (AC11_AC, AC11_NAME)
                         , (AC12_AC, AC12_NAME)
                         , (AC13_AC, AC13_NAME)
                         , (AC14_AC, AC14_NAME)
                         , (AC15_AC, AC15_NAME)
                         , (AC16_AC, AC16_NAME)
                         , (AC17_AC, AC17_NAME)
                         , (AC18_AC, AC18_NAME)
                         , (AC19_AC, AC19_NAME)
                         , (AC20_AC, AC20_NAME)
                         , (AC21_AC, AC21_NAME)
                         , (AC22_AC, AC22_NAME)
                         , (AC23_AC, AC23_NAME)
                         , (AC24_AC, AC24_NAME)
                         , (AC25_AC, AC25_NAME)))
          WHERE A_CODE IS NOT NULL)
    GROUP BY A_CODE;

COMMENT ON COLUMN IAS20261.IAS_V_COSTING_TYPES.A_CODE IS '129 - —ﬁ„ «·Õ”«»';



