--
-- IAS_V_INV_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_INV_TYPES
(INV_TYPE, TYPE_NO, TYPE_L_NM, TYPE_F_NM, AD_DATE, 
 AD_U_ID, UP_DATE, UP_U_ID)
BEQUEATH DEFINER
AS 
Select Inv_Type ,  TYPE_NO , Type_L_Nm ,  Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID
From 
(
SELECT  1 Inv_Type , REQ_TYPE TYPE_NO ,REQ_NAME Type_L_Nm , REQ_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  REQUEST_TYPES
Union All
SELECT  2 Inv_Type , INCOM_TYPE TYPE_NO ,INCOM_NAME Type_L_Nm , INCOM_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM INCOM_TYPES
Union All
SELECT 3  Inv_Type , OUT_TYPE TYPE_NO ,OUT_NAME Type_L_Nm , OUT_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM OUT_TYPES
Union All
SELECT  4 Inv_Type , TR_TYPE TYPE_NO ,TR_NAME Type_L_Nm , TR_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM TRANSFER_TYPES
Union All
SELECT  5 Inv_Type , STK_TYPE TYPE_NO ,STK_NAME Type_L_Nm , STK_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM IAS_STK_ADJST_TYPES
Union All
SELECT  6 Inv_Type , INV_TYPE TYPE_NO ,INV_NAME Type_L_Nm , INV_E_NAME Type_F_Nm ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM IAS_INV_TYPES);

COMMENT ON COLUMN IAS20261.IAS_V_INV_TYPES.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_INV_TYPES.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.IAS_V_INV_TYPES.UP_U_ID IS '760 - „⁄œ· «·”Ã·';



