																		              Cr_Card_Doc_No_Ref, 
																		              Cr_Card_Doc_No_Ref_Scnd, 
																		              Cr_Card_Doc_No_Ref_Thrd, 
																		              Cr_Card_Dsc, 
																		              Cr_Card_Dsc_Scnd, 
																		              Cr_Card_Dsc_Thrd, 
																		              Cr_Card_No, 
																		              Cr_Card_No_Scnd, 
																		              Cr_Card_No_Thrd,
												                          Ac_Amt,
											                            Pymnt_Ac,
																					        Ac_Code,
																					        Ac_Code_Dtl,
																					        Ac_Dtl_Typ,
																					        Insrnce_Add_Lmt_Mst,
																					        INSRNCE_LMT_AMT_LOC_DOC,
																					        INSRNCE_LMT_APPRVD_AMT_LOC_DOC,
																					        INSRNCE_ADD_LMT_DOC,
																					        INSRNCE_ADD_LMT_DTL,
																					        INSRNCE_DIAGNOSIS,
																					        INSRNCE_APPRVD_CODE,
																					        C_Tax_Code,
																					        Tax_Bill_Typ,
												                          Bill_No_Conn,
				                                          bill_ser_Conn,
				                                          SI_TYPE ,
				                                          BILL_WITHOUT_AUTO_OTHR_AMT,
				                                          Ptnt_No,
				                                          DRIVER_NO,  m.emp_no,
				                                          E.BILL_DOC_TYPE_SUB,
				                                          E.Ass_No,
                                                  C_Tel,
                                                  M.CONN_SI_WITH_OUTGONG,
                                                  M.SLS_ORDR_REF, M.PRFRM_INVC_NO,
                                                  CRD_NO_DISC,
                                                  Cntrct_No
    FROM IAS20251.Ias_Bill_Mst m, IAS20251.Ias_Bill_Mst_Extnd E,IAS20251.S_Flags
   WHERE M.Bill_Ser=E.Bill_Ser(+)
     And Bill_Doc_Type = Flg_value
     AND lang_no =1
     AND Flg_Code = 'TYPE_NAME_SI'         
     AND Decode(0,1,brn_no,1) = Decode(0,1,1,1)
	    
   ORDER BY bill_no, bill_doc_type, bill_date;


--
-- IAS_V_USR_ALRT_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_ALRT_PRV
(U_ID, USR_NAME, ALRT_NO, PRV_FLG, SEND_TYP, 
 RPRT_ATTACH_FLG, SND_LANG_NO, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
          DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),1, NVL (B.U_A_Name, B.U_E_Name),
                  NVL (B.U_E_Name, B.U_A_Name))Usr_Nm,
          A.ALRT_NO,
          A.Prv_Flg,
          A.Send_Typ,
          A.Rprt_Attach_Flg,
          A.SND_LANG_NO,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     FROM S_USR_ALRT_SYS_PRIV A, User_R B, S_ALRT_SYS_MST C
    WHERE     A.U_Id = B.U_Id
          AND A.ALRT_NO = C.ALRT_NO
          AND Prv_Flg = 1         
   UNION
   SELECT B.U_Id,
          DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                  1, NVL (B.U_A_Name, B.U_E_Name),
                  NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.ALRT_NO,
          0 Prv_Flg,
          NULL Send_Typ,
          0 Rprt_Attach_Flg,
          0 SND_LANG_NO,
          NULL Ad_U_Id,
          NULL Ad_Date,
          NULL Up_U_Id,
          NULL Up_Date,
          0 Rec_Src
     FROM User_R B, S_ALRT_SYS_MST C
    WHERE NOT EXISTS
                 (SELECT 1
                    FROM S_USR_ALRT_SYS_PRIV
                   WHERE     ALRT_NO = C.ALRT_NO
                         AND U_Id = B.U_Id
                         AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_ALRT_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ALRT_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ALRT_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_FLG_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_FLG_PRV
(U_ID, USR_NAME, FLG_CODE, FLG_VALUE, PRIV_FLAG, 
 AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Flg_Code,
          C.Flg_Value,
          A.Priv_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From S_FLAGS_PRIV A, User_R B, S_FLAGS C
    Where A.U_Id = B.U_Id
      And A.Flg_Code = C.Flg_Code
      And A.Flg_Value = C.Flg_Value
      And A.Priv_Flag = 1 
    --And C.LBL_NO IS NOT NULL 
      And C.FLG_ST = 1
      AND C.LANG_NO = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Flg_Code,
          C.Flg_Value,
          0 Priv_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, S_FLAGS C
    Where C.FLG_ST = 1
      AND C.FLG_PRIV = 1
    --And C.LBL_NO IS NOT NULL 
      AND C.LANG_NO = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
      AND Not Exists
             (Select 1
                From S_FLAGS_PRIV
               Where U_Id = B.U_Id And Flg_Code = C.Flg_Code And   Flg_Value = C.Flg_Value And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_FLG_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_FLG_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_FLG_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



