-- IAS_V_USR_GLS_NOTE_TYP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_GLS_NOTE_TYP_PRV
(U_ID, USR_NAME, NOTE_TYPE, NOTE_TYPE_NO, NOTE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Note_Type ,
          A.Note_Type_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Note_A_Name, C.Note_E_Name),Nvl (C.Note_E_Name, C.Note_A_Name)) Note_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From IAS_PRIV_NOTE_TYPES A, User_R B, Ias_NOTE_TYPES  C
    Where     A.U_Id = B.U_Id
          And A.Note_Type_No = C.Note_Type_No
          And (Add_Flag = 1 Or View_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Note_Type ,
          C.Note_Type_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Note_A_Name, C.Note_E_Name),Nvl (C.Note_E_Name, C.Note_A_Name)) Note_Nm,
          0 Add_Flag,
          0 View_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, Ias_NOTE_TYPES C
    Where Not Exists
             (Select 1
                From IAS_PRIV_NOTE_TYPES
               Where Note_Type_No = C.Note_Type_No  And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_GLS_NOTE_TYP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

