--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_INV_TYP_PRV
(U_ID, USR_NAME, INV_TYPE, INV_NM, ADD_FLAG, 
 VIEW_FLAG, FILL_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Inv_Type,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Inv_Name, C.Inv_E_Name),Nvl (C.Inv_E_Name, C.Inv_Name)) Inv_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Fill_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From IAS_PRIV_INV_TYPE A, User_R B,IAS_INV_TYPES C
    Where     A.U_Id = B.U_Id
          And A.Inv_Type = C.Inv_Type
          And (A.Add_Flag = 1 Or A.View_Flag = 1 Or A.Fill_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Inv_Type,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Inv_Name, C.Inv_E_Name),Nvl (C.Inv_E_Name, C.Inv_Name)) Inv_Nm,
          0 Add_Flag,
          0 View_Flag,
          0 Fill_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, IAS_INV_TYPES C
    Where Not Exists
             (Select 1
                From IAS_PRIV_INV_TYPE
               Where Inv_Type = C.Inv_Type And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_INV_TYP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

