COMMENT ON COLUMN IAS20261.IAS_V_USR_INV_TYP_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_PUR_MAN_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_PUR_MAN_PRV
(U_ID, USR_NAME, PMAN_CODE, PMAN_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.pman_code,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.pman_a_name, c.pman_e_name),
                  NVL (c.pman_e_name, c.pman_a_name)
                 ) pman_nm,
          a.add_flag,
          a.view_flag,
          a.ad_u_id,
          a.ad_date,
          a.up_u_id,
          a.up_date,
          1 rec_src
   FROM   Ias_Priv_Pman a,
          user_r b,
          Ias_Purchs_Man c
   WHERE  a.u_id = b.u_id
   AND    a.Pman_Code = c.Pman_Code
   AND    (add_flag = 1 OR view_flag = 1)
   UNION
   SELECT b.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.pman_code,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.pman_a_name, c.pman_e_name),
                  NVL (c.pman_e_name, c.pman_a_name)
                 ) pman_nm,
          0 add_flag,
          0 view_flag,
          NULL ad_u_id,
          NULL ad_date,
          NULL up_u_id,
          NULL up_date,
          0 rec_src
   FROM   user_r b,
          Ias_Purchs_Man c
   WHERE  NOT EXISTS (
               SELECT 1
               FROM   Ias_Priv_Pman
               WHERE  pman_code = c.pman_code AND u_id = b.u_id
                      AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_PUR_MAN_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PUR_MAN_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PUR_MAN_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_REP_SMPLE_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_REP_SMPLE_PRV
(U_ID, USR_NAME, REP_SMPLE_NO, REP_SMPLE_NM, FORM_NO, 
 REP_SMPLE_DFLT, PRIV_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Rep_Smple_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.SMPL_L_NM, C.SMPL_F_NM),Nvl (C.SMPL_F_NM, C.SMPL_L_NM)) REP_SMPLE_NM,          
          A.Form_No,
          A.Rep_Smple_Dflt,
          A.Priv_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From Ias_Rep_Smple_User A, User_R B, S_SCR_RPRT_SMPL C
    Where A.U_Id = B.U_Id
      AND A.Rep_Smple_No=C.SMPL_NO
      AND A.FORM_NO=C.FORM_NO
    --  And A.Priv_Flag = 1 
  Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          SMPL_NO Rep_Smple_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.SMPL_L_NM, C.SMPL_F_NM),Nvl (C.SMPL_F_NM, C.SMPL_L_NM)) REP_SMPLE_NM,
          A.Form_No ,
          0 Rep_Smple_Dflt,
          0 Priv_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From Form_Detail A ,User_R B, S_SCR_RPRT_SMPL C
    Where A.FORM_NO = C.FORM_NO
      And Not Exists
               (Select 1
                  From Ias_Rep_Smple_User
                  Where Ias_Rep_Smple_User.Rep_Smple_No = C.SMPL_NO 
                  And Ias_Rep_Smple_User.Form_No = A.Form_No 
                  And Ias_Rep_Smple_User.U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_REP_SMPLE_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_REP_SMPLE_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_REP_SMPLE_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



