--
-- INPT_CID_LST_DTL_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INPT_CID_LST_DTL_VW
(CID_ROWID, CID_CAT, CID_CODE, CID_SUB_CODE, CID_CLMN_NM, 
 CST_BR_CODE, CID_STS, RCRD_SQ, LST_RCRD_SQ, CLMN_VAL, 
 CID_NAME)
BEQUEATH DEFINER
AS 
SELECT CID_rowid,
           CID_CAT,
           CID_CODE,
           CID_SUB_CODE,
           CID_CLMN_NM,
           CST_BR_CODE,
           CID_STS,
           RCRD_SQ,
           lst_RCRD_SQ,
           CLMN_VAL,
           Cid_addr_op_pkg.Get_cid_col_lbl (
               P_cntry_2_ltr   =>
                   NVL (CID_ADDR_OP_PKG.GET_USR_CNTRY_2_LTR_CODE, 'A'),
               P_lang_code    => NVL (CID_ADDR_OP_PKG.GET_USR_LANG_CODE, 'en'),
               P_lang_id      => NVL (CID_ADDR_OP_PKG.GET_USR_LANG_NO, 1),
               P_colmn_name   => CID_CLMN_NM,
               P_type         => 2)
               CID_NAME
      FROM (SELECT ROWID
                       CID_rowid,
                   CID_CAT,
                   CID_CODE,
                   CID_SUB_CODE,
                   CID_CLMN_NM,
                   CST_BR_CODE,
                   CID_STS,
                   RCRD_SQ,
                   CLMN_VAL,
                   MAX (RCRD_SQ)
                   KEEP (DENSE_RANK LAST ORDER BY RCRD_SQ)
                   OVER (
                       PARTITION BY CID_CAT, UPPER (CID_CLMN_NM), CST_BR_CODE)
                       lst_RCRD_SQ
              FROM INPT_CID_LST_DTL
             WHERE     CID_cat =
                       NVL (cid_addr_op_pkg.get_usr_addr_cat, CID_cat)
                   AND cst_br_code =
                       CASE
                           WHEN NVL (
                                    cid_addr_op_pkg.get_usr_addr_cst_br_code,
                                    '0') =
                                '0'
                           THEN
                               cst_br_code
                           ELSE
                               cid_addr_op_pkg.get_usr_addr_cst_br_code
                       END
                   AND CASE
                           WHEN NVL (cid_addr_op_pkg.get_usr_addr_rcrd_sq, 0) =
                                0
                           THEN
                               1
                           ELSE
                               CASE
                                   WHEN rcrd_sq <=
                                        cid_addr_op_pkg.get_usr_addr_rcrd_sq
                                   THEN
                                       1
                                   ELSE
                                       0
                               END
                       END =
                       1)
     WHERE RCRD_SQ = lst_RCRD_SQ;


