--
-- INV_V_DOC_TYPE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_DOC_TYPE
(LANG_NO, DOC_TYPE, DOC_TYPE_NAME, DOC_APPRVD_FLG, TB_MST, 
 TB_DTL, FLD_NO, FLD_SER, FLD_DATE, LOV_NM, 
 FLD_DESC, INV_DOC_TYPE, DOC_INV_FLG, FLD_JV_TYPE, IN_OUT)
BEQUEATH DEFINER
AS 
Select   Lang_no
           ,Doc_type
           ,Doc_type_name
           ,Doc_apprvd_flg
           ,Tb_mst
           ,Tb_dtl
           ,Fld_no
           ,Fld_ser
           ,Fld_date
           ,Lov_nm
           ,Fld_desc
           ,Inv_doc_type
           ,Doc_inv_flg
           ,Fld_jv_type
           ,In_out
   From     (Select Lang_no
                   ,Doc_type
                   ,Doc_type_name
                   ,Doc_apprvd_flg
                   ,'ITEM_MOVEMENT' Tb_mst
                   ,'ITEM_MOVEMENT' Tb_dtl
                   ,'DOC_NO' Fld_no
                   ,'DOC_SER' Fld_ser
                   ,'DOC_DATE' Fld_date
                   ,' ' Lov_nm
                   ,'A_DESC' Fld_desc
                   ,0 Inv_doc_type
                   ,1 Doc_inv_flg
                   ,'BILL_DOC_TYPE' Fld_jv_type
                   ,1 In_out
             From   Ias_sys.Ias_docjv_type_systems_mst
             Where  Doc_type = 0
             Union All
             Select Lang_no
                   ,Doc_type
                   ,Doc_type_name
                   ,Doc_apprvd_flg
                   ,'IAS_BILL_MST' Tb_mst
                   ,'IAS_BILL_DTL' Tb_dtl
                   ,'BILL_NO' Fld_no
                   ,'BILL_SER' Fld_ser
