--
-- INV_V_GRP_DATA  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_GRP_DATA
(G_CODE, MNG_CODE, SUBG_CODE, ASSISTANT_NO, DETAIL_NO, 
 GRP_CODE, GRP_L_NM, GRP_F_NM, GRP_TYP)
BEQUEATH DEFINER
AS 
Select Distinct G_Code, Mng_Code, Subg_Code, Assistant_No, Detail_No,
                   Grp_Code, Grp_L_Nm, Grp_F_Nm, Grp_Typ
   From            (Select G_Code G_Code, Mng_Code Mng_Code,
                           Subg_Code Subg_Code, Assistant_No Assistant_No,
                           Detail_No Detail_No, Grp_Code, G_A_Name Grp_L_Nm,
                           G_E_Name Grp_F_Nm, Grp_Typ
                    From   (Select G_Code, Null Mng_Code, Null Subg_Code,
                                   Null Assistant_No, Null Detail_No,
                                   G_Code Grp_Code, G_A_Name, G_E_Name,
                                   1 Grp_Typ
                            From   Group_Details
                            Union All
                            Select G_Code, Mng_Code, Null Subg_Code,
                                   Null Assistant_No, Null Detail_No,
                                   Mng_Code Grp_Code, Mng_A_Name G_A_Name,
                                   Mng_E_Name G_E_Name, 2 Grp_Typ
                            From   Ias_Mainsub_Grp_Dtl
                            Union All
                            Select G_Code, Mng_Code, Subg_Code,
                                   Null Assistant_No, Null Detail_No,
                                   Subg_Code Grp_Code, Subg_A_Name G_A_Name,
                                   Subg_E_Name G_E_Name, 3 Grp_Typ
                            From   Ias_Sub_Grp_Dtl
                            Union All
                            Select G_Code, Mng_Code, Subg_Code, Assistant_No,
                                   Null Detail_No, Assistant_No Grp_Code,
                                   Assistant_A_Name G_A_Name,
                                   Assistant_E_Name G_E_Name, 4 Grp_Typ
                            From   Ias_Assistant_Group
                            Union All
                            Select G_Code, Mng_Code, Subg_Code, Assistant_No,
                                   Detail_No, Detail_No Grp_Code,
                                   Detail_A_Name G_A_Name,
                                   Detail_E_Name G_E_Name, 5 Grp_Typ
                            From   Ias_Detail_Group))
   Order By        Grp_Typ,
                   G_Code;


--
-- INV_V_OTHR_DOC_TYPE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_OTHR_DOC_TYPE
(LANG_NO, DOC_TYPE, DOC_TYPE_NAME, DOC_APPRVD_FLG, TB_MST, 
 TB_DTL, FLD_NO, FLD_SER, FLD_DATE, LOV_NM, 
 FLD_DESC, INV_DOC_TYPE, DOC_INV_FLG, FLD_JV_TYPE, IN_OUT)
BEQUEATH DEFINER
AS 
SELECT Lang_no,
           Doc_type,
           Doc_type_name(Lang_no,Doc_type) Doc_type_name,
           Doc_apprvd_flg,
           Tb_mst,
           Tb_dtl,
           Fld_no,
           Fld_ser,
           Fld_date,
           Lov_nm,
           Fld_desc,
           Inv_doc_type,
           Doc_inv_flg,
           Fld_jv_type,
           In_out
      FROM (SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   0 Doc_apprvd_flg,
                   NULL            Tb_mst,
                   'INV_ITM_QR_CODE_MOVMNT_OTHR'     Tb_dtl,
                   'DOC_NO'              Fld_no,
                   'DOC_SER'             Fld_ser,
                   'DOC_DATE'            Fld_date,
                   ''                   Lov_nm,
                   Null            Fld_desc,
                   NULL                 Inv_doc_type,
                   0                    Doc_inv_flg,
                   Null            Fld_jv_type,
                   1                    In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 180
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   Doc_apprvd_flg,
                   'SALES_ORDER'      Tb_mst,
                   'ORDER_DETAIL'     Tb_dtl,
                   'ORDER_NO'         Fld_no,
                   'ORDER_SER'        Fld_ser,
                   'ORDER_DATE'       Fld_date,
                   ''                 Lov_nm,
                   'A_DESC'           Fld_desc,
                   NULL               Inv_doc_type,
                   0                  Doc_inv_flg,
                   'SO_TYPE'          Fld_jv_type,
                   -1                 In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 53
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   Doc_apprvd_flg,
                   'IAS_GR_INCOMING_MST'     Tb_mst,
                   'IAS_GR_INCOMING_DTL'     Tb_dtl,
                   'INC_NO'                  Fld_no,
                   'INC_SER'                 Fld_ser,
                   'INC_DATE'                Fld_date,
                   ''                        Lov_nm,
                   'INC_DESC'                Fld_desc,
                   NULL                      Inv_doc_type,
                   0                         Doc_inv_flg,
                   'INCOM_TYPE'              Fld_jv_type,
                   1                         In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 32
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   Doc_apprvd_flg,
                   'IAS_OUT_REQUEST_MST'     Tb_mst,
                   'IAS_OUT_REQUEST_DTL'     Tb_dtl,
                   'OUT_REQ_NO'              Fld_no,
                   'OUT_REQ_SER'             Fld_ser,
                   'OUT_REQ_DATE'            Fld_date,
                   ''                        Lov_nm,
                   'DOC_DESC'                Fld_desc,
                   NULL                      Inv_doc_type,
                   0                         Doc_inv_flg,
                   'OUT_REQ_TYPE'            Fld_jv_type,
                   -1                        In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 31
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   Doc_apprvd_flg,
                   'P_ORDER'            Tb_mst,
                   'P_ORDER_DETAIL'     Tb_dtl,
                   'PO_NO'              Fld_no,
                   'PO_SER'             Fld_ser,
                   'PO_DATE'            Fld_date,
                   ''                   Lov_nm,
                   'PO_DESC'            Fld_desc,
                   NULL                 Inv_doc_type,
                   0                    Doc_inv_flg,
                   'PO_TYPE'            Fld_jv_type,
                   1                    In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 42
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   0 Doc_apprvd_flg,
                   NULL            Tb_mst,
                   'INV_ITM_QR_CODE_MOVMNT_OTHR'     Tb_dtl,
                   'DOC_NO'              Fld_no,
                   'DOC_SER'             Fld_ser,
                   'DOC_DATE'            Fld_date,
                   ''                   Lov_nm,
                   Null            Fld_desc,
                   NULL                 Inv_doc_type,
                   0                    Doc_inv_flg,
                   Null            Fld_jv_type,
                   1                    In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 181
            UNION ALL
            SELECT Lang_no,
                   Doc_type,
                   Doc_type_name(Lang_no,Doc_type) Doc_type_name,
                   0 Doc_apprvd_flg,
                   NULL            Tb_mst,
                   'INV_ITM_QR_CODE_MOVMNT_OTHR'     Tb_dtl,
                   'DOC_NO'              Fld_no,
                   'DOC_SER'             Fld_ser,
                   'DOC_DATE'            Fld_date,
                   ''                   Lov_nm,
                   Null            Fld_desc,
                   NULL                 Inv_doc_type,
                   0                    Doc_inv_flg,
                   Null            Fld_jv_type,
                   -1                    In_out
              FROM Ias_sys.Ias_docjv_type_systems_mst
             WHERE Doc_type = 182
              );

COMMENT ON COLUMN IAS20261.INV_V_OTHR_DOC_TYPE.DOC_TYPE IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';



--
-- INV_V_USR_PRV_ASSMBL_TYP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_USR_PRV_ASSMBL_TYP
(U_ID, USR_NAME, TYP_NO, TYP_NM, ADD_FLG, 
 VIEW_FLG, FILL_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.TYP_NO,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.TYP_L_NM, C.TYP_F_NM),Nvl (C.TYP_F_NM, C.TYP_L_NM)) Typ_Nm,
          A.Add_Flg,
          A.View_Flg,
          A.Fill_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From INV_PRV_ASSMBL_TYP A, User_R B,INV_ASSMBL_TYP C
    Where     A.U_Id = B.U_Id
          And A.TYP_NO = C.TYP_NO
          And (Add_Flg = 1 Or View_Flg = 1 Or Fill_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.TYP_NO,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.TYP_L_NM, C.TYP_F_NM),Nvl (C.TYP_F_NM, C.TYP_L_NM)) Typ_Nm,
          0 Add_Flg,
          0 View_Flg,
          0 Fill_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, INV_ASSMBL_TYP C
    Where Not Exists
             (Select 1
                From INV_PRV_ASSMBL_TYP
               Where TYP_NO = C.TYP_NO And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.INV_V_USR_PRV_ASSMBL_TYP.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.INV_V_USR_PRV_ASSMBL_TYP.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.INV_V_USR_PRV_ASSMBL_TYP.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



