--
-- MRP_V_SGS_SHOPS_FLOOR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.MRP_V_SGS_SHOPS_FLOOR_PRV
(U_ID, USR_NAME, SHF_CODE, SHF_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
       DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
               1, NVL (b.u_a_name, b.u_e_name),
               NVL (b.u_e_name, b.u_a_name)
              ) usr_name,
       c.SHF_CODE,
       DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
               1, NVL (c.SHF_NAME_A, c.SHF_NAME_F),
               NVL (c.SHF_NAME_F, c.SHF_NAME_A)
              ) SHF_NM,
       a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
       1 rec_src
FROM   PRIVILEGE_MRP_SHF a,
       user_r b,
       MRP_SGS_SHOPS_FLOOR_CODING c
WHERE  a.u_id = b.u_id AND a.SHF_CODE = c.SHF_CODE
UNION
SELECT b.u_id,
       DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
               1, NVL (b.u_a_name, b.u_e_name),
               NVL (b.u_e_name, b.u_a_name)
              ) usr_name,
       c.SHF_CODE,
       DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
               1, NVL (c.SHF_NAME_A, c.SHF_NAME_F),
               NVL (c.SHF_NAME_F, c.SHF_NAME_A)
              ) SHF_NM,
       0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
       NULL up_date, 0 rec_src
FROM   user_r b,
       MRP_SGS_SHOPS_FLOOR_CODING c
WHERE  NOT EXISTS (
                SELECT 1
                FROM   PRIVILEGE_MRP_SHF
                WHERE  SHF_CODE = c.SHF_CODE AND u_id = b.u_id
                       AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.MRP_V_SGS_SHOPS_FLOOR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.MRP_V_SGS_SHOPS_FLOOR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.MRP_V_SGS_SHOPS_FLOOR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- MRP_V_SGS_WOP_CTGRY_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.MRP_V_SGS_WOP_CTGRY_PRV
(U_ID, USR_NAME, WOP_CTGRY_NO, WOP_CTGRY_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
																												          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																												                  1, NVL (b.u_a_name, b.u_e_name),
																												                  NVL (b.u_e_name, b.u_a_name)
																												                 ) usr_name,
																												          c.WOP_CTGRY_NO,
																												          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																												                  1, NVL (c.WOP_CTGRY_ADES, c.WOP_CTGRY_EDES),
																												                  NVL (c.WOP_CTGRY_EDES, c.WOP_CTGRY_ADES)
																												                 ) WOP_CTGRY_NM,
																												          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
																												          1 rec_src
																												   FROM   PRIVILEGE_MRP_CTGRY a,
																												          user_r b,
																												          MRP_SGS_WOP_CTGRY c
																												   WHERE  a.u_id = b.u_id AND a.WOP_CTGRY_NO = c.WOP_CTGRY_NO
																												   UNION
																												   SELECT b.u_id,
																												          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																												                  1, NVL (b.u_a_name, b.u_e_name),
																												                  NVL (b.u_e_name, b.u_a_name)
																												                 ) usr_name,
																												          c.WOP_CTGRY_NO,
																												          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
																												                  1, NVL (c.WOP_CTGRY_ADES, c.WOP_CTGRY_EDES),
																												                  NVL (c.WOP_CTGRY_EDES, c.WOP_CTGRY_ADES)
																												                 ) WOP_CTGRY_NM,
																												          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
																												          NULL up_date, 0 rec_src
																												   FROM   user_r b,
																												          MRP_SGS_WOP_CTGRY c
																												   WHERE  NOT EXISTS (
																												                   SELECT 1
																												                   FROM   PRIVILEGE_MRP_CTGRY
																												                   WHERE  WOP_CTGRY_NO = c.WOP_CTGRY_NO AND u_id = b.u_id
																												                          AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.MRP_V_SGS_WOP_CTGRY_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.MRP_V_SGS_WOP_CTGRY_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.MRP_V_SGS_WOP_CTGRY_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- MWS_V_USR_GNR_INPT_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.MWS_V_USR_GNR_INPT_PRV
(U_ID, USR_NAME, INPT_TYP, INPT_TYP_NM, INPT_NO, 
 INPT_NM, ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Inpt_Typ,
          N.Form_Name Inpt_Typ_Nm,
          A.Inpt_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Typ_L_Nm, C.Typ_F_Nm),Nvl (C.Typ_F_Nm, C.Typ_L_Nm)) Typ_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          1 Rec_Src
     From Mws_Gnr_Inpt_Prv A, User_R B, Mws_V_Gnr_Inpt_Prv C, Ias_Form_Name N
    Where A.Inpt_No = C.Typ_No
          And A.Inpt_Typ = C.Inpt_Typ
          And C.Form_No = N.Form_No
          And N.Lang_no = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
          And A.U_Id = B.U_Id
          And (Add_Flag = 1 Or View_Flag = 1 )
  Union
 Select B.U_Id,
        Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
        A.Inpt_Typ,
        N.Form_Name Inpt_Typ_Nm,
        A.Typ_No,
        Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (A.Typ_L_Nm, A.Typ_F_Nm),Nvl (A.Typ_F_Nm, A.Typ_L_Nm)) Typ_Nm,
        0 Add_Flag,
        0 View_Flag,
        Null Ad_U_Id,
        Null Ad_Date,
        Null Up_U_Id,
        Null Up_Date,
        0 Rec_Src
   From Mws_V_Gnr_Inpt_Prv A, User_R B, Ias_Form_Name N
  Where A.Form_No = N.Form_No 
    And N.Lang_no = Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO')
    And Not Exists
             (Select 1
                From Mws_Gnr_Inpt_Prv D
               Where D.Inpt_Typ = A.Inpt_Typ  And D.Inpt_No = A.Typ_No And  D.U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.MWS_V_USR_GNR_INPT_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.MWS_V_USR_GNR_INPT_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.MWS_V_USR_GNR_INPT_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- S_EMP_V_HLDY_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_EMP_V_HLDY_BLNC
(EMP_NO, HLDY_NO, HLDY_NM, HLDY_TYP, HLDY_TYP_NM, 
 HLDY_BLNC, OPN_HLDY_BLNC, HLDY_BLNC_RNWL, HLDY_LAW_BLNC, LST_HLDY_DATE)
BEQUEATH DEFINER
AS 
SELECT s.emp_no, s.hldy_no,
				          hrs_gnr_pkg.get_hldy_nm
				                      (p_hldy_no      => s.hldy_no,
				                       p_lng_no       => ias_prmtr_pkg.getpval(p_prmtr      => 'LANG_NO')
				                      ),
				          h.hldy_typ,
				          ias_gen_pkg.get_flg_nm
				                      (p_flg_code       => 'HLDY_TYP',
				                       p_flg_value      => h.hldy_typ,
				                       p_lng_no         => ias_prmtr_pkg.getpval(p_prmtr      => 'LANG_NO')
				                      ),
				          s.hldy_blnc, s.OPN_HLDY_BLNC,s.HLDY_BLNC_RNWL,s.hldy_law_blnc, s.lst_hldy_date
				     FROM s_emp_hldy_blnc s, hrs_hldy_code h
				    WHERE h.hldy_no = s.hldy_no
				    Order by s.emp_no,s.hldy_no;

COMMENT ON COLUMN IAS20261.S_EMP_V_HLDY_BLNC.EMP_NO IS '1928 - —ﬁ„ «·„ÊŸ›';



