 FETCH_TO_COLTION, INDCTR_GRPS, FLD_DATE_FRMT, GRID_COLS, GRID_OPTION, 
 SHOW_LEGEND, LEGEND_POSITION, SHOW_LABELS, F_DATE, T_DATE, 
 SYS_TYP_FLG, LINE_FLAG_TYPE, LINE_FLAG_LOCATION, LINE_FLAG_IN_LEGEND, LINE_FLAG1_VALUE, 
 LINE_FLAG2_VALUE, LINE_FLAG3_VALUE, LINE_FLAG1_LBL_NO, LINE_FLAG2_LBL_NO, LINE_FLAG3_LBL_NO, 
 LINE_FLAG1_L_TITLE, LINE_FLAG2_L_TITLE, LINE_FLAG3_L_TITLE, LINE_FLAG1_F_TITLE, LINE_FLAG2_F_TITLE, 
 LINE_FLAG3_F_TITLE, LINE_FLAG1_DSC, LINE_FLAG2_DSC, LINE_FLAG3_DSC, LINE_FLAG1_STYLE, 
 LINE_FLAG2_STYLE, LINE_FLAG3_STYLE, LINE_FLAG1_COLOR, LINE_FLAG2_COLOR, LINE_FLAG3_COLOR, 
 LINE_FLAG1_WIDTH, LINE_FLAG2_WIDTH, LINE_FLAG3_WIDTH)
BEQUEATH DEFINER
AS 
SELECT S.DSH_NO,
           NVL(VW.VIEW_NO, 0) VIEW_NO,
           S.SYS_NO,
           NVL(VW.VIEW_LBL_NO, S.LBL_NO) LBL_NO,
           NVL(VW.VIEW_ORDR_NO, S.ORDR_NO) ORDR_NO,
           NVL(VW.VIEW_L_TITLE, S.DSH_L_TITLE) DSH_L_TITLE,
           NVL(VW.VIEW_F_TITLE, S.DSH_F_TITLE) DSH_F_TITLE,
           S.FLD_CNT,
           S.DSH_SLCT,
           S.DSH_WHR,
           VW.VIEW_WHR,
           S.DSH_PRV,
           S.DSH_GRP_BY,
           S.DSH_ORDR,
           NVL(VW.LBL_NO_FLD, S.LBL_NO_FLD) LBL_NO_FLD,
           S.shw_dsh_flg,
           S.INACTIVE,
           NVL(VW.VIEW_DSH_PARNT, S.DSH_PARNT) DSH_PARNT,
           S.LBL_NO_DSC,
           S.FLD_NMBR,
           NVL(VW.VIEW_INDCTR_COLS, S.INDCTR_COLS) INDCTR_COLS,
           NVL(VW.VIEW_INDCTR_COLS_DTL_MAPPING, S.INDCTR_COLS_DTL_MAPPING) INDCTR_COLS_DTL_MAPPING,
           NVL(VW.VIEW_INDCTR_VALS, S.INDCTR_VALS) INDCTR_VALS,
           NVL(VW.VIEW_Z_INDCTR_VALS, S.Z_INDCTR_VALS) Z_INDCTR_VALS,
           COALESCE(VW.VIEW_INDCTR_COLS_WHR_MAPPING,S.INDCTR_COLS_WHR_MAPPING,VW.VIEW_INDCTR_COLS, S.INDCTR_COLS) INDCTR_COLS_WHR_MAPPING,
           COALESCE(VW.VIEW_INDCTR_GRPS_WHR_MAPPING,S.INDCTR_GRPS_WHR_MAPPING,VW.VIEW_INDCTR_GRPS, S.INDCTR_GRPS) INDCTR_GRPS_WHR_MAPPING,
           NVL(VW.VIEW_INDCTR_COLS_GRPS_MAPPING,S.INDCTR_COLS_GRPS_MAPPING) INDCTR_COLS_GRPS_MAPPING,
           NVL(VW.VIEW_INDCTR_GRPS_DTL_MAPPING,S.INDCTR_GRPS_DTL_MAPPING) INDCTR_GRPS_DTL_MAPPING,
           CASE NVL(S.CHILD_DSH_NO,0) WHEN 0 THEN NULL ELSE S.DSH_NO END CHILD_DSH_NO, 
           VW.CHILD_VIEW_NO,
           S.FLD_DATE,
           NVL(VW.VIEW_CHRT_OPTIONS, S.CHRT_OPTIONS) CHRT_OPTIONS,
           S.DESC_MSG_NO,
           NVL(VIEW_L_DSC, DSH_L_DSC) DSH_L_DSC, 
           NVL(VIEW_F_DSC, DSH_F_DSC) DSH_F_DSC,
           NVL(VW.VIEW_PG_ID, S.PG_ID) PG_ID,
           NVL(VW.VIEW_ICON_IMG, S.ICON_IMG) ICON_IMG,
           NVL(VW.VIEW_ROWS_CNT, S.ROWS_CNT) ROWS_CNT,
           NVL(VW.VIEW_FLTR_COLS,S.FLTR_COLS) FLTR_COLS,
           NVL(VW.VIEW_AUTO_REF_SCNDS,S.AUTO_REF_SCNDS) AUTO_REF_SCNDS,
           nvl(S.FETCH_TO_COLTION,0) FETCH_TO_COLTION,
           NVL(VW.VIEW_INDCTR_GRPS,S.INDCTR_GRPS) INDCTR_GRPS,
           S.FLD_DATE_FRMT,
           NVL(VW.VIEW_GRID_COLS, S.GRID_COLS) GRID_COLS, 
           nvl(vW.view_Grid_Option,s.Grid_Option)Grid_Option
          ,NVL(VW.VIEW_SHOW_LEGEND,S.SHOW_LEGEND) SHOW_LEGEND
          ,NVL(VW.VIEW_LEGEND_POSITION,S.LEGEND_POSITION) LEGEND_POSITION
          ,NVL(VW.VIEW_SHOW_LABELS,SHOW_LABELS) SHOW_LABELS
          ,coalesce(VW.VIEW_F_DATE,F_DATE,TO_DATE(IAS_GEN_PKG.Get_Fld_Value(' Dual ',NVL(VW.VIEW_F_DATE_Fnc,F_DATE_Fnc)))) F_DATE
          ,coalesce(VW.VIEW_T_DATE,T_DATE,TO_DATE(IAS_GEN_PKG.Get_Fld_Value(' Dual ',NVL(VW.VIEW_T_DATE_Fnc,T_DATE_Fnc)))) T_DATE
          ,S.SYS_TYP_FLG
          ,NVL( VW.VIEW_LINE_FLAG_TYPE   , S.LINE_FLAG_TYPE    )             LINE_FLAG_TYPE
          ,NVL( VW.VIEW_LINE_FLAG_LOCATION   , S.LINE_FLAG_LOCATION    )     LINE_FLAG_LOCATION
          ,NVL( VW.VIEW_LINE_FLAG_IN_LEGEND   , S.LINE_FLAG_IN_LEGEND    )   LINE_FLAG_in_Legend
          ,NVL( VW.VIEW_LINE_FLAG1_VALUE , S.LINE_FLAG1_VALUE    )           LINE_FLAG1_VALUE
          ,NVL( VW.VIEW_LINE_FLAG2_VALUE , S.LINE_FLAG2_VALUE    )           LINE_FLAG2_VALUE
          ,NVL( VW.VIEW_LINE_FLAG3_VALUE , S.LINE_FLAG3_VALUE    )           LINE_FLAG3_VALUE
          ,NVL( VW.VIEW_LINE_FLAG1_LBL_NO , S.LINE_FLAG1_LBL_NO   )          LINE_FLAG1_LBL_NO
          ,NVL( VW.VIEW_LINE_FLAG2_LBL_NO , S.LINE_FLAG2_LBL_NO   )          LINE_FLAG2_LBL_NO
          ,NVL( VW.VIEW_LINE_FLAG3_LBL_NO , S.LINE_FLAG3_LBL_NO   )          LINE_FLAG3_LBL_NO
          ,NVL( VW.VIEW_LINE_FLAG1_L_TITLE , S.LINE_FLAG1_L_TITLE  )         LINE_FLAG1_L_TITLE
          ,NVL( VW.VIEW_LINE_FLAG2_L_TITLE , S.LINE_FLAG2_L_TITLE  )         LINE_FLAG2_L_TITLE
          ,NVL( VW.VIEW_LINE_FLAG3_L_TITLE , S.LINE_FLAG3_L_TITLE  )         LINE_FLAG3_L_TITLE
          ,NVL( VW.VIEW_LINE_FLAG1_F_TITLE , S.LINE_FLAG1_F_TITLE  )         LINE_FLAG1_F_TITLE
          ,NVL( VW.VIEW_LINE_FLAG2_F_TITLE , S.LINE_FLAG2_F_TITLE  )         LINE_FLAG2_F_TITLE
          ,NVL( VW.VIEW_LINE_FLAG3_F_TITLE , S.LINE_FLAG3_F_TITLE  )         LINE_FLAG3_F_TITLE
          ,NVL( VW.VIEW_LINE_FLAG1_DSC    , S.LINE_FLAG1_DSC)                LINE_FLAG1_DSC
          ,NVL( VW.VIEW_LINE_FLAG2_DSC    , S.LINE_FLAG2_DSC)                LINE_FLAG2_DSC
          ,NVL( VW.VIEW_LINE_FLAG3_DSC    , S.LINE_FLAG3_DSC)                LINE_FLAG3_DSC
          ,NVL( VW.VIEW_LINE_FLAG_STYLE , S.LINE_FLAG_STYLE    )             LINE_FLAG1_STYLE
          ,NVL( VW.VIEW_LINE_FLAG_STYLE , S.LINE_FLAG_STYLE    )             LINE_FLAG2_STYLE
          ,NVL( VW.VIEW_LINE_FLAG_STYLE , S.LINE_FLAG_STYLE    )             LINE_FLAG3_STYLE
          ,NVL( VW.VIEW_LINE_FLAG1_COLOR , S.LINE_FLAG1_COLOR    )           LINE_FLAG1_COLOR
          ,NVL( VW.VIEW_LINE_FLAG2_COLOR , S.LINE_FLAG2_COLOR    )           LINE_FLAG2_COLOR
          ,NVL( VW.VIEW_LINE_FLAG3_COLOR , S.LINE_FLAG3_COLOR    )           LINE_FLAG3_COLOR
          ,NVL( VW.VIEW_LINE_FLAG1_WIDTH , S.LINE_FLAG1_WIDTH    )           LINE_FLAG1_WIDTH
          ,NVL( VW.VIEW_LINE_FLAG2_WIDTH , S.LINE_FLAG2_WIDTH    )           LINE_FLAG2_WIDTH
          ,NVL( VW.VIEW_LINE_FLAG3_WIDTH , S.LINE_FLAG3_WIDTH    )           LINE_FLAG3_WIDTH
      FROM S_DSH_BORD S, S_DSH_BORD_VIEW VW
      WHERE S.DSH_NO = VW.DSH_NO
      UNION
    SELECT S.DSH_NO,
           0 VIEW_NO,
           S.SYS_NO,
           S.LBL_NO,
           S.ORDR_NO,
           DSH_L_TITLE,
           DSH_F_TITLE,
           S.FLD_CNT,
           S.DSH_SLCT,
           S.DSH_WHR,
           NULL VIEW_WHR,
           S.DSH_PRV,
           S.DSH_GRP_BY,
           S.DSH_ORDR,
           S.LBL_NO_FLD,
           S.shw_dsh_flg,
           S.INACTIVE,
           S.DSH_PARNT,
           S.LBL_NO_DSC,
           S.FLD_NMBR,
           S.INDCTR_COLS,
           S.INDCTR_COLS_DTL_MAPPING,
           S.INDCTR_VALS,
           S.Z_INDCTR_VALS,
           NVL(S.INDCTR_COLS_WHR_MAPPING,S.INDCTR_COLS),
           NVL(S.INDCTR_GRPS_WHR_MAPPING,S.INDCTR_GRPS),
           S.INDCTR_COLS_GRPS_MAPPING,
           S.INDCTR_GRPS_DTL_MAPPING,
           CASE NVL(S.CHILD_DSH_NO,0) WHEN 0 THEN NULL ELSE S.DSH_NO END CHILD_DSH_NO,
           0 CHILD_VIEW_NO,
           S.FLD_DATE,
           S.CHRT_OPTIONS,
           S.DESC_MSG_NO,
           DSH_L_DSC,
           DSH_F_DSC,
           S.PG_ID,
           S.ICON_IMG,
           S.ROWS_CNT, 
           S.FLTR_COLS,
           S.AUTO_REF_SCNDS,
           nvl(S.FETCH_TO_COLTION,0),
           S.INDCTR_GRPS,
           S.FLD_DATE_FRMT,
           S.GRID_COLS, 
           S.Grid_Option
          ,S.SHOW_LEGEND
          ,S.LEGEND_POSITION
          ,S.SHOW_LABELS
          ,NVL(F_DATE,TO_DATE(IAS_GEN_PKG.Get_Fld_Value(' Dual ',F_DATE_Fnc))) F_DATE
          ,NVL(T_DATE,TO_DATE(IAS_GEN_PKG.Get_Fld_Value(' Dual ',T_DATE_Fnc))) T_DATE
          ,S.SYS_TYP_FLG
          ,S.LINE_FLAG_TYPE    
          ,S.LINE_FLAG_LOCATION    
          ,S.LINE_FLAG_IN_LEGEND    
          ,S.LINE_FLAG1_VALUE
          ,S.LINE_FLAG2_VALUE
          ,S.LINE_FLAG3_VALUE
          ,S.LINE_FLAG1_LBL_NO
          ,S.LINE_FLAG2_LBL_NO
          ,S.LINE_FLAG3_LBL_NO
          ,S.LINE_FLAG1_L_TITLE
          ,S.LINE_FLAG2_L_TITLE
          ,S.LINE_FLAG3_L_TITLE
          ,S.LINE_FLAG1_F_TITLE
          ,S.LINE_FLAG2_F_TITLE
          ,S.LINE_FLAG3_F_TITLE
          , S.LINE_FLAG1_DSC
          , S.LINE_FLAG2_DSC
          , S.LINE_FLAG3_DSC
          ,S.LINE_FLAG_STYLE
          ,S.LINE_FLAG_STYLE
          ,S.LINE_FLAG_STYLE
          ,S.LINE_FLAG1_COLOR
          ,S.LINE_FLAG2_COLOR
          ,S.LINE_FLAG3_COLOR
          ,S.LINE_FLAG1_WIDTH
          ,S.LINE_FLAG2_WIDTH
          ,S.LINE_FLAG3_WIDTH
      FROM S_DSH_BORD S;

ALTER VIEW IAS20261.S_V_DSH_BORD
 ADD CONSTRAINT S_V_DSH_BORD_PK
  PRIMARY KEY
  (DSH_NO, VIEW_NO)
  DISABLE NOVALIDATE;


--
-- S_V_EMP_ESS_SCR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_EMP_ESS_SCR_PRV
(U_ID, USR_NM, SCR_NO, PRV_FLG, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.emp_no,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.emp_l_nm, b.emp_f_nm),
                  NVL (b.emp_f_nm, b.emp_l_nm)
                 ) emp_nm,
          a.scr_no, a.inc_flg, a.ad_u_id, a.ad_date, NULL up_u_id,
          NULL up_date, 1 rec_src
   FROM   hrs_scr_ess_prv a,
          s_emp b,
          hrs_scr_ess c
   WHERE  a.emp_no = b.emp_no
   AND    a.scr_no = c.scr_no
   AND    a.inc_flg = 1
   AND    NVL (c.inactive, 0) = 0
   UNION
   SELECT b.emp_no,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.emp_l_nm, b.emp_f_nm),
                  NVL (b.emp_f_nm, b.emp_l_nm)
                 ) usr_nm,
          c.scr_no, 0 prv_flg, NULL ad_u_id, NULL ad_date, NULL up_u_id,
          NULL up_date, 0 rec_src
   FROM   s_emp b,
          hrs_scr_ess c
   WHERE  NVL (c.inactive, 0) = 0
   AND    NOT EXISTS (
                 SELECT 1
                 FROM   hrs_scr_ess_prv
                 WHERE  emp_no = b.emp_no AND scr_no = c.scr_no
                        AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.S_V_EMP_ESS_SCR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_EMP_ESS_SCR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_EMP_ESS_SCR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



