--
-- S_V_USR_DSH_BORD_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_USR_DSH_BORD_PRV
(U_ID, USR_NAME, DSH_NO, DSH_NM, PRV_FLG, 
 AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
							          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
							          A.DSH_NO,
							          Ias_Gen_Pkg.Get_Prompt(IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'), Lbl_No)DSH_NM,                        
							          A.PRV_FLG,
							          A.Ad_U_Id,
							          A.Ad_Date,
							          A.Up_U_Id,
							          A.Up_Date,
							          1 Rec_Src
							     From S_USR_DSH_BORD_PRV A, User_R B, S_DSH_BORD C
							    Where A.U_Id = B.U_Id
							      AND A.DSH_NO=C.DSH_NO
							  Union
							   Select B.U_Id,
							          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
							          DSH_NO,
							          Ias_Gen_Pkg.Get_Prompt(IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'), Lbl_No)DSH_NM,          
							          0 PRV_FLG,
							          Null Ad_U_Id,
							          Null Ad_Date,
							          Null Up_U_Id,
							          Null Up_Date,
							          0 Rec_Src
							     From User_R B, S_DSH_BORD C
							    Where Not Exists
							               (Select 1
							                  From S_USR_DSH_BORD_PRV
							                  Where S_USR_DSH_BORD_PRV.DSH_NO = C.DSH_NO 
							                  And S_USR_DSH_BORD_PRV.U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.S_V_USR_DSH_BORD_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_USR_DSH_BORD_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_USR_DSH_BORD_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- TRL_V_USR_TYP_CODE_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.TRL_V_USR_TYP_CODE_PRV
(U_ID, USR_NAME, CODE_TYP, CODE_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
                                  Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
                                  C.CODE_TYP,
                                  C.CODE_NO,
                                  Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.CODE_L_NM, C.CODE_F_NM),Nvl (C.CODE_F_NM, C.CODE_L_NM)) Type_NM,
                                  A.Add_Flag,
                                  A.View_Flag,
                                  A.Ad_U_Id,
                                  A.Ad_Date,
                                  1 Rec_Src
                             From TRL_TYP_CODE_DTL_PRV A, User_R B, TRL_TYP_CODE_DTL C
                            Where   A.CODE_TYP = C.CODE_TYP
                                  And A.CODE_NO = C.CODE_NO
                                  And A.U_Id = B.U_Id
                                  And (Add_Flag = 1 Or View_Flag = 1)
                          Union
                         Select B.U_Id,
                                  Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
                                  A.CODE_TYP,
                                  A.CODE_NO,
                                  Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (A.CODE_L_NM, A.CODE_F_NM),Nvl (A.CODE_F_NM, A.CODE_L_NM)) Type_NM,
                                  0 Add_Flag,
                                  0 View_Flag,
                                  Null Ad_U_Id,
                                  Null Ad_Date,
                                  0 Rec_Src
                             From TRL_TYP_CODE_DTL  A,User_R B
                            Where Not Exists
                                     (Select 1
                                        From TRL_TYP_CODE_DTL_PRV
                                       Where CODE_TYP = A.CODE_TYP And CODE_NO = A.CODE_NO And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.TRL_V_USR_TYP_CODE_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';



--
-- VNDR_DGR_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.VNDR_DGR_AI_VW
(DGR_NO, DGR_L_NM, DGR_F_NM, NOTES, ORDR_NO, 
 INACTV_FLG, INACTV_DATE, INACTV_USR, INACTV_RSON, CRT_USR, 
 CRT_DATE, UPD_USR, UPD_DATE, UPD_CNT, CRT_TRMNL_NM, 
 UPD_TRMNL_NM, AC_CODE, PYMNT_TYP)
BEQUEATH DEFINER
AS 
SELECT 
          V_DEGREE DGR_NO,
          V_DEGREE_A_NAME DGR_L_NM,
          V_DEGREE_E_NAME DGR_F_NM,
          NULL NOTES,
          NULL ORDR_NO,
          0 INACTV_FLG,
          NULL INACTV_DATE,
          NULL INACTV_USR,
          NULL INACTV_RSON,
          AD_U_ID CRT_USR,
          AD_DATE CRT_DATE,
          UP_U_ID UPD_USR,
          UP_DATE UPD_DATE,
          UP_CNT UPD_CNT,
          AD_TRMNL_NM CRT_TRMNL_NM,
