--
-- YS_V_OBJ  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.YS_V_OBJ
(SYS_NO, OBJ_TYP, OBJ_NM, OBJ_CODE, OBJ_VRSN)
BEQUEATH DEFINER
AS 
SELECT DISTINCT F.SYS_NO, ITM_TYP OBJ_TYP, OBJ_NM, ITM_NM OBJ_CODE, OBJ_VRSN
					    FROM IAS_SYS.YS_OBJCT O, FORM_DETAIL F
					    WHERE F.FORM_NO=O.FORM_NO AND OBJ_NM IS NOT NULL
					    UNION 
					    SELECT DISTINCT F.SYS_NO, 'FORM' ITM_TYP, N.FORM_NAME OBJ_NM,  TO_CHAR(NVL(F.SCR_ORGNL,F.FORM_NO)) OBJ_CODE, YS_HNT_PKG.GET_FORM_VRSN(F.FORM_NO) OBJ_VRSN
					    FROM 
					    FORM_DETAIL F, IAS_FORM_NAME N WHERE F.FORM_NO=N.FORM_NO AND N.LANG_NO=NVL(IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'),1);


--
-- YS_V_OBJ_HNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.YS_V_OBJ_HNT
(HNT_SQ, OBJ_CODE, FORM_NO, HNT_OBJ_VRSN, HNT_OBJ_SQ, 
 RCRD_NO, HNT_SRC, HNT_TOPC, HNT_DATE, DUMMY_COL, 
 READ_FLG, HIDE_FLG, READ_DATE, U_ID, HNT_LVL)
BEQUEATH DEFINER
AS 
SELECT H.HNT_SQ, H.OBJ_CODE, H.FORM_NO, H.HNT_OBJ_VRSN, H.HNT_OBJ_SQ, H.RCRD_NO,H.HNT_SRC, H.HNT_TOPC,HNT_DATE,H.DUMMY_COL , U.READ_FLG, U.HIDE_FLG , U.READ_DATE,U.U_ID,H.HNT_LVL
					FROM 
					    YS_OBJ_HNT H,
					    YS_OBJ_HNT_USR U
					WHERE
					    H.HNT_SQ=U.HNT_SQ;


--
-- YS_V_OBJ_TREE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.YS_V_OBJ_TREE
(SYS_NO, OBJ_TYP, OBJ_CODE, OBJ_NM, OBJ_PARNT, 
 OBJ_VRSN, F_FILE_NAME)
BEQUEATH DEFINER
AS 
SELECT F.SYS_NO, ITM_TYP OBJ_TYP, OBJ_CODE,OBJ_NM, TO_CHAR(O.FORM_NO) OBJ_PARNT, O.OBJ_VRSN, null F_FILE_NAME FROM YS_OBJCT O, FORM_DETAIL F
								WHERE F.FORM_NO=O.FORM_NO AND OBJ_CODE IS NOT NULL AND O.FORM_NO IS NOT NULL
								UNION 
								SELECT F.SYS_NO, 'FORM' ITM_TYP, TO_CHAR(NVL(F.SCR_ORGNL,F.FORM_NO)) OBJ_CODE, N.FORM_NAME,
								TO_CHAR (YS_HNT_PKG.GET_FORM_SCR_PARNT(NVL(SCR_ORGNL, F.FORM_NO))) OBJ_PARNT,
								YS_HNT_PKG.GET_FORM_VRSN(TO_CHAR(NVL(SCR_ORGNL,F.FORM_NO))),
								F.F_FILE_NAME
								FROM FORM_DETAIL F, IAS_FORM_NAME N 
								WHERE NVL(SCR_ORGNL,F.FORM_NO)=N.FORM_NO AND NVL(F_INACTIVE,0)=0 AND N.LANG_NO=NVL(IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'),1)
								UNION
 								SELECT 0 COL1 ,'FORM' COL2,'0' COL3, NULL COL4, NULL COL5, NULL COL6, NULL COL7 FROM DUAL;


--
-- ADD_SRVC_URL_TO_ACL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.ADD_SRVC_URL_TO_ACL_TRG
AFTER INSERT OR UPDATE OR DELETE
ON IAS20261.GNR_WEB_SRVC_MST
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
tmpVar VARCHAR2(10);
V_HOST   VARCHAR2(1000);
V_PORT  NUMBER;
V_OLD_HOST  VARCHAR2(1000);
V_OLD_PORT  NUMBER;
V_IS_HTTPS  BOOLEAN := FALSE;

BEGIN
   IF :NEW.SRVC_URL IS NOT NULL OR :OLD.SRVC_URL IS NOT NULL THEN 
      V_HOST := REGEXP_REPLACE(:NEW.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\3');
      tmpVar := REGEXP_REPLACE(:NEW.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\4');
      V_IS_HTTPS := LENGTH(REGEXP_REPLACE(:NEW.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\1'))=8;
      
      IF LENGTH(tmpVar)>1 THEN
        V_PORT := TO_NUMBER(SUBSTR(tmpVar,2));
      ELSIF V_IS_HTTPS THEN 
        V_PORT := 443;
      ELSE
        V_PORT := 80;
      END IF;
      
      IF INSERTING THEN
        DBMS_NETWORK_ACL_ADMIN.assign_acl (
                                                 acl         => 'ONYX_ACL.xml',
                                                 host        => v_host, 
                                                 lower_port  => v_port,
                                                 upper_port  => NULL);
      ELSIF UPDATING THEN 
        BEGIN
            V_OLD_HOST := REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\3');
            tmpVar := REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\4');
            V_IS_HTTPS := LENGTH(REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\1'))=8;
            
            IF LENGTH(tmpVar)>1 THEN
                V_OLD_PORT := TO_NUMBER(SUBSTR(tmpVar,2));
            ELSIF V_IS_HTTPS THEN 
                V_OLD_PORT := 443;
            ELSE
                V_OLD_PORT := 80;
            END IF;
            IF NVL(V_HOST,'') <> NVL(V_OLD_HOST,'') OR NVL(V_PORT,0) <> NVL(V_OLD_PORT,0) THEN
                DBMS_NETWORK_ACL_ADMIN.unassign_acl (
                                                 acl         => 'ONYX_ACL.xml',
                                                 host        => v_old_host, 
                                                 lower_port  => v_old_port,
                                                 upper_port  => NULL);
                                                 --RAISE_APPLICATION_ERROR(-20001,'HOST:'||:NEW.SRVC_URL||' -- PORT:'||V_PORT);
                DBMS_NETWORK_ACL_ADMIN.assign_acl (
                                                 acl         => 'ONYX_ACL.xml',
                                                 host        => v_host, 
                                                 lower_port  => v_port,
                                                 upper_port  => NULL);
            END IF;
        END;
      ELSE
         BEGIN
            --RAISE_APPLICATION_ERROR(-20001,'3');
            V_OLD_HOST := REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\3');
            tmpVar := REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\4');
            V_IS_HTTPS := LENGTH(REGEXP_REPLACE(:OLD.SRVC_URL, '(http[s]?://)?(www\.)?(.*?)(/|:[0-9]{1,5})((.)*|$)', '\1'))=8;
            
            IF LENGTH(tmpVar)>1 THEN
                V_OLD_PORT := TO_NUMBER(SUBSTR(tmpVar,2));
            ELSIF V_IS_HTTPS THEN 
                V_OLD_PORT := 443;
            ELSE
                V_OLD_PORT := 80;
            END IF;
            
            DBMS_NETWORK_ACL_ADMIN.unassign_acl (
                                                 acl         => 'ONYX_ACL.xml',
                                                 host        => v_old_host, 
                                                 lower_port  => v_old_port,
                                                 upper_port  => NULL);
         END;
      END IF;
   END IF;
   EXCEPTION
     WHEN OTHERS THEN
       NULL;
END ADD_SRVC_URL_TO_ACL_TRG;
/


