--
-- AUD_REQUEST_TYPES_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_REQUEST_TYPES_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.REQUEST_TYPES
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
														                 END IF;
                                                                                   
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'REQUEST_TYPES','AD_DATE',:NEW.AD_DATE,:OLD.AD_DATE,Nvl(:NEW.REQ_TYPE,:OLD.REQ_TYPE),NULL,NULL,NULL,NULL,NULL,NULL,NULL); 
