        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_LIB_FILE','ACCESSED_DATE',:NEW.ACCESSED_DATE,:OLD.ACCESSED_DATE,Nvl(:NEW.FILE_NAME,:OLD.FILE_NAME),NULL,NULL,NULL,NULL,NULL,NULL,NULL); 
