--
-- AUTID_VIEW_COLS  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUTID_VIEW_COLS
BEFORE INSERT OR UPDATE
ON IAS20261.S_DSH_BORD_VIEW
FOR EACH ROW
DISABLE
BEGIN
IF  :NEW.VIEW_INDCTR_COLS IS NOT NULL AND :NEW.VIEW_INDCTR_COLS_DTL_MAPPING IS NULL 
OR (:NEW.VIEW_INDCTR_COLS IS NULL     AND :NEW.VIEW_INDCTR_COLS_DTL_MAPPING IS NOT NULL)
THEN
        Raise_application_error(-20600,'INCONSISTANT INPUT FOR VIEW VIEW_INDCTR_COLS AND  VIEW_INDCTR_COLS_DTL_MAPPING NUST MATCH') ;
        END IF;
END AUTID_VIEW_COLS
/


--
-- CRT_IR_PG_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.CRT_IR_PG_TRG
											BEFORE INSERT OR UPDATE
											ON IAS20261.APEX_IR_SLCT 
											REFERENCING NEW AS New OLD AS Old
											FOR EACH ROW
DECLARE
											    V_MAX NUMBER;
											    V_APP NUMBER;
											BEGIN 
											    IF :NEW.PG_ID IS NULL THEN
											        IF INSERTING THEN 
											            SELECT nvl(MAX(IR_ID),0) INTO V_MAX FROM APEX_IR_SLCT;
											            :NEW.IR_ID:=V_MAX+1;
											            :NEW.APP_ID:=NULL;
											            :NEW.PG_ID:=NULL;
											            APEX_IR_PKG.CRT_IR_PG(P_IR_ID=>:NEW.IR_ID,P_APP_ID_TO=>V_APP,P_PG_ID_TO=>:NEW.PG_ID);
											        ELSIF UPDATING THEN 
											           :NEW.IR_ID:=:OLD.IR_ID;
											            IF NVL(:OLD.SPCL_FLG,0)=1 THEN
											                :NEW.APP_ID:=:OLD.APP_ID;
											                :NEW.PG_ID:=:OLD.PG_ID;
											            END IF;
											        END IF;     
											    END IF;
											   :NEW.RPRT_FILE_NM:=upper(:NEW.RPRT_FILE_NM); 
											   END;
/


--
-- GET_TRNS_NO_POINT_CALC_TRNS  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GET_TRNS_NO_POINT_CALC_TRNS
										BEFORE INSERT
										ON IAS20261.IAS_POINT_CALC_TRNS 
										REFERENCING NEW AS New OLD AS Old
										FOR EACH ROW
BEGIN
										  IF :NEW.TRNS_NO IS NULL THEN
										     BEGIN
										       SELECT RPAD(:NEW.BRN_NO,6,0)||IAS_AR_POINT_SEQ.NEXTVAL INTO :NEW.TRNS_NO FROM DUAL;
										     EXCEPTION WHEN OTHERS THEN
										         RAISE_APPLICATION_ERROR (-20001,'Error When Get Sequence , Ias_Ar_Point_Seq='||SQLERRM);
										     END;      
										  END IF;   
										END;
/


--
-- IAS_DRTMP_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_DRTMP_TRG
AFTER UPDATE
ON IAS20261.IAS_DR_DET_TMP
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN
   Insert Into Ias_Dr_Det_Paid_Tmp (I_No,I_Doc_Ser,I_Doc_No,I_Doc_Date,Doc_Type,Doc_No,Doc_Ser,A_Cy,Amt,amt_f,Doc_Date)
                                 Values ( :new.I_No,:new.Doc_Ser,:new.Doc_No,:new.Doc_Date,:new.Doc_Type,
                                           :new.paid_Doc_No,:new.paid_Doc_Ser,:new.A_Cy,
                                          (nvl(:new.paid_amt_loc,0)-nvl(:old.paid_amt_loc,0)),(nvl(:new.paid_amt,0)-nvl(:old.paid_amt,0)),                                 
                                         :new.paid_Date);
   EXCEPTION
     WHEN OTHERS THEN
        Raise_Application_Error(-20303,' Error When Insert InTo Ias_Dr_Det_Paid_Tmp , '||SqlErrm);
   END IAS_DRTMP_TRG;
/


--
-- INV_ARGMNT_NO_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.Inv_Argmnt_No_Trg Before Insert Or Update
						    ON IAS20261.IAS_CONN_ITM_MSUR_UNT For Each Row
Begin
						   If INSERTING Or 
						   UPDATING('ARGMNT_NO')  Then
						        :New.ARGMNT_NO := Round(:New.ARGMNT_NO,16); 
						   End If; 
						Exception When Others Then
						   Null;
						End Inv_Argmnt_No_Trg ;
/


--
-- SET_AR_MSG_CSS_SEQ  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SET_AR_MSG_CSS_SEQ
                        BEFORE INSERT ON IAS20261.AR_MSG_CSS  FOR EACH ROW
DECLARE
						    V_MSG_NO  NUMBER;
						BEGIN

			      BEGIN
			        SELECT NVL(MAX(MSG_NO),0)+1 
			          INTO V_MSG_NO 
			          FROM AR_MSG_CSS;
			      EXCEPTION WHEN OTHERS THEN
			        V_MSG_NO := 1;
			      END;
        
             IF :NEW.MSG_NO IS NULL THEN
                :NEW.MSG_NO:=   V_MSG_NO;
             END IF; 
          END;
/


