--
-- SQ_GLS_BNK_IDNTF_MST_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SQ_GLS_BNK_IDNTF_MST_TRG BEFORE INSERT
				ON IAS20261.GLS_BNK_IDNTF_MST FOR EACH ROW
BEGIN
					 IF :NEW.DOC_M_SQ IS NULL THEN    
					    :NEW.DOC_M_SQ  := IAS_DOC_SEQ_GL.Nextval; 
					 END IF;
					 IF :NEW.DOC_SRL IS NULL THEN 
					     :NEW.DOC_SRL :=:NEW.BRN_YEAR||Lpad(:NEW.Brn_No,6,'0')||Lpad(:NEW.DOC_TYP,5,'0')||:NEW.DOC_NO;
					 END IF;				 
				EXCEPTION 
				   WHEN OTHERS THEN
				        RAISE_APPLICATION_ERROR(-20401,'Err. When Get Srl/Sequence.');   
				END;
/


