--
-- ARS_V_CMPNS_QTY_COMPARE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_CMPNS_QTY_COMPARE
(DOC_NO, DOC_SRL, C_CODE, DOC_DATE, I_CODE, 
 ITM_UNT, CMPNS_QTY, BILL_QTY)
BEQUEATH DEFINER
AS 
Select "DOC_NO","DOC_SRL","C_CODE","DOC_DATE","I_CODE","ITM_UNT","CMPNS_QTY","BILL_QTY"
							  From (  Select D.Doc_No
							                ,D.Doc_Srl
							                ,m.c_code
							                ,M.DOC_DATE
							                ,D.I_Code
							                ,D.Itm_Unt                
							                ,Sum (Nvl (D.Cmpns_Qty, 0)) Cmpns_Qty
							                ,Nvl ( (Select Sum (Nvl (Free_Qty, 0))
							                          From Ias_V_Bill_Dtl_Cmpns_Qty
							                         Where I_Code = D.I_Code And Doc_Ser_Ref = D.Doc_Srl
							                         and doc_type_ref=160
							                      ) ,0) Bill_Qty
							            From Ias_V_Cmpns_Qty_Clc_Dtl D ,Ias_V_Cmpns_Qty_Clc_Mst M
							            where m.doc_srl=d.doc_srl
							            and nvl(m.NOT_ALLW_RTRN,0)=0
							            AND NVL(M.MANUALLY_CLOSED,0)=0
							        Group By D.Doc_No
							                ,D.Doc_Srl
							                 ,M.DOC_DATE
							                 ,m.c_code
							                ,D.I_Code
							                ,D.Itm_Unt)                   
							 where nvl(CMPNS_QTY,0)>0;

COMMENT ON COLUMN IAS20261.ARS_V_CMPNS_QTY_COMPARE.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.ARS_V_CMPNS_QTY_COMPARE.DOC_SRL IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.ARS_V_CMPNS_QTY_COMPARE.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';

COMMENT ON COLUMN IAS20261.ARS_V_CMPNS_QTY_COMPARE.DOC_DATE IS '1137 -  «—ÌŒ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_CMPNS_QTY_COMPARE.I_CODE IS '176 - —ﬁ„ «·’‰›';



--
-- DTS_INSTLMNT_TRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_INSTLMNT_TRNS
(DOC_TYPE, BILL_NO, BILL_SER, DOC_DATE, C_CODE, 
 I_AMT, PAID_AMT, ADJ_AMT, A_CY, I_PY, 
 I_NO, REM_AMT)
BEQUEATH DEFINER
AS 
SELECT    doc_type,
                                     bill_no,
                                     bill_ser,
                                     doc_date,   
                                    c_code,                                    
                                    SUM (NVL (i_amt, 0)) i_amt,
                                    SUM (NVL (paid_amt, 0)) paid_amt, 
                                    SUM (NVL (adj_amt, 0)) adj_amt,           
                                    a_cy,           
                                    i_py, 
                                    i_no,                       
                                    NVL ((  SUM (NVL (installment.i_amt, 0))
                                          - (  SUM (NVL (installment.paid_amt, 0))
                                             + SUM (NVL (installment.adj_amt, 0))
                                            )
                                         ),
                                         0
                                        ) rem_amt
                           FROM     installment
                           WHERE   DOC_TYPE in(4,0)
                                AND c_code IS NOT NULL     
                               AND  NVL (i_amt, 0) - (NVL (paid_amt, 0) + NVL (adj_amt, 0)) > 0
                           GROUP BY  doc_type,
                                     bill_no,
                                     bill_ser,
                                    doc_date,
                                    c_code,           
                                    a_cy,
                                    i_py,
                                    i_no;


