--
-- DTS_V_GNR_TAX_INPT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GNR_TAX_INPT
(INPT_TYP, INPT_CODE, TAX_NO, CLC_TYP_NO, AGNCY_NO, 
 TAX_PRCNT, A_CODE)
BEQUEATH DEFINER
AS 
Select Distinct    TI.Inpt_Typ
                  ,TI.Inpt_Code 
                  ,Ti.Tax_No 
                  ,Tc.Clc_Typ_No 
                  ,Ti.Agncy_No 
                  ,Ti.Tax_Prcnt 
                  ,TD.AC_CODE_AR A_CODE
     From 
          Sales_Charges D
         ,Gnr_Tax_Inpt Ti
         ,Gnr_Tax_Code_Mst Tm
         ,Gnr_Tax_Code_Dtl Td
         ,Gnr_Tax_Typ_Clc_Dtl Tc
          ,Gnr_Tax_Typ_Clc_MST TCM
          ,Ias_para_gen  p
    Where TI.Inpt_Typ = 1  
    and D.Sc_No = Ti.Inpt_Code
    And Nvl (D.Inv_Item, 0) = 0      
    And Nvl (D.Sc_Add_Frc_Invoice, 0) = 0 
    And Nvl (D.Sc_Type, 0) <> 3 
    And Nvl (D.Diff_Cmpns_Qty_Sr, 0) = 0
    And Nvl(d.INACTIVE,0)=0
    And Ti.Tax_No = Tm.Tax_No
     And Ti.Tax_No = Td.Tax_No 
     And Ti.Agncy_No = Td.Agncy_No 
     And Ti.Tax_No = Tc.Tax_No 
     And Tm.Tax_No = Td.Tax_No 
     And Tm.Tax_No = Tc.Tax_No 
     And Td.Tax_No = Tc.Tax_No 
     And TCM.Clc_Typ_No = Tc.Clc_Typ_No 
     AND NVL(TCM.CLC_TAX_TYP,0)=0
     And Nvl (Tm.Inactive, 0) = 0 
     and nvl(p.use_vat,0)=1;

COMMENT ON TABLE IAS20261.DTS_V_GNR_TAX_INPT IS '—»ÿ «·«⁄»«¡ »«·÷—«∆»';

COMMENT ON COLUMN IAS20261.DTS_V_GNR_TAX_INPT.INPT_TYP IS '‰Ê⁄ «·„œŒ·    1-√⁄»«¡ „»Ì⁄«    ';

COMMENT ON COLUMN IAS20261.DTS_V_GNR_TAX_INPT.INPT_CODE IS '14689-—ﬁ„ «·⁄»∆';

COMMENT ON COLUMN IAS20261.DTS_V_GNR_TAX_INPT.TAX_NO IS '4593 - —ﬁ„ «·÷—Ì»…';

COMMENT ON COLUMN IAS20261.DTS_V_GNR_TAX_INPT.AGNCY_NO IS '2980-—ﬁ„ «·ÃÂÂ';

COMMENT ON COLUMN IAS20261.DTS_V_GNR_TAX_INPT.TAX_PRCNT IS '2208 - ‰”»… «·÷—Ì»…';



--
-- DTS_V_PDA_TYPS_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_PDA_TYPS_PRIV
(U_ID, U_L_NM, U_F_NM, DOC_TYPE, DOC_TYP_NM, 
 TYP_NO, TYP_L_NM, TYP_F_NM, ADD_FLAG, VIEW_FLAG, 
 ONYX_DOC_TYP)
BEQUEATH DEFINER
AS 
Select U_Id
                                               ,U_L_Nm
                                               ,U_F_Nm
                                               ,Doc_Type
                                               ,Doc_Typ_Nm
                                               ,Typ_No
                                               ,Typ_L_Nm
                                               ,Typ_F_Nm
                                               ,Add_Flag
                                               ,View_Flag
                                             ,  decode(Doc_Type,0,2
                                                    ,1,52
                                                    ,2,53
                                                    ,3,4
                                                    ,4,5
                                                    ,9,136
                                                    ,Doc_Type )Onyx_Doc_Typ
                                           From (Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Ar.Ar_Type Doc_Type
                                                       ,Decode (Ar.Ar_Type, 3, 'Sales Types') Doc_Typ_Nm
                                                       ,S.Si_Type Typ_No
                                                       ,Nvl (S.Si_A_Name, S.Si_E_Name) Typ_L_Nm
                                                       ,Nvl (S.Si_E_Name, S.Si_A_Name) Typ_F_Nm
                                                       ,Ar.Add_Flag
                                                       ,Ar.View_Flag
                                                   From User_R U, Ias_Priv_Ar Ar, Ias_Sales_Types S
                                                  Where U.U_Id = Ar.U_Id And Ar.Ar_Type = 3 And Ar.S_Type = S.Si_Type And (Ar.Add_Flag = 1 Or Ar.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Ar.Ar_Type Doc_Type
                                                       ,Decode (Ar.Ar_Type, 4, 'Rt_Sales Types') Doc_Typ_Nm
                                                       ,R.Sr_Type Typ_No
                                                       ,Nvl (R.Sr_A_Name, R.Sr_E_Name) Typ_L_Nm
                                                       ,Nvl (R.Sr_E_Name, R.Sr_A_Name) Typ_F_Nm
                                                       ,Ar.Add_Flag
                                                       ,Ar.View_Flag
                                                   From User_R U, Ias_Priv_Ar Ar, Ias_Rt_Sales_Types R
                                                  Where U.U_Id = Ar.U_Id And Ar.Ar_Type = 4 And Ar.S_Type = R.Sr_Type And (Ar.Add_Flag = 1 Or Ar.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Ar.Ar_Type Doc_Type
                                                       ,Decode (Ar.Ar_Type, 1, 'Quotation Types') Doc_Typ_Nm
                                                       ,Q.Qt_Type Typ_No
                                                       ,Nvl (Q.Qt_A_Name, Q.Qt_E_Name) Typ_L_Nm
                                                       ,Nvl (Q.Qt_E_Name, Q.Qt_A_Name) Typ_F_Nm
                                                       ,Ar.Add_Flag
                                                       ,Ar.View_Flag
                                                   From User_R U, Ias_Priv_Ar Ar, Ias_Quot_Types Q
                                                  Where U.U_Id = Ar.U_Id And Ar.Ar_Type = 1 And Ar.S_Type = Q.Qt_Type And (Ar.Add_Flag = 1 Or Ar.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Ar.Ar_Type Doc_Type
                                                       ,Decode (Ar.Ar_Type, 2, 'Sales Order Types') Doc_Typ_Nm
                                                       ,O.So_Type Typ_No
                                                       ,Nvl (O.So_A_Name, O.So_E_Name) Typ_L_Nm
                                                       ,Nvl (O.So_E_Name, O.So_A_Name) Typ_F_Nm
                                                       ,Ar.Add_Flag
                                                       ,Ar.View_Flag
                                                   From User_R U, Ias_Priv_Ar Ar, Ias_Sorder_Types O
                                                  Where U.U_Id = Ar.U_Id And Ar.Ar_Type = 2 And Ar.S_Type = O.So_Type And (Ar.Add_Flag = 1 Or Ar.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Ar.Ar_Type Doc_Type
                                                       ,Decode (Ar.Ar_Type, 9, 'Rt_Sales Request Types') Doc_Typ_Nm
                                                       ,O.Typ_No Typ_No
                                                       ,Nvl (O.Typ_L_Nm, O.Typ_F_Nm) Typ_L_Nm
                                                       ,Nvl (O.Typ_F_Nm, O.Typ_L_Nm) Typ_F_Nm
                                                       ,Ar.Add_Flag
                                                       ,Ar.View_Flag
                                                   From User_R U, Ias_Priv_Ar Ar, Ias_Ar_Typs O
                                                  Where U.U_Id = Ar.U_Id And Ar.Ar_Type = 9 And O.Ar_Type_No = 9 And Ar.S_Type = O.Typ_No And (Ar.Add_Flag = 1 Or Ar.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,0 Doc_Type
                                                       ,Decode (V.V_Type, 1, 'Voucher Receipt') Doc_Typ_Nm
                                                       ,V.V_Type_No Typ_No
                                                       ,Nvl (V.V_Type_A_Name, V.V_Type_E_Name) Typ_L_Nm
                                                       ,Nvl (V.V_Type_E_Name, V.V_Type_A_Name) Typ_F_Nm
                                                       ,D.Add_Flag
                                                       ,D.View_Flag
                                                   From User_R U, Ias_Vouchr_Type V ,GLS_VCHR_TYP_PRV d
                                                  Where V.V_Type = 1
                                                  and v.V_Type_No=d.V_TYP_NO
                                                  and u.u_id=d.u_id
                                                  and NVL(ADD_FLAG,0)=1
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,5 Doc_Type
                                                       ,'Rep Inventory' Doc_Typ_Nm
                                                       ,Inv.Inv_Type Typ_No
                                                       ,Nvl (Inv.Inv_Name, Inv.Inv_E_Name) Typ_L_Nm
                                                       ,Nvl (Inv.Inv_E_Name, Inv.Inv_Name) Typ_F_Nm
                                                       ,Invp.Add_Flag
                                                       ,Invp.View_Flag
                                                   From User_R U, Ias_Priv_Inv_Type Invp, Ias_Inv_Types Inv
                                                  Where U.U_Id = Invp.U_Id And Invp.Inv_Type = Inv.Inv_Type And (Invp.Add_Flag = 1 Or Invp.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,31 Doc_Type
                                                       ,'Goods Request' Doc_Typ_Nm
                                                       ,Inv.Req_Type Typ_No
                                                       ,Nvl (Inv.Req_Name, Inv.Req_E_Name) Typ_L_Nm
                                                       ,Nvl (Inv.Req_E_Name, Inv.Req_Name) Typ_F_Nm
                                                       ,Invp.Add_Flag
                                                       ,Invp.View_Flag
                                                   From User_R U, Priv_Req_Type Invp, Request_Types Inv
                                                  Where U.U_Id = Invp.U_Id And Nvl (Inv.Out_Trnsfr, 0) <> 1 And Invp.Req_Type = Inv.Req_Type And (Invp.Add_Flag = 1 Or Invp.View_Flag = 1)
                                                 Union
                                                 Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,8 Doc_Type
                                                       ,'Goods Recieve' Doc_Typ_Nm
                                                       ,Inv.Tr_Type Typ_No
                                                       ,Nvl (Inv.Tr_Name, Inv.Tr_E_Name) Typ_L_Nm
                                                       ,Nvl (Inv.Tr_E_Name, Inv.Tr_Name) Typ_F_Nm
                                                       ,Invp.Add_Flag
                                                       ,Invp.View_Flag
                                                   From User_R U, Priv_Trnsfr_Type Invp, Transfer_Types Inv
                                                  Where U.U_Id = Invp.U_Id And Nvl (Inv.Tr_Rec, 0) <> 1 And Invp.Tr_Type = Inv.Tr_Type And (Invp.Add_Flag = 1 Or Invp.View_Flag = 1)
                                                  Union
                                                  Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,11 Doc_Type
                                                       ,'Goods Transfare' Doc_Typ_Nm
                                                       ,Inv.Tr_Type Typ_No
                                                       ,Nvl (Inv.Tr_Name, Inv.Tr_E_Name) Typ_L_Nm
                                                       ,Nvl (Inv.Tr_E_Name, Inv.Tr_Name) Typ_F_Nm
                                                       ,Invp.Add_Flag
                                                       ,Invp.View_Flag
                                                   From User_R U, Priv_Trnsfr_Type Invp, Transfer_Types Inv
                                                  Where U.U_Id = Invp.U_Id 
                                                  And NVL(INV.TR_RES,0)<>1
                                                  And Nvl (Inv.Tr_Rec, 0)IN(1,3) And Invp.Tr_Type = Inv.Tr_Type And (Invp.Add_Flag = 1 Or Invp.View_Flag = 1)
                                                  Union all
                                                  Select U.U_Id
                                                       ,Nvl (U_A_Name, U_E_Name) U_L_Nm
                                                       ,Nvl (U_E_Name, U_A_Name) U_F_Nm
                                                       ,Inv.RQ_DOC_TYPE Doc_Type
                                                       ,decode(Inv.RQ_DOC_TYPE,92,'Receive Requests','Payment Requests') Doc_Typ_Nm
                                                       ,Inv.RQ_TYPE Typ_No
                                                       ,Nvl (Inv.RQ_NAME, Inv.RQ_E_NAME) Typ_L_Nm
                                                       ,Nvl (Inv.RQ_E_NAME, Inv.RQ_NAME) Typ_F_Nm
                                                       ,Invp.Add_Flag
                                                       ,Invp.View_Flag
                                                   From User_R U, IAS_GLRQ_TYPES_PRIV Invp, IAS_GLRQ_TYPES Inv
                                                  Where U.U_Id = Invp.U_Id
                                                  and inv.RQ_DOC_TYPE in(92,93)
                                                  and inv.RQ_DOC_TYPE =Invp.RQ_DOC_TYPE
                                                  and inv.RQ_TYPE =Invp.RQ_TYPE                                                                                                     
                                                  And (Invp.Add_Flag = 1 Or Invp.View_Flag = 1)
                                                  )
                                       Order By U_Id
                                               ,Doc_Type
                                               ,Typ_No
                                               ,Typ_No;


