 BRN_USR, AC_CODE_DTL, AC_CODE_DTL_CSH, AC_DTL_TYP, INSRNCE_CMP_NO, 
 INSRNCE_BNF_NO, INSRNCE_CARD_NO, INSRNCE_CARD_NO_FMLY, NSRNCE_RLTN_TYP, CR_CARD_TYPE, 
 DOC_SEQUENCE_REF, RCRD_NO_REF, CRD_CARD_NO, CRD_CARD_NO_REF, CR_CARD_DSC, 
 AC_CODE_DTL_SUB, ENDRSMNT, DOC_NO_MNL, DOC_DATE_MNL, DUE_REF_NO, 
 DUE_NOTE)
BEQUEATH DEFINER
AS 
SELECT  1 BNK_UONION,
           D.DOC_TYPE      DOC_TYPE,
           D.BILL_DOC_TYPE            JV_TYPE,
           D.BILL_NO          DOC_NO,
           D.BILL_SER               DOC_SER,
           0              W_CODE,
           D.CC_CODE,
           D.PJ_NO,
           D.ACTV_NO,
           0 CASH_NO,
           NULL NO,
           D.A_CODE,
           IAS_ACODE_PKG.Get_AC_Analysis(P_a_code =>D.A_CODE),
           D.A_CY,
          0     DR_AMT,
           0 CR_AMT,
           0   DR_AMT_F,
           0  CR_AMT_F,      
           CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0)) ELSE (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))*NVL(AC_RATE,1) END  AMT,
           CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN 0 ELSE (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))  END      AMT_F,
           D.DOC_DATE    DOC_DATE,
           D.I_DATE        DOC_DUE_DATE,
           NULL          DOC_VALUE_DATE,
           NULL          DOC_DESC,
           1         MNTH,
           D.BRN_YEAR    D_YEAR,
           D.REF_NO,
           NULL       DOC_POST,
           0      DOC_CLOSE,
           0      INV_CLOSE,
           0     CB_BEFORE,
           0     CB_AFTER,
           NULL LC_NO,
           NULL   C_V_CODE,
           NULL   V_C_CODE,
           NULL   COL_NO,
           D.REP_CODE,
           NULL  R_CODE,
           0      HRCHY_NO,
           NULL WO_NO,
           NULL WO_SER,
           D.CHEQUE_NO,
           NULL NOTE_NO,
           NULL CHEQUE_VALUED,
           NULL DOC_TYPE_REF,
           NULL DOC_JV_TYPE_REF,
           NULL DOC_NO_REF,
           NULL DOC_SER_REF,
           D.DOC_SEQUENCE,
           D.EXTERNAL_POST,
           D.RCRD_NO,
           0 G_CODE,
           0  WHG_CODE,
           0 TRMNL_NAME,
           NULL INSTALL_TYPE,
           NULL     MOV_DOC_PY,
           NULL       FROM_CC_CODE,
           NULL     F_BRN_NO,
           D.BRN_NO DOC_BRN_NO,
           NULL CASHIER_NO,
           NULL AUDIT_REF,
           NULL AUDIT_REF_DESC,
           NULL AUDIT_REF_U_ID,
           NULL AUDIT_REF_DATE,
           NULL AD_U_ID,
           NULL AD_DATE,
           NULL UP_U_ID,
           NULL UP_DATE,
           D.UP_CNT,
           0 CNFRM,
           0 CNFRM_DESC,
           0 CNFRM_U_ID,
           0 CNFRM_DATE,
           NULL POST_U_ID,
           NULL POST_DATE,
           NULL UNPOST_U_ID,
           NULL UNPOST_DATE,
           D.CMP_NO,
           D.BRN_NO,
           D.BRN_YEAR,
           D.BRN_USR,
           D.C_CODE AC_CODE_DTL,
           NULL AC_CODE_DTL_CSH,
           3 AC_DTL_TYP,
           NULL    INSRNCE_CMP_NO,
           NULL            INSRNCE_BNF_NO,
           NULL          INSRNCE_CARD_NO,
           NULL         INSRNCE_CARD_NO_FMLY,
           NULL           INSRNCE_RLTN_TYP,
           NULL         CR_CARD_TYPE,
           NULL DOC_SEQUENCE_REF,
           NULL           RCRD_NO_REF,
           NULL CRD_CARD_NO,
           NULL        CRD_CARD_NO_REF,
           NULL        CR_CARD_DSC,
           NULL AC_CODE_DTL_SUB,
           NULL ENDRSMNT,
           0     DOC_NO_MNL,
           0    DOC_DATE_MNL,
           D.Ref_No Due_Ref_No,
           D.I_DATE Due_Note
    FROM   INSTALLMENT D 
   WHERE 1=1 
   AND CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN abs((NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))) ELSE abs(NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))*NVL(AC_RATE,1) END >0  
   UNION  
   SELECT  -1 BNK_UONION,
           D.DOC_TYPE      DOC_TYPE,
           D.BILL_DOC_TYPE            JV_TYPE,
           D.BILL_NO          DOC_NO,
           D.BILL_SER               DOC_SER,
           0              W_CODE,
           D.CC_CODE,
           D.PJ_NO,
           D.ACTV_NO,
           0 CASH_NO,
           NULL NO,
           D.A_CODE,
           IAS_ACODE_PKG.Get_AC_Analysis(P_a_code =>D.A_CODE),
           D.A_CY,
          0     DR_AMT,
           0 CR_AMT,
           0   DR_AMT_F,
           0  CR_AMT_F,
           CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0)) ELSE (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))*NVL(AC_RATE,1) END  AMT,
           CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN 0 ELSE (NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))  END      AMT_F,
           D.DOC_DATE    DOC_DATE,
           D.I_DATE        DOC_DUE_DATE,
           NULL          DOC_VALUE_DATE,
           NULL          DOC_DESC,
           1         MNTH,
           D.BRN_YEAR    D_YEAR,
           D.REF_NO,
           NULL       DOC_POST,
           0      DOC_CLOSE,
           0      INV_CLOSE,
           0     CB_BEFORE,
           0     CB_AFTER,
           NULL LC_NO,
           NULL   C_V_CODE,
           NULL   V_C_CODE,
           NULL   COL_NO,
           NULL REP_CODE,
           NULL  R_CODE,
           0      HRCHY_NO,
           NULL WO_NO,
           NULL WO_SER,
           D.CHEQUE_NO,
           NULL NOTE_NO,
           NULL CHEQUE_VALUED,
           NULL DOC_TYPE_REF,
           NULL DOC_JV_TYPE_REF,
           NULL DOC_NO_REF,
           NULL DOC_SER_REF,
           D.DOC_SEQUENCE,
           D.EXTERNAL_POST,
           D.RCRD_NO,
           0 G_CODE,
           0  WHG_CODE,
           0 TRMNL_NAME,
           NULL INSTALL_TYPE,
           NULL     MOV_DOC_PY,
           NULL       FROM_CC_CODE,
           NULL     F_BRN_NO,
           D.BRN_NO DOC_BRN_NO,
           NULL CASHIER_NO,
           NULL AUDIT_REF,
           NULL AUDIT_REF_DESC,
           NULL AUDIT_REF_U_ID,
           NULL AUDIT_REF_DATE,
           NULL AD_U_ID,
           NULL AD_DATE,
           NULL UP_U_ID,
           NULL UP_DATE,
           D.UP_CNT,
           0 CNFRM,
           0 CNFRM_DESC,
           0 CNFRM_U_ID,
           0 CNFRM_DATE,
           NULL POST_U_ID,
           NULL POST_DATE,
           NULL UNPOST_U_ID,
           NULL UNPOST_DATE,
           D.CMP_NO,
           D.BRN_NO,
           D.BRN_YEAR,
           D.BRN_USR,
           D.V_CODE AC_CODE_DTL,
           NULL AC_CODE_DTL_CSH,
           4 AC_DTL_TYP,
           NULL    INSRNCE_CMP_NO,
           NULL            INSRNCE_BNF_NO,
           NULL          INSRNCE_CARD_NO,
           NULL         INSRNCE_CARD_NO_FMLY,
           NULL           INSRNCE_RLTN_TYP,
           NULL         CR_CARD_TYPE,
           NULL DOC_SEQUENCE_REF,
           NULL           RCRD_NO_REF,
           NULL CRD_CARD_NO,
           NULL        CRD_CARD_NO_REF,
           NULL        CR_CARD_DSC,
           NULL AC_CODE_DTL_SUB,
           NULL ENDRSMNT,
           0     DOC_NO_MNL,
           0    DOC_DATE_MNL,
           D.Ref_No Due_Ref_No,
           D.I_DATE Due_Note
    FROM   IAS_INSTALLMENT_PI D 
   WHERE 1=1  
   AND CASE WHEN D.A_CY=YS_GEN_PKG.GET_LOCAL_CUR THEN abs((NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))) ELSE abs(NVL(D.I_AMT,0) -NVL(PAID_AMT,0)-NVL(ADJ_AMT,0))*NVL(AC_RATE,1) END >0;

