--
-- GLS_V_USR_AC_CODE_DTL_GRPS_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_USR_AC_CODE_DTL_GRPS_PRV
(U_ID, USR_NAME, GRP_CODE, GRP_CODE_NM, AC_CODE, 
 AC_CODE_NM, GRP_CONN_CODE, ADD_FLAG, VIEW_FLAG, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          a.GRP_CODE,
           DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.GRP_L_NM, c.GRP_F_NM),
                  NVL (c.GRP_F_NM, c.GRP_L_NM)
                 ) GRP_CODE_NM,
          c.AC_CODE,
          IAS_ACODE_PKG.GET_A_NAME(c.AC_CODE,ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO')) AC_CODE_NM,
          c.GRP_CONN_CODE,
          a.add_flag,
          a.view_flag,
          a.ad_u_id,
          a.ad_date,
          a.up_u_id,
          a.up_date,
          1 rec_src
   FROM   GLS_AC_CODE_DTL_GRPS_PRIV a,
          user_r b,
          GLS_AC_CODE_DTL_GRPS c
   WHERE  a.u_id = b.u_id
   AND    a.GRP_CODE = c.GRP_CODE
   AND    a.AC_CODE = c.AC_CODE
   AND    (   add_flag = 1
           OR view_flag = 1)
   UNION
   SELECT b.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.GRP_CODE,
           DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.GRP_L_NM, c.GRP_F_NM),
                  NVL (c.GRP_F_NM, c.GRP_L_NM)
                 ) GRP_CODE_NM,
          c.AC_CODE,
          IAS_ACODE_PKG.GET_A_NAME(c.AC_CODE,ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO')) AC_CODE_NM,
          c.GRP_CONN_CODE,
          0 add_flag,
          0 view_flag,
          NULL ad_u_id,
          NULL ad_date,
          NULL up_u_id,
          NULL up_date,
          0 rec_src
   FROM   user_r b,
          GLS_AC_CODE_DTL_GRPS c
   WHERE  NOT EXISTS (
             SELECT 1
             FROM   GLS_AC_CODE_DTL_GRPS_PRIV
             WHERE  GRP_CODE = c.GRP_CODE
             AND    AC_CODE = c.AC_CODE
             AND    u_id = b.u_id
             AND    ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.GLS_V_USR_AC_CODE_DTL_GRPS_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.GLS_V_USR_AC_CODE_DTL_GRPS_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.GLS_V_USR_AC_CODE_DTL_GRPS_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- GLS_V_USR_VCHR_TYP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_USR_VCHR_TYP_PRV
(U_ID, USR_NAME, V_TYP, V_TYP_NM, V_TYP_NO, 
 V_TYP_NO_NM, ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          a.v_typ,
          ys_gen_pkg.get_flg_nm ('CASH_TYPE',
                                 a.v_typ,
                                 ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO')
                                ) typ_nm,
          c.v_type_no,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.v_type_a_name, c.v_type_e_name),
                  NVL (c.v_type_e_name, c.v_type_a_name)
                 ) v_typ_no_nm,
          a.add_flag,
          a.view_flag,
          a.ad_u_id,
          a.ad_date,
          a.up_u_id,
          a.up_date,
          1 rec_src
   FROM   gls_vchr_typ_prv a,
          user_r b,
          ias_vouchr_type c
   WHERE  a.u_id = b.u_id
   AND    a.v_typ = c.v_type
   AND    a.v_typ_no = c.v_type_no
   AND    (   add_flag = 1
           OR view_flag = 1)
   UNION
   SELECT b.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.v_type,
          ys_gen_pkg.get_flg_nm ('CASH_TYPE',
                                 c.v_type,
                                 ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO')
                                ) typ_nm,
          c.v_type_no,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.v_type_a_name, c.v_type_e_name),
                  NVL (c.v_type_e_name, c.v_type_a_name)
                 ) v_typ_no_nm,
          0 add_flag,
          0 view_flag,
          NULL ad_u_id,
          NULL ad_date,
          NULL up_u_id,
          NULL up_date,
          0 rec_src
   FROM   user_r b,
          ias_vouchr_type c
   WHERE  NOT EXISTS (
             SELECT 1
             FROM   gls_vchr_typ_prv
             WHERE  v_typ = c.v_type
             AND    v_typ_no = c.v_type_no
             AND    u_id = b.u_id
             AND    ROWNUM <= 1);


--
-- GNR_TAX_ACCNT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_ACCNT_VW
(A_CODE)
BEQUEATH DEFINER
AS 
SELECT DISTINCT A_CODE
      FROM GNR_TAX_CODE_DTL
           UNPIVOT (A_CODE FOR A_CODE_NAME IN (AC_CODE_AR, AC_CODE_AP))
     WHERE A_CODE IS NOT NULL;


--
-- IAS_ITM_ATTACH_MOVEMENT_PY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_ITM_ATTACH_MOVEMENT_PY
(I_CODE, ITM_UNT, P_SIZE, ATTCH_NO1, ATTCH_DESC_NO1, 
 ATTCH_NO2, ATTCH_DESC_NO2, ATTCH_NO3, ATTCH_DESC_NO3, ATTCH_NO4, 
 ATTCH_DESC_NO4, ATTCH_NO5, ATTCH_DESC_NO5, FLEX_FIELD, FLEX_NO, 
 REC_ATTCH, ATTCH_NOTE, DOC_TYPE, BILL_DOC_TYPE, DOC_NO, 
 DOC_SER, W_CODE, BILL_COST, RCRD_NO_DOC, IN_OUT, 
 CC_CODE, PJ_NO, ACTV_NO, REP_CODE, R_CODE, 
 C_CODE, EXPIRE_DATE, BATCH_NO, I_QTY, P_QTY, 
 FREE_QTY, PF_QTY, RCRD_NO, EXTERNAL_POST, DOC_TYPE_REF, 
 DOC_NO_REF, DOC_SER_REF, OUT_NO, OUT_GR_SER, DOC_DATE, 
 A_CY, AC_RATE, STK_RATE, I_PRICE, DIS_AMT, 
 I_COST, STK_COST, VAT_AMT, OTHR_AMT, V_CODE, 
 RT_TYPE, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR)
BEQUEATH DEFINER
AS 
SELECT "I_CODE","ITM_UNT","P_SIZE","ATTCH_NO1","ATTCH_DESC_NO1","ATTCH_NO2","ATTCH_DESC_NO2","ATTCH_NO3","ATTCH_DESC_NO3","ATTCH_NO4","ATTCH_DESC_NO4","ATTCH_NO5","ATTCH_DESC_NO5","FLEX_FIELD","FLEX_NO","REC_ATTCH","ATTCH_NOTE","DOC_TYPE","BILL_DOC_TYPE","DOC_NO","DOC_SER","W_CODE","BILL_COST","RCRD_NO_DOC","IN_OUT","CC_CODE","PJ_NO","ACTV_NO","REP_CODE","R_CODE","C_CODE","EXPIRE_DATE","BATCH_NO","I_QTY","P_QTY","FREE_QTY","PF_QTY","RCRD_NO","EXTERNAL_POST","DOC_TYPE_REF","DOC_NO_REF","DOC_SER_REF","OUT_NO","OUT_GR_SER","DOC_DATE","A_CY","AC_RATE","STK_RATE","I_PRICE","DIS_AMT","I_COST","STK_COST","VAT_AMT","OTHR_AMT","V_CODE","RT_TYPE","AD_U_ID","AD_DATE","UP_U_ID","UP_DATE","CMP_NO","BRN_NO","BRN_YEAR","BRN_USR"
																													       From IAS20251.Ias_Itm_Attach_Movement a 
																													      Where doc_type=1
																													        And Exists(Select 1 From Ias_V_Si_Py Where Bill_Ser=a.doc_Ser And RowNum<=1)
																													       Order By doc_no;


--
-- IAS_V_AR_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AR_TYPES
(AR_TYPE, TYPE_NO, TYPE_L_NM, TYPE_F_NM, AD_DATE, 
 AD_U_ID, UP_DATE, UP_U_ID)
BEQUEATH DEFINER
AS 
SELECT AR_TYPE ,  TYPE_NO , TYPE_L_NM ,  TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID
					FROM 
					(
					SELECT  1 AR_TYPE , QT_TYPE TYPE_NO ,QT_A_NAME TYPE_L_NM , QT_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_QUOT_TYPES
					UNION ALL
					SELECT  2 AR_TYPE , SO_TYPE TYPE_NO ,SO_A_NAME TYPE_L_NM , SO_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_SORDER_TYPES
					UNION ALL
					SELECT 3 AR_TYPE , SI_TYPE TYPE_NO ,SI_A_NAME TYPE_L_NM , SI_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_SALES_TYPES
					UNION ALL
					SELECT  4 AR_TYPE , SR_TYPE TYPE_NO ,SR_A_NAME TYPEL_NM , SR_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_RT_SALES_TYPES
					UNION ALL
					SELECT  5 AR_TYPE , RCPT_TYPE_NO TYPE_NO ,RCPT_A_NAME TYPE_L_NM , RCPT_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_RCPT_DOC_TYPES
					UNION ALL
					SELECT  6 AR_TYPE , WO_TYPE_NO TYPE_NO ,WO_A_NAME TYPE_L_NM , WO_E_NAME TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_WORK_ORDER_TYPES
					UNION ALL
					SELECT  7 AR_TYPE , TYP_NO TYPE_NO ,TYP_L_NM TYPE_L_NM , TYP_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_AR_TYPS WHERE AR_TYPE_NO = 7
					UNION ALL
					SELECT  8 AR_TYPE , TYP_NO TYPE_NO ,TYP_L_NM TYPE_L_NM , TYP_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_AR_TYPS WHERE AR_TYPE_NO = 8
					UNION ALL
					SELECT  9 AR_TYPE , TYP_NO TYPE_NO ,TYP_L_NM TYPE_L_NM , TYP_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_AR_TYPS WHERE AR_TYPE_NO = 9
					UNION ALL
					SELECT  10 AR_TYPE , TYP_NO TYPE_NO ,TYP_L_NM TYPE_L_NM , TYP_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_AR_TYPS WHERE AR_TYPE_NO = 10
					UNION ALL
					SELECT  11 AR_TYPE , TYP_NO TYPE_NO ,TYP_L_NM TYPE_L_NM , TYP_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  IAS_AR_TYPS WHERE AR_TYPE_NO = 11
					UNION ALL
					SELECT  21 AR_TYPE , CODE_NO TYPE_NO ,CODE_L_NM TYPE_L_NM , CODE_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  ARS_CODE_DTL WHERE CODE_TYP=21
					UNION ALL
					SELECT  22 AR_TYPE , CODE_NO TYPE_NO ,CODE_L_NM TYPE_L_NM , CODE_F_NM TYPE_F_NM ,AD_DATE, AD_U_ID, UP_DATE, UP_U_ID FROM  ARS_CODE_DTL WHERE CODE_TYP=22
					UNION ALL
          SELECT  23 AR_TYPE , c_class TYPE_NO,C_CLASS_NAME  TYPE_L_NM,C_CLASS_E_NAME   TYPE_F_NM,AD_DATE,AD_U_ID,UP_DATE,UP_U_ID FROM customer_class
					);

