--
-- IAS_V_USR_ACC_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_ACC_PRV
(U_ID, USR_NAME, A_CODE, AC_NM, A_CY, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.A_CODE,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.A_Name, C.A_Name_Eng),NVL (C.A_Name_Eng, C.A_Name)) Ac_Nm,
          A.A_Cy,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     FROM Priv_Acc A, User_R B, Account C
    WHERE     A.U_Id     = B.U_Id
          AND   A.A_Code = C.A_Code
          --AND (Add_Flag   = 1 OR View_Flag = 1)
     And Exists  ( Select 1  From Account_Types  
                    Where Nvl (Affected_By_Trans, 0) = 1
                      And Account_Types.Account_Type = C.A_S_M )              
   UNION
   SELECT B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.A_Code,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.A_Name, C.A_Name_Eng),NVL (C.A_Name_Eng, C.A_Name)) Ac_Nm,
          A.A_Cy,
          0 Add_Flag,
          0 View_Flag,
          NULL Ad_U_Id,
          NULL Ad_Date,
          NULL Up_U_Id,
          NULL Up_Date,
          0 Rec_Src
     FROM Account_Curr A, User_R B, Account C
    WHERE A.A_Code = C.A_Code
          AND NOT EXISTS
                     (SELECT 1
                        FROM Priv_Acc
                       WHERE     A_Code = A.A_Code
                             And    A_Cy     = A.A_Cy
                             AND U_Id        =  B.U_Id
                             AND ROWNUM <= 1)
     And Exists  ( Select 1  From Account_Types  
                       Where Nvl (Affected_By_Trans, 0) = 1
                          And Account_Types.Account_Type = C.A_S_M );

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACC_PRV.A_CODE IS '129 - —ﬁ„ «·Õ”«»';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACC_PRV.A_CY IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACC_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACC_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACC_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_ACTIVITY_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_ACTIVITY_PRV
(U_ID, USR_NAME, ACTV_NO, ACTV_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Actv_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Actv_A_Name, C.Actv_E_Name),Nvl (C.Actv_E_Name, C.Actv_A_Name)) Actv_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From IAS_PRIV_ACTVTY A, User_R B, Ias_Actvty  C
    Where     A.U_Id = B.U_Id
          And A.Actv_No = C.Actv_No
          --And (Add_Flag = 1 Or View_Flag = 1)
          And Nvl(C.Actv_Sub,0) = 1 
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Actv_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Actv_A_Name, C.Actv_E_Name),Nvl (C.Actv_E_Name, C.Actv_A_Name)) Actv_Nm,
          0 Add_Flag,
          0 View_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, Ias_Actvty C
    Where Nvl(C.Actv_Sub,0) = 1 
     And Not Exists
             (Select 1
                From IAS_PRIV_ACTVTY
               Where Actv_No = C.Actv_No And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACTIVITY_PRV.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACTIVITY_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACTIVITY_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_ACTIVITY_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_AP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_AP_PRV
(U_ID, USR_NM, AP_TYPE, TYPE_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, FILL_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           A.Ap_Type,
           C.Type_No,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (C.Type_L_NM, C.Type_F_NM),
                   NVL (C.Type_F_NM, C.Type_L_NM))
               Type_NM,
           A.Add_Flag,
           A.View_Flag,
           A.FILL_FLAG,
           A.Ad_U_Id,
           A.Ad_Date,
           A.Up_U_Id,
           A.Up_Date,
           1
               Rec_Src
      FROM Ias_Priv_Ap A, User_R B, Ias_V_Ap_Types C
     WHERE     A.P_Type = C.Type_No
           AND A.Ap_Type = C.Ap_Type
           AND A.U_Id = B.U_Id
           AND (Add_Flag = 1 OR View_Flag = 1)
    UNION
    SELECT B.U_Id,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (B.U_A_Name, B.U_E_Name),
                   NVL (B.U_E_Name, B.U_A_Name))
               Usr_Nm,
           A.Ap_Type,
           A.Type_No,
           DECODE (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                   1, NVL (A.Type_L_NM, A.Type_F_NM),
                   NVL (A.Type_F_NM, A.Type_L_NM))
               Type_NM,
           0
               Add_Flag,
           0
               View_Flag,
           0
               FILL_Flag,
           NULL
               Ad_U_Id,
           NULL
               Ad_Date,
           NULL
               Up_U_Id,
           NULL
               Up_Date,
           0
               Rec_Src
      FROM Ias_V_Ap_Types A, User_R B
     WHERE NOT EXISTS
               (SELECT 1
                  FROM Ias_Priv_Ap
                 WHERE     P_Type = A.Type_No
                       AND Ap_Type = A.Ap_Type
                       AND U_Id = B.U_Id
                       AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_AP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_AP_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_AP_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_AR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_AR_PRV
(U_ID, USR_NAME, AR_TYPE, TYPE_NO, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, FILL_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Ar_Type,
          C.Type_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Type_L_NM, C.Type_F_NM),Nvl (C.Type_F_NM, C.Type_L_NM)) Type_NM,
          A.Add_Flag,
          A.View_Flag,
          A.Fill_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
