--
-- IAS_V_USR_GNR_CODE_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_GNR_CODE_PRV
(U_ID, USR_NAME, MAIN_TYP, SUB_TYP, TYPE_NM, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT        A.U_ID,
                     DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1, NVL (B.U_A_NAME, B.U_E_NAME), NVL (B.U_E_NAME, B.U_A_NAME) ) USR_NM,
                     A.MAIN_TYP,
                     C.SUB_NO,
                     DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1, NVL (C.SUB_L_NAME, C.SUB_F_NAME), NVL (C.SUB_F_NAME, C.SUB_L_NAME) )
                                                                                                                                              TYPE_NM,
                     A.ADD_FLAG,
                     A.VIEW_FLAG,
                     A.AD_U_ID,
                     A.AD_DATE,
                     A.UP_U_ID,
                     A.UP_DATE,
                     1 REC_SRC
       FROM          IAS_GNR_CODE_PRV A,
                     USER_R B,
                     IAS_GNR_CODE_DTL C
       WHERE         C.MAIN_CODE = A.MAIN_TYP
       AND           A.SUB_TYP = C.SUB_NO
       AND           A.MAIN_TYP = C.MAIN_CODE
       AND           A.U_ID = B.U_ID
       AND           (ADD_FLAG = 1 OR VIEW_FLAG = 1)
       UNION
       SELECT        B.U_ID,
