			          A.Unpst_Flag,
			          A.Ad_U_Id,
			          A.Ad_Date,
			          A.Up_U_Id,
			          A.Up_Date,
			          1 Rec_Src,
		            A.F_Order_No
			     From Privilege  A, User_R B, Ias_Form_Name C
			    Where     A.U_Id = B.U_Id
			          And   A.Form_No = C.Form_No
			          And   C.Lang_No= 1
			          --And   Include_Flag = 1
			  Union
			   Select B.U_Id,
			          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
			          C.Form_No,
			          C.Form_Name Form_Name ,
			         0 Include_Flag,
			         0 Add2_Flag,
			         0 Ad_Flag,
			         0 Del_Flag,
			         0 Mod_Flag,
			         0 View_Flag,
			         0 View_F5_Flag,
			         0 Snd_To_Flag,
			         0 Print_Flag,
			         0 Vwrep_Flag,
			         0 Vrfy_Flag,
			         0 Pst_Flag,
			         0 Unpst_Flag,
			          Null Ad_U_Id,
			          Null Ad_Date,
			          Null Up_U_Id,
			          Null Up_Date,
			          0 Rec_Src,
		            Null F_Order_No
			     From User_R B, Ias_Form_Name C
			    Where C.Lang_No= 1 
			          And Not Exists
			             (Select 1
			                From Privilege
			               Where Form_No = C.Form_No And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_SCR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_SCR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_SCR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_STK_TYP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_STK_TYP_PRV
(U_ID, USR_NAME, STK_TYPE, STK_NM, ADD_FLAG, 
 VIEW_FLAG, FILL_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Stk_Type,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Stk_Name, C.Stk_E_Name),Nvl (C.Stk_E_Name, C.Stk_Name)) Stk_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.FILL_FLAG,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From Ias_Priv_Stk_Adjst_Types A, User_R B,Ias_Stk_Adjst_Types C
    Where     A.U_Id = B.U_Id
          And A.Stk_Type = C.Stk_Type
          And (A.Add_Flag = 1 Or A.View_Flag = 1 Or A.Fill_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Stk_Type,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Stk_Name, C.Stk_E_Name),Nvl (C.Stk_E_Name, C.Stk_Name)) Stk_Nm,
          0 Add_Flag,
          0 View_Flag,
          0 Fill_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, Ias_Stk_Adjst_Types C
    Where Not Exists
             (Select 1
                From Ias_Priv_Stk_Adjst_Types
               Where Stk_Type = C.Stk_Type And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_STK_TYP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_STK_TYP_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_STK_TYP_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



