--
-- INV_V_ADJSTMNT_TMP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_ADJSTMNT_TMP
(I_CODE, ITM_UNT, P_SIZE, W_CODE, EXPIRE_DATE, 
 BATCH_NO, I_LENGTH, I_WIDTH, I_HEIGHT, I_NUMBER, 
 AVL_QTY, QTY, P_QTY, ITM_AVL_QTY, TYP, 
 I_NAME, USE_QTY_FRACTION, USE_EXP_DATE, USE_BATCH_NO, USE_WEIGHT, 
 USE_SERIALNO, USE_ATTCH, CLC_AVG_FCTR_FOR_NUM_QTY, APPRVD_ICODE_AS_SERIALNO)
BEQUEATH DEFINER
AS 
Select D."I_CODE",D."ITM_UNT",D."P_SIZE",D."W_CODE",D."EXPIRE_DATE",D."BATCH_NO",D."I_LENGTH",D."I_WIDTH",D."I_HEIGHT",D."I_NUMBER",D."AVL_QTY",D."QTY",D."P_QTY",D."ITM_AVL_QTY",D."TYP",
Null I_Name,
						                    Nvl(Use_Qty_Fraction,0) Use_Qty_Fraction,
						                    Nvl(Use_Exp_Date,0) Use_Exp_Date, 
						                    Nvl(Use_Batch_no,0) Use_Batch_no,
						                    Nvl(Use_Weight,0) Use_Weight,
						                    Nvl(Use_Serialno,0) Use_Serialno,
						                     Nvl(Use_Attch,0) Use_Attch,
						                    Nvl(CLC_AVG_FCTR_FOR_NUM_QTY,0) CLC_AVG_FCTR_FOR_NUM_QTY,
						                    Nvl(APPRVD_ICODE_AS_SERIALNO,0) APPRVD_ICODE_AS_SERIALNO
 from (
Select I_code,
														     Itm_Unt ,
												         P_Size          ,
														     w_code            ,
														     expire_date       ,
														     batch_no          ,
												         I_Length ,        
												         I_Width  ,        
												         I_Height ,        
												         I_Number ,		                          
														     Avl_Qty ,
														      Qty     ,
														      p_qty,
												         Itm_Avl_Qty,
												         Typ  
												         From Table(INV_DOC_TRNS_PKG.Get_Inv_Adjstmnt_Pip_Fnc)
												         ) D , ias_Itm_Mst M
												         Where M.I_Code = D.I_Code;

COMMENT ON COLUMN IAS20261.INV_V_ADJSTMNT_TMP.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_V_ADJSTMNT_TMP.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- INV_V_DOC_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_DOC_TYPES
(TBL_NM, TYPE_NO, TYPE_L_NM, TYPE_F_NM, AD_DATE, 
 AD_U_ID, UP_DATE, UP_U_ID)
BEQUEATH DEFINER
AS 
SELECT TBL_NM,
           TYPE_NO,
           Type_L_Nm,
           Type_F_Nm,
           AD_DATE,
           AD_U_ID,
           UP_DATE,
           UP_U_ID
      FROM (SELECT 'REQUEST_TYPES_TRNSFR'     TBL_NM,
                   REQ_TYPE                   TYPE_NO,
                   REQ_NAME                   Type_L_Nm,
                   REQ_E_NAME                 Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM REQUEST_TYPES
             WHERE NVL (OUT_TRNSFR, 0) IN (1, 3)
            UNION ALL
            SELECT 'REQUEST_TYPES_OUT'     TBL_NM,
                   REQ_TYPE                TYPE_NO,
                   REQ_NAME                Type_L_Nm,
                   REQ_E_NAME              Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM REQUEST_TYPES
             WHERE NVL (OUT_TRNSFR, 0) IN (2, 3)
            UNION ALL
            SELECT 'INCOM_TYPES'     TBL_NM,
                   INCOM_TYPE        TYPE_NO,
                   INCOM_NAME        Type_L_Nm,
                   INCOM_E_NAME      Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM INCOM_TYPES
            UNION ALL
            SELECT 'OUT_TYPES'     TBL_NM,
                   OUT_TYPE        TYPE_NO,
                   OUT_NAME        Type_L_Nm,
                   OUT_E_NAME      Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM OUT_TYPES
            UNION ALL
            SELECT 'TRANSFER_TYPES_TR'     TBL_NM,
                   TR_TYPE                 TYPE_NO,
                   TR_NAME                 Type_L_Nm,
                   TR_E_NAME               Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM TRANSFER_TYPES
             WHERE NVL (TR_RES, 0) IN (1, 3)
            UNION ALL
            SELECT 'TRANSFER_TYPES_RES'     TBL_NM,
                   TR_TYPE                  TYPE_NO,
                   TR_NAME                  Type_L_Nm,
                   TR_E_NAME                Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM TRANSFER_TYPES
             WHERE NVL (TR_RES, 0) IN (2, 3)
            UNION ALL
            SELECT 'IAS_STK_ADJST_TYPES_RQ'     TBL_NM,
                   STK_TYPE                     TYPE_NO,
                   STK_NAME                     Type_L_Nm,
                   STK_E_NAME                   Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_STK_ADJST_TYPES
             WHERE NVL (RQ_STK_TYPE_FLG, 0) = 1
            UNION ALL
            SELECT 'IAS_STK_ADJST_TYPES'     TBL_NM,
                   STK_TYPE                  TYPE_NO,
                   STK_NAME                  Type_L_Nm,
                   STK_E_NAME                Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_STK_ADJST_TYPES
             WHERE NVL (RQ_STK_TYPE_FLG, 0) = 0
            UNION ALL
            SELECT 'IAS_INV_TYPES'     TBL_NM,
                   Inv_Type            TYPE_NO,
                   INV_NAME            Type_L_Nm,
                   INV_E_NAME          Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_INV_TYPES
            UNION ALL
            SELECT 'IAS_QUOT_TYPES'     TBL_NM,
                   QT_TYPE              TYPE_NO,
                   QT_A_NAME            TYPE_L_NM,
                   QT_E_NAME            TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_QUOT_TYPES
            UNION ALL
            SELECT 'IAS_SORDER_TYPES'     TBL_NM,
                   SO_TYPE                TYPE_NO,
                   SO_A_NAME              TYPE_L_NM,
                   SO_E_NAME              TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_SORDER_TYPES
            UNION ALL
            SELECT 'IAS_SALES_TYPES'     TBL_NM,
                   SI_TYPE               TYPE_NO,
                   SI_A_NAME             TYPE_L_NM,
                   SI_E_NAME             TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_SALES_TYPES
            UNION ALL
            SELECT 'IAS_RT_SALES_TYPES'     TBL_NM,
                   SR_TYPE                  TYPE_NO,
                   SR_A_NAME                TYPEL_NM,
                   SR_E_NAME                TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_RT_SALES_TYPES
            UNION ALL
            SELECT 'IAS_RCPT_DOC_TYPES'     TBL_NM,
                   RCPT_TYPE_NO             TYPE_NO,
                   RCPT_A_NAME              TYPE_L_NM,
                   RCPT_E_NAME              TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_RCPT_DOC_TYPES
            UNION ALL
            SELECT 'IAS_WORK_ORDER_TYPES'     TBL_NM,
                   WO_TYPE_NO                 TYPE_NO,
                   WO_A_NAME                  TYPE_L_NM,
                   WO_E_NAME                  TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_WORK_ORDER_TYPES
            UNION ALL
            SELECT 'IAS_AR_TYPS_7'     TBL_NM,
                   TYP_NO              TYPE_NO,
                   TYP_L_NM            TYPE_L_NM,
                   TYP_F_NM            TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_AR_TYPS
             WHERE AR_TYPE_NO = 7
            UNION ALL
            SELECT 'IAS_AR_TYPS_8'     TBL_NM,
                   TYP_NO              TYPE_NO,
                   TYP_L_NM            TYPE_L_NM,
                   TYP_F_NM            TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_AR_TYPS
             WHERE AR_TYPE_NO = 8
            UNION ALL
            SELECT 'IAS_AR_TYPS_9'     TBL_NM,
                   TYP_NO              TYPE_NO,
                   TYP_L_NM            TYPE_L_NM,
                   TYP_F_NM            TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_AR_TYPS
             WHERE AR_TYPE_NO = 9
            UNION ALL
            SELECT 'IAS_AR_TYPS_10'     TBL_NM,
                   TYP_NO               TYPE_NO,
                   TYP_L_NM             TYPE_L_NM,
                   TYP_F_NM             TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_AR_TYPS
             WHERE AR_TYPE_NO = 10
            UNION ALL
            SELECT 'ARS_CODE_DTL_21'     TBL_NM,
                   CODE_NO               TYPE_NO,
                   CODE_L_NM             TYPE_L_NM,
                   CODE_F_NM             TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM ARS_CODE_DTL
             WHERE CODE_TYP = 21
            UNION ALL
            SELECT 'ARS_CODE_DTL_22'     TBL_NM,
                   CODE_NO               TYPE_NO,
                   CODE_L_NM             TYPE_L_NM,
                   CODE_F_NM             TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM ARS_CODE_DTL
             WHERE CODE_TYP = 22
            UNION ALL
            SELECT 'CUSTOMER_CLASS'     TBL_NM,
                   c_class              TYPE_NO,
                   C_CLASS_NAME         TYPE_L_NM,
                   C_CLASS_E_NAME       TYPE_F_NM,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM CUSTOMER_CLASS
            UNION ALL
            SELECT 'IAS_PREQ_TYPES'     TBL_NM,
                   Pr_TYPE              TYPE_No,
                   Pr_A_NAME            Type_L_Nm,
                   Pr_E_NAME            Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_PREQ_TYPES
            UNION ALL
            SELECT 'IAS_PORDER_TYPES'     TBL_NM,
                   Po_TYPE                TYPE_No,
                   Po_A_NAME              Type_L_Nm,
                   Po_E_NAME              Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_PORDER_TYPES
            UNION ALL
            SELECT 'IAS_GRN_TYPES'     TBL_NM,
                   GRN_TYPE            TYPE_No,
                   GRN_A_NAME          Type_L_Nm,
                   GRN_E_NAME          Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_GRN_TYPES
            UNION ALL
            SELECT 'IAS_AP_BILL_TYPES'     TBL_NM,
                   Bill_TYPE_No            TYPE_No,
                   Type_L_NAME             Type_L_Nm,
                   Type_F_NAME             Type_F_Nm,
                   AD_DATE,
                   AD_U_ID,
                   UP_DATE,
                   UP_U_ID
              FROM IAS_AP_BILL_TYPES
            UNION ALL
            SELECT 'IAS_AP_TYPES'     TBL_NM,
                   typ_no             type_no,
                   typ_l_name         type_l_nm,
                   typ_f_name         type_f_nm,
                   ad_date,
                   ad_u_id,
                   up_date,
                   up_u_id
              FROM IAS_AP_TYPES
            UNION ALL
            SELECT 'IAS_AP_ADD_DSC_TYP'     TBL_NM,
                   Add_Dsc_Typ_No           Type_No,
                   Type_L_Name              Type_L_Nm,
                   Type_F_Name              Type_F_Nm,
                   Ad_Date,
                   Ad_U_Id,
                   Up_Date,
                   Up_U_Id
              FROM IAS_AP_ADD_DSC_TYP);

COMMENT ON COLUMN IAS20261.INV_V_DOC_TYPES.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.INV_V_DOC_TYPES.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.INV_V_DOC_TYPES.UP_U_ID IS '760 - „⁄œ· «·”Ã·';



--
-- S_V_APPRVD_USR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_APPRVD_USR
(U_ID, LVL_NO, DOC_TYP, TYP_NO, T_AMT, 
 F_AMT, PRV_FLG, AD_U_ID, AD_DATE)
BEQUEATH DEFINER
AS 
SELECT 
  M.U_ID 
 ,M.LVL_NO
 ,M.DOC_TYP
 ,D.TYP_NO 
 ,NVL(D.T_AMT,M.T_AMT) T_AMT
 ,NVL(D.F_AMT,M.F_AMT) F_AMT
 ,M.PRV_FLG
 ,M.AD_U_ID
 ,M.AD_DATE
FROM S_APPRVD_USR M, S_APPRVD_USR_DTL D
WHERE D.U_ID(+) = M.U_ID
  AND D.LVL_NO(+) = M.LVL_NO 
  AND D.DOC_TYP(+) = M.DOC_TYP;


--
-- S_V_FLD_DFLT_USR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_FLD_DFLT_USR
(FLD_NM, FLD_LBL_NO, FLD_TYP, FLD_LOV_NM, FLD_LOV_WHR, 
 FLD_ORDR, FLD_LOV_RTRN_CLMN_NM, FLD_LOV_WHR_CLMN_NM, FLD_DFLT_VAL, FLD_OPN_FILE, 
 FLD_LBL_NM, FLD_VAL_DSC, U_ID, FLD_VAL, AD_U_ID, 
 AD_DATE, AD_TRMNL_NM, UP_U_ID, UP_DATE, UP_CNT, 
 UP_TRMNL_NM, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.FLD_NM, A.FLD_LBL_NO, A.FLD_TYP, A.FLD_LOV_NM, A.FLD_LOV_WHR, A.FLD_ORDR, 
       A.FLD_LOV_RTRN_CLMN_NM, A.FLD_LOV_WHR_CLMN_NM, A.FLD_DFLT_VAL, A.FLD_OPN_FILE, 
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO) FLD_LBL_NM, 
       ADM_INSRT_TRNS_PKG.GET_LOV_RTRN_FLD_NM_FNC ( P_FLD_LOV_NM           => A.FLD_LOV_NM,
                                                    P_FLD_VAL              => B.FLD_VAL,
                                                    P_FLD_LOV_WHR          => A.FLD_LOV_WHR,
                                                    P_FLD_LOV_WHR_CLMN_NM  => A.FLD_LOV_WHR_CLMN_NM,
                                                    P_FLD_LOV_RTRN_CLMN_NM => A.FLD_LOV_RTRN_CLMN_NM)  FLD_VAL_DSC,
       B.U_ID, B.FLD_VAL, B.AD_U_ID, B.AD_DATE, B.AD_TRMNL_NM, B.UP_U_ID, B.UP_DATE, B.UP_CNT, B.UP_TRMNL_NM, 
       1 REC_SRC
     From S_FLD_DFLT A, S_FLD_DFLT_USR B
    Where A.FLD_NM = B.FLD_NM
      AND NVL(A.FLD_ST_FLG,0)=1
  Union
Select A.FLD_NM, A.FLD_LBL_NO, A.FLD_TYP, A.FLD_LOV_NM, A.FLD_LOV_WHR, A.FLD_ORDR, 
       A.FLD_LOV_RTRN_CLMN_NM, A.FLD_LOV_WHR_CLMN_NM, A.FLD_DFLT_VAL, A.FLD_OPN_FILE,
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO) FLD_LBL_NM, 
       A.FLD_DFLT_VAL FLD_VAL_DSC,
       B.U_ID, A.FLD_DFLT_VAL FLD_VAL, NULL AD_U_ID, NULL AD_DATE, NULL AD_TRMNL_NM, NULL UP_U_ID, NULL UP_DATE, NULL UP_CNT, NULL UP_TRMNL_NM, 
       0 REC_SRC
   From S_FLD_DFLT A, User_R B
  Where NVL(A.FLD_ST_FLG,0)=1
    AND Not Exists
             (Select 1
                From S_FLD_DFLT_USR D
               Where D.FLD_NM = A.FLD_NM  And D.U_ID = B.U_ID And Rownum <= 1);

COMMENT ON COLUMN IAS20261.S_V_FLD_DFLT_USR.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_FLD_DFLT_USR.AD_TRMNL_NM IS '1726 - «”„ «·ÃÂ«“ «·„œŒ·';

COMMENT ON COLUMN IAS20261.S_V_FLD_DFLT_USR.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_FLD_DFLT_USR.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.S_V_FLD_DFLT_USR.UP_CNT IS '1969 - „—«  «· ⁄œÌ·';



--
-- S_V_HRCHY_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_HRCHY_PRV
(U_ID, USR_NAME, EMPNO_HRCHYNO, EMPNM_HRCHYNM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (b.u_a_name, b.u_e_name),
						                  NVL (b.u_e_name, b.u_a_name)
						                 ) usr_nm,
						          a.empno_hrchyno,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (c.hrchy_l_nm, c.hrchy_f_nm),
						                  NVL (c.hrchy_f_nm, c.hrchy_l_nm)
						                 ) empnm_hrchynm,
						          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
						          1 rec_src
						     FROM s_emp_prv a, user_r b, s_hrchy c
						    WHERE a.u_id = b.u_id
						      AND a.empno_hrchyno = c.hrchy_no
						      AND a.emp_prv_typ = 2
						      AND (add_flag = 1 OR view_flag = 1)
						   UNION
						   SELECT b.u_id,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (b.u_a_name, b.u_e_name),
						                  NVL (b.u_e_name, b.u_a_name)
						                 ) usr_nm,
						          c.hrchy_no empno_hrchyno,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (c.hrchy_l_nm, c.hrchy_f_nm),
						                  NVL (c.hrchy_f_nm, c.hrchy_l_nm)
						                 ) empnm_hrchynm,
						          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
						          NULL up_date, 0 rec_src
						     FROM user_r b, s_hrchy c
						    WHERE NOT EXISTS (
						             SELECT 1
						               FROM s_emp_prv
						              WHERE empno_hrchyno = c.hrchy_no
						                AND u_id = b.u_id
						                AND emp_prv_typ = 2
						                AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.S_V_HRCHY_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_HRCHY_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_HRCHY_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- S_V_PRD_BRN_UNCLS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_PRD_BRN_UNCLS
(BRN_NO, PRD_NO, YR_NO, F_DATE, T_DATE)
BEQUEATH DEFINER
AS 
Select Brn_No, Prd_No, YR_NO, F_Date, T_Date
														 From S_Prd_Brn_Cls M
														Where NVL(Prd_Cls,0) = 0 
														  And Prd_No =(Select Min(Prd_No) From S_Prd_Brn_Cls D
														                  Where NVL(Prd_Cls,0) = 0
														                    And D.Brn_No = M.Brn_No
														                    AND D.YR_NO = (Select Min(Yr_No) From S_Prd_Brn_Cls DD
														                                                    Where DD.Brn_No = M.Brn_No 
														                                                      And Nvl(DD.Prd_Cls,0) = 0 ));

COMMENT ON COLUMN IAS20261.S_V_PRD_BRN_UNCLS.BRN_NO IS '50 - —ﬁ„ «·›—⁄';



