--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_PRD_DTL_YR
(ROW_ID, UMARKER, PRD_TYP, PRD_NO, PRD_L_NM, 
 PRD_F_NM, F_DATE, T_DATE, YR_NO, INACTV, 
 PRD_SEASON, VAT_PRD_NO, TAX_RTRN_ST, CLNDR_F_DATE, CLNDR_T_DATE, 
 CLNDR_PRD_F_NM, CLNDR_PRD_L_NM, MIN_TAX_PRD_DAY, TAX_PRD_STATUS, DIFF_DAYS, 
 UP_U_ID, UP_DATE, UP_CNT)
BEQUEATH DEFINER
AS 
SELECT ROWID ROW_ID,1 UMARKER , PRD_TYP,PRD_NO,PRD_L_NM,PRD_F_NM,F_DATE,T_DATE,YR_NO,INACTV,PRD_SEASON,VAT_PRD_NO,TAX_RTRN_ST,CLNDR_F_DATE,CLNDR_T_DATE,CLNDR_PRD_F_NM,CLNDR_PRD_L_NM,MIN_TAX_PRD_DAY,TAX_PRD_STATUS,DIFF_DAYS,UP_U_ID,UP_DATE,UP_CNT FROM IAS20241.S_PRD_DTL           UNION ALL  SELECT ROWID ROW_ID,1 UMARKER , PRD_TYP,PRD_NO,PRD_L_NM,PRD_F_NM,F_DATE,T_DATE,YR_NO,INACTV,PRD_SEASON,VAT_PRD_NO,TAX_RTRN_ST,CLNDR_F_DATE,CLNDR_T_DATE,CLNDR_PRD_F_NM,CLNDR_PRD_L_NM,MIN_TAX_PRD_DAY,TAX_PRD_STATUS,DIFF_DAYS,UP_U_ID,UP_DATE,UP_CNT FROM IAS20251.S_PRD_DTL           UNION ALL  SELECT ROWID ROW_ID,1 UMARKER , PRD_TYP,PRD_NO,PRD_L_NM,PRD_F_NM,F_DATE,T_DATE,YR_NO,INACTV,PRD_SEASON,VAT_PRD_NO,TAX_RTRN_ST,CLNDR_F_DATE,CLNDR_T_DATE,CLNDR_PRD_F_NM,CLNDR_PRD_L_NM,MIN_TAX_PRD_DAY,TAX_PRD_STATUS,DIFF_DAYS,UP_U_ID,UP_DATE,UP_CNT FROM IAS20261.S_PRD_DTL           UNION ALL  SELECT ROWID ROW_ID,2 UMARKER , PRD_TYP,PRD_NO,PRD_L_NM,PRD_F_NM,F_DATE,T_DATE,YR_NO,INACTV,PRD_SEASON,VAT_PRD_NO,TAX_RTRN_ST,CLNDR_F_DATE,CLNDR_T_DATE,CLNDR_PRD_F_NM,CLNDR_PRD_L_NM,MIN_TAX_PRD_DAY,TAX_PRD_STATUS,DIFF_DAYS,UP_U_ID,UP_DATE,UP_CNT FROM S_PRD_DTL           WHERE 1 = 2;


--
-- S_V_S_FLD_PRV_FXD_USR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_S_FLD_PRV_FXD_USR
(FLD_NM, FLD_LBL_NO, FLD_LBL_NO2, FLD_TYP, FLD_LNGTH, 
 FLD_ORDR, FLD_CHKBOX_FLG, FLD_VSBL_SLCT, FLD_UPDTD_SLCT, FLD_DFLT_VAL, 
 FLD_SYS, FLD_LOV_NM, FLD_LOV_WHR, FLD_LOV_RTRN_CLMN_NM, FLD_LOV_WHR_CLMN_NM, 
 FLD_LBL_NM, FLD_LBL_NM2, FLD_VAL_DSC, U_ID, FLD_VAL, 
 AD_U_ID, AD_DATE, AD_TRMNL_NM, UP_U_ID, UP_DATE, 
 UP_CNT, UP_TRMNL_NM, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.FLD_NM, A.FLD_LBL_NO, A.FLD_LBL_NO2, A.FLD_TYP, A.FLD_LNGTH, A.FLD_ORDR, A.FLD_CHKBOX_FLG, A.FLD_VSBL_SLCT, A.FLD_UPDTD_SLCT,
       A.FLD_DFLT_VAL, A.FLD_SYS, A.FLD_LOV_NM, A.FLD_LOV_WHR, A.FLD_LOV_RTRN_CLMN_NM, A.FLD_LOV_WHR_CLMN_NM,  
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO) FLD_LBL_NM, 
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO2) FLD_LBL_NM2,
       ADM_INSRT_TRNS_PKG.GET_LOV_RTRN_FLD_NM_FNC ( P_FLD_LOV_NM           => A.FLD_LOV_NM,
                                                    P_FLD_VAL              => B.FLD_VAL,
                                                    P_FLD_LOV_WHR          => A.FLD_LOV_WHR,
                                                    P_FLD_LOV_WHR_CLMN_NM  => A.FLD_LOV_WHR_CLMN_NM,
                                                    P_FLD_LOV_RTRN_CLMN_NM => A.FLD_LOV_RTRN_CLMN_NM)  FLD_VAL_DSC,
       B.U_ID, B.FLD_VAL, B.AD_U_ID, B.AD_DATE, B.AD_TRMNL_NM, B.UP_U_ID, B.UP_DATE, B.UP_CNT, B.UP_TRMNL_NM, 
       1 REC_SRC
     From S_FLD_PRV_FXD A, S_FLD_PRV_FXD_USR B
    Where A.FLD_NM = B.FLD_NM
  Union
Select A.FLD_NM, A.FLD_LBL_NO, A.FLD_LBL_NO2, A.FLD_TYP, A.FLD_LNGTH, A.FLD_ORDR, A.FLD_CHKBOX_FLG, A.FLD_VSBL_SLCT, A.FLD_UPDTD_SLCT,
       A.FLD_DFLT_VAL, A.FLD_SYS, A.FLD_LOV_NM, A.FLD_LOV_WHR, A.FLD_LOV_RTRN_CLMN_NM, A.FLD_LOV_WHR_CLMN_NM,  
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO) FLD_LBL_NM, 
       YS_GEN_PKG.Get_Prompt(P_Lng_no =>Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,P_Lbl_no => A.FLD_LBL_NO2) FLD_LBL_NM2,
       A.FLD_DFLT_VAL FLD_VAL_DSC,
       B.U_ID, NULL FLD_VAL, NULL AD_U_ID, NULL AD_DATE, NULL AD_TRMNL_NM, NULL UP_U_ID, NULL UP_DATE, NULL UP_CNT, NULL UP_TRMNL_NM, 
       0 REC_SRC
   From S_FLD_PRV_FXD A, User_R B
  Where Not Exists
             (Select 1
                From S_FLD_PRV_FXD_USR D
               Where D.FLD_NM = A.FLD_NM  And D.U_ID = B.U_ID And Rownum <= 1);

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.FLD_CHKBOX_FLG IS '49 - —ﬁ„ ’‰œÊﬁ «·»—Ìœ';

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.AD_TRMNL_NM IS '1726 - «”„ «·ÃÂ«“ «·„œŒ·';

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.S_V_S_FLD_PRV_FXD_USR.UP_CNT IS '1969 - „—«  «· ⁄œÌ·';



--
-- S_V_USR_DSH_BORD_FVRT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_USR_DSH_BORD_FVRT
(U_ID, MAIN_NO, DSH_NO, VIEW_NO, ORDR_NO, 
 MAIN_DSH_CHRT_NO, LBL_NO, DSH_USR_L_TITLE, DSH_USR_F_TITLE, MAIN_DSH_ROWS, 
 DFLT_INDCTR_COL, DFLT_INDCTR_VAL, DFLT_INDCTR_GRP, MAIN_DSH_FETCH_TO_COLTION, WIDTH_IN_MAIN_DSH, 
 SHOW_LEGEND, LEGEND_POSITION, SHOW_LABELS, DFLT_Z_INDCTR_VAL, USR_LINE_FLAG_TYPE, 
 USR_LINE_FLAG_STYLE, USR_LINE_FLAG1_VALUE, USR_LINE_FLAG1_L_TITLE, USR_LINE_FLAG1_F_TITLE, USR_LINE_FLAG1_COLOR, 
 USR_LINE_FLAG2_VALUE, USR_LINE_FLAG2_L_TITLE, USR_LINE_FLAG2_F_TITLE, USR_LINE_FLAG2_COLOR, USR_LINE_FLAG3_VALUE, 
 USR_LINE_FLAG3_L_TITLE, USR_LINE_FLAG3_F_TITLE, USR_LINE_FLAG3_COLOR, SHOW_IN_MAIN, MAIN_AUTO_REF_SCNDS, 
 PRIORITY_LEVEL)
BEQUEATH DEFINER
AS 
SELECT 
						    U_ID, 0 MAIN_NO, dsh_no , view_no , ordr_no, main_dsh_chrt_no, lbl_no, dsh_usr_l_title, dsh_usr_f_title, main_dsh_rows, dflt_indctr_col, dflt_indctr_val, dflt_indctr_grp, main_dsh_fetch_to_coltion, 
								width_in_main_dsh, show_legend, legend_position, show_labels, dflt_z_indctr_val, usr_line_flag_type, usr_line_flag_style, 
								usr_line_flag1_value, usr_line_flag1_l_title, usr_line_flag1_f_title, usr_line_flag1_color,
								usr_line_flag2_value, usr_line_flag2_l_title, usr_line_flag2_f_title, usr_line_flag2_color,
								usr_line_flag3_value, usr_line_flag3_l_title, usr_line_flag3_f_title, usr_line_flag3_color,
								show_in_main, main_auto_ref_scnds, PRIORITY_LEVEL
								FROM S_usr_dsh_bord_fvrt F 
								WHERE F.INACTIVE=0 --AND U_ID=1
								UNION
								SELECT 
								        U.U_ID,M.MAIN_NO, M.dsh_no , M.view_no , M.ordr_no, chrt_no, NVL(F.lbl_no,M.lbl_no) lbl_no, 
								        NVL(F.DSH_USR_L_TITLE,M.chrt_l_title) chrt_l_title,NVL(F.DSH_USR_F_TITLE,chrt_f_title) chrt_f_title, chrt_rows, NVL(F.dflt_indctr_col,M.dflt_indctr_col) dflt_indctr_col, 
								        NVL(F.dflt_indctr_val,M.dflt_indctr_val) dflt_indctr_val, NVL(F.dflt_indctr_grp,M.dflt_indctr_grp) dflt_indctr_grp, fetch_to_coltion, 
								        chrt_width, NVL(F.show_legend,M.show_legend) show_legend, NVL(F.legend_position,M.legend_position) legend_position, NVL(F.show_labels,M.show_labels) show_labels, 
								        NVL(F.dflt_z_indctr_val,M.dflt_z_indctr_val) dflt_z_indctr_val , line_flag_type, line_flag_style, 
								        line_flag1_value, line_flag1_title, null line_flag1_f_title, line_flag1_color,
								        line_flag2_value, line_flag2_title, null line_flag2_f_title, line_flag2_color,
								        line_flag3_value, line_flag3_title, null line_flag3_f_title, line_flag3_color,
								        show_in_main, auto_ref_scnds, U.PRIORITY_LEVEL
								FROM S_DSH_BORD_MAIN_CHRT M , S_USR_DSH_BORD_FVRT F, S_DSH_BORD_MAIN_USR U 
								WHERE M.DSH_NO=F.DSH_NO(+)  AND M.VIEW_NO=F.VIEW_NO(+) AND M.CHRT_NO IS NOT NULL
								AND M.MAIN_NO=U.MAIN_NO AND (U.U_ID=F.U_ID or F.U_ID is null) AND F.INACTIVE(+)=0 AND U.INACTIVE=0;


--
-- S_V_USR_MOBILE_SCR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_USR_MOBILE_SCR_PRV
(U_ID, USR_NM, SCR_NO, ADD_FLAG, PRV_FLG, 
 AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_ID,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (b.u_a_name, b.u_e_name),
						                  NVL (b.u_e_name, b.u_a_name)
						                 ) usr_nm,
						          a.scr_no, a.add_flag, a.prv_flg, a.ad_u_id, a.ad_date, a.up_u_id,
						          a.up_date, 1 rec_src
						     FROM s_mobile_scr_prv a, user_r b, s_mobile_scr c
						    WHERE a.u_id = b.u_id
						      AND a.scr_no = c.scr_no
						      AND (a.add_flag = 1 OR prv_flg = 1)
						      AND NVL (c.inactive, 0) = 0
						   UNION
						   SELECT b.u_id,
						          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
						                  1, NVL (b.u_a_name, b.u_e_name),
						                  NVL (b.u_e_name, b.u_a_name)
						                 ) usr_nm,
						          c.scr_no, 0 add_flag, 0 prv_flg, NULL ad_u_id, NULL ad_date,
						          NULL up_u_id, NULL up_date, 0 rec_src
						     FROM user_r b, s_mobile_scr c
						    WHERE NVL (c.inactive, 0) = 0
						      AND NOT EXISTS (
						                     SELECT 1
						                       FROM s_mobile_scr_prv
						                      WHERE u_id = b.u_id AND scr_no = c.scr_no
						                            AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.S_V_USR_MOBILE_SCR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_USR_MOBILE_SCR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_USR_MOBILE_SCR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- S_V_USR_TP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_USR_TP_PRV
(U_ID, USR_NAME, FORM_NO, OBJ_NM, TP_NM, 
 LBL_NO, PRV_FLG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (b.u_a_name, b.u_e_name),NVL (b.u_E_name, b.u_A_name)) usr_nm,
          a.form_no,
          c.obj_nm,
          c.tp_nm,
          c.lbl_no,
          a.prv_flg,
          a.ad_u_id,
          a.ad_date,
          a.up_u_id,
          a.up_date,
          1 rec_src
     FROM s_usr_tp_prv a, user_r b, s_tp c
     WHERE a.u_id = b.u_id
          AND a.form_no = c.form_no
          AND a.obj_nm = c.obj_nm
          AND a.tp_nm = c.tp_nm
          AND prv_flg = 1
   UNION
   SELECT b.u_id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (b.u_a_name, b.u_e_name),NVL (b.u_e_name, b.u_a_name)) usr_nm,
          c.form_no,
          c.obj_nm,
          c.tp_nm,
          c.lbl_no,
          0 prv_flg,
          NULL ad_u_id,
          NULL ad_date,
          NULL up_u_id,
          NULL up_date,
          0 rec_src
     FROM user_r b, s_tp c
    WHERE NOT EXISTS
                 (SELECT 1
                    FROM s_usr_tp_prv
                   WHERE     form_no = c.form_no
                         AND obj_nm = c.obj_nm
                         AND tp_nm = c.tp_nm
                         AND u_id = b.u_id
                         AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.S_V_USR_TP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_USR_TP_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_USR_TP_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



