--
-- YS_OBJ_VRSN  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.YS_OBJ_VRSN
(DUMMY_COL, SYS_NO, OBJ_TYP, OBJ_NM, OBJ_CODE, 
 OBJ_VRSN, HNT_OBJ_VRSN, OBJ_PARNT, OBJ_PATH, F_FILE_NAME)
BEQUEATH DEFINER
AS 
SELECT 1                                                        DUMMY_COL,
               O.SYS_NO,
               O.OBJ_TYP,
               O.OBJ_NM,
               O.OBJ_CODE,
               NVL (O.OBJ_VRSN, 'V8.0.01.01.2022')                      OBJ_VRSN,
               (SELECT MAX(H.HNT_OBJ_VRSN) FROM YS_OBJ_HNT H WHERE H.OBJ_CODE=O.OBJ_CODE) HNT_OBJ_VRSN,
               O.OBJ_PARNT,
               '/0' || SYS_CONNECT_BY_PATH (O.OBJ_CODE, '/') || '/'     OBJ_PATH,
               O.F_FILE_NAME
          FROM YS_V_OBJ_TREE O
         WHERE O.OBJ_TYP='FORM'
    CONNECT BY NOCYCLE PRIOR O.OBJ_CODE = O.OBJ_PARNT AND  O.OBJ_TYP='FORM'
    START WITH o.obj_parnt = '0' AND  O.OBJ_TYP='FORM';


