        IF UPDATING('USR_FILL_DOC_PRV') THEN UPDATE S_FLD_PRV_FXD_USR SET UP_DATE=SYSDATE, FLD_VAL=:NEW.USR_FILL_DOC_PRV WHERE U_ID=:NEW.U_ID AND FLD_NM='USR_FILL_DOC_PRV'; END IF; 
        IF UPDATING('USR_SHW_MSG_B4SAVE') THEN UPDATE S_FLD_PRV_FXD_USR SET UP_DATE=SYSDATE, FLD_VAL=:NEW.USR_SHW_MSG_B4SAVE WHERE U_ID=:NEW.U_ID AND FLD_NM='USR_SHW_MSG_B4SAVE'; END IF;
                                                               
                                               EXCEPTION WHEN OTHERS THEN
                                                    NULL;
                                               END;
            
                                            ELSIF DELETING THEN
      
                                               BEGIN
                                                  DELETE FROM S_FLD_PRV_FXD_USR
                                                  WHERE U_ID=:OLD.U_ID; 
                                               EXCEPTION WHEN OTHERS THEN
                                                    NULL;
                                               END;
       
                                            END IF;                                                                                         

                                        END;
/


