--
-- RAISE_NTFCTION_APPRV_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.RAISE_NTFCTION_APPRV_TRG
       AFTER INSERT OR UPDATE OF APPRVD
       ON IAS20261.S_APPRVD_MOV        
       FOR EACH ROW
BEGIN
       
       YS_MOBILE_APPRVD_PKG.RAISE_NTFCTION_APPRV_PRC ( P_DOC_TYP   => NVL(:OLD.DOC_TYP,:NEW.DOC_TYP),
                                                      P_DOC_SRL   => NVL(:OLD.DOC_SER,:NEW.DOC_SER),
                                                      P_LVL_NO    => NVL(:OLD.LVL_NO,:NEW.LVL_NO),
                                                      P_APPRVD    => NVL(:OLD.APPRVD,:NEW.APPRVD),
                                                      P_LNG_NO    => NVL(IAS_PRMTR_PKG.GETPVAL(P_PRMTR =>'LANG_NO'),2),
                                                      P_INSERTING => INSERTING);
      
EXCEPTION WHEN OTHERS THEN
   NULL;       
END RAISE_NTFCTION_APPRV_TRG;
/


--
-- SND_SMS_MAIL_APPRV_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SND_SMS_MAIL_APPRV_TRG
       AFTER INSERT OR UPDATE OF APPRVD
       ON IAS20261.S_APPRVD_MOV        
       FOR EACH ROW
BEGIN
       
      
       IAS_SMS_MAIL_PKG.SND_APPRV_PRC( P_DOC_TYP    =>NVL(:OLD.DOC_TYP,:NEW.DOC_TYP),                       
                                       P_DOC_SRL    =>NVL(:OLD.DOC_SER,:NEW.DOC_SER),
                                       P_LVL_NO     =>NVL(:OLD.LVL_NO,:NEW.LVL_NO),
                                       P_DOC_NO     =>NVL(:OLD.DOC_NO,:NEW.DOC_NO),
                                       P_APPRVD_OLD =>:OLD.APPRVD,
                                       P_APPRVD_NEW =>:NEW.APPRVD,
                                       P_INSERTING  => INSERTING,
                                       P_CMP_NO     =>NVL(:OLD.CMP_NO,:NEW.CMP_NO),
                                       P_BRN_NO     =>NVL(:OLD.BRN_NO,:NEW.BRN_NO),
                                       P_BRN_USR    =>NVL(:OLD.BRN_USR,:OLD.BRN_USR),
                                       P_BRN_YEAR   =>NVL(:NEW.BRN_YEAR,:NEW.BRN_YEAR));

 

EXCEPTION WHEN OTHERS THEN
   NULL;       
END SND_SMS_MAIL_APPRV_TRG;
/


--
-- SQ_GLS_BNK_IDNTF_DTL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SQ_GLS_BNK_IDNTF_DTL_TRG BEFORE INSERT
				ON IAS20261.GLS_BNK_IDNTF_DTL FOR EACH ROW
BEGIN
                     IF :NEW.DOC_D_SQ IS NULL THEN    
                        :NEW.DOC_D_SQ  := IAS_DOC_SEQ_GL.Nextval; 
                     END IF;				 
				EXCEPTION 
				   WHEN OTHERS THEN
				        RAISE_APPLICATION_ERROR(-20401,'Err. When Get Srl/Sequence.');   
				END;
/


--
-- SRL_GLS_ADVNC_MST_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SRL_GLS_ADVNC_MST_TRG BEFORE INSERT
				ON IAS20261.GLS_ADVNC_EXPNS_RVNU_MST FOR EACH ROW
BEGIN
				     
				 IF :NEW.DOC_M_SQ IS NULL THEN    
				    :NEW.DOC_M_SQ  := IAS_DOC_SEQ_GL.Nextval; 
				 END IF;
				
				                      
				 IF :NEW.DOC_SRL IS NULL THEN 
				     :NEW.DOC_SRL :=:NEW.BRN_YEAR||Lpad(:NEW.Brn_No,6,'0')||Lpad(:NEW.DOC_TYP,5,'0')||:NEW.DOC_NO;
				 END IF;
				 
				EXCEPTION 
				   WHEN OTHERS THEN
				        RAISE_APPLICATION_ERROR(-20401,'Err. When Get Srl/Sequence.');   
				END;
/


