 USE_QTN_PRM_IN_CSS_SYS_FLG, NO_OF_DAYS, FLD_DAY1, FLD_DAY2, FLD_DAY3, 
 FLD_DAY4, FLD_DAY5, FLD_DAY6, FLD_DAY7, I_CODE, 
 ITM_UNT, P_SIZE, I_PRICE, RCRD_NO, BARCODE, 
 F_QTY, T_QTY, F_AMT, T_AMT, DISC_TYPE, 
 DISC_AMT_PER, QT_I_CODE, FREE_QTY, QT_ITM_UNT, QT_QTY, 
 W_CODE, WHG_CODE, CNTRY_NO, PROV_NO, CITY_NO, 
 R_CODE, CARD_AMT, COMP_QTY, CMP_NO, BRN_NO, 
 BRN_YEAR, BRN_USR, UP_CNT, EXPIRE_DATE, BATCH_NO, 
 C_CODE, C_GROUP_CODE, C_CLASS, C_DEGREE, G_CODE, 
 MNG_CODE, SUBG_CODE, ASSISTANT_NO, DETAIL_NO, GROUP_NO, 
 ITEM_TYPE, GRP_CLASS_CODE, PRM_GRP_NO, BANK_NO, MAX_QT_QTY_DOC)
BEQUEATH DEFINER
AS 
SELECT M.Quot_No,
                  M.Quot_Ser,
                  M.F_DATE,
                  M.T_DATE,
                  M.Qt_Prm_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_TYP'
                          AND Flg_Value = m.Qt_Prm_Type)        Prm_Typ_Nm,
                  M.Qt_Prm_Method,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE    Flg_Code = Decode (M.Qt_Prm_Type,3,'QT_PRM_METHOD_TOT_BILL','QT_PRM_METHOD')
                          AND Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          --- AND Flg_Value <> 9
                          AND Flg_Value = M.Qt_Prm_Method)      Mthd_Nm,
                  M.Qt_Prm_Wc_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_WC_TYP'
                          AND Flg_Value = M.Qt_Prm_Wc_Type)     Qt_Prm_Wc_Type_NM,
                  M.Qt_Prm_Cst_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_CST_TYP'
                          AND Flg_Value = M.Qt_Prm_Cst_Type)    Qt_Prm_Cst_Type_NM,
                  M.A_Desc,
                  M.QUOT_CUR,
                  M.Rsn_Txt,
                  M.USE_QTN_PRM_IN_SHO_SYS_FLG,
                  M.USE_QTN_PRM_IN_RMS_SYS_FLG,
                  M.USE_QTN_PRM_IN_POS_SYS_FLG,
                  M.USE_QTN_PRM_IN_IAS_SYS_FLG,
                  M.USE_QTN_PRM_IN_DTS_SYS_FLG,
                  M.USE_QTN_PRM_IN_CSS_SYS_FLG,
                  M.NO_OF_DAYS,
                  M.FLD_DAY1,
                  M.FLD_DAY2,
                  M.FLD_DAY3,
                  M.FLD_DAY4,
                  M.FLD_DAY5,
                  M.FLD_DAY6,
                  M.FLD_DAY7,
                  D.I_Code,
                  D.Itm_Unt,
                  D.P_Size,
                  D.I_Price,
                  D.Rcrd_No,
                  D.Barcode,
                  D.F_Qty,
                  D.T_Qty,
                  D.F_Amt,
                  D.T_Amt,
                  D.Disc_Type,
                  D.Disc_Amt_Per,
                  D.Qt_I_Code,
                  D.Free_Qty,
                  D.Qt_Itm_Unt,
                  D.Qt_Qty,
                  D.W_Code,
                  D.Whg_Code,
                  D.Cntry_No,
                  D.Prov_No,
                  D.City_No,
                  D.R_Code,
                  D.Card_Amt,
                  D.Comp_Qty,
                  D.Cmp_No,
                  D.Brn_No,
                  D.Brn_Year,
                  D.Brn_Usr,
                  D.Up_Cnt,
                  D.Expire_Date,
                  D.Batch_No,
                  D.C_Code,
                  D.C_Group_Code,
                  D.C_Class,
                  D.C_Degree,
                  D.G_Code,
                  D.Mng_Code,
                  D.Subg_Code,
                  D.Assistant_No,
                  D.Detail_No,
                  D.Group_No,
                  D.Item_Type,
                  D.Grp_Class_Code,
                  D.Prm_Grp_No,
                  D.Bank_No,
                  D.Max_Qt_Qty_Doc
             FROM Ias_Qut_Prm_Mst M, Ias_Qut_Prm_Dtl D
            WHERE     M.Quot_Ser = D.Quot_Ser
                  AND D.Prm_grp_no IS NULL
                  AND TO_DATE (YS_GEN_PKG.GET_CURDATE, 'DD/MM/RRRR') <=
                      TO_DATE (M.T_DATE, 'DD/MM/RRRR')
                  AND NVL (M.INACTIVE, 0) = 0
                  AND NVL (M.APPROVED, 0) = 1
           UNION ALL
           SELECT M.Quot_No,
                  M.Quot_Ser,
                  M.F_DATE,
                  M.T_DATE,
                  M.Qt_Prm_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_TYP'
                          AND Flg_Value = m.Qt_Prm_Type)        Prm_Typ_Nm,
                  M.Qt_Prm_Method,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Flg_Code = 'QT_PRM_METHOD'
                          AND Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          --- AND Flg_Value <> 9
                          AND Flg_Value = M.Qt_Prm_Method)      Mthd_Nm,
                  M.Qt_Prm_Wc_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_WC_TYP'
                          AND Flg_Value = M.Qt_Prm_Wc_Type)     Qt_Prm_Wc_Type_NM,
                  M.Qt_Prm_Cst_Type,
                  (SELECT Flg_Desc
                     FROM S_Flags
                    WHERE     Lang_No =
                              NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1)
                          AND Flg_Code = 'QT_PRM_CST_TYP'
                          AND Flg_Value = M.Qt_Prm_Cst_Type)    Qt_Prm_Cst_Type_NM,
                  M.A_Desc,
                  M.QUOT_CUR,
                  M.Rsn_Txt,
                  M.USE_QTN_PRM_IN_SHO_SYS_FLG,
                  M.USE_QTN_PRM_IN_RMS_SYS_FLG,
                  M.USE_QTN_PRM_IN_POS_SYS_FLG,
                  M.USE_QTN_PRM_IN_IAS_SYS_FLG,
                  M.USE_QTN_PRM_IN_DTS_SYS_FLG,
                  M.USE_QTN_PRM_IN_CSS_SYS_FLG,
                  M.NO_OF_DAYS,
                  M.FLD_DAY1,
                  M.FLD_DAY2,
                  M.FLD_DAY3,
                  M.FLD_DAY4,
                  M.FLD_DAY5,
                  M.FLD_DAY6,
                  M.FLD_DAY7,
                  G.I_Code,
                  G.Itm_Unt,
                  G.P_Size,
                  D.I_Price,
                  D.Rcrd_No,
                  D.Barcode,
                  D.F_Qty,
                  D.T_Qty,
                  D.F_Amt,
                  D.T_Amt,
                  D.Disc_Type,
                  D.Disc_Amt_Per,
                  D.Qt_I_Code,
                  D.Free_Qty,
                  D.Qt_Itm_Unt,
                  D.Qt_Qty,
                  D.W_Code,
                  D.Whg_Code,
                  D.Cntry_No,
                  D.Prov_No,
                  D.City_No,
                  D.R_Code,
                  D.Card_Amt,
                  D.Comp_Qty,
                  D.Cmp_No,
                  D.Brn_No,
                  D.Brn_Year,
                  D.Brn_Usr,
                  D.Up_Cnt,
                  D.Expire_Date,
                  D.Batch_No,
                  D.C_Code,
                  D.C_Group_Code,
                  D.C_Class,
                  D.C_Degree,
                  D.G_Code,
                  D.Mng_Code,
                  D.Subg_Code,
                  D.Assistant_No,
                  D.Detail_No,
                  D.Group_No,
                  D.Item_Type,
                  D.Grp_Class_Code,
                  D.Prm_Grp_No,
                  D.Bank_No,
                  D.Max_Qt_Qty_Doc
             FROM Ias_Qut_Prm_Mst M, Ias_Qut_Prm_Dtl D, Ias_Qut_Prm_Grp_Dtl G
            WHERE     M.Quot_Ser = D.Quot_Ser
                  AND D.Prm_grp_no = G.Prm_grp_no
                  AND TO_DATE (YS_GEN_PKG.GET_CURDATE, 'DD/MM/RRRR') <=TO_DATE (M.T_DATE, 'DD/MM/RRRR')
                  AND NVL (M.INACTIVE, 0) = 0
                  AND NVL (M.APPROVED, 0) = 1;

