--
-- BGT_V_TRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.BGT_V_TRNS
(DOC_TYP, BRN_NO, DOC_NO, DOC_SER, DOC_DATE, 
 A_CODE, CC_CODE, PJ_NO, ACTV_NO, A_CY, 
 PRD_NO, BDGT_PRD_TYPE, F_DATE, T_DATE, DOC_DESC, 
 AMT_L_ADD, AMT_F_ADD, AMT_L_DISC, AMT_F_DISC, DOC_NO_REF, 
 DOC_SER_REF)
BEQUEATH DEFINER
AS 
(SELECT 73 doc_typ,
           M.BRN_NO,
           m.doc_no,
           m.doc_ser,
           m.doc_date,
           d.a_code,
           d.cc_code,
           d.pj_no,
           d.actv_no,
           d.a_cy,
           d.prd_no,
           D.BDGT_PRD_TYPE,
           D.F_DATE,
           D.T_DATE,
           D.DOC_DESC,
           d.amt_l amt_l_add,
           d.amt_f amt_f_add,
           0 amt_l_disc,
           0 amt_f_disc,
           m.doc_no doc_no_ref,
           m.doc_ser doc_ser_ref
    FROM   ias_bdgt_blnc_dtl d,
           ias_bdgt_blnc_mst m
    WHERE  m.doc_ser = d.doc_ser
    UNION ALL
    SELECT 74 doc_typ,
           M.BRN_NO,
           m.doc_no,
           m.doc_ser,
           m.doc_date,
           d.a_code,
           d.cc_code,
           d.pj_no,
           d.actv_no,
           d.a_cy,
           d.prd_no,
           D.BDGT_PRD_TYPE,
           D.F_DATE,
           D.T_DATE,
           D.DOC_DESC,
           d.amt_l_add amt_l_add,
           d.amt_f_add amt_f_add,
           d.amt_l_disc amt_l_disc,
           d.amt_f_disc amt_f_disc,
           d.doc_no_ref,
           d.doc_ser_ref
    FROM   gls_edit_bdgt_blnc_dtl d,
           gls_edit_bdgt_blnc_mst m
    WHERE  m.doc_ser = d.doc_ser
    UNION
    SELECT 75 doc_typ,
           M.BRN_NO,
           m.doc_no,
           m.doc_ser,
           m.doc_date,
           m.a_code,
           m.cc_code,
           m.pj_no,
           m.actv_no,
           m.a_cy,
           m.prd_no,
           M.BDGT_PRD_TYPE,
           NULL,
           NULL,
           M.DOC_DESC,
           0 amt_l_add,
           0 amt_f_add,
           m.amt_l amt_l_disc,
           m.amt_f amt_f_disc,
           m.doc_no_ref,
           m.doc_ser_ref
    FROM   gls_mov_bdgt_dtl d,
           gls_mov_bdgt_mst m
    WHERE  m.doc_ser = d.doc_ser
    UNION
    SELECT 75 doc_typ,
           M.BRN_NO,
           m.doc_no,
           m.doc_ser,
           m.doc_date,
           m.a_code,
           d.cc_code,
           d.pj_no,
           d.actv_no,
           d.a_cy,
           d.prd_no,
           D.BDGT_PRD_TYPE,
           D.F_DATE,
           D.T_DATE,
           D.DOC_DESC,
           d.amt_l amt_l_add,
           d.amt_f amt_f_add,
           0 amt_l_disc,
           0 amt_f_disc,
           d.doc_no_ref,
           d.doc_ser_ref
    FROM   gls_mov_bdgt_dtl d,
           gls_mov_bdgt_mst m
    WHERE  m.doc_ser = d.doc_ser);


--
-- GLS_BILL_ADVNC_VIEW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_BILL_ADVNC_VIEW
(DOC_TYP, BILL_DOC_TYP, DOC_JV_TYP, DOC_NO, DOC_SRL, 
 DOC_DATE, RCRD_NO, DOC_SQ, CC_CODE, PJ_NO, 
 ACTV_NO, I_CODE, I_NM, I_TYP, ITM_UNT, 
 P_SIZE, TAX_NO, CLC_TYP_NO, AGNCY_NO, I_QTY, 
 AC_CODE, CUR_CODE, CUR_RATE, TAX_PRCNT, AMT_L, 
 AMT_F, TAX_AMT_F, TAX_AMT_L, REF_NO, EXTERNAL_POST, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, DR_CR_FLG)
BEQUEATH DEFINER
AS 
SELECT DOC_TYP,
          BILL_DOC_TYP,
          DOC_JV_TYP,
          DOC_NO,
          DOC_SRL,
          DOC_DATE,
          RCRD_NO,
          DOC_SQ,
          CC_CODE,
          PJ_NO,
          ACTV_NO,
          I_CODE,
          NULL I_NM,
          I_TYP,
          ITM_UNT,
          P_SIZE,
          TAX_NO,
          CLC_TYP_NO,
          AGNCY_NO,
          I_QTY,
          AC_CODE,
          CUR_CODE,
          CUR_RATE,
          TAX_PRCNT,
          DECODE (YS_GEN_PKG.GET_LOCAL_CUR, CUR_CODE, AMT, AMT * CUR_RATE)
             AMT_L,
          DECODE (YS_GEN_PKG.GET_LOCAL_CUR, CUR_CODE, 0, AMT) AMT_F,
          TAX_AMT_F,
          TAX_AMT_L,
          REF_NO,
          EXTERNAL_POST,
          CMP_NO,
          BRN_NO,
          BRN_YEAR,
          BRN_USR,
          DR_CR_FLG
     FROM (SELECT DOC_TYPE DOC_TYP,
                  BILL_DOC_TYPE BILL_DOC_TYP,
                  DOC_JV_TYPE DOC_JV_TYP,
                  DOC_NO,
                  DOC_SER DOC_SRL,
                  DOC_DATE,
                  TAX_NO,
                  CLC_TYP_NO,
                  AGNCY_NO,
                  I_CODE,
                  NULL I_NM,
                  NULL I_TYP,
                  ITM_UNT,
                  P_SIZE,
                  A_CODE AC_CODE,
                  A_CY CUR_CODE,
                  AC_RATE CUR_RATE,
                  CC_CODE,
                  PJ_NO,
                  ACTV_NO,
                  RCRD_NO,
                  DOC_SEQUENCE DOC_SQ,
                  REF_NO,
                  EXTERNAL_POST,
                  CMP_NO,
                  BRN_NO,
                  BRN_YEAR,
                  BRN_USR,
                  I_QTY,
                  DR_CR_FLG,
                  TAX_PRCNT,
                  NVL (I_PRICE, 0) AMT,
                  NVL (TAX_AMT, 0) TAX_AMT_F,
                  NVL (TAX_AMT_L, 0) TAX_AMT_L
             FROM GNR_RQ_TAX_ITM_MOVMNT M
            WHERE DOC_TYPE IN (53, 143)
           UNION ALL
           SELECT DOC_TYPE,
                  BILL_DOC_TYPE,
                  DOC_JV_TYPE,
                  DOC_NO,
                  DOC_SER,
                  DOC_DATE,
                  TAX_NO,
                  CLC_TYP_NO,
                  AGNCY_NO,
                  TO_CHAR (INPT_CODE) I_CODE,
                  NULL I_NM,
                  TO_CHAR (INPT_TYP) I_TYP,
                  NULL ITM_UNT,
                  NULL P_SIZE,
                  A_CODE,
                  A_CY,
                  AC_RATE,
                  CC_CODE,
                  PJ_NO,
                  ACTV_NO,
                  RCRD_NO,
                  DOC_SEQUENCE,
                  REF_NO,
                  EXTERNAL_POST,
                  CMP_NO,
                  BRN_NO,
                  BRN_YEAR,
                  BRN_USR,
                  NULL I_QTY,
                  DR_CR_FLG,
                  TAX_PRCNT,
                  NVL (INPT_AMT, 0) I_PRICE,
                  NVL (TAX_AMT, 0) TAX_AMT,
                  NVL (TAX_AMT_L, 0) TAX_AMT_L
             FROM GNR_RQ_TAX_INPT_MOVMNT M
            WHERE DOC_TYPE IN (500, 507, 300))
    WHERE 1 = 1;


--
-- GLS_V_ACCNT_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL
(AC_CODE, AC_CODE_DTL, AC_CODE_DTL_L_NM, AC_CODE_DTL_F_NM, AC_DTL_TYP, 
 AC_DTL_TYP_DTL, GRP_CONN_CODE, GRP_CODE, CONN_BRN_NO, INACTV, 
 INACTV_RSON, INACTV_DATE)
BEQUEATH DEFINER
AS 
(SELECT D.ac_code, D.ac_code_dtl,D.ac_code_dtl_L_nm,D.ac_code_dtl_F_nm,  Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.Ac_code) AC_DTL_TYP , 1,M.GRP_CODE GRP_CONN_CODE,D.GRP_CODE,CONN_BRN_NO ,INACTV,INACTV_RSON,INACTV_DATE
   FROM   GlS_ACCNT_DTL_GRPS M,GlS_ACCNT_DTL D 
   WHERE  m.GRP_AC_code = D.AC_code
     AND  Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.AC_code) IN (5,6) 
     AND  M.ac_dtl_typ_DTL=1
   UNION ALL 
   SELECT  D.AC_CODE, D.DCTR_NO,D.DCTR_L_NM,D.DCTR_F_NM, Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.Ac_code) AC_DTL_TYP , 10,M.GRP_CODE GRP_CONN_CODE,NULL,NULL,INACTV,INACTV_RSON,INACTV_DATE
     FROM  GlS_ACCNT_DTL_GRPS M,HPS_DCTR D
    WHERE  M.GRP_AC_code = D.AC_code 
      AND  M.ac_dtl_typ_DTL=10  
      AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.AC_CODE) IN (5,6) 
      UNION ALL
   SELECT M.GRP_AC_CODE,
            D.AS_CODE,
            D.AS_A_NAME,
            D.AS_E_NAME,
            Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.GRP_Ac_code)     AC_DTL_TYP,
            90,
            M.GRP_CODE GRP_CONN_CODE,
            NULL,
            NULL,
            CASE WHEN AS_ST = 5 THEN 1 ELSE 0 END INACTV,
            NULL INACTV_RSON,
            NULL INACTV_DATE
       FROM GlS_ACCNT_DTL_GRPS M, FAS_ASSETS_MST D
      WHERE      M.ac_dtl_typ_DTL = 90
            AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.GRP_AC_CODE) IN (5, 6));

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_CODE IS '129';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_CODE_DTL IS '1041 - C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_CODE_DTL_L_NM IS ' - C?? C???CE ';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_CODE_DTL_F_NM IS '1041 - C?C?? C?C??E?';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_DTL_TYP IS '3398 - ??? C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL.AC_DTL_TYP_DTL IS '3398 - ??? C???CE C?E?????';



--
-- GLS_V_ACCNT_DTL_CURR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL_CURR
(AC_CODE_DTL, AC_DTL_TYP, CUR_CODE, AC_CODE, DFLT, 
 INACTV, INACTV_RSON, INACTV_DATE, AC_DTL_TYP_DTL)
BEQUEATH DEFINER
AS 
(SELECT  D.ac_code_dtl, Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.Ac_code) AC_DTL_TYP,D.CUR_CODE, M.Ac_code,D.DFLT,D.INACTV, D.INACTV_RSON,D.INACTV_DATE,1
             FROM  GlS_ACCNT_DTL M,GlS_ACCNT_DTL_CURR D  
             WHERE M.AC_code_DTL = D.AC_code_DTL 
               and M.Ac_Dtl_typ = D.Ac_Dtl_typ
               AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.Ac_code) IN (5,6) 
           UNION ALL 
           SELECT   M.DCTR_NO,Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.A_code) AC_DTL_TYP,D.A_CY, D.A_code,D.DFLT,D.INACTIVE,NULL,NULL, 10
             FROM   HPS_DCTR M,ACCOUNT_CURR D 
            WHERE M.AC_code = D.A_code 
              AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.A_code) IN (5,6)
               UNION ALL
     SELECT M.AS_CODE,
            Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.A_code)     AC_DTL_TYP,
            D.A_CY,
            D.A_code,
            D.DFLT,
            D.INACTIVE,
            NULL,
            NULL,
            90
       FROM FAS_ASSETS_MST M, ACCOUNT_CURR D,GlS_ACCNT_DTL_GRPS G
      WHERE     D.A_code = G.GRP_AC_code
            AND G.AC_DTL_TYP_DTL = 90 
            AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (D.A_code) IN (5, 6));


--
-- GLS_V_ACCNT_DTL_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL_PRIV
(U_ID, AC_CODE_DTL, AC_DTL_TYP, CUR_CODE, AC_CODE, 
 ADD_FLAG, VIEW_FLAG, AC_DTL_TYP_DTL)
BEQUEATH DEFINER
AS 
(SELECT D.U_ID,
            D.ac_code_dtl,
            D.AC_DTL_TYP,
            D.CUR_CODE,
            M.AC_CODE,
            D.ADD_FLAG,
            D.VIEW_FLAG,
            1
       FROM GLS_ACCNT_DTL M,GLS_ACCNT_DTL_PRIV D
      WHERE M.AC_CODE_DTL = D.AC_CODE_DTL
        AND M.AC_DTL_TYP=D.AC_DTL_TYP
     UNION ALL
     SELECT D.U_ID,
            M.DCTR_NO,
            Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_code),
            C.A_CY,
            M.AC_CODE,
            D.ADD_FLAG,
            D.VIEW_FLAG,
            10
       FROM HPS_DCTR M, HPS_DCTR_PRV D, ACCOUNT_CURR C
      WHERE  M.DCTR_NO = D.DCTR_NO
        AND  M.AC_code = C.A_code
        AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_code) IN (5, 6)
        union all
         SELECT P.u_id,
            D.AS_CODE,  
            Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.GRP_AC_CODE),
            C.A_CY,
            M.GRP_AC_CODE,
            P.ADD_FLAG,
            P.VIEW_FLAG,
            90
       FROM GlS_ACCNT_DTL_GRPS M, FAS_ASSETS_MST D,ACCOUNT_CURR C,PRIV_ACC P
      WHERE      M.ac_dtl_typ_DTL = 90
            AND  M.GRP_AC_code = C.A_code
            AND  M.GRP_AC_CODE =P.A_CODE
            AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.GRP_AC_CODE) IN (5, 6));


