--
-- GLS_V_USR_ACCNT_DTL_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_USR_ACCNT_DTL_PRV
(U_ID, USR_NAME, AC_CODE_DTL, AC_CODE_DTL_NM, AC_DTL_TYP, 
 AC_DTL_TYP_NM, CUR_CODE, ADD_FLAG, VIEW_FLAG, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
                                                                    Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
                                                                    A.AC_CODE_DTL,
                                                                    Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.AC_CODE_DTL_L_NM, C.AC_CODE_DTL_F_NM),NVL (C.AC_CODE_DTL_F_NM, C.AC_CODE_DTL_L_NM)) AC_CODE_DTL_NM,
                                                                    A.AC_DTL_TYP,
                                                                    YS_GEN_PKG.GET_FLG_NM ('AC_DTL_TYP', A.AC_DTL_TYP, IAS_PRMTR_PKG.GETPVAL(P_PRMTR =>'LANG_NO')) AC_DTL_TYP_NM,          
                                                                    A.CUR_CODE,          
                                                                    A.Add_Flag,
                                                                    A.View_Flag,
                                                                    A.Ad_U_Id,
                                                                    A.Ad_Date,
                                                                    A.Up_U_Id,
                                                                    A.Up_Date,
                                                                    1 Rec_Src
                                                               FROM GLS_ACCNT_DTL_PRIV A, User_R B, GLS_ACCNT_DTL C
                                                              WHERE A.U_Id = B.U_Id
                                                                AND A.AC_CODE_DTL = C.AC_CODE_DTL
                                                                AND A.AC_DTL_TYP  = C.AC_DTL_TYP          
                                                             UNION
                                                             SELECT B.U_Id,
                                                                    Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
                                                                    C.AC_CODE_DTL,
                                                                    Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.AC_CODE_DTL_L_NM, C.AC_CODE_DTL_F_NM),NVL (C.AC_CODE_DTL_F_NM, C.AC_CODE_DTL_L_NM)) AC_CODE_DTL_NM,
                                                                    A.AC_DTL_TYP,
                                                                    YS_GEN_PKG.GET_FLG_NM ('AC_DTL_TYP', A.AC_DTL_TYP, IAS_PRMTR_PKG.GETPVAL(P_PRMTR =>'LANG_NO')) AC_DTL_TYP_NM,
                                                                    A.CUR_CODE,          
                                                                    0 Add_Flag,
                                                                    0 View_Flag,
                                                                    NULL Ad_U_Id,
                                                                    NULL Ad_Date,
                                                                    NULL Up_U_Id,
                                                                    NULL Up_Date,
                                                                    0 Rec_Src
                                                               FROM GLS_ACCNT_DTL_CURR A, User_R B, GLS_ACCNT_DTL C
                                                              WHERE A.AC_CODE_DTL = C.AC_CODE_DTL
                                                                AND A.AC_DTL_TYP  = C.AC_DTL_TYP
                                                                    AND NOT EXISTS
                                                                               (SELECT 1
                                                                                  FROM GLS_ACCNT_DTL_PRIV
                                                                                 WHERE AC_CODE_DTL = A.AC_CODE_DTL
                                                                                   AND AC_DTL_TYP  = A.AC_DTL_TYP
                                                                                   And CUR_CODE    = A.CUR_CODE
                                                                                   AND U_Id        =  B.U_Id
                                                                                   AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.AC_CODE_DTL IS '1041 - «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.AC_DTL_TYP IS '3398 - ‰Ê⁄ «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.CUR_CODE IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.GLS_V_USR_ACCNT_DTL_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- GNR_EMP_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_EMP_AI_VW
(BRN_NO, EMP_NO, EMP_L_NM, EMP_F_NM, EMP_STS_NM, 
 JOB_NM_NO_NM, MNG_NM_NO_NM, GRD_NO, GRD_NO_NM, EMPLYMNT_TYP_NM, 
 CRNT_STS_NM, NTNLTY_NO, NTNLTY_NM, GNDR_TYP_NM, MRTL_STS_NM, 
 RLGN_NM, LVL_NO_NM, CTZN_NO_NM, STRT_WRK_DATE, GRP_NO, 
 GRP_NO_NM, CUR_CODE, NTNL_ID, BRTH_AD_DATE, END_WRK_DATE, 
 PAY_MTHD, END_TST_PRD_DATE)
BEQUEATH DEFINER
AS 
SELECT M.BRN_NO,
          M.EMP_NO,
          M.EMP_L_NM,
          M.EMP_F_NM,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 7,
             P_COD_NO    => M.EMP_ST,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             EMP_STS_NM,
          --M.JOB_NM_NO,
          --YS_EMP_PKG.Get_Code_Nm(P_Cod_Typ=> 1 ,P_Cod_No=>EMP_JOB_NO,P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 1,
             P_COD_NO    => M.EMP_JOB_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             JOB_NM_NO_NM,
          --M.MNG_NM_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 31,
             P_COD_NO    => M.MNGRL_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             MNG_NM_NO_NM,
          M.GRD_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 3,
             P_COD_NO    => M.GRD_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             GRD_NO_NM,
          --M.EMPLYMNT_TYP,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 6,
             P_COD_NO    => M.EMPLYMNT_TYP,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             EMPLYMNT_TYP_NM,
          /*M.CLSS_NO,
          YS_EMP_PKG.GET_EMP_CODE_DTL_NM (
             P_CODE_TYP   => 9,
             P_CODE_NO    => M.CLSS_NO,
             P_LNG_DFLT   => YS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LNG_DFLT'))
             CLSS_NO_NM,*/
          --M.CRNT_ST CRNT_STS,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 10,
             P_COD_NO    => M.EMP_CRNT_ST,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             CRNT_STS_NM,
          M.NTNLTY_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 11,
             P_COD_NO    => M.NTNLTY_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             NTNLTY_NM,
          --M.GNDR_TYP,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 12,
             P_COD_NO    => M.GNDR,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             GNDR_TYP_NM,
          --M.SCL_ST Mrtl_sts,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 13,
             P_COD_NO    => M.SCL_ST,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             Mrtl_sts_NM,
          --M.RLGN_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 14,
             P_COD_NO    => M.RLGN_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             RLGN_NM,
          /*M.CTGRY_NO,
          YS_EMP_PKG.GET_EMP_CODE_DTL_NM (
             P_CODE_TYP   => 23,
             P_CODE_NO    => M.CTGRY_NO,
             P_LNG_DFLT   => YS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LNG_DFLT'))
             CTGRY_NO_NM,*/
          --M.LVL_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 34,
             P_COD_NO    => M.LVL_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             LVL_NO_NM,
          --M.CTZN_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 35,
             P_COD_NO    => M.CTZNSHP,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             CTZN_NO_NM,
          /*M.EMP_LNG_NO,
          YS_EMP_PKG.GET_EMP_CODE_DTL_NM (
             P_CODE_TYP   => 17,
             P_CODE_NO    => M.EMP_LNG_NO,
             P_LNG_DFLT   => YS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LNG_DFLT'))
             EMP_LNG_NO_NM,*/
          M.STRT_WRK_DATE,
          /*M.HRCHY_NO,
          YS_GNR_PKG.GET_HRCHY_NM (
             P_HRCHY_NO   => M.HRCHY_NO,
             P_UNT_NO     => M.UNT_NO,
             P_LNG_DFLT   => TO_NUMBER (
                               YS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LNG_DFLT')))
             HRCHY_NO_NM,*/
          M.GRP_NO,
          YS_EMP_PKG.Get_Code_Nm (
             P_COD_TYP   => 23,
             P_COD_NO    => M.GRP_NO,
             P_Lng_NO=>IAS_PRMTR_PKG.GetPval(p_prmtr =>'LANG_NO'))
             GRP_NO_NM,
          M.CUR_CODE,
          M.NTNLTY_NO NTNL_ID,
          M.BRTH_AD_DATE,
          M.LST_WRK_DATE END_WRK_DATE,
          M.PAY_MTHD,
          M.PRBTNRY_PRD_END_DATE END_TST_PRD_DATE
     FROM S_EMP M;


--
-- GNR_TAX_MOVMNT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_MOVMNT_VW
(DOC_TYPE, DOC_JV_TYPE, DOC_NO, DOC_SER, DOC_DATE, 
 TAX_AMT_L, DOC_AMT, TAX_NO, TAX_NO_NM, CLC_TYP_NO, 
 AGNCY_NO, AGNCY_NM, TAX_PRCNT, TAX_CODE, A_CY, 
 BRN_NO, CMP_NO)
BEQUEATH DEFINER
AS 
WITH TLNG AS (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1) LNG_NO FROM DUAL)
SELECT DOC_TYPE,
           DOC_JV_TYPE,
           DOC_NO,
           DOC_SER,
           DOC_DATE,
           TAX_AMT_L,
           DOC_AMT,
           TAX_NO,
           TAX_NO_NM,
           CLC_TYP_NO,
           AGNCY_NO,
           AGNCY_NM,
           TAX_PRCNT,
           TAX_CODE,
           A_CY,
           BRN_NO,
           CMP_NO
      FROM (SELECT DOC_TYPE,
                   DOC_JV_TYPE,
                   DOC_NO,
                   DOC_SER,
                   NVL(TAX_DUE_DATE,DOC_DATE) DOC_DATE,
                   (TAX_AMT_L * (NVL (I_QTY, 0) + (NVL(CLC_TAX_FREE_QTY_FLG,0)*NVL (FREE_QTY, 0)))* DR_CR_FLG) TAX_AMT_L,
                   (NVL (I_QTY, 0) * (NVL (I_PRICE, 0) - ABS(NVL (DISC_AMT, 0))) * DR_CR_FLG) DOC_AMT,
                   TAX_NO,
                   A_CY,
                   BRN_NO,
                   CMP_NO,
                   (SELECT YS_TAX_PKG.GET_TAX_NM (P_TAX_NO   => TAX_NO,
                                                  P_LNG_NO   => TLNG.LNG_NO)FROM DUAL) TAX_NO_NM,
                   CLC_TYP_NO,
                   AGNCY_NO,
                   (SELECT YS_TAX_PKG.GET_TAX_AGNCY_NM(P_TAX_NO     => TAX_NO,
                                                       P_AGNCY_NO   => AGNCY_NO,
                                                       P_LNG_NO     => TLNG.LNG_NO) FROM DUAL) AGNCY_NM,
                   TAX_PRCNT,
                   NVL(ITM_VAT_CAT_CODE,(SELECT GNR_TAX_AMT_PKG.GET_ITM_VAT_CAT_CODE_FUN(P_TAX_NO  => TAX_NO,
                                                                                         P_I_CODE  => I_CODE) FROM DUAL)) TAX_CODE
              FROM GNR_TAX_ITM_MOVMNT,TLNG
            UNION ALL
            SELECT DOC_TYPE,
                   DOC_JV_TYPE,
                   DOC_NO,
                   DOC_SER,
                   DOC_DATE DOC_DATE,
                   (NVL(TAX_AMT_L,0) * DR_CR_FLG) TAX_AMT_L,
                   CASE WHEN DOC_TYPE <= 3 THEN ((NVL(INPT_AMT,0)-NVL(TAX_AMT_L,0)) * DR_CR_FLG) 
                        ELSE (NVL(INPT_AMT,0) * DR_CR_FLG)
                        END  DOC_AMT,
                   TAX_NO,
                   A_CY,
                   BRN_NO,
                   CMP_NO,
                   (SELECT YS_TAX_PKG.GET_TAX_NM ( P_TAX_NO   => TAX_NO,
                                                   P_LNG_NO   => TLNG.LNG_NO) FROM DUAL) TAX_NO_NM,
                   CLC_TYP_NO,
                   AGNCY_NO,
                   (SELECT YS_TAX_PKG.GET_TAX_AGNCY_NM(P_TAX_NO     => TAX_NO,
                                                       P_AGNCY_NO   => AGNCY_NO,
                                                       P_LNG_NO     => TLNG.LNG_NO) FROM DUAL) AGNCY_NM,
                   TAX_PRCNT,
                   INPT_VAT_CAT_CODE TAX_CODE
              FROM GNR_TAX_INPT_MOVMNT,TLNG
             /*WHERE NVL (TAX_AMT_L, 0) <> 0*/);


--
-- GNR_V_TAX_INPT_MOVMNT_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_V_TAX_INPT_MOVMNT_YR
(DOC_TYPE, BILL_DOC_TYPE, DOC_JV_TYPE, DOC_NO, DOC_SER, 
 DOC_DATE, TAX_NO, CLC_TYP_NO, AGNCY_NO, INPT_TYP, 
 INPT_CODE, A_CODE, A_CY, AC_RATE, INPT_AMT, 
 TAX_PRCNT, TAX_AMT, TAX_AMT_L, CC_CODE, PJ_NO, 
 ACTV_NO, REF_NO, RCRD_NO, DOC_SEQUENCE, EXTERNAL_POST, 
 DR_CR_FLG, BATCH_NO, ITEM_COD, VAT_CAT_CODE, TAX_PRD_NO, 
 TAX_TYP_CODE, INPT_VAT_CAT_CODE, INPT_VAT_EX_RSN_CODE, INPT_VAT_EX_RSN_TXT, INPT_BS_AMT, 
 INPT_BS_PRCNT, INPT_RSN_CODE, INPT_RSN_TXT, INPT_NET_AMT, TAX_CUR_CODE, 
 TAX_CUR_RATE, NET_TAX_AMT, TAX_DUE_DATE, TAX_HAS_JRNL, BILL_TAX_STATUS, 
 CPN_TYP, CPN_NO, CMP_NO, BRN_NO, BRN_YEAR, 
 BRN_USR, UP_CNT, PR_REP, AD_TRMNL_NM, UP_TRMNL_NM, 
 IN_OUT_TYP)
BEQUEATH DEFINER
AS 
SELECT DOC_TYPE,BILL_DOC_TYPE,DOC_JV_TYPE,DOC_NO,DOC_SER,DOC_DATE,TAX_NO,CLC_TYP_NO,AGNCY_NO,INPT_TYP,INPT_CODE,A_CODE,A_CY,AC_RATE,INPT_AMT,TAX_PRCNT,TAX_AMT,TAX_AMT_L,CC_CODE,PJ_NO,ACTV_NO,REF_NO,RCRD_NO,DOC_SEQUENCE,EXTERNAL_POST,DR_CR_FLG,BATCH_NO,ITEM_COD,VAT_CAT_CODE,TAX_PRD_NO,TAX_TYP_CODE,INPT_VAT_CAT_CODE,INPT_VAT_EX_RSN_CODE,INPT_VAT_EX_RSN_TXT,INPT_BS_AMT,INPT_BS_PRCNT,INPT_RSN_CODE,INPT_RSN_TXT,INPT_NET_AMT,TAX_CUR_CODE,TAX_CUR_RATE,NET_TAX_AMT,TAX_DUE_DATE,TAX_HAS_JRNL,BILL_TAX_STATUS,CPN_TYP,CPN_NO,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,UP_CNT,PR_REP,AD_TRMNL_NM,UP_TRMNL_NM,IN_OUT_TYP FROM GNR_TAX_INPT_MOVMNT;


--
-- GNR_V_TAX_ITM_MOVMNT_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_V_TAX_ITM_MOVMNT_YR
(DOC_TYPE, BILL_DOC_TYPE, DOC_JV_TYPE, DOC_NO, DOC_SER, 
 DOC_DATE, TAX_NO, CLC_TYP_NO, AGNCY_NO, I_CODE, 
 ITM_UNT, P_SIZE, I_PRICE, DISC_AMT, A_CODE, 
 A_CY, AC_RATE, TAX_PRCNT, TAX_AMT, W_CODE, 
 CC_CODE, PJ_NO, ACTV_NO, RCRD_NO, TAX_AMT_L, 
 I_QTY, FREE_QTY, REF_NO, STK_COST, STK_RATE, 
 DOC_SEQUENCE, CLC_TAX_FREE_QTY_FLG, EXTERNAL_POST, DR_CR_FLG, VAT_CAT_CODE, 
 TAX_PRD_NO, PRC_BS_QTY, PRC_DED_AMT, ITM_NET_PRICE, ITM_NET_QTY, 
 OTHR_AMT_ITM_DISC, OTHR_AMT_ITM, ITM_NET_AMT, TAX_CUR_CODE, TAX_CUR_RATE, 
 NET_TAX_AMT, ITM_VAT_CAT_CODE, ITM_VAT_EX_RSN_CODE, ITM_VAT_EX_RSN_TXT, TAX_DUE_DATE, 
 TAX_HAS_JRNL, BILL_TAX_STATUS, TAX_TYP_CODE, CMP_NO, BRN_NO, 
 BRN_YEAR, BRN_USR, UP_CNT, PR_REP, AD_TRMNL_NM, 
 UP_TRMNL_NM, IN_OUT_TYP)
BEQUEATH DEFINER
AS 
