--
-- IAS_V_AC_CC_LMT_HSTRY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AC_CC_LMT_HSTRY
(RCRD_SQ, COL_PK2, COL_PK3, AC_DTL_TYP, A_CODE, 
 AC_CODE_DTL, AC_CODE_DTL_SUB, A_CY, CC_CODE, PJ_NO, 
 ACTV_NO, MIN_AMT, MAX_AMT, MIN_TRNS_AMT, MAX_TRNS_AMT, 
 EXCEED_LMT, FCLTY_ST, FCLTY_AMT, MAX_LMT_PER, MAX_LMT_PSBL, 
 DALY_AMT, MNTHLY_AMT, ANULY_AMT, DR_CR, LMT_DESC, 
 EXTERNAL_POST, INACTIVE, OPR_TYPE, VAL_TYP, FORM_NO, 
 TAB_NM, AUD_U_ID, AUD_DATE, BRN_NO, CMP_NO, 
 BRN_YEAR, BRN_USR)
BEQUEATH DEFINER
AS 
SELECT M.COL_PK1 RCRD_SQ, M.COL_PK2,
           M.COL_PK3, TO_CHAR(D.AC_DTL_TYP) AC_DTL_TYP,
           D.A_CODE, D.AC_CODE_DTL,
           D.AC_CODE_DTL_SUB, D.A_CY,
           D.CC_CODE, D.PJ_NO,
           D.ACTV_NO,
           M.MIN_AMT,
           M.MAX_AMT, M.MIN_TRNS_AMT,
           M.MAX_TRNS_AMT, M.EXCEED_LMT,
           M.FCLTY_ST, M.FCLTY_AMT,
           M.MAX_LMT_PER, M.MAX_LMT_PSBL,
           M.DALY_AMT, M.MNTHLY_AMT,
           M.ANULY_AMT, M.DR_CR,
           M.LMT_DESC, M.EXTERNAL_POST,
           M.INACTIVE, 
           M.OPR_TYPE,
           M.VAL_TYP, M.FORM_NO,
           M.TAB_NM, M.AUD_U_ID,
           M.AUD_DATE, D.BRN_NO,
           M.CMP_NO, M.BRN_YEAR,
           M.BRN_USR
      FROM (  SELECT 'OLD' VAL_TYP
                     , OPR_TYPE
                     , M.FORM_NO
                     , M.TAB_NM
                     , M.COL_PK1
                     , M.COL_PK2
                     , M.COL_PK3
                     --------------------------------------------------------------------
                     , MAX(CASE WHEN M.COL_NM = 'MIN_AMT' THEN OLD_VAL END) AS MIN_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_AMT' THEN OLD_VAL END) AS MAX_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MIN_TRNS_AMT' THEN OLD_VAL END) AS MIN_TRNS_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_TRNS_AMT' THEN OLD_VAL END) AS MAX_TRNS_AMT
                     , MAX(CASE WHEN M.COL_NM = 'EXCEED_LMT' THEN OLD_VAL END) AS EXCEED_LMT
                     , MAX(CASE WHEN M.COL_NM = 'FCLTY_ST' THEN OLD_VAL END) AS FCLTY_ST
                     , MAX(CASE WHEN M.COL_NM = 'FCLTY_AMT' THEN OLD_VAL END) AS FCLTY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PER' THEN OLD_VAL END) AS MAX_LMT_PER
                     , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PSBL' THEN OLD_VAL END) AS MAX_LMT_PSBL
                     , MAX(CASE WHEN M.COL_NM = 'DALY_AMT' THEN OLD_VAL END) AS DALY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MNTHLY_AMT' THEN OLD_VAL END) AS MNTHLY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'ANULY_AMT' THEN OLD_VAL END) AS ANULY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'DR_CR' THEN OLD_VAL END) AS DR_CR
                     , MAX(CASE WHEN M.COL_NM = 'LMT_DESC' THEN OLD_VAL END) AS LMT_DESC
                     , MAX(CASE WHEN M.COL_NM = 'EXTERNAL_POST' THEN OLD_VAL END) AS EXTERNAL_POST
                     , MAX(CASE WHEN M.COL_NM = 'INACTIVE' THEN OLD_VAL END) AS INACTIVE
                     , M.AUD_U_ID,
                     M.AUD_DATE,
                     M.CMP_NO,
                     M.BRN_YEAR,
                     M.BRN_USR
                FROM IAS_AUD_HIST M
               WHERE 1 = 1 AND M.TAB_NM = 'IAS_AC_CC_LMT' AND M.OPR_TYPE = 1
            GROUP BY M.OPR_TYPE, M.FORM_NO,
                     M.TAB_NM, M.COL_PK1,
                     M.COL_PK2, M.COL_PK3,
                     M.AUD_U_ID, M.AUD_DATE,
                     M.CMP_NO, M.BRN_YEAR,
                     M.BRN_USR
            UNION ALL
              SELECT 'NEW' VAL_TYP
                     , OPR_TYPE
                     , M.FORM_NO
                     , M.TAB_NM
                     , M.COL_PK1
                     , M.COL_PK2
                     , M.COL_PK3
                     --------------------------------------------------------------------
                     , MAX(CASE WHEN M.COL_NM = 'MIN_AMT' THEN NEW_VAL END) AS MIN_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_AMT' THEN NEW_VAL END) AS MAX_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MIN_TRNS_AMT' THEN NEW_VAL END) AS MIN_TRNS_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_TRNS_AMT' THEN NEW_VAL END) AS MAX_TRNS_AMT
                     , MAX(CASE WHEN M.COL_NM = 'EXCEED_LMT' THEN NEW_VAL END) AS EXCEED_LMT
                     , MAX(CASE WHEN M.COL_NM = 'FCLTY_ST' THEN NEW_VAL END) AS FCLTY_ST
                     , MAX(CASE WHEN M.COL_NM = 'FCLTY_AMT' THEN NEW_VAL END) AS FCLTY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PER' THEN NEW_VAL END) AS MAX_LMT_PER
                     , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PSBL' THEN NEW_VAL END) AS MAX_LMT_PSBL
                     , MAX(CASE WHEN M.COL_NM = 'DALY_AMT' THEN NEW_VAL END) AS DALY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'MNTHLY_AMT' THEN NEW_VAL END) AS MNTHLY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'ANULY_AMT' THEN NEW_VAL END) AS ANULY_AMT
                     , MAX(CASE WHEN M.COL_NM = 'DR_CR' THEN NEW_VAL END) AS DR_CR
                     , MAX(CASE WHEN M.COL_NM = 'LMT_DESC' THEN NEW_VAL END) AS LMT_DESC
                     , MAX(CASE WHEN M.COL_NM = 'EXTERNAL_POST' THEN NEW_VAL END) AS EXTERNAL_POST
                     , MAX(CASE WHEN M.COL_NM = 'INACTIVE' THEN NEW_VAL END) AS INACTIVE
                     , M.AUD_U_ID,
                     M.AUD_DATE,
                     M.CMP_NO,
                     M.BRN_YEAR,
                     M.BRN_USR
                FROM IAS_AUD_HIST M
               WHERE 1 = 1 AND M.TAB_NM = 'IAS_AC_CC_LMT' AND M.OPR_TYPE = 1
            GROUP BY M.OPR_TYPE, M.FORM_NO,
                     M.TAB_NM, M.COL_PK1,
                     M.COL_PK2, M.COL_PK3,
                     M.AUD_U_ID, M.AUD_DATE,
                     M.CMP_NO, M.BRN_YEAR,
                     M.BRN_USR) M,
           IAS_AC_CC_LMT  D
     WHERE M.COL_PK1 = D.RCRD_SQ AND M.TAB_NM = 'IAS_AC_CC_LMT'
    UNION ALL
      SELECT M.COL_PK1
             , M.COL_PK2
             , M.COL_PK3
             , MAX(CASE WHEN M.COL_NM = 'AC_DTL_TYP' THEN OLD_VAL END) AS AC_DTL_TYP
             , MAX(CASE WHEN M.COL_NM = 'A_CODE' THEN OLD_VAL END) AS A_CODE
             , MAX(CASE WHEN M.COL_NM = 'AC_CODE_DTL' THEN OLD_VAL END) AS AC_CODE_DTL
             , MAX(CASE WHEN M.COL_NM = 'AC_CODE_DTL_SUB' THEN OLD_VAL END) AS AC_CODE_DTL_SUB
             , MAX(CASE WHEN M.COL_NM = 'A_CY' THEN OLD_VAL END) AS A_CY
             , MAX(CASE WHEN M.COL_NM = 'CC_CODE' THEN OLD_VAL END) AS CC_CODE
             , MAX(CASE WHEN M.COL_NM = 'PJ_NO' THEN OLD_VAL END) AS PJ_NO
             , MAX(CASE WHEN M.COL_NM = 'ACTV_NO' THEN OLD_VAL END) AS ACTV_NO
             --------------------------------------------------------------------
             , MAX(CASE WHEN M.COL_NM = 'MIN_AMT' THEN OLD_VAL END) AS MIN_AMT
             , MAX(CASE WHEN M.COL_NM = 'MAX_AMT' THEN OLD_VAL END) AS MAX_AMT
             , MAX(CASE WHEN M.COL_NM = 'MIN_TRNS_AMT' THEN OLD_VAL END) AS MIN_TRNS_AMT
             , MAX(CASE WHEN M.COL_NM = 'MAX_TRNS_AMT' THEN OLD_VAL END) AS MAX_TRNS_AMT
             , MAX(CASE WHEN M.COL_NM = 'EXCEED_LMT' THEN OLD_VAL END) AS EXCEED_LMT
             , MAX(CASE WHEN M.COL_NM = 'FCLTY_ST' THEN OLD_VAL END) AS FCLTY_ST
             , MAX(CASE WHEN M.COL_NM = 'FCLTY_AMT' THEN OLD_VAL END) AS FCLTY_AMT
             , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PER' THEN OLD_VAL END) AS MAX_LMT_PER
             , MAX(CASE WHEN M.COL_NM = 'MAX_LMT_PSBL' THEN OLD_VAL END) AS MAX_LMT_PSBL
             , MAX(CASE WHEN M.COL_NM = 'DALY_AMT' THEN OLD_VAL END) AS DALY_AMT
             , MAX(CASE WHEN M.COL_NM = 'MNTHLY_AMT' THEN OLD_VAL END) AS MNTHLY_AMT
             , MAX(CASE WHEN M.COL_NM = 'ANULY_AMT' THEN OLD_VAL END) AS ANULY_AMT
             , MAX(CASE WHEN M.COL_NM = 'DR_CR' THEN OLD_VAL END) AS DR_CR
             , MAX(CASE WHEN M.COL_NM = 'LMT_DESC' THEN OLD_VAL END) AS LMT_DESC
             , MAX(CASE WHEN M.COL_NM = 'EXTERNAL_POST' THEN OLD_VAL END) AS EXTERNAL_POST
             , MAX(CASE WHEN M.COL_NM = 'INACTIVE' THEN OLD_VAL END) AS INACTIVE
             , M.OPR_TYPE,
             'DEL' VAL_TYP,
             M.FORM_NO,
             M.TAB_NM,
             M.AUD_U_ID,
             MAX(M.AUD_DATE) AUD_DATE,
             M.BRN_NO,
             M.CMP_NO,
             M.BRN_YEAR,
             M.BRN_USR
        FROM IAS_AUD_HIST M
       WHERE 1 = 1
         AND M.TAB_NM = 'IAS_AC_CC_LMT'
         AND M.OPR_TYPE = 2
         AND COL_PK1 IS NOT NULL
    GROUP BY M.COL_PK1, M.COL_PK2,
             M.COL_PK3, M.OPR_TYPE,
             M.FORM_NO, M.TAB_NM,
             M.AUD_U_ID, M.BRN_NO,
             M.CMP_NO, M.BRN_YEAR,
             M.BRN_USR;


--
-- IAS_V_BDGT_BLNC_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_BDGT_BLNC_DTL
(BDGT_TYPE, BDGT_PRD_TYPE, DOC_NO, DOC_SER, A_CODE, 
 AC_CODE_DTL, AC_DTL_TYP, A_CY, CC_CODE, PJ_NO, 
 ACTV_NO, AC_RATE, CMP_NO, BRN_NO, BRN_YEAR, 
 BRN_USR, AMT_L1, AMT_L2, AMT_L3, AMT_L4, 
 AMT_L5, AMT_L6, AMT_L7, AMT_L8, AMT_L9, 
 AMT_L10, AMT_L11, AMT_L12)
BEQUEATH DEFINER
AS 
SELECT BDGT_TYPE,
             BDGT_PRD_TYPE,
             DOC_NO,
             DOC_SER,
             A_CODE,
             AC_CODE_DTL,
             AC_DTL_TYP,
             A_CY,
             CC_CODE,
             PJ_NO,
             ACTV_NO,
             AC_RATE,
             CMP_NO,
             BRN_NO,
             BRN_YEAR,
             BRN_USR,
             SUM(DECODE(PRD_NO, 1, AMT_L, 0)) AMT_L1,
             SUM(DECODE(PRD_NO, 2, AMT_L, 0)) AMT_L2,
             SUM(DECODE(PRD_NO, 3, AMT_L, 0)) AMT_L3,
             SUM(DECODE(PRD_NO, 4, AMT_L, 0)) AMT_L4,
             SUM(DECODE(PRD_NO, 5, AMT_L, 0)) AMT_L5,
             SUM(DECODE(PRD_NO, 6, AMT_L, 0)) AMT_L6,
             SUM(DECODE(PRD_NO, 7, AMT_L, 0)) AMT_L7,
             SUM(DECODE(PRD_NO, 8, AMT_L, 0)) AMT_L8,
             SUM(DECODE(PRD_NO, 9, AMT_L, 0)) AMT_L9,
             SUM(DECODE(PRD_NO, 10, AMT_L, 0)) AMT_L10,
             SUM(DECODE(PRD_NO, 11, AMT_L, 0)) AMT_L11,
             SUM(DECODE(PRD_NO, 12, AMT_L, 0)) AMT_L12
        FROM IAS_BDGT_BLNC_DTL
    GROUP BY BDGT_TYPE, BDGT_PRD_TYPE,
             DOC_NO, DOC_SER,
             A_CODE, AC_CODE_DTL,
             AC_DTL_TYP, A_CY,
             CC_CODE, PJ_NO,
             ACTV_NO, AC_RATE,
             CMP_NO, BRN_NO,
             BRN_YEAR, 
             BRN_USR;


