--
-- IAS_V_GL_CSHFLW_AC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_GL_CSHFLW_AC
(A_CODE, AC_DTL_TYP, RCRD_NO_DTL, DOC_NO, DOC_SER, 
 RCRD_NO, UP_CNT, PR_REP, AD_TRMNL_NM, UP_TRMNL_NM, 
 A_ANALYSIS)
BEQUEATH DEFINER
AS 
SELECT 
																						decode(i.a_code,null,a.a_code,i.a_code) a_code ,
																						 decode(i.AC_DTL_TYP,null,a.AC_DTL_TYP,i.AC_DTL_TYP) AC_DTL_TYP,
																						 I.RCRD_NO_DTL, I.DOC_NO, 
																						   I.DOC_SER, I.RCRD_NO, I.UP_CNT, 
																						   I.PR_REP, I.AD_TRMNL_NM, I.UP_TRMNL_NM, 
																						   I.A_ANALYSIS
																						FROM IAS_GL_CSHFLW_AC i ,account a
																					  WHERE  nvl(a.a_analysis,0)= DECODE (i.a_analysis, NULL, nvl(a.a_analysis,0), i.a_analysis) 
                                             and  nvl(a.a_code,'0')= DECODE (i.a_code, NULL, nvl(a.a_code,'0'), i.a_code);


--
-- IAS_V_ITEM_DTL_TMP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITEM_DTL_TMP
(I_CODE, ITM_UNT)
BEQUEATH DEFINER
AS 
Select Distinct Ias_Itm_Mst.I_Code,Ias_Itm_Dtl.ITM_UNT From Ias_Itm_Mst,Ias_Itm_Dtl Where Ias_Itm_Mst.I_Code=Ias_Itm_Dtl.I_Code;


--
-- IAS_V_ITM_DIS_QUT_ONLINE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_DIS_QUT_ONLINE
(I_CODE, W_CODE, ITM_UNT, QUOT_CUR, QUT_PER, 
 QUT_AMT, SHO_NO)
BEQUEATH DEFINER
AS 
SELECT QD.I_CODE, QD.W_CODE,QD.ITM_UNT,QUOT_CUR , decode(DISC_TYPE,1,NVL (QD.DISC_AMT_PER, 0),0)QUT_per,
             decode(DISC_TYPE,2,NVL (QD.DISC_AMT_PER, 0),0)QUT_amt,SQ.SHO_NO 
             FROM Ias_Qut_Prm_Mst QM, Ias_Qut_Prm_Dtl QD,SHO_QUOT_PRM SQ 
             WHERE     
                  QM.Quot_Ser = QM.Quot_Ser
              AND SQ.Quot_Ser = QD.Quot_Ser
              AND SQ.Quot_Ser = QM.Quot_Ser
              AND QM.Qt_Prm_Type = 1
              AND QM.Qt_Prm_Method = 2
              AND IAS_GEN_PKG.GET_CURDATE BETWEEN Qm.F_DATE AND Qm.T_DATE
              AND NVL (QM.Inactive, 0) = 0 
              AND NVL (SQ.Inactive, 0) = 0 
               AND NVL(QM.APPROVED,0)=1 
              AND NVL(QM.USE_QTN_PRM_IN_SHO_SYS_FLG,0)=1;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_DIS_QUT_ONLINE.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_DIS_QUT_ONLINE.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_ITM_ONLINE_QT_PRM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_ONLINE_QT_PRM
(QUOT_NO, QUOT_SER, QUOT_CUR, F_DATE, T_DATE, 
 BILL_DOC_TYPE, I_CODE, ITM_UNT, I_PRICE)
BEQUEATH DEFINER
AS 
SELECT Ias_Qut_Prm_Mst.Quot_No,
           Ias_Qut_Prm_Mst.Quot_Ser,
           Ias_Qut_Prm_Mst.Quot_Cur,
           Ias_Qut_Prm_Mst.F_Date,
           Ias_Qut_Prm_Mst.T_Date,
           Ias_Qut_Prm_Mst.Bill_Doc_Type,
           Ias_Qut_Prm_Dtl.I_Code,
           Ias_Qut_Prm_Dtl.Itm_Unt,
           Ias_Qut_Prm_Dtl.I_Price
      FROM Ias_Qut_Prm_Mst, Ias_Qut_Prm_Dtl, Ias_Itm_Online
     WHERE     Ias_Qut_Prm_Mst.Quot_Ser = Ias_Qut_Prm_Dtl.Quot_Ser
           AND Ias_Qut_Prm_Dtl.I_Code = Ias_Itm_Online.I_Code
           AND Ias_Qut_Prm_Dtl.Itm_Unt = Ias_Itm_Online.Itm_Unt
           AND Ias_Qut_Prm_Mst.Qt_Prm_Type = 1
           AND Ias_Qut_Prm_Mst.Qt_Prm_Method = 1
           AND NVL (Ias_Qut_Prm_Mst.Inactive, 0) = 0
           AND IAS_GEN_PKG.GET_CURDATE BETWEEN Ias_Qut_Prm_Mst.F_DATE AND Ias_Qut_Prm_Mst.T_DATE
           AND NVL(Ias_Qut_Prm_Mst.USE_QTN_PRM_IN_SHO_SYS_FLG,0)=1;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_ONLINE_QT_PRM.I_CODE IS '176 - —ﬁ„ «·’‰›';

