--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_QUOT_PRM_CSS
(QUOT_NO, QUOT_SER, QUOT_RCRD_NO, I_CODE, W_CODE, 
 ITM_UNT, QT_PRM_METHOD, MTHD_NM, QT_PRM_TYPE, PRM_TYP_NM, 
 A_DESC, QUOT_CUR, RSN_TXT, P_SIZE, I_PRICE, 
 FREE_QTY, QT_QTY, QT_POINT_CNT, MAX_QT_QTY_DOC, COMP_QTY, 
 QT_ITM_UNT, PRM_GRP_NO, LEV_PRICE)
BEQUEATH DEFINER
AS 
SELECT T.Quot_No,
           T.Quot_Ser,
           T.Rcrd_No     Quot_Rcrd_No,
           t.I_Code,
           t.w_code,
           T.Itm_Unt,
           T.Qt_Prm_Method,
           t.Mthd_Nm,
           T.Qt_Prm_Type,
           t.Prm_Typ_Nm,
           A_Desc,
           QUOT_CUR,
           Rsn_Txt,
           P_Size,
           I_Price,
           Free_Qty,
           Qt_Qty,
           Qt_Point_Cnt,
           Max_Qt_Qty_Doc,
           Comp_Qty,
           Qt_Itm_Unt,
           Prm_Grp_No,
           Lev_Price
      FROM (SELECT M.Quot_No,
                   M.Quot_Ser,
                   D.I_Code,
                   D.Itm_Unt,
                   D.W_Code,
                   M.Qt_Prm_Type,
                   (SELECT Flg_Desc
                      FROM S_Flags
                     WHERE     Lang_No =
                               NVL (
                                   Ias_Prmtr_Pkg.Getpval (
                                       P_Prmtr   => 'LANG_DFLT'),
                                   1)
                           AND Flg_Code = 'QT_PRM_TYP'
                           AND Flg_Value <= 5
                           AND Flg_Value NOT IN (4, 5)
                           AND Flg_Value = m.Qt_Prm_Type)      Prm_Typ_Nm,
                   M.Qt_Prm_Method,
                   (SELECT Flg_Desc
                      FROM S_Flags
                     WHERE     Flg_Code = 'QT_PRM_METHOD'
                           AND Lang_No =
                               NVL (
                                   Ias_Prmtr_Pkg.Getpval (
                                       P_Prmtr   => 'LANG_DFLT'),
                                   1)
                           AND Flg_Value <> 9
                           AND Flg_Value = M.Qt_Prm_Method)    Mthd_Nm,
                   D.Rcrd_No,
                   M.A_Desc,
                   M.QUOT_CUR,
                   M.Rsn_Txt,
                   D.P_Size,
                   D.I_Price,
                   D.Free_Qty,
                   D.Qt_Qty,
                   D.Qt_Point_Cnt,
                   D.Max_Qt_Qty_Doc,
                   D.Comp_Qty,
                   D.Qt_Itm_Unt,
                   D.Prm_Grp_No,
                   D.Lev_Price
              FROM Ias_Qut_Prm_Mst M, Ias_Qut_Prm_Dtl D
             WHERE     M.Quot_Ser = D.Quot_Ser
                   AND D.I_Code IS NOT NULL
                   AND NVL (M.Inactive, 0) = 0
                   AND NVL (M.Use_Qtn_Prm_In_Css_Sys_Flg, 0) = 1
                   AND NVL (Qt_Prm_Method, 0) <> 5
                   AND NVL (M.Approved, 0) = 1
                   AND TO_CHAR (IAS_GEN_PKG.GET_CURDATE, 'DD/MM/YYYY') BETWEEN F_Date AND T_Date
            UNION ALL
            SELECT M.Quot_No,
                   M.Quot_Ser,
                   D.I_Code,
                   D.Itm_Unt,
                   D.W_Code,
                   M.Qt_Prm_Type,
                   (SELECT Flg_Desc
                      FROM S_Flags
                     WHERE     Lang_No = 1
                           AND Flg_Code = 'QT_PRM_TYP'
                           AND Flg_Value <= 5
                           AND Flg_Value NOT IN (4, 5)
                           AND Flg_Value = m.Qt_Prm_Type)      Prm_Typ_Nm,
                   M.Qt_Prm_Method,
                   (SELECT Flg_Desc
                      FROM S_Flags
                     WHERE     Flg_Code = 'QT_PRM_METHOD'
                           AND Lang_No = 1
                           AND Flg_Value <> 9
                           AND Flg_Value = M.Qt_Prm_Method)    Mthd_Nm,
                   D.Rcrd_No,
                   M.A_Desc,
                   M.QUOT_CUR,
                   M.Rsn_Txt,
                   D.P_Size,
                   D.I_Price,
                   D.Free_Qty,
                   D.Qt_Qty,
                   D.Qt_Point_Cnt,
                   D.Max_Qt_Qty_Doc,
                   D.Comp_Qty,
                   D.Qt_Itm_Unt,
                   D.Prm_Grp_No,
                   D.Lev_Price
              FROM Ias_Qut_Prm_Mst      M,
                   Ias_Qut_Prm_Dtl      D,
                   Ias_Qut_Prm_Sub_Dtl  S
             WHERE     M.Quot_Ser = D.Quot_Ser
                   AND D.Quot_Ser = S.Quot_Ser
                   AND D.I_Code IS NOT NULL
                   AND NVL (M.Inactive, 0) = 0
                   AND NVL (M.Approved, 0) = 1
                   AND TO_CHAR (IAS_GEN_PKG.GET_CURDATE, 'DD/MM/YYYY') BETWEEN F_Date AND T_Date
                   AND NVL (M.Use_Qtn_Prm_In_Css_Sys_Flg, 0) = 1
                   AND D.Rcrd_No = S.Rcrd_No
                   AND NVL (Qt_Prm_Method, 0) = 5) T,
           Ias_Itm_Mst  I
     WHERE T.I_Code = I.I_Code AND I.Use_Itm_In_Css_Sys_Flg = 1;

COMMENT ON COLUMN IAS20261.IAS_V_QUOT_PRM_CSS.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_QUOT_PRM_CSS.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_QUOT_PRM_CSS.A_DESC IS '146 - «·»Ì«‰';

COMMENT ON COLUMN IAS20261.IAS_V_QUOT_PRM_CSS.I_PRICE IS '230 - «·”⁄—';



--
-- IAS_V_USR_BRN_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_BRN_PRV
(U_ID, USR_NAME, BRN_NO, BRN_NM, ADD_FLAG, 
 VIEW_FLAG, FILL_FLAG, ADD_BNF_FLAG, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Brn_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Brn_Lname, C.Brn_Fname),Nvl (C.Brn_Fname, C.Brn_Lname)) Brn_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Fill_Flag,
          A.ADD_BNF_FLAG,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From S_Brn_Usr_Priv A, User_R B, S_Brn  C
    Where     A.U_Id = B.U_Id
          And A.Brn_No = C.Brn_No
          --And (Add_Flag = 1 Or View_Flag = 1)  
   Union
 Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Brn_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Brn_Fname, C.Brn_Lname),Nvl (C.Brn_Lname, C.Brn_Fname)) Brn_Nm,
          0 Add_Flag,
          0 View_Flag,
          0 Fill_Flag,
          0 ADD_BNF_FLAG,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, S_Brn C
    Where Not Exists
             (Select 1
                From S_Brn_Usr_Priv
               Where Brn_No = C.Brn_No And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_BRN_PRV.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.IAS_V_USR_BRN_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_BRN_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_BRN_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_PROJCT_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_PROJCT_PRV
(U_ID, USR_NAME, PJ_NO, PJ_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Pj_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Pj_A_Name, C.Pj_E_Name),Nvl (C.Pj_E_Name, C.Pj_A_Name)) Pj_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From Ias_Priv_Projects A, User_R B, Ias_Projects  C
    Where     A.U_Id = B.U_Id
          And A.Pj_No = C.Pj_No
          --And (Add_Flag = 1 Or View_Flag = 1)
          And Nvl(C.PJ_SUB,0) = 1  
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Pj_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Pj_A_Name, C.Pj_E_Name),Nvl (C.Pj_E_Name, C.Pj_A_Name)) Pj_Nm,
          0 Add_Flag,
          0 View_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, Ias_Projects C
    Where  Nvl(C.PJ_SUB,0) = 1  
     And Not Exists
             (Select 1
                From Ias_Priv_Projects
               Where Pj_No = C.Pj_No And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROJCT_PRV.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROJCT_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROJCT_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROJCT_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- INV_KIT_ITM_ALL_CMPNNT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_KIT_ITM_ALL_CMPNNT_VW
(I_CODE, I_NAME, ITM_UNT, I_QTY, DI_CODE, 
 DI_NAME, DITM_UNT, DI_QTY, ITM_MIN_QTY, ITM_MAX_QTY)
BEQUEATH DEFINER
AS 
SELECT IAS_ITM_MST.I_CODE I_CODE,
       NVL(NVL(SHRT_ITM_L_NM, SHRT_ITM_F_NM), NVL(I_NAME, I_E_NAME)) I_NAME,
       IAS_ITM_PKG.GET_ICODE_MIN_UNIT(IAS_ITM_MST.I_CODE) ITM_UNT,
       1 I_QTY,
       KIT_ITEMS.I_CODE DI_CODE,
       IAS_ITM_PKG.GET_ITM_NAME(KIT_ITEMS.I_CODE, 1) DI_NAME,
       KIT_ITEMS.ITM_UNT DITM_UNT,
       NVL(I_QTY, 0) DI_QTY,
       KIT_ITEMS.ITM_MIN_QTY,
       KIT_ITEMS.ITM_MAX_QTY
  FROM IAS_ITM_MST,
       (WITH
            RCRSV (KIT_ITEM_NO, I_CODE, ITM_UNT, P_SIZE, I_QTY, P_QTY, PER_COST_FROM_KIT_ITM, ITM_MIN_QTY, ITM_MAX_QTY, KIT_ITM)
            AS
                (SELECT KIT_ITEMS.KIT_ITEM_NO,
                        KIT_ITEMS.I_CODE,
                        KIT_ITEMS.ITM_UNT,
                        KIT_ITEMS.P_SIZE,
                        KIT_ITEMS.I_QTY,
                        KIT_ITEMS.P_QTY,
                        KIT_ITEMS.PER_COST_FROM_KIT_ITM,
                        KIT_ITEMS.ITM_MIN_QTY,
                        KIT_ITEMS.ITM_MAX_QTY,
                        NVL(IAS_ITM_MST.KIT_ITM, 0) KIT_ITM
                   FROM KIT_ITEMS, IAS_ITM_MST
                  WHERE IAS_ITM_MST.I_CODE = KIT_ITEMS.KIT_ITEM_NO
                 UNION ALL
                 SELECT RCRSV.I_CODE KIT_ITEM_NO,
                        KIT_ITEMS.I_CODE,
                        KIT_ITEMS.ITM_UNT,
                        KIT_ITEMS.P_SIZE,
                        (NVL(RCRSV.I_QTY,0) * NVL(RCRSV.P_SIZE,1) * NVL(KIT_ITEMS.I_QTY,0)) I_QTY,
                        ((NVL(RCRSV.I_QTY,0) * NVL(RCRSV.P_SIZE,1)) * (NVL(KIT_ITEMS.I_QTY,0) * NVL(KIT_ITEMS.P_SIZE,1))) P_QTY,
                        KIT_ITEMS.PER_COST_FROM_KIT_ITM,
                        KIT_ITEMS.ITM_MIN_QTY,
                        KIT_ITEMS.ITM_MAX_QTY,
                        NVL(IAS_ITM_MST.KIT_ITM, 0) KIT_ITM
                   FROM KIT_ITEMS, IAS_ITM_MST, RCRSV
                  WHERE KIT_ITEMS.KIT_ITEM_NO = RCRSV.I_CODE AND IAS_ITM_MST.I_CODE = KIT_ITEMS.KIT_ITEM_NO)
        SELECT *
          FROM RCRSV) KIT_ITEMS
 WHERE IAS_ITM_MST.I_CODE = KIT_ITEMS.KIT_ITEM_NO;

COMMENT ON COLUMN IAS20261.INV_KIT_ITM_ALL_CMPNNT_VW.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_KIT_ITM_ALL_CMPNNT_VW.I_QTY IS '222 - «·ﬂ„Ì…';



--
-- LOCTN_GEO_GPS_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.LOCTN_GEO_GPS_VW
(INPT_CODE, ROUTE_CODE, ORDR, LAT, LNG)
BEQUEATH DEFINER
AS 
SELECT 'R_CODE' INPT_CODE,
          R_CODE ROUTE_CODE,
          ORDR,
          FLD1 LAT,
          FLD2 LNG
     FROM REGIONS M, TABLE (DTS_MAP_API_PKG.SPLIT_KV (P_STR => NVL (M.RGN_GEO, '' || ',' || ''), P_DELIMITER => ';', P_SEPARATOR => ',')) D
    WHERE FLD1 IS NOT NULL AND FLD2 IS NOT NULL
   UNION ALL
   SELECT 'ROUTE_NO' INPT_CODE,
          ROUTE_NO ROUTE_CODE,
          ORDR,
          FLD1 LAT,
          FLD2 LNG
     FROM IAS_ROUTE_MST M, TABLE (DTS_MAP_API_PKG.SPLIT_KV (P_STR => NVL (M.RGN_GEO, '' || ',' || ''), P_DELIMITER => ';', P_SEPARATOR => ',')) D
    WHERE FLD1 IS NOT NULL AND FLD2 IS NOT NULL
   UNION ALL
   SELECT 'ROUTE_NO' INPT_CODE,
          ROUTE_NO ROUTE_CODE,
          ORDR,
          FLD1 LAT,
          FLD2 LNG
     FROM IAS_ROUTE_MST M, TABLE (DTS_MAP_API_PKG.SPLIT_KV (P_STR => NVL (M.RGN_GEO, '' || ',' || ''), P_DELIMITER => ';', P_SEPARATOR => ',')) D
    WHERE FLD1 IS NOT NULL AND FLD2 IS NOT NULL;


--
-- SHO_V_IAS_QUT_PRM_SUB_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL
(RCRD_NO, QUOT_NO, QUOT_SER, I_CODE, FREE_QTY, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, UP_CNT, 
 ITM_UNT, P_SIZE, SHO_SYS_TYP)
BEQUEATH DEFINER
AS 
SELECT M.RCRD_NO, M.QUOT_NO, M.QUOT_SER, 
   M.I_CODE, M.FREE_QTY, M.CMP_NO, 
   M.BRN_NO, M.BRN_YEAR, M.BRN_USR, 
   M.UP_CNT, M.ITM_UNT, M.P_SIZE,I.SHO_SYS_TYP
FROM IAS_QUT_PRM_SUB_DTL M ,IAS_ITM_ONLINE I,Sho_Quot_Prm S 
Where I.I_Code  = M.I_Code
  And I.Itm_Unt = M.Itm_Unt
  And S.Sho_No  = I.Sho_Sys_Typ
  and S.quot_ser= m.quot_ser
    And Exists (Select 1 From Ias_Qut_Prm_Mst  
      Where M.Quot_Ser=Ias_Qut_Prm_Mst.Quot_Ser 
       And  Nvl( Use_Qtn_Prm_In_Sho_Sys_Flg,0) = 1 
       And Nvl(Inactive,0)=0 
       And Nvl(Approved,0)=1);

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.CMP_NO IS '1583 - —ﬁ„ «·‘—ﬂ…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.BRN_YEAR IS '41 - «·”‰…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.BRN_USR IS '3300 - «·ÊÕœ… «·„Õ«”»Ì…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_SUB_DTL.UP_CNT IS '1969 - „—«  «· ⁄œÌ·';



--
-- S_V_EMP_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_EMP_PRV
(U_ID, USR_NAME, EMPNO_HRCHYNO, EMPNM_HRCHYNM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
			          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
			                  1, NVL (b.u_a_name, b.u_e_name),
			                  NVL (b.u_e_name, b.u_a_name)
			                 ) usr_nm,
			          a.empno_hrchyno,
			          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
			                  1, NVL (c.emp_l_nm, c.emp_f_nm),
			                  NVL (c.emp_f_nm, c.emp_l_nm)
			                 ) empnm_hrchynm,
			          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
			          1 rec_src
			     FROM s_emp_prv a, user_r b, s_emp c
			    WHERE a.u_id = b.u_id
			      AND a.empno_hrchyno = c.emp_no
			      AND a.emp_prv_typ = 1
			      AND (add_flag = 1 OR view_flag = 1)
			   UNION
			   SELECT b.u_id,
			          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
			                  1, NVL (b.u_a_name, b.u_e_name),
			                  NVL (b.u_e_name, b.u_a_name)
			                 ) usr_nm,
			          c.emp_no empno_hrchyno,
			          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
			                  1, NVL (c.emp_l_nm, c.emp_f_nm),
			                  NVL (c.emp_f_nm, c.emp_l_nm)
			                 ) empnm_hrchynm,
			          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
			          NULL up_date, 0 rec_src
			     FROM user_r b, s_emp c
			    WHERE NOT EXISTS (
			             SELECT 1
			               FROM s_emp_prv
			              WHERE empno_hrchyno = c.emp_no
			                AND u_id = b.u_id
			                AND emp_prv_typ = 1
			                AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.S_V_EMP_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_EMP_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_EMP_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- VNDR_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.VNDR_AI_VW
(UNT_NO, VNDR_CODE, VNDR_PARNT, VNDR_L_NM, VNDR_F_NM, 
