--
-- AUD_CITIES_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_CITIES_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.CITIES
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
														                 END IF;
                                                                                   
