--
-- SQ_IAS_AC_CC_LMT_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SQ_IAS_AC_CC_LMT_TRG BEFORE INSERT
						ON IAS20261.IAS_AC_CC_LMT FOR EACH ROW
BEGIN
						    IF  :NEW.RCRD_SQ  IS NULL THEN
						        :NEW.RCRD_SQ := YS_GEN_PKG.GET_VAL(' SELECT NVL(MAX(RCRD_SQ),0)+1 FROM IAS_AC_CC_LMT ' );
						    END IF;
						 EXCEPTION 
						   WHEN OTHERS THEN
						        RAISE_APPLICATION_ERROR(-20215,'ErrOn SQ_IAS_AC_CC_LMT: '||SQLERRM);
						END;
/


--
-- SRL_GLS_ADVNC_DTL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.SRL_GLS_ADVNC_DTL_TRG BEFORE INSERT
									ON IAS20261.GLS_ADVNC_EXPNS_RVNU_DTL FOR EACH ROW
BEGIN
									     
									 IF :NEW.DOC_D_SQ IS NULL THEN    
									    :NEW.DOC_D_SQ  := IAS_DOC_SEQ_GL.Nextval;--YS_TRNS_PKG.GET_DOC_M_SQ_FNC;
									 END IF;
									
									     
									EXCEPTION 
									   WHEN OTHERS THEN
									        RAISE_APPLICATION_ERROR(-20401,'Err. When Get Srl/Sequence.');   
									END;
/


--
-- UPD_EDIT_BDGT_BLNC_DTL_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.UPD_EDIT_BDGT_BLNC_DTL_TGR 
                                 BEFORE INSERT OR UPDATE OR DELETE ON IAS20261.GLS_EDIT_BDGT_BLNC_DTL
                                 REFERENCING NEW AS NEW OLD AS OLD
							     FOR EACH ROW
BEGIN  
   
     IF INSERTING THEN
      
       BEGIN 
         UPDATE IAS_BDGT_BLNC_DTL   
            SET AMT_L_ADD=NVL(AMT_L_ADD,0)+NVL(:NEW.AMT_L_ADD,0)
              , AMT_F_ADD=NVL(AMT_F_ADD,0)+NVL(:NEW.AMT_F_ADD,0)
              , AMT_L_DISC=NVL(AMT_L_DISC,0)+NVL(:NEW.AMT_L_DISC,0)
              , AMT_F_DISC=NVL(AMT_F_DISC,0)+NVL(:NEW.AMT_F_DISC,0)
          Where doc_ser=:NEW.DOC_SER_REF
            AND A_CODE= :NEW.A_CODE
            AND PRD_NO= :NEW.PRD_NO
            AND Bdgt_Prd_Type= :NEW.Bdgt_Prd_Type
