--
-- APS_V_PO_WTH_FREIGHT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_PO_WTH_FREIGHT
(ROWDTL, PO_TYPE, PO_NO, PO_DATE, V_CODE, 
 V_NAME, PO_DESC, REF_NO, PUR_TYPE, PO_SER, 
 BRN_NO, I_CODE, ITM_UNT, P_SIZE, P_QTY, 
 REC_ATTCH, WT_UNT, WT_QTY, ARGMNT_NO, I_LENGTH, 
 I_WIDTH, I_HEIGHT, I_NUMBER, W_CODE, I_PRICE, 
 REM_QTY, FREIGHT_QTY, PO_QTY, CC_CODE, PJ_NO, 
 ACTV_NO, BATCH_NO, DOC_SEQUENCE, RCRD_NO, APPROVED, 
 BILL_DATE_V_CODE, BILL_NO_V_CODE, CUR_CODE, CUR_RATE, DISC_AMT, 
 DISC_AMT_MST, DISC_AMT_DTL, VAT_AMT, OTHR_AMT, VNDR_IS_FRGHT_CMP, 
 PAYMNT_MTHD)
BEQUEATH DEFINER
AS 
SELECT P_Order_Detail.ROWID  Rowdtl
          ,P_Order.Po_Type
          ,P_Order.Po_No
          ,P_Order.Po_Date
          ,P_Order.V_code
          ,P_Order.V_Name
          ,P_Order.Po_Desc
          ,P_Order.Ref_No
          ,P_Order.PUR_TYPE
          ,P_Order.Po_Ser
          ,P_Order.Brn_No
          ,P_Order_Detail.I_Code
          ,P_Order_Detail.Itm_Unt
          ,P_Order_Detail.P_Size
          ,P_Order_Detail.P_Qty
          ,P_Order_Detail.Rec_Attch
          ,P_Order_Detail.Wt_Unt
          ,P_Order_Detail.Wt_Qty
          ,P_Order_Detail.Argmnt_No
          ,P_Order_Detail.I_Length
          ,P_Order_Detail.I_Width
          ,P_Order_Detail.I_Height
          ,P_Order_Detail.I_Number
          ,P_Order_Detail.W_Code
          ,DECODE (P_Order.CLC_VAT_PRICE_TYP, 2, P_Order_Detail.i_price_vat, P_Order_Detail.i_price) i_price
          ,(((NVL (SUM (P_Order_Detail.P_Qty), 0)) / NVL (P_Order_Detail.P_Size, 1)) - (NVL (SUM (Ias_Freight_Dtl.P_Qty), 0)) / NVL (P_Order_Detail.P_Size, 1))     Rem_Qty
          ,(NVL (SUM (Ias_Freight_Dtl.P_Qty), 0)) / NVL (P_Order_Detail.P_Size, 1)                                                                                  Freight_Qty
          ,(NVL (SUM (P_Order_Detail.P_Qty), 0)) / NVL (P_Order_Detail.P_Size, 1)                                                                                   Po_Qty
          ,P_Order_Detail.Cc_Code
          ,P_Order_Detail.Pj_No
          ,P_Order_Detail.Actv_No
          ,P_Order_Detail.Batch_No
          ,P_Order_Detail.Doc_Sequence
          ,P_Order_Detail.Rcrd_No
          -- ,p_order.PROCESED
          ,P_Order.Approved
          ,P_Order.BILL_DATE_V_CODE
          ,P_Order.BILL_NO_V_CODE
          ,P_Order.CUR_CODE
          ,P_Order.CUR_RATE
          ,P_Order.DISC_AMT
          ,P_Order.DISC_AMT_MST
          ,P_Order.DISC_AMT_DTL
          ,P_Order.VAT_AMT
          ,P_Order.OTHR_AMT
          ,P_Order.VNDR_IS_FRGHT_CMP
          ,P_Order.PAYMNT_MTHD
    FROM P_Order, P_Order_Detail, Ias_Freight_Dtl
    WHERE P_Order.Po_No = P_Order_Detail.Po_No AND P_Order.Po_Ser = P_Order_Detail.Po_Ser AND P_Order_Detail.I_Code = Ias_Freight_Dtl.I_Code(+) AND P_Order_Detail.Po_Ser = Ias_Freight_Dtl.Po_Ser(+) AND P_Order_Detail.Doc_Sequence = Ias_Freight_Dtl.Doc_Sequence_Ref(+) AND P_Order.Approved = 1
    And  Not Exists(Select 1 From Ias_Freight_Dtl M Where Po_Ser = Ias_Freight_Dtl.PO_SER And Rownum<=1)
    HAVING NVL (SUM (P_Order_Detail.P_Qty), 0) - (NVL (SUM (Ias_Freight_Dtl.P_Qty), 0)) > 0
    GROUP BY P_Order_Detail.ROWID
            ,P_Order.Po_Type
            ,P_Order.Po_No
            ,P_Order.Po_Date
            ,P_Order.V_code
            ,P_Order.V_Name
            ,P_Order.Po_Desc
            ,P_Order.Ref_No
