            ,P_Order_Detail.I_Qty
            ,P_Order_Detail.Itm_Unt
            ,P_Order_Detail.P_Size
            ,P_Order_Detail.P_Qty
            ,P_Order_Detail.Rec_Attch
            ,P_Order_Detail.Wt_Unt
            ,P_Order_Detail.Wt_Qty
            ,P_Order_Detail.Argmnt_No
            ,P_Order_Detail.I_Length
            ,P_Order_Detail.I_Width
            ,P_Order_Detail.I_Height
            ,P_Order_Detail.I_Number
            ,P_Order_Detail.W_Code
            ,P_Order_Detail.i_price
            ,P_Order_Detail.Cc_Code
            ,P_Order_Detail.Pj_No
            ,P_Order_Detail.Actv_No
            ,P_Order_Detail.Batch_No
            ,P_Order_Detail.Doc_Sequence
            ,P_Order_Detail.Rcrd_No
            ,P_Order.Approved
            ,P_Order.BILL_DATE_V_CODE
            ,P_Order.BILL_NO_V_CODE
            ,P_Order.CUR_CODE
            ,P_Order.CUR_RATE
            ,P_Order.DISC_AMT
            ,P_Order.DISC_AMT_MST
            ,P_Order.DISC_AMT_DTL
            ,P_Order.VAT_AMT
            ,P_Order.OTHR_AMT
            ,P_Order.VNDR_IS_FRGHT_CMP
            ,P_Order.PAYMNT_MTHD
            ,P_Order.CLC_VAT_PRICE_TYP
            ,P_Order_Detail.i_price_vat;

