--
-- APS_V_TRNS_MST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_TRNS_MST
(DOC_TYP, PR_TYPE, DOC_NO, DOC_SER, PUR_NO, 
 PUR_SER, DOC_DATE, V_CODE, V_NAME, W_CODE, 
 CC_CODE, PJ_NO, ACTV_NO, HRCHY_NO, DOC_DESC, 
 REQ_AVL_DATE, PR_SELECTED, PR_PARTIAL, APPROVED, REF_NO, 
 BRN_NO)
BEQUEATH DEFINER
AS 
Select 40 Doc_Typ ,-- ÿ·» «·‘—«¡
   M.Pr_Type, M.Pr_No, M.Pr_Ser, Pur_No ,  Pur_Ser, 
   Pr_Date, V_Code, V_Name, M.W_Code, M.Cc_Code, 
   Pj_No,  Actv_No, Hrchy_No, 
   Pr_Desc, Req_Avl_Date, 
   Pr_Selected, Pr_Partial, Approved,Ref_No,  M.Brn_No
From P_Request M
WHERE PUR_SER IS NOT NULL
Union
Select 41 Doc_Typ ,-- ⁄—÷ ”⁄— „‘ —Ì« 
   Null Qt_Type, M.Qt_No , M.Qt_Ser ,  Pur_No , Pur_Ser, 
   Qt_Date, V_Code, V_Name, Null W_Code, null Cc_Code, NULL PJ_NO,NULL ACTV_NO ,Null Hrchy_No, 
   A_Desc,  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Vnd_Quot_Mst M
WHERE PUR_SER IS NOT NULL
Union
Select 156 Doc_Typ ,-- «·„ﬁ«—‰Â «·›‰ÌÂ ·⁄—Ê÷ «·‘—«¡
   Null Qt_Type, M.Doc_No , M.Doc_Ser ,  Pur_No , Pur_Ser, 
   Doc_Date, NULL V_Code,NULL V_Name, Null W_Code, Cc_Code, 
   Pj_No, Actv_No,Null Hrchy_No, 
   Doc_Dsc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Aps_Qtn_Cmpr_Mst M
WHERE PUR_SER IS NOT NULL
Union
Select 157 Doc_Typ ,--  —‘ÌÕ «·„ﬁ«—‰Â «·›‰ÌÂ
   Null Qt_Type, M.Doc_No , M.Doc_Ser , Pur_No ,  Pur_Ser, 
   Doc_Date, NULL V_Code, NULL V_Name, Null W_Code, M.Cc_Code, 
   M.Pj_No, M.Actv_No,Null Hrchy_No, 
   Doc_Dsc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Aps_Qtn_Cmpr_Fltr_Mst M
WHERE PUR_SER IS NOT NULL
Union
Select 43 Doc_Typ ,-- «–‰  Ê—Ìœ „‘ —Ì«  „Õ·ÌÂ
   M.Grn_Type, M.Gr_No , M.G_Ser ,  Pur_No , Pur_Ser, 
   Gr_Date, V_Code, V_Name, M.W_Code, M.Cc_Code, 
   M.Pj_No, M.Actv_No,Null Hrchy_No, 
   A_Desc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Grn_Master M
WHERE PUR_SER IS NOT NULL
Union
Select 116 Doc_Typ ,-- ›Õ’ «Ê«„— «·‘—«¡
   Null Qt_Type, M.Doc_No , M.Doc_Ser , Pur_No , Pur_Ser, 
   Doc_Date, V_Code, V_Name, M.W_Code, M.Cc_Code, 
   M.Pj_No, M.Actv_No,Null Hrchy_No, 
   Doc_Desc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Check_Incm_Mst M
WHERE PUR_SER IS NOT NULL
Union
Select 42 Doc_Typ ,-- «Ê«„— «·‘—«¡
   M.Po_Type, M.Po_No , M.Po_Ser ,  Pur_No , Pur_Ser, 
   Po_Date, V_Code, V_Name, M.W_Code, M.Cc_Code, 
   M.Pj_No, M.Actv_No,Null Hrchy_No, 
   Po_Desc,  Delivery_Date, 
   Null Pr_Selected, Po_Partial, Approved,Ref_No,  M.Brn_No
From P_Order M
WHERE PUR_SER IS NOT NULL
Union
Select 6 Doc_Typ ,-- ›« Ê—Â «·„‘ —Ì« 
   M.PUR_Type, M.bill_No , M.BILL_Ser , Pur_No , Pur_Ser, 
   BILL_Date, V_Code, V_Name, M.W_Code, M.Cc_Code, 
   M.Pj_No, M.Actv_No,Null Hrchy_No, 
   A_Desc, NULL Delivery_Date, 
   Null Pr_Selected, NULL Po_Partial, NULL Approved,Ref_No,  M.Brn_No
From IAS_PI_BILL_MST M
WHERE PUR_SER IS NOT NULL;

