--
-- CHK_RCRD_MUST_REVLT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.CHK_RCRD_MUST_REVLT
(I_CODE, EXPR, OP_RCRD_CNT, REEVAL_RCRD_CNT, REEVAL_CNT)
BEQUEATH DEFINER
AS 
select max_rcrd.i_code,max_rcrd.expr,max_rcrd.rcrd_count op_rcrd_cnt,min_rcrd.rcrd_count reeval_rcrd_cnt,max_rcrd.rcrd_count-min_rcrd.rcrd_count reeval_cnt from(
		                select item_movement.i_code,case when 2=2 then item_movement.w_code when 2=3 then item_movement.whg_code ELSE 0  end expr 
		                ,count(last_reeval_serial)rcrd_count from item_movement,
		                (select i_code,(case when 2=2 then w_code when 2=3 then whg_code ELSE 0  end) expr 
		                ,min(last_reeval_serial)last_reeval_serial from ias_itm_wcode
		                group by i_code,case when 2=2 then w_code when 2=3 then whg_code ELSE 0  end)wcode_tbl
		                where wcode_tbl.i_code=item_movement.i_code 
		                and wcode_tbl.expr=case when 2=2 then item_movement.w_code when 2=3 then item_movement.whg_code ELSE 0  end
		                 and serial<=NVL(last_reeval_serial,SERIAL)
		                group by item_movement.i_code,case when 2=2 then item_movement.w_code when 2=3 then item_movement.whg_code ELSE 0  end
		                )min_rcrd,(
		                select i_code,(case when 2=2 then w_code when 2=3 then whg_code ELSE 0  end) expr 
		                ,count(serial)rcrd_count from item_movement
		                group by i_code,case when 2=2 then w_code when 2=3 then whg_code ELSE 0  end
		                )max_rcrd
		                where max_rcrd.i_code=min_rcrd.i_code and max_rcrd.expr=min_rcrd.expr;


--
-- DTS_V_GET_REP_GPS_TRACK  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_GPS_TRACK
(REP_CODE, GPS_DATE, SRL, SMAN_L_NM, SMAN_F_NM, 
 GPS, LATITUDE, LONGITUDE)
BEQUEATH DEFINER
AS 
select d.Rep_Code,To_Date(To_char(d.GPS_DATE, 'DD/MM/YYYY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') gps_date,srl,nvl(c.REPRS_a_name,'no local name') Sman_L_Nm,nvl(c.REPRS_e_name,'no foreign name') Sman_F_Nm,
                       Ltrim(Rtrim((Ltrim(Rtrim(GPS_LAT_Y))||','||Ltrim(Rtrim(GPS_LNGT_X))))) GPS,Ltrim(Rtrim(GPS_LAT_Y)) Latitude,Ltrim(Rtrim(GPS_LNGT_X))Longitude
                  From Sales_Man c ,GPS_EVENT d 
                Where SMAN_TYP=1
                   And  c.reprs_code=d.rep_code
                Order By  d.rep_code,srl;


--
-- DTS_V_GET_REP_GPS_TRACK_HSTRY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_GPS_TRACK_HSTRY
(REP_CODE, GPS_DATE, SRL, SMAN_L_NM, SMAN_F_NM, 
 GPS, LATITUDE, LONGITUDE)
BEQUEATH DEFINER
AS 
Select D.Rep_Code
											           ,To_Date (To_Char (D.Gps_Date, 'DD/MM/YYYY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') Gps_Date
											           ,Srl
											           ,Nvl (C.Reprs_A_Name, 'no local name') Sman_L_Nm
											           ,Nvl (C.Reprs_E_Name, 'no foreign name') Sman_F_Nm
											           ,Ltrim (Rtrim ( (Ltrim (Rtrim (Gps_Lat_Y)) || ',' || Ltrim (Rtrim (Gps_Lngt_X))))) Gps
											           ,Ltrim (Rtrim (Gps_Lat_Y)) Latitude
											           ,Ltrim (Rtrim (Gps_Lngt_X)) Longitude
											       From Sales_Man C, Gps_Event_Hstry D
											      Where  C.Reprs_Code = D.Rep_Code
											      union all
											      Select D.Rep_Code
											           ,To_Date (To_Char (D.Gps_Date, 'DD/MM/YYYY HH24:MI:SS'), 'DD/MM/YYYY HH24:MI:SS') Gps_Date
											           ,Srl
											           ,Nvl (C.Reprs_A_Name, 'no local name') Sman_L_Nm
											           ,Nvl (C.Reprs_E_Name, 'no foreign name') Sman_F_Nm
											           ,Ltrim (Rtrim ( (Ltrim (Rtrim (Gps_Lat_Y)) || ',' || Ltrim (Rtrim (Gps_Lngt_X))))) Gps
											           ,Ltrim (Rtrim (Gps_Lat_Y)) Latitude
											           ,Ltrim (Rtrim (Gps_Lngt_X)) Longitude
											       From Sales_Man C, Gps_Event D
											      Where  C.Reprs_Code = D.Rep_Code;


--
-- DTS_V_ITM_DTL_PPC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ITM_DTL_PPC
(GRNO, ITMCODE, ITMNAME, ITMUNTCODE, ITMFNAME, 
 ITMSIZE, ITMPCODE, ITMPSIZE, BOONSPERC, DISPERC, 
 PRICE, SUBPRICE, ADDFLDTEXT1, USEDIS, USEEXPR, 
 USEBATCHNO)
BEQUEATH DEFINER
AS 
SELECT G.Grp_Code GrNo,
			          G.I_Code Itmcode,
			          I.I_Name Itmname,
			          G.Itm_Unt Itmuntcode,
			          I.I_E_Name Itmfname,
			          G.P_Size Itmsize,
			          G.I_Code Itmpcode,
			          C.P_Size Itmpsize,
			          I.Free_Qty_Per Boonsperc,
			          I.Disc_Per Disperc,
			          C.I_Price Price,
			          0 Subprice,
			          I.Field1 Addfldtext1,
			          I.Allow_Disc Usedis,
			          I.Use_Exp_Date Useexpr,
			          I.Use_Batch_No Usebatchno
			     FROM Dts_Grp_Dtl G, Ias_Itm_Mst I, Ias_Item_Price C
			    WHERE     G.I_Code = I.I_Code
			          AND G.I_Code = C.I_Code
			          AND I.I_Code = C.I_Code
			          AND C.Lev_No = G.Lev_No;


--
-- DTS_V_REP_INPT_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_REP_INPT_PRIV
(U_ID, U_L_NM, U_F_NM, INPT_TYP, INPT_NO, 
 INPT_L_NM, INPT_F_NM, ADD_FLAG, VIEW_FLAG)
BEQUEATH DEFINER
AS 
Select   u.u_id,nvl(u_a_name,u_e_name) u_l_nm ,NVL(u_e_name,u_a_name) u_f_nm,
				             'WCODE' inpt_typ,ip.w_code inpt_no,Nvl(i.w_name,i.w_e_name) inpt_l_nm,
				             Nvl(i.w_e_name,i.w_name) inpt_f_nm,ip.add_flag,ip.view_flag
				       From  user_r u ,sales_man s ,warehouse_details i, privilege_wh ip   
				      Where  u.u_id = ip.u_id
				        and  u.rep_code is not null
				        and  u.rep_code=s.reprs_code
				        and  ip.w_code=i.w_code 
				        and  (ip.add_flag = 1 or ip.view_flag = 1);


--
-- DTS_V_SMAN_WCODE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_WCODE
(REP_CODE, W_CODE, W_NAME, W_E_NAME, U_ID, 
 BRN_NO, WHG_CODE, GRP_CODE, WCODE_TYPE, ADD_FLAG, 
 VIEW_FLAG, MAIN_WCODE, TRNSFR_WCODE_FLG, CNTRY_NO, PROV_NO, 
 CITY_NO, R_CODE)
BEQUEATH DEFINER
AS 
With Sman
                                        As (Select S.Reprs_Code Rep_Code
                                                  ,S.W_Code
                                                  ,S.Grp_Code
                                                  ,U.U_Id
                                                  ,U.Conn_Brn_No Brn_No
                                                  ,Nvl (S.No_Sal, 0) No_Sal
                                                  ,S.So_W_Code
                                                  ,Decode ( (Nvl (P.Use_Ret_Wcode, 0) + Nvl (S.Use_Ret_Wcode, 0)), 2, 1, 0) Use_Ret_Wcode
                                                  ,Decode ( (Nvl (P.Use_Ret_Wcode, 0) + Nvl (S.Use_Ret_Wcode, 0)), 2, S.Rt_W_Code, Null) Rt_W_Code
                                                  ,Decode ( (Nvl (P.Allw_So_Wh_Rep_Conn_Brn, 0) + Nvl (S.Allw_So_Wh_Rep_Conn_Brn, 0)), 2, 1, 0) Allw_So_Wh_Rep_Conn_Brn
                                                  ,CASE WHEN (Nvl (P.Allw_So_Wh_Rep_Conn_Brn, 0) + Nvl (S.Allw_So_Wh_Rep_Conn_Brn, 0)+Nvl (Use_Balanced_Brn, 0) + Nvl (ALLW_SAL_WH_NOT_CONN_BRN, 0)) =4 THEN 1 ELSE 0 END ALLW_SAL_WH_NOT_CONN_BRN
                                              From Sales_Man S, User_R U, Dts_Para P,IAS_PARA_GEN,IAS_PARA_AR
                                             Where S.Reprs_Code = U.Rep_Code 
                                             And Nvl(S.Inactive,0) = 0 
                                             And Nvl(U.Inactive,0) = 0 
                                             And Nvl(S.Conn_Sp_Sman,0)<>1                                            
                                             And S.Reprs_Code = Nvl (Dts_Prmtr_Pkg.Getpval ('REP_CODE'), S.Reprs_Code) 
                                             And S.Grp_Code Is Not Null)
                                   Select S.Rep_Code Rep_Code
                                         ,S.W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,S.Brn_No
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,1 Wcode_Type
                                         ,1 Add_Flag
                                         ,1 View_Flag
                                         ,Nvl (Wh.Main_Wcode, 0) Main_Wcode
                                         ,0 Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh
                                    Where Nvl (S.W_Code, 0) = Wh.W_Code
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=0
                                   Union All
                                   Select S.Rep_Code
                                         ,S.Rt_W_Code W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,S.Brn_No
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,2 Wcode_Type
                                         ,1 Add_Flag
                                         ,1 View_Flag
                                         ,Nvl (Wh.Main_Wcode, 0) Main_Wcode
                                         ,0 Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh
                                    Where Nvl (S.Rt_W_Code, 0) = Wh.W_Code 
                                    And S.Rt_W_Code Is Not Null
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=0
                                   Union All
                                   Select S.Rep_Code
                                         ,Wh.W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,Wh.Conn_Brn_No Brn_No
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,3 Wcode_Type
                                         ,1 Add_Flag
                                         ,1 View_Flag
                                         ,Nvl (Main_Wcode, 0) Main_Wcode
                                         ,0 Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh
                                    Where Wh.W_Code = S.So_W_Code 
                                    And S.So_W_Code Is Not Null
                                    And S.No_Sal=1
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=0
                                   Union All
                                   Select S.Rep_Code
                                         ,Wh.W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,S.Brn_No 
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,3 Wcode_Type
                                         ,Nvl (Pwh.Add_Flag, 0) Add_Flag
                                         ,Nvl (Pwh.View_Flag, 0) View_Flag
                                         ,Nvl (Main_Wcode, 0) Main_Wcode
                                         ,Nvl (Trnsfr_Wcode_Flg, 0) Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh, Privilege_Wh Pwh
                                    Where Wh.W_Code = Pwh.W_Code 
                                    And S.U_Id = Pwh.U_Id 
                                    And So_W_Code Is Null 
                                    And Nvl (S.W_Code, 0) <> Wh.W_Code 
                                    And Nvl (Pwh.Add_Flag, 0) = 1 
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=0
                                    And 1 = (Case When Allw_So_Wh_Rep_Conn_Brn = 1 And Nvl (Wh.Conn_Brn_No, 0) = Nvl (S.Brn_No, 0) Then 1
                                                   WHEN ALLW_SAL_WH_NOT_CONN_BRN=1 AND  Nvl (Wh.Allw_Sl_In_Brn, 0)=1 
                                                                                          THEN NVL((SELECT 1 FROM Inv_Conn_Brn_Wh c
                                                                                                        WHERE    c.W_Code = Wh.W_Code 
                                                                                                                And c.Brn_No = S.Brn_No                                                                        
                                                                                                  And Rownum <= 1 ),0) 
                                                   WHEN  Nvl (Wh.Conn_Brn_No, 0) = Nvl (S.Brn_No, 0) AND NVL(S.No_Sal,0)=1 THEN 1                                                                                                 
                                                   Else 0 End)
                                   Union All
                                   Select S.Rep_Code
                                         ,Wh.W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,Wh.Conn_Brn_No Brn_No
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,4 Wcode_Type
                                         ,Nvl (Pwh.Add_Flag, 0) Add_Flag
                                         ,Nvl (Pwh.View_Flag, 0) View_Flag
                                         ,Nvl (Main_Wcode, 0) Main_Wcode
                                         ,Nvl (Trnsfr_Wcode_Flg, 0) Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh, Privilege_Wh Pwh
                                    Where Wh.W_Code = Pwh.W_Code 
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=0
                                    And S.U_Id = Pwh.U_Id 
                                    And Nvl (S.W_Code, 0) <> Wh.W_Code 
                                    And 1 = (Case When Nvl (Add_Flag, 0) = 1 Then 1 
                                                  When Nvl (Trnsfr_Wcode_Flg, 0) = 1  Then 1 
                                                  Else 0 End)
                                    Union All
                                   Select S.Rep_Code
                                         ,Wh.W_Code
                                         ,Nvl (Wh.W_Name, Wh.W_E_Name) W_Name
                                         ,Nvl (Wh.W_E_Name, Wh.W_Name) W_E_Name
                                         ,S.U_Id
                                         ,Wh.Conn_Brn_No Brn_No
                                         ,Wh.Whg_Code
                                         ,S.Grp_Code
                                         ,5 Wcode_Type
                                         ,Nvl (Pwh.Add_Flag, 0) Add_Flag
                                         ,Nvl (Pwh.View_Flag, 0) View_Flag
                                         ,Nvl (Main_Wcode, 0) Main_Wcode
                                        , 0 Trnsfr_Wcode_Flg
                                         ,Wh.Cntry_No
                                         ,Wh.Prov_No
                                         ,Wh.City_No
                                         ,Wh.R_Code
                                     From Sman S, Warehouse_Details Wh, Privilege_Wh Pwh,IAS_PARA_AR AR
                                    Where Wh.W_Code = Pwh.W_Code 
                                    And S.U_Id = Pwh.U_Id 
                                    AND   Nvl (Pwh.Add_Flag, 0) = 1
                                    And Nvl (Wh.Conn_Brn_No, 0) = Nvl (S.Brn_No, 0)                                    
                                    And Nvl (S.W_Code, 0) <> Wh.W_Code
                                    AND NVL(WH.CUS_WH_UNDR_DSPSL_FLG,0)=1
                                    AND NVL(AR.AR_UNDR_DSPSL_FLG,0)=1;


