--
-- GLS_V_VNDR_ACCNTS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_VNDR_ACCNTS
(AC_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, AC_CODE_DTL_L_NM, AC_CODE_DTL_F_NM, 
 AC_CODE_DTL_SUB_NM, CONN_BRN_NO, CUR_CODE, AC_DTL_TYP_SUB)
BEQUEATH DEFINER
AS 
Select    M.V_A_Code  						 Ac_Code
           ,M.V_Code     					 Ac_Code_Dtl             
           ,Null         					 Ac_Code_Dtl_Sub
           ,V_A_Name               AC_CODE_DTL_L_NM
           ,Nvl(V_E_Name,V_A_Name) Ac_Code_Dtl_F_Nm
           ,Null    							 Ac_Code_Dtl_Sub_Nm
           ,M.Conn_Brn_No
           ,D.A_Cy 								Cur_Code
           ,4       							Ac_Dtl_Typ_Sub
   From V_Details    M
       ,Vendor_Curr D
  Where M.V_Code    = D.V_Code        
    Union 
    Select  Ac.A_Code   					 Ac_Code
           ,M.V_Code     					 Ac_Code_Dtl            
           ,Null         					 Ac_Code_Dtl_Sub
           ,V_A_Name               AC_CODE_DTL_L_NM
           ,Nvl(V_E_Name,V_A_Name) Ac_Code_Dtl_F_Nm
           ,Null    							 Ac_Code_Dtl_Sub_Nm
           ,M.Conn_Brn_No
           ,D.A_Cy 								Cur_Code
           ,4       							Ac_Dtl_Typ_Sub
      From V_Details    M, Ias_Vndr_Accnt Ac
       ,Account_Curr D
    Where M.V_Code    = Ac.V_Code
      And Ac.A_Code=D.A_Code
      AND EXISTS(SELECT 1 FROM Vendor_Curr WHERE A_CY=D.A_CY AND V_CODE=M.V_CODE);


--
-- GNR_TAX_DTL_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_DTL_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 DOC_TYPE, CLC_TYP_NO, TAX_NO, A_CY, DOC_TYP_NAME, 
 VAT_AMT, DOC_AMT_VAT, DOC_AMT_ZERO_VAT, DOC_AMT_NO_VAT, DOC_AMT_EXPORT_VAT)
BEQUEATH DEFINER
AS 
WITH TLNG AS (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1) LNG_NO FROM DUAL)
SELECT BRN_NO,
             CMP_NO,
             DOC_SER,
             DOC_NO,
             DOC_DATE,
             DOC_TYPE,
             CLC_TYP_NO,
             TAX_NO,
             A_CY,
             (SELECT YS_GEN_PKG.GET_DOCTYP_NM ( P_DOC_TYP   => DOC_TYPE,
                                                P_LNG_NO    => TLNG.LNG_NO) FROM DUAL) DOC_TYP_NAME,
             CASE WHEN (SELECT YS_TAX_PKG.GET_TAX_TYP_NO (CLC_TYP_NO) FROM DUAL) = 0 THEN SUM (TAX_AMT_L)
                  ELSE NULL END VAT_AMT,
             CASE WHEN (SELECT YS_TAX_PKG.GET_TAX_TYP_NO (CLC_TYP_NO) FROM DUAL) = 0 AND SUM (TAX_AMT_L) <> 0 THEN SUM (DOC_AMT)
                  ELSE NULL END SALES_15_VAT,
             CASE WHEN (SELECT YS_TAX_PKG.GET_TAX_TYP_NO (CLC_TYP_NO) FROM DUAL) = 0 AND SUM (TAX_AMT_L) = 0 THEN SUM (DOC_AMT)
                  ELSE NULL END ZERO_VAT,
             CASE WHEN (SELECT YS_TAX_PKG.GET_TAX_TYP_NO (CLC_TYP_NO) FROM DUAL) IN (2, 3, 4) THEN SUM (DOC_AMT)
                  ELSE NULL END NO_VAT,
             CASE
                 WHEN (SELECT YS_TAX_PKG.GET_TAX_TYP_NO (CLC_TYP_NO) FROM DUAL) = 1  THEN SUM (DOC_AMT)
                 ELSE NULL END EXPORT_VAT
        FROM GNR_TAX_MOVMNT_VW,TLNG
       /*WHERE  EXISTS( SELECT DOC_TYP FROM GNR_DDC_TBL 
                       WHERE (NVL(DOC_PST,0) = 1 OR DOC_TYP = 87004) 
                         AND DOC_TYP =GNR_TAX_MOVMNT_VW.DOC_TYPE )*/
    GROUP BY DOC_SER,
             DOC_NO,
             DOC_DATE,
             DOC_TYPE,
             CLC_TYP_NO,
             TAX_NO,
             A_CY,
             BRN_NO,
             CMP_NO,
             TAX_CODE,
             TLNG.LNG_NO
      UNION ALL
      SELECT BRN_NO,
             CMP_NO,
             DOC_SER,
             DOC_NO,
             DOC_DATE,
             106 DOC_TYPE,
             CLC_TYP_NO,
             NULL TAX_NO,
             A_CY,
             (SELECT YS_GEN_PKG.GET_DOCTYP_NM ( P_DOC_TYP   => 106,
                                                P_LNG_NO    => TLNG.LNG_NO) FROM DUAL) DOC_TYP_NAME,
             (SELECT ARS_GNR_PKG.GET_ADVNC_PYMNT (P_DOC_SER => DOC_SER,
                                                  P_TYP     => 2) FROM DUAL) VAT_AMT,
             (SELECT ARS_GNR_PKG.GET_ADVNC_PYMNT (P_DOC_SER => DOC_SER,
                                                  P_TYP     => 1) FROM DUAL) SALES_15_VAT,
             0 ZERO_VAT,
             0 NO_VAT,
             0 EXPORT_VAT
        FROM GNR_TAX_MOVMNT_VW,TLNG
       WHERE DOC_TYPE = 4
         AND (SELECT ARS_GNR_PKG.GET_ADVNC_PYMNT (P_DOC_SER => DOC_SER,
                                                  P_TYP     => 2) FROM DUAL) <> 0                              
    GROUP BY DOC_SER,
             DOC_NO,
             DOC_DATE,
             DOC_TYPE,
             CLC_TYP_NO,
             A_CY,
             BRN_NO,
             CMP_NO,
             TLNG.LNG_NO;


--
-- GNR_TAX_SUM_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_SUM_VW
(BRN_NO, CMP_NO, PRD_NO, PRD_NM, F_DATE, 
 T_DATE, DOC_TYP_NAME, DOC_TYPE, VAT_AMT, DOC_AMT_VAT, 
 DOC_AMT_ZERO_VAT, DOC_AMT_NO_VAT, DOC_AMT_EXPORT_VAT)
BEQUEATH DEFINER
AS 
SELECT BRN_NO,
             CMP_NO,
             GNR_PRD_PKG.GET_TAX_PRD_NO (P_DOC_DATE => DOC_DATE)
                 PRD_NO,
             GNR_PRD_PKG.GET_TAX_PRD_NM (
                 GNR_PRD_PKG.GET_TAX_PRD_NO (P_DOC_DATE => DOC_DATE),
                 1)
                 PRD_NM,
             (SELECT MIN (F_DATE)
                FROM S_PRD_DTL
               WHERE VAT_PRD_NO =
                     GNR_PRD_PKG.GET_TAX_PRD_NO (P_DOC_DATE => DOC_DATE)) --TO_CHAR (Doc_Date, 'MM'))
                 F_DATE,
             (SELECT MAX (T_DATE)
                FROM S_PRD_DTL
               WHERE VAT_PRD_NO =
                     GNR_PRD_PKG.GET_TAX_PRD_NO (P_DOC_DATE => DOC_DATE)) --TO_CHAR (Doc_Date, 'MM'))
                 T_DATE,
             YS_GEN_PKG.GET_DOCTYP_NM (
                 P_DOC_TYP   => DOC_TYPE,
                 P_LNG_NO    =>
                     NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1))
                 DOC_TYP_NAME,
             DOC_TYPE,
             SUM (VAT_AMT)
                 VAT_AMT,
             SUM (DOC_AMT_VAT)
                 DOC_AMT_VAT,
             SUM (DOC_AMT_ZERO_VAT)
                 DOC_AMT_ZERO_VAT,
             SUM (DOC_AMT_NO_VAT)
                 DOC_AMT_NO_VAT,
             SUM (DOC_AMT_EXPORT_VAT)
                 DOC_AMT_EXPORT_VAT
        FROM GNR_TAX_DTL_VW
       --WHERE 1 = 1
    GROUP BY DOC_DATE,                             --TO_CHAR (Doc_Date, 'MM'),
             DOC_TYPE,
             BRN_NO,
             CMP_NO
    ORDER BY DOC_DATE DESC;


--
-- IAS_FREIGHT_ITM_SUM_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_FREIGHT_ITM_SUM_VW
(FREIGHT_NO, PO_TYPE, PO_NO, PO_SER, I_CODE, 
 I_NAME, I_E_NAME, ITM_UNT, I_QTY, P_SIZE, 
 P_QTY, W_CODE, FREIGHT_SER, DOC_NO, DOC_SER)
BEQUEATH DEFINER
AS 
Select D.Freight_No, D.Po_Type, D.Po_No, D.Po_Ser, D.I_Code,M.I_Name,M.I_E_Name,D.Itm_Unt, Sum(D.I_Qty) I_Qty, D.P_Size, Sum(D.P_Qty) P_Qty, D.W_Code, D.Freight_Ser,D.Doc_No, D.Doc_Ser
            From Ias_Freight_Dtl D,Ias_Itm_Mst M
               Where M.I_Code=D.I_Code 
                  Group By D.Freight_No, D.Po_Type, D.Po_No, D.Po_Ser, D.I_Code,D.Itm_Unt, D.P_Size, D.W_Code, 
                  D.Freight_Ser, D.Doc_No, D.Doc_Ser,M.I_Name,M.I_E_Name;

COMMENT ON COLUMN IAS20261.IAS_FREIGHT_ITM_SUM_VW.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_FREIGHT_ITM_SUM_VW.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_FREIGHT_ITM_SUM_VW.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_FREIGHT_ITM_SUM_VW.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.IAS_FREIGHT_ITM_SUM_VW.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';



--
-- IAS_ITM_ATTACH_AVLQTY_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_ITM_ATTACH_AVLQTY_VW
(I_CODE, ITM_UNT, W_CODE, EXPIRE_DATE, BATCH_NO, 
 ATTCH_NO1, ATTCH_DESC_NO1, ATTCH_NO2, ATTCH_DESC_NO2, ATTCH_NO3, 
 ATTCH_DESC_NO3, ATTCH_NO4, ATTCH_DESC_NO4, ATTCH_NO5, ATTCH_DESC_NO5, 
 FLEX_FIELD, FLEX_NO, AVL_QTY)
BEQUEATH DEFINER
AS 
SELECT D.I_CODE,
            D.ITM_UNT,
            M.W_CODE,
            M.EXPIRE_DATE,
            M.BATCH_NO,
            M.ATTCH_NO1,
            M.ATTCH_DESC_NO1,
            M.ATTCH_NO2,
            M.ATTCH_DESC_NO2,
            M.ATTCH_NO3,
            M.ATTCH_DESC_NO3,
            M.ATTCH_NO4,
            M.ATTCH_DESC_NO4,
            M.ATTCH_NO5,
            M.ATTCH_DESC_NO5,
            M.FLEX_FIELD,
            M.FLEX_NO,
            SUM ((NVL (P_QTY, 0) + NVL (PF_QTY, 0)) * NVL (M.IN_OUT, 1))
               AVL_QTY
       FROM IAS_ITM_ATTACH_MOVEMENT M, IAS_ITM_DTL D, IAS_ITM_ONLINE O
      WHERE     M.I_CODE = D.I_CODE
            AND M.I_CODE = O.I_CODE
            AND D.I_CODE = O.I_CODE
            AND NVL (D.MAIN_UNIT, 0) = 1
   GROUP BY D.I_CODE,
            D.ITM_UNT,
            M.W_CODE,
            M.EXPIRE_DATE,
            M.BATCH_NO,
            M.ATTCH_NO1,
            M.ATTCH_DESC_NO1,
            M.ATTCH_NO2,
            M.ATTCH_DESC_NO2,
            M.ATTCH_NO3,
            M.ATTCH_DESC_NO3,
            M.ATTCH_NO4,
            M.ATTCH_DESC_NO4,
            M.ATTCH_NO5,
            M.ATTCH_DESC_NO5,
            M.FLEX_FIELD,
            M.FLEX_NO;

