--
-- IAS_V_DOCTYP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_DOCTYP
(DOC_TYP_NO, BRN_NO, U_ID, AD_DATE)
BEQUEATH DEFINER
AS 
SELECT DOC_TYPE, BRN_NO, AD_U_ID, AD_DATE
      FROM IAS_POST_MST
     WHERE AD_U_ID IS NOT NULL AND DOC_TYPE <> 0
     UNION ALL
    SELECT DOC_TYP , BRN_NO , AD_U_ID, AD_DATE
     FROM S_APPRVD_MOV;

COMMENT ON COLUMN IAS20261.IAS_V_DOCTYP.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

