--
-- IAS_V_DOCTYP_USR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_DOCTYP_USR
(CNT, DOC_TYPE, U_ID)
BEQUEATH DEFINER
AS 
SELECT COUNT(1) ,DOC_TYPE  , AD_U_ID 
  FROM IAS_POST_MST
WHERE AD_U_ID IS NOT NULL AND DOC_TYPE <> 0 
GROUP BY  DOC_TYPE, AD_U_ID
ORDER BY AD_U_ID,DOC_TYPE;

