--
-- IAS_V_ITEMS_STORAGE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITEMS_STORAGE
(I_CODE, I_NAME, I_DESC, PRIMARY_COST, ITM_UNT, 
 W_CODE, P_SIZE)
BEQUEATH DEFINER
AS 
Select Ias_Itm_Mst.i_code,Decode(1,1,Nvl(i_name,i_e_name),Nvl(i_e_name,i_name)) i_name,i_desc,
				                  Nvl(primary_cost,0)  Primary_Cost ,
				                  Ias_Itm_Pkg.Get_Icode_Min_Unit (Ias_Itm_Mst.I_Code) Itm_Unt ,w_code,1 P_Size
				                  From Ias_Itm_Mst,warehouse_details
				                      Where Nvl(service_itm,0)= 0 
				                         And  Nvl(Ias_Itm_Mst.INACTIVE,0)<>1
				                         And  Exists ( Select 1 From Privilege_Gc
				                                      Where G_Code = Ias_Itm_Mst.G_Code
				                                       And  U_Id   = 1
				                                       And  Add_Flag = 1 
				                                       And  RowNum <= 1 ) 
				                       And Exists ( Select 1 From Privilege_Wh
				                                      Where W_Code = Warehouse_Details.W_Code
				                                       And  U_Id   = 1
				                                       And  Add_Flag = 1 
				                                       And  RowNum <= 1 ) 
				                       And Get_Items_ACtivity(Ias_Itm_Mst.Activity_No,
																                       1       ,
																                       0) = 1
				                      And i_code||w_code 
				                      In (Select Distinct i_code||w_code
				                              From  Ias_Itm_Mst,warehouse_details 
						              Minus
						               Select distinct i_code||w_code
						                 From Ias_Open_Stock )     And w_code >=161 And w_code <=161 Order By i_code;

COMMENT ON COLUMN IAS20261.IAS_V_ITEMS_STORAGE.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITEMS_STORAGE.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



