--
-- IAS_V_ITM_AVLQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_AVLQTY
(I_CODE, I_NAME, ITM_UNT, I_IMG, I_PRICE, 
 W_CODE, BRN_NO, AVL_QTY, RSRV_QTY)
BEQUEATH DEFINER
AS 
SELECT m.i_code, m.i_name, d.itm_unt, m.i_img, i.i_price, w.w_code,wh.conn_brn_no,
          (w.avl_qty / d.p_size) avl_qty,
          (SELECT NVL (SUM (NVL (cp_qty, 0)), 0) / NVL (d.p_size, 1)
           FROM   ias_reserve_dtl
           WHERE  i_code = m.i_code
           AND    NVL (w_code, 0) = w.w_code
           AND    t_date >= SYSDATE
           AND    NVL (reserved, 0) = 1
           AND    NVL (cp_qty, 0) >= 0) rsrv_qty
   FROM   ias_itm_mst m,
          ias_itm_dtl d,
          ias_itm_wcode w,
          ias_item_price i,
          warehouse_details wh
   WHERE  m.i_code = d.i_code
   AND    m.i_code = w.i_code
   AND    w.w_code = wh.w_code
   AND    m.i_code(+) = i.i_code
   AND    d.i_code = w.i_code
   AND    d.i_code(+) = i.i_code
   AND    d.itm_unt(+) = i.itm_unt
   AND    w.i_code(+) = i.i_code
   AND    EXISTS (
                SELECT 1
                FROM   ias_pricing_levels
                WHERE  NVL (lev_deflt, 0) = 1 AND lev_no(+) = i.lev_no
                       AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_ITM_AVLQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_AVLQTY.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_AVLQTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_AVLQTY.BRN_NO IS '50 - —ﬁ„ «·›—⁄';



--
-- IAS_V_ITM_MOV_EXP_BTCH_AVLQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_MOV_EXP_BTCH_AVLQTY
(I_CODE, W_CODE, EXPIRE_DATE, BATCH_NO, AVL_QTY)
BEQUEATH DEFINER
AS 
SELECT I_CODE,
             W_CODE,
             EXPIRE_DATE,
             BATCH_NO,
             TRUNC (SUM ((NVL (P_QTY, 0) + NVL (PF_QTY, 0)) * IN_OUT), 6)
                 AVL_QTY
        FROM ITEM_MOVEMENT
    GROUP BY I_CODE,
             W_CODE,
             EXPIRE_DATE,
             BATCH_NO;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_MOV_EXP_BTCH_AVLQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_MOV_EXP_BTCH_AVLQTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



