-- IAS_V_ITM_MOV_NO_EXP_BTCH_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_MOV_NO_EXP_BTCH_QTY
(I_CODE, W_CODE, EXPIRE_DATE, BATCH_NO, AVL_QTY)
BEQUEATH DEFINER
AS 
SELECT I_CODE,
	             W_CODE,
	             '01/01/1900' EXPIRE_DATE,
	             '0' BATCH_NO,
	             TRUNC (SUM ((NVL (P_QTY, 0) + NVL (PF_QTY, 0)) * IN_OUT), 6)
	                 AVL_QTY
	        FROM ITEM_MOVEMENT
	    GROUP BY I_CODE,
             W_CODE;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_MOV_NO_EXP_BTCH_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_MOV_NO_EXP_BTCH_QTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_ITM_PRICE_ONLINE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_PRICE_ONLINE
(I_CODE, I_NAME, ITM_UNT, LEV_NO, CUR_CODE, 
 I_PRICE, SHO_SYS_TYP)
BEQUEATH DEFINER
AS 
SELECT DISTINCT M.I_CODE,
                   M.I_NAME,
                   D.ITM_UNT,
                   I.LEV_NO,
                   E.CUR_CODE,
                   DECODE(P.A_CY, E.CUR_CODE, I.I_PRICE,
                           (I.I_PRICE * (SELECT CUR_RATE FROM EX_RATE WHERE CUR_CODE=P.A_CY) / E.CUR_RATE)) I_PRICE,                                                           
                   WH.SHO_SYS_TYP
     FROM IAS_ITM_MST M,
          IAS_ITM_DTL D,
          IAS_ITEM_PRICE I,
          WAREHOUSE_DETAILS WH,
          IAS_ITM_ONLINE O,
          EX_RATE E,
          IAS_PRICING_LEVELS P
    WHERE     M.I_CODE = D.I_CODE
          AND M.I_CODE = I.I_CODE
          AND D.I_CODE = I.I_CODE
          AND D.ITM_UNT = I.ITM_UNT
          AND M.I_CODE = O.I_CODE
          AND D.I_CODE = O.I_CODE
          AND I.I_CODE = O.I_CODE
          AND D.ITM_UNT = O.ITM_UNT
          AND I.LEV_NO = P.LEV_NO
          AND WH.SHO_SYS_TYP = O.SHO_SYS_TYP
          AND NVL (WH.SHO_WC_TYP, 0)<>0;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_PRICE_ONLINE.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_PRICE_ONLINE.CUR_CODE IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_PRICE_ONLINE.I_PRICE IS '230 - «·”⁄—';



--
-- IAS_V_LAST_UPD_ITM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_LAST_UPD_ITM
(I_CODE, LAST_UPDATE)
BEQUEATH DEFINER
AS 
SELECT I_CODE,MAX(MAX_UPDATE) LAST_UPDATE FROM 
( SELECT I_CODE,MAX(NVL(UP_DATE,AD_DATE)) MAX_UPDATE FROM IAS_ITM_ONLINE GROUP BY I_CODE
  UNION ALL
  SELECT I_CODE,MAX(NVL(UP_DATE,AD_DATE)) MAX_UPDATE FROM IAS_ITEM_PRICE GROUP BY I_CODE
  UNION ALL
  SELECT I_CODE,MAX(NVL(UP_DATE,AD_DATE)) MAX_UPDATE FROM IAS_RESERVE_DTL GROUP BY I_CODE
  UNION ALL
  SELECT I_CODE,MAX(UP_DATE) MAX_UPDATE FROM IAS_ITM_WCODE GROUP BY I_CODE)
GROUP BY I_CODE;

COMMENT ON COLUMN IAS20261.IAS_V_LAST_UPD_ITM.I_CODE IS '176 - —ﬁ„ «·’‰›';



--
-- IAS_V_LOV_PI_CHK_PO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_LOV_PI_CHK_PO
(PO_NO, PO_SER, I_CODE, ITM_NM, UNIT, 
 I_QTY, CHK_QTY, W_CODE, DOC_SEQUENCE, FREE_QTY, 
 P_SIZE, CC_CODE, REC_ATTCH, BARCODE, ITEM_DESC, 
 CANCELED, EXPIRE_DATE, BATCH_NO)
BEQUEATH DEFINER
AS 
SELECT Po_No
          ,Po_Ser
          ,I_Code
          ,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1)     Itm_Nm
          ,Unit
          ,I_Qty
          ,Chk_Qty
          ,W_Code
          ,Doc_Sequence
          ,free_qty
          ,P_Size
          ,cc_code
          ,rec_attch
          ,Barcode
          ,Item_Desc
          ,Canceled
          ,EXPIRE_DATE
          ,BATCH_NO
    FROM (SELECT A.Po_No
                ,A.Po_Ser
                ,B.I_Code
                ,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1)
                     Itm_Nm
                ,B.Itm_Unt
                     Unit
                ,  SUM (I_Qty)I_Qty
                ,(  SUM (Free_Qty)
                  - (SELECT NVL (SUM (CHK_FREE_QTY), 0)
                     FROM Ias_Check_Incm_Dtl P
                     WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence))
                     Free_Qty
                ,(SELECT NVL (SUM (Chk_Qty), 0)
                  FROM Ias_Check_Incm_Dtl P
                  WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence)
                     Chk_Qty
                ,B.W_Code
                ,B.Doc_Sequence
                ,B.P_Size
                ,B.cc_code
                ,B.rec_attch
                ,B.Barcode
                ,B.Item_Desc
                ,B.Canceled
                ,B.EXPIRE_DATE
                ,B.BATCH_NO
          FROM P_Order A, P_Order_Detail B
          WHERE A.Po_No = B.Po_No AND A.Po_Ser = B.Po_Ser
          HAVING    (  SUM (I_Qty)
                     - (SELECT NVL (SUM (Chk_Qty), 0)
                        FROM Ias_Check_Incm_Dtl P
                        WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence)) > 0
                 OR (  SUM (Free_Qty)
                     - (SELECT NVL (SUM (CHK_FREE_QTY), 0)
                        FROM Ias_Check_Incm_Dtl P
                        WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence)) > 0
          GROUP BY A.Po_No
                  ,A.Po_Ser
                  ,I_Code
                  ,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1)
                  ,Itm_Unt
                  ,b.W_Code
                  ,Doc_Sequence
                  ,B.P_Size
                  ,B.cc_code
                  ,B.rec_attch
                  ,B.Barcode
                  ,B.Item_Desc
                  ,B.Canceled
                  ,B.EXPIRE_DATE
                  ,B.BATCH_NO);

COMMENT ON COLUMN IAS20261.IAS_V_LOV_PI_CHK_PO.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_LOV_PI_CHK_PO.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_LOV_PI_CHK_PO.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_LOV_PI_CHK_PO.DOC_SEQUENCE IS '2767 -  ”·”· «·Õ—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_LOV_PI_CHK_PO.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';



