--
-- IAS_V_NY_P_REQUEST_DETAIL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_NY_P_REQUEST_DETAIL
(PR_TYPE, PR_NO, PR_SER, I_CODE, I_QTY, 
 P_SIZE, P_QTY, W_CODE, RCRD_NO, ITEM_DESC, 
 USE_ATTCH, REC_ATTCH, AVL_QTY, ARIV_QTY, PO_QTY, 
 I_MIN_QTY, LAST_INCOME_PRICE, BARCODE, OUT_REQ_NO, OUT_REQ_SER, 
 DOC_SEQUENCE, I_LENGTH, I_WIDTH, I_HEIGHT, I_NUMBER, 
 NOT_PO_PRV_QTY, PO_PRV_QTY, EXPIRE_DATE, BATCH_NO, PUR_CNT, 
 LOST_DAY, I_ROL, SQTY, POQTY, POQTY_OPEN, 
 LAST_INCOME_QTY, LAST_INCOME_DATE, LAST_EXP_DATE, LAST_FREE_QTY, PER_LAST_FREE_QTY, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, UP_CNT, 
 ITM_UNT, WT_QTY, CC_CODE, PJ_NO, ACTV_NO, 
 I_PRICE, WT_UNT)
BEQUEATH DEFINER
AS 
Select RQ.PR_TYPE, RQ.PR_NO, RQ.PR_SER, RQ.I_CODE, RQ.I_QTY, RQ.P_SIZE, P_QTY, RQ.W_CODE, RQ.RCRD_NO, RQ.ITEM_DESC, RQ.USE_ATTCH,
       RQ.REC_ATTCH, RQ.AVL_QTY, RQ.ARIV_QTY, RQ.PO_QTY, RQ.I_MIN_QTY, RQ.LAST_INCOME_PRICE, RQ.BARCODE, RQ.OUT_REQ_NO, RQ.OUT_REQ_SER,
       RQ.DOC_SEQUENCE, RQ.I_LENGTH, RQ.I_WIDTH, RQ.I_HEIGHT, RQ.I_NUMBER, RQ.NOT_PO_PRV_QTY, RQ.PO_PRV_QTY, RQ.EXPIRE_DATE, RQ.BATCH_NO,
       RQ.PUR_CNT, RQ.LOST_DAY, RQ.I_ROL, RQ.SQTY, RQ.POQTY, RQ.POQTY_OPEN, RQ.LAST_INCOME_QTY, RQ.LAST_INCOME_DATE, RQ.LAST_EXP_DATE, RQ.LAST_FREE_QTY,
       RQ.PER_LAST_FREE_QTY, RQ.CMP_NO, RQ.BRN_NO, RQ.BRN_YEAR, RQ.BRN_USR, RQ.UP_CNT, RQ.ITM_UNT, RQ.WT_QTY, RQ.CC_CODE, RQ.PJ_NO, RQ.ACTV_NO, RQ.I_PRICE, RQ.WT_UNT 
    From P_Request_Detail RQ,(Select Doc_Ser,I_Code,Sum(Nvl(I_Qty,0)) I_Qty 
                          From( Select PR_SER  Doc_Ser,I_Code,Nvl(I_Qty,0) I_Qty
                                  From P_Request_Detail 
                                Union All
                                Select PR_SER Doc_Ser,I_Code,Sum(Nvl(I_Qty,0))*-1 I_Qty
                                  From P_Order_Detail 
                                 Where  PR_SER Is Not Null                                   
                                 Group By PR_SER,I_Code)
                        Group By Doc_Ser,I_Code
                        Having Sum(Nvl(I_Qty,0))>0) Mov_Data
    Where RQ.PR_SER=Mov_Data.Doc_Ser
    And RQ.I_Code=Mov_Data.I_Code
    And Nvl(Mov_Data.I_Qty,0)>=0;

COMMENT ON COLUMN IAS20261.IAS_V_NY_P_REQUEST_DETAIL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_NY_P_REQUEST_DETAIL.I_QTY IS '222 - «·ﬂ„Ì…';

