--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_NY_VND_QUOT_DTL
(QT_NO, QT_SER, I_CODE, I_QTY, P_SIZE, 
 P_QTY, I_PRICE, RCRD_NO, PR_NO, PR_SER, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, UP_CNT, 
 ITM_UNT, ITEM_DESC, FIELD_DTL1, FIELD_DTL2, FIELD_DTL3, 
 FIELD_DTL4, FIELD_DTL5)
BEQUEATH DEFINER
AS 
Select VQ.QT_NO, VQ.QT_SER, VQ.I_CODE, Mov_Data.I_Qty, VQ.P_SIZE, (Mov_Data.I_Qty*VQ.P_Size) P_QTY, VQ.I_PRICE, VQ.RCRD_NO, VQ.PR_NO, VQ.PR_SER,
       VQ.CMP_NO, VQ.BRN_NO, VQ.BRN_YEAR, VQ.BRN_USR, VQ.UP_CNT, VQ.ITM_UNT, VQ.ITEM_DESC,
       VQ.FIELD_DTL1, VQ.FIELD_DTL2, VQ.FIELD_DTL3, VQ.FIELD_DTL4, VQ.FIELD_DTL5 
    From IAS_VND_QUOT_DTL VQ,(Select Doc_Ser,I_Code,Sum(Nvl(I_Qty,0)) I_Qty 
                          From( Select QT_SER Doc_Ser,I_Code,Nvl(I_Qty,0) I_Qty
                                  From IAS_VND_QUOT_DTL 
                                Union All
                                Select QT_SER Doc_Ser,I_Code,Sum(Nvl(I_Qty,0))*-1 I_Qty
                                  From P_Order_Detail
                                 Where QT_SER Is Not Null
                                 Group By QT_SER,I_Code)
                        Group By Doc_Ser,I_Code
                        Having Sum(Nvl(I_Qty,0))>0) Mov_Data
    Where VQ.QT_SER=Mov_Data.Doc_Ser
    And VQ.I_Code=Mov_Data.I_Code
    And Nvl(Mov_Data.I_Qty,0)>=0;

COMMENT ON COLUMN IAS20261.IAS_V_NY_VND_QUOT_DTL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_NY_VND_QUOT_DTL.I_QTY IS '222 - «·ﬂ„Ì…';

