--
-- IAS_V_PI_CHK_PO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PI_CHK_PO
(PO_NO, PO_SER, I_CODE, ITM_NM, UNIT, 
 I_QTY, CHK_QTY, W_CODE, DOC_SEQUENCE, FREE_QTY, 
 P_SIZE, CC_CODE, REC_ATTCH, BARCODE, ITEM_DESC, 
 CANCELED, EXPIRE_DATE, BATCH_NO, PUR_NO, PUR_SER)
BEQUEATH DEFINER
AS 
Select Po_No,Po_Ser,I_Code,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1) Itm_Nm,Unit,I_Qty,Chk_Qty,W_Code,Doc_Sequence,		                         
		                         free_qty,P_Size,cc_code,rec_attch,Barcode ,Item_Desc,Canceled,EXPIRE_DATE,BATCH_NO,PUR_NO,PUR_SER
                        From
                        (
                        Select A.Po_No,A.Po_Ser,B.I_Code,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1) Itm_Nm,B.Itm_Unt Unit,
                        (  Sum (I_Qty)
                                          - (Select Nvl (Sum (Chk_Qty), 0)
                                             From   Ias_Check_Incm_Dtl P
                                             Where  P.I_Code = B.I_Code
                                             And    P.Itm_Unt = B.Itm_Unt
                                             And    P.Doc_No_Ref = A.Po_No
                                             And    P.Doc_Ser_Ref = A.Po_Ser
                                             And    P.Doc_Sequence_Ref = B.Doc_Sequence)
                                         ) I_Qty,
                                        (  SUM (b.Free_Qty)
													                  - (SELECT NVL (SUM (CHK_FREE_QTY), 0)
													                     FROM Ias_Check_Incm_Dtl P
													                     WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence))
													                     Free_Qty,   
                                         (Select Nvl (Sum (Chk_Qty), 0)
                                             From   Ias_Check_Incm_Dtl P
                                             Where  P.I_Code = B.I_Code
                                             And    P.Itm_Unt = B.Itm_Unt
                                             And    P.Doc_No_Ref = A.Po_No
                                             And    P.Doc_Ser_Ref = A.Po_Ser
                                             And    P.Doc_Sequence_Ref = B.Doc_Sequence)
                                          Chk_Qty,
                        B.W_Code,B.Doc_Sequence,B.P_Size,B.cc_code,B.rec_attch,B.Barcode ,B.Item_Desc,B.Canceled,B.EXPIRE_DATE	,B.BATCH_NO,B.PUR_NO,B.PUR_SER
                        From P_Order A,P_Order_Detail B 
                         Where A.Po_No=B.Po_No
                         And A.Po_Ser = B.Po_Ser
                         Having   (  Sum (I_Qty)
                                          - (Select Nvl (Sum (Chk_Qty), 0)
                                             From   Ias_Check_Incm_Dtl P
                                             Where  P.I_Code = B.I_Code
                                             And    P.Itm_Unt = B.Itm_Unt
                                             And    P.Doc_No_Ref = A.Po_No
                                             And    P.Doc_Ser_Ref = A.Po_Ser
                                             And    P.Doc_Sequence_Ref = B.Doc_Sequence)
                                         ) > 0
                         Or (  SUM (Free_Qty)
                  - (SELECT NVL (SUM (CHK_FREE_QTY), 0)
                     FROM Ias_Check_Incm_Dtl P
                     WHERE P.I_Code = B.I_Code AND P.Itm_Unt = B.Itm_Unt AND P.Doc_No_Ref = A.Po_No AND P.Doc_Ser_Ref = A.Po_Ser AND P.Doc_Sequence_Ref = B.Doc_Sequence)) > 0                
                         Group By  A.Po_No,A.Po_Ser,I_Code,Ias_Itm_Pkg.Get_Itm_Name (I_Code, 1),Itm_Unt,B.W_Code,Doc_Sequence
                                   ,B.P_Size,B.cc_code,B.rec_attch,B.Barcode ,B.Item_Desc,B.Canceled,B.EXPIRE_DATE	,B.BATCH_NO,B.PUR_NO,B.PUR_SER);

COMMENT ON COLUMN IAS20261.IAS_V_PI_CHK_PO.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PI_CHK_PO.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_PI_CHK_PO.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PI_CHK_PO.DOC_SEQUENCE IS '2767 -  ”·”· «·Õ—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_PI_CHK_PO.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';



--
-- IAS_V_PI_FORIN_PRCHS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PI_FORIN_PRCHS
(BILL_NO, BILL_DATE, V_NAME, BILL_SER, W_CODE, 
 BRN_NO)
BEQUEATH DEFINER
AS 
SELECT bill_no, bill_date, v_name, bill_ser,W_CODE, brn_no
    FROM ias_pi_bill_Mst
    WHERE     NVL (pur_type, 2) = 2
          AND NVL (bill_good_rec, 0) = 0
    ORDER BY bill_date DESC, bill_no;

COMMENT ON COLUMN IAS20261.IAS_V_PI_FORIN_PRCHS.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PI_FORIN_PRCHS.BRN_NO IS '50 - —ﬁ„ «·›—⁄';



--
-- IAS_V_PO_REF_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PO_REF_QTY
(PR_NO, PR_SER, INCLD_REF_NO_IN_CMPR_PR, I_CODE, RCRD_NO, 
 MANUAL_REF_NO, W_CODE, PR_P_QTY, PO_P_QTY, SUM_PRV_PRQTY, 
 P_QTY)
BEQUEATH DEFINER
AS 
SELECT M.PR_NO,
		           M.PR_SER,
		         INCLD_REF_NO_IN_CMPR_PR,
		           M.I_CODE,
		           M.RCRD_NO,
		           M.MANUAL_REF_NO,
		           M.W_CODE,
		           M.PR_P_QTY,
		           M.PO_P_QTY,
		           M.SUM_PRV_PRQTY,
		           GREATEST (LEAST (Pr_P_Qty, Po_P_Qty - Sum_Prv_PrQty), 0)     P_Qty
		    FROM   (SELECT   PR_NO,
		                     pr_ser,
		                     INCLD_REF_NO_IN_CMPR_PR,
		                     I_CODE,
		                     Rcrd_No,
		                     Manual_Ref_No,
		                     W_CODE,
		                     Pr_P_Qty,
		                     Po_P_Qty,
		                     DOC_SEQUENCE,
		                     NVL (
		                         SUM (Pr_P_Qty)
		                             OVER (
		                                 PARTITION BY PR_NO,
		                                              I_CODE,
		                                              Decode(INCLD_REF_NO_IN_CMPR_PR,1,NVL (Manual_Ref_No, Rcrd_No),DOC_SEQUENCE),
		                                              w_code
		                                 ORDER BY  PR_NO, I_CODE, Manual_Ref_No, Rcrd_No
		                                 ROWS BETWEEN UNBOUNDED PRECEDING
		                                      AND     1 PRECEDING),
		                         0)
		                         Sum_Prv_PrQty
		            FROM     (SELECT   A.PR_NO,
		                               A.PR_SER,
		                               INCLD_REF_NO_IN_CMPR_PR,
		                               A.I_Code,
		                               A.Rcrd_No,
		                               A.Manual_Ref_No,
		                               w_code,
		                               DOC_SEQUENCE,
		                               (  NVL (A.P_Qty, 0)
		                                - NVL (
		                                      (SELECT NVL (SUM (P_Qty), 0)
		                                       FROM   P_Order_Detail
		                                       WHERE      Doc_Ser_Ref = A.Pr_Ser
		                                              AND I_Code = A.I_Code
		                                              AND Decode(INCLD_REF_NO_IN_CMPR_PR,1,Manual_Ref_No, DOC_SEQUENCE_REF) =
		                                           Decode(INCLD_REF_NO_IN_CMPR_PR,1,Manual_Ref_No, a.doc_sequence) 
		                                              AND w_code = NVL (a.w_code, w_code)
		                                              AND P_Order_Detail.doc_sequence <
		                                                  P_Order_Detail.doc_sequence),
		                                      0))
		                                   Pr_P_Qty,
		                               (SELECT NVL (SUM (P_Qty), 0)
		                                FROM   P_Order_Detail
		                                WHERE      Doc_Ser_Ref = A.Pr_Ser
		                                       AND I_Code = A.I_Code
		                                       AND Decode(INCLD_REF_NO_IN_CMPR_PR,1,Manual_Ref_No, DOC_SEQUENCE_REF) =
		                                           Decode(INCLD_REF_NO_IN_CMPR_PR,1,Manual_Ref_No, a.doc_sequence) 
		                                       AND w_code = NVL (a.w_code, w_code)
		                                       )
		                                   Po_P_Qty
		                      FROM     P_Request_Detail A,ias_para_ap)) M;

COMMENT ON COLUMN IAS20261.IAS_V_PO_REF_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PO_REF_QTY.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_PO_REF_QTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_PR_PO_DIFF  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PR_PO_DIFF
(PR_NO, I_CODE, UNIT, W_CODE, I_QTY, 
 PO_QTY, DIFF)
BEQUEATH DEFINER
AS 
SELECT b.pr_no,
                                 b.i_code,
                                 b.itm_unt
                                     unit,
                                 b.w_code,
                                 NVL (SUM (NVL (b.i_qty, 0)), 0) / COUNT (b.i_code)
                                     i_qty,
                                 NVL (SUM (NVL (d.i_qty, 0)), 0)
                                     po_qty,
                                 ((  NVL (SUM (NVL (b.i_qty, 0)), 0) / COUNT (b.i_code)
                                   - NVL (SUM (NVL (d.i_qty, 0)), 0)))
                                     diff
                            FROM p_request       a,
                                 p_request_detail b,
                                 ias_itm_mst     c,
                                 p_order_detail  d
                           WHERE     a.pr_no = b.pr_no
                                 AND a.pr_ser = b.pr_ser
                                 AND a.pr_type = b.pr_type
                                 AND b.i_code = c.i_code
                                 AND b.i_code = d.i_code(+)
                                 AND b.pr_no = d.pr_no(+)
                        GROUP BY b.pr_no,
                                 b.i_code,
                                 b.itm_unt,
                                 b.w_code,
                                 b.rcrd_no
                        ORDER BY TO_NUMBER (b.pr_no), b.rcrd_no, b.i_code;

COMMENT ON COLUMN IAS20261.IAS_V_PR_PO_DIFF.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PR_PO_DIFF.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PR_PO_DIFF.I_QTY IS '222 - «·ﬂ„Ì…';



--
-- IAS_V_PR_WTH_PO_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PR_WTH_PO_QTY
(PR_NO, PR_SER, INCLD_REF_NO_IN_CMPR_PR, I_CODE, ITM_UNT, 
 RCRD_NO, MANUAL_REF_NO, W_CODE, PR_QTY, PO_QTY, 
 DIFF_QTY, CC_CODE, PJ_NO, ACTV_NO, WT_UNT, 
 WT_QTY, ARGMNT_NO, I_LENGTH, I_WIDTH, I_HEIGHT, 
 I_NUMBER, P_SIZE, P_QTY, ITEM_DESC, REC_ATTCH, 
 EXPIRE_DATE, BATCH_NO, DOC_SEQUENCE, DLVRY_DATE, I_PRICE, 
 APPROVED, BARCODE, PUR_NO, PUR_SER)
BEQUEATH DEFINER
AS 
SELECT M.PR_NO,
           M.PR_SER,
           INCLD_REF_NO_IN_CMPR_PR,
           M.I_CODE,
           M.itm_unt,
           M.RCRD_NO,
           M.Manual_Ref_No,
           M.W_CODE,
           M.PR_QTY,
           DECODE (INCLD_REF_NO_IN_CMPR_PR,
                   1, GREATEST (LEAST (Pr_Qty, Po_Qty - Sum_Prv_PrQty), 0),
                   Po_Qty)
               PO_QTY,
             pr_Qty
           - DECODE (INCLD_REF_NO_IN_CMPR_PR,
                     1, GREATEST (LEAST (Pr_Qty, Po_Qty - Sum_Prv_PrQty), 0),
                     Po_Qty)
               diff_qty,
           cc_code,
           pj_no,
           actv_no,
           Wt_Unt,
           Wt_Qty,
           Argmnt_No,
           I_Length,
           I_Width,
           I_Height,
           I_Number,
           p_size,
           p_qty,
           item_desc,
           Rec_Attch,
           Expire_date,
           Batch_No,
           DOC_SEQUENCE,
           DLVRY_DATE,
           I_price,
           Approved,
           Barcode,PUR_NO,PUR_SER
    FROM   (SELECT   PR_NO,
                     pr_ser,
                     INCLD_REF_NO_IN_CMPR_PR,
                     I_CODE,
                     itm_unt,
                     Rcrd_No,
                     Manual_Ref_No,
                     W_CODE,
                     Pr_Qty,
                     Po_Qty,
                     DOC_SEQUENCE,
                     NVL (
                         SUM (Pr_Qty)
                             OVER (
                                 PARTITION BY PR_NO,
                                              I_CODE,
                                              DECODE (
                                                  INCLD_REF_NO_IN_CMPR_PR,
                                                  1, NVL (Manual_Ref_No,
                                                          DOC_SEQUENCE),
                                                  DOC_SEQUENCE)
                                 ORDER BY
                                     PR_NO, I_CODE, Manual_Ref_No, DOC_SEQUENCE
                                 ROWS BETWEEN UNBOUNDED PRECEDING
                                      AND     1 PRECEDING),
                         0)
                         Sum_Prv_PrQty,
                     cc_code,
                     pj_no,
                     actv_no,
                     Wt_Unt,
                     Wt_Qty,
                     Argmnt_No,
                     I_Length,
                     I_Width,
                     I_Height,
                     I_Number,
                     p_size,
                     p_qty,
                     item_desc,
                     Rec_Attch,
                     Expire_date,
                     Batch_No,
                     DLVRY_DATE,
                     I_price,
                     Approved,
                     Barcode,PUR_NO,PUR_SER
            FROM     (SELECT   b.PR_NO,
                               b.PR_SER,
                               INCLD_REF_NO_IN_CMPR_PR,
                               b.I_Code,
                               b.itm_unt,
                               b.Rcrd_No,
                               b.Manual_Ref_No,
                               b.w_code,
                               DOC_SEQUENCE,
                               (NVL (b.P_Qty, 0) / NVL (b.p_size, 1))
                                   Pr_Qty,
                               (SELECT NVL (SUM (P_Qty), 0) / NVL (b.p_size, 1)
                                FROM   P_Order_Detail
                                WHERE      Doc_Ser_Ref = b.Pr_Ser
                                       AND I_Code = b.I_Code
                                       AND DECODE (
                                               INCLD_REF_NO_IN_CMPR_PR,
                                               1, NVL (Manual_Ref_No,
                                                       DOC_SEQUENCE_REF),
                                               DOC_SEQUENCE_REF) =
                                           DECODE (
                                               INCLD_REF_NO_IN_CMPR_PR,
                                               1, NVL (b.Manual_Ref_No,
                                                       b.doc_sequence),
                                               b.doc_sequence))
                                   Po_Qty,
                               b.cc_code,
                               b.pj_no,
                               b.actv_no,
                               Wt_Unt,
                               Wt_Qty,
                               Argmnt_No,
                               I_Length,
                               I_Width,
                               I_Height,
                               I_Number,
                               p_size,
                               p_qty,
                               item_desc,
                               Rec_Attch,
                               b.Expire_date,
                               b.Batch_No,
                               b.DLVRY_DATE,
                               b.I_price,
                               a.Approved,
                               b.Barcode,
                               B.PUR_NO,
                               B.PUR_SER
                      FROM     P_Request a, P_Request_Detail b, ias_para_ap
                      WHERE    a.pr_no = b.pr_no AND a.pr_ser = b.pr_ser
                      ORDER BY PR_NO, I_CODE, Rcrd_No, Manual_Ref_No)
            ORDER BY PR_NO DESC, Rcrd_No, I_CODE, Manual_Ref_No) M;

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.DOC_SEQUENCE IS '2767 -  ”·”· «·Õ—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PO_QTY.APPROVED IS '1377 - Õ«·… «·≈⁄ „«œ';



