SELECT PR_TYPE,PR_NO,PR_SER,PR_DATE,W_CODE,CC_CODE,PJ_NO,ACTV_NO,HRCHY_NO,PR_DESC,SIDE_REQ,REQ_AVL_DATE,PR_SELECTED,PR_PARTIAL,PUR_NO,PUR_SER,APPROVED,APRV_U_ID,APRV_DATE,APRV_DSC,ASSGN_TO_U_ID,ASSGN_U_ID,ASSGN_DATE,OUT_REQ_TYPE,OUT_REQ_NO,OUT_REQ_SER,INACTIVE,INACTIVE_U_ID,INACTIVE_RES,INACTIVE_DATE,REF_NO,V_CODE,V_NAME,PUR_TYPE,A_CY,USE_AUTO_SYNC_VNDR,ITM_UNT_TYP,USE_JRNL_AUDT_FLG,AD_U_ID,AD_DATE,UP_U_ID,UP_DATE,UP_CNT,PR_REP,CMP_NO,BRN_NO,BRN_YEAR,BRN_USR,AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,UNPOST_U_ID,UNPOST_DATE,PR_RATE,AD_TRMNL_NM,UP_TRMNL_NM,DOC_SER_EXTRNL FROM P_REQUEST;


--
-- IAS_V_SI_DET_PY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_SI_DET_PY
(I_CODE, ITM_UNT, P_SIZE, W_CODE, CC_CODE, 
 PJ_NO, ACTV_NO, I_QTY, FREE_QTY, PRICE, 
 I_PRICE_VAT, I_PRICE, STK_COST, EXPIRE_DATE, BATCH_NO, 
 RCRD_NO, BILL_NO, BILL_DOC_TYPE, VAT_PER, VAT_AMT, 
 DIS_PER, DIS_AMT, DIS_AMT_MST, DIS_AMT_MST_VAT, BILL_SER, 
 SERVICE_ITEM, BARCODE, DIS_AMT_DTL, ADD_DIS_AMT_MST, ADD_DIS_AMT_DTL, 
 ADD_DISC_AMT_DTL_YR, INSRNCE_LOAD_PER, INSRNCE_LOAD_AMT, INSRNCE_ADD_LMT, INSRNCE_ADD_LMT_MST, 
 I_LENGTH, I_WIDTH, I_HEIGHT, I_NUMBER, WT_UNT, 
 WT_QTY, ARGMNT_NO, REC_ATTCH, DOC_SEQUENCE, CLC_VAT_PRICE_TYP, 
 CR_CARD_NO, DIS_PER2, DIS_PER3, DIS_AMT_DTL2, DIS_AMT_DTL3, 
 DIS_AMT_DTL_VAT, DIS_AMT_DTL2_VAT, DIS_AMT_DTL3_VAT, DMTR_CRCL, CRCMFRNC_CRCL, 
 CNT_WIDTH, CNT_LENGTH, USE_ATTCH, FIELD_DTL1, FIELD_DTL2, 
 FIELD_DTL3, EMP_NO, COMM_PER, COMM_AMT_DTL, REP_CODE_SP, 
 PRM_CODE_OUT)
BEQUEATH DEFINER
AS 
SELECT D.i_code,
		                                                    D.Itm_Unt,
		                                                    nvl(D.p_size,1) p_size,
		                                                    D.w_code,
		                                                    D.Cc_Code,
		                                                    D.pj_no,
		                                                    D.actv_no,
		                                                    nvl(D.i_qty,0) i_qty,
		                                                    nvl(D.Free_qty,0) Free_qty,
		                                                    decode(1,1,i_price_vat,i_price) price,
	                                                      nvl(D.I_price_Vat,0) I_price_Vat,
	                                                      nvl(D.i_price,0) I_price,
	                                                      nvl(D.stk_cost,0) Stk_cost,
	                                                      Decode(D.Expire_date,'01/01/1900',to_date(null),
	                                                             to_char(D.Expire_date,'DD/MM/YYYY')) Expire_date,
	                                                      Decode(D.batch_no,'0',null,D.batch_no) batch_no,
	                                                      D.rcrd_no,
	                                                      D.bill_no,
	                                                      D.bill_doc_type,
	                                                      nvl(D.vat_Per,0) vat_Per,
	                                                      nvl(D.vat_amt,0) vat_amt,
	                                                      nvl(D.dis_per,0) dis_per,
	                                                      nvl(D.dis_amt,0) dis_amt,
	                                                      nvl(D.dis_amt_mst,0) dis_amt_mst,
	                                                      nvl(D.dis_amt_mst_Vat,0) dis_amt_mst_Vat,
	                                                      D.bill_ser,
	                                                      nvl(D.Service_Item,0) Service_Item,
	                                                      D.Barcode,
	                                                      D.dis_amt_dtl,
	                                                      D.add_dis_amt_mst,
	                                                      D.add_dis_amt_dtl,
	                                                      D.add_disc_amt_dtl_yr,
	                                                      D.Insrnce_Load_Per,
														                            D.Insrnce_Load_Amt,
														                            Nvl(D.Insrnce_Add_Lmt,0) Insrnce_Add_Lmt,
														                            Nvl(D.Insrnce_Add_Lmt_Mst,0) Insrnce_Add_Lmt_Mst,
														                            D.I_Length,
																	                      D.I_Width,
																	                      D.I_Height,
																	                      D.I_Number,
														                            D.Wt_Unt,
															                          D.Wt_Qty,
															                          D.Argmnt_No,
															                          D.Rec_Attch,
															                          D.Doc_Sequence,
															                          Nvl(M.Clc_Vat_Price_Typ,0) Clc_Vat_Price_Typ,
															                          M.Cr_Card_No,
															                         NVL(D.Dis_Per2, 0)                Dis_Per2,
																								       NVL(D.Dis_Per3, 0)                Dis_Per3,
																								       NVL(D.Dis_Amt_Dtl2, 0)            Dis_Amt_Dtl2,
																								       NVL(D.Dis_Amt_Dtl3, 0)            Dis_Amt_Dtl3,
																								       NVL(D.Dis_Amt_Dtl_Vat, 0)             Dis_Amt_Dtl_Vat,
																								       NVL(D.Dis_Amt_Dtl2_Vat, 0)            Dis_Amt_Dtl2_Vat,
																								       NVL(D.Dis_Amt_Dtl3_Vat, 0)            Dis_Amt_Dtl3_Vat,
																								       Dmtr_Crcl,
																								       Crcmfrnc_Crcl,
																								       Cnt_Width,
																								       Cnt_Length,
																								       Use_Attch,
																								       Field_Dtl1,
																								       Field_Dtl2,
																								       Field_Dtl3,
																								       D.Emp_No,
																								       D.Comm_Per,
																								       D.Comm_Amt_Dtl,
																								       D.REP_CODE_SP,
																								       D.PRM_CODE_OUT
																				      From IAS20251.Ias_Bill_Mst M ,IAS20251.Ias_Bill_Dtl D,IAS20251.Ex_Rate E
																				      Where M.Bill_Ser=D.Bill_Ser																				        
																				        And Exists(Select 1 From Ias_V_Si_Py Where Bill_Ser=M.Bill_Ser And RowNum<=1)
																				        And Exists(Select 1 From Ias_Itm_Mst Where I_Code=D.I_Code And Nvl(No_Return_Sale,0)=0 And RowNum<=1)
																				        AND Decode(0,1,m.brn_no,1) = Decode(0,1,1,1)
																						    And ((12 = 1) Or 0=0
																						          Or Exists(
																						                 Select 1
																						                   From Privilege_wh 
																						                  Where w_code=d.w_code
																						                    And U_id = 12
																						                    And add_flag = 1
																						                    And Rownum <= 1))
																				        And Nvl(E.Stock_Cur,0)=1
																				        Order By D.Rcrd_No;


--
-- IAS_V_UPAVLQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_UPAVLQTY
(I_CODE, W_CODE, AVLQTYMV)
BEQUEATH DEFINER
AS 
Select tb1.I_code I_code,tb1.w_code w_code ,tb1.avlqtyMV  From Ias_Itm_Wcode, 
		          (Select item_movement.I_code,w_code, sum(In_out*(nvl(item_movement.p_qty,0)+nvl(item_movement.pf_qty,0))) avlqtyMV  
		             From item_movement
		            Group by item_movement.I_code,w_code) tb1
            where Ias_Itm_Wcode.I_code=tb1.I_code
              and Ias_Itm_Wcode.w_code=tb1.w_code
              and avlqtyMV  <> avl_qty;

COMMENT ON COLUMN IAS20261.IAS_V_UPAVLQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_UPAVLQTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_USR_COLLECTOR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_COLLECTOR_PRV
(U_ID, USR_NAME, COL_NO, COL_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.Col_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Col_Name, C.Col_E_Name),Nvl (C.Col_E_Name, C.Col_Name)) Col_Nm,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     From Ias_Priv_Collectors A, User_R B, Collerctor C
    Where     A.U_Id = B.U_Id
          And A.Col_No = C.Col_No
       --   And (Add_Flag = 1 Or View_Flag = 1)
   Union
   Select B.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (B.U_A_Name, B.U_E_Name),Nvl (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          C.Col_No,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,Nvl (C.Col_Name, C.Col_E_Name),Nvl (C.Col_E_Name, C.Col_Name)) Col_Nm,
          0 Add_Flag,
          0 View_Flag,
          Null Ad_U_Id,
          Null Ad_Date,
          Null Up_U_Id,
          Null Up_Date,
          0 Rec_Src
     From User_R B, Collerctor C
    Where Not Exists
             (Select 1
                From Ias_Priv_Collectors
               Where Col_No = C.Col_No And U_Id = B.U_Id And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_COLLECTOR_PRV.COL_NO IS '1222 - —ﬁ„ «·„Õ’·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_COLLECTOR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_COLLECTOR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_COLLECTOR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



