--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_DRIVERS_PRV
(U_ID, USR_NAME, DRIVER_NO, DRIVER_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
Select A.U_Id,
          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                  1, Nvl (B.U_A_Name, B.U_E_Name),
                  Nvl (B.U_E_Name, B.U_A_Name)
                 ) Usr_Nm,
          C.Driver_No,
          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                  1, Nvl (C.Driver_A_Name, C.Driver_E_Name),
                  Nvl (C.Driver_E_Name, C.Driver_A_Name)
                 ) Driver_Nm,
          A.Add_Flag, A.View_Flag, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id, A.Up_Date,
          1 Rec_Src
     From Ias_Priv_Drivers A, User_R B, Ias_Drivers C
    Where A.U_Id = B.U_Id
      And A.Driver_No = C.Driver_No
      --And (Add_Flag = 1 Or View_Flag = 1)
   Union
   Select B.U_Id,
          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                  1, Nvl (B.U_A_Name, B.U_E_Name),
                  Nvl (B.U_E_Name, B.U_A_Name)
                 ) Usr_Nm,
          C.Driver_No,
          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                  1, Nvl (C.Driver_A_Name, C.Driver_E_Name),
                  Nvl (C.Driver_E_Name, C.Driver_A_Name)
                 ) Driver_Nm,
          0 Add_Flag, 0 View_Flag, Null Ad_U_Id, Null Ad_Date, Null Up_U_Id,
          Null Up_Date, 0 Rec_Src
     From User_R B, Ias_Drivers C
    Where Not Exists (
             Select 1
               From Ias_Priv_Drivers
              Where Driver_No = C.Driver_No And U_Id = B.U_Id
                    And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_DRIVERS_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_DRIVERS_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_DRIVERS_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_SALES_MAN_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_SALES_MAN_PRV
(U_ID, USR_NAME, REP_CODE, SALES_MAN_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT a.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.reprs_code,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.reprs_a_name, c.reprs_e_name),
                  NVL (c.reprs_e_name, c.reprs_a_name)
                 ) stk_nm,
          a.add_flag, a.view_flag, a.ad_u_id, a.ad_date, a.up_u_id, a.up_date,
          1 rec_src
     FROM ias_priv_sman a, user_r b, sales_man c
    WHERE a.u_id = b.u_id
      AND a.rep_code = c.reprs_code
      --AND (add_flag = 1 OR view_flag = 1)
   UNION
   SELECT b.u_id,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (b.u_a_name, b.u_e_name),
                  NVL (b.u_e_name, b.u_a_name)
                 ) usr_nm,
          c.reprs_code,
          DECODE (ias_prmtr_pkg.getpval (p_prmtr => 'LANG_NO'),
                  1, NVL (c.reprs_a_name, c.reprs_e_name),
                  NVL (c.reprs_e_name, c.reprs_a_name)
                 ) stk_nm,
          0 add_flag, 0 view_flag, NULL ad_u_id, NULL ad_date, NULL up_u_id,
          NULL up_date, 0 rec_src
     FROM user_r b, sales_man c
    WHERE NOT EXISTS (
             SELECT 1
               FROM ias_priv_sman
              WHERE rep_code = c.reprs_code AND u_id = b.u_id
                    AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_SALES_MAN_PRV.REP_CODE IS '395 - —ﬁ„ «·„‰œÊ»';

COMMENT ON COLUMN IAS20261.IAS_V_USR_SALES_MAN_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_SALES_MAN_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

