--
-- INTERFACE_ACC_V  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INTERFACE_ACC_V
(BRN_NO, A_CODE, A_CODE_NAME, LBL_NM)
BEQUEATH DEFINER
AS 
SELECT BRN_NO,
           A_CODE,
           A_CODE_NAME,
           (SELECT Ias_Gen_Pkg.Get_Prompt (1,REGEXP_SUBSTR (Comments,
                                                          LOWER ('\d+'),
                                                          1,
                                                          1))    LBL_NM
              FROM User_Col_Comments
             WHERE  REGEXP_SUBSTR(Comments,'\d+')In (Select To_Char(Label_No) From Ias_Labels) 
                   AND CASE
                           WHEN 'INTERFACE_ACC' = '0' THEN '0'
                           ELSE Table_Name
                       END =
                       NVL ('INTERFACE_ACC', '0')
                   AND COLUMN_NAME = A_CODE_NAME)    LBL_NM
      FROM INTERFACE_ACC
           UNPIVOT (A_CODE
                   FOR A_CODE_NAME
                   IN (AC_BALANCED_BRN,
                      AC_BALANCED_CC,
                      AMS_A_CODE_EXPNS,
                      AMS_A_CODE_LBR,
                      AMS_CC_CODE_LBR,
