                      FMS_A_CODE_COMM,
                      FMS_A_CODE_INTRNL_TRNSPRT,
                      FMS_A_CODE_SALE_RVNU,
                      FMS_CUST_AC,
                      FMS_DRVR_COMM_ACC,
                      FMS_DRVR_CSTDY_ACC,
                      FMS_RVNU_AC,
                      FMS_TRNS_VNDR_EXPNS_ACC,
                      FRC_DIFF_AC,
                      FRC_DIFF_CC,
                      FRC_DIFF_DISC_AFTR_VAT_AC,
                      GLS_BNK_DPST_AC,
                      HPS_ADMT_A_CODE,
                      HPS_ADMT_A_CODE_DTL,
                      HPS_ADMT_DISC_A_CODE,
                      HPS_DCTR_PRCNT_A_CODE,
                      HPS_RNT_RVNUS_A_CODE,
                      HRS_DSRV_EMP_A_CODE,
                      HRS_MDCL_CARE_TAX_ACC,
                      LC_A_CODE,
                      LC_DIFF,
