                      REM_A_CODE_PURCHS,
                      REM_A_CODE_REAL,
                      REM_A_CODE_RENT_PREPAID,
                      REPRS_COMM_AC,
                      RMS_AC_CODE_EXPENSE,
                      RMS_AC_CODE_HOSPITALITY,
                      RMS_AC_CODE_INSURANCE,
                      RMS_AC_CODE_ITM_DAMAGED,
                      RMS_AC_CODE_NUTRITION,
