--
-- INV_CHK_ASSM_DISASSM_RCRDS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_CHK_ASSM_DISASSM_RCRDS
(TYP, DOC_SER, I_CODE, W_CODE, BATCH_NO, 
 EXPIRE_DATE, DOC_SEQUENCE)
BEQUEATH DEFINER
AS 
SELECT   "TYP","DOC_SER","I_CODE","W_CODE","BATCH_NO","EXPIRE_DATE","DOC_SEQUENCE"
   FROM     (SELECT 'Assmble' typ, doc_ser, i_code, w_code,
                    NVL (batch_no, '0') batch_no,
                    NVL (expire_date, '01/01/1900') expire_date, doc_sequence
             FROM   (
             (SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 12
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             T_W_code W_Code, NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   assemble_kit_items_det)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             T_W_code W_Code, NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   assemble_kit_items_det
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 12)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 11
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   kit_items_detail)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   kit_items_detail
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 11)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null W_Code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   assemble_kit_items_det
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null w_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   kit_items_detail)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null w_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   kit_items_detail
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null W_Code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   assemble_kit_items_det))
             UNION
             SELECT 'DisAssmble' typ, doc_ser, i_code, w_code,
                    NVL (batch_no, '0') batch_no,
                    NVL (expire_date, '01/01/1900') expire_date, doc_sequence
             FROM   ((SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 13
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             F_W_code W_Code, NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   disassemble_kit_items_det)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             F_W_code W_Code, NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   disassemble_kit_items_det
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 13)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 14
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   dis_kit_items_detail)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   dis_kit_items_detail
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, i_code, w_code,
                             NVL (batch_no, '0') batch_no,
                             NVL (expire_date, '01/01/1900') expire_date,
                             doc_sequence
                      FROM   item_movement
                      WHERE  doc_type = 14)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null W_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   disassemble_kit_items_det
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null w_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   dis_kit_items_detail)
                     UNION
                     (SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null w_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   dis_kit_items_detail
                      MINUS
                      SELECT TO_CHAR (doc_ser) doc_ser, kit_item_no i_code,
                             Null W_code, '0' batch_no,
                             To_Date('01/01/1900','dd/mm/yyyy') expire_date,
                             doc_sequence
                      FROM   disassemble_kit_items_det)))
   ORDER BY typ,
            doc_ser,
            i_code,
            w_code,
            NVL (batch_no, '0'),
            NVL (expire_date, '01/01/1900'),
            doc_sequence;

COMMENT ON COLUMN IAS20261.INV_CHK_ASSM_DISASSM_RCRDS.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.INV_CHK_ASSM_DISASSM_RCRDS.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_CHK_ASSM_DISASSM_RCRDS.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.INV_CHK_ASSM_DISASSM_RCRDS.DOC_SEQUENCE IS '2767 -  ”·”· «·Õ—ﬂ…';



--
-- INV_ITM_AVL_QTY_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_ITM_AVL_QTY_VW
(I_CODE, W_CODE, EXPIRE_DATE, BATCH_NO, AVL_QTY)
BEQUEATH DEFINER
AS 
Select   I_Code, W_Code, Expire_Date, Batch_No,
						             Nvl(Sum(In_Out*(Nvl(P_Qty,0)+Nvl(Pf_Qty,0)) ),0) Avl_Qty
						   From     Item_Movement
						   Group By I_Code,
						            W_Code,
						            Expire_Date,
						            Batch_No;

COMMENT ON COLUMN IAS20261.INV_ITM_AVL_QTY_VW.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_ITM_AVL_QTY_VW.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- INV_ITM_PRICE_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_ITM_PRICE_VW
(U_ID, LEVL_NO, I_CODE, ITM_UNT, P_SIZE, 
 A_CY, CUR_RATE, DEFLT_LVL, I_PRICE, LOW_PRICE, 
 HIGH_PRICE, W_CODE, BRN_NO, PRICE_TYPE)
BEQUEATH DEFINER
AS 
Select Prv.U_Id, Lvl.Lev_No, Prc.I_Code, Prc.Itm_Unt, Prc.P_Size, A_Cy,
          Ex.Cur_Rate,
          Decode
               (Ias_Gen_Pkg.Get_Lev_Dflt_Prv (P_Userno => Prv.U_Id),
                Lvl.Lev_No, 1,
                0
               ) Deflt_Lvl,
          Prc.I_Price,
          Nvl
             (Ias_Gen_Pkg.Get_Low_Price
                 (P_Icode           => Prc.I_Code,
                  P_Itm_Unt         => Prc.Itm_Unt,
                  P_Acy             => Lvl.A_Cy,
                  P_Loc_Cur         => Ias_Gen_Pkg.Get_Local_Cur,
                  P_Stk_Cur         => Ias_Gen_Pkg.Get_Stk_Cur,
                  P_Ac_Rate         => Ex.Cur_Rate,
                  P_Stk_Rate        => Ias_Gen_Pkg.Get_Cur_Rate
                                             (P_Acy      => Ias_Gen_Pkg.Get_Stk_Cur),
                  P_Price_Type      => Pr.Price_Type,
                  P_W_Code          => Prc.W_Code,
                  P_Qty             => Null,
                  P_Brn_No          => Prc.Brn_No,
                  P_Usr_No          => Prv.U_Id
                 ),
              0
             ) Low_Price,
          Nvl
             (Ias_Gen_Pkg.Get_High_Price
                 (P_Icode           => Prc.I_Code,
                  P_Itm_Unt         => Prc.Itm_Unt,
                  P_Acy             => Lvl.A_Cy,
                  P_Loc_Cur         => Ias_Gen_Pkg.Get_Local_Cur,
                  P_Stk_Cur         => Ias_Gen_Pkg.Get_Stk_Cur,
                  P_Ac_Rate         => Ex.Cur_Rate,
                  P_Stk_Rate        => Ias_Gen_Pkg.Get_Cur_Rate
                                             (P_Acy      => Ias_Gen_Pkg.Get_Stk_Cur),
                  P_Price_Type      => Pr.Price_Type,
                  P_W_Code          => Prc.W_Code,
                  P_Qty             => Null,
                  P_Brn_No          => Prc.Brn_No,
                  P_Usr_No          => Prv.U_Id
                 ),
              0
             ) High_Price,
          Prc.W_Code, Prc.Brn_No, Nvl (Pr.Price_Type, 0) Price_Type
   From   Ias_Pricing_Levels Lvl,
          Ias_Item_Price Prc,
          Ias_Priv_Price Prv,
          Ex_Rate Ex,
          Ias_Para_Inv Pr
   Where  Nvl (Prv.Add_Flag, 0) = 1
   And    Prv.Lev_No = Lvl.Lev_No
   And    Prc.Lev_No = Lvl.Lev_No
   And    Lvl.A_Cy = Ex.Cur_Code
   And    Nvl (Lvl.Lev_No, 0) =
                  Nvl (Ias_Gen_Pkg.Get_Lev_Dflt_Prv (P_Userno => Prv.U_Id), 0);

COMMENT ON COLUMN IAS20261.INV_ITM_PRICE_VW.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_ITM_PRICE_VW.A_CY IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.INV_ITM_PRICE_VW.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.INV_ITM_PRICE_VW.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.INV_ITM_PRICE_VW.BRN_NO IS '50 - —ﬁ„ «·›—⁄';



--
-- INV_KPI_ITM_PRICE_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_KPI_ITM_PRICE_VW
(ITM_CODE, ITM_NM, ITM_F_NM, ITM_DSC, ITM_F_DSC, 
 LEV_NO, LEV_NM, ITM_UNT, P_SIZE, W_CODE, 
 W_NM, EXPIRE_DATE, BATCH_NO, BRN_NO, BRN_NM, 
 FROM_QTY, TO_QTY, I_PRICE, GRP_CLASS_CODE, GRP_CLASS_NM, 
 ACTIVITY_NO, ACTIVITY_NM, GRP_CODE, GRP_CODE_NM, MNG_CODE, 
 MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, ASSTNT_GRP_CODE, ASSTNT_GRP_NM, 
 DTL_GRP_NO, DTL_GRP_NM, ALTRNTV_GRP_CODE, ALTRNTV_GRP_NM, ITM_TYP_NO, 
 ITM_TYP_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITEM_SIZE, SIZE_ITM, AREA_ITM, WEIGHT_ITM, 
 GTIN_CODE, HSN_CODE, MANF_CODE, ALTER_CODE, MRP_ITM_CLSS, 
 DOC_DATE, PRD_NO, PRD_NM, I_CWTAVG, INCOME_DATE, 
 LENGTH_ITM, WIDTH_ITM, HEIGHT_ITM, SEASON_ITM, ORE_ITM, 
 MARK_ITM, COMPANY_ITM, COUNTRY_ITM)
BEQUEATH DEFINER
AS 
WITH
        Lng
        AS
            (SELECT (SELECT NVL (
                                Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                1)
                       FROM DUAL)
                        Lng_No,
                    NVL (
                        (SELECT FLD_VAL
                           FROM S_FLD_PRV_FXD_USR
                          WHERE     UPPER (FLD_NM) = UPPER ('HIDE_COST')
                                AND U_ID =
                                    NVL (
                                        Ias_Prmtr_Pkg.Getpval (
                                            P_Prmtr   => 'USER_NO'),
                                        1)
                                AND ROWNUM <= 1),
                        0)
                        HIDE_COST,
                    (SELECT NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),
                                 1)
                       FROM DUAL)
                        P_USR_NO,
                    (SELECT WTAVG_TYPE
                       FROM IAS_PARA_INV
                      WHERE ROWNUM <= 1)
                        WTAVG_TYPE
               FROM DUAL)
    SELECT M.I_Code
               Itm_Code,
           DECODE (Lng.Lng_No, 1, M.I_Name, NVL (M.I_E_Name, M.I_Name))
               Itm_Nm,
           M.I_E_Name
               Itm_F_Nm,
           DECODE (Lng.Lng_No, 1, M.I_Desc, NVL (M.I_F_Desc, M.I_Desc))
               Itm_Dsc,
           M.I_F_Desc
               Itm_F_Dsc,
           D.Lev_No,
              D.Lev_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, LEV_A_NAME,
                              NVL (LEV_E_NAME, LEV_A_NAME))
                 FROM IAS_PRICING_LEVELS
                WHERE Lev_No = D.Lev_No AND ROWNUM <= 1)
               Lev_Nm,
           D.Itm_Unt,
           D.P_Size,
           D.W_Code
               W_Code,
              D.W_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No, 1, W_Name, NVL (W_E_Name, W_Name))
                 FROM Warehouse_Details
                WHERE W_Code = D.W_Code AND ROWNUM <= 1)
               W_Nm,
           DECODE (D.Expire_Date, '01/01/1900', NULL, D.Expire_Date)
               Expire_Date,
           DECODE (D.Batch_No, '0', NULL, D.Batch_No)
               Batch_No,
           D.Brn_No
               Brn_No,
              D.Brn_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Brn_Lname, Brn_Fname),
                              NVL (Brn_Fname, Brn_Lname))
                 FROM S_Brn
                WHERE Brn_No = D.Brn_No AND ROWNUM <= 1)
               Brn_Nm,
           D.FROM_QTY,
           D.TO_QTY,
           D.I_Price,
           M.Grp_Class_Code
               Grp_Class_Code,
              M.Grp_Class_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, A.Grp_L_Name,
                              NVL (A.Grp_F_Name, A.Grp_L_Name))
                 FROM Ias_Grp_Itm_Lvl A
                WHERE A.Grp_Code = M.Grp_Class_Code AND ROWNUM <= 1)
               Grp_Class_Nm,
           M.Activity_No
               Activity_No,
              M.Activity_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, A.Activity_A_Name,
                              NVL (A.Activity_E_Name, A.Activity_A_Name))
                 FROM Ias_Items_Activity A
                WHERE A.Activity_No = M.Activity_No AND ROWNUM <= 1)
               Activity_Nm,
           M.G_Code
               Grp_Code,
              M.G_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Grp.G_A_NAME, Grp.G_E_NAME),
                              NVL (Grp.G_E_NAME, Grp.G_A_NAME))
                          Grp_Nm
                 FROM GROUP_DETAILS Grp
                WHERE G_Code = M.G_Code AND ROWNUM <= 1)
               Grp_Code_Nm,
           M.Mng_Code,
              M.Mng_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Grp.MNG_A_NAME, Grp.MNG_E_NAME),
                              NVL (Grp.MNG_E_NAME, Grp.MNG_A_NAME))
                          Grp_Nm
                 FROM IAS_MAINSUB_GRP_DTL Grp
                WHERE     Mng_Code = M.Mng_Code
                      AND NVL (M.G_Code, '0') =
                          DECODE (NVL (G_Code, '0'),
                                  '0', NVL (M.G_Code, '0'),
                                  G_Code)
                      AND ROWNUM <= 1)
               Mng_Code_Nm,
           M.Subg_Code,
              M.Subg_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Grp.SUBG_A_NAME, Grp.SUBG_E_NAME),
                              NVL (Grp.SUBG_E_NAME, Grp.SUBG_A_NAME))
                          Grp_Nm
                 FROM IAS_SUB_GRP_DTL Grp
                WHERE     Subg_Code = M.Subg_Code
                      AND NVL (M.G_Code, '0') =
                          DECODE (NVL (G_Code, '0'),
                                  '0', NVL (M.G_Code, '0'),
                                  G_Code)
                      AND NVL (M.Mng_Code, '0') =
                          DECODE (NVL (Mng_Code, '0'),
                                  '0', NVL (M.Mng_Code, '0'),
                                  Mng_Code)
                      AND ROWNUM <= 1)
               Subg_Code_Nm,
           M.Assistant_No
               Asstnt_Grp_Code,
              M.Assistant_No
           || ' - '
           || (SELECT DECODE (
                          Lng.Lng_No,
                          1, NVL (Grp.Assistant_A_Name, Grp.Assistant_E_Name),
                          NVL (Grp.Assistant_E_Name, Grp.Assistant_A_Name))
                          Grp_Nm
                 FROM Ias_Assistant_Group Grp
                WHERE     Assistant_No = M.Assistant_No
                      AND NVL (M.G_Code, '0') =
                          DECODE (NVL (G_Code, '0'),
                                  '0', NVL (M.G_Code, '0'),
                                  G_Code)
                      AND NVL (M.Mng_Code, '0') =
                          DECODE (NVL (Mng_Code, '0'),
                                  '0', NVL (M.Mng_Code, '0'),
                                  Mng_Code)
                      AND NVL (M.Subg_Code, '0') =
                          DECODE (NVL (Subg_Code, '0'),
                                  '0', NVL (M.Subg_Code, '0'),
                                  Subg_Code)
                      AND ROWNUM <= 1)
               Asstnt_Grp_Nm,
           M.Detail_No
               Dtl_Grp_No,
              M.Detail_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Grp.Detail_A_Name, Grp.Detail_E_Name),
                              NVL (Grp.Detail_E_Name, Grp.Detail_A_Name))
                          Grp_Nm
                 FROM Ias_Detail_Group Grp
                WHERE     Detail_No = M.Detail_No
                      AND NVL (M.G_Code, '0') =
                          DECODE (NVL (G_Code, '0'),
                                  '0', NVL (M.G_Code, '0'),
                                  G_Code)
                      AND NVL (M.Mng_Code, '0') =
                          DECODE (NVL (Mng_Code, '0'),
                                  '0', NVL (M.Mng_Code, '0'),
                                  Mng_Code)
                      AND NVL (M.Subg_Code, '0') =
                          DECODE (NVL (Subg_Code, '0'),
                                  '0', NVL (M.Subg_Code, '0'),
                                  Subg_Code)
                      AND NVL (M.Assistant_No, '0') =
                          DECODE (NVL (Assistant_No, '0'),
                                  '0', NVL (M.Assistant_No, '0'),
                                  Assistant_No)
                      AND ROWNUM <= 1)
               Dtl_Grp_Nm,
           M.Group_No
               Altrntv_Grp_Code,
              M.Group_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, A.Group_A_Name,
                              NVL (A.Group_E_Name, A.Group_A_Name))
                 FROM Ias_Alternative_Group A
                WHERE A.Group_No = M.Group_No AND ROWNUM <= 1)
               Altrntv_Grp_Nm,
           M.Item_Type
               Itm_Typ_No,
              M.Item_Type
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, A.It_A_Name,
                              NVL (A.It_E_Name, A.It_A_Name))
                 FROM Item_Types A
                WHERE A.Type_Of_Item = M.Item_Type AND ROWNUM <= 1)
               Itm_Typ_Nm,
           M.Kit_Itm,
           M.Use_Exp_Date,
           M.Use_Batch_No,
           M.Use_Serialno,
           M.Use_Attch,
           M.Item_Size,
           M.Size_Itm,
           M.Area_Itm,
           M.Weight_Itm,
           M.Gtin_Code,
           M.Hsn_Code,
           M.Manf_Code,
           M.Alter_Code,
           TO_CHAR (D.AD_DATE, 'DD/MM/YYYY')
               Doc_Date,
           TO_NUMBER (TO_CHAR (D.AD_DATE, 'MM'))
               Prd_No,
              TO_NUMBER (TO_CHAR (D.AD_DATE, 'MM'))
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Prd_L_Nm, Prd_F_Nm),
                              NVL (Prd_F_Nm, Prd_L_Nm))
                 FROM S_Prd_Dtl
                WHERE     Prd_No = TO_NUMBER (TO_CHAR (D.AD_DATE, 'MM'))
                      AND ROWNUM <= 1)
               Prd_Nm,
           DECODE (
               LNG.HIDE_COST,
               1, ROUND (
                      Ias_Itm_Pkg.Get_Grand_Wtavg (
                          P_Wtavg_Type   => Lng.Wtavg_Type,
                          P_Icode        => M.I_Code,
                          P_Wcode        => D.W_Code),
                      4),
               0)
               I_Cwtavg,
           TO_NUMBER (TO_CHAR (D.AD_DATE, 'YYYY'))
               Brn_Year,
           M.Income_Date,
           M.Length_Itm,
           M.Width_Itm,
           M.Height_Itm,
           M.Season_Itm,
           M.Ore_Itm,
           M.Mark_Itm,
           M.Company_Itm,
           M.Country_Itm
      FROM Ias_Item_Price     D,
           Ias_Itm_Mst        M,
           Lng
     WHERE     M.I_Code = D.I_Code
           AND EXISTS
                   (SELECT 1
                      FROM Privilege_Wh
                     WHERE     Privilege_Wh.W_Code =
                               NVL (D.W_Code, Privilege_Wh.W_Code)
                           AND View_Flag = 1
                           AND U_Id = LNG.P_USR_NO)
           AND EXISTS
                   (SELECT 1
                      FROM Privilege_Gc
                     WHERE     Privilege_Gc.G_Code = M.G_CODE
                           AND View_Flag = 1
                           AND U_Id = LNG.P_USR_NO);

COMMENT ON COLUMN IAS20261.INV_KPI_ITM_PRICE_VW.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.INV_KPI_ITM_PRICE_VW.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.INV_KPI_ITM_PRICE_VW.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.INV_KPI_ITM_PRICE_VW.DOC_DATE IS '1137 -  «—ÌŒ «·ÊÀÌﬁ…';



--
-- INV_V_ITM_BIN_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_ITM_BIN_MOVMNT
(I_CODE, W_CODE, B_CODE, I_QTY)
BEQUEATH DEFINER
AS 
Select   D.I_code
           ,M.W_code
           ,M.B_code
           ,Sum(Nvl(D.P_qty, 0) * Nvl(D.In_out, 0)) I_qty
   From     Bin_details M
           ,Inv_itm_bin_movmnt D
   Where    M.B_code = D.B_code And M.W_code = D.W_code
   Group By D.I_code
           ,M.W_code
           ,M.B_code
   Having   Sum(Nvl(D.P_qty, 0) * Nvl(D.In_out, 0)) > 0;

COMMENT ON COLUMN IAS20261.INV_V_ITM_BIN_MOVMNT.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_V_ITM_BIN_MOVMNT.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.INV_V_ITM_BIN_MOVMNT.I_QTY IS '222 - «·ﬂ„Ì…';



--
-- PURCHS_BILL_MST_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.PURCHS_BILL_MST_AI_VW
(TYP_NO, DOC_NO, DOC_SRL, DOC_DATE, MNL_DATE, 
 CUR_CODE, CUR_RATE, STK_RATE, WRHS_CODE, UNT_NO, 
 PYMNT_CSH, PYMNT_BNK, PYMNT_CRDT, PYMNT_AC, VNDR_CODE, 
 VNDR_NM, AC_CODE_DTL_SUB, CSH_CODE, BNK_CODE, AC_CODE_DTL_SUB_BNK, 
 AC_CODE, AC_CODE_DTL, AC_DTL_TYP, CSH_AMT, BNK_AMT, 
 CRDT_AMT, AC_AMT, DOC_AMT, DSCNT_AMT, OTHR_AMT, 
 TAX_AMT, DSCNT_AMT_ADD, CSH_AMT_LOCAL, BNK_AMT_LOCAL, CRDT_AMT_LOCAL, 
 AC_AMT_LOCAL, DOC_AMT_LOCAL, DSCNT_AMT_LOCAL, OTHR_AMT_LOCAL, TAX_AMT_LOCAL, 
 DSCNT_AMT_ADD_LOCAL, TOTL_BILL_AMT, TOTL_BILL_AMT_LOCAL, PMAN_CODE, DRVR_NO, 
 SUB_LDGR1_CODE, SUB_LDGR2_CODE, SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, 
 SUB_LDGR6_CODE, TAX_CODE, DOC_DUE_DATE, DOC_DSC, REF_NO, 
 MNL_NO, CHQ_NOTE_NO, CHQ_NOTE_DATE, TAX_CTGRY_NO, CLC_TAX_FREE_QTY_FLG, 
 VRFY_FLG, STNDBY_FLG, PST_FLG, YR_NO, CRT_USR, 
 CRT_DATE)
BEQUEATH DEFINER
AS 
SELECT BILL_TYPE_NO TYP_NO,
          BILL_NO DOC_NO,
          BILL_SER DOC_SRL,
          BILL_DATE DOC_DATE,
          BILL_DATE_V_CODE  MNL_DATE,
          BILL_CURRENCY CUR_CODE,
          BILL_RATE CUR_RATE,
          STOCK_RATE STK_RATE,
          W_CODE     WRHS_CODE,
          BRN_NO     UNT_NO,          
          (CASE WHEN BILL_DOC_TYPE = 1 THEN 1 ELSE 0 END)          PYMNT_CSH  ,
          (CASE WHEN BILL_DOC_TYPE IN (2,3,5,6) THEN 1 ELSE 0 END) PYMNT_BNK  ,
          (CASE WHEN BILL_DOC_TYPE = 4 THEN 1 ELSE 0 END)          PYMNT_CRDT ,
          (CASE WHEN BILL_DOC_TYPE = 8 THEN 1 ELSE 0 END)          PYMNT_AC   ,
          V_CODE      VNDR_CODE,
          V_NAME      VNDR_NM,
          NULL AC_CODE_DTL_SUB,
         (CASE WHEN BILL_DOC_TYPE = 1 THEN CASH_NO ELSE NULL END) CSH_CODE,
         (CASE WHEN BILL_DOC_TYPE IN (2,3,5,6) THEN CASH_NO ELSE NULL END)  BNK_CODE,
          NULL AC_CODE_DTL_SUB_BNK,
          AC_CODE AC_CODE,
          AC_CODE_DTL AC_CODE_DTL,
          AC_DTL_TYP  AC_DTL_TYP,   
         (CASE WHEN BILL_DOC_TYPE = 1 THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) ELSE 0 END)          CSH_AMT,
         (CASE WHEN BILL_DOC_TYPE IN (2,3,5,6) THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) ELSE 0 END) BNK_AMT,
         (CASE WHEN BILL_DOC_TYPE = 4 THEN ( BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) ELSE 0 END)           CRDT_AMT,
         (CASE WHEN BILL_DOC_TYPE = 8 THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0)) ELSE 0 END)           AC_AMT,        
          NVL(BILL_AMT,0)  DOC_AMT,
          NVL(DISC_AMT,0)  DSCNT_AMT,
          NVL(OTHR_AMT,0)  OTHR_AMT,
          NVL(VAT_AMT,0)   TAX_AMT,
          NVL(ADD_DISC_AMT_MST,0) DSCNT_AMT_ADD,
          (NVL((CASE WHEN BILL_DOC_TYPE = 1 THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) ELSE 0 END),0)*BILL_RATE)         CSH_AMT_LOCAL,
          (NVL((CASE WHEN BILL_DOC_TYPE IN (2,3,5,6) THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0)) ELSE 0 END),0)*BILL_RATE) BNK_AMT_LOCAL,
          (NVL((CASE WHEN BILL_DOC_TYPE = 4 THEN ( BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) ELSE 0 END),0)*BILL_RATE)          CRDT_AMT_LOCAL,
          (NVL((CASE WHEN BILL_DOC_TYPE = 8 THEN (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0)) ELSE 0 END),0)*BILL_RATE)          AC_AMT_LOCAL,         
          (NVL(BILL_AMT,0)*BILL_RATE)         DOC_AMT_LOCAL,
          (NVL(DISC_AMT,0)*BILL_RATE)         DSCNT_AMT_LOCAL,
          (NVL(OTHR_AMT,0)*BILL_RATE)         OTHR_AMT_LOCAL,
          (NVL(VAT_AMT,0)*BILL_RATE)          TAX_AMT_LOCAL,
          (NVL(ADD_DISC_AMT_MST,0)*BILL_RATE) DSCNT_AMT_ADD_LOCAL,
          ( BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) TOTL_BILL_AMT,
          ( (  BILL_AMT - NVL (DISC_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT, 0) ) * BILL_RATE) TOTL_BILL_AMT_LOCAL,
          PMAN_CODE,
          DRIVER_NAME  DRVR_NO,
          CC_CODE SUB_LDGR1_CODE,
          PJ_NO   SUB_LDGR2_CODE,
          ACTV_NO SUB_LDGR3_CODE,
          NULL    SUB_LDGR4_CODE,
          NULL    SUB_LDGR5_CODE,
          NULL    SUB_LDGR6_CODE,                  
          V_TAX_CODE TAX_CODE,          
          BILL_DUE_DATE DOC_DUE_DATE,
          A_DESC DOC_DSC,
          REF_NO,
          BILL_NO_V_CODE MNL_NO,
          CHEQUE_NO CHQ_NOTE_NO,
          CHEQUE_DUE_DATE  CHQ_NOTE_DATE,
          CLC_TYP_NO_TAX TAX_CTGRY_NO, 
          CLC_TAX_FREE_QTY_FLG,          
          AUDIT_REF VRFY_FLG,
          HUNG STNDBY_FLG,
          BILL_POST PST_FLG,
          BRN_YEAR YR_NO,
          AD_U_ID CRT_USR,
          AD_DATE CRT_DATE          
     FROM IAS_PI_BILL_MST;


