--
-- AUD_INV_CONN_BRN_WH_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_INV_CONN_BRN_WH_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.INV_CONN_BRN_WH
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
														                 END IF;
                                                                                   
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'INV_CONN_BRN_WH','AD_DATE',:NEW.AD_DATE,:OLD.AD_DATE,Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NVL(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'INV_CONN_BRN_WH','AD_TRMNL_NM',:NEW.AD_TRMNL_NM,:OLD.AD_TRMNL_NM,Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NVL(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'INV_CONN_BRN_WH','AD_U_ID',:NEW.AD_U_ID,:OLD.AD_U_ID,Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NVL(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'INV_CONN_BRN_WH','UP_TRMNL_NM',:NEW.UP_TRMNL_NM,:OLD.UP_TRMNL_NM,Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NVL(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'INV_CONN_BRN_WH','W_CODE',:NEW.W_CODE,:OLD.W_CODE,Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NVL(:NEW.BRN_NO,:OLD.BRN_NO),NULL,NULL,NULL); 

                                        END;
