--
-- AUD_OPEN_BAL_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_OPEN_BAL_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.OPEN_BAL
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
