--
-- AUD_SALES_MAN_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_SALES_MAN_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.SALES_MAN
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
														                 END IF;
                                                                                   
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'SALES_MAN','ACTV_NO',:NEW.ACTV_NO,:OLD.ACTV_NO,Nvl(:NEW.REPRS_CODE,:OLD.REPRS_CODE),NULL,NULL,NULL,NULL,NULL,NULL,NULL); 
