			ON IAS20261.IAS_PI_BILL_MST 
			REFERENCING NEW AS New OLD AS Old
			FOR EACH ROW
BEGIN                                                                                     
			             
			     If :NEW.CLC_TYP_NO_TAX IS NULL and :NEW.PUR_TYPE=1   Then
			        Raise_application_error(-20469,'Error When insert BILL into IAS_PI_BILL_MST Table '||SqlErrm) ;
			     End If;
			   
			  END chk_tax_PI_BILL_MST;
/


--
-- GLS_VCHR_MST_DEL_INSTLMNT_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_VCHR_MST_DEL_INSTLMNT_Trgr
				BEFORE DELETE OR INSERT OR UPDATE
				OF V_SER
				ON IAS20261.VOUCHERS
				REFERENCING NEW AS NEW OLD AS OLD
				FOR EACH ROW
DECLARE
				 ----------------------------------
				 
				 -- Created by  MURAD ALGARRASH
				 -- Date       17/02/2020 
				 
				 ----------------------------------
				  V_VCHR_DATE DATE;
				  Ino Number:=1;  
				BEGIN
				If DELETING Then --(((1)
  IF :OLD.VOUCHER_TYPE=1 AND :OLD.V_ser IS NOT NULL   THEN
     
             Begin
                If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type  => 2
                                                                   ,p_doc_ser   => :OLD.V_ser) = 1     Then
                 
                 Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
                End If ;   
                If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>2
                                                         ,p_doc_ser   => :OLD.V_ser) = 1     Then
                  Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);  
                End If ;                
             Exception
                When Others Then
                Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
             End ;    
                              
            Begin
               If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 2               
                                                                    ,P_Doc_Ser   => :OLD.V_Ser
                                                                   ,P_Paid_Type => 1                    ) = 1     Then
                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1239)||SqlErrm);     
               End If ;
            end;            
                              
            Begin
                Delete From Installment
                where Doc_Type = 2
                and bill_ser = :OLD.V_ser;
            Exception
            When Others Then
              Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
            End ;    
            ------------------------------------------------
            -----------------------------------------------------------------------------
            --MDR  MULTI MASTER 
            --## Check Installment Trans    
            --- Installment Pi
            Begin
               If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  =>2
                                                                  ,p_doc_ser   => :OLD.V_ser) = 1     Then
                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
               End If ;   
               If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>2
                                                          ,p_doc_ser   => :old.V_ser) = 1     Then
                  Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
               End If ;                
            Exception
                 When Others Then
                 Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
            End ;    
               -----------------------------------------------------------------------------
              Begin
                   Delete From ias_Installment_pi
                    where Doc_Type =2
                      and bill_ser = :OLD.V_ser
                      and i_py=0;
              Exception
                    When Others Then
                   Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
              End ;    
 ---------------------------------------------------------------------------------------------------
 ELSIF  :OLD.VOUCHER_TYPE=2 AND :OLD.V_ser IS NOT NULL   THEN
 ---------------------------------------------------------------------------------------------------   
               Begin
                If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type  =>3,
                                                                 p_doc_ser   => :OLD.V_ser) = 1     Then
                       Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   
                End If ;   
                If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>3,
                                                          p_doc_ser   => :OLD.V_ser) = 1     Then
                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
                End If ;                
            Exception
                    When Others Then
                     Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
            End ;    
              
              Begin
                   If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 3                   ,
                                                                   P_Doc_Ser   => :OLD.V_Ser,
                                                                   P_Paid_Type => 1                    ) = 1     Then
                     Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1239)||SqlErrm);     
                   End If ;
              end;            
              
              Begin
                   Delete From Installment
                    where Doc_Type = 3
                      and bill_ser = :OLD.V_ser;
              Exception
                     When Others Then
                      Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
              End ;    
            ------------------------------------------------
            -----------------------------------------------------------------------------
            --MDR  MULTI MASTER 
            --## Check Installment Trans    
            --- Installment Pi
          Begin
               If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  =>3,
                                                                   p_doc_ser   => :OLD.V_ser) = 1     Then
                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);    
               End If ;   
               If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>3,
                                                          p_doc_ser   => :OLD.V_ser) = 1     Then
                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   
               End If ;                
            Exception
                When Others Then
                Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
            End ;    
           -----------------------------------------------------------------------------
          Begin
               Delete From ias_Installment_pi
                where Doc_Type = 3
                  and bill_ser = :OLD.V_ser
                  and i_py=0;
          Exception
                When Others Then
                 Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
            End ;    
    
   END IF;
END IF;
 EXCEPTION WHEN OTHERS THEN
   Raise_Application_Error(-20303,' Error When Deleting Installment Trans. '||SqlErrm);
END GLS_VCHR_MST_DEL_INSTLMNT_Trgr;
/


--
-- IAS_DECR_AVLQTY_STRGE_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_DECR_AVLQTY_STRGE_Tgr
BEFORE DELETE ON IAS20261.ITEM_MOVEMENT   FOR EACH ROW
BEGIN
--## For Incoming
    If :OLD.IN_OUT = 1 Then
            Update Ias_Itm_Wcode Set Avl_Qty = nvl(Avl_Qty,0) - ((nvl(:OLD.I_qty,0)+ nvl(:OLD.FREE_Qty,0))*:OLD.P_SIZE)
             Where I_Code  = :Old.I_Code
             --And Itm_Unt = :Old.Itm_Unt
               And w_code  = :Old.W_CODE;

             Begin
               Update Ias_Itm_Sales_Age 
                Set    Doc_Ser_Inc    = Null ,
                       Doc_Seq_Inc    = Null ,
                       First_Inc_Date = Null
                 Where I_Code         = :Old.I_Code
                   And Itm_Unt        = :Old.Itm_Unt
                   And W_Code         = :Old.W_Code
                   And Brn_Year       = :Old.Brn_Year
                   And Doc_Ser_Inc    = :Old.Doc_Ser
                   And Doc_Seq_Inc    = :Old.Doc_Sequence ;
             Exception
               When Others Then
                Null ;
             End ;
             
--## For Outgoing

  Else
            
            Update Ias_Itm_Wcode Set Avl_Qty = nvl(Avl_Qty,0) +  ((nvl(:OLD.I_qty,0)+ nvl(:OLD.FREE_Qty,0))*:OLD.P_SIZE)
             Where I_Code  = :Old.I_Code
             --And Itm_Unt = :Old.Itm_Unt
               And w_code  = :Old.W_Code;
     Begin
        Delete From Ias_Itm_Sales_Age
         Where I_Code        = :Old.I_Code
          And Itm_Unt        = :Old.Itm_Unt
          And  W_Code        = :Old.W_Code
          And  Brn_Year      = :Old.Brn_Year
          And  Doc_Ser_Out   = :Old.Doc_Ser
          And  Doc_Seq_out   = :Old.Doc_Sequence ;
     Exception
       When Others Then
        Null ;
     End ;
  End If;
  
Exception When Others Then
 Raise_Application_Error (-20301,'Error In DecrTrg. When Update Ias_Itm_Wcode AvlQty ='||SqlErrm);
End;
/


--
-- IAS_INCR_AVLQTY_STRGE_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_INCR_AVLQTY_STRGE_Tgr
		AFTER INSERT ON IAS20261.ITEM_MOVEMENT REFERENCING NEW AS NEW OLD AS OLD
		FOR EACH ROW
DECLARE
		 V_AVLQTY  NUMBER;
		 V_Cnt     Number := 0 ;
		Begin
		
		 Select Ias_Itm_Pkg.Get_grand_Avlqty (:NEW.I_CODE,:NEW.W_CODE)
		   Into V_AVLQTY
		   From Dual;
		 
		--## For Incoming
		
		 If :NEW.IN_OUT = 1 Then
		            
		            Update Ias_Itm_Wcode Set avl_qty = nvl(V_AVLQTY,0) + ((nvl(:NEW.I_QTY,0)+ nvl(:NEW.FREE_QTY,0))*:NEW.P_SIZE)
		             Where I_Code  = :NEW.I_Code
		             --And Itm_Unt = :NEW.Itm_Unt
		               And W_Code  = :NEW.W_Code;
		
		         If Sql%NotFound Then
		            Insert Into Ias_Itm_Wcode(  I_CODE, 
	                                          Itm_Unt, 
	                                          P_SIZE,
	                                          W_CODE, 
	                                          AVL_QTY,
	                                          Whg_Code,
                                            Primary_Cost,
                                            I_Cwtavg,
                                            Inactive)
	                                  VALUES( :NEW.I_CODE, 
	                                          Ias_Itm_Pkg.Get_Icode_Min_Unit (P_I_Code => :NEW.I_CODE), 
	                                          1,
	                                          :NEW.W_CODE, 
	                                          ((nvl(:NEW.I_QTY,0)+ nvl(:NEW.FREE_QTY,0))*:NEW.P_SIZE),
	                                          Ias_Wcode_Pkg.Get_Whg_Code  (:New.W_Code),
                                            0,
                                            Nvl(Ias_Itm_Pkg.Get_Grand_Wtavg( P_Wtavg_Type => (select Wtavg_Type from Ias_Para_Inv Where RowNum<=1),
                                                                         P_Icode      => :NEW.I_CODE ,
                                                                         P_Wcode      => :NEW.W_CODE ),0),
                                            0);
		         End If;
	
		              
		         If  Nvl(V_AVLQTY,0) = 0 And :New.Doc_Type <> 0 Then
		             Begin
		               Update Ias_Itm_Sales_Age 
		                Set    Doc_Ser_Inc    = :New.Doc_Ser      ,
		                       Doc_Seq_Inc    = :New.Doc_Sequence ,
		                       First_Inc_Date = :New.I_Date
		                 Where I_Code         = :New.I_Code
		                   And Itm_Unt        = :New.Itm_Unt
		                   And W_Code         = :New.W_Code
		                   And Brn_Year       = :New.Brn_Year
		                   And Doc_Ser_Out Is Not Null
		                   And Doc_Seq_Out Is Not Null
		                   And Doc_Ser_Inc Is Null
		                   And Doc_Seq_Inc Is Null ; 
		             Exception
		               When Others Then
		                Null ;
		             End ;
		         End If ;
		--## For Outgoing
		
		 Else
		
		      Update Ias_Itm_Wcode Set Avl_qty = nvl(V_AVLQTY,0) - ((nvl(:NEW.I_QTY,0)+ nvl(:NEW.FREE_QTY,0))*:NEW.P_SIZE)
		       Where I_Code  = :NEW.I_Code
		       --And Itm_Unt = :NEW.Itm_Unt
		         And w_code  = :NEW.W_Code;
		    If Nvl(V_Avlqty,0) - ((Nvl(:New.I_Qty,0)+ Nvl(:New.Free_Qty,0))*:New.P_Size) = 0 Then
		       Begin
		          Insert Into Ias_Itm_Sales_Age ( I_Code         ,
		                                          Itm_Unt        ,
		                                          W_Code         , 
		                                          Last_Sale_Date ,
		                                          Last_Out_Date  ,
		                                          First_Inc_Date ,
		                                          Doc_Ser_Inc    ,
		                                          Doc_Seq_Inc    ,
		                                          Doc_Ser_Out    ,
		                                          Doc_Seq_Out    ,
		                                          Doc_Ser_Sale   ,
		                                          Doc_Seq_Sale   ,  
		                                          Ad_U_Id        ,
		                                          Up_U_Id        ,
		                                          Ad_Date        ,
		                                          Up_Date        ,
		                                          Cmp_No         ,
		                                          Brn_No         ,
		                                          Brn_Year       ,
		                                          Brn_Usr        )
		           Values ( :New.I_Code         ,
		                    :New.Itm_Unt        ,
		                    :New.W_Code         , 
		                    Decode(:New.Doc_Type,1,:New.I_Date,Null) ,
		                    :New.I_Date         ,
		                    Null                ,
		                    Null                ,
		                    Null                ,
		                    :New.Doc_Ser        ,
		                    :New.Doc_Sequence        ,
		                    Decode(:New.Doc_Type,1,:New.Doc_Ser,Null)      ,
		                    Decode(:New.Doc_Type,1,:New.Doc_Sequence,Null) ,  
		                    Null                ,
		                    Null                ,
		                    :New.Ad_Date        ,
		                    :New.Up_Date        ,
		                    :New.Cmp_No         ,
		                    :New.Brn_No         ,
		                    :New.Brn_Year       ,
		                    :New.Brn_Usr        ) ;
		       Exception
		         When Others Then
		          --Raise_Application_Error (-20303,'Error In IncrTrg. When Insert Into Ias_Itm_Sales_Age  ='||SqlErrm);
		          Null ;
		       End ;       
		    End If ;
		
		 End if;
		
		Exception When Others Then
		  Raise_Application_Error (-20302,'Error In IncrTrg. When Update Ias_Itm_Wcode AvlQty ='||SqlErrm);
		End;
/


