--
-- IAS_RET_BILL_MST_CHK_SRL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_RET_BILL_MST_CHK_SRL_TRG BEFORE INSERT OR UPDATE
ON IAS20261.IAS_RET_BILL_MST
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
BEGIN
   IF NVL(:NEW.EXTERNAL_POST,0)=0 THEN
       IF INSERTING AND AR_DOC_SQ_PKG.GET_DOC_SRL (   P_DOC_TYP       => 14,
                                                      P_PAY_TYP       => :NEW.RT_BILL_DOC_TYPE,                                                      
                                                      P_BRN_YEAR      => :NEW.BRN_YEAR,
                                                      P_BRN_NO        => :NEW.BRN_NO,
                                                      P_CC_CODE       => :NEW.CC_CODE ,
                                                      P_W_CODE        => :NEW.W_CODE,
                                                      P_TYP_NO        => :NEW.SR_TYPE,
                                                      P_DOC_NO        => :NEW.RET_NO,
                                                      P_SYS_NO        => 61,
                                                      P_USR_NO        => :NEW.AD_U_ID,
                                                      P_TRMNL_NO      => NULL                 )<>:NEW.RET_SER THEN
               RAISE_APPLICATION_ERROR(-20090,'The Serial No. For Ducument Not Currect') ; 
               
         ELSIF UPDATING THEN      
               IF :OLD.RET_NO<>:NEW.RET_NO THEN 
                  RAISE_APPLICATION_ERROR(-20091,'Error .. Can Not Update Return No') ;                    
               ELSIF :OLD.RET_SER<>:NEW.RET_SER THEN 
                  RAISE_APPLICATION_ERROR(-20092,'Error .. Can Not Update Return Serial') ;
               END IF;
       END IF;
   END IF;
       
END IAS_RET_BILL_MST_CHK_SRL_TRG;
/


--
-- MASTER_OUT_BILLS_CHK_SRL_TRG  (Trigger) 
