                                                      P_BRN_NO        => :NEW.BRN_NO,
                                                      P_CC_CODE       => :NEW.CC_CODE ,
                                                      P_W_CODE        => :NEW.W_CODE,
                                                      P_TYP_NO        => :NEW.SI_TYPE,
                                                      P_DOC_NO        => :NEW.OUT_NO,
                                                      P_SYS_NO        => 61,
                                                      P_USR_NO        => :NEW.AD_U_ID,
                                                      P_TRMNL_NO      => NULL                 )<>:NEW.OUT_SER THEN
               RAISE_APPLICATION_ERROR(-20090,'The Serial No. For Ducument Not Currect') ; 
               
         ELSIF UPDATING THEN      
               IF :OLD.OUT_NO<>:NEW.OUT_NO THEN 
                  RAISE_APPLICATION_ERROR(-20091,'Error .. Can Not Update Out No') ;                    
               ELSIF :OLD.OUT_SER<>:NEW.OUT_SER THEN 
                  RAISE_APPLICATION_ERROR(-20092,'Error .. Can Not Update Out Serial') ;
               END IF;
       END IF;
   END IF;  
END MASTER_OUT_BILLS_CHK_SRL_TRG;
