  REF_NO                    VARCHAR2(30 BYTE),
  DUE_REF_NO                VARCHAR2(30 BYTE),
  RCRD_NO                   NUMBER(10),
  RCRD_NO_ORD               NUMBER(10),
  CONN_V_NO                 NUMBER(15),
  CONN_V_SER                NUMBER(38),
