  DOC_NO_REF                NUMBER(15),
  DOC_SER_REF               NUMBER(38),
  DOC_TYPE_REF_DTL          NUMBER(5),
  DOC_JV_TYPE_REF_DTL       NUMBER(5),
  DOC_NO_REF_DTL            NUMBER(15),
  DOC_SER_REF_DTL           NUMBER(38),
  DOC_BRN_NO                NUMBER(6),
  DLVRD                     NUMBER(1)           DEFAULT 0,
  POST_U_ID                 NUMBER(5),
  POST_DATE                 DATE,
  UNPOST_U_ID               NUMBER(5),
  UNPOST_DATE               DATE,
  F_CNTRCT_DATE             DATE,
  T_CNTRCT_DATE             DATE,
  F_CNTRCT_DATE_AH          VARCHAR2(10 BYTE),
