  CRD_ACODE_REC_LETTER      VARCHAR2(30 BYTE),
  CRD_COMM_AC               VARCHAR2(30 BYTE),
  CRD_COMM_CALC_TYP         NUMBER(1),
  CRD_COMM_PER              NUMBER              DEFAULT 0,
