  CRD_DUE_PRD               NUMBER,
  CRD_PRCSS_MAX_COMM_AMT    NUMBER,
  CRD_PRSSES_NO             NUMBER(20),
  CRD_COMM_AMT_L            NUMBER              DEFAULT 0,
