  ENDRSMNT_AUDIT_REF_DESC   VARCHAR2(500 BYTE),
  ENDRSMNT_AUDIT_REF_DATE   DATE,
  FLD1                      VARCHAR2(60 BYTE),
  FLD2                      VARCHAR2(60 BYTE),
  FLD3                      VARCHAR2(60 BYTE),
  FLD4                      VARCHAR2(60 BYTE),
  FLD5                      VARCHAR2(60 BYTE),
  AD_U_ID                   NUMBER(5),
