  UP_U_ID                   NUMBER(5),
  UP_DATE                   DATE,
  UP_CNT                    NUMBER(10),
  CMP_NO                    NUMBER(3),
  BRN_NO                    NUMBER(6),
  BRN_YEAR                  NUMBER(4),
  BRN_USR                   NUMBER(3),
  ENDRSMNT_UAUDIT_REF_DATE  DATE,
  AR_BILL_NO                NUMBER(15),
  AR_BILL_SER               NUMBER(38),
  DRIVER_NO                 NUMBER(10),
  RCRD_NO_REF               NUMBER(10)
)
