--
-- APS_KPI_ALL_TRNS_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_ALL_TRNS_VW
(DOC_NO, DOC_SRL, DOC_DATE, BRN_NO, BRN_NM, 
 ITM_CODE, ITM_NM, ITM_UNT, MAX_ITM_UNT, MAX_P_SIZE, 
 G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, SUBG_CODE, 
 SUBG_CODE_NM, ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, ALTRNTV_GRP_NM, 
 ITM_TYP_NM, GRP_CLASS_NM, ITM_DSC, W_CODE, W_NM, 
 V_CODE, V_NM, CC_CODE, CC_NM, PJ_NO, 
 PJ_NM, ACTV_NO, ACTV_NM, PR_QTY, PO_QTY_NOT_APRV, 
 PO_QTY_APRV, PI_QTY, PI_QTY_WITH_PO, FRGN_PI_QTY_WITH_PO, FRGN_PI_QTY, 
 FRGN_GOOD_QTY_WITH_COST, FRGN_GOOD_QTY_NO_COST, GRN_QTY, GRN_QTY_WITH_PO, GRN_QTY_WITH_PR, 
 PI_RCV_QTY, PI_RCV_QTY_WITH_PO, PI_QTY_WITH_RCV)
BEQUEATH DEFINER
AS 
WITH
        LNG
        AS
            (SELECT (SELECT NVL (
                                IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                1)
                       FROM DUAL)
                        LNG_NO
               FROM DUAL)
    SELECT DOC_NO,
           DOC_SRL,
           DOC_DATE,
           M.BRN_NO,
              M.BRN_NO
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (BRN_LNAME, BRN_FNAME),
                              NVL (BRN_FNAME, BRN_LNAME))
                 FROM S_BRN
                WHERE BRN_NO = M.BRN_NO AND ROWNUM <= 1)
               BRN_NM,
           I.I_CODE
               ITM_CODE,
           DECODE (LNG.LNG_NO, 1, I.I_NAME, NVL (I.I_E_NAME, I.I_NAME))
               ITM_NM,
           (SELECT ITM_UNT
              FROM IAS_ITM_DTL
             WHERE     IAS_ITM_DTL.I_CODE = M.I_CODE
                   AND NVL (IAS_ITM_DTL.P_SIZE, 0) = 1
                   AND NVL (IAS_ITM_DTL.MAIN_UNIT, 0) = 1
                   AND ROWNUM <= 1)
               ITM_UNT,
           (SELECT ITM_UNT
              FROM IAS_ITM_DTL
             WHERE     I_CODE = M.I_CODE
                   AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                     FROM IAS_ITM_DTL
                                    WHERE I_CODE = M.I_CODE)
                   AND ROWNUM <= 1)
               MAX_ITM_UNT,
           (SELECT P_SIZE
              FROM IAS_ITM_DTL
             WHERE     I_CODE = M.I_CODE
                   AND ITM_UNT =
                       (SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE     I_CODE = M.I_CODE
                               AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                                 FROM IAS_ITM_DTL
                                                WHERE I_CODE = M.I_CODE)
                               AND ROWNUM <= 1)
                   AND ROWNUM <= 1)
               MAX_P_SIZE,
           I.G_CODE,
              I.G_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (GRP.G_A_NAME, GRP.G_E_NAME),
                              NVL (GRP.G_E_NAME, GRP.G_A_NAME))
                          GRP_NM
                 FROM GROUP_DETAILS GRP
                WHERE GRP.G_CODE = I.G_CODE AND ROWNUM <= 1)
               GRP_CODE_NM,
           I.MNG_CODE,
              I.MNG_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (GRP.MNG_A_NAME, GRP.MNG_E_NAME),
                              NVL (GRP.MNG_E_NAME, GRP.MNG_A_NAME))
                          GRP_NM
                 FROM IAS_MAINSUB_GRP_DTL GRP
                WHERE     MNG_CODE = I.MNG_CODE
                      AND NVL (I.G_CODE, '0') =
                          DECODE (NVL (G_CODE, '0'),
                                  '0', NVL (I.G_CODE, '0'),
                                  G_CODE)
                      AND ROWNUM <= 1)
               MNG_CODE_NM,
           I.SUBG_CODE,
              I.SUBG_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (GRP.SUBG_A_NAME, GRP.SUBG_E_NAME),
                              NVL (GRP.SUBG_E_NAME, GRP.SUBG_A_NAME))
                          GRP_NM
                 FROM IAS_SUB_GRP_DTL GRP
                WHERE     SUBG_CODE = I.SUBG_CODE
                      AND NVL (I.G_CODE, '0') =
                          DECODE (NVL (G_CODE, '0'),
                                  '0', NVL (I.G_CODE, '0'),
                                  G_CODE)
                      AND NVL (I.MNG_CODE, '0') =
                          DECODE (NVL (MNG_CODE, '0'),
                                  '0', NVL (I.MNG_CODE, '0'),
                                  MNG_CODE)
                      AND ROWNUM <= 1)
               SUBG_CODE_NM,
           I.ASSISTANT_NO,
              I.ASSISTANT_NO
           || ' - '
           || (SELECT DECODE (
                          LNG.LNG_NO,
                          1, NVL (GRP.ASSISTANT_A_NAME, GRP.ASSISTANT_E_NAME),
                          NVL (GRP.ASSISTANT_E_NAME, GRP.ASSISTANT_A_NAME))
                          GRP_NM
                 FROM IAS_ASSISTANT_GROUP GRP
                WHERE     ASSISTANT_NO = I.ASSISTANT_NO
                      AND NVL (I.G_CODE, '0') =
                          DECODE (NVL (G_CODE, '0'),
                                  '0', NVL (I.G_CODE, '0'),
                                  G_CODE)
                      AND NVL (I.MNG_CODE, '0') =
                          DECODE (NVL (MNG_CODE, '0'),
                                  '0', NVL (I.MNG_CODE, '0'),
                                  MNG_CODE)
                      AND NVL (I.SUBG_CODE, '0') =
                          DECODE (NVL (SUBG_CODE, '0'),
                                  '0', NVL (I.SUBG_CODE, '0'),
                                  SUBG_CODE)
                      AND ROWNUM <= 1)
               ASSTNT_GRP_NM,
              I.DETAIL_NO
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (GRP.DETAIL_A_NAME, GRP.DETAIL_E_NAME),
                              NVL (GRP.DETAIL_E_NAME, GRP.DETAIL_A_NAME))
                          GRP_NM
                 FROM IAS_DETAIL_GROUP GRP
                WHERE     DETAIL_NO = I.DETAIL_NO
                      AND NVL (I.G_CODE, '0') =
                          DECODE (NVL (G_CODE, '0'),
                                  '0', NVL (I.G_CODE, '0'),
                                  G_CODE)
                      AND NVL (I.MNG_CODE, '0') =
                          DECODE (NVL (MNG_CODE, '0'),
                                  '0', NVL (I.MNG_CODE, '0'),
                                  MNG_CODE)
                      AND NVL (I.SUBG_CODE, '0') =
                          DECODE (NVL (SUBG_CODE, '0'),
                                  '0', NVL (I.SUBG_CODE, '0'),
                                  SUBG_CODE)
                      AND NVL (I.ASSISTANT_NO, '0') =
                          DECODE (NVL (ASSISTANT_NO, '0'),
                                  '0', NVL (I.ASSISTANT_NO, '0'),
                                  ASSISTANT_NO)
                      AND ROWNUM <= 1)
               DTL_GRP_NM,
              I.GROUP_NO
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, A.GROUP_A_NAME,
                              NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
                 FROM IAS_ALTERNATIVE_GROUP A
                WHERE A.GROUP_NO = I.GROUP_NO AND ROWNUM <= 1)
               ALTRNTV_GRP_NM,
              I.ITEM_TYPE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, A.IT_A_NAME,
                              NVL (A.IT_E_NAME, A.IT_A_NAME))
                 FROM ITEM_TYPES A
                WHERE A.TYPE_OF_ITEM = I.ITEM_TYPE AND ROWNUM <= 1)
               ITM_TYP_NM,
              I.GRP_CLASS_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, A.GRP_L_NAME,
                              NVL (A.GRP_F_NAME, A.GRP_L_NAME))
                 FROM IAS_GRP_ITM_LVL A
                WHERE A.GRP_CODE = I.GRP_CLASS_CODE AND ROWNUM <= 1)
               GRP_CLASS_NM,
           DECODE (LNG.LNG_NO, 1, I.I_DESC, NVL (I.I_F_DESC, I.I_DESC))
               ITM_DSC,
           M.W_CODE,
              M.W_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (W_NAME, W_E_NAME),
                              NVL (W_E_NAME, W_NAME))
                 FROM WAREHOUSE_DETAILS
                WHERE W_CODE = M.W_CODE AND ROWNUM <= 1)
               W_NM,
           M.V_CODE,
           Ias_Vndr_Pkg.Get_V_Name (M.V_CODE, LNG.LNG_NO)
               V_NM,
           M.CC_CODE,
              M.CC_CODE
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (CC_A_NAME, CC_E_NAME),
                              NVL (CC_E_NAME, CC_A_NAME))
                 FROM COST_CENTERS
                WHERE CC_CODE = M.CC_CODE AND ROWNUM <= 1)
               CC_NM,
           M.PJ_NO,
              M.PJ_NO
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (PJ_A_NAME, PJ_E_NAME),
                              NVL (PJ_A_NAME, PJ_E_NAME))
                 FROM IAS_PROJECTS
                WHERE PJ_NO = M.PJ_NO AND ROWNUM <= 1)
               PJ_NM,
           M.ACTV_NO,
              M.ACTV_NO
           || ' - '
           || (SELECT DECODE (LNG.LNG_NO,
                              1, NVL (ACTV_A_NAME, ACTV_E_NAME),
                              NVL (ACTV_E_NAME, ACTV_A_NAME))
                 FROM IAS_ACTVTY
                WHERE ACTV_NO = M.ACTV_NO AND ROWNUM <= 1)
               ACTV_NM,
           PR_QTY,
           PO_QTY_NOT_APRV,
           PO_QTY_APRV,
           PI_QTY,
           PI_QTY_WITH_PO,
           FRGN_PI_QTY_WITH_PO,
           FRGN_PI_QTY,
           FRGN_GOOD_QTY_WITH_COST,
           FRGN_GOOD_QTY_NO_COST,
           GRN_QTY,
           GRN_QTY_WITH_PO,
           GRN_QTY_WITH_PR,
           PI_RCV_QTY,
           PI_RCV_QTY_WITH_PO,
           PI_QTY_WITH_RCV
      FROM (SELECT M.Brn_No,
                   D.Cc_Code,
                   D.Pj_No,
                   D.Actv_No,
                   D.W_Code,
                   D.I_Code,
