--
-- APS_V_GLS_INSTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_GLS_INSTL
(DOC_TYP_INSTL1, DOC_TYP_INSTL2, DOC_TYP_INSTL3, DOC_TYP_INSTL4, DOC_TYP, 
 LOV_NM, TBL_NM_MST, TBL_NM_DTL, DOC_SRL, BRN_NO, 
 DOC_NO, DOC_DATE, DOC_JV_TYPE_REF, HSTR, AC_CODE, 
 AC_CODE_DTL, AC_CODE_DTL_SUB, V_NAME, CLC_TYP_NO_TAX, CUR_CODE, 
 CUR_RATE, COL_NO, REP_CODE, DOC_BRN_NO, AC_DTL_TYP, 
 DOC_DSC, REF_NO, CC_CODE, PJ_NO, ACTV_NO, 
 GLS_PRCSSD_FLG, AD_U_ID, NEED_PMAN_FIN_TRST, DOC_AMT, PAID_AMT, 
 REM_AMT)
BEQUEATH DEFINER
AS 
With
        Bal_vw
        As
            (  Select Case When A_cy = Ys_gen_pkg.Get_local_cur Then Sum (Abs (Ac_amt))   Else Sum (Abs (Ac_amtf)) End  Sum_ac_amt,
                      Doc_ser_ref_dtl,
                      Doc_ser_ref,
                      Ac_code_dtl,
                      Ac_code_dtl_sub
                 From Voucher_detail
             Group By Ac_amt,
                      Doc_ser_ref_dtl,
                      A_cy,
                      Doc_ser_ref,
                      Ac_code_dtl,
                      Ac_code_dtl_sub),
        Bal_rq_vw
        As
            (  Select  Case When Ias_rq_vchr_dtl.A_cy = Ys_gen_pkg.Get_local_cur Then Sum (Abs (Ac_amt))   Else Sum (Abs (Ac_amtf)) End   Sum_ac_rq_amt,
                      Doc_ser_ref,
                      Ac_code_dtl,
                      Ac_code_dtl_sub
                 From Ias_rq_vchr_dtl, Ias_rq_vchr_mst
                Where     Ias_rq_vchr_dtl.V_ser = Ias_rq_vchr_mst.V_ser
                      And Nvl (Procesed, 0) = 0
                      And Nvl (Approved, 0) = 1
             Group By Ac_amt,
                     Ias_rq_vchr_dtl.A_cy,
                      Doc_ser_ref,
                      Ac_code_dtl,
                      Ac_code_dtl_sub),
        Para
        As
            (Select Nvl (No_of_decimal_ap, 2)       No_of_decimal,
                    Nvl (Use_advnc_pymnt, 0)     Use_advnc_pymnt,
                    Nvl (Use_e_invoice, 0)       Use_e_invoice
               From Ias_para_gl, Ias_para_ar, Ias_para_gen,Ias_Para_ap
              Where Rownum <= 1),
        Claim
        As
            (Select M.Doc_ser,
                    M.Brn_no,
                    M.Doc_no,
                    M.Doc_date,
                    M.V_code,
                    0                           Ptnt_no,
                    M.A_cy,
                    M.Doc_dsc,
                    M.Ref_no,
                    M.Processed,
                    M.Approved,
                    M.Ad_u_id,
                    D.Net_amt,
                    Nvl (D.Net_bill_amt, 0)     Net_bill_amt
               From Ias_vndr_claim_mst M, Ias_vndr_claim_dtl D
              Where M.Doc_ser = D.Doc_ser)
      Select 3
                 Doc_typ_instl1,
             93
                 Doc_typ_instl2,
             Null
                 Doc_typ_instl3,
             Null
                 Doc_typ_instl4,
             158
                 Doc_typ,
             'Lov_gls_aps_instl'
                 Lov_nm,
             'Ias_vndr_claim_mst'
                 Tbl_nm_mst,
             'Ias_vndr_claim_dtl'
                 Tbl_nm_dtl,
             M.Doc_ser
                 Doc_srl,
             M.Brn_no
                 Brn_no,
             M.Doc_no
                 Doc_no,
             M.Doc_date
                 Doc_date,
             158
                 Doc_jv_type_ref,
             0
                 Hstry,
             C.V_a_code
                 Ac_code,
             M.V_code
                 Ac_code_dtl,
             0
                 Ac_code_dtl_sub,
             Nvl (V_a_name, V_e_name)
                 V_name,
             Null,
             M.A_cy
                 Cur_code,
             Null
                 Cur_rate,
             Null
                 Col_no,
             Null
                 Rep_code,
             Null
                 Doc_brn_no,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.V_a_code)
                 Ac_dtl_typ,
             M.Doc_dsc
                 Doc_dsc,
             M.Ref_no,
             Null
                 Cc_code,
             Null
                 Pj_no,
             Null
                 Actv_no,
             M.Processed
                 Gls_prcssd_flg,
             M.Ad_u_id,
             Null,
             Round (Sum (Nvl (M.Net_bill_amt, 0)), Max (Para.No_of_decimal))
                 Doc_amt,
             Round (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0),
                    Max (Para.No_of_decimal))
                 Paid_amt,
             Round (
                   Sum (Nvl (M.Net_bill_amt, 0))
                 - Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0),
                 Max (Para.No_of_decimal))
                 Rem_amt
        From Claim    M,
             V_details C,
             Bal_vw,
             Para
       Where     M.Doc_ser = M.Doc_ser
             And M.V_code = C.V_code
             And Nvl (Bal_vw.Ac_code_dtl(+), '0') = Nvl (M.V_code, '0')
             And Bal_vw.Doc_ser_ref(+) = M.Doc_ser
             And M.Approved = 1
      Having (Sum (Nvl (M.Net_bill_amt, 0)) - Sum (Nvl (Bal_vw.Sum_ac_amt, 0))) >
             0
    Group By 3,
             93,
             158,
             'Lov_gls_aps_instl',
             'Ias_vndr_claim_mst',
             'Ias_vndr_claim_dtl',
             M.Doc_ser,
             M.Brn_no,
             M.Doc_no,
             M.Doc_date,
             0,
             C.V_a_code,
             M.V_code,
             158,
             0,
             Nvl (V_a_name, V_e_name),
             M.A_cy,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.V_a_code),
             M.Doc_dsc,
             M.Ref_no,
             M.Processed,
             M.Ad_u_id
    Union All
      Select 3
                 Doc_typ_instl1,
             93
                 Doc_typ_instl2,
             Null
                 Doc_typ_instl3,
             Null
                 Doc_typ_instl4,
             42
                 Doc_typ,
             'Lov_gls_aps_instl'
                 Lov_nm,
             'P_order'
                 Tbl_nm_mst,
             'P_order_detail'
                 Tbl_nm_dtl,
             M.Po_ser
                 Doc_srl,
             M.Brn_no
                 Brn_no,
             M.Po_no
                 Doc_no,
             M.Po_date
                 Doc_date,
             M.Po_type
                 Doc_jv_type_ref,
             0
                 Hstry,
             C.P_a_code
                 Ac_code,
             C.Ac_code_dtl
                 Ac_code_dtl,
             0
                 Ac_code_dtl_sub,
             Nvl (Pman_a_name, Pman_e_name),
             M.Clc_typ_no_tax
                 Pman_name,
             M.Cur_code
                 Cur_code,
             Null
                 Cur_rate,
             Null
                 Col_no,
             Null
                 Rep_code,
             Null
                 Doc_brn_no,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.P_a_code)
                 Ac_dtl_typ,
             M.Po_desc
                 Doc_dsc,
             M.Ref_no,
             M.Cc_code,
             M.Pj_no,
             M.Actv_no,
             M.Po_processed
                 Gls_prcssd_flg,
             M.Ad_u_id,
             T.Need_pman_fin_trst,
             Round (
                 Sum (
                       Nvl (D.I_qty, 0)
                     * (  (  Nvl (D.I_price, 0)
                           + Nvl (D.Vat_amt, 0)
                           + Nvl (D.Othr_amt, 0))
                        - (Nvl (D.Dis_amt, 0)))),
                 Max (Para.No_of_decimal))
                 Doc_amt,
             (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               +
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser)
                 Paid_amt,
             Round (
                   Sum (
                         Nvl (D.I_qty, 0)
                       * (  (  Nvl (D.I_price, 0)
                             + Nvl (D.Vat_amt, 0)
                             + Nvl (D.Othr_amt, 0))
                          - (Nvl (D.Dis_amt, 0))))
                 - (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               -
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser),
                 Max (Para.No_of_decimal))
                 Rem_amt
        From P_order         M,
             P_order_detail  D,
             Ias_purchs_man  C,
             Para,
             Ias_porder_types T
       Where     M.Po_ser = D.Po_ser
             And M.Pman_code = C.Pman_code
             And M.Po_type = T.Po_type
             And M.Approved = 1
             And T.Need_pman_fin_trst = 1
      Having (  Sum (
                      Nvl (D.I_qty, 0)
                    * (  (  Nvl (D.I_price, 0)
                          + Nvl (D.Vat_amt, 0)
                          + Nvl (D.Othr_amt, 0))
                       - (Nvl (D.Dis_amt, 0))))
              - (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               -
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser)) >
             0
    Group By 2,
             93,
             42,
             'Lov_gls_aps_instl',
             'P_order',
             'P_order_detail',
             M.Po_ser,
             M.Brn_no,
             M.Po_no,
             M.Po_date,
             M.Po_type,
             0,
             C.P_a_code,
             C.Ac_code_dtl,
             0,
             Nvl (Pman_a_name, Pman_e_name),
             M.Clc_typ_no_tax,
             M.Cur_code,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.P_a_code),
             M.Po_desc,
             M.Ref_no,
             M.Cc_code,
             M.Pj_no,
             M.Actv_no,
             M.Po_processed,
             M.Ad_u_id,
             T.Need_pman_fin_trst
    Union All
      Select 3
                 Doc_typ_instl1,
             93
                 Doc_typ_instl2,
             Null
                 Doc_typ_instl3,
             Null
                 Doc_typ_instl4,
             42
                 Doc_typ,
             'Lov_gls_aps_instl'
                 Lov_nm,
             'P_order'
                 Tbl_nm_mst,
             'P_order_detail'
                 Tbl_nm_dtl,
             M.Po_ser
                 Doc_srl,
             M.Brn_no
                 Brn_no,
             M.Po_no
                 Doc_no,
             M.Po_date
                 Doc_date,
             M.Po_type
                 Doc_jv_type_ref,
             0
                 Hstry,
             (Case
                  When Ias_vndr_pkg.Get_advnc_pymnt_type (P_v_code => C.V_code) =
                       1
                  Then
                      C.V_a_code
                  Else
                      Nvl (Ias_vndr_pkg.Get_intrfc_accnt (C.V_code, 2),
                           C.V_a_code)
              End)
                 Ac_code,
             C.V_code
                 Ac_code_dtl,
             0
                 Ac_code_dtl_sub,
             Nvl (V_a_name, V_e_name),
             M.Clc_typ_no_tax
                 V_name,
             M.Cur_code
                 Cur_code,
             Null
                 Cur_rate,
             Null
                 Col_no,
             Null
                 Rep_code,
             Null
                 Doc_brn_no,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.V_a_code)
                 Ac_dtl_typ,
             M.Po_desc
                 Doc_dsc,
             M.Ref_no,
             M.Cc_code,
             M.Pj_no,
             M.Actv_no,
             M.Po_processed
                 Gls_prcssd_flg,
             M.Ad_u_id,
             T.Need_pman_fin_trst,
             Sum (
                   Nvl (D.I_qty, 0)
                 * (  (  Nvl (D.I_price, 0)
                       + Nvl (D.Vat_amt, 0)
                       + Nvl (D.Othr_amt, 0))
                    - (Nvl (D.Dis_amt, 0))))
                 Doc_amt,
             (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               +
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser)
                 Paid_amt,
             Round (
                   Sum (
                         Nvl (D.I_qty, 0)
                       * (  (  Nvl (D.I_price, 0)
                             + Nvl (D.Vat_amt, 0)
                             + Nvl (D.Othr_amt, 0))
                          - (Nvl (D.Dis_amt, 0))))
                 - (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               -
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser),
                 Max (Para.No_of_decimal))
                 Rem_amt
        From P_order         M,
             P_order_detail  D,
             V_details       C,
             Para,
             Ias_porder_types T
       Where     M.Po_ser = D.Po_ser
             And M.V_code = C.V_code
             And M.Po_type = T.Po_type
             And M.Approved = 1
             And T.Need_pman_fin_trst = 0
      Having (  Sum (
                      Nvl (D.I_qty, 0)
                    * (  (  Nvl (D.I_price, 0)
                          + Nvl (D.Vat_amt, 0)
                          + Nvl (D.Othr_amt, 0))
                       - (Nvl (D.Dis_amt, 0))))
              - (Select (Nvl (Sum (Abs (Bal_vw.Sum_ac_amt)), 0))
                From Bal_vw
               Where Nvl (Bal_vw.Doc_ser_ref_dtl(+), Bal_vw.Doc_ser_ref(+)) =M.Po_ser)
               -
               (Select (Nvl (Sum (Abs (Bal_rq_vw.Sum_ac_rq_amt)), 0))
                From Bal_rq_vw
               Where Bal_rq_vw.Doc_ser_ref =M.Po_ser)) >
             0
    Group By 2,
             93,
             42,
             'Lov_gls_aps_instl',
             'P_order',
             'P_order_detail',
             M.Po_ser,
             M.Brn_no,
             M.Po_no,
             M.Po_date,
             M.Po_type,
             C.V_code,
             C.V_a_code,
             Nvl (V_a_name, V_e_name),
             M.Clc_typ_no_tax,
             M.Cur_code,
             Ys_ac_dtl_pkg.Get_ac_dtl_typ (C.V_a_code),
