--
-- APS_V_P_REQST_WTH_ARS_QUOT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_P_REQST_WTH_ARS_QUOT
(ROWDTL, QT_TYPE, QUOT_NO, QUOT_DATE, C_NAME, 
 A_DESC, REF_NO, QUOT_SER, BRN_NO, I_CODE, 
 ITM_UNT, P_SIZE, P_QTY, REC_ATTCH, WT_UNT, 
 WT_QTY, ARGMNT_NO, I_LENGTH, I_WIDTH, I_HEIGHT, 
 I_NUMBER, W_CODE, REM_QTY, REQ_QTY, SALES_QTY, 
 CC_CODE, PJ_NO, ACTV_NO, BATCH_NO, DOC_SEQ, 
 RCRD_NO, PROCESSED, APPROVED)
BEQUEATH DEFINER
AS 
SELECT QUOTATION_DETAIL.ROWID                                                                                                                                          ROWDTL
          ,QUOTATION.Qt_Type
          ,QUOTATION.QUOT_no
          ,QUOTATION.QUOT_Date
          ,QUOTATION.C_Name
          ,QUOTATION.A_Desc
          ,QUOTATION.REF_NO
          ,QUOTATION.QUOT_Ser
          ,QUOTATION.Brn_No
          ,QUOTATION_DETAIL.I_Code
          ,QUOTATION_DETAIL.itm_unt
          ,QUOTATION_DETAIL.P_Size
          ,QUOTATION_DETAIL.P_Qty
          ,QUOTATION_DETAIL.Rec_Attch
          ,QUOTATION_DETAIL.wt_unt
          ,QUOTATION_DETAIL.wt_qty
          ,QUOTATION_DETAIL.Argmnt_No
          ,QUOTATION_DETAIL.I_Length
          ,QUOTATION_DETAIL.I_Width
          ,QUOTATION_DETAIL.I_Height
          ,QUOTATION_DETAIL.I_Number
          ,QUOTATION_DETAIL.W_Code
          ,(((NVL (SUM (QUOTATION_DETAIL.P_Qty), 0)) / NVL (QUOTATION_DETAIL.P_Size, 1)) - (NVL (SUM (P_Request_detail.P_Qty), 0)) / NVL (QUOTATION_DETAIL.P_Size, 1))     Rem_qty
          ,(NVL (SUM (P_Request_detail.P_Qty), 0)) / NVL (QUOTATION_DETAIL.P_Size, 1)                                                                                      REQ_QTY
          ,(NVL (SUM (QUOTATION_DETAIL.P_Qty), 0)) / NVL (QUOTATION_DETAIL.P_Size, 1)                                                                                      Sales_QTY
          ,QUOTATION_DETAIL.cc_code
          ,QUOTATION_DETAIL.pj_no
          ,QUOTATION_DETAIL.actv_no
          ,QUOTATION_DETAIL.batch_no
          ,QUOTATION_DETAIL.DOC_SEQ
          ,QUOTATION_DETAIL.rcrd_no
          ,QUOTATION.PROCESSED
          ,QUOTATION.APPROVED
    FROM QUOTATION, QUOTATION_DETAIL, P_Request_detail
    WHERE QUOTATION.QUOT_no = QUOTATION_DETAIL.QUOT_no AND QUOTATION.QUOT_Ser = QUOTATION_DETAIL.QUOT_Ser AND QUOTATION_DETAIL.i_code = P_Request_detail.i_code(+) AND QUOTATION_DETAIL.QUOT_Ser = P_Request_detail.Out_Req_Ser(+) AND QUOTATION_DETAIL.Rcrd_No = P_Request_detail.DOC_SEQUENCE_REF(+) AND QUOTATION.Approved = 1
    HAVING NVL (SUM (QUOTATION_DETAIL.P_Qty), 0) - (NVL (SUM (P_Request_detail.P_Qty), 0)) > 0
    GROUP BY QUOTATION_DETAIL.ROWID
            ,QUOTATION.QT_TYPE
            ,QUOTATION.QUOT_No
            ,QUOTATION.QUOT_Date
            ,QUOTATION.C_Name
            ,QUOTATION.A_Desc
            ,QUOTATION.REF_NO
            ,QUOTATION.QUOT_Ser
            ,QUOTATION.Brn_No
            ,QUOTATION_DETAIL.I_Code
            ,QUOTATION_DETAIL.I_Qty
            ,QUOTATION_DETAIL.itm_unt
            ,QUOTATION_DETAIL.P_Size
            ,QUOTATION_DETAIL.P_Qty
            ,QUOTATION_DETAIL.Rec_Attch
            ,QUOTATION_DETAIL.wt_unt
            ,QUOTATION_DETAIL.wt_qty
            ,QUOTATION_DETAIL.Argmnt_No
            ,QUOTATION_DETAIL.I_Length
            ,QUOTATION_DETAIL.I_Width
            ,QUOTATION_DETAIL.I_Height
            ,QUOTATION_DETAIL.I_Number
            ,QUOTATION_DETAIL.W_Code
            ,QUOTATION_DETAIL.cc_code
            ,QUOTATION_DETAIL.pj_no
            ,QUOTATION_DETAIL.actv_no
            ,QUOTATION_DETAIL.batch_no
            ,QUOTATION_DETAIL.DOC_SEQ
            ,QUOTATION_DETAIL.rcrd_no
            ,QUOTATION.PROCESSED
            ,QUOTATION.APPROVED;

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.A_DESC IS '146 - «·»Ì«‰';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.REF_NO IS '143 - —ﬁ„ «·„—Ã⁄';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';

COMMENT ON COLUMN IAS20261.APS_V_P_REQST_WTH_ARS_QUOT.DOC_SEQ IS '2767 -  ”·”· «·Õ—ﬂ…';

