--
-- APS_V_TRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_TRNS
(DOC_TYP, PR_TYPE, DOC_NO, DOC_SER, PUR_NO, 
 PUR_SER, DOC_DATE, V_CODE, V_NAME, W_CODE, 
 CC_CODE, PJ_NO, ACTV_NO, HRCHY_NO, I_CODE, 
 ITM_UNT, I_QTY, I_PRICE, PRICE_VNDR, DOC_DESC, 
 REQ_AVL_DATE, PR_SELECTED, PR_PARTIAL, APPROVED, REF_NO, 
 BRN_NO)
BEQUEATH DEFINER
AS 
Select 40 Doc_Typ ,-- ÿ·» «·‘—«¡
   D.Pr_Type, D.Pr_No, D.Pr_Ser, D.Pur_No , D.Pur_Ser, 
   Pr_Date, V_Code, V_Name, NVL(M.W_Code,D.W_Code) W_CODE, NVL(M.CC_CODE,D.Cc_Code) CC_CODE, 
   D.Pj_No, D.Actv_No, Hrchy_No, 
   I_Code,Itm_Unt,I_Qty,I_Price,NULL Price_Vndr,
   Pr_Desc, Req_Avl_Date, 
   Pr_Selected, Pr_Partial, Approved,Ref_No,  M.Brn_No
From P_Request M, P_Request_Detail D
Where M.Pr_Ser = D.Pr_Ser
AND D.PUR_SER IS NOT NULL
Union
Select 41 Doc_Typ ,-- ⁄—÷ ”⁄— „‘ —Ì« 
   Null Qt_Type, D.Qt_No , D.Qt_Ser ,  D.Pur_No , D.Pur_Ser, 
   Qt_Date, V_Code, V_Name, Null W_Code,  NVL(M.CC_CODE,D.Cc_Code) CC_CODE, 
   D.Pj_No, D.Actv_No,Null Hrchy_No, 
   I_Code,Itm_Unt,I_Qty,I_Price,Null Price_Vndr,
   A_Desc,  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Vnd_Quot_Mst M, Ias_Vnd_Quot_Dtl D
Where M.Qt_Ser = D.Qt_Ser
AND D.PUR_SER IS NOT NULL
Union
Select 156 Doc_Typ ,-- «·„ﬁ«—‰Â «·›‰ÌÂ ·⁄—Ê÷ «·‘—«¡
   Null Qt_Type, D.Doc_No , D.Doc_Ser ,  D.Pur_No , D.Pur_Ser, 
   Doc_Date, V_Code, V_Name, Null W_Code,  NVL(M.CC_CODE,D.Cc_Code) CC_CODE,
   D.Pj_No, D.Actv_No,Null Hrchy_No, 
   I_Code,Itm_Unt,I_Qty,I_Price,Null Price_Vndr,
   Doc_Dsc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Aps_Qtn_Cmpr_Mst M, Ias_Aps_Qtn_Cmpr_Dtl D
Where M.Doc_Ser = D.Doc_Ser
AND D.PUR_SER IS NOT NULL
Union
Select 157 Doc_Typ ,--  —‘ÌÕ «·„ﬁ«—‰Â «·›‰ÌÂ
   Null Qt_Type, D.Doc_No , D.Doc_Ser ,  D.Pur_No ,D.Pur_Ser, 
   Doc_Date, V_Code, V_Name, Null W_Code, D.Cc_Code, 
   D.Pj_No, D.Actv_No,Null Hrchy_No, 
   I_Code,Itm_Unt,I_Qty,I_Price,Null Price_Vndr,
   Doc_Dsc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Ias_Aps_Qtn_Cmpr_Fltr_Mst M, Ias_Aps_Qtn_Cmpr_Fltr_Dtl D
Where M.Doc_Ser = D.Doc_Ser
AND D.PUR_SER IS NOT NULL
Union
Select 43 Doc_Typ ,-- «–‰  Ê—Ìœ „‘ —Ì«  „Õ·ÌÂ
   D.Grn_Type, D.Gr_No , D.G_Ser ,  D.Pur_No ,D.Pur_Ser, 
   Gr_Date, V_Code, V_Name,NVL(M.W_Code,D.W_Code) W_CODE, D.Cc_Code, 
   D.Pj_No, D.Actv_No,Null Hrchy_No, 
   I_Code,Itm_Unt,I_Qty,I_Price,Null Price_Vndr,
   A_Desc, Null  Quot_Expire_Date, 
   Null Pr_Selected,Null Pr_Partial, Approved,Ref_No,  M.Brn_No
From Grn_Master M, Grn_Detail D
Where M.G_Ser = D.G_Ser
AND D.PUR_SER IS NOT NULL
Union
Select 116 Doc_Typ ,-- ›Õ’ «Ê«„— «·‘—«¡
