CREATE OR REPLACE FORCE VIEW IAS20261.ARS_ALL_CUSTMR
(C_TYP, C_CODE, C_A_NAME, C_E_NAME, C_ADDRESS, 
 C_PHONE, C_MOBILE, CNTRY_NO, PROV_NO, CITY_NO, 
 R_CODE, BUILDING_NO, DSTRCT_NM, C_BOX_CODE, C_COM_LNAME, 
 C_COM_FNAME, SHRT_ADD, CSTMR_IDNTFR, STREET, ADD_NO, 
 CR_NO, CLC_TYP_NO_TAX, C_TAX_CODE, CLC_VAT_PRICE_TYP, CST_VAT_GRP_FLG, 
 C_CLASS_VAT, INACTIVE, BLK_LST, C_PERSON, C_GROUP_CODE, 
 C_A_CODE, CONN_BRN_NO, C_E_MAIL, LATITUDE, LONGITUDE, 
 AD_DATE, C_NOTE, C_FAX, C_WEB_SITE)
BEQUEATH DEFINER
AS 
SELECT    1 C_TYP,
           C_CODE,
           C_A_NAME,
           C_E_NAME ,
           C_ADDRESS,
           C_PHONE ,
           TO_CHAR(C_MOBILE) C_MOBILE  ,
           CNTRY_NO,
           PROV_NO,
           CITY_NO,
           R_CODE ,
           BUILDING_NO,
           DSTRCT_NM,
           C_BOX_CODE,
           C_COM_LNAME,
           C_COM_FNAME,
           SHRT_ADD,
           CSTMR_IDNTFR,
           STREET,
           ADD_NO,
           CR_NO,
           CLC_TYP_NO_TAX,
           C_TAX_CODE,
           CLC_VAT_PRICE_TYP,
           CST_VAT_GRP_FLG,
           C_CLASS_VAT,
           INACTIVE,
           BLK_LST ,
           C_PERSON,
           C_GROUP_CODE,
           C_A_CODE ,
           CONN_BRN_NO,
           C_E_MAIL,
           LATITUDE,
           LONGITUDE,
           AD_DATE,
           C_NOTE,
           C_FAX,
           C_WEB_SITE         
      FROM CUSTOMER      
    UNION ALL   
 SELECT    2   C_TYP,
           CUST_CODE  ,
           CUST_L_NM,
           CUST_F_NM,
           ADDRESS,
           TEL_NO ,
           TO_CHAR (MOBILE_NO) MOBILE_NO  ,
           CNTRY_NO,
           PROV_NO,
           CITY_NO,
           R_CODE,
           BUILDING_NO,
