           C_BOX_CODE,
           NULL     C_COM_LNAME,
           NULL     C_COM_FNAME,
           SHRT_ADD,
           CSTMR_IDNTFR,
           STREET,
           ADD_NO,
           CR_NO,
           NULL     CLC_TYP_NO_TAX,
           C_TAX_CODE,
           NULL     CLC_VAT_PRICE_TYP,
           NULL     CST_VAT_GRP_FLG,
           NULL     C_CLASS_VAT ,
           INACTIVE,
           BLK_LST ,
           NULL C_PERSON,
           NULL C_GROUP_CODE,
           NULL C_A_CODE ,
           NULL CONN_BRN_NO,
           NULL C_E_MAIL,
           NULL LATITUDE,
           NULL LONGITUDE,
           AD_DATE,
           NULL C_NOTE,
           NULL C_FAX,
           NULL C_WEB_SITE            
      FROM IAS_CASH_CUSTMR;

