--
-- DTS_RT_BILL_MST_RQ  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_RT_BILL_MST_RQ
(REP_CODE, RT_BILL_DOC_TYPE, RT_BILL_NO, RT_BILL_SER, RT_BILL_DATE, 
 RT_BILL_CURRENCY, C_CODE, DISC_AMT, DISC_AMT_MST, DISC_AMT_DTL, 
 BILL_AMT, VAT_AMT, OTHR_AMT, CC_CODE, PJ_NO, 
 ACTV_NO, REP_CODE_BILL)
BEQUEATH DEFINER
AS 
SELECT REP_CODE, RT_BILL_DOC_TYPE, RT_BILL_NO, RT_BILL_SER, 
												    RT_BILL_DATE, RT_BILL_CURRENCY,C_CODE, 
												   DISC_AMT, DISC_AMT_MST, DISC_AMT_DTL, 
												   BILL_AMT, VAT_AMT, OTHR_AMT, 
												   CC_CODE, PJ_NO, ACTV_NO,REP_CODE_BILL
												FROM IAS_RT_BILL_MST_RQ
												WHERE NVL(PROCESSED,0)<>1
												  AND NVL(STAND_BY,0)<>1
												  AND NVL(APPROVED,0)=1;


--
-- DTS_V_GET_RCPT_VCHRS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_RCPT_VCHRS
(DOC_DATE, REP_CODE, C_CODE, A_CY, CASH_AMT, 
 CASH_AMT_L, CHEQ_AMT, CHEQ_AMT_L, UNDUE_CHEQ_AMT, UNDUE_CHEQ_AMT_L)
BEQUEATH DEFINER
AS 
(SELECT   TO_DATE (d.doc_date, 'DD/MM/RRRR') doc_date, d.rep_code,
                             NVL (ac_code_dtl, '0') AS "C_CODE", d.a_cy,
                             ABS (SUM (DECODE (d.a_cy,
                                               ys_gen_pkg.get_local_cur, NVL (amt, 0),
                                               NVL (amt_f, 0)
                                              )
                                      )
                                 ) cash_amt,
                             ABS (SUM ( NVL (amt, 0))) cash_amt_L,    
                             0 cheq_amt, 0 cheq_amt_L, 0 undue_cheq_amt, 0 undue_cheq_amt_L
                        FROM ias_post_dtl d
                       WHERE doc_type = 2
                         AND d.jv_type = 1
                         AND d.rep_code IS NOT NULL
                         AND a_code NOT IN (SELECT a_code
                                              FROM cash_in_hand)
                         AND ac_dtl_typ = 3
                         AND NVL (ac_code_dtl, '0') IS NOT NULL
                    GROUP BY TO_DATE (d.doc_date, 'DD/MM/RRRR'),
                             NVL (ac_code_dtl, '0'),
                             d.rep_code,
                             d.a_cy
                    UNION
                    SELECT   TO_DATE (d.doc_date, 'DD/MM/RRRR') doc_date, d.rep_code,
                             NVL (ac_code_dtl, '0') AS "C_CODE", d.a_cy, 0 cash_amt,0 cash_amt_L,    
                             ABS (SUM (DECODE (d.a_cy,
                                               ys_gen_pkg.get_local_cur, NVL (amt, 0),
                                               NVL (amt_f, 0)
                                              )
                                      )
                                 ) cheq_amt, ABS (SUM ( NVL (amt, 0))) cheq_amt_L, 0 undue_cheq_amt, 0 undue_cheq_amt_L
                         FROM ias_post_dtl d
                       WHERE doc_type = 2
                         AND d.jv_type = 2
                         AND d.rep_code IS NOT NULL
                         AND a_code NOT IN (SELECT a_code
                                              FROM cash_in_hand)
                         AND ac_dtl_typ = 3
                         AND NVL (ac_code_dtl, '0') IS NOT NULL
                    GROUP BY TO_DATE (d.doc_date, 'DD/MM/RRRR'),
                             NVL (ac_code_dtl, '0'),
                             d.rep_code,
                             d.a_cy
                    UNION
                    SELECT   TO_DATE (m.voucher_date, 'DD/MM/RRRR') doc_date, d.rep_code,
                             NVL (d.ac_code_dtl, '0') AS "C_CODE", d.a_cy, 
                             0 cash_amt,0 cash_amt_L,0 cheq_amt, 0 cheq_amt_L,
                             ABS (SUM (DECODE (d.a_cy,
                                               ys_gen_pkg.get_local_cur, NVL (ac_amt, 0),
                                               NVL (ac_amtf, 0)
                                              )
                                      )
                                 ) undue_cheq_amt ,ABS (SUM ( NVL (Ac_amt, 0))) undue_cheq_amt_l 
                        FROM voucher_detail d, vouchers m
                       WHERE m.v_ser = d.v_ser
                         AND NVL (m.stand_by, 0) = 0
                         AND m.voucher_pay_type = 2
                         AND NVL (cheque_valued, 0) IN (0, 3)
                         AND a_code NOT IN (SELECT a_code
                                              FROM cash_in_hand)
                         AND m.cheq_type <> 0
                         AND d.ac_dtl_typ = 3
                         AND NVL (d.ac_code_dtl, '0') IS NOT NULL
                    GROUP BY TO_DATE (m.voucher_date, 'DD/MM/RRRR'),
                             NVL (d.ac_code_dtl, '0'),
                             d.rep_code,
                             d.a_cy);


--
-- DTS_V_GET_REP_PLAN_GPS_MAP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_PLAN_GPS_MAP
(REP_CODE, DOC_NO, DOC_SER, PLAN_DATE, C_CODE, 
 CST_L_NM, CST_F_NM, GPS, LATITUDE, LONGITUDE, 
 ROUTE_NO, SORTINROUTE)
BEQUEATH DEFINER
AS 
select m.Rep_Code,m.DOC_NO,m.Doc_Ser,m.Doc_date plan_date,d.c_code,nvl(c.c_a_name,'no local name') Cst_L_Nm,nvl(c.c_e_name,'no foreign name') Cst_F_Nm,c.GPS,
																			                 Substr(c.GPS,1,(nvl(instr(c.GPS,','),0)-1)) Latitude,Substr(c.GPS,(nvl(instr(c.GPS,','),0)+1),(nvl(instr(c.GPS,',',2),0)-1)) Longitude,c.ROUTE_NO,c.sortinroute
																			                   From Customer c ,Dts_Plan_Sman_Dtl d ,Dts_Plan_Sman_mst m 
																			                Where m.doc_ser=d.doc_ser
																			                   And  d.C_code=c.c_code
																			                    And nvl(m.APPROVED,0)=1 and c.gps is not null
																			                Order By  c.sortinroute,d.c_code;


--
-- DTS_V_ITEM_SERIALNO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ITEM_SERIALNO
(I_CODE, ITM_UNT, SERIALNO, W_CODE, EXPIRE_DATE, 
 BATCH_NO, GRP_CODE, REP_CODE)
BEQUEATH DEFINER
AS 
Select S.I_Code
           ,Ias_Itm_Pkg.Get_Icode_Min_Unit (P_I_Code => S.I_Code) Itm_Unt
           ,S.Serialno
           ,S.W_Code
           ,S.Expire_Date
           ,S.Batch_No
           ,S.Grp_Code
           ,S.Rep_Code
       From (Select Doc_Type
                   ,Bill_Doc_Type
                   ,Doc_No
                   ,Doc_Ser
                   ,I_Code
                   ,Itm_Unt
                   ,Serialno
                   ,R.W_Code
                   ,Expire_Date
                   ,Batch_No
                   ,In_Out
                   ,S.Grp_Code
                   ,S.Reprs_Code Rep_Code
               From Ias_Item_Serialno R, Sales_Man S
              Where     R.W_Code = S.W_Code
                    And Nvl (R.Bill_Cost, 0) = 1
                    And S.Grp_Code Is Not Null
                    And Exists
                           (Select 1
                              From Dts_Grp_Dtl
                             Where Grp_Code = S.Grp_Code And I_Code = R.I_Code And Rownum <= 1)
             Union All
             Select Doc_Type
                   ,Bill_Doc_Type
                   ,Doc_No
                   ,Doc_Ser
                   ,I_Code
                   ,Itm_Unt
                   ,Serialno
                   ,R.W_Code
                   ,Expire_Date
                   ,Batch_No
                   ,In_Out
                   ,S.Grp_Code
                   ,S.Reprs_Code Rep_Code
               From Ias_Item_Serialno_Br R, Sales_Man S
              Where     R.W_Code = S.W_Code
                    And S.Grp_Code Is Not Null
                    And Exists
                           (Select 1
                              From Dts_Grp_Dtl
                             Where Grp_Code = S.Grp_Code And I_Code = R.I_Code And Rownum <= 1)
                    And  Exists
                           (Select BILL_SER DOC_SER
                              From Ias_Bill_Mst_Br
                             Where Bill_Ser = R.Doc_Ser 
                             And Nvl (Bill_Post, 0) = 0 
                             AND  Nvl (Cncl_Flg, 0) = 0
                             UNION ALL
                            Select RT_BILL_SER
                              From Ias_Rt_Bill_Mst_Br
                             Where Rt_Bill_Ser = R.Doc_Ser 
                             And Nvl (Rt_Bill_Post, 0) = 0
                             AND  Nvl (Cncl_Flg, 0) = 0)) S
   Group By S.I_Code           
           ,S.W_Code
           ,S.Serialno
           ,S.Expire_Date
           ,S.Batch_No
           ,S.Grp_Code
           ,S.Rep_Code
     Having Sum (S.In_Out) = 1;


--
-- DTS_V_ITM_UNT_BARCODE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ITM_UNT_BARCODE
(REP_CODE, I_CODE, BARCODE, BATCH_NO, EXPIRE_DATE, 
 LAST_UPDT, ITM_UNT, P_SIZE, USE_SERIALNO)
BEQUEATH DEFINER
AS 
Select S.Reprs_Code Rep_Code
         ,B.I_Code
         ,B.Barcode
         ,B.Batch_No
         ,B.Expire_Date
         ,Nvl (B.Up_Date, B.Ad_Date) Last_Updt
         ,G.Itm_Unt
         ,G.P_Size
         ,nvl(Mi.Use_Serialno,0) Use_Serialno
     From Ias_V_Itm_Unt_Barcode B
         ,Dts_Grp_Dtl G
         ,Ias_Itm_Mst Mi
         ,Sales_Man S
         ,Ias_Para_Inv Pinv
         ,Dts_Para Pdts
    Where G.I_Code = Mi.I_Code 
    And S.Grp_Code = G.Grp_Code 
    And B.I_Code = G.I_Code 
    And B.Itm_Unt = G.Itm_Unt 
    And Nvl (Pdts.Use_Barcode, 0) = 1 
    And Decode (Pinv.Apprvd_Bracode_Same_Serialno, 1, Mi.Use_Serialno, 0) = 0
   Union All
   Select Rep_Code
         ,I_Code
         ,Serialno Barcode
         ,Batch_No
         ,Expire_Date
         ,Sysdate Last_Updt
         ,Itm_Unt
         ,1 P_Size
         , Use_Serialno
     From Dts_V_Item_Serialno, Ias_Para_Inv Pinv, Dts_Para Pdts
    Where Nvl (Pdts.Use_Barcode, 0) = 1 And Pinv.Apprvd_Bracode_Same_Serialno = 1;


