                 ,1407 Qstnr_Itm_Doc_type
                 ,1413 Open_Visit_Doc_type
                 , 1412 Free_Sample_Doc_type
             From Dts_Plan_Sman_Dtl d,Dts_Plan_Sman_Mst m
             where M.Doc_Ser = D.Doc_Ser) 
             Unpivot ((Fld_Val,Doc_Type, Exec_Val) 
                 For Fld_Code In (
                    (Collect_Rqst_Flg,Collect_Rqst_Doc_Type, Exec_Collect_Rqst_Flg) As '1'
                   ,(Dlvry_Goods_Flg,Dlvry_Goods_Doc_Type, Exec_Dlvry_Goods_Flg) As '2'
                   ,(Prmtng_Goods_Flg,Prmtng_Goods_Doc_Type, Exec_Prmtng_Goods_Flg) As '3'
                   , (Sales_Rtrn_Flg,Sales_Rtrn_Doc_Type, Exec_Sales_Rtrn_Flg) As '4'
                   , (Get_Info_Item_Flg,Get_Info_Item_Doc_Type, Exec_Get_Info_Item_Flg) As '5'
                   , (Showing_Items_Flg,Showing_Items_Doc_Type, Exec_Showing_Items_Flg) As '6'
                   , (Qt_Prices_Flg,Qt_Prices_Doc_Type, Exec_Qt_Prices_Flg) As '7'
                   , (Dlvry_Invoice_Flg,Dlvry_Invoice_Doc_Type, Exec_Dlvry_Invoice_Flg) As '8'
                   , (Sales_Flg,Sales_Doc_Type, Exec_Sales_Flg) As '9'
                   , (Collect_Flg,Collect_Doc_Type, Exec_Collect_Flg) As '10'
                   , (Inv_Stk_Cst_Flg,Inv_Stk_Cst_Doc_Type, Exec_Inv_Stk_Cst_Flg) As '11'
                   , (Others_Flg,Others_Doc_Type, Exec_Others_Flg) As '12'
                   , (Qstnr_Itm_Flg,Qstnr_Itm_Doc_Type, Exec_Qstnr_Itm_Flg) As '15'
                   , (Open_Visit_Flg,Open_Visit_Doc_Type, Exec_Open_Visit_Flg) As '16'
                   , (Free_Sample_Flg,Free_Sample_Doc_Type, Exec_Free_Sample_Flg) As '17')
                   ) M         
         ,Dts_Prfrmnce_Indctr P
    Where  M.Fld_Code = P.Pr_No 
    And Nvl (P.Use_In_Mob_App, 0) = 1 
    And Nvl (P.Pr_Flg, 0) = 1 
    And Nvl (P.Sp_Sman_Flg, 0) = Decode (M.Plan_Typ, 1, 0, 1);


--
-- DTS_V_PRM_TRGT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_PRM_TRGT
(DOC_SER, DOC_NO, DOC_DATE, CODE_NO, CODE_L_NM, 
 CODE_F_NM, FORM_NO, DOC_TYPE, DOC_SER_EXTRNL, CODE_NO_INSRT, 
 APPROVED, PRCSSD_FLG, INACTIVE, INACTIVE_RES, INACTIVE_DATE, 
 AD_DATE, AD_U_ID, UP_DATE, UP_U_ID, UP_CNT, 
 PR_REP, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 AD_TRMNL_NM, UP_TRMNL_NM, PRM_CODE, PRM_L_NM, PRM_F_NM, 
 PRM_TYPE, PRM_DEGREE, CNTRY_NO, PROV_NO, CITY_NO, 
 R_CODE, ROUTE_NO, SORTINROUTE, REP_CODE, PRM_PHONE, 
 PRM_MOBILE, PRM_BOX, PRM_FAX, PRM_ADDRESS, PRM_NOTE, 
 GPS, NTNLTY_NO, TYP_CRD, CRD_NO, CRD_ISSUSE_PLAC, 
 CRD_ISSUSE_DATE, CRD_ISSUSE_DATE_AH, CRD_END_DATE, CRD_END_DATE_AH, C_PROFF, 
 MRTL_STAT, BRTH_DATE, BRTH_DATE_AH, BRTH_PLC, WORK_PLC, 
 CMPNY_WORK, C_GENDER, SRC_INC, SRC_INC_RATE, IMG1, 
 IMG2, IMG3, IMG4, FIELD1, FIELD2, 
 FIELD3, FIELD4, FIELD5, FIELD6, FIELD7, 
 FIELD8, FIELD9, FIELD10)
BEQUEATH DEFINER
AS 
Select "DOC_SER","DOC_NO","DOC_DATE","CODE_NO","CODE_L_NM","CODE_F_NM","FORM_NO","DOC_TYPE","DOC_SER_EXTRNL","CODE_NO_INSRT","APPROVED","PRCSSD_FLG","INACTIVE","INACTIVE_RES","INACTIVE_DATE","AD_DATE","AD_U_ID","UP_DATE","UP_U_ID","UP_CNT","PR_REP","CMP_NO","BRN_NO","BRN_YEAR","BRN_USR","AD_TRMNL_NM","UP_TRMNL_NM","PRM_CODE","PRM_L_NM","PRM_F_NM","PRM_TYPE","PRM_DEGREE","CNTRY_NO","PROV_NO","CITY_NO","R_CODE","ROUTE_NO","SORTINROUTE","REP_CODE","PRM_PHONE","PRM_MOBILE","PRM_BOX","PRM_FAX","PRM_ADDRESS","PRM_NOTE","GPS","NTNLTY_NO","TYP_CRD","CRD_NO","CRD_ISSUSE_PLAC","CRD_ISSUSE_DATE","CRD_ISSUSE_DATE_AH","CRD_END_DATE","CRD_END_DATE_AH","C_PROFF","MRTL_STAT","BRTH_DATE","BRTH_DATE_AH","BRTH_PLC","WORK_PLC","CMPNY_WORK","C_GENDER","SRC_INC","SRC_INC_RATE","IMG1","IMG2","IMG3","IMG4","FIELD1","FIELD2","FIELD3","FIELD4","FIELD5","FIELD6","FIELD7","FIELD8","FIELD9","FIELD10"
  From (Select M.Doc_Ser
              ,M.Doc_No
              ,M.Doc_Date
              ,M.Code_No
              ,M.Code_L_Nm
              ,M.Code_F_Nm            
              ,M.Form_No
              ,M.Doc_Type
              ,M.Doc_Ser_Extrnl
              ,M.Code_No_Insrt
              ,M.Approved   
              ,M.Prcssd_Flg
              ,M.Inactive
              ,M.Inactive_Res
              ,M.Inactive_Date
              ,M.Ad_Date
              ,M.Ad_U_Id
              ,M.Up_Date
              ,M.Up_U_Id
              ,M.Up_Cnt
              ,M.Pr_Rep
              ,M.Cmp_No
              ,M.Brn_No
              ,M.Brn_Year
              ,M.Brn_Usr
              ,M.Ad_Trmnl_Nm
              ,M.Up_Trmnl_Nm
              ,d.Fld_Nm
              ,d.Fld_Val
          From Dts_Inpt_Coding_Dtl d,Dts_Inpt_Coding_mst m
         Where m.doc_ser=d.doc_ser
         and d.Form_No =1360) 
         Pivot (Max (Fld_Val)
                               For (Fld_Nm)
                               In  ('PRM_CODE' PRM_CODE,'PRM_L_NM' PRM_L_NM,'PRM_F_NM' PRM_F_NM,'PRM_TYPE' PRM_TYPE,'PRM_DEGREE' PRM_DEGREE,'CNTRY_NO' CNTRY_NO,'PROV_NO' PROV_NO,'CITY_NO' CITY_NO,'R_CODE' R_CODE,'ROUTE_NO' ROUTE_NO,'SORTINROUTE' SORTINROUTE,'REP_CODE' REP_CODE,'PRM_PHONE' PRM_PHONE,'PRM_MOBILE' PRM_MOBILE,'PRM_BOX' PRM_BOX,'PRM_FAX' PRM_FAX,'PRM_ADDRESS' PRM_ADDRESS,'PRM_NOTE' PRM_NOTE,'GPS' GPS,'NTNLTY_NO' NTNLTY_NO,'TYP_CRD' TYP_CRD,'CRD_NO' CRD_NO,'CRD_ISSUSE_PLAC' CRD_ISSUSE_PLAC,'CRD_ISSUSE_DATE' CRD_ISSUSE_DATE,'CRD_ISSUSE_DATE_AH' CRD_ISSUSE_DATE_AH,'CRD_END_DATE' CRD_END_DATE,'CRD_END_DATE_AH' CRD_END_DATE_AH,'C_PROFF' C_PROFF,'MRTL_STAT' MRTL_STAT,'BRTH_DATE' BRTH_DATE,'BRTH_DATE_AH' BRTH_DATE_AH,'BRTH_PLC' BRTH_PLC,'WORK_PLC' WORK_PLC,'CMPNY_WORK' CMPNY_WORK,'C_GENDER' C_GENDER,'SRC_INC' SRC_INC,'SRC_INC_RATE' SRC_INC_RATE,'IMG1' IMG1,'IMG2' IMG2,'IMG3' IMG3,'IMG4' IMG4,'FIELD1' FIELD1,'FIELD2' FIELD2,'FIELD3' FIELD3,'FIELD4' FIELD4,'FIELD5' FIELD5,'FIELD6' FIELD6,'FIELD7' FIELD7,'FIELD8' FIELD8,'FIELD9' FIELD9,'FIELD10' FIELD10 ));

COMMENT ON COLUMN IAS20261.DTS_V_PRM_TRGT.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';

