--
-- DTS_V_SMAN_INFO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_INFO
(SMAN_TYP, REP_CODE, U_ID, BRN_NO, W_CODE, 
 CASH_NO, BANK_NO, GRP_CODE, CC_CODE, INACTIVE, 
 WHG_CODE, SUCSES_VSTS, FAILED_VSTS, ALLOW_MOD_PRICE, MAX_BILL_DISC_PER, 
 MAX_BILL_ITM_DISC_PER, ALLW_MOD_ITM_HAVE_DISC_IN_BILL, ALLOW_MOD_ITM_NOT_HAVE_DISC, ALLOW_UPD_DISC_RTBILL, MUST_NOT_EXCD_HIGH_AND_LOW_PRC, 
 MUST_NOT_LESS_THN_LPRICE, MUST_NOT_HIGHR_THN_HPRICE, CLC_TYP_NO_TAX, NO_SAL, NO_COLCT, 
 CHK_STK_COST_IN_INVOICE, PLIMIT_TYPE, PLIMIT_PER, CASH_AMT_LMT, CASH_AMT_DAILY_LMT, 
 CASH_BLNC_AMT, CASH_DAY_BLNC_AMT, CR_LMT, SMAN_BLNC_AMT, USE_RET_WCODE, 
 RT_W_CODE, ALLW_SO_WH_REP_CONN_BRN, ALLW_CNCL_DOC, CONN_SP_SMAN, OPN_CLS_VST_AUTO, 
 ALLW_SAL_EXPRD_ITM, COL_NO, NOT_ALLW_UPDT_PARTIAL_DATA, USE_RES_IN_SO_APP, SO_RES_PRD, 
 SO_W_CODE, ALLW_WHTRNS_DIRCT, FREE_W_CODE, USE_RT_BILL_RQ_TYP, CLS_VST_BY_GPS, 
 SEND_GPS_PRD, READ_GPS_DSTNC, SHW_CC_CODE_VCHR_APP, SHW_ACTV_NO_VCHR_APP, SHW_PJ_NO_VCHR_APP, 
 AR_HIDE_QTY_IN_TRNS, SHOW_AVL_QTY_IN_REQ, NOT_ALLW_SAL_OUT_LOCTN_GEO, ALLW_APPROV_CSTMR_TRGT, PJ_NO, 
 ACTV_NO, USE_VCHR_RCPT_RQ)
BEQUEATH DEFINER
AS 
Select Sman_Typ
         ,Rep_Code
         ,U_Id
         ,Brn_No
         ,W_Code
         ,Cash_No
         ,Bank_No
         ,Grp_Code
         ,Cc_Code
         ,Nvl (Inactive, 0) Inactive
         ,Whg_Code
         ,Sucses_Vsts
         ,Failed_Vsts
         ,Allow_Mod_Price
         ,Max_Bill_Disc_Per
         ,Max_Bill_Itm_Disc_Per
         ,Allw_Mod_Itm_Have_Disc_In_Bill
         ,Allow_Mod_Itm_Not_Have_Disc
         ,Allow_Upd_Disc_Rtbill
         ,Must_Not_Excd_High_And_Low_Prc
         ,Must_Not_Less_Thn_Lprice
         ,Must_Not_Highr_Thn_Hprice
         ,decode (nvl(use_vat,0),1,(Nvl (Ys_Tax_Pkg.Get_Clc_Typ_No_Trnsprd (P_Clc_Typ_No => Clc_Typ_No_Tax, P_Brn_No => Brn_No), Clc_Typ_No_Tax)),null) Clc_Typ_No_Tax
         ,No_Sal
         ,No_Colct
         ,Chk_Stk_Cost_In_Invoice
         ,Plimit_Type
         ,Plimit_Per        
         ,CASH_AMT_LMT  
         ,CASH_AMT_DAILY_LMT
         ,CASH_BLNC_AMT 
         ,CASH_DAY_BLNC_AMT
         ,Cr_Lmt
         ,SMAN_BLNC_AMT 
         ,USE_RET_WCODE                       
         ,RT_W_CODE
         ,ALLW_SO_WH_REP_CONN_BRN 
         ,ALLW_CNCL_DOC 
         ,CONN_SP_SMAN  
         ,OPN_CLS_VST_AUTO 
         ,ALLW_SAL_EXPRD_ITM 
         ,col_no
         ,NOT_ALLW_UPDT_PARTIAL_DATA
         ,USE_RES_IN_SO_APP
         ,SO_RES_PRD
         ,SO_W_CODE
         ,ALLW_WHTRNS_DIRCT 
         ,case when Sman_Typ in(2,3) Then ( Select W_CODE                      
                                             From Warehouse_Details
                                                  Where NVL(FREE_SMPL_WH,0)=1
                                                 and  Nvl(CONN_BRN_NO,Brn_No)=Brn_No
                                                 And Rownum<=1) Else Null End Free_W_Code 
        ,USE_RT_BILL_RQ_TYP 
        ,CLS_VST_BY_GPS
        ,SEND_GPS_PRD
        ,READ_GPS_DSTNC 
        ,SHW_CC_CODE_VCHR_APP
        ,SHW_ACTV_NO_VCHR_APP
        ,SHW_PJ_NO_VCHR_APP 
        ,Nvl((select nvl(FLD_VAL,0)  from S_FLD_PRV_FXD_USR 
                 where FLD_NM='AR_HIDE_QTY_IN_TRNS' 
                        and U_ID=m.U_ID and rownum<=1 ),0) AR_HIDE_QTY_IN_TRNS  
        ,Nvl((select nvl(FLD_VAL,0)  from S_FLD_PRV_FXD_USR 
                 where FLD_NM='SHOW_AVL_QTY_IN_REQ' 
                        and U_ID=m.U_ID and rownum<=1 ),0) SHOW_AVL_QTY_IN_REQ 
       ,NOT_ALLW_SAL_OUT_LOCTN_GEO
       ,ALLW_APPROV_CSTMR_TRGT  ,
        PJ_NO  ,
        ACTV_NO ,
        USE_VCHR_RCPT_RQ                                                                                                                   
     From (     
     Select case When NVL(R.USE_SP_SMAN,0) IN(0,3) Then 1                        
                        When NVL(R.USE_SP_SMAN,0)=1 And NVL(S.CONN_SP_SMAN,0)=2 Then 3 
                        Else 1 end  Sman_Typ
                 ,S.Reprs_Code Rep_Code
                 ,U.U_Id
                 ,U.Conn_Brn_No Brn_No
                 ,S.W_Code
                 ,S.Cash_No
                 ,S.Bank_No
                 ,S.Grp_Code
                 ,S.Cc_Code
                 ,Nvl (S.Inactive, 0) Inactive
                 ,Ias_Wcode_Pkg.Get_Whg_Code (P_W_Code => S.W_Code) Whg_Code
                 ,Nvl ( (  Select Count (Vst_Sts) Sucses_Vsts
                             From Dts_Cst_Vst_Mst M
                            Where Vst_Sts = 1 And M.Rep_Code = S.Reprs_Code And Rownum <= 1
                         Group By M.Rep_Code)
                      ,0)
                     Sucses_Vsts
                 ,Nvl ( (  Select Count (Vst_Sts) Failed_Vsts
                             From Dts_Cst_Vst_Mst M
                            Where Vst_Sts = 0 And M.Rep_Code = S.Reprs_Code And Rownum <= 1
                         Group By M.Rep_Code)
                      ,0)
                     Failed_Vsts
                 ,Nvl (P.Pmanual, 0) Allow_Mod_Price
                 ,P.Inv_Dis_Lmt Max_Bill_Disc_Per
                 ,Inv_Dis_Lmt_Itm Max_Bill_Itm_Disc_Per
                 ,Ar_Update_Itm_Allow_Disc Allw_Mod_Itm_Have_Disc_In_Bill
                 ,Ar_Update_Itm_Not_Allow_Disc Allow_Mod_Itm_Not_Have_Disc
                 ,Allow_Upd_Disc_Rtbill Allow_Upd_Disc_Rtbill
                 ,R.Chk_Lmt_Price_Minus_Disc_Si Must_Not_Excd_High_And_Low_Prc
                 ,Nvl (L_Price, 0) Must_Not_Less_Thn_Lprice
                 ,Nvl (H_Price, 0) Must_Not_Highr_Thn_Hprice
                 ,S.Clc_Typ_No_Tax
                 ,Nvl (S.No_Sal, 0) No_Sal
                 ,Nvl (S.No_Colct, 0) No_Colct
                 ,Dts_Para.Chk_Stk_Cost_In_Invoice
                 ,Decode (Dts_Para.Chk_Stk_Cost_In_Invoice, 1, Nvl (Plimit_Type, 2), 2) Plimit_Type
                 ,Plimit_Per Plimit_Per                 
                 ,CASH_AMT_LMT  
                 ,CASH_AMT_DAILY_LMT 
                 ,(DTS_GEN_PKG.GET_CSH_BLNC ( P_REP_CODE  => S.Reprs_Code,P_CASH_NO=>S.Cash_No) ) CASH_BLNC_AMT
                 ,(DTS_GEN_PKG.GET_CSH_BLNC ( P_REP_CODE  =>  S.Reprs_Code,P_CASH_NO=>S.Cash_No,P_DATE=> TO_DATE(SYSDATE,'DD/MM/RRRR')) ) CASH_DAY_BLNC_AMT
                 ,s.Cr_Lmt
                 ,(DTS_GEN_PKG.GET_SMAN_BLNC ( P_REP_CODE  => S.Reprs_Code) )SMAN_BLNC_AMT 
                 ,Decode ( (Dts_Para.USE_RET_WCODE + S.USE_RET_WCODE), 2,1,0) USE_RET_WCODE                       
                 ,Decode ( (Dts_Para.USE_RET_WCODE + S.USE_RET_WCODE),2, s.rt_w_code,null) rt_w_code
                 ,Decode ( (Dts_Para.Allw_So_Wh_Rep_Conn_Brn + S.Allw_So_Wh_Rep_Conn_Brn), 2,1,0) Allw_So_Wh_Rep_Conn_Brn
                 ,Decode(Nvl (Ias_Brn_Pkg.Is_Brn_Use_E_Invc (P_Brn_No => U.Conn_Brn_No), 0), 1,0,nvl(s.ALLW_CNCL_DOC,0)) ALLW_CNCL_DOC
                 ,NVL(S.CONN_SP_SMAN,0) CONN_SP_SMAN
                 ,nvl(OPN_CLS_VST_AUTO,0)OPN_CLS_VST_AUTO
                 ,nvl(p.ALLW_SAL_EXPRD_ITM,0) ALLW_SAL_EXPRD_ITM
                 ,pg.use_vat
                 ,U.col_no
                 ,S.NOT_ALLW_UPDT_PARTIAL_DATA
                 ,S.USE_RES_IN_SO_APP
                 ,S.SO_RES_PRD
                 ,S.SO_W_CODE
                 ,Nvl(ALLW_WHTRNS_DIRCT,0) ALLW_WHTRNS_DIRCT
                 ,Decode(nvl(AR_USE_RT_BILL_RQ_TYP,0),1,
                   Decode(nvl(S.USE_RT_BILL_RQ_TYP,0),0,1,2),nvl(AR_USE_RT_BILL_RQ_TYP,0)) USE_RT_BILL_RQ_TYP
                 ,Nvl(S.CLS_VST_BY_GPS,0) CLS_VST_BY_GPS  
                 ,Case when nvl(Dts_Para.Trk_type,0)= 1 then Dts_Para.SEND_GPS_PRD 
                       when nvl(Dts_Para.Trk_type,0)= 2 and nvl(s.STOP_TRK,0)=0 then S.SEND_GPS_PRD 
                       Else Null end SEND_GPS_PRD
                 ,Case when nvl(Dts_Para.Trk_type,0)= 1 then Dts_Para.READ_GPS_DSTNC 
                       when nvl(Dts_Para.Trk_type,0)= 2 and nvl(s.STOP_TRK,0)=0 then S.READ_GPS_DSTNC 
                       Else Null end READ_GPS_DSTNC  
                 ,nvl(DTS_PARA.SHW_CC_CODE_VCHR_APP,0)SHW_CC_CODE_VCHR_APP
                ,nvl(DTS_PARA.SHW_ACTV_NO_VCHR_APP,0)SHW_ACTV_NO_VCHR_APP
                ,nvl(DTS_PARA.SHW_PJ_NO_VCHR_APP,0)SHW_PJ_NO_VCHR_APP 
                ,nvl(s.NOT_ALLW_SAL_OUT_LOCTN_GEO,0) NOT_ALLW_SAL_OUT_LOCTN_GEO
                ,nvl(s.ALLW_APPROV_CSTMR_TRGT,0) ALLW_APPROV_CSTMR_TRGT, 
                 S.PJ_NO  ,
                 S.ACTV_NO,
                 NVL(S.USE_VCHR_RCPT_RQ,0) USE_VCHR_RCPT_RQ                                                                   
             From Sales_Man S
                 ,User_R U
                 ,Privilege_Fixed P
                 ,Ias_Para_Ar R
                 ,Dts_Para
                 ,Ias_para_gen  pg
            Where Nvl (S.Inactive, 0) = 0 
             And Nvl (U.Inactive, 0) = 0 
             And S.Reprs_Code = U.Rep_Code
             And S.Reprs_Code = Nvl (DTS_PRMTR_PKG.Getpval ('REP_CODE'), S.Reprs_Code) 
             And U.U_Id = P.U_Id           
             And 1=Decode (nvl(S.W_Code,0),0,Nvl(S.No_Sal,0),1)
             And 1=Decode (nvl(S.Cash_No,0),0,nvl(S.No_Colct,0),1)               
             And 1=case When NVL(R.USE_SP_SMAN,0)=0 Then 1
                        When NVL(R.USE_SP_SMAN,0)=1 And NVL(S.CONN_SP_SMAN,0) <>1 Then 1 
                        Else 0 end                    
             And Grp_Code Is Not Null                          
       UNION ALL
       Select 2 Sman_Typ
                 ,S.Reprs_Code Rep_Code
                 ,U.U_Id
                 ,U.Conn_Brn_No Brn_No
                 ,( Select W_CODE                      
                      From Warehouse_Details
                       Where NVL(FREE_SMPL_WH,0)=1
                        and  Nvl(CONN_BRN_NO,U.Conn_Brn_No)=U.Conn_Brn_No
                         And Rownum<=1)W_Code
                 ,S.Cash_No
                 ,S.Bank_No
                 ,S.Grp_Code
                 ,S.Cc_Code
                 ,Nvl (S.Inactive, 0) Inactive
                 ,NULL Whg_Code
                 ,Nvl ( (  Select Count (Vst_Sts) Sucses_Vsts
                             From Dts_Cst_Vst_Mst M
                            Where Vst_Sts = 1 And M.Rep_Code = S.Reprs_Code And Rownum <= 1
                         Group By M.Rep_Code)
                      ,0)
                     Sucses_Vsts
                 ,Nvl ( (  Select Count (Vst_Sts) Failed_Vsts
                             From Dts_Cst_Vst_Mst M
                            Where Vst_Sts = 0 And M.Rep_Code = S.Reprs_Code And Rownum <= 1
                         Group By M.Rep_Code)
                      ,0)
                     Failed_Vsts
                 ,Nvl (P.Pmanual, 0) Allow_Mod_Price
                 ,P.Inv_Dis_Lmt Max_Bill_Disc_Per
                 ,Inv_Dis_Lmt_Itm Max_Bill_Itm_Disc_Per
                 ,Ar_Update_Itm_Allow_Disc Allw_Mod_Itm_Have_Disc_In_Bill
                 ,Ar_Update_Itm_Not_Allow_Disc Allow_Mod_Itm_Not_Have_Disc
                 ,Allow_Upd_Disc_Rtbill Allow_Upd_Disc_Rtbill
                 ,R.Chk_Lmt_Price_Minus_Disc_Si Must_Not_Excd_High_And_Low_Prc
                 ,Nvl (L_Price, 0) Must_Not_Less_Thn_Lprice
                 ,Nvl (H_Price, 0) Must_Not_Highr_Thn_Hprice
                 ,S.Clc_Typ_No_Tax
                 ,Nvl (S.No_Sal, 0) No_Sal
                 ,Nvl (S.No_Colct, 0) No_Colct
                 ,Dts_Para.Chk_Stk_Cost_In_Invoice
                 ,Decode (Dts_Para.Chk_Stk_Cost_In_Invoice, 1, Nvl (Plimit_Type, 2), 2) Plimit_Type
                 ,Plimit_Per Plimit_Per                 
                 ,CASH_AMT_LMT  
                 ,CASH_AMT_DAILY_LMT 
                 ,0 CASH_BLNC_AMT
                 ,0 CASH_DAY_BLNC_AMT
                 ,s.Cr_Lmt
                 ,0 SMAN_BLNC_AMT 
                 ,0 USE_RET_WCODE                       
                 ,NULL rt_w_code
                 ,0 Allw_So_Wh_Rep_Conn_Brn
                 ,nvl(s.ALLW_CNCL_DOC,0) ALLW_CNCL_DOC
                 ,NVL(S.CONN_SP_SMAN,0) CONN_SP_SMAN
                 ,nvl(s.OPN_CLS_VST_AUTO,0) OPN_CLS_VST_AUTO
                 ,nvl(p.ALLW_SAL_EXPRD_ITM,0) ALLW_SAL_EXPRD_ITM
                 ,pg.use_vat
                 ,U.col_no
                 ,S.NOT_ALLW_UPDT_PARTIAL_DATA
                 ,S.USE_RES_IN_SO_APP
                 ,S.SO_RES_PRD
                 ,S.SO_W_CODE
                 ,Nvl(ALLW_WHTRNS_DIRCT,0)ALLW_WHTRNS_DIRCT 
                 ,0 USE_RT_BILL_RQ_TYP 
                 ,Nvl(S.CLS_VST_BY_GPS,0) CLS_VST_BY_GPS 
                 ,Case when nvl(Dts_Para.Trk_type,0)= 1 then Dts_Para.SEND_GPS_PRD 
                       when nvl(Dts_Para.Trk_type,0)= 2 and nvl(s.STOP_TRK,0)=0 then S.SEND_GPS_PRD 
                       Else Null end SEND_GPS_PRD
                 ,Case when nvl(Dts_Para.Trk_type,0)= 1 then Dts_Para.READ_GPS_DSTNC 
                       when nvl(Dts_Para.Trk_type,0)= 2 and nvl(s.STOP_TRK,0)=0 then S.READ_GPS_DSTNC 
                       Else Null end READ_GPS_DSTNC
                ,nvl(DTS_PARA.SHW_CC_CODE_VCHR_APP,0)SHW_CC_CODE_VCHR_APP
                ,nvl(DTS_PARA.SHW_ACTV_NO_VCHR_APP,0)SHW_ACTV_NO_VCHR_APP
                ,nvl(DTS_PARA.SHW_PJ_NO_VCHR_APP,0)SHW_PJ_NO_VCHR_APP 
                ,nvl(s.NOT_ALLW_SAL_OUT_LOCTN_GEO,0) NOT_ALLW_SAL_OUT_LOCTN_GEO
                ,nvl(s.ALLW_APPROV_CSTMR_TRGT,0) ALLW_APPROV_CSTMR_TRGT,
                 S.PJ_NO  ,
                 S.ACTV_NO ,
                 NVL(S.USE_VCHR_RCPT_RQ,0) USE_VCHR_RCPT_RQ                      
             From Sales_Man S
                 ,User_R U
                 ,Privilege_Fixed P
                 ,Ias_Para_Ar R
                 ,Dts_Para
                 ,ias_para_gen pg
            Where Nvl (S.Inactive, 0) = 0 
             And Nvl (U.Inactive, 0) = 0 
             And S.Reprs_Code = U.Rep_Code
             And S.Reprs_Code = Nvl (DTS_PRMTR_PKG.Getpval ('REP_CODE'), S.Reprs_Code) 
             And U.U_Id = P.U_Id                        
             AND NVL(S.CONN_SP_SMAN,0)=1 
             AND NVL(R.USE_SP_SMAN,0)=1                          
             ) M;

COMMENT ON COLUMN IAS20261.DTS_V_SMAN_INFO.SMAN_TYP IS '1-„‰œÊ» „»Ì⁄«  
