--
-- DTS_V_VCHR_BNK_TYPE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_VCHR_BNK_TYPE
(LANG_NO, REP_CODE, FLG_CODE, FLG_VALUE, FLG_DESC)
BEQUEATH DEFINER
AS 
Select S_Flags.Lang_No
         ,Rep_Code
         ,S_Flags.Flg_Code
         ,S_Flags.Flg_Value
         ,S_Flags.Flg_Desc
     From S_Flags, S_Flags_Priv, Dts_V_Sman_Info
    Where S_Flags.Flg_Code = S_Flags_Priv.Flg_Code 
    And S_Flags.Flg_Value = S_Flags_Priv.Flg_Value 
    And S_Flags.Flg_Code = 'VCHR_BNK_TYP' 
    And Nvl (Priv_Flag, 0) = 1 
    And Dts_V_Sman_Info.U_Id = S_Flags_Priv.U_Id;

COMMENT ON TABLE IAS20261.DTS_V_VCHR_BNK_TYPE IS '’·«ÕÌ«  ÿ—ﬁ «·œ›⁄ ·”‰œ «·ﬁ»÷ ·‰Ÿ«„ «· Ê“Ì⁄';



--
-- GLS_CST_VND_EMP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_CST_VND_EMP
(AC_CODE_DTL, MOBILE_NO, E_MAIL, AC_DTL_TYP)
BEQUEATH DEFINER
AS 
(SELECT C_CODE       AC_CODE_DTL,
            C_MOBILE     MOBILE_NO,
            C_E_MAIL     E_MAIL,
            3            AC_DTL_TYP
       FROM CUSTOMER
      WHERE SEND_MSG = 1 AND (C_MOBILE IS NOT NULL OR C_E_MAIL IS NOT NULL)
     UNION ALL
     SELECT V_CODE,
            V_MOBILE     MOBILE_NO,
            V_E_MAIL     E_MAIL,
            4            AC_DTL_TYP
       FROM V_DETAILS
      WHERE (V_MOBILE IS NOT NULL OR V_E_MAIL IS NOT NULL)
     UNION ALL
     SELECT TO_CHAR (EMP_NO)     AC_CODE_DTL,
            MOBILE_NO,
            E_MAIL,
            7                    AC_DTL_TYP
       FROM S_EMP
      WHERE MOBILE_NO IS NOT NULL OR E_MAIL IS NOT NULL
      );

COMMENT ON COLUMN IAS20261.GLS_CST_VND_EMP.MOBILE_NO IS '770 - —ﬁ„ «·ÃÊ«·';

COMMENT ON COLUMN IAS20261.GLS_CST_VND_EMP.E_MAIL IS '520 - «·»—Ìœ «·«·ﬂ —Ê‰Ì';



--
-- GLS_KPI_BGDGT_BLNC_DIFF_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_KPI_BGDGT_BLNC_DIFF_VW
(DOC_NO, DOC_SER, DOC_DATE, REF_NO, DOC_DESC, 
 DOC_NOTE, AC_TREE, A_CODE, AC_NAME, AC_DTL_TYP, 
 AC_DTL_TYP_NM, AC_CODE_DTL, AC_CODE_DTL_NM, A_CY, PRD_NO, 
 PRD_NM, CC_CODE, CC_NM, PJ_NO, PJ_NM, 
 ACTV_NO, ACTV_NM, BRN_YEAR, F_DATE, T_DATE, 
 BDGT_PRD_TYPE, BDGT_TYPE, BRN_NO, BRN_NM, AD_U_ID, 
 MN_SUB, A_S_M, A_LEVEL, A_REPORT, EST_BLNC, 
 ACT_BAL, CMLTV_ACT_BAL, CMLTV_EST_BAL)
BEQUEATH DEFINER
AS 
WITH TLNG AS (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1) LNG_NO FROM DUAL)
      SELECT A.DOC_NO
            ,A.DOC_SER
            ,A.DOC_DATE
            ,A.REF_NO
            ,A.DOC_DESC
            ,A.DOC_NOTE
            ,C.AC_TREE
            ,C.A_CODE
            ,C.A_CODE|| '-' ||(SELECT DECODE(TLNG.LNG_NO,1,A_NAME,NVL(A_NAME_ENG,A_NAME))
                                FROM ACCOUNT
                               WHERE A_CODE = C.A_CODE 
                                 AND ROWNUM<=1) AC_NAME
            ,B.AC_DTL_TYP                    
            ,B.AC_DTL_TYP || '-' ||YS_GEN_PKG.GET_FLG_NM (P_FLG_CODE => 'AC_DTL_TYP', P_FLG_VALUE => B.AC_DTL_TYP, P_LNG_NO => TLNG.LNG_NO) AC_DTL_TYP_NM
            ,B.AC_CODE_DTL
            ,B.AC_CODE_DTL || '-' || DECODE(NVL(B.AC_DTL_TYP,0),0,NULL,YS_AC_DTL_PKG.GET_AC_DTL_NM(B.AC_CODE_DTL,C.AC_TREE,B.AC_DTL_TYP,TLNG.LNG_NO)) AC_CODE_DTL_NM
            ,A.A_CY
            ,B.PRD_NO
            ,(SELECT B.PRD_NO || '-' || NVL (PRD_L_NM, PRD_F_NM)     PRD_NM
              FROM S_PRD_DTL
             WHERE PRD_NO =B.PRD_NO AND ROWNUM <= 1)
               PRD_NM
            ,B.CC_CODE
            ,B.CC_CODE || ' - ' || (SELECT DECODE (TLNG.LNG_NO
                                                ,1, NVL (CC_A_NAME, CC_E_NAME)
                                                ,NVL (CC_E_NAME, CC_A_NAME))
                                    FROM COST_CENTERS
                                   WHERE CC_CODE = B.CC_CODE)
               CC_NM
            ,B.PJ_NO
            ,B.PJ_NO || ' - ' || (SELECT DECODE (TLNG.LNG_NO
                                              ,1, NVL (PJ_A_NAME, PJ_E_NAME)
                                              ,NVL (PJ_A_NAME, PJ_E_NAME))
                                  FROM IAS_PROJECTS
                                 WHERE PJ_NO = B.PJ_NO)
               PJ_NM
            ,B.ACTV_NO
            ,B.ACTV_NO || ' - ' || (SELECT DECODE (TLNG.LNG_NO
                                                ,1, NVL (ACTV_A_NAME, ACTV_E_NAME)
                                                ,NVL (ACTV_E_NAME, ACTV_A_NAME))
                                    FROM IAS_ACTVTY
                                   WHERE ACTV_NO = B.ACTV_NO)
               ACTV_NM
            ,B.BRN_YEAR
            ,B.F_DATE
            ,B.T_DATE
            ,A.BDGT_PRD_TYPE|| ' - ' || (SELECT FLG_DESC
                                        FROM S_FLAGS
                                       WHERE FLG_CODE = 'BDGT_TYPE'
                                         AND LANG_NO = TLNG.LNG_NO
                                         AND FLG_VALUE = A.BDGT_PRD_TYPE
                                         AND ROWNUM <= 1) 
             BDGT_PRD_TYPE                            
            ,A.BDGT_TYPE || ' - ' || (SELECT FLG_DESC
                                        FROM S_FLAGS
                                       WHERE FLG_CODE = 'BDGT_STATUS'
                                         AND LANG_NO = TLNG.LNG_NO
                                         AND FLG_VALUE = A.BDGT_TYPE
                                         AND ROWNUM <= 1)
              BDGT_TYPE
            ,A.BRN_NO
            ,A.BRN_NO || ' - ' || (SELECT DECODE (TLNG.LNG_NO
                                               ,1, NVL (BRN_LNAME, BRN_FNAME)
                                               ,NVL (BRN_FNAME, BRN_LNAME))
                                   FROM S_BRN
                                  WHERE BRN_NO = A.BRN_NO AND ROWNUM <= 1)
               BRN_NM
            ,A.AD_U_ID
            ,C.MN_SUB
            ,C.A_S_M ||' - '||(SELECT DECODE (TLNG.LNG_NO,1, NVL (ACCOUNT_NAME, ACCOUNT_E_NAME),NVL (ACCOUNT_E_NAME, ACCOUNT_NAME))
                                 FROM ACCOUNT_TYPES
                                WHERE ACCOUNT_TYPE = C.A_S_M AND ROWNUM <= 1)
            A_S_M
            ,C.A_LEVEL
            ,C.A_REPORT||' - '||(SELECT DECODE (TLNG.LNG_NO,1, NVL (REPORT_NAME, REPORT_E_NAME),NVL (REPORT_E_NAME, REPORT_NAME))
                                   FROM ACCOUNT_REPORT_TYPE
                                  WHERE REPORT_TYPE = C.A_REPORT AND ROWNUM <= 1)
               A_REPORT
            ,ROUND (
                 SUM (
                     DECODE (
                         YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(Use_Multi_Cur_Bdgt,0)')
                        ,0,   NVL (B.AMT_L, 0)
                            + NVL (B.AMT_L_ADD, 0)
                            + NVL (B.AMT_L_ADD_MOV, 0)
                            - NVL (B.AMT_L_DISC, 0)
                            - NVL (B.AMT_L_DISC_MOV, 0)
                        ,DECODE (
                             A.A_CY
                            ,YS_GEN_PKG.GET_LOCAL_CUR,   NVL (B.AMT_L, 0)
                                                       + NVL (B.AMT_L_ADD, 0)
                                                       + NVL (B.AMT_L_ADD_MOV, 0)
                                                       - NVL (B.AMT_L_DISC, 0)
                                                       - NVL (B.AMT_L_DISC_MOV, 0)
                            ,  NVL (B.AMT_F, 0)
                             + NVL (B.AMT_F_ADD, 0)
                             + NVL (B.AMT_F_ADD_MOV, 0)
                             - NVL (B.AMT_F_DISC, 0)
                             - NVL (B.AMT_F_DISC_MOV, 0))))
                ,4)
                 EST_BLNC
            ,(SELECT ROUND (
                         SUM (
                             DECODE (
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL'
                                                          ,'nvl(Use_Multi_Cur_Bdgt,0)')
                                ,0, NVL (PST.AMT, 0)
                                ,DECODE (A.A_CY
                                        ,YS_GEN_PKG.GET_LOCAL_CUR, NVL (PST.AMT, 0)
                                        ,NVL (PST.AMT_F, 0))))
                        ,4)
                         BLNC
                FROM IAS_POST_DTL PST
               WHERE A_CODE IN (SELECT A_CODE
                                  FROM IAS_ACC_TREE
                                 WHERE AC_TREE = C.A_CODE)
                     AND NVL(PST.AC_DTL_TYP,0) = NVL(B.AC_DTL_TYP,0)
                     AND NVL(PST.AC_CODE_DTL,'*') =NVL(B.AC_CODE_DTL,'*')          
                     AND A_CY =
                         DECODE (
                             YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(Use_Multi_Cur_Bdgt,0)')
                            ,0, A_CY
                            ,A.A_CY)
                     AND PST.BRN_NO =
                         DECODE (YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(CHK_BGT_AMT,1)')
                                ,1, PST.BRN_NO
                                ,A.BRN_NO)
                     AND NVL (PST.CC_CODE, '0') =
                         DECODE (B.CC_CODE, '', NVL (PST.CC_CODE, '0'), B.CC_CODE)
                     AND NVL (PST.PJ_NO, '0') = DECODE (B.PJ_NO, '', NVL (PST.PJ_NO, '0'), B.PJ_NO)
                     AND NVL (PST.ACTV_NO, '0') =
                         DECODE (B.ACTV_NO, '', NVL (PST.ACTV_NO, '0'), B.ACTV_NO)
                     AND DOC_TYPE <> 0
                     AND PST.DOC_DATE BETWEEN NVL (B.F_DATE, PST.DOC_DATE)
                                          AND NVL (B.T_DATE, PST.DOC_DATE))
                 ACT_BAL
            ,(SELECT ROUND (
                         SUM (
                             DECODE (
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL'
                                                          ,'nvl(Use_Multi_Cur_Bdgt,0)')
                                ,0, NVL (PST.AMT, 0)
                                ,DECODE (A.A_CY
                                        ,YS_GEN_PKG.GET_LOCAL_CUR, NVL (PST.AMT, 0)
                                        ,NVL (PST.AMT_F, 0))))
                        ,4)
                         BLNC
                FROM IAS_POST_DTL PST
               WHERE A_CODE IN (SELECT A_CODE
                                  FROM IAS_ACC_TREE
                                 WHERE AC_TREE = C.A_CODE)
                     AND NVL(PST.AC_DTL_TYP,0) = NVL(B.AC_DTL_TYP,0)
                     AND NVL(PST.AC_CODE_DTL,'*') =NVL(B.AC_CODE_DTL,'*')            
                     AND A_CY =
                         DECODE (
                             YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(Use_Multi_Cur_Bdgt,0)')
                            ,0, A_CY
                            ,A.A_CY)
                     AND PST.BRN_NO =
                         DECODE (YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(CHK_BGT_AMT,1)')
                                ,1, PST.BRN_NO
                                ,A.BRN_NO)
                     AND NVL (PST.CC_CODE, '0') =
                         DECODE (B.CC_CODE, '', NVL (PST.CC_CODE, '0'), B.CC_CODE)
                     AND NVL (PST.PJ_NO, '0') = DECODE (B.PJ_NO, '', NVL (PST.PJ_NO, '0'), B.PJ_NO)
                     AND NVL (PST.ACTV_NO, '0') =
                         DECODE (B.ACTV_NO, '', NVL (PST.ACTV_NO, '0'), B.ACTV_NO)
                     AND DOC_TYPE <> 0
                     AND PST.DOC_DATE <= NVL (B.T_DATE, PST.DOC_DATE))
                 CMLTV_ACT_BAL,
                 (SELECT ROUND (
                 SUM (
                     DECODE (
                         YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL', 'nvl(Use_Multi_Cur_Bdgt,0)')
                        ,0,   NVL (BGT.AMT_L, 0)
                            + NVL (BGT.AMT_L_ADD, 0)
                            + NVL (BGT.AMT_L_ADD_MOV, 0)
                            - NVL (BGT.AMT_L_DISC, 0)
                            - NVL (BGT.AMT_L_DISC_MOV, 0)
                        ,DECODE (
                             A.A_CY
                            ,YS_GEN_PKG.GET_LOCAL_CUR,   NVL (BGT.AMT_L, 0)
                                                       + NVL (BGT.AMT_L_ADD, 0)
                                                       + NVL (BGT.AMT_L_ADD_MOV, 0)
                                                       - NVL (BGT.AMT_L_DISC, 0)
                                                       - NVL (BGT.AMT_L_DISC_MOV, 0)
                            ,  NVL (BGT.AMT_F, 0)
                             + NVL (BGT.AMT_F_ADD, 0)
                             + NVL (BGT.AMT_F_ADD_MOV, 0)
                             - NVL (BGT.AMT_F_DISC, 0)
                             - NVL (BGT.AMT_F_DISC_MOV, 0))))
                ,4)
                FROM IAS_BDGT_BLNC_DTL BGT
               WHERE DOC_SER = A.DOC_SER
                     AND AC_TREE = C.A_CODE
                     AND NVL(BGT.AC_DTL_TYP,0) = NVL(B.AC_DTL_TYP,0)
                     AND NVL(BGT.AC_CODE_DTL,'*') =NVL(B.AC_CODE_DTL,'*')
                     AND A_CY = A.A_CY
                     AND BGT.F_DATE <= NVL (B.F_DATE, BGT.F_DATE)
                     --And BGT.brn_no  =DECODE(ys_gen_pkg.get_fld_value ('IAS_PARA_GL','nvl(CHK_BGT_AMT,1)'),1,BGT.brn_no,b.brn_no)
                     AND NVL (BGT.CC_CODE, '0') =
                         DECODE (B.CC_CODE, '', NVL (BGT.CC_CODE, '0'), B.CC_CODE)
                     AND NVL (BGT.PJ_NO, '0') = DECODE (B.PJ_NO, '', NVL (BGT.PJ_NO, '0'), B.PJ_NO)
                     AND NVL (BGT.ACTV_NO, '0') =
                         DECODE (B.ACTV_NO, '', NVL (BGT.ACTV_NO, '0'), B.ACTV_NO))
                 CMLTV_EST_BAL
        FROM IAS_BDGT_BLNC_MST A
            ,IAS_BDGT_BLNC_DTL B
            ,IAS_ACC_TREE     C
            ,TLNG
       WHERE A.DOC_SER = B.DOC_SER AND B.A_CODE = C.A_CODE AND MN_SUB=1 
    GROUP BY TLNG.LNG_NO,A.DOC_NO
            ,A.DOC_SER
            ,A.DOC_DATE
            ,A.REF_NO
            ,A.DOC_DESC
            ,A.DOC_NOTE
            ,C.AC_TREE
            ,C.A_CODE
            ,B.AC_DTL_TYP
            ,B.AC_CODE_DTL
            ,A.A_CY
            ,B.PRD_NO
            ,B.CC_CODE
            ,B.PJ_NO
            ,B.ACTV_NO
            ,B.BRN_YEAR
            ,B.F_DATE
            ,B.T_DATE
            ,A.BDGT_PRD_TYPE
            ,A.BDGT_TYPE
            ,A.BRN_NO
            ,A.AD_U_ID
            ,C.MN_SUB
            ,C.A_S_M
            ,C.A_LEVEL
            ,C.A_REPORT;


--
-- GLS_PST_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_PST_AI_VW
(DOC_SRL, DOC_TYP, UNT_NO, AC_CODE, AC_L_NM, 
 AC_F_NM, AC_TYP, IS_OPN_BLNC, IS_CRNCY_DFRNC, AC_CODE_DTL, 
 AC_DTL_NM, AC_DTL_TYP, CUR_CODE, DOC_NO, DOC_DATE, 
 GL_DATE, DOC_TYP_NM, SMAN_CODE, SMAN_CODE_NM, CLCTR_CODE, 
 CLCTR_CODE_NM, REF_NO, MNL_NO, DOC_DESC, DR_AMT_L, 
 DR_AMT_F, CR_AMT_L, CR_AMT_F)
BEQUEATH DEFINER
AS 
SELECT D.DOC_SER
               DOC_SRL,
           D.DOC_TYPE
               DOC_TYP,
           D.BRN_NO
               UNT_NO,
           M.A_CODE
               AC_CODE,
           M.A_NAME
               AC_L_NM,
           M.A_NAME_ENG
               AC_F_NM,
           M.DR
               AC_TYP,
           DECODE (D.DOC_TYPE, 0, 'YES', 'NO')
               IS_OPN_BLNC,
           DECODE (D.DOC_TYPE, 30, 'YES', 'NO')
               IS_CRNCY_DFRNC,
           D.AC_CODE_DTL,
           YS_AC_DTL_PKG.GET_AC_DTL_NM (
               P_AC_CODE       => D.A_CODE,
               P_AC_CODE_DTL   => D.AC_CODE_DTL,
               P_AC_DTL_TYP    => D.AC_DTL_TYP,
               P_LNG_NO        =>
                   NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1),
               P_GET_NM_ONLY   => 1)
               AC_DTL_NM,
           D.AC_DTL_TYP,
           D.A_CY
               CUR_CODE,
           D.DOC_NO,
           D.DOC_DATE,
           D.DOC_DATE_MNL
               GL_DATE,
           DOC_TYPE_NAME (
               P_DOCTYPE   => D.DOC_TYPE,
               P_LANG      =>
                   NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1))
               DOC_TYP_NM,
           D.REP_CODE
               SMAN_CODE,
           IAS_SMAN_PKG.GET_SMAN_NAME (
               P_REP_CODE   => D.REP_CODE,
               P_LNG_NO     =>
                   NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1))
               SMAN_CODE_NM,
           D.COL_NO
               CLCTR_CODE,
           (SELECT DECODE (
                       NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'), 1),
                       1, NVL (COL_NAME, COL_E_NAME),
                       NVL (COL_E_NAME, COL_NAME))
              FROM COLLERCTOR
             WHERE COL_NO = D.COL_NO AND ROWNUM <= 1)
               CLCTR_CODE_NM,
           D.REF_NO,
           D.DOC_NO_MNL
               MNL_NO,
           D.DOC_DESC,
           D.DR_AMT
               DR_AMT_L,
           D.DR_AMT_F,
           D.CR_AMT
               CR_AMT_L,
           D.CR_AMT_F
      FROM IAS_POST_DTL D, ACCOUNT M
     WHERE M.A_CODE = D.A_CODE;


--
-- GLS_V_ACCNT_DTL_CURR2  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL_CURR2
(AC_CODE, AC_CODE_DTL, AC_DTL_TYP, AC_DTL_TYP_DTL, CUR_CODE, 
 GRP_NO, CONN_BRN_NO, AC_DTL_DEGREE, CLASS_NO, CLASS_TYP, 
 DFLT, INACTV, INACTV_RSON, INACTV_DATE)
BEQUEATH DEFINER
AS 
(SELECT DISTINCT M.A_Code     AC_CODE,
                     NULL         AC_CODE_DTL,
                     M.AC_DTL_TYP,
                     0            ac_dtl_typ_DTL,
                     A_cy         cur_code,
                     A_GROUPING   GRP_NO,
                     NULL         CONN_BRN_NO,
                     NULL         AC_DTL_DEGREE,
                     CLASS_NO     CLASS_NO,
                     NULL         CLASS_TYP,
                     D.DFLT ,
                     INACTIVE,
                     NULL         inactv_rson,
                     NULL         inactv_date
       FROM Ias_Acc_Tree M, Account_Curr D
      WHERE M.a_code = D.a_code AND MN_SUB = 1 AND M.AC_DTL_TYP =0
     UNION ALL
     SELECT DISTINCT
                D.A_Code                                    AC_CODE,
                TO_CHAR (M.cash_no)                           AC_CODE_DTL,
                YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code)     AC_DTL_TYP,
                0                                           ac_dtl_typ_DTL,
                A_cy                                        CUR_CODE,
                GROUP_NO     GRP_NO,
                CONN_BRN_NO  CONN_BRN_NO,
                NULL         AC_DTL_DEGREE,
                NULL         CLASS_NO,
                NULL         CLASS_TYP,
                D.DFLT ,
                D.INACTIVE,
                NULL                                        inactv_rson,
                D.INACTIVE_DATE
               FROM CASH_IN_HAND M,IAS_CASH_IN_HAND_DTL D
              WHERE M.CASH_NO=D.CASH_NO
                 AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code) = 1
     UNION ALL
     SELECT DISTINCT
            D.A_Code                                    AC_CODE,
            TO_CHAR (D.BANK_NO)                         AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code)     AC_DTL_TYP,
            0                                           ac_dtl_typ_DTL,
            A_cy                                        CUR_CODE,
            GROUP_NO     GRP_NO,
            CONN_BRN_NO  CONN_BRN_NO,
            NULL         AC_DTL_DEGREE,
            NULL         CLSS_NO,
            NULL         CLSS_TYP,
            D.DFLT ,
            D.INACTIVE,
            NULL                                        inactv_rson,
            D.INACTIVE_DATE
       FROM CASH_AT_BANK M,IAS_CASH_AT_BANK_DTL D
      WHERE YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code) = 2
     UNION ALL
     SELECT DISTINCT
            M.C_A_Code                                    AC_CODE,
            M.C_CODE                                      AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.C_A_Code)     AC_DTL_TYP,
            0                                             ac_dtl_typ_DTL,
            A_cy                                          CUR_CODE,
            C_GROUP_CODE     GRP_NO,
            CONN_BRN_NO      CONN_BRN_NO,
            C_DEGREE         AC_DTL_DEGREE,
            C_CLASS          CLASS_NO,
            C_CLASS_TYP      CLASS_TYP,
            D.DFLT_FLG ,
            D.INACTIVE,
            NULL                                          inactv_rson,
            NULL                                          INACTIVE_DATE
       FROM customer M, customer_curr D
      WHERE     M.C_CODE = D.C_CODE
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.C_A_Code) = 3
     UNION ALL
     SELECT DISTINCT
            M.V_A_Code                                    AC_CODE,
            M.v_CODE                                      AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.V_A_Code)     AC_DTL_TYP,
            0                                             ac_dtl_typ_DTL,
            A_cy                                          CUR_CODE,
            V_GROUP_CODE     GRP_NO,
            CONN_BRN_NO  CONN_BRN_NO,
            V_DEGREE       AC_DTL_DEGREE,
            V_CLASS         CLSS_NO,
            NULL         CLSS_TYP,
            D.CUR_DFLT ,
            D.INACTIVE,
            NULL                                          inactv_rson,
            NULL                                          INACTIVE_DATE
       FROM v_details M, VENDOR_CURR D
      WHERE     M.V_CODE = D.V_CODE
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.V_A_Code) = 4
     UNION ALL
     SELECT DISTINCT
            M.a_code                                    ac_code,
            TO_CHAR (EMP_NO)                            ac_code_dtl,
            ys_ac_dtl_pkg.get_ac_dtl_typ (M.a_code)     ac_dtl_typ,
            0                                           ac_dtl_typ_dtl,
            a_cy                                        cur_code,
            GRP_NO       GRP_NO,
            BRN_NO       CONN_BRN_NO,
            NULL         AC_DTL_DEGREE,
            CLASS_NO     CLSS_NO,
            NULL         CLSS_TYP,
            M.DFLT,
            d.inactive,
            NULL                                        inactv_rson,
            d.inactive_date
       FROM ACCOUNT_CURR M, S_EMP d
      WHERE ys_ac_dtl_pkg.get_ac_dtl_typ (M.a_code) = 7
     UNION ALL
     SELECT DISTINCT
            M.AC_CODE,
            M.AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE)     AC_DTL_TYP,
            1                                          ac_dtl_typ_DTL,
            D.CUR_CODE,
            GRP_CODE     GRP_NO,
            CONN_BRN_NO  CONN_BRN_NO,
            NULL         AC_DTL_DEGREE,
            NULL         CLSS_NO,
            NULL         CLSS_TYP,
            D.DFLT,
            d.inactv,
            d.inactv_rson,
            d.inactv_date
       FROM gls_accnt_dtl M, gls_accnt_dtl_curr D
      WHERE     m.ac_code_dtl = d.ac_code_dtl
            AND m.ac_dtl_typ = d.ac_dtl_typ
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE) IN (5, 6)
     UNION ALL
     SELECT DISTINCT
            M.AC_CODE,
            AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE)     AC_DTL_TYP,
            10                                         ac_dtl_typ_DTL,
            D.A_CY                                     CUR_CODE,
            DCTR_GRP     GRP_NO,
            NULL  CONN_BRN_NO,
            NULL         AC_DTL_DEGREE,
            NULL     CLSS_NO,
            NULL         CLSS_TYP,
            D.DFLT,
            d.INACTIVE,
            NULL                                       inactv_rson,
            NULL                                       inactv_date
       FROM hps_dctr m, account_curr d
      WHERE     m.ac_code = d.a_code
            AND ys_ac_dtl_pkg.get_ac_dtl_typ (d.a_code) IN (5, 6));

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR2.AC_CODE IS '129';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR2.AC_CODE_DTL IS '1041 - C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR2.AC_DTL_TYP IS '3398 - ??? C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR2.AC_DTL_TYP_DTL IS '3398 - ??? C???CE C?E?????';



--
-- GLS_V_ACCNT_DTL_CURR_LMT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL_CURR_LMT
(AC_CODE, AC_CODE_DTL, AC_DTL_TYP, AC_DTL_TYP_DTL, CUR_CODE, 
 GRP_NO, CONN_BRN_NO, AC_DTL_DEGREE, CLASS_NO, CLASS_TYP, 
 DFLT, INACTV, INACTV_RSON, INACTV_DATE, DR_CR)
BEQUEATH DEFINER
AS 
(SELECT DISTINCT M.A_Code       AC_CODE,
                     NULL           AC_CODE_DTL,
