            d.inactv_rson,
            d.inactv_date,
            0                                          DR_CR
       FROM gls_accnt_dtl M, gls_accnt_dtl_curr D
      WHERE     m.ac_code_dtl = d.ac_code_dtl
            AND m.ac_dtl_typ = d.ac_dtl_typ
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE) IN (5, 6)
     UNION ALL
     SELECT DISTINCT
            M.AC_CODE,
            AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE)     AC_DTL_TYP,
            10                                         ac_dtl_typ_DTL,
            D.A_CY                                     CUR_CODE,
