     SELECT DISTINCT M.A_Code       AC_CODE,
                     NULL           AC_CODE_DTL,
                     M.AC_DTL_TYP,
                     0              ac_dtl_typ_DTL,
                     A_cy           cur_code,
                     A_GROUPING     GRP_NO,
                     NULL           CONN_BRN_NO,
                     NULL           AC_DTL_DEGREE,
