                     1              DR_CR
       FROM Ias_Acc_Tree M, Account_Curr D
      WHERE M.a_code = D.a_code AND MN_SUB = 1 AND M.AC_DTL_TYP = 0
     UNION ALL
     SELECT DISTINCT
            D.A_Code                                    AC_CODE,
            TO_CHAR (M.cash_no)                         AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code)     AC_DTL_TYP,
