            GROUP_NO                                    GRP_NO,
            CONN_BRN_NO                                 CONN_BRN_NO,
            NULL                                        AC_DTL_DEGREE,
            NULL                                        CLASS_NO,
            NULL                                        CLASS_TYP,
            D.DFLT,
            D.INACTIVE,
            NULL                                        inactv_rson,
            D.INACTIVE_DATE,
            1                                           DR_CR
       FROM CASH_IN_HAND M, IAS_CASH_IN_HAND_DTL D
      WHERE     M.CASH_NO = D.CASH_NO
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code) = 1
     UNION ALL
     SELECT DISTINCT
            D.A_Code                                    AC_CODE,
            TO_CHAR (D.BANK_NO)                         AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code)     AC_DTL_TYP,
            0                                           ac_dtl_typ_DTL,
            A_cy                                        CUR_CODE,
            GROUP_NO                                    GRP_NO,
            CONN_BRN_NO                                 CONN_BRN_NO,
            NULL                                        AC_DTL_DEGREE,
            NULL                                        CLSS_NO,
            NULL                                        CLSS_TYP,
            D.DFLT,
            D.INACTIVE,
            NULL                                        inactv_rson,
            D.INACTIVE_DATE,
            1                                           DR_CR
       FROM CASH_AT_BANK M, IAS_CASH_AT_BANK_DTL D
      WHERE YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (D.A_Code) = 2
     UNION ALL
     SELECT DISTINCT
            M.C_A_Code                                    AC_CODE,
            M.C_CODE                                      AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.C_A_Code)     AC_DTL_TYP,
            0                                             ac_dtl_typ_DTL,
            A_cy                                          CUR_CODE,
            C_GROUP_CODE                                  GRP_NO,
            CONN_BRN_NO                                   CONN_BRN_NO,
            C_DEGREE                                      AC_DTL_DEGREE,
            C_CLASS                                       CLASS_NO,
            C_CLASS_TYP                                   CLASS_TYP,
            D.DFLT_FLG,
            D.INACTIVE,
            NULL                                          inactv_rson,
            NULL                                          INACTIVE_DATE,
            1                                             DR_CR
       FROM customer M, customer_curr D
      WHERE     M.C_CODE = D.C_CODE
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.C_A_Code) = 3
     UNION ALL
     SELECT DISTINCT
            M.V_A_Code                                    AC_CODE,
            M.v_CODE                                      AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.V_A_Code)     AC_DTL_TYP,
            0                                             ac_dtl_typ_DTL,
            A_cy                                          CUR_CODE,
            V_GROUP_CODE                                  GRP_NO,
            CONN_BRN_NO                                   CONN_BRN_NO,
            V_DEGREE                                      AC_DTL_DEGREE,
            V_CLASS                                       CLSS_NO,
            NULL                                          CLSS_TYP,
            D.CUR_DFLT,
            D.INACTIVE,
            NULL                                          inactv_rson,
            NULL                                          INACTIVE_DATE,
            1                                             DR_CR
       FROM v_details M, VENDOR_CURR D
      WHERE     M.V_CODE = D.V_CODE
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (M.V_A_Code) = 4
     UNION ALL
     SELECT DISTINCT
            M.a_code                                    ac_code,
            TO_CHAR (EMP_NO)                            ac_code_dtl,
            ys_ac_dtl_pkg.get_ac_dtl_typ (M.a_code)     ac_dtl_typ,
            0                                           ac_dtl_typ_dtl,
            a_cy                                        cur_code,
            GRP_NO                                      GRP_NO,
            BRN_NO                                      CONN_BRN_NO,
            NULL                                        AC_DTL_DEGREE,
            CLASS_NO                                    CLSS_NO,
            NULL                                        CLSS_TYP,
            M.DFLT,
            d.inactive,
            NULL                                        inactv_rson,
            d.inactive_date,
            1                                           DR_CR
       FROM ACCOUNT_CURR M, S_EMP d
      WHERE ys_ac_dtl_pkg.get_ac_dtl_typ (M.a_code) = 7
     UNION ALL
     SELECT DISTINCT
            M.AC_CODE,
            M.AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE)     AC_DTL_TYP,
            1                                          ac_dtl_typ_DTL,
            D.CUR_CODE,
            GRP_CODE                                   GRP_NO,
            CONN_BRN_NO                                CONN_BRN_NO,
            NULL                                       AC_DTL_DEGREE,
            NULL                                       CLSS_NO,
            NULL                                       CLSS_TYP,
            D.DFLT,
            d.inactv,
            d.inactv_rson,
            d.inactv_date,
            1                                          DR_CR
       FROM gls_accnt_dtl M, gls_accnt_dtl_curr D
      WHERE     m.ac_code_dtl = d.ac_code_dtl
            AND m.ac_dtl_typ = d.ac_dtl_typ
            AND YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE) IN (5, 6)
     UNION ALL
     SELECT DISTINCT
            M.AC_CODE,
            AC_CODE_DTL,
            YS_AC_DTL_PKG.Get_Ac_Dtl_Typ (AC_CODE)     AC_DTL_TYP,
            10                                         ac_dtl_typ_DTL,
            D.A_CY                                     CUR_CODE,
            DCTR_GRP                                   GRP_NO,
            NULL                                       CONN_BRN_NO,
            NULL                                       AC_DTL_DEGREE,
            NULL                                       CLSS_NO,
            NULL                                       CLSS_TYP,
            D.DFLT,
            d.INACTIVE,
            NULL                                       inactv_rson,
            NULL                                       inactv_date,
            1                                          DR_CR
       FROM hps_dctr m, account_curr d
      WHERE     m.ac_code = d.a_code
            AND ys_ac_dtl_pkg.get_ac_dtl_typ (d.a_code) IN (5, 6));

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR_LMT.AC_CODE IS '129';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR_LMT.AC_CODE_DTL IS '1041 - C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR_LMT.AC_DTL_TYP IS '3398 - ??? C???CE C?E?????';

COMMENT ON COLUMN IAS20261.GLS_V_ACCNT_DTL_CURR_LMT.AC_DTL_TYP_DTL IS '3398 - ??? C???CE C?E?????';



--
-- GLS_V_ACCNT_DTL_PRIV_ALL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_ACCNT_DTL_PRIV_ALL
(U_ID, AC_CODE_DTL, AC_DTL_TYP, CUR_CODE, AC_CODE, 
 ADD_FLAG, VIEW_FLAG, AC_DTL_TYP_DTL)
BEQUEATH DEFINER
AS 
(SELECT D.U_ID,
           D.ac_code_dtl,
           D.AC_DTL_TYP,
           D.CUR_CODE,
           M.AC_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           1
      FROM GLS_ACCNT_DTL M, GLS_ACCNT_DTL_PRIV D
     WHERE M.AC_CODE_DTL = D.AC_CODE_DTL 
       AND M.AC_DTL_TYP = D.AC_DTL_TYP
    UNION ALL
    SELECT D.U_ID,
           M.DCTR_NO,
           Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_code),
           C.A_CY,
           M.AC_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           10
      FROM HPS_DCTR M, HPS_DCTR_PRV D, ACCOUNT_CURR C
     WHERE     M.DCTR_NO = D.DCTR_NO
           AND M.AC_code = C.A_code
           AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_code) IN (5, 6)
    union all
         SELECT P.u_id,
            D.AS_CODE,  
            Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_CODE),
            C.A_CY,
            M.AC_CODE,
            P.ADD_FLAG,
            P.VIEW_FLAG,
            90
       FROM GLS_AC_CODE_DTL_GRPS M, FAS_ASSETS_MST D,ACCOUNT_CURR C,PRIV_ACC P
      WHERE      M.ac_dtl_typ_DTL = 90
            AND  M.AC_code = C.A_code
            AND  M.AC_CODE =P.A_CODE
            AND Ys_Ac_Dtl_Pkg.Get_Ac_Dtl_Typ (M.AC_CODE) IN (5, 6)
    UNION ALL
    SELECT D.U_ID,
           TO_CHAR(M.CASH_NO),
           D.CASH_TYPE,
           D.A_CY,
           M.A_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           0
      FROM CASH_IN_HAND M, PRIV_CASH D
     WHERE  M.CASH_NO = D.CASH_NO
           AND D.CASH_TYPE=1
     UNION ALL
    SELECT D.U_ID,
           TO_CHAR(M.BANK_NO),
           D.CASH_TYPE,
           D.A_CY,
           M.A_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           0
      FROM CASH_AT_BANK M, PRIV_CASH D
     WHERE  M.BANK_NO = D.CASH_NO
           AND D.CASH_TYPE=2
      UNION ALL
    SELECT D.U_ID,
            M.C_CODE,
           3,
           D.A_CY,
           M.C_A_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           0
      FROM CUSTOMER M, IAS_PRIV_CUSTOMER D
     WHERE  M.C_CODE = D.C_CODE
       UNION ALL
    SELECT D.U_ID,
            M.V_CODE,
           4,
           D.A_CY,
           M.V_A_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           0
      FROM V_DETAILS M, IAS_PRIV_VENDOR D
     WHERE  M.V_CODE = D.V_CODE  
     UNION ALL
    SELECT D.U_ID,
           TO_CHAR(M.EMP_NO),
           7,
           C.A_CY,
           C.A_CODE,
           D.ADD_FLAG,
           D.VIEW_FLAG,
           0
      FROM S_EMP M,IAS_PARA_GEN S,
           S_EMP_PRV D,
           ACCOUNT A,
           ACCOUNT_CURR C
     WHERE     A.A_CODE = C.A_CODE
           AND A.AC_DTL_TYP = 7
           AND D.EMPNO_HRCHYNO =
                  CASE
                     WHEN S.EMP_PRV_TYP = 1 THEN M.EMP_NO
                     WHEN S.EMP_PRV_TYP = 2 THEN M.HRCHY_NO
                  END );


--
-- GLS_V_AC_CODE_DTL_SUB  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_AC_CODE_DTL_SUB
(AC_CODE_DTL_SUB, AC_CODE_DTL_SUB_L_NM, AC_CODE_DTL_SUB_F_NM, AC_CODE_DTL, AC_DTL_TYP, 
 AC_DTL_TYP_SUB, INACTV, INACTV_RSON, INACTV_DATE)
BEQUEATH DEFINER
AS 
(SELECT d.PTNT_NO
																					    			 ,d.PTNT_L_NM,d.PTNT_f_NM
																					    			 ,NULL,3,9
																					           ,inactv, NULL,NULL
																					       FROM hps_ptnt d
																					   UNION ALL
																					       SELECT  D.SUB_C_CODE, D.SUB_C_L_NM
																						            ,D.SUB_C_F_NM
																						            ,D.C_CODE,3,3
																						            ,D.INACTIVE, D.INACTIVE_RES,D.INACTIVE_DATE
																					       FROM CUSTOMER     M
																					           ,SUB_CUSTOMER D
																					        WHERE M.C_CODE=D.C_CODE
																					          AND NVL(M.USE_SUB_CSTMR_FLG,0)=1
																					          -- AND NVL(D.PST_FLG,0)=1 -- Add this CLMN if agent use sub_cstmr for other servic or others system 
																					          );


--
-- GLS_V_AC_DTL_CCPJACTV_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_AC_DTL_CCPJACTV_BLNC
(A_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, AC_DTL_TYP, BRN_NO, 
 CC_CODE, PJ_NO, ACTV_NO, A_CY, AMT, 
 AMT_F)
BEQUEATH DEFINER
AS 
SELECT m.a_code,
             d.ac_code_dtl,
             D.AC_CODE_DTL_SUB,
             d.ac_dtl_typ,
             D.BRN_NO,
             D.CC_CODE,
             D.PJ_NO,
             D.ACTV_NO,
             d.a_cy,
             NVL (SUM (d.amt), 0)       amt,
             NVL (SUM (d.amt_f), 0)     amt_f
        FROM account M, Ias_Post_Dtl D
       WHERE M.a_code = D.a_code
    GROUP BY m.a_code,
             d.ac_code_dtl,
             D.AC_CODE_DTL_SUB,
             d.ac_dtl_typ,
             D.BRN_NO,
             D.CC_CODE,
             D.PJ_NO,
             D.ACTV_NO,
             d.a_cy;


--
-- GLS_V_CSTMR_ACCNTS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CSTMR_ACCNTS
(AC_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, AC_CODE_DTL_L_NM, AC_CODE_DTL_F_NM, 
 AC_CODE_DTL_SUB_NM, CONN_BRN_NO, CUR_CODE, AC_DTL_TYP_SUB, CC_CODE)
BEQUEATH DEFINER
AS 
Select    M.C_A_Code     					Ac_Code
           ,M.C_Code     					Ac_Code_Dtl             
           ,Null         					Ac_Code_Dtl_Sub
           ,C_A_Name 							 Ac_Code_Dtl_L_Nm  
           ,Nvl(C_E_Name,C_A_Name) Ac_Code_Dtl_F_Nm
           ,Null   								 Ac_Code_Dtl_Sub_Nm
           ,M.Conn_Brn_No
           ,D.A_Cy 								Cur_Code
           ,3       							Ac_Dtl_Typ_Sub
           ,M.CC_CODE
   From Customer    M
       ,Customer_Curr D
  Where M.C_Code    = D.C_Code
        And Nvl(Conn_Hps_Sys,0)=0
    Union 
    Select  Ac.A_Code  					  Ac_Code
           ,M.C_Code     					Ac_Code_Dtl            
           ,Null        					Ac_Code_Dtl_Sub
           ,C_A_Name 							Ac_Code_Dtl_L_Nm  
           ,Nvl(C_E_Name,C_A_Name) Ac_Code_Dtl_F_Nm
           ,Null    							Ac_Code_Dtl_Sub_Nm
           ,M.Conn_Brn_No
           ,D.A_Cy 							Cur_Code
           ,3      						 	Ac_Dtl_Typ_Sub
           ,M.CC_CODE
      From Customer    M, Ias_Cst_Accnt Ac
       ,Account_Curr D
    Where M.C_Code    = Ac.C_Code
      And Ac.A_Code=D.A_Code
      AND EXISTS(SELECT 1 FROM Customer_Curr WHERE A_CY=D.A_CY AND C_CODE=M.C_CODE);


--
-- GLS_V_CSTMR_ACCNTS_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CSTMR_ACCNTS_PRIV
(U_ID, AC_CODE, AC_CODE_DTL, ADD_FLAG, VIEW_FLAG, 
 CUR_CODE, CC_CODE)
BEQUEATH DEFINER
AS 
Select      D.U_Id
           ,M.C_A_Code   Ac_Code
           ,M.C_Code     Ac_Code_Dtl             
           ,Add_Flag
           ,View_Flag 
           ,D.A_Cy Cur_Code
           ,M.CC_CODE           
   From Customer    M
       ,Ias_Priv_Customer D
  Where M.C_Code    = D.C_Code
   AND (M.CC_CODE IS NULL OR EXISTS (SELECT 1 FROM PRIVILEGE_CC WHERE U_ID=D.U_ID AND CC_CODE=M.CC_CODE AND ADD_FLAG=1) )        
    Union 
    Select  D.U_Id
           ,Ac.A_Code   Ac_Code
           ,M.C_Code     Ac_Code_Dtl            
           ,Add_Flag
           ,View_Flag                      
           ,D.A_Cy Cur_Code 
           ,M.CC_CODE         
      From   Customer    M, Ias_Cst_Accnt Ac
            ,Priv_Acc D
    Where   M.C_Code    = Ac.C_Code
      And Ac.A_Code=D.A_Code
      AND EXISTS(SELECT 1 FROM Ias_Priv_Customer WHERE A_CY=D.A_CY AND C_CODE=M.C_CODE)
       AND (M.CC_CODE IS NULL OR EXISTS (SELECT 1 FROM PRIVILEGE_CC WHERE U_ID=D.U_ID AND CC_CODE=M.CC_CODE AND ADD_FLAG=1));


--
-- GLS_V_CST_VNDR_ACC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CST_VNDR_ACC
(AC_CODE)
BEQUEATH DEFINER
AS 
SELECT  C_A_CODE ac_code FROM CUSTOMER
							UNION
							SELECT  V_A_CODE ac_code FROM V_DETAILS;


--
-- GLS_V_CST_VND_CCPJACTV_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CST_VND_CCPJACTV_BLNC
(C_A_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, AC_DTL_TYP, CC_CODE, 
 PJ_NO, ACTV_NO, A_CY, AMT, AMT_F)
BEQUEATH DEFINER
AS 
SELECT  m.C_A_CODE,d.ac_code_dtl,d.ac_code_dtl_sub,d.ac_dtl_typ,D.CC_CODE,D.PJ_NO,D.ACTV_NO , d.a_cy,NVL (SUM (d.amt), 0) amt, NVL (SUM (d.amt_f), 0) amt_f
                                From CUSTOMER M, Ias_Post_Dtl D
                                 WHERE (D.A_CODE = M.C_A_CODE  AND D.ac_code_dtl = M.C_CODE AND D.AC_DTL_TYP=3)
                                OR (NVL(M.C_VENDOR,'-1')=NVL(D.ac_code_dtl,'0') AND D.AC_DTL_TYP=4)
                                GROUP BY M.C_A_CODE,d.ac_code_dtl,d.ac_code_dtl_sub,d.ac_dtl_typ,D.CC_CODE,D.PJ_NO,D.ACTV_NO , d.a_cy;


--
-- GLS_V_DOC_INSTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_DOC_INSTL
(DOC_TYP, DOC_NO, DOC_SRL, RCRD_NO, AC_CODE, 
 AC_CODE_DTL, AC_CODE_DTL_SUB, AC_CODE_DTL_CSH, CC_CODE, PJ_NO, 
 ACTV_NO, COL_NO, PRM_CODE, REP_CODE, CHEQUE_NO, 
 DOC_BRN_NO, DIR_CODE1, DIR_CODE2, DIR_CODE3, DIR_CODE4, 
 DIR_CODE5, AC_DTL_TYP, DOC_SER_REF, DOC_TYPE_REF, DOC_SEQUENCE_REF, 
 RCRD_NO_REF, DOC_JV_TYPE_REF, CUR_CODE, AMT_L, AMT_F)
BEQUEATH DEFINER
AS 
SELECT CASE WHEN VOUCHER_TYPE = 1 THEN 2 ELSE 3 END     DOC_TYP,
           VOUCHER_NO                                       DOC_NO,
           V_SER                                            DOC_SRL,
           RCRD_NO                                          RCRD_NO,
           A_CODE                                           AC_CODE,
           AC_CODE_DTL,
           AC_CODE_DTL_SUB   ,
           AC_CODE_DTL_CSH,
           CC_CODE,
           PJ_NO,
           ACTV_NO,
           COL_NO,
           PRM_CODE,
           REP_CODE,
           CHEQUE_NO,
           DOC_BRN_NO,
           DIR_CODE1,
           DIR_CODE2,
           DIR_CODE3,
           DIR_CODE4,
           DIR_CODE5,
           AC_DTL_TYP,
           Doc_ser_Ref,          
           DOC_TYPE_REF,
           DOC_SEQUENCE_REF,
           RCRD_NO_REF,
           DOC_JV_TYPE_REF,
           A_CY                                            CUR_CODE,
           ABS (NVL (AC_AMT, 0) + NVL (OTR_AMT_L, 0))       AMT_L,
           ABS (NVL (AC_AMTF, 0) + NVL (OTR_AMT_F, 0))      AMT_F
      FROM VOUCHER_DETAIL
     WHERE DOC_SER_REF IS NOT NULL
    UNION ALL
    SELECT CASE WHEN VOUCHER_TYPE = 1 THEN 92 ELSE 93 END    DOC_TYP,
           VOUCHER_NO                                        DOC_NO,
           V_SER                                             DOC_SRL,
           RCRD_NO                                           RCRD_NO,
           A_CODE                                            AC_CODE,
           AC_CODE_DTL,
           AC_CODE_DTL_SUB,
           NULL AC_CODE_DTL_CSH,
           CC_CODE,
           PJ_NO,
           ACTV_NO,
           COL_NO,
           PRM_CODE,
           REP_CODE,
           CHEQUE_NO,
           DOC_BRN_NO,
           DIR_CODE1,
           DIR_CODE2,
           DIR_CODE3,
           DIR_CODE4,
           DIR_CODE5,
           AC_DTL_TYP,
           Doc_ser_Ref,
           DOC_TYPE_REF,
           DOC_SEQUENCE_REF,
           RCRD_NO_REF,
           DOC_JV_TYPE_REF,
           A_CY                                           CUR_CODE,
           ABS (NVL (AC_AMT, 0) + NVL (OTR_AMT_L, 0))        AMT_L,
           ABS (NVL (AC_AMTF, 0) + NVL (OTR_AMT_F, 0))       AMT_F
      FROM IAS_RQ_VCHR_DTL
     WHERE DOC_SER_REF IS NOT NULL
    UNION ALL
    SELECT 1                          DOC_TYP,
           J_DOC_NO                   DOC_NO,
           J_SER                      DOC_SRL,
           RCRD_NO                    RCRD_NO,
           A_CODE                     AC_CODE,
           AC_CODE_DTL,
           AC_CODE_DTL_SUB ,
           NULL AC_CODE_DTL_CSH,
           CC_CODE,
           PJ_NO,
           ACTV_NO,
           COL_NO,
           PRM_CODE,
           REP_CODE,
           CHEQUE_NO,
           DOC_BRN_NO,
           DIR_CODE1,
           DIR_CODE2,
           DIR_CODE3,
           DIR_CODE4,
           DIR_CODE5,
           AC_DTL_TYP,
           Doc_ser_Ref,
           DOC_TYPE_REF,
           DOC_SEQUENCE_REF,
           RCRD_NO_REF,
           DOC_JV_TYPE_REF,
           A_CY                       CUR_CODE,
           ABS (NVL (J_AMT, 0))       AMT,
           ABS (NVL (J_AMT_F, 0))     AMT_F
      FROM DETAIL_JOURNAL_V
     WHERE DOC_SER_REF IS NOT NULL
    UNION ALL
    SELECT 85                         DOC_TYP,
           J_DOC_NO                   DOC_NO,
           J_SER                      DOC_SRL,
           RCRD_NO                    RCRD_NO,
           A_CODE                     AC_CODE,
           AC_CODE_DTL,
           AC_CODE_DTL_SUB,
           NULL AC_CODE_DTL_CSH,
           CC_CODE,
           PJ_NO,
           ACTV_NO,
           COL_NO,
           PRM_CODE,
           REP_CODE,
           CHEQUE_NO,
           DOC_BRN_NO,
           DIR_CODE1,
           DIR_CODE2,
           DIR_CODE3,
           DIR_CODE4,
           DIR_CODE5,
           AC_DTL_TYP,
           Doc_ser_Ref,
           DOC_TYPE_REF,
           DOC_SEQUENCE_REF,
           RCRD_NO_REF,
           DOC_JV_TYPE_REF,
           A_CY                                           CUR_CODE,
           ABS (NVL (J_AMT, 0))       AMT,
           ABS (NVL (J_AMT_F, 0))     AMT_F
      FROM IAS_RQ_JRNL_DTL
     WHERE DOC_SER_REF IS NOT NULL;


--
-- GLS_V_INSTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_INSTL
(DOC_TYP_INSTL1, DOC_TYP_INSTL2, DOC_TYP_INSTL3, DOC_TYP_INSTL4, DOC_TYP, 
 LOV_NM, TBL_NM_MST, TBL_NM_DTL, DOC_SRL, BRN_NO, 
 DOC_NO, DOC_DATE, DOC_JV_TYPE_REF, HSTR, RCRD_NO, 
 AC_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB, AC_NM, CUR_RATE, 
 COL_NO, REP_CODE, DOC_BRN_NO, AC_DTL_TYP, DOC_DSC, 
 REF_NO, CC_CODE, PJ_NO, ACTV_NO, GLS_PRCSSD_FLG, 
 AD_U_ID, CUR_CODE, DOC_AMT, PAID_AMT, REM_AMT)
BEQUEATH DEFINER
AS 
WITH				 	       
    BAL_VW AS (SELECT SUM (ABS (AMT_L)) SUM_AC_AMT_L,SUM (ABS (AMT_F)) SUM_AC_AMT_F,CUR_CODE, DOC_SER_REF,RCRD_NO_REF,DOC_SEQUENCE_REF, Ac_code, AC_CODE_DTL, AC_CODE_DTL_SUB FROM GLS_V_DOC_INSTL
                       GROUP BY CUR_CODE,DOC_SER_REF,RCRD_NO_REF,DOC_SEQUENCE_REF,AC_CODE, AC_CODE_DTL, AC_CODE_DTL_SUB),
    PARA AS   (SELECT NVL(NO_OF_DECIMAL,2) NO_OF_DECIMAL FROM IAS_PARA_GL WHERE ROWNUM<=1)	,
    NOTE_DTL As  (SELECT  CASE WHEN M.NOTE_TYPE =1 THEN 21 ELSE 22 END DOC_TYP, M.NOTE_SER Doc_SRL    ,M.Brn_no     ,       M.NOTE_NO Doc_no     
                        ,M.NOTE_DATE Doc_date   ,       M.NOTE_TYPE_NO  doc_jv_type_ref 
                        ,M.A_CODE ac_code    ,   m.AC_CODE_DTL ac_code_dtl, NULL ac_code_dtl_sub  ,Ys_ac_dtl_pkg.Get_ac_dtl_typ (m.a_code) Ac_dtl_typ,
                       M.A_cy       ,       D.NOTE_DESC Doc_dsc    ,       NULL Ref_no     ,       M.Processed  ,       M.Approved   ,       M.Ad_u_id    ,  D.NOTE_AMT AMT_L    , D.NOTE_AMTF AMT_F
                 FROM NOTE M, NOTE_DETAIL D
                WHERE M.NOTE_TYPE = D.NOTE_TYPE 
                   AND M.NOTE_NO   = D.NOTE_NO
                   AND M.NOTE_SER  = D.NOTE_SER    
                 --  AND NVL(M.PROCESSED,0) = 0
                   AND NVL(APPROVED,0)=1  )			 	       
    SELECT 1  Doc_typ_instl1,
            85 Doc_typ_instl2,
            NULL Doc_typ_instl3,
            NULL Doc_typ_instl4,
            M.Doc_typ,
            'LOV_GLS_INSTL' Lov_nm,
            'NOTE' Tbl_nm_mst,
            'NOTE_DETAIL' Tbl_nm_dtl,
            M.Doc_srl Doc_srl,
            M.Brn_no Brn_no,
            M.Doc_no Doc_no,
            M.Doc_date Doc_date,
            M.doc_jv_type_ref Doc_jv_type_ref,
            0 Hstry,
            1 rcrd_no,
            M.Ac_code,
            M.Ac_code_dtl,
            M.Ac_code_dtl_sub,
            YS_AC_DTL_PKG.GET_AC_DTL_NM(M.AC_CODE_DTL,M.Ac_code,M.AC_DTL_TYP,1)AC_NM,            
            NULL Cur_rate,
            NULL Col_no,
            NULL Rep_code,
            NULL Doc_brn_no,
            m.Ac_dtl_typ,
            M.Doc_dsc Doc_dsc,
            M.Ref_no,
            NULL Cc_code,
            NULL Pj_no,
            NULL Actv_no,
            M.Processed Gls_prcssd_flg,
            M.Ad_u_id,
            M.A_cy Cur_code,
            ROUND ( CASE WHEN M.A_cy=IAS_GEN_PKG.GET_LOCAL_CUR THEN NVL (M.AMT_L, 0) ELSE  NVL (M.AMT_F, 0) END ,Para.No_of_decimal) Doc_amt,
            ROUND ( CASE WHEN Bal_vw.CUR_CODE=IAS_GEN_PKG.GET_LOCAL_CUR THEN  nvl(ABS(Bal_vw.SUM_AC_AMT_L),0) ELSE nvl(ABS(Bal_vw.SUM_AC_AMT_F),0) END, Para.No_of_decimal) Paid_amt,
            ROUND ( CASE WHEN M.A_cy=IAS_GEN_PKG.GET_LOCAL_CUR THEN NVL (M.AMT_L, 0) ELSE  NVL (M.AMT_F, 0) END
                     - CASE WHEN Bal_vw.CUR_CODE=IAS_GEN_PKG.GET_LOCAL_CUR THEN  nvl(ABS(Bal_vw.SUM_AC_AMT_L),0) ELSE nvl(ABS(Bal_vw.SUM_AC_AMT_F),0) END, Para.No_of_decimal)   Rem_amt
       FROM NOTE_DTL M, Bal_vw, Para
      WHERE  M.Approved = 1
        AND M.Doc_srl=Bal_vw.Doc_ser_ref(+)  
        AND M.AC_code = Bal_vw.Ac_code (+) 
        AND M.A_cy = Bal_vw.CUR_CODE(+)
        --AND M.AC_code_DTL = Bal_vw.Ac_code_dtl(+)
        --AND M.RCRD_NO = Bal_vw.RCRD_NO_REF(+)
       -- AND NVL(M.AC_code_DTL,'0')= Bal_vw.Ac_code_dtl(+)            
       -- AND M.Ac_code_dtl_sub  = Bal_vw.Ac_code_dtl_sub (+)              
        AND ROUND ( CASE WHEN M.A_cy=IAS_GEN_PKG.GET_LOCAL_CUR THEN NVL (M.AMT_L, 0) ELSE  NVL (M.AMT_F, 0) END
                     - CASE WHEN Bal_vw.CUR_CODE=IAS_GEN_PKG.GET_LOCAL_CUR THEN  nvl(ABS(Bal_vw.SUM_AC_AMT_L),0) ELSE nvl(ABS(Bal_vw.SUM_AC_AMT_F),0) END, Para.No_of_decimal)  > 0;


