--
-- GLS_V_PST_DTL_VCHR_CHQ  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_PST_DTL_VCHR_CHQ
(BNK_UONION, DOC_TYPE, JV_TYPE, DOC_NO, DOC_SER, 
 W_CODE, CC_CODE, PJ_NO, ACTV_NO, CASH_NO, 
 BANK_NO, A_CODE, AC_UN_CODE, A_CY, DR_AMT, 
 CR_AMT, DR_AMT_F, CR_AMT_F, AMT, AMT_F, 
 DOC_DATE, DOC_DUE_DATE, DOC_VALUE_DATE, DOC_DESC, MNTH, 
 D_YEAR, REF_NO, DOC_POST, DOC_CLOSE, INV_CLOSE, 
 CB_BEFORE, CB_AFTER, LC_NO, C_V_CODE, V_C_CODE, 
 COL_NO, REP_CODE, R_CODE, HRCHY_NO, WO_NO, 
 WO_SER, CHEQUE_NO, NOTE_NO, CHEQUE_VALUED, DOC_TYPE_REF, 
 DOC_JV_TYPE_REF, DOC_NO_REF, DOC_SER_REF, DOC_SEQUENCE, EXTERNAL_POST, 
 RCRD_NO, G_CODE, WHG_CODE, TRMNL_NAME, INSTALL_TYPE, 
 MOV_DOC_PY, FROM_CC_CODE, F_BRN_NO, DOC_BRN_NO, CASHIER_NO, 
 AUDIT_REF, AUDIT_REF_DESC, AUDIT_REF_U_ID, AUDIT_REF_DATE, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, UP_CNT, CNFRM, 
 CNFRM_DESC, CNFRM_U_ID, CNFRM_DATE, POST_U_ID, POST_DATE, 
 UNPOST_U_ID, UNPOST_DATE, CMP_NO, BRN_NO, BRN_YEAR, 
 BRN_USR, AC_CODE_DTL, AC_CODE_DTL_CSH, AC_DTL_TYP, INSRNCE_CMP_NO, 
 INSRNCE_BNF_NO, INSRNCE_CARD_NO, INSRNCE_CARD_NO_FMLY, NSRNCE_RLTN_TYP, CR_CARD_TYPE, 
 DOC_SEQUENCE_REF, RCRD_NO_REF, CRD_CARD_NO, CRD_CARD_NO_REF, CR_CARD_DSC, 
 AC_CODE_DTL_SUB, ENDRSMNT, DOC_NO_MNL, DOC_DATE_MNL, DUE_REF_NO, 
 DUE_NOTE)
BEQUEATH DEFINER
AS 
SELECT  0 BNK_UONION,
           CASE WHEN D.VOUCHER_TYPE=1 THEN 2 ELSE 3 END      DOC_TYPE,
           D.VOUCHER_PAY_TYPE            JV_TYPE,
           D.VOUCHER_NO          DOC_NO,
           D.V_SER               DOC_SER,
           0              W_CODE,
           D.CC_CODE,
           D.PJ_NO,
           D.ACTV_NO,
           D.CASH_NO,
           D.BANK_NO,
           D.A_CODE,
           IAS_ACODE_PKG.Get_AC_Analysis(P_a_code =>D.A_CODE),
           D.A_CY,
           CASE WHEN D.AC_AMT > 0 THEN AC_AMT ELSE NULL END       DR_AMT,
           CASE WHEN D.AC_AMT < 0 THEN AC_AMT * -1 ELSE NULL END CR_AMT,
           CASE WHEN D.AC_AMTF > 0 THEN AC_AMTF ELSE NULL END   DR_AMT_F,
           CASE WHEN D.AC_AMTF < 0 THEN AC_AMTF * -1 ELSE NULL END  CR_AMT_F,
           D.AC_AMT        AMT,
           D.AC_AMTF       AMT_F,
           M.VOUCHER_DATE    DOC_DATE,
           D.DUE_DATE        DOC_DUE_DATE,
           D.VALUE_DATE 		 DOC_VALUE_DATE,
           D.AC_DESC          DOC_DESC,
           1         MNTH,
           D.BRN_YEAR    D_YEAR,
           D.REF_NO,
           D.cheque_post             DOC_POST,
           0      DOC_CLOSE,
           0      INV_CLOSE,
           0     CB_BEFORE,
           0     CB_AFTER,
           D.LC_NO,
           NULL   C_V_CODE,
           NULL   V_C_CODE,
           NULL   COL_NO,
           D.REP_CODE,
           NULL  R_CODE,
           0      HRCHY_NO,
           D.WO_NO,
           D.WO_SER,
           D.CHEQUE_NO,
           D.NOTE_NO,
           D.CHEQUE_VALUED,
           D.DOC_TYPE_REF,
           D.DOC_JV_TYPE_REF,
           D.DOC_NO_REF,
           D.DOC_SER_REF,
           D.DOC_SEQUENCE,
           D.EXTERNAL_POST,
           D.RCRD_NO,
           0 G_CODE,
           0  WHG_CODE,
           0 TRMNL_NAME,
           NULL INSTALL_TYPE,
           NULL     MOV_DOC_PY,
           NULL       FROM_CC_CODE,
           NULL     F_BRN_NO,
           D.DOC_BRN_NO,
           D.CASHIER_NO,
           D.AUDIT_REF,
           D.AUDIT_REF_DESC,
           D.AUDIT_REF_U_ID,
           D.AUDIT_REF_DATE,
           D.AD_U_ID,
           D.AD_DATE,
           D.UP_U_ID,
           D.UP_DATE,
           D.UP_CNT,
           0 CNFRM,
           0 CNFRM_DESC,
           0 CNFRM_U_ID,
           0 CNFRM_DATE,
           D.POST_U_ID,
           D.POST_DATE,
           D.UNPOST_U_ID,
           D.UNPOST_DATE,
           D.CMP_NO,
           D.BRN_NO,
           D.BRN_YEAR,
           D.BRN_USR,
           D.AC_CODE_DTL,
           D.AC_CODE_DTL_CSH,
           D.AC_DTL_TYP,
           NULL    INSRNCE_CMP_NO,
           NULL            INSRNCE_BNF_NO,
           NULL          INSRNCE_CARD_NO,
           NULL         INSRNCE_CARD_NO_FMLY,
           NULL           INSRNCE_RLTN_TYP,
           NULL         CR_CARD_TYPE,
           D.DOC_SEQUENCE_REF,
           NULL           RCRD_NO_REF,
           D.CRD_CARD_NO,
           NULL        CRD_CARD_NO_REF,
           NULL        CR_CARD_DSC,
           D.AC_CODE_DTL_SUB,
           D.ENDRSMNT,
           0     DOC_NO_MNL,
           0    DOC_DATE_MNL,
           D.Due_Ref_No,
           D.Due_Note
    FROM   VOUCHERS M,VOUCHER_DETAIL D
   WHERE    M.V_SER=D.V_SER  
    AND M.VOUCHER_PAY_TYPE = 2
    AND NVL (D.CHEQUE_VALUED, 0) IN (0,1,2,3)
    AND M.Cheq_Type <> 0
    AND NVL (M.TRANSFER, 0) = 0          
    AND D.a_code NOT IN (SELECT a_code FROM cash_in_hand)           
 UNION ALL
    SELECT  1 BNK_UONION,
           CASE WHEN D.VOUCHER_TYPE=1 THEN 2 ELSE 3 END      DOC_TYPE,
           D.VOUCHER_PAY_TYPE            JV_TYPE,
           D.VOUCHER_NO          DOC_NO,
           D.V_SER               DOC_SER,
           0              W_CODE,
           D.CC_CODE,
           D.PJ_NO,
           D.ACTV_NO,
           D.CASH_NO,
           D.BANK_NO,
           ias_cshbnk_pkg.Get_A_code (2, M.cash_no) A_CODE,
           IAS_ACODE_PKG.Get_AC_Analysis(P_a_code =>ias_cshbnk_pkg.Get_A_code (2, M.cash_no)),
           D.A_CY,
           CASE WHEN D.AC_AMT > 0 THEN AC_AMT ELSE NULL END       DR_AMT,
           CASE WHEN D.AC_AMT < 0 THEN AC_AMT * -1 ELSE NULL END CR_AMT,
           CASE WHEN D.AC_AMTF > 0 THEN AC_AMTF ELSE NULL END   DR_AMT_F,
           CASE WHEN D.AC_AMTF < 0 THEN AC_AMTF * -1 ELSE NULL END  CR_AMT_F,
           D.AC_AMT        AMT,
           D.AC_AMTF       AMT_F,
           M.VOUCHER_DATE    DOC_DATE,
           D.DUE_DATE        DOC_DUE_DATE,
           D.VALUE_DATE 		 DOC_VALUE_DATE,
           D.AC_DESC          DOC_DESC,
           1         MNTH,
           D.BRN_YEAR    D_YEAR,
           D.REF_NO,
           D.cheque_post             DOC_POST,
           0     DOC_CLOSE,
           0     INV_CLOSE,
           0     CB_BEFORE,
           0     CB_AFTER,
           D.LC_NO,
           NULL   C_V_CODE,
           NULL   V_C_CODE,
           NULL   COL_NO,
           D.REP_CODE,
           NULL  R_CODE,
           0      HRCHY_NO,
           D.WO_NO,
           D.WO_SER,
           D.CHEQUE_NO,
           D.NOTE_NO,
           D.CHEQUE_VALUED,
           D.DOC_TYPE_REF,
           D.DOC_JV_TYPE_REF,
           D.DOC_NO_REF,
           D.DOC_SER_REF,
           D.DOC_SEQUENCE,
           D.EXTERNAL_POST,
           D.RCRD_NO,
           0 G_CODE,
           0  WHG_CODE,
           0 TRMNL_NAME,
           NULL INSTALL_TYPE,
           NULL     MOV_DOC_PY,
           NULL       FROM_CC_CODE,
           NULL     F_BRN_NO,
           D.DOC_BRN_NO,
           D.CASHIER_NO,
           D.AUDIT_REF,
           D.AUDIT_REF_DESC,
           D.AUDIT_REF_U_ID,
           D.AUDIT_REF_DATE,
           D.AD_U_ID,
           D.AD_DATE,
           D.UP_U_ID,
           D.UP_DATE,
           D.UP_CNT,
           0 CNFRM,
           0 CNFRM_DESC,
           0 CNFRM_U_ID,
           0 CNFRM_DATE,
           D.POST_U_ID,
           D.POST_DATE,
           D.UNPOST_U_ID,
           D.UNPOST_DATE,
           D.CMP_NO,
           D.BRN_NO,
           D.BRN_YEAR,
           D.BRN_USR,
           TO_CHAR(D.CASH_NO) AC_CODE_DTL,
           D.AC_CODE_DTL_CSH,
            2 AC_DTL_TYP,
           NULL    INSRNCE_CMP_NO,
           NULL            INSRNCE_BNF_NO,
           NULL          INSRNCE_CARD_NO,
           NULL         INSRNCE_CARD_NO_FMLY,
           NULL           INSRNCE_RLTN_TYP,
           NULL         CR_CARD_TYPE,
           D.DOC_SEQUENCE_REF,
           NULL           RCRD_NO_REF,
           D.CRD_CARD_NO,
           NULL        CRD_CARD_NO_REF,
           NULL        CR_CARD_DSC,
           D.AC_CODE_DTL_SUB,
           D.ENDRSMNT,
           0     DOC_NO_MNL,
           0    DOC_DATE_MNL,
           D.Due_Ref_No,
           D.Due_Note
    FROM   VOUCHERS M,VOUCHER_DETAIL D
   WHERE    M.V_SER=D.V_SER 
    AND  M.VOUCHER_TYPE IN(2) 
    AND M.VOUCHER_PAY_TYPE = 2
    AND NVL (D.CHEQUE_VALUED, 0) IN (0,1,2,3)
    AND M.Cheq_Type <> 0
    AND NVL (M.TRANSFER, 0) = 0          
    AND D.a_code NOT IN (SELECT a_code FROM cash_in_hand);


