--
-- GLS_V_RQ_VCHR_DTL_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_RQ_VCHR_DTL_YR
(VOUCHER_TYPE, VOUCHER_PAY_TYPE, VOUCHER_NO, CASH_NO, V_SER, 
 A_CODE, AC_CODE_DTL, AC_DTL_TYP, A_CY, AC_DESC, 
 AC_AMT, AC_AMTF, EX_RATE, CC_CODE, PJ_NO, 
 REP_CODE, COL_NO, PRM_CODE, DIR_CODE1, DIR_CODE2, 
 DIR_CODE3, DIR_CODE4, DIR_CODE5, CSH_BNK_NO, CHEQUE_NO, 
 VALUE_DATE, DUE_DATE, CHEQUE_VALUED, NOTE_NO, CRD_CARD_TYP, 
 CRD_CARD_NO, CRD_ACODE_REC_LETTER, CRD_COMM_AC, CRD_COMM_CALC_TYP, CRD_COMM_PER, 
 CRD_VAT_COMM_PER, CRD_DUE_PRD, CRD_PRCSS_MAX_COMM_AMT, CRD_PRSSES_NO, CRD_COMM_AMT_L, 
 CRD_VAT_COMM_AMT_L, CRD_WTHDRW_AMT_L, CRD_WTHDRW_AMT, CRD_COMM_AMT, CRD_ACY_MAX_COMM, 
 CRD_VAT_COMM_AMT, BANK_NO, BANK_NM, LC_NO, CI_NO, 
 CI_SER, HRS_PAY_NO, K_NO, K_SER, BILL_NO, 
 BILL_SER, I_NO, WO_NO, WO_SER, REF_NO, 
 OTR_AMT_L, OTR_AMT_F, RCRD_NO, BLMNT_DATE, NOTE, 
 CLC_TYP_NO_TAX, TAX_PRCNT, TAX_AMT, BNK_AC_CODE, DOC_SEQUENCE, 
 DOC_TYPE_REF, DOC_JV_TYPE_REF, DOC_NO_REF, DOC_SER_REF, REP_COMM_AMT, 
 AC_DTL_TYP_DR_COMM, AC_CODE_DR_COMM, AC_CODE_DTL_DR_COMM, AC_CODE_DTL_SUB_DR_COMM, CNTRCT_NO, 
 CNTRCT_SRL, CNTRCT_BTCH, T_CNTRCT_DATE, T_CNTRCT_DATE_HJ, F_CNTRCT_DATE, 
 F_CNTRCT_DATE_HJ, F_CNTRCT_DATE_AH, T_CNTRCT_DATE_AH, VNDR_CODE_CONN_TAX, VNDR_CODE_CONN_TAX_NM, 
 VNDR_TAX_CODE, VNDR_TAX_DSC, VNDR_BILL_NO, VNDR_BILL_DATE, CONN_V_NO, 
 CONN_V_SER, CONN_V_AMT, DOC_BRN_NO, ACTV_NO, AC_CODE_DTL_SUB, 
 FLD1, FLD2, FLD3, FLD4, FLD5, 
 EXTERNAL_POST, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 UP_CNT, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 DRIVER_NO, AR_BILL_NO, AR_BILL_SER, DOC_SEQUENCE_REF, RCRD_NO_REF)
