--
-- GLS_V_VCHR_IN_BNK_APPRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_VCHR_IN_BNK_APPRV
(VOUCHER_PAY_TYPE, VOUCHER_NO, DOC_PST_SQ_MST, DOC_PST_SQ, V_TYPE_NO, 
 VOUCHER_DATE, DOC_NO_MNL, DOC_DATE_MNL, REF_NO, REF_NO_DTL, 
 CASH_NO, CASH_ACY_MST, AC_CODE_DTL_MST, AC_DTL_TYP_MST, CASH_AMT, 
 CASH_AMTF, A_CODE, AC_CODE_DTL, AC_DTL_TYP, AC_CODE_DTL_SUB, 
 A_CY, AMT, AMTF, A_DESC, RETURN_RES, 
 CC_CODE_MST, CC_CODE, PJ_NO_MST, PJ_NO, ACTV_NO_MST, 
 ACTV_NO, DIR_CODE1_MST, DIR_CODE2_MST, DIR_CODE3_MST, DIR_CODE4_MST, 
 DIR_CODE5_MST, DIR_CODE1_DTL, DIR_CODE2_DTL, DIR_CODE3_DTL, DIR_CODE4_DTL, 
 DIR_CODE5_DTL, REP_CODE_MST, REP_CODE, PRM_CODE, BANK_NO, 
 A_CODE_END, AC_CODE_DTL_END, AC_DTL_TYP_END, AC_CODE_DTL_SUB_END, DOC_TYPE_REF, 
 DOC_JV_TYPE_REF, DOC_NO_REF, DOC_SER_REF, LC_NO, VALUE_DATE, 
 CHEQUE_NO, CHEQUE_VALUED, CHEQ_TYPE, BANK_A_CODE, RCRD_NO, 
 V_SER, CHEQUE_POST, AC_RATE_M, AC_RATE_D, MOVE_CHEQ_PY, 
 DOC_SEQUENCE, AD_U_ID, BRN_NO, DOC_BRN_NO_MST, DOC_BRN_NO_DTL, 
 BRN_YEAR, CMP_NO, BRN_USR, AUDIT_REF, AUDIT_REF_DESC, 
 AUDIT_REF_U_ID, AUDIT_REF_DATE, UP_U_ID, UP_DATE, UP_CNT, 
 UNPOST_U_ID, UNPOST_DATE, WO_NO, WO_SER, BANK_BRN_NO, 
 ENDRSMNT, STAND_BY, AC_DESC, AD_DATE)
BEQUEATH DEFINER
AS 
SELECT Mv.voucher_pay_type           voucher_pay_type,
           Mv.voucher_no                 voucher_no,
           Mv.doc_pst_sq                 doc_pst_sq_mst,
           Dv.doc_pst_sq                 doc_pst_sq,
           Mv.V_type_NO                  V_type_NO,
           Mv.voucher_date               voucher_date,
           Mv.Doc_No_Mnl                 Doc_No_Mnl , 
           Mv.DOC_DATE_MNL               DOC_DATE_MNL ,
           Mv.ref_no                     ref_no,
           Dv.ref_no                     ref_no_dtl,
           Mv.cash_no                    CASH_No,
           Mv.a_cy                       Cash_acy_Mst,
           Mv.AC_CODE_DTL                AC_CODE_DTL_MST,
           Mv.AC_DTL_TYP                 AC_DTL_TYP_MST,
           NVL (Mv.cash_amt, 0)          cash_amt,
           NVL (Mv.cash_amtf, 0)         cash_amtf,
           Dv.a_code                     a_code,
           Dv.ac_code_dtl                ac_code_dtl,
           Dv.ac_dtl_typ                 ac_dtl_typ,
           Dv.ac_code_dtl_sub            ac_code_dtl_sub,
           Dv.a_cy                       a_cy,
           Dv.ac_amt                     amt,
           Dv.ac_amtf                    amtf,
           Mv.a_desc                     a_desc,
           Dv.Return_Res                 Return_Res,
           Mv.cc_code                    cc_code_Mst,
           Dv.cc_code                    cc_code,
           Mv.pj_no                      pj_no_Mst,
           Dv.pj_no                      pj_no,
           Mv.Actv_No                    Actv_No_Mst,
           Dv.Actv_No                    Actv_No
            ,Mv.DIR_CODE1    DIR_CODE1_MST
            ,Mv.DIR_CODE2    DIR_CODE2_MST
            ,Mv.DIR_CODE3    DIR_CODE3_MST
            ,Mv.DIR_CODE4    DIR_CODE4_MST
            ,Mv.DIR_CODE5    DIR_CODE5_MST
            ,Dv.DIR_CODE1    DIR_CODE1_DTL
            ,Dv.DIR_CODE2    DIR_CODE2_DTL
            ,Dv.DIR_CODE3    DIR_CODE3_DTL
            ,Dv.DIR_CODE4    DIR_CODE4_DTL
            ,Dv.DIR_CODE5    DIR_CODE5_DTL
          ,Mv.rep_code                   rep_code_MST,
           Dv.rep_code                   rep_code,
           DV.PRM_CODE									 PRM_CODE,
           Dv.bank_no                    Bank_no,
           Dv.a_code_end                 a_code_end,
           Dv.AC_CODE_DTL_END            AC_CODE_DTL_END,
           Dv.AC_DTL_Typ_END             AC_DTL_Typ_END,
           Dv.AC_CODE_DTL_sub_END        AC_CODE_DTL_sub_END,
           Dv.DOC_TYPE_REF               DOC_TYPE_REF,
           Dv.DOC_JV_TYPE_REF            DOC_JV_TYPE_REF,
           Dv.DOC_NO_REF                 DOC_NO_REF,
           Dv.DOC_SER_REF                DOC_SER_REF,
           Dv.Lc_no                      Lc_no,
           Dv.due_date                   value_date,
           Dv.Cheque_No                  Cheque_No,
           NVL (Dv.cheque_valued, 0)     cheque_valued,
           NVL (Mv.cheq_type, 0)         cheq_type,
           Cb.a_code                     Bank_a_code,
           Dv.rcrd_no                    rcrd_no,
           Mv.v_ser                      v_ser,
           Cheque_Post,
           NVL (Mv.Ex_rate, 1)           ac_rate_M,
           NVL (Dv.Ex_rate, 1)           ac_rate_D,
           NVL (Mv.Move_Cheq_Py, 0)      Move_Cheq_Py,
           Dv.Doc_Sequence               Doc_Sequence,
           Mv.ad_u_id                    ad_u_id,
           Mv.Brn_no                     Brn_no,
           Mv.Doc_Brn_No                 Doc_Brn_No_Mst,
           Dv.Doc_Brn_No                 Doc_Brn_No_Dtl,
           Mv.Brn_Year                   Brn_Year,
           Mv.CMP_NO                     CMP_NO,
           Mv.BRN_USR                    BRN_USR,
           Dv.Audit_Ref                  Audit_Ref,
           Dv.Audit_Ref_Desc             Audit_Ref_Desc,
           Dv.Audit_Ref_U_Id             Audit_Ref_U_Id,
           Dv.Audit_Ref_Date             Audit_Ref_Date,
           Mv.Up_U_Id                    Up_U_Id,
           Mv.Up_Date                    Up_Date,
           Mv.Up_Cnt                     Up_Cnt,
           Mv.Unpost_U_Id                Unpost_U_Id,
           Mv.Unpost_Date                Unpost_Date,
           Dv.Wo_No                      Wo_No,
           Dv.Wo_Ser                     Wo_Ser,
           Dv.Bank_Brn_No                Bank_Brn_No,
           NVL (Endrsmnt, 0)             Endrsmnt,
           MV.Stand_By,
           dV.AC_DESC,
           dV.ad_date
      FROM Vouchers Mv, Voucher_Detail Dv, Cash_AT_Bank Cb
     WHERE     Mv.v_ser = Dv.v_ser
           AND Dv.AC_CODE_DTL = Cb.bank_no
           AND Mv.voucher_type = 2
           AND Mv.voucher_pay_type = 1
           AND Dv.Ac_dtl_typ = 2
           AND NVL (CB.MEDIATOR, 0) = 0
           AND NVL (Dv.cheque_valued, 0) IN (1, 2);


