           NVL (Endrsmnt, 0)             Endrsmnt
      FROM Vouchers Mv, Voucher_Detail Dv, Cash_at_Bank Cb
     WHERE     Mv.v_ser = Dv.v_ser
           AND Mv.cash_no = Cb.bank_no
           AND Mv.voucher_type = 2
           AND Mv.voucher_pay_type = 2
           AND Mv.Cheq_type = 3
           AND NVL (Dv.cheque_valued, 0) IN (1, 2);


--
-- GLS_V_VCHR_RCVD_CHEQ  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_VCHR_RCVD_CHEQ
(VOUCHER_PAY_TYPE, VOUCHER_NO, DOC_PST_SQ_MST, DOC_PST_SQ, V_TYPE_NO, 
 VOUCHER_DATE, DOC_NO_MNL, DOC_DATE_MNL, TRANSFER, REF_NO, 
 REF_NO_DTL, CASH_NO, COL_NO, BANK_ACY_MST, CASH_AMT, 
 CASH_AMTF, A_CODE, AC_CODE_DTL, AC_DTL_TYP, AC_CODE_DTL_SUB, 
 A_CY, AMT, AMTF, A_DESC, AC_DESC, 
 BANK_NO, A_CODE_END, AC_CODE_DTL_END, AC_DTL_TYP_END, AC_CODE_DTL_SUB_END, 
 RETURN_RES, CC_CODE_MST, CC_CODE, PJ_NO_MST, PJ_NO, 
 ACTV_NO_MST, ACTV_NO, DIR_CODE1_MST, DIR_CODE2_MST, DIR_CODE3_MST, 
 DIR_CODE4_MST, DIR_CODE5_MST, DIR_CODE1_DTL, DIR_CODE2_DTL, DIR_CODE3_DTL, 
 DIR_CODE4_DTL, DIR_CODE5_DTL, REP_CODE_MST, REP_CODE, REP_COMM_AMT, 
 AC_CODE_DR_COMM, AC_CODE_DTL_DR_COMM, AC_CODE_DTL_SUB_DR_COMM, PRM_CODE, DOC_BRN_NO_MST, 
 DOC_BRN_NO_DTL, DOC_TYPE_REF, DOC_JV_TYPE_REF, DOC_NO_REF, DOC_SER_REF, 
 DOC_TYPE_REF_DTL, DOC_JV_TYPE_REF_DTL, DOC_NO_REF_DTL, DOC_SER_REF_DTL, LC_NO, 
 VALUE_DATE, CHEQUE_NO, CHEQUE_VALUED, CHEQ_TYPE, ENDRSMNT, 
 ENDRSMNT_DATE, BANK_A_CODE, AC_RATE_M, AC_RATE_D, RCRD_NO, 
 V_SER, MOVE_CHEQ_PY, DOC_SEQUENCE, AD_U_ID, BRN_NO, 
 BRN_YEAR, CMP_NO, BRN_USR, AUDIT_REF, AUDIT_REF_DESC, 
 AUDIT_REF_U_ID, AUDIT_REF_DATE, AD_DATE, UP_U_ID, UP_DATE, 
 UP_CNT, UNPOST_U_ID, UNPOST_DATE, WO_NO, WO_SER, 
 BANK_BRN_NO, CHEQUE_POST)
BEQUEATH DEFINER
AS 
SELECT Mv.voucher_pay_type,
           Mv.voucher_no,
           Mv.doc_pst_sq                           doc_pst_sq_mst,
           Dv.doc_pst_sq                           doc_pst_sq,
           Mv.V_type_NO,
           Mv.voucher_date,
           Mv.Doc_No_Mnl  ,
           Mv.DOC_DATE_MNL ,
           Mv.TRANSFER ,
           Mv.ref_no                               ref_no,
           Dv.ref_no                               ref_no_dtl,
           Mv.cash_no,
           Mv.col_no                               col_no,
           Mv.a_cy                                 Bank_acy_Mst,
           NVL (Mv.cash_amt, 0)                    cash_amt,
           NVL (Mv.cash_amtf, 0)                   cash_amtf,
           Dv.a_code                               a_code,
           Dv.ac_code_dtl                          ac_code_dtl,
           Dv.ac_dtl_typ                           ac_dtl_typ,
           Dv.ac_code_dtl_sub                      ac_code_dtl_sub,
           Dv.a_cy                                 a_cy,
           ABS (Dv.ac_amt)                         amt,
           ABS (Dv.ac_amtf)                        amtf,
           Mv.a_desc                               a_desc,
           Dv.ac_desc,
           Dv.bank_no,
           Dv.a_code_end                           a_code_end,
           Dv.AC_CODE_DTL_END                      AC_CODE_DTL_END,
           Dv.AC_DTL_Typ_END                       AC_DTL_Typ_END,
           Dv.AC_CODE_DTL_Sub_END                  AC_CODE_DTL_Sub_END,
           Dv.Return_Res                           Return_Res,
           Mv.cc_code                              cc_code_Mst,
           Dv.cc_code,
           Mv.pj_no                                pj_no_Mst,
           Dv.pj_no,
           Mv.Actv_No                              Actv_No_Mst,
           Dv.Actv_No,
           Mv.dir_code1                            dir_code1_Mst,
           Mv.dir_code2                            dir_code2_Mst,
           Mv.dir_code3                            dir_code3_Mst,
           Mv.dir_code4                            dir_code4_Mst,
           Mv.dir_code5                            dir_code5_Mst,           
           Dv.dir_code1                            dir_code1_DTL,
           Dv.dir_code2                            dir_code2_DTL,
           Dv.dir_code3                            dir_code3_DTL,
           Dv.dir_code4                            dir_code4_DTL,
           Dv.dir_code5                            dir_code5_DTL,
           Mv.rep_code                             rep_code_MST,           
           Dv.rep_code                             rep_code,
           Dv.Rep_Comm_Amt                         Rep_Comm_Amt,
           Dv.Ac_Code_Dr_Comm                      Ac_Code_Dr_Comm,
           Dv.Ac_Code_DTL_Dr_Comm                  Ac_Code_DTL_Dr_Comm,
           Dv.Ac_Code_dtl_sub_Dr_Comm              Ac_Code_dtl_sub_Dr_Comm,
           DV.PRM_CODE											  		 PRM_CODE,
           Mv.Doc_Brn_No                           Doc_Brn_No_Mst,
           Dv.Doc_Brn_No                           Doc_Brn_No_Dtl,
           Dv.DOC_TYPE_REF                         DOC_TYPE_REF,
           Dv.DOC_JV_TYPE_REF                      DOC_JV_TYPE_REF,
           Dv.DOC_NO_REF                           DOC_NO_REF,
           Dv.DOC_SER_REF                          DOC_SER_REF,
           Dv.DOC_TYPE_REF_DTL,
           Dv.DOC_JV_TYPE_REF_DTL,
           Dv.DOC_NO_REF_DTL,
           Dv.DOC_SER_REF_DTL,
           Dv.Lc_no                                Lc_no,
           CASE
               WHEN NVL (Endrsmnt, 0) IN (1, 2)
               THEN
                  DV.due_date -- NVL (DV.Endrsmnt_Date, DV.due_date) 
               ELSE
                   Dv.due_date
           END                                     value_date,
           Dv.cheque_no                            cheque_no,
           NVL (Dv.cheque_valued, 0)               cheque_valued,
           NVL (Mv.cheq_type, 0)                   cheq_type,
           NVL (Endrsmnt, 0)                       Endrsmnt,
           CASE
               WHEN NVL (Endrsmnt, 0) IN (1, 2)
               THEN
                   NVL (DV.Endrsmnt_Date, DV.due_date)
               ELSE
                  DV.Endrsmnt_Date -- Dv.due_date
           END                                     Endrsmnt_Date,
           Cb.a_code                               Bank_a_code,
           NVL (Mv.Ex_rate, 1)                     ac_rate_M,
           NVL (Dv.Ex_rate, 1)                     ac_rate_D,
           Dv.rcrd_no                              rcrd_no,
           Mv.v_ser                                V_ser,
           NVL (Mv.Move_Cheq_Py, 0)                Move_Cheq_Py,
           Dv.Doc_Sequence                         Doc_Sequence,
           Mv.ad_u_id                              ad_u_id,
           Mv.Brn_no                               Brn_no,
           Mv.Brn_Year                             Brn_Year,
           Mv.CMP_NO                               CMP_NO,
           Mv.BRN_USR                              BRN_USR,
           Dv.Audit_Ref                            Audit_Ref,
           Dv.Audit_Ref_Desc                       Audit_Ref_Desc,
           Dv.Audit_Ref_U_Id                       Audit_Ref_U_Id,
           Dv.Audit_Ref_Date                       Audit_Ref_Date,
           Mv.Ad_Date                              Ad_Date,
           Mv.Up_U_Id                              Up_U_Id,
           Mv.Up_Date                              Up_Date,
           Mv.Up_Cnt                               Up_Cnt,
           NVL (Dv.Unpost_U_Id, Mv.Unpost_U_Id)    Unpost_U_Id,
           NVL (Dv.Unpost_Date, Mv.Unpost_Date)    Unpost_Date,
           Dv.Wo_No                                Wo_No,
           Dv.Wo_Ser                               Wo_Ser,
           Dv.Bank_Brn_No                          Bank_Brn_No,
           CASE
               WHEN NVL (Endrsmnt_post, 0) = 0 AND NVL (Dv.cheque_post, 0) = 0
               THEN
                   0
               ELSE
                   1
           END                                     cheque_post
      FROM Vouchers Mv, Voucher_Detail Dv, Cash_at_Bank Cb
     WHERE     Mv.v_ser = Dv.v_ser
           AND Mv.cash_no = Cb.bank_no
           AND Mv.voucher_type = 1
           AND Mv.voucher_pay_type = 2
           AND Mv.Cheq_type = 3
           AND (   NVL (Dv.cheque_valued, 0) IN (1, 2)
                OR NVL (Endrsmnt, 0) IN (1, 2));


--
-- GLS_V_VNDR_ACCNTS_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_VNDR_ACCNTS_PRIV
(U_ID, AC_CODE, AC_CODE_DTL, ADD_FLAG, VIEW_FLAG, 
 CUR_CODE)
BEQUEATH DEFINER
AS 
Select      D.U_Id
           ,M.V_A_Code   Ac_Code
           ,M.V_Code     Ac_Code_Dtl             
           ,Add_Flag
           ,View_Flag 
           ,D.A_Cy Cur_Code           
   From V_Details    M
       ,Ias_Priv_Vendor D
  Where M.V_Code    = D.V_Code        
    Union 
    Select  D.U_Id
           ,Ac.A_Code   Ac_Code
           ,M.V_Code     Ac_Code_Dtl            
           ,Add_Flag
           ,View_Flag                      
           ,D.A_Cy Cur_Code          
      From   V_Details    M, Ias_Vndr_Accnt Ac
            ,Priv_Acc D
    Where   M.V_Code    = Ac.V_Code
      And Ac.A_Code=D.A_Code
      AND EXISTS(SELECT 1 FROM Ias_Priv_Vendor WHERE A_CY=D.A_CY AND V_CODE=M.V_CODE);


--
-- GNR_TAX_PURCH_NO_VAT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_PURCH_NO_VAT_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 A_CY, CLC_TYP_NO_TAX, VAT_TYPE, VAT_AMT, DOC_AMT)
BEQUEATH DEFINER
AS 
SELECT Ias_Pi_Bill_Mst.BRN_NO,
             Ias_Pi_Bill_Mst.CMP_NO,
             Ias_Pi_Bill_Mst.Bill_Ser,
             Ias_Pi_Bill_Mst.Bill_No,
             Ias_Pi_Bill_Mst.Bill_Date,
             Ias_Pi_Bill_Mst.Bill_Currency,
             Ias_Pi_Bill_Mst.Clc_Typ_No_Tax  Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             DECODE (
                 NVL (Clc_Tax_Free_Qty_Flg, 0),
                 0, SUM (
                          NVL (Ias_Pi_Bill_Dtl.Vat_Amt, 0)
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)),
                 1, SUM (
                          NVL (Ias_Pi_Bill_Dtl.Vat_Amt, 0)
                        * (  NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                           + NVL (Ias_Pi_Bill_Dtl.Free_Qty, 0))
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)))
                 Vat_Amt,
             DECODE (
                 CALC_VAT_AMT_TYPE_AP,
                 1, SUM (
                          NVL (Ias_Pi_Bill_Dtl.I_Price, 0)
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)),
                 2, SUM (
                          ((  NVL (Ias_Pi_Bill_Dtl.I_Price, 0)
                            - NVL (Ias_Pi_Bill_Dtl.Dis_Amt, 0)))
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)))
                 Bill_Amt
        FROM Ias_Pi_Bill_Mst,
             Ias_Pi_Bill_Dtl,
             Ias_Itm_Mst,
             IAS_PARA_AP
       WHERE     Ias_Pi_Bill_Mst.Bill_Ser = Ias_Pi_Bill_Dtl.Bill_Ser
             AND Ias_Pi_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_PI_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (2, 3, 4)
             AND NVL (Ias_PI_Bill_Dtl.PUR_TYPE, 0) <> 2
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pi_Bill_Mst.Bill_Ser,
             Ias_Pi_Bill_Mst.Bill_No,
             Ias_Pi_Bill_Mst.Bill_Date,
             Ias_Pi_Bill_Mst.Bill_Currency,
             Ias_Pi_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pi_Bill_Mst.BRN_NO,
             Ias_Pi_Bill_Mst.CMP_NO,
             CALC_VAT_AMT_TYPE_AP
    UNION ALL
      SELECT Ias_Pi_Bill_Mst.BRN_NO,
             Ias_Pi_Bill_Mst.CMP_NO,
             Ias_Pi_Bill_Mst.Bill_Ser,
             Ias_Pi_Bill_Mst.Bill_No,
             Ias_Pi_Bill_Mst.Bill_Date,
             Ias_Pi_Bill_Mst.Bill_Currency,
             Ias_Pi_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,    
             DECODE (
                 NVL (Clc_Tax_Free_Qty_Flg, 0),
                 0, SUM (
                          NVL (Ias_Pi_Bill_Dtl.Vat_Amt, 0)
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)),
                 1, SUM (
                          NVL (Ias_Pi_Bill_Dtl.Vat_Amt, 0)
                        * (  NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                           + NVL (Ias_Pi_Bill_Dtl.Free_Qty, 0))
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)))
                 Vat_Amt,
             DECODE (
                 CALC_VAT_AMT_TYPE_AP,
                 1, SUM (
                          NVL (Ias_Pi_Bill_Dtl.I_Price, 0)
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)),
                 2, SUM (
                          ((  NVL (Ias_Pi_Bill_Dtl.I_Price, 0)
                            - NVL (Ias_Pi_Bill_Dtl.Dis_Amt, 0)))
                        * NVL (Ias_Pi_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Pi_Bill_Mst.Bill_Rate, 1)))
                 Bill_Amt
        FROM Ias_Pi_Bill_Mst,
             Ias_Pi_Bill_Dtl,
             Ias_Itm_Mst,
             IAS_PARA_AP
       WHERE     Ias_Pi_Bill_Mst.Bill_Ser = Ias_Pi_Bill_Dtl.Bill_Ser
             AND Ias_Pi_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_PI_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (1, 0)
             AND NVL (Ias_Pi_Bill_Dtl.Vat_amt, 0) = 0
             AND NVL (Ias_PI_Bill_Mst.PUR_TYPE, 0) <> 2
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pi_Bill_Mst.Bill_Ser,
             Ias_Pi_Bill_Mst.Bill_No,
             Ias_Pi_Bill_Mst.Bill_Date,
             Ias_Pi_Bill_Mst.Bill_Currency,
             Ias_Pi_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pi_Bill_Mst.BRN_NO,
             Ias_Pi_Bill_Mst.CMP_NO,
             CALC_VAT_AMT_TYPE_AP;


--
-- IAS_V_ACCNT_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ACCNT_BLNC
(A_CODE, AC_A_NM, AC_E_NM, A_CY, CRNT_BLNC_L, 
 CRNT_BLNC_F)
BEQUEATH DEFINER
AS 
SELECT M.A_CODE,M.A_NAME AC_A_NM,M.A_NAME_ENG AC_E_NM, D.A_CY,NVL(SUM(D.AMT),0) CRNT_BLNC_L  , NVL(SUM(D.AMT_F),0) CRNT_BLNC_F
		  FROM ACCOUNT M ,IAS_POST_DTL D
		 WHERE M.A_CODE = D.A_CODE 
		 GROUP BY M.A_CODE,M.A_NAME,M.A_NAME_ENG, D.A_CY;

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_BLNC.A_CODE IS '129 - —ﬁ„ «·Õ”«»';

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_BLNC.A_CY IS '8 - «·⁄„·…';



--
-- IAS_V_ACCNT_DTL_MSG  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ACCNT_DTL_MSG
(SQ_NO, AC_DTL_TYP, AC_CODE_DTL, A_NAME, E_NAME, 
 MOBILE_NO, SEND_LANG_NO, E_MAIL, MOV_TYP, TRNS_TYP, 
 SEND_TYP, PST_TYP, BLNC_AMT, MSG, INACTV, 
 INACTV_DATE, INACTV_USR_NO, INACTV_RSON, AD_U_ID, AD_DATE, 
 UP_U_ID, UP_DATE, UP_CNT, PR_REP, AD_TRMNL_NM, 
 UP_TRMNL_NM)
BEQUEATH DEFINER
AS 
Select A.SQ_NO, 1 Ac_Dtl_Typ, To_Char (B.Cash_No), B.Cash_Name, B.Cash_E_Name,
          A.Mobile_No, A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ,
          A.Send_Typ, A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date,
          A.Inactv_Usr_No, A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id,
          A.Up_Date, A.Up_Cnt, A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, Cash_In_Hand B
    Where A.Ac_Code_Dtl = B.Cash_No And A.Ac_Dtl_Typ = 1
   Union All
   Select A.SQ_NO, 2 Ac_Dtl_Typ, To_Char (B.Bank_No), B.Bank_Name, B.Bank_Name,
          A.Mobile_No, A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ,
          A.Send_Typ, A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date,
          A.Inactv_Usr_No, A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id,
          A.Up_Date, A.Up_Cnt, A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, Cash_At_Bank B
    Where A.Ac_Code_Dtl = B.Bank_No And A.Ac_Dtl_Typ = 2
   Union All
   Select A.SQ_NO, 3 Ac_Dtl_Typ, B.C_Code, B.C_A_Name, B.C_E_Name, A.Mobile_No,
          A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ, A.Send_Typ,
          A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date, A.Inactv_Usr_No,
          A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id, A.Up_Date, A.Up_Cnt,
          A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, Customer B
    Where A.Ac_Code_Dtl = B.C_Code And A.Ac_Dtl_Typ = 3
   Union All
   Select A.SQ_NO, 4 Ac_Dtl_Typ, B.V_Code, B.V_A_Name, B.V_E_Name, A.Mobile_No,
          A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ, A.Send_Typ,
          A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date, A.Inactv_Usr_No,
          A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id, A.Up_Date, A.Up_Cnt,
          A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, V_Details B
    Where A.Ac_Code_Dtl = B.V_Code And A.Ac_Dtl_Typ = 4
   Union All
   Select A.SQ_NO, 5 Ac_Dtl_Typ, B.Ac_Code_Dtl, B.Ac_Code_Dtl_L_Nm, B.Ac_Code_Dtl_F_Nm,
          A.Mobile_No, A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ,
          A.Send_Typ, A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date,
          A.Inactv_Usr_No, A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id,
          A.Up_Date, A.Up_Cnt, A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, Gls_V_Accnt_Dtl B
    Where A.Ac_Code_Dtl = B.Ac_Code_Dtl And A.Ac_Dtl_Typ = 5
   Union All
   Select A.SQ_NO, 6 Ac_Dtl_Typ, B.Ac_Code_Dtl, B.Ac_Code_Dtl_L_Nm, B.Ac_Code_Dtl_F_Nm,
          A.Mobile_No, A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ,
          A.Send_Typ, A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date,
          A.Inactv_Usr_No, A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id,
          A.Up_Date, A.Up_Cnt, A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, Gls_V_Accnt_Dtl B
    Where A.Ac_Code_Dtl = B.Ac_Code_Dtl And A.Ac_Dtl_Typ = 6
   Union All
   Select A.SQ_NO, 7 Ac_Dtl_Typ, To_Char (B.Emp_No), B.Emp_L_Nm, B.Emp_F_Nm,
          A.Mobile_No, A.Send_Lang_No, A.E_Mail, A.Mov_Typ, A.Trns_Typ,
          A.Send_Typ, A.Pst_Typ, A.Blnc_Amt, A.Msg, A.Inactv, A.Inactv_Date,
          A.Inactv_Usr_No, A.Inactv_Rson, A.Ad_U_Id, A.Ad_Date, A.Up_U_Id,
          A.Up_Date, A.Up_Cnt, A.Pr_Rep, A.Ad_Trmnl_Nm, A.Up_Trmnl_Nm
     From Ias_Accnt_Dtl_Msg A, S_Emp B
    Where A.Ac_Code_Dtl = B.Emp_No And A.Ac_Dtl_Typ = 7;

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_DTL_MSG.AC_DTL_TYP IS '3398 - ‰Ê⁄ «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_DTL_MSG.AC_CODE_DTL IS '1041 - «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_DTL_MSG.MOBILE_NO IS '770 - —ﬁ„ «·ÃÊ«·';

COMMENT ON COLUMN IAS20261.IAS_V_ACCNT_DTL_MSG.E_MAIL IS '520 - «·»—Ìœ «·«·ﬂ —Ê‰Ì';

