--
-- IAS_V_AC_AMT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AC_AMT
(A_CODE, A_CY, AMT, AMT_F, DR_AMT, 
 CR_AMT, DR_AMT_F, CR_AMT_F)
BEQUEATH DEFINER
AS 
SELECT A_CODE,A_CY,SUM(AMT) AMT,SUM(AMT_F) AMT_F ,SUM(DR_AMT) DR_AMT, 
					SUM(CR_AMT) CR_AMT, sum(DR_AMT_F) DR_AMT_F, sum(CR_AMT_F) CR_AMT_F
					FROM Ias_Post_Dtl 
					GROUP BY A_CODE,A_CY;

COMMENT ON COLUMN IAS20261.IAS_V_AC_AMT.A_CODE IS '129 - —ﬁ„ «·Õ”«»';

COMMENT ON COLUMN IAS20261.IAS_V_AC_AMT.A_CY IS '8 - «·⁄„·…';



--
-- IAS_V_AC_CODE_DTL_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AC_CODE_DTL_BLNC
(A_CODE, AC_CODE_DTL, AC_DTL_TYP, A_CY, AMT, 
 AMT_F)
BEQUEATH DEFINER
AS 
Select m.a_code,d.ac_code_dtl,d.ac_dtl_typ, d.a_cy,ROUND(NVL (SUM (d.amt), 0),2) amt, ROUND(NVL (SUM (d.amt_f), 0),2) amt_f
							    From account M, Ias_Post_Dtl D
								 where M.a_code  = D.a_code
								 AND m.AC_DTL_TYP = d.AC_DTL_TYP
								    AND NVL(m.AC_DTL_TYP,0)<>0
						        group by m.a_code,d.ac_code_dtl,d.ac_dtl_typ ,d.a_cy;


--
-- IAS_V_AC_CODE_DTL_LCL_BLNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AC_CODE_DTL_LCL_BLNC
(A_CODE, AC_CODE_DTL, AC_DTL_TYP, AMT)
BEQUEATH DEFINER
AS 
SELECT m.a_code,
							             d.ac_code_dtl,
							             d.ac_dtl_typ,
							             NVL (SUM (d.amt), 0)       amt
							        FROM account M, Ias_Post_Dtl D
							       WHERE M.a_code = D.a_code 
							       AND m.AC_DTL_TYP = d.AC_DTL_TYP
							       AND NVL(m.AC_DTL_TYP,0)<>0
							    GROUP BY m.a_code,
							             d.ac_code_dtl,
							             d.ac_dtl_typ;


--
-- IAS_V_AC_CODE_DTL_PRIV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_AC_CODE_DTL_PRIV
(U_ID, AC_CODE_DTL, AC_DTL_TYP, A_CY, ADD_FLAG, 
 VIEW_FLAG)
BEQUEATH DEFINER
AS 
SELECT U_ID ,TO_CHAR(CASH_NO) AC_CODE_DTL ,CASH_TYPE AC_DTL_TYP ,A_CY ,ADD_FLAG,VIEW_FLAG 
FROM PRIV_CASH
UNION
SELECT U_ID ,C_CODE AC_CODE_DTL ,3 AC_DTL_TYP ,A_CY ,ADD_FLAG,VIEW_FLAG
FROM IAS_PRIV_CUSTOMER
UNION
SELECT U_ID ,V_CODE AC_CODE_DTL ,4 AC_DTL_TYP ,A_CY ,ADD_FLAG,VIEW_FLAG
FROM IAS_PRIV_VENDOR
UNION
SELECT U_ID , AC_CODE_DTL ,AC_DTL_TYP ,CUR_CODE A_CY ,ADD_FLAG,VIEW_FLAG
FROM GLS_ACCNT_DTL_PRIV;


