--
-- IAS_V_CHK_CSTTRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_CHK_CSTTRNS
(DOC_TYPE, C_CODE, A_CY, DOC_NO, JV_TYPE, 
 DOC_SER, CC_CODE, RCRD_NO)
BEQUEATH DEFINER
AS 
Select 1 doc_type,D.ac_code_dtl c_code,a_cy a_cy,D.j_doc_no doc_no,D.jv_type jv_type ,
        M.j_ser doc_ser,D.cc_code cc_code , D.rcrd_no
   From master_journal_v M,detail_journal_v D ,Customer C
  where M.j_ser  = D.j_ser
    and D.a_code = C.c_a_code  
    and D.ac_code_dtl   = C.c_code  
    and D.ac_dtl_typ=3
    and nvl(stand_by,0) = 0
 Minus
 Select doc_type,ac_code_dtl c_code,a_cy,doc_no doc_no,jv_type jv_type, 
        doc_ser,cc_code,rcrd_no
   From Ias_Post_dtl
  where doc_type=1
    and ac_dtl_typ=3;


--
-- IAS_V_CHK_POST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_CHK_POST
(DOC_TYPE, JV_TYPE, DOC_NO, W_CODE, CC_CODE, 
 DOC_SER)
BEQUEATH DEFINER
AS 
Select doc_type,jv_type,doc_no,w_code,cc_code,Doc_ser
                    From Ias_Post_Mst where Doc_ser in ( select Doc_ser From Ias_Post_Dtl 
                                                          Minus
