(C_CODE, C_A_NAME, C_E_NAME, A_CY, DOC_NO, 
 DOC_TYPE, DOC_JV_TYPE, DOC_SER, DOC_DATE, DOC_DUE_DATE, 
 DR_AMT, CR_AMT, DR_AMTF, CR_AMTF, DOC_DESC, 
 CASH_NO, CC_CODE, PJ_NO, W_CODE, COL_NO, 
 REP_CODE, DOC_POST, REF_NO, WO_NO, WO_SER, 
