--
-- IAS_V_ERR_CC_OUTGOING  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ERR_CC_OUTGOING
(OUT_SER, CC_CODE)
BEQUEATH DEFINER
AS 
Select OUT_SER,CC_CODE 
					   From Ias_Outgoing_Mst where out_ser is not null 
					  Minus 
					 Select OUT_SER,CC_CODE 
					   From Ias_Outgoing_Dtl where out_ser is not null;


--
-- IAS_V_GRN_PO_DIFF  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_GRN_PO_DIFF
(PO_NO, PO_SER, I_CODE, UNIT, W_CODE, 
 PO_QTY, GRN_QTY, DIFF)
BEQUEATH DEFINER
AS 
SELECT b.po_no,
             b.po_ser,
             b.i_code,
             b.itm_unt
                 unit,
             b.w_code,
               NVL (SUM (NVL (b.i_qty, 0)), 0)
             / DECODE (COUNT (d.i_code), 0, 1, COUNT (d.i_code))
                 po_qty,
             NVL (SUM (NVL (d.i_qty, 0)), 0)
                 grn_qty,
             ((    NVL (SUM (NVL (b.i_qty, 0)), 0)
                 / DECODE (COUNT (d.i_code), 0, 1, COUNT (d.i_code))
               - NVL (SUM (NVL (d.i_qty, 0)), 0)))
                 diff
        FROM p_order       a,
             p_order_detail b,
             ias_itm_mst   c,
             GRN_DETAIL    d
       WHERE     a.po_no = b.po_no
             AND a.po_ser = b.po_ser
             AND b.i_code = c.i_code
             AND NVL (b.Canceled, 0) = 0
             AND b.i_code = d.i_code(+)
             AND b.po_ser = d.po_ser(+)
    GROUP BY b.po_no,
             b.po_ser,
             b.i_code,
             b.itm_unt,
             b.w_code,
             b.rcrd_no
    ORDER BY b.po_no, b.rcrd_no;

COMMENT ON COLUMN IAS20261.IAS_V_GRN_PO_DIFF.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_GRN_PO_DIFF.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_ITEM_SERIALNO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITEM_SERIALNO
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, DOC_SER, DOC_DATE, 
 I_CODE, ITM_UNT, P_SIZE, SERIALNO, DESC_NO, 
 W_CODE, CC_CODE, PJ_NO, ACTV_NO, EXPIRE_DATE, 
 BATCH_NO, FREE_FLG, BILL_COST, OUT_NO, OUT_GR_SER, 
 IN_OUT, RCRD_NO, RCRD_NO_DOC, ACTIVE, ACTIVE_U_ID, 
 ACTIVE_DATE, ACTIVE_NOTE, EXTERNAL_POST, AD_DATE, UP_DATE, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, QR_CODE, 
 SRL_SQ, AD_U_ID, UP_U_ID, UP_CNT, AD_TRMNL_NM, 
 UP_TRMNL_NM, PR_REP)
BEQUEATH DEFINER
AS 
Select 
		 Doc_Type,  Bill_Doc_Type,  Doc_No, 
		    Doc_Ser,  Doc_Date,  I_Code, 
		    Itm_Unt,  P_Size,  Serialno, 
		    Desc_No,  W_Code,  Cc_Code, 
		    Pj_No,  Actv_No,  Expire_Date, 
		    Batch_No,  Free_Flg,  Bill_Cost, 
		    Out_No,  Out_Gr_Ser,  In_Out, 
		    Rcrd_No,  Rcrd_No_Doc,  Active, 
		    Active_U_Id,  Active_Date,  Active_Note, 
		    External_Post,  Ad_Date,  Up_Date, 
		    Cmp_No,  Brn_No,  Brn_Year, 
		    Brn_Usr,  Qr_Code,  Srl_Sq, 
		    Ad_U_Id,  Up_U_Id,  Up_Cnt, 
		    Ad_Trmnl_Nm,  Up_Trmnl_Nm,  Pr_Rep
		From Ias_Item_Serialno 
		Union All
		Select
		 8 Doc_Type,  Bill_Doc_Type,  Doc_No, 
		    Doc_Ser,  Doc_Date,  I_Code, 
		    Itm_Unt,  P_Size,  Serialno, 
		    Desc_No,  W_Code,  Cc_Code, 
		    Pj_No,  Actv_No,  Expire_Date, 
		    Batch_No,  Free_Flg,  Bill_Cost, 
		    Out_No,  Out_Gr_Ser,  1 In_Out, 
		    Rcrd_No,  Rcrd_No_Doc,  Active, 
		    Active_U_Id,  Active_Date,  Active_Note, 
		    External_Post,  Ad_Date,  Up_Date, 
		    Cmp_No,  Brn_No,  Brn_Year, 
		    Brn_Usr,  Qr_Code,  Srl_Sq, 
		    Ad_U_Id,  Up_U_Id,  Up_Cnt, 
		    Ad_Trmnl_Nm,  Up_Trmnl_Nm,  Pr_Rep
		    From Ias_Item_Serialno 
		    Where Doc_Type=7
		    And Not Exists ( Select 1 From Ias_Whtrns_Dtl
		                      Where Tr_Inout_Type=2
		                       And F_Tr_Ser= Ias_Item_Serialno.Doc_Ser
		                       And I_Code  = Ias_Item_Serialno.I_Code
		                       And Rownum<=1
		                   );

