--
-- IAS_V_ITM_DISC_ONLINE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_DISC_ONLINE
(I_CODE, W_CODE, ITM_UNT, CUR_CODE, DIS_PER, 
 DIS_AMT)
BEQUEATH DEFINER
AS 
SELECT  D.I_CODE, D.W_CODE,D.ITM_UNT, A_CY CUR_CODE,
          decode(AMT_TYPE,0,NVL(AMT, 0),0) DIS_PER,
             decode(AMT_TYPE,1,NVL(AMT,0),0)DIS_amt
          FROM SALES_DISC D , IAS_SALES_DISC_MST M 
         WHERE M.DOC_SER = D.DOC_SER
               AND M.SALES_DISC_TYPE = 1
               AND IAS_GEN_PKG.GET_CURDATE BETWEEN D.F_DATE AND D.T_DATE
               AND NVL(M.INACTIVE,0) =0;

COMMENT ON COLUMN IAS20261.IAS_V_ITM_DISC_ONLINE.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_DISC_ONLINE.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_DISC_ONLINE.CUR_CODE IS '8 - «·⁄„·…';



--
-- IAS_V_ITM_EXPBTCH_AVLQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_EXPBTCH_AVLQTY
(I_CODE, I_NAME, ITM_UNT, W_CODE, EXPIRE_DATE, 
 BATCH_NO, AVL_QTY, RSRV_QTY, I_PRICE, CONN_BRN_NO, 
 I_IMG)
BEQUEATH DEFINER
AS 
Select M.I_Code, 
					          M.I_Name,
					          D.Itm_Unt,
					          Mov.W_Code,
					          Mov.Expire_Date,
					          Mov.Batch_No,          
					          (Mov.Avl_Qty / D.P_Size) Avl_Qty,
					          (Select Nvl (Sum (Nvl (Cp_Qty, 0)), 0) / Nvl (D.P_Size, 1)
					             From Ias_Reserve_Dtl
					            Where I_Code = M.I_Code
					              And Nvl (W_Code, 0) = Mov.W_Code
					              And T_Date >= Sysdate
					              And Nvl (Reserved, 0) = 1
					              And Nvl (Cp_Qty, 0) >= 0) Rsrv_Qty,
					          I.I_Price,
					          Wh.Conn_Brn_No,
					          M.I_Img
					     From Ias_Itm_Mst M,
					          Ias_Itm_Dtl D,
					          Ias_V_Itm_Mov_Exp_Btch_Avlqty Mov,
					          Ias_Item_Price I,
					          Warehouse_Details Wh
					    Where M.I_Code = D.I_Code
					      And M.I_Code = Mov.I_Code
					      And Mov.W_Code = Wh.W_Code
					      And M.I_Code(+) = I.I_Code
					      And D.I_Code = Mov.I_Code
					      And D.I_Code(+) = I.I_Code
					      And D.Itm_Unt(+) = I.Itm_Unt
					      And Mov.I_Code(+) = I.I_Code      
					      And Exists (
					                Select 1
					                  From Ias_Pricing_Levels
					                 Where Nvl (Lev_Deflt, 0) = 1 And Lev_No(+) = I.Lev_No
					                       And Rownum <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_ITM_EXPBTCH_AVLQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_EXPBTCH_AVLQTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_ITM_EXPBTCH_AVLQTY.I_PRICE IS '230 - «·”⁄—';



