--
-- IAS_V_NY_P_ORDER_DETAIL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_NY_P_ORDER_DETAIL
(PO_TYPE, PO_NO, PO_SER, I_CODE, I_QTY, 
 FREE_QTY, P_SIZE, P_QTY, W_CODE, DOC_TYPE_REF, 
 PR_NO, PR_SER, QT_NO, QT_SER, I_PRICE, 
 RCRD_NO, ITEM_DESC, BARCODE, USE_ATTCH, REC_ATTCH, 
 PI_QTY, PI_FREE_QTY, AVL_QTY, ITM_CWTAVG, LAST_INCOME_PRICE, 
 DOC_SEQUENCE, DOC_SEQUENCE_PRQ, CANCELED, EXPIRE_DATE, BATCH_NO, 
 I_LENGTH, I_WIDTH, I_HEIGHT, I_NUMBER, DIS_AMT, 
 DIS_AMT_MST, DIS_PER, DIS_AMT_DTL, DIS_PER2, DIS_AMT_DTL2, 
 DIS_PER3, DIS_AMT_DTL3, UNIT_SIZE, U_QTY, NOT_BILL_PRV_QTY, 
 BILL_PRV_QTY, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 UP_CNT, ITM_UNT, WT_QTY, CC_CODE, PJ_NO, 
 ACTV_NO, WT_UNT, I_PRICE_VAT, OTHR_AMT, VAT_PER, 
 VAT_AMT, ARGMNT_NO, DLVRY_DATE, PKG_UNT, PKG_UNT_SIZE, 
 PKG_QTY, PKG_LENGTH, PKG_WIDTH, PKG_HEIGHT, PKG_SIZE, 
 PKG_WEIGHT, DOC_NO_REF, DOC_SER_REF, DOC_SEQUENCE_REF, PJ_NO_REF)
BEQUEATH DEFINER
AS 
Select PO.PO_TYPE, PO.PO_NO, PO.PO_SER, PO.I_CODE,Mov_Data.I_Qty I_QTY, Mov_Data.Free_Qty FREE_QTY, PO.P_SIZE,(Mov_Data.I_Qty*PO.P_Size) P_QTY , PO.W_CODE, PO.DOC_TYPE_REF, PO.PR_NO,
        PO.PR_SER, PO.QT_NO, PO.QT_SER, PO.I_PRICE, PO.RCRD_NO, PO.ITEM_DESC, PO.BARCODE, PO.USE_ATTCH, PO.REC_ATTCH, PO.PI_QTY, PO.PI_FREE_QTY, PO.AVL_QTY, 
        PO.ITM_CWTAVG, PO.LAST_INCOME_PRICE, PO.DOC_SEQUENCE, PO.DOC_SEQUENCE_PRQ, PO.CANCELED, PO.EXPIRE_DATE, PO.BATCH_NO, PO.I_LENGTH,
        PO.I_WIDTH, PO.I_HEIGHT, PO.I_NUMBER, PO.DIS_AMT, PO.DIS_AMT_MST, PO.DIS_PER, PO.DIS_AMT_DTL, PO.DIS_PER2, PO.DIS_AMT_DTL2, PO.DIS_PER3, PO.DIS_AMT_DTL3,
        PO.UNIT_SIZE, PO.U_QTY, PO.NOT_BILL_PRV_QTY, PO.BILL_PRV_QTY, PO.CMP_NO, PO.BRN_NO, PO.BRN_YEAR, PO.BRN_USR, PO.UP_CNT, PO.ITM_UNT, PO.WT_QTY, PO.CC_CODE,
        PO.PJ_NO, PO.ACTV_NO, PO.WT_UNT ,
        I_Price_Vat, Othr_Amt, 
     Vat_Per, Vat_Amt, Argmnt_No, 
     Dlvry_Date,  Pkg_Unt, 
     Pkg_Unt_Size, Pkg_Qty, Pkg_Length, 
     Pkg_Width, Pkg_Height, Pkg_Size, 
     Pkg_Weight, Doc_No_Ref, Doc_Ser_Ref, 
     Doc_Sequence_Ref,  Pj_No_Ref      
    From P_Order_Detail PO,(Select Doc_Ser,I_Code,DOC_SEQUENCE,Sum(Nvl(I_Qty,0)) I_Qty,Sum(Nvl(Free_Qty,0)) Free_Qty 
                          From( Select Po_Ser Doc_Ser,I_Code,DOC_SEQUENCE ,Nvl(I_Qty,0) I_Qty,Nvl(Free_Qty,0) Free_Qty
                                  From P_Order_Detail 
                                Union All
                                Select PO_SER Doc_Ser,I_Code,DOC_SEQUENCE_GRN_PO DOC_SEQUENCE,Sum(Nvl(I_Qty,0))*-1 I_Qty,Sum(Nvl(Free_Qty,0))*-1 Free_Qty
                                  From Ias_Pi_Bill_Dtl
                                 Where  PO_SER Is Not Null
                                   And DOC_SEQUENCE_GRN_PO Is Not Null
                                 Group By PO_SER,I_Code,DOC_SEQUENCE_GRN_PO)
                        Group By Doc_Ser,I_Code,Doc_Sequence
                        Having Sum(Nvl(I_Qty,0))+Sum(Nvl(Free_Qty,0))>0) Mov_Data
    Where PO.Po_Ser=Mov_Data.Doc_Ser
      And PO.I_Code=Mov_Data.I_Code
      And PO.Doc_Sequence=Mov_Data.Doc_Sequence 
      And Nvl(Canceled,0)=0       
      And Nvl(Mov_Data.I_Qty,0)>=0
      And Nvl(Mov_Data.Free_Qty,0)>=0;

COMMENT ON COLUMN IAS20261.IAS_V_NY_P_ORDER_DETAIL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_NY_P_ORDER_DETAIL.I_QTY IS '222 - «·ﬂ„Ì…';

