--
-- IAS_V_PI_BILL_MST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PI_BILL_MST
(PUR_TYPE, BILL_DOC_TYPE, BILL_TYPE_NO, BILL_NO, BILL_SER, 
 V_CODE, V_NAME, BILL_DUE_DATE, VAT_AMT, DISC_AMT, 
 OTHR_AMT, BILL_NO_V_CODE, REF_NO, BILL_DATE, BILL_CURRENCY, 
 BILL_POST, W_CODE, CASH_NO, CC_CODE, PJ_NO, 
 A_DESC, ACTV_NO, HUNG, SRVC_BILL, AUDIT_REF, 
 AUDIT_REF_U_ID, AUDIT_REF_DATE, AD_U_ID, AD_DATE, UP_DATE, 
 UP_U_ID, POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
 CMP_NO, BRN_NO, GR_NO, G_SER)
BEQUEATH DEFINER
AS 
Select Pur_type,
          Bill.Bill_doc_type,
          Bill.Bill_type_no,
          Bill.Bill_no,
          Bill.Bill_ser,
          Bill.V_code,
          Bill.V_name,
          Bill.Bill_due_date,
          Bill.Vat_amt,
          Bill.Disc_amt,
          Bill.Othr_amt,
          Bill.Bill_no_v_code,
          Bill.Ref_no,          
          Bill.Bill_date,
          Bill.Bill_currency,
          Bill.Bill_post,
          Bill.W_code,
          Bill.Cash_no,
          Bill.Cc_code,
          Bill.Pj_no,
          Bill.A_desc,
          Bill.Actv_no,
          Bill.Hung,
          Bill.Srvc_bill,
          Bill.Audit_ref,
          Bill.Audit_ref_u_id,
          Bill.Audit_ref_date,
          Bill.Ad_u_id,
          Bill.Ad_date,
          Bill.UP_DATE,
          Bill.Up_U_Id,
          Bill.Post_u_id,
          Bill.Post_date,
          Bill.Unpost_u_id,
          Bill.Unpost_date,
          Bill.Cmp_no,
          Bill.Brn_no,
          0 Gr_no,
          0 G_ser
     From Ias_pi_bill_mst Bill
    Where Pur_type In (1, 3, 4)
   Union All
   Select Bill.Pur_type,
          Bill.Bill_doc_type,
          Bill.Bill_type_no,
          Bill.Bill_no,
          Bill.Bill_ser,
          Bill.V_code,
          Bill.V_name,
          Bill.Bill_due_date,
          Bill.Vat_amt,
          Bill.Disc_amt,
          Bill.Othr_amt,
          Bill.Bill_no_v_code,
          Bill.Ref_no,
          Bill.Bill_date,
          Bill.Bill_currency,
          Gr.Gr_post Bill_post,
          Bill.W_code,
          Bill.Cash_no,
          Bill.Cc_code,
          Bill.Pj_no,
          Bill.A_desc,
          Bill.Actv_no,
          Bill.Hung,
          Bill.Srvc_bill,
          Bill.Audit_ref,
          Bill.Audit_ref_u_id,
          Bill.Audit_ref_date,
          Bill.Ad_u_id,
          Bill.Ad_date,
          Bill.UP_DATE,
          Bill.Up_U_Id,
          Bill.Post_u_id,
          Bill.Post_date,
          Bill.Unpost_u_id,
          Bill.Unpost_date,
          Bill.Cmp_no,
          Bill.Brn_no,
          Gr_no,
          G_ser
     From Ias_pi_bill_mst Bill, Gr_note Gr
    Where Gr.Pur_type = 2 And Bill.Bill_ser = Gr.Doc_ser And Gr.C_flag = 1;

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.V_CODE IS '328 - —ﬁ„ «·„Ê—œ';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.REF_NO IS '143 - —ﬁ„ «·„—Ã⁄';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.CASH_NO IS '1220 - «·’‰œÊﬁ/«·»‰ﬂ';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.A_DESC IS '146 - «·»Ì«‰';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.CMP_NO IS '1583 - —ﬁ„ «·‘—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_PI_BILL_MST.BRN_NO IS '50 - —ﬁ„ «·›—⁄';



--
-- IAS_V_PI_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PI_QTY
(PO_NO, PO_DATE, I_CODE, PO_QTY, PI_QTY, 
 W_CODE, PO_TYPE, PO_SER, AD_U_ID, BRN_NO)
BEQUEATH DEFINER
AS 
SELECT b.po_no,
					             a.po_date,
					             b.i_code,            
					               NVL (SUM (NVL (b.P_Qty, 0)+(NVL (b.Free_Qty, 0) * NVL (b.P_Size, 1))),0) po_qty,
					             ((NVL (SUM (NVL (b.P_Qty, 0)+ (NVL (b.Free_Qty, 0) * NVL (b.P_Size, 1))),0)                
					               - NVL ((SELECT NVL (SUM (NVL (P_Qty, 0)+ (NVL (Free_Qty, 0) * NVL (P_Size, 1))),0)
					                                         FROM ias_pi_bill_dtl
					                                         WHERE  po_ser = b.po_ser
					                                         AND    I_Code = b.I_Code),0)))
					             pi_qty,
					             b.w_code,
					             b.po_type,
					             a.po_ser,
					             a.ad_u_id,
					             a.brn_no
					        FROM p_order a, p_order_detail b
					       WHERE     a.po_no = b.po_no
					         AND a.po_ser  = b.po_ser
					         AND NVL (a.approved, 0) = 1
					         AND NVL (b.canceled, 0) = 0                        
					    GROUP BY b.po_no,
					             b.po_ser,
					             a.po_date,
					             b.i_code,
					             b.w_code,
					             b.po_type,
					             a.po_ser,
					             a.ad_u_id,
					             a.brn_no;

COMMENT ON COLUMN IAS20261.IAS_V_PI_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PI_QTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

