--
-- IAS_V_PO_DIFF_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PO_DIFF_QTY
(PO_NO, PO_DATE, V_CODE, V_NAME, I_CODE, 
 I_NAME, I_E_NAME, UNIT, I_PRICE, DIS_AMT, 
 I_QTY, O_QTY, DIFF_Q, PO_TYPE, PO_SER, 
 AD_U_ID, BRN_NO)
BEQUEATH DEFINER
AS 
SELECT   b.po_no,
								             a.po_date,
								             a.v_code,
								             v_name,
								             b.i_code,
								             NVL( c.i_name, c.i_e_name ) i_name,
								             NVL( c.i_e_name, c.i_name ) i_e_name,
								             b.itm_unt unit,
								             b.i_price,
								             SUM( ( ( b.dis_amt_dtl + b.dis_amt_dtl2 + b.dis_amt_dtl3 ) + b.dis_amt_mst )) dis_amt,
								             NVL( SUM( NVL( b.i_qty, 0 )), 0 ) / DECODE( COUNT( d.i_code ),
								                                                         0, 1,
								                                                         COUNT( d.i_code )
								                                                       ) i_qty,
								             NVL( SUM( NVL( d.i_qty, 0 )), 0 ) o_qty,
								             ( (     NVL( SUM( NVL( b.i_qty, 0 )), 0 )
								                   / DECODE( COUNT( d.i_code ),
								                             0, 1,
								                             COUNT( d.i_code )
								                           )
								                 - NVL( SUM( NVL( d.i_qty, 0 )), 0 )
								               )
								             ) diff_q,
								             b.po_type,
								             a.po_ser,
								             a.ad_u_id,
								             a.brn_no
								    FROM     p_order a,
								             p_order_detail b,
								             ias_itm_mst c,
								             ias_pi_bill_dtl d
								    WHERE    a.po_no = b.po_no
								    AND      a.po_ser = b.po_ser
								    AND      b.i_code = c.i_code
								    AND      NVL( a.approved, 0 ) = 1
								    AND      NVL( b.canceled, 0 ) = 0
								    AND      b.i_code = d.i_code(+)
								    AND      b.po_ser = d.po_ser(+)
								    GROUP BY b.po_no,
								             b.po_ser,
								             a.po_date,
								             a.v_code,
								             v_name,
								             b.i_code,
								             c.i_name,
								             c.i_e_name,
								             b.itm_unt,
								             b.i_price,
								             b.rcrd_no,
								             b.po_type,
								             a.po_ser,
								             a.ad_u_id,
								             a.brn_no

								    ORDER BY b.po_no,
								             b.rcrd_no;

COMMENT ON COLUMN IAS20261.IAS_V_PO_DIFF_QTY.V_CODE IS '328 - —ﬁ„ «·„Ê—œ';

