--
-- IAS_V_PO_WTH_PI_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PO_WTH_PI_QTY
(PO_NO, PO_SER, PO_DATE, V_CODE, V_NAME, 
 CUR_CODE, DISC_AMT_MST, REF_NO, PO_DESC, CNTRCT_NO, 
 CNTRCT_SER, BILL_DATE_V_CODE, BILL_NO_V_CODE, CLC_VAT_PRICE_TYP, CLC_TYP_NO_TAX, 
 PMAN_CODE, I_CODE, ITM_UNT, P_SIZE, RCRD_NO, 
 DOC_SEQUENCE, MANUAL_REF_NO, W_CODE, PO_QTY, BILL_QTY, 
 DIFF_QTY, FREE_QTY, FREE_BILL_QTY, I_PRICE, I_PRICE_VAT, 
 ITEM_DESC, CC_CODE, PJ_NO, ACTV_NO, REC_ATTCH, 
 DIS_PER, DIS_AMT_DTL, DIS_PER2, DIS_AMT_DTL2, DIS_PER3, 
 DIS_AMT_DTL3, BARCODE, EXPIRE_DATE, BATCH_NO, WT_UNT, 
 WT_QTY, ARGMNT_NO, I_LENGTH, I_WIDTH, I_HEIGHT, 
 I_NUMBER, FIELD_DTL1, FIELD_DTL2, FIELD_DTL3, FIELD_DTL4, 
 FIELD_DTL5, FIELD_DTL6, FIELD_DTL7, FIELD_DTL8, FIELD_DTL9, 
 FIELD_DTL10, BRN_NO, APPROVED, PO_TYPE, PO_EXPIRE_DATE, 
 RQRD_FRGHT_DATA, NEED_CHECK_QTY, PO_LOCKED, PO_CHECKED, PUR_TYPE, 
 INACTIVE, AD_DATE, AD_U_ID, CANCELED)
BEQUEATH DEFINER
AS 
SELECT Po_NO,
           po_ser,
           PO_Date,
           v_code,
           v_name,
           cur_code,
           Disc_amt_mst,
           Ref_No,
           Po_Desc,
           Cntrct_No,
           Cntrct_Ser,
           Bill_Date_V_Code,
           Bill_No_V_Code,
           Clc_Vat_Price_Typ,
           Clc_Typ_No_Tax,
           PMAN_CODE,
           I_CODE,
           itm_unt,
           P_Size,
           Rcrd_No,
           DOC_SEQUENCE,
           Manual_Ref_No,
           W_CODE,
           Po_Qty,
           Bill_Qty,
           (Po_Qty - Bill_Qty)     Diff_qty,
           NVL (free_qty, 0)       free_qty,
           FREE_Bill_Qty,
           i_price,
           i_price_vat,
           item_desc,
           cc_code,
           pj_no,
           actv_No,
           Rec_Attch,
           Dis_Per,
           Dis_Amt_Dtl,
           Dis_Per2,
           Dis_Amt_Dtl2,
           Dis_Per3,
           Dis_Amt_Dtl3,
           Barcode,
           Expire_Date,
           Batch_No,
           wt_unt,
           wt_qty,
           Argmnt_No,
           I_Length,
           I_Width,
           I_Height,
           I_Number,
           FIELD_DTL1,
           FIELD_DTL2,
           FIELD_DTL3,
           FIELD_DTL4,
           FIELD_DTL5,
           FIELD_DTL6,
           FIELD_DTL7,
           FIELD_DTL8,
           FIELD_DTL9,
           FIELD_DTL10,
           brn_no,
           approved,
           po_type,
           Po_Expire_Date,
           Rqrd_Frght_Data,
           Need_Check_Qty,
           Po_Locked,
           Po_Checked,
           Pur_Type,
           Inactive,
           Ad_Date,
           AD_U_ID,           
           Canceled
    FROM   (SELECT   b.Po_NO,
                     b.Po_SER,
                     PO_Date,
                     v_code,
                     v_name,
                     cur_code,
                     Disc_amt_mst,
                     Ref_No,
                     Po_Desc,
                     Cntrct_No,
                     Cntrct_Ser,
                     Bill_Date_V_Code,
                     Bill_No_V_Code,
                     Clc_Vat_Price_Typ,
                     Clc_Typ_No_Tax,
                     PMAN_CODE,
                     b.I_Code,
                     b.itm_unt,
                     P_Size,
                     b.Rcrd_No,
                     b.Manual_Ref_No,
                     b.w_code,
                     DOC_SEQUENCE,
                     NVL (b.p_Qty, 0) / NVL (b.P_Size, 1)
                         Po_Qty,
                       (SELECT NVL (SUM (P_Qty), 0)
                        FROM   Ias_Pi_bill_Dtl
                        WHERE      po_ser = b.po_ser
                               AND I_Code = b.I_Code
                               AND Doc_Sequence_Grn_Po = b.Doc_Sequence
                               AND w_code = NVL (b.w_code, w_code))
                     / NVL (b.P_Size, 1)
                         Bill_Qty,
                     NVL (free_qty, 0) * NVL (b.P_Size, 1)
                         free_qty,
                       (SELECT NVL (SUM (free_qty), 0)
                        FROM   Ias_Pi_bill_Dtl
                        WHERE      po_ser = b.po_ser
                               AND I_Code = b.I_Code
                               AND Doc_Sequence_Grn_Po = b.Doc_Sequence
                               AND w_code = NVL (b.w_code, w_code))
                     * NVL (b.P_Size, 1)
                         FREE_Bill_Qty,
                     i_price,
                     i_price_vat,
                     item_desc,
                     b.cc_code,
                     b.pj_no,
                     b.actv_No,
                     Rec_Attch,
                     Dis_Per,
                     Dis_Amt_Dtl,
                     Dis_Per2,
                     Dis_Amt_Dtl2,
                     Dis_Per3,
                     Dis_Amt_Dtl3,
                     Barcode,
                     Expire_Date,
                     Batch_No,
                     wt_unt,
                     wt_qty,
                     Argmnt_No,
                     I_Length,
                     I_Width,
                     I_Height,
                     I_Number,
                     FIELD_DTL1,
                     FIELD_DTL2,
                     FIELD_DTL3,
                     FIELD_DTL4,
                     FIELD_DTL5,
                     FIELD_DTL6,
                     FIELD_DTL7,
                     FIELD_DTL8,
                     FIELD_DTL9,
                     FIELD_DTL10,
                     a.brn_no,
                     a.approved,
                     a.po_type,
                     a.Po_Expire_Date,
                     a.Rqrd_Frght_Data,
                     a.Need_Check_Qty,
                     a.Po_Locked,
                     a.Po_Checked,
                     a.Pur_Type,
                     a.Inactive,
                     a.Ad_Date,
                     a.AD_U_ID,
                     b.Canceled
            FROM     p_order a, p_order_detail b
            WHERE    a.po_no = b.po_no AND a.po_ser = b.po_ser
            ORDER BY Po_NO DESC, I_CODE, Rcrd_No);

COMMENT ON COLUMN IAS20261.IAS_V_PO_WTH_PI_QTY.V_CODE IS '328 - —ﬁ„ «·„Ê—œ';

COMMENT ON COLUMN IAS20261.IAS_V_PO_WTH_PI_QTY.CUR_CODE IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.IAS_V_PO_WTH_PI_QTY.REF_NO IS '143 - —ﬁ„ «·„—Ã⁄';

COMMENT ON COLUMN IAS20261.IAS_V_PO_WTH_PI_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

