--
-- IAS_V_PR_WTH_PI_QTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PR_WTH_PI_QTY
(PR_NO, PR_DATE, PR_TYPE, PR_SER, I_CODE, 
 ITM_UNT, RCRD_NO, MANUAL_REF_NO, W_CODE, PR_QTY, 
 PI_QTY, DIFF_QTY, REM_QTY, CC_CODE, PJ_NO, 
 ACTV_NO, WT_UNT, WT_QTY, ARGMNT_NO, I_LENGTH, 
 I_WIDTH, I_HEIGHT, I_NUMBER, P_SIZE, P_QTY, 
 ITEM_DESC, REC_ATTCH, EXPIRE_DATE, BATCH_NO, DOC_SEQUENCE, 
 DLVRY_DATE, I_PRICE, APPROVED, PR_DESC, V_NAME, 
 REF_NO, SIDE_REQ, BRN_NO, PUR_NO, PUR_SER)
BEQUEATH DEFINER
AS 
SELECT PR_NO,
             PR_Date,
             Pr_Type,
             PR_SER,
             I_CODE,
             itm_unt,
             RCRD_NO,
             Manual_Ref_No,
             W_CODE,
             PR_QTY,
             PI_QTY,
             pr_Qty - PI_Qty     diff_qty,
             Rem_Qty,
             cc_code,
             pj_no,
             actv_no,
             Wt_Unt,
             Wt_Qty,
             Argmnt_No,
             I_Length,
             I_Width,
             I_Height,
             I_Number,
             p_size,
             p_qty,
             item_desc,
             Rec_Attch,
             Expire_date,
             Batch_No,
             DOC_SEQUENCE,
             DLVRY_DATE,
             I_price,
             Approved,
             PR_DESC,
             v_name,
             Ref_No,
             SIDE_REQ,
             Brn_No,
             PUR_NO,
             PUR_SER
        FROM (  SELECT b.PR_NO,
                       a.PR_Date,
                       a.Pr_Type,
                       b.PR_SER,
                       b.I_Code,
                       b.itm_unt,
                       b.Rcrd_No,
                       b.Manual_Ref_No,
                       b.w_code,
                       DOC_SEQUENCE,
                       (NVL (b.P_Qty, 0) / NVL (b.p_size, 1))
                           Pr_Qty,
                       (SELECT NVL (SUM (P_Qty), 0) / NVL (b.p_size, 1)
                          FROM Ias_Pi_Bill_Dtl
                         WHERE     Doc_Ser_Ref = b.Pr_Ser
                               AND I_Code = b.I_Code
                               AND DOC_SEQUENCE_REF = b.doc_sequence
                               AND w_code = NVL (b.w_code, w_code))
                           Pi_Qty,
                       (  SUM ((NVL (b.P_Qty, 0) / NVL (b.p_size, 1)))
                        - (SELECT NVL (SUM (P_Qty), 0) / NVL (b.p_size, 1)
                             FROM Ias_Pi_Bill_Dtl
                            WHERE     Doc_Ser_Ref = b.Pr_Ser
                                  AND I_Code = b.I_Code
                                  AND DOC_SEQUENCE_REF = b.doc_sequence
                                  AND w_code = NVL (b.w_code, w_code)))
                           Rem_Qty,
                       b.cc_code,
                       b.pj_no,
                       b.actv_no,
                       Wt_Unt,
                       Wt_Qty,
                       Argmnt_No,
                       I_Length,
                       I_Width,
                       I_Height,
                       I_Number,
                       p_size,
                       p_qty,
                       item_desc,
                       Rec_Attch,
                       b.Expire_date,
                       b.Batch_No,
                       b.DLVRY_DATE,
                       b.I_price,
                       a.Approved,
                       a.PR_DESC,
                       a.v_name,
                       a.Ref_No,
                       a.SIDE_REQ,
                       a.Brn_No,
                       B.PUR_NO,
                       B.PUR_SER
                  FROM P_Request a, P_Request_Detail b
                 WHERE a.pr_no = b.pr_no AND a.pr_ser = b.pr_ser
                 			 AND NVL(A.APPROVED,0) = 1 
                HAVING (  SUM ((NVL (b.P_Qty, 0) / NVL (b.p_size, 1)))
                        - (SELECT NVL (SUM (P_Qty), 0) / NVL (b.p_size, 1)
                             FROM Ias_Pi_Bill_Dtl
                            WHERE     Doc_Ser_Ref = b.Pr_Ser
                                  AND I_Code = b.I_Code
                                  AND DOC_SEQUENCE_REF = b.doc_sequence
                                  AND w_code = NVL (b.w_code, w_code))) > 0
              GROUP BY b.PR_NO,
                       a.PR_Date,
                       a.Pr_Type,
                       b.PR_SER,
                       b.I_Code,
                       b.itm_unt,
                       b.Rcrd_No,
                       b.Manual_Ref_No,
                       b.w_code,
                       DOC_SEQUENCE,
                       (NVL (b.P_Qty, 0) / NVL (b.p_size, 1)),
                       b.cc_code,
                       b.pj_no,
                       b.actv_no,
                       Wt_Unt,
                       Wt_Qty,
                       Argmnt_No,
                       I_Length,
                       I_Width,
                       I_Height,
                       I_Number,
                       p_size,
                       p_qty,
                       item_desc,
                       Rec_Attch,
                       b.Expire_date,
                       b.Batch_No,
                       b.DLVRY_DATE,
                       b.I_price,
                       a.Approved,
                       a.PR_DESC,
                       a.v_name,
                       a.Ref_No,
                       a.SIDE_REQ,
                       a.Brn_No,
                       B.PUR_NO,
                       B.PUR_SER
              ORDER BY PR_NO, I_CODE, Rcrd_No)
    ORDER BY PR_NO DESC, Rcrd_No, I_CODE;

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.DOC_SEQUENCE IS '2767 -  ”·”· «·Õ—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.IAS_V_PR_WTH_PI_QTY.APPROVED IS '1377 - Õ«·… «·≈⁄ „«œ';

