--
-- IAS_V_SMAN_PRM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_SMAN_PRM
(SMAN_TYP, REP_CODE, REP_L_NM, REP_F_NM, W_CODE, 
 CASH_NO, BANK_NO, GRP_CODE, SMAN_PASS, USE_INV_DTS)
BEQUEATH DEFINER
AS 
(SELECT 1 SMAN_TYP,
		           REPRS_CODE REP_CODE,
		           REPRS_A_NAME REP_L_NM,
		           REPRS_E_NAME REP_F_NM,
		           W_CODE,
		           CASH_NO,
		           BANK_NO,
		           GRP_CODE,
		           SMAN_PASS,
		           NVL (USE_INV_DTS, 0)
		      FROM SALES_MAN
		    UNION ALL
		    SELECT 3 SMAN_TYP,
		           PRM_CODE REP_CODE,
		           PRM_L_NM REP_L_NM,
		           PRM_F_NM REP_F_NM,
		           W_CODE,
		           CASH_NO,
		           BANK_NO,
		           GRP_CODE,
		           SMAN_PASS PRM_PASS,
		           NVL (USE_INV_DTS, 0)
		      FROM IAS_PROMOTERS);

COMMENT ON COLUMN IAS20261.IAS_V_SMAN_PRM.REP_CODE IS '395 - —ﬁ„ «·„‰œÊ»';

COMMENT ON COLUMN IAS20261.IAS_V_SMAN_PRM.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_SMAN_PRM.CASH_NO IS '1220 - «·’‰œÊﬁ/«·»‰ﬂ';



--
-- IAS_V_USR_CST_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_CST_PRV
(U_ID, USR_NAME, C_CODE, C_NM, A_CY, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.C_CODE,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.C_A_Name, C.C_E_Name),NVL (C.C_E_Name, C.C_A_Name)) C_Nm,
          A.A_Cy,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     FROM Ias_Priv_Customer A, User_R B, Customer C
    WHERE     A.U_Id = B.U_Id
          AND  A.C_Code = C.C_Code
          --AND (Add_Flag = 1 OR View_Flag = 1)
   UNION
   SELECT B.U_Id,
              Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
              C.C_Code,
              Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.C_A_Name, C.C_E_Name),NVL (C.C_E_Name, C.C_A_Name)) C_Nm,
              A.A_Cy,
              0 Add_Flag,
              0 View_Flag,
              NULL Ad_U_Id,
              NULL Ad_Date,
              NULL Up_U_Id,
              NULL Up_Date,
              0 Rec_Src
     FROM Customer_Curr A, User_R B, Customer C
    WHERE A.C_Code = C.C_Code
          AND NOT EXISTS
                     (SELECT 1
                        FROM Ias_Priv_Customer
                       WHERE     C_Code = A.C_Code
                             AND A_Cy = A.A_Cy
                             AND U_Id = B.U_Id
                             AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_CST_PRV.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_CST_PRV.A_CY IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.IAS_V_USR_CST_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_CST_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_CST_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_PROMOTERS_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_PROMOTERS_PRV
(U_ID, USR_NAME, PRM_CODE, PRM_NM, ADD_FLAG, 
 VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, 
 REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_ID,
          DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'),
                  1, NVL (B.U_A_NAME, B.U_E_NAME),
                  NVL (B.U_E_NAME, B.U_A_NAME)
                 ) USR_NM,
          C.PRM_CODE,
          DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'),
                  1, NVL (C.PRM_L_NM, C.PRM_F_NM),
                  NVL (C.PRM_F_NM, C.PRM_L_NM)
                 ) PRM_NM,
          A.ADD_FLAG, A.VIEW_FLAG, A.AD_U_ID, A.AD_DATE, A.UP_U_ID, A.UP_DATE,
          1 REC_SRC
     FROM IAS_PROMOTERS_PRV A, USER_R B, IAS_PROMOTERS C
    WHERE A.U_ID = B.U_ID
      AND A.PRM_CODE = C.PRM_CODE
      --AND (ADD_FLAG = 1 OR VIEW_FLAG = 1)
   UNION
   SELECT B.U_ID,
          DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'),
                  1, NVL (B.U_A_NAME, B.U_E_NAME),
                  NVL (B.U_E_NAME, B.U_A_NAME)
                 ) USR_NM,
          C.PRM_CODE,
          DECODE (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_NO'),
                  1, NVL (C.PRM_L_NM, C.PRM_F_NM),
                  NVL (C.PRM_F_NM, C.PRM_L_NM)
                 ) PRM_NM,
          0 ADD_FLAG, 0 VIEW_FLAG, NULL AD_U_ID, NULL AD_DATE, NULL UP_U_ID,
          NULL UP_DATE, 0 REC_SRC
     FROM USER_R B, IAS_PROMOTERS C
    WHERE NOT EXISTS (
             SELECT 1
               FROM IAS_PROMOTERS_PRV
              WHERE PRM_CODE = C.PRM_CODE AND U_ID = B.U_ID
                    AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROMOTERS_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROMOTERS_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_PROMOTERS_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_USR_VNDR_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_USR_VNDR_PRV
(U_ID, USR_NAME, V_CODE, V_NM, A_CY, 
 ADD_FLAG, VIEW_FLAG, AD_U_ID, AD_DATE, UP_U_ID, 
 UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
SELECT A.U_Id,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
          A.V_CODE,
          Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.V_A_Name, C.V_E_Name),NVL (C.V_E_Name, C.V_A_Name)) C_Nm,
          A.A_Cy,
          A.Add_Flag,
          A.View_Flag,
          A.Ad_U_Id,
          A.Ad_Date,
          A.Up_U_Id,
          A.Up_Date,
          1 Rec_Src
     FROM Ias_Priv_Vendor A, User_R B, V_Details C
    WHERE     A.U_Id = B.U_Id
          AND  A.V_Code = C.V_Code
          --AND (Add_Flag = 1 OR View_Flag = 1)
   UNION
   SELECT B.U_Id,
              Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (B.U_A_Name, B.U_E_Name),NVL (B.U_E_Name, B.U_A_Name)) Usr_Nm,
              C.V_Code,
              Decode ( Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_NO') ,1,NVL (C.V_A_Name, C.V_E_Name),NVL (C.V_E_Name, C.V_A_Name)) C_Nm,
              A.A_Cy,
              0 Add_Flag,
              0 View_Flag,
              NULL Ad_U_Id,
              NULL Ad_Date,
              NULL Up_U_Id,
              NULL Up_Date,
              0 Rec_Src
     FROM Vendor_Curr A, User_R B, V_Details C
    WHERE A.V_Code = C.V_Code
          AND NOT EXISTS
                     (SELECT 1
                        FROM Ias_Priv_Vendor
                       WHERE     V_Code = A.V_Code
                             AND A_Cy = A.A_Cy
                             AND U_Id = B.U_Id
                             AND ROWNUM <= 1);

COMMENT ON COLUMN IAS20261.IAS_V_USR_VNDR_PRV.V_CODE IS '328 - —ﬁ„ «·„Ê—œ';

COMMENT ON COLUMN IAS20261.IAS_V_USR_VNDR_PRV.A_CY IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.IAS_V_USR_VNDR_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_VNDR_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_USR_VNDR_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- IAS_V_VND_TRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_VND_TRNS
(V_CODE, V_A_NAME, V_E_NAME, A_CY, DOC_NO, 
 DOC_TYPE, DOC_JV_TYPE, DOC_SER, DOC_DATE, DOC_DUE_DATE, 
 DR_AMT, CR_AMT, DR_AMTF, CR_AMTF, DOC_DESC, 
 CASH_NO, CC_CODE, PJ_NO, W_CODE, DOC_POST, 
 REF_NO, CHEQUE_VALUED, EXTERNAL_POST, RCRD_NO, AD_U_ID, 
 UP_U_ID, AD_DATE, UP_DATE, CMP_NO, BRN_NO, 
