--
-- INV_KPI_ITM_MOVMNT_DTL_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_KPI_ITM_MOVMNT_DTL_VW
(ITM_CODE, ITM_NM, ITM_F_NM, ITM_DSC, ITM_F_DSC, 
 ITM_UNT, MAX_ITM_UNT, MAX_P_SIZE, GRP_CLASS_CODE, GRP_CLASS_NM, 
 ACTIVITY_NO, ACTIVITY_NM, GRP_CODE, GRP_CODE_NM, MNG_CODE, 
 MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, ASSTNT_GRP_CODE, ASSTNT_GRP_NM, 
 DTL_GRP_NO, DTL_GRP_NM, ALTRNTV_GRP_CODE, ALTRNTV_GRP_NM, ITM_TYP_NO, 
 ITM_TYP_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITEM_SIZE, SIZE_ITM, AREA_ITM, WEIGHT_ITM, 
 GTIN_CODE, HSN_CODE, MANF_CODE, ALTER_CODE, MRP_ITM_CLSS, 
 DOC_TYPE, DOC_TYPE_NM, BILL_DOC_TYPE, BILL_DOC_TYPE_NM, DOC_SUB_TYPE, 
 DOC_SUB_TYPE_NM, W_CODE, W_NM, WHG_CODE, WHG_NM, 
 DOC_DATE, PRD_NO, PRD_NM, IN_OUT, IN_OUT_NM, 
 I_QTY, NET_SAL_QTY, IN_QTY, OUT_QTY, IN_FREE_QTY, 
 OUT_FREE_QTY, NET_IN_QTY, NET_OUT_QTY, AVL_QTY, STK_COST, 
 VAT_AMT, DIS_AMT, OTHR_AMT, VAT_AMT_OTHR, DIS_AMT_DTL, 
 DIS_AMT_DTL_VAT, DIS_AMT_DTL2, DIS_AMT_DTL2_VAT, DIS_AMT_DTL3, DIS_AMT_DTL3_VAT, 
 I_CWTAVG, I_LENGTH, I_WIDTH, I_HEIGHT, AC_DTL_TYP, 
 C_CODE, C_NM, V_CODE, V_NM, CC_CODE, 
 CC_NM, PJ_NO, PJ_NM, ACTV_NO, ACTV_NM, 
 EXPIRE_DATE, BATCH_NO, CMP_NO, CMP_NM, BRN_NO, 
 BRN_NM, BRN_YEAR, BRN_USR, CNTRY_NO, CNTRY_NM, 
 PROV_NO, PROV_NM, CITY_NO, CITY_NM, R_CODE, 
 R_CODE_NM, INCOME_DATE, LENGTH_ITM, WIDTH_ITM, HEIGHT_ITM, 
 SEASON_ITM, ORE_ITM, MARK_ITM, COMPANY_ITM, COUNTRY_ITM)
BEQUEATH DEFINER
AS 
With Lng As (Select (select  Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1) from dual) Lng_No
                               ,Nvl((SELECT FLD_VAL FROM S_FLD_PRV_FXD_USR WHERE UPPER(FLD_NM)=UPPER('HIDE_COST') AND U_ID =nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1) AND ROWNUM<=1),0) HIDE_COST                 
                               ,(select Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1)  from dual) P_USR_NO
                               ,(SELECT WTAVG_TYPE FROM IAS_PARA_INV WHERE ROWNUM<=1) WTAVG_TYPE   From Dual                
                )                                
   Select M.I_Code Itm_Code
         ,Decode (Lng.Lng_No, 1, M.I_Name, Nvl (M.I_E_Name, M.I_Name)) Itm_Nm
         ,M.I_E_Name Itm_F_Nm  
         ,Decode (Lng.Lng_No, 1, M.I_Desc, Nvl (M.I_F_Desc, M.I_Desc)) Itm_Dsc
         ,M.I_F_Desc  Itm_F_Dsc
         ,(Select Itm_Unt 
                  From Ias_Itm_Dtl
                   Where Ias_Itm_Dtl.I_Code           = m.I_Code
                     And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 
                     And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 
                     And RowNum                      <= 1 )Itm_Unt
         ,(SELECT ITM_UNT  
             FROM IAS_ITM_DTL 
            WHERE I_CODE= M.I_CODE 
              AND LVL_UNIT = ( SELECT MAX(LVL_UNIT) 
                                 FROM IAS_ITM_DTL
                                WHERE I_CODE= M.I_CODE 
                                 ) AND ROWNUM <=1) MAX_ITM_UNT 
           ,(SELECT P_SIZE 
              FROM IAS_ITM_DTL
             WHERE I_CODE  = M.I_CODE
               AND ITM_UNT = (SELECT ITM_UNT  
                                FROM IAS_ITM_DTL 
                               WHERE I_CODE= M.I_CODE 
                                 AND LVL_UNIT = ( SELECT MAX(LVL_UNIT) 
                                                    FROM IAS_ITM_DTL
                                                   WHERE I_CODE= M.I_CODE
                                                    ) AND ROWNUM <=1) 
               AND ROWNUM <= 1 )  MAX_P_SIZE            
         ,M.Grp_Class_Code Grp_Class_Code
         ,   M.Grp_Class_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Grp_L_Name, Nvl (A.Grp_F_Name, A.Grp_L_Name))
                From Ias_Grp_Itm_Lvl A
               Where A.Grp_Code = M.Grp_Class_Code And Rownum <= 1)
             Grp_Class_Nm
         ,M.Activity_No Activity_No
         ,   M.Activity_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Activity_A_Name, Nvl (A.Activity_E_Name, A.Activity_A_Name))
                From Ias_Items_Activity A
               Where A.Activity_No = M.Activity_No And Rownum <= 1)
             Activity_Nm
         ,M.G_Code Grp_Code
         ,   M.G_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.G_A_NAME, Grp.G_E_NAME), Nvl (Grp.G_E_NAME, Grp.G_A_NAME)) Grp_Nm
                From GROUP_DETAILS Grp
               Where G_Code = M.G_Code And Rownum <= 1)
             Grp_Code_Nm
         ,M.Mng_Code
         ,   M.Mng_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.MNG_A_NAME, Grp.MNG_E_NAME), Nvl (Grp.MNG_E_NAME, Grp.MNG_A_NAME)) Grp_Nm
                From IAS_MAINSUB_GRP_DTL Grp
               Where  Mng_Code = M.Mng_Code
                  AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                   And Rownum <= 1)
             Mng_Code_Nm
         ,M.Subg_Code
         ,   M.Subg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.SUBG_A_NAME, Grp.SUBG_E_NAME), Nvl (Grp.SUBG_E_NAME, Grp.SUBG_A_NAME)) Grp_Nm
                From IAS_SUB_GRP_DTL Grp
               Where Subg_Code = M.Subg_Code
               AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
               AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code) 
               And Rownum <= 1)
             Subg_Code_Nm
         ,M.Assistant_No Asstnt_Grp_Code
         ,   M.Assistant_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Assistant_A_Name, Grp.Assistant_E_Name), Nvl (Grp.Assistant_E_Name, Grp.Assistant_A_Name)) Grp_Nm
                From Ias_Assistant_Group Grp
               Where Assistant_No = M.Assistant_No 
                 AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                 AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code)
                 AND NVL(M.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL(M.Subg_Code,'0'),Subg_Code)
                 And Rownum <= 1)
             Asstnt_Grp_Nm
         ,M.Detail_No Dtl_Grp_No
         ,   M.Detail_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Detail_A_Name, Grp.Detail_E_Name), Nvl (Grp.Detail_E_Name, Grp.Detail_A_Name)) Grp_Nm
                From Ias_Detail_Group Grp
               Where Detail_No=M.Detail_No
               AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                 AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code)
                 AND NVL(M.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL(M.Subg_Code,'0'),Subg_Code)
                 AND NVL(M.Assistant_No,'0')= DECODE(Nvl (Assistant_No, '0'),'0',NVL(M.Assistant_No,'0'),Assistant_No)
                 And Rownum <= 1)
             Dtl_Grp_Nm
         ,M.Group_No Altrntv_Grp_Code
         ,   M.Group_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Group_A_Name, Nvl (A.Group_E_Name, A.Group_A_Name))
                From Ias_Alternative_Group A
               Where A.Group_No = M.Group_No And Rownum <= 1)
             Altrntv_Grp_Nm
         ,M.Item_Type Itm_Typ_No
         ,   M.Item_Type
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.It_A_Name, Nvl (A.It_E_Name, A.It_A_Name))
                From Item_Types A
               Where A.Type_Of_Item = M.Item_Type And Rownum <= 1)
             Itm_Typ_Nm
         ,M.Kit_Itm
         ,M.Use_Exp_Date
         ,M.Use_Batch_No
         ,M.Use_Serialno
         ,M.Use_Attch
         ,M.Item_Size
         ,M.Size_Itm
         ,M.Area_Itm
         ,M.Weight_Itm
         ,M.Gtin_Code
         ,M.Hsn_Code
         ,M.Manf_Code
         ,M.Alter_Code
         ,(SELECT FLG_VALUE || '-' || FLG_DESC
               FROM S_FLAGS
              WHERE FLG_CODE      = 'MRP_ITM_CLSS'
                    AND LANG_NO   = LNG.LNG_NO
                    AND FLG_VALUE = M.MRP_ITM_CLSS
                    AND ROWNUM <= 1) MRP_ITM_CLSS
         ,D.Doc_Type Doc_Type
         , (Select Flg_Desc
              From S_Flags
             Where Lang_No = Lng.Lng_No And Flg_Code = 'DOC_TYPE_INV' And Flg_Value = D.Doc_Type And Rownum <= 1)
             Doc_Type_Nm
         ,D.Bill_Doc_Type
         ,Decode (D.Doc_Type
                 ,1, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,2, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,3, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,4, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,Null)
             Bill_Doc_Type_Nm
         ,Decode (D.Doc_Type,  5, D.Bill_Doc_Type,  6, D.Bill_Doc_Type,  7, D.Bill_Doc_Type,  8, D.Bill_Doc_Type,  11, D.Bill_Doc_Type,  12, D.Bill_Doc_Type,  13, D.Bill_Doc_Type,  14, D.Bill_Doc_Type,  15, D.Bill_Doc_Type,  16, D.Bill_Doc_Type,  17, D.Bill_Doc_Type,  18, D.Bill_Doc_Type,  Null) Doc_Sub_Type
         ,Decode (D.Doc_Type
                 ,5,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Incom_Name, Nvl (Incom_E_Name, Incom_Name))
                           From Incom_Types
                          Where Incom_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,6,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Out_Name, Nvl (Out_E_Name, Out_Name))
                           From Out_Types
                          Where Out_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,7,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Tr_Name, Nvl (Tr_E_Name, Tr_Name))
                           From Transfer_Types
                          Where Tr_Type = D.Bill_Doc_Type And Nvl (Tr_Rec, 0) In (1, 3) And Rownum <= 1)
                 ,8,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Tr_Name, Nvl (Tr_E_Name, Tr_Name))
                           From Transfer_Types
                          Where Tr_Type = D.Bill_Doc_Type And Nvl (Tr_Rec, 0) In (2, 3) And Rownum <= 1)
                 ,11,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (1, 3) And Rownum <= 1)
                 ,12,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (1, 3) And Rownum <= 1)
                 ,13,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (2, 3) And Rownum <= 1)
                 ,14,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (2, 3) And Rownum <= 1)
                 ,15,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,16,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,17,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,18,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,Null)
             Doc_Sub_Type_Nm
         ,D.W_Code W_Code
         ,   D.W_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, W_Name, Nvl (W_E_Name, W_Name))
                From Warehouse_Details
               Where W_Code = D.W_Code And Rownum <= 1)
             W_Nm
         ,D.Whg_Code Whg_Code
         ,   D.Whg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Whg_A_Name, Nvl (Whg_E_Name, Whg_A_Name)) Whg_Nm
                From Warehouse_Group
               Where Whg_Code = D.Whg_Code And Rownum <= 1)
             Whg_Nm
         ,D.I_Date Doc_Date
         ,To_Number (To_Char (D.I_Date, 'MM')) Prd_No
         ,   To_Number (To_Char (D.I_Date, 'MM'))
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prd_L_Nm, Prd_F_Nm), Nvl (Prd_F_Nm, Prd_L_Nm))
                From S_Prd_Dtl
               Where Prd_No = To_Number (To_Char (I_Date, 'MM')) And Rownum <= 1)
             Prd_Nm
         ,In_Out
         ,Case
             When D.DOC_TYPE = 0 Then
                (Select '1-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 1264 And Rownum <= 1)
             When In_Out = 1 Then
                (Select '2-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 3066 And Rownum <= 1)
             Else
                (Select '3-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 18764 And Rownum <= 1)
          End
             In_Out_Nm
         ,D.I_Qty
         ,D.NET_SAL_QTY
         ,D.In_Qty
         ,D.Out_Qty
         ,D.In_Free_Qty
         ,D.Out_Free_Qty
         ,D.Net_In_Qty
         ,D.Net_Out_Qty
         ,D.Avl_Qty
         ,Decode(lng.HIDE_COST,1,D.Stk_Cost,0) Stk_Cost
         ,D.Vat_Amt
         ,D.Dis_Amt
         ,D.Othr_Amt
         ,D.Vat_Amt_Othr
         ,D.Dis_Amt_Dtl
         ,D.Dis_Amt_Dtl_Vat
         ,D.Dis_Amt_Dtl2
         ,D.Dis_Amt_Dtl2_Vat
         ,D.Dis_Amt_Dtl3
         ,D.Dis_Amt_Dtl3_Vat
         ,DECODE (LNG.HIDE_COST, 1, ROUND(Ias_Itm_Pkg.Get_Grand_Wtavg( P_Wtavg_Type =>Lng.Wtavg_Type,
																                                       P_Icode      =>M.I_Code ,
																                                       P_Wcode      =>D.W_Code),4), 0)
          I_Cwtavg
         ,D.I_Length
         ,D.I_Width
         ,D.I_Height
         ,D.Ac_Dtl_Typ
         ,D.C_Code
         ,   D.C_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (C_A_Name, C_E_Name), Nvl (C_E_Name, C_A_Name))
                From Customer
               Where C_Code = D.C_Code And Rownum <= 1)
             C_Nm
         ,D.V_Code
         ,   D.V_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (V_A_Name, V_E_Name), Nvl (V_E_Name, V_A_Name))
                From V_Details
               Where V_Code = D.V_Code And Rownum <= 1)
             V_Nm
         ,D.Cc_Code
         ,   D.Cc_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cc_A_Name, Cc_E_Name), Nvl (Cc_E_Name, Cc_A_Name))
                From Cost_Centers
               Where Cc_Code = D.Cc_Code And Rownum <= 1)
             Cc_Nm
         ,D.Pj_No
         ,   D.Pj_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Pj_A_Name, Pj_E_Name), Nvl (Pj_A_Name, Pj_E_Name))
                From Ias_Projects
               Where Pj_No = D.Pj_No And Rownum <= 1)
             Pj_Nm
         ,D.Actv_No
         ,   D.Actv_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Actv_A_Name, Actv_E_Name), Nvl (Actv_E_Name, Actv_A_Name))
                From Ias_Actvty
               Where Actv_No = D.Actv_No And Rownum <= 1)
             Actv_Nm
         ,Decode (D.Expire_Date, '01/01/1900', Null, D.Expire_Date) Expire_Date
         ,Decode (D.Batch_No, '0', Null, D.Batch_No) Batch_No
         ,D.Cmp_No Cmp_No
         ,   D.Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cmp_Lname, Cmp_Fname), Nvl (Cmp_Fname, Cmp_Lname))
                From S_Cmpny
               Where Cmp_No = D.Cmp_No And Rownum <= 1)
             Cmp_Nm
         ,D.Brn_No Brn_No
         ,   D.Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = D.Brn_No And Rownum <= 1)
             Brn_Nm
         ,D.Brn_Year
         ,D.Brn_Usr
         ,W.Cntry_No
         ,   W.Cntry_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cntry_A_Name, Cntry_E_Name), Nvl (Cntry_E_Name, Cntry_A_Name))
                From Cntry
               Where Cntry_No = W.Cntry_No And Rownum <= 1)
             Cntry_Nm
         ,W.Prov_No
         ,   W.Prov_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prov_A_Name, Prov_E_Name), Nvl (Prov_E_Name, Prov_A_Name))
                From Ias_Provinces
               Where Prov_No = W.Prov_No And Rownum <= 1)
             Prov_Nm
         ,W.City_No
         ,   W.City_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (City_A_Name, City_E_Name), Nvl (City_E_Name, City_A_Name))
                From Cities
               Where City_No = W.City_No And Rownum <= 1)
             City_Nm
         ,W.R_Code
         ,   W.R_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (R_A_Name, R_A_Name), Nvl (R_E_Name, R_A_Name))
                From Regions
               Where R_Code = W.R_Code And Rownum <= 1)
             R_Code_Nm
         ,M.Income_Date
         ,M.Length_Itm
         ,M.Width_Itm
         ,M.Height_Itm
         ,M.Season_Itm
         ,M.Ore_Itm
         ,M.Mark_Itm
         ,M.Company_Itm
         ,M.Country_Itm
     From (  Select D.I_Code                  
                   ,D.W_Code
                   ,D.Whg_Code                   
                   ,In_Out                                                                                               
                   ,D.Cc_Code
                   ,D.Pj_No
                   ,D.Actv_No
                   ,D.Expire_Date
                   ,D.Cmp_No
                   ,D.Brn_No
                   ,D.Brn_Year
                   ,D.Brn_Usr
                   ,D.Batch_No                    
                   ,D.Doc_Type 
                   ,D.Bill_Doc_Type                                                       
                   ,D.I_Date                  
                   ,NULL I_Length
                   ,NULL I_Width
                   ,NULL I_Height
                   ,D.Ac_Dtl_Typ
                   ,D.C_Code                   
                   ,D.V_Code
                   ,/* CASE WHEN D.Doc_Type = 0 THEN 
                               ( Select Open_Stock ( I_Code,
                                                     w_code,
                                                    To_Date(Ias_Gen_Pkg.Get_Frst_Day,'DD/MM/YYYY'),
                                                    NULL
                                                   ) 
                                  From Dual)  
                           ELSE */ Sum ( (Nvl (D.P_Qty, 0) + Nvl (D.Pf_Qty, 0)) * In_Out) 
                           --END  
                      I_Qty
                   , SUM( CASE WHEN D.Doc_Type IN(1,3) THEN ( (Nvl (D.P_Qty, 0) + Nvl (D.Pf_Qty, 0)) * In_Out) ELSE 0 END ) NET_SAL_QTY
                   ,Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) In_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) Out_Qty
                   ,Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0)) In_Free_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0)) Out_Free_Qty
                   ,Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0)) Net_In_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0)) Net_Out_Qty
                   , (Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0))) - (Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0))) Avl_Qty
                   ,Sum ( (Nvl (Stk_Cost, 0) / Nvl (D.P_Size, 1)) * Nvl (P_Qty, 0) * In_Out) Stk_Cost
                   ,Sum (Nvl (D.Vat_Amt, 0) * Nvl (I_Qty, 0)) Vat_Amt
                   ,Sum (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) Dis_Amt
                   ,Sum (Nvl (D.Othr_Amt, 0) * Nvl (I_Qty, 0)) Othr_Amt
                   ,Sum (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) Vat_Amt_Othr
                   ,Sum (Nvl (D.Dis_Amt_Dtl, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl
                   ,Sum (Nvl (D.Dis_Amt_Dtl_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl_Vat
                   ,Sum (Nvl (D.Dis_Amt_Dtl2, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl2
                   ,Sum (Nvl (D.Dis_Amt_Dtl2_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl2_Vat
                   ,Sum (Nvl (D.Dis_Amt_Dtl3, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl3
                   ,Sum (Nvl (D.Dis_Amt_Dtl3_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl3_Vat
               From Item_Movement D              
           Group By  D.I_Code                  
                   ,D.W_Code
                   ,D.Whg_Code                   
                   ,In_Out                                                                                               
                   ,D.Cc_Code
                   ,D.Pj_No
                   ,D.Actv_No
                   ,D.Expire_Date
                   ,D.Cmp_No
                   ,D.Brn_No
                   ,D.Brn_Year
                   ,D.Brn_Usr
                   ,D.Batch_No                    
                   ,D.Doc_Type 
                   ,D.Bill_Doc_Type                                                       
                   ,D.I_Date                                    
                   ,D.Ac_Dtl_Typ
                   ,D.C_Code                   
                   ,D.V_Code ) D
         ,Ias_Itm_Mst M
         ,Warehouse_Details W         
         ,Lng
    Where M.I_Code = D.I_Code And D.W_Code = W.W_Code     
    And Exists
       (Select 1
          From Privilege_Wh
         Where     Privilege_Wh.W_Code = D.W_Code               
               And View_Flag = 1
               And U_Id = LNG.P_USR_NO
               And Rownum <= 1)
       And Exists
               (Select 1
                  From Privilege_Gc
                 Where     Privilege_Gc.G_Code = M.G_CODE                      
                       And View_Flag = 1
                       And U_Id = LNG.P_USR_NO
                        And Rownum <= 1)
       AND 1= CASE WHEN D.Cc_Code Is  Null THEN 1
                 WHEN  Exists
                   (Select 1
                      From Privilege_Cc
                     Where     Privilege_Cc.Cc_Code = D.Cc_Code
                           And View_Flag = 1
                           And U_Id = LNG.P_USR_NO
                           And Rownum <= 1) THEN 1
                  ELSE  0 END 
              AND 1= CASE WHEN D.Pj_No Is  Null THEN 1
                 WHEN Exists(Select 1 From Ias_Priv_Projects
                                     Where   Ias_Priv_Projects.Pj_No= D.Pj_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
               ELSE  0 END 
             AND 1= CASE WHEN D.Actv_No Is  Null THEN 1
                 WHEN Exists(Select 1
                                      From Ias_Priv_Actvty
                                     Where     D.Actv_No = Ias_Priv_Actvty.Actv_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
               ELSE  0 END                         
             And Exists (Select 1
                                      From S_Brn_Usr_Priv
                                     Where     S_Brn_Usr_Priv.Brn_No = D.Brn_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1)
            AND 1= CASE WHEN D.C_Code Is  Null THEN 1
                WHEN  Exists(Select 1
                                      From Ias_Priv_Customer
                                     Where     Ias_Priv_Customer.C_Code = D.C_Code
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
             ELSE  0 END
           AND 1= CASE WHEN D.V_Code Is  Null THEN 1
                WHEN  Exists
                                   (Select 1
                                      From Ias_Priv_Vendor
                                     Where     Ias_Priv_Vendor.V_Code = D.V_Code
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
             ELSE  0 END;


--
-- INV_KPI_ITM_MOVMNT_DTL_VW_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_KPI_ITM_MOVMNT_DTL_VW_YR
(ITM_CODE, ITM_NM, ITM_F_NM, ITM_DSC, ITM_F_DSC, 
 ITM_UNT, MAX_ITM_UNT, MAX_P_SIZE, GRP_CLASS_CODE, GRP_CLASS_NM, 
 ACTIVITY_NO, ACTIVITY_NM, GRP_CODE, GRP_CODE_NM, MNG_CODE, 
 MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, ASSTNT_GRP_CODE, ASSTNT_GRP_NM, 
 DTL_GRP_NO, DTL_GRP_NM, ALTRNTV_GRP_CODE, ALTRNTV_GRP_NM, ITM_TYP_NO, 
 ITM_TYP_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITEM_SIZE, SIZE_ITM, AREA_ITM, WEIGHT_ITM, 
 GTIN_CODE, HSN_CODE, MANF_CODE, ALTER_CODE, MRP_ITM_CLSS, 
 DOC_TYPE, DOC_TYPE_NM, BILL_DOC_TYPE, BILL_DOC_TYPE_NM, DOC_SUB_TYPE, 
 DOC_SUB_TYPE_NM, W_CODE, W_NM, WHG_CODE, WHG_NM, 
 DOC_DATE, HALF_NO, QRTR_NO, PRD_NO, PRD_NM, 
 IN_OUT, IN_OUT_NM, I_QTY, NET_SAL_QTY, IN_QTY, 
 OUT_QTY, IN_FREE_QTY, OUT_FREE_QTY, NET_IN_QTY, NET_OUT_QTY, 
 AVL_QTY, STK_COST, VAT_AMT, DIS_AMT, OTHR_AMT, 
 VAT_AMT_OTHR, DIS_AMT_DTL, DIS_AMT_DTL_VAT, DIS_AMT_DTL2, DIS_AMT_DTL2_VAT, 
 DIS_AMT_DTL3, DIS_AMT_DTL3_VAT, I_CWTAVG, I_LENGTH, I_WIDTH, 
 I_HEIGHT, AC_DTL_TYP, C_CODE, C_NM, V_CODE, 
 V_NM, CC_CODE, CC_NM, PJ_NO, PJ_NM, 
 ACTV_NO, ACTV_NM, EXPIRE_DATE, BATCH_NO, CMP_NO, 
 CMP_NM, BRN_NO, BRN_NM, BRN_YEAR, BRN_USR, 
 CNTRY_NO, CNTRY_NM, PROV_NO, PROV_NM, CITY_NO, 
 CITY_NM, R_CODE, R_CODE_NM, INCOME_DATE, LENGTH_ITM, 
 WIDTH_ITM, HEIGHT_ITM, SEASON_ITM, ORE_ITM, MARK_ITM, 
 COMPANY_ITM, COUNTRY_ITM)
BEQUEATH DEFINER
AS 
With Lng As (Select (select  Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1) from dual) Lng_No
                               ,Nvl((SELECT FLD_VAL FROM S_FLD_PRV_FXD_USR WHERE UPPER(FLD_NM)=UPPER('HIDE_COST') AND U_ID =nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1) AND ROWNUM<=1),0) HIDE_COST                 
                               ,(select Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1)  from dual) P_USR_NO
                               ,(SELECT WTAVG_TYPE FROM IAS_PARA_INV WHERE ROWNUM<=1) WTAVG_TYPE  From Dual                
                )                                
   Select M.I_Code Itm_Code
         ,Decode (Lng.Lng_No, 1, M.I_Name, Nvl (M.I_E_Name, M.I_Name)) Itm_Nm
         ,M.I_E_Name Itm_F_Nm 
         ,Decode (Lng.Lng_No, 1, M.I_Desc, Nvl (M.I_F_Desc, M.I_Desc)) Itm_Dsc
         ,M.I_F_Desc  Itm_F_Dsc
         ,(Select Itm_Unt 
                  From Ias_Itm_Dtl
                   Where Ias_Itm_Dtl.I_Code           = m.I_Code
                     And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 
                     And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 
                     And RowNum                      <= 1 )Itm_Unt
         ,(SELECT ITM_UNT  
             FROM IAS_ITM_DTL 
            WHERE I_CODE= M.I_CODE 
              AND LVL_UNIT = ( SELECT MAX(LVL_UNIT) 
                                 FROM IAS_ITM_DTL
                                WHERE I_CODE= M.I_CODE 
                                 ) AND ROWNUM <=1) MAX_ITM_UNT 
          ,(SELECT P_SIZE 
              FROM IAS_ITM_DTL
             WHERE I_CODE  = M.I_CODE
               AND ITM_UNT = (SELECT ITM_UNT  
                                FROM IAS_ITM_DTL 
                               WHERE I_CODE= M.I_CODE 
                                 AND LVL_UNIT = ( SELECT MAX(LVL_UNIT) 
                                                    FROM IAS_ITM_DTL
                                                   WHERE I_CODE= M.I_CODE
                                                    ) AND ROWNUM <=1) 
               AND ROWNUM <= 1 )  MAX_P_SIZE                       
         ,M.Grp_Class_Code Grp_Class_Code
         ,   M.Grp_Class_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Grp_L_Name, Nvl (A.Grp_F_Name, A.Grp_L_Name))
                From Ias_Grp_Itm_Lvl A
               Where A.Grp_Code = M.Grp_Class_Code And Rownum <= 1)
             Grp_Class_Nm
         ,M.Activity_No Activity_No
         ,   M.Activity_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Activity_A_Name, Nvl (A.Activity_E_Name, A.Activity_A_Name))
                From Ias_Items_Activity A
               Where A.Activity_No = M.Activity_No And Rownum <= 1)
             Activity_Nm
         ,M.G_Code Grp_Code
         ,   M.G_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.G_A_NAME, Grp.G_E_NAME), Nvl (Grp.G_E_NAME, Grp.G_A_NAME)) Grp_Nm
                From GROUP_DETAILS Grp
               Where G_Code = M.G_Code And Rownum <= 1)
             Grp_Code_Nm
         ,M.Mng_Code
         ,   M.Mng_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.MNG_A_NAME, Grp.MNG_E_NAME), Nvl (Grp.MNG_E_NAME, Grp.MNG_A_NAME)) Grp_Nm
                From IAS_MAINSUB_GRP_DTL Grp
               Where  Mng_Code = M.Mng_Code
                  AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                   And Rownum <= 1)
             Mng_Code_Nm
         ,M.Subg_Code
         ,   M.Subg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.SUBG_A_NAME, Grp.SUBG_E_NAME), Nvl (Grp.SUBG_E_NAME, Grp.SUBG_A_NAME)) Grp_Nm
                From IAS_SUB_GRP_DTL Grp
               Where Subg_Code = M.Subg_Code
               AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
               AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code) 
               And Rownum <= 1)
             Subg_Code_Nm
         ,M.Assistant_No Asstnt_Grp_Code
         ,   M.Assistant_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Assistant_A_Name, Grp.Assistant_E_Name), Nvl (Grp.Assistant_E_Name, Grp.Assistant_A_Name)) Grp_Nm
                From Ias_Assistant_Group Grp
               Where Assistant_No = M.Assistant_No 
                 AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                 AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code)
                 AND NVL(M.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL(M.Subg_Code,'0'),Subg_Code)
                 And Rownum <= 1)
             Asstnt_Grp_Nm
         ,M.Detail_No Dtl_Grp_No
         ,   M.Detail_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Detail_A_Name, Grp.Detail_E_Name), Nvl (Grp.Detail_E_Name, Grp.Detail_A_Name)) Grp_Nm
                From Ias_Detail_Group Grp
               Where Detail_No=M.Detail_No
               AND NVL(M.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL(M.G_Code,'0'),G_Code) 
                 AND NVL(M.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL(M.Mng_Code,'0'),Mng_Code)
                 AND NVL(M.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL(M.Subg_Code,'0'),Subg_Code)
                 AND NVL(M.Assistant_No,'0')= DECODE(Nvl (Assistant_No, '0'),'0',NVL(M.Assistant_No,'0'),Assistant_No)
                 And Rownum <= 1)
             Dtl_Grp_Nm
         ,M.Group_No Altrntv_Grp_Code
         ,   M.Group_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Group_A_Name, Nvl (A.Group_E_Name, A.Group_A_Name))
                From Ias_Alternative_Group A
               Where A.Group_No = M.Group_No And Rownum <= 1)
             Altrntv_Grp_Nm
         ,M.Item_Type Itm_Typ_No
         ,   M.Item_Type
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.It_A_Name, Nvl (A.It_E_Name, A.It_A_Name))
                From Item_Types A
               Where A.Type_Of_Item = M.Item_Type And Rownum <= 1)
             Itm_Typ_Nm
         ,M.Kit_Itm
         ,M.Use_Exp_Date
         ,M.Use_Batch_No
         ,M.Use_Serialno
         ,M.Use_Attch
         ,M.Item_Size
         ,M.Size_Itm
         ,M.Area_Itm
         ,M.Weight_Itm
         ,M.Gtin_Code
         ,M.Hsn_Code
         ,M.Manf_Code
         ,M.Alter_Code
         ,(SELECT FLG_VALUE || '-' || FLG_DESC
               FROM S_FLAGS
              WHERE FLG_CODE      = 'MRP_ITM_CLSS'
                    AND LANG_NO   = LNG.LNG_NO
                    AND FLG_VALUE = M.MRP_ITM_CLSS
                    AND ROWNUM <= 1) MRP_ITM_CLSS
         ,D.Doc_Type Doc_Type
         , (Select Flg_Desc
              From S_Flags
             Where Lang_No = Lng.Lng_No And Flg_Code = 'DOC_TYPE_INV' And Flg_Value = D.Doc_Type And Rownum <= 1)
             Doc_Type_Nm
         ,D.Bill_Doc_Type
         ,Decode (D.Doc_Type
                 ,1, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,2, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,3, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,4, (Select Flg_Desc
                        From S_Flags
                       Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = D.Bill_Doc_Type And Rownum <= 1)
                 ,Null)
             Bill_Doc_Type_Nm
         ,Decode (D.Doc_Type,  5, D.Bill_Doc_Type,  6, D.Bill_Doc_Type,  7, D.Bill_Doc_Type,  8, D.Bill_Doc_Type,  11, D.Bill_Doc_Type,  12, D.Bill_Doc_Type,  13, D.Bill_Doc_Type,  14, D.Bill_Doc_Type,  15, D.Bill_Doc_Type,  16, D.Bill_Doc_Type,  17, D.Bill_Doc_Type,  18, D.Bill_Doc_Type,  Null) Doc_Sub_Type
         ,Decode (D.Doc_Type
                 ,5,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Incom_Name, Nvl (Incom_E_Name, Incom_Name))
                           From Incom_Types
                          Where Incom_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,6,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Out_Name, Nvl (Out_E_Name, Out_Name))
                           From Out_Types
                          Where Out_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,7,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Tr_Name, Nvl (Tr_E_Name, Tr_Name))
                           From Transfer_Types
                          Where Tr_Type = D.Bill_Doc_Type And Nvl (Tr_Rec, 0) In (1, 3) And Rownum <= 1)
                 ,8,    D.Bill_Doc_Type
                     || ' - '
                     || (Select Decode (Lng.Lng_No, 1, Tr_Name, Nvl (Tr_E_Name, Tr_Name))
                           From Transfer_Types
                          Where Tr_Type = D.Bill_Doc_Type And Nvl (Tr_Rec, 0) In (2, 3) And Rownum <= 1)
                 ,11,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (1, 3) And Rownum <= 1)
                 ,12,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (1, 3) And Rownum <= 1)
                 ,13,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (2, 3) And Rownum <= 1)
                 ,14,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Typ_L_Nm, Nvl (Typ_F_Nm, Typ_L_Nm))
                            From Inv_Assmbl_Typ
                           Where Typ_No = D.Bill_Doc_Type And Nvl (Assmbl_Flg, 0) In (2, 3) And Rownum <= 1)
                 ,15,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,16,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,17,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,18,    D.Bill_Doc_Type
                      || ' - '
                      || (Select Decode (Lng.Lng_No, 1, Stk_Name, Nvl (Stk_E_Name, Stk_Name))
                            From Ias_Stk_Adjst_Types
                           Where Stk_Type = D.Bill_Doc_Type And Rownum <= 1)
                 ,Null)
             Doc_Sub_Type_Nm
         ,D.W_Code W_Code
         ,   D.W_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, W_Name, Nvl (W_E_Name, W_Name))
                From Warehouse_Details
               Where W_Code = D.W_Code And Rownum <= 1)
             W_Nm
         ,D.Whg_Code Whg_Code
         ,   D.Whg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Whg_A_Name, Nvl (Whg_E_Name, Whg_A_Name)) Whg_Nm
                From Warehouse_Group
               Where Whg_Code = D.Whg_Code And Rownum <= 1)
             Whg_Nm
         ,D.I_Date Doc_Date
         ,ROUND (TO_CHAR (D.I_DATE, 'Q') / 2)
                       HALF_NO
         ,ROUND (TO_CHAR (D.I_DATE, 'Q'))
                       QRTR_NO
         ,To_Number (To_Char (D.I_Date, 'MM')) Prd_No
         ,   To_Number (To_Char (D.I_Date, 'MM'))
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prd_L_Nm, Prd_F_Nm), Nvl (Prd_F_Nm, Prd_L_Nm))
                From S_Prd_Dtl
               Where Prd_No = To_Number (To_Char (I_Date, 'MM')) And Rownum <= 1)
             Prd_Nm
         ,In_Out
         ,Case
             When D.DOC_TYPE = 0 Then
                (Select '1-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 1264 And Rownum <= 1)
             When In_Out = 1 Then
                (Select '2-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 3066 And Rownum <= 1)
             Else
                (Select '3-'||Caption_Det
                   From Ias_Sys.Ias_Labels
                  Where Lang_No = Lng.Lng_No And Label_No = 18764 And Rownum <= 1)
          End
             In_Out_Nm
         ,D.I_Qty
         ,D.NET_SAL_QTY
         ,D.In_Qty
         ,D.Out_Qty
         ,D.In_Free_Qty
         ,D.Out_Free_Qty
         ,D.Net_In_Qty
         ,D.Net_Out_Qty
         ,D.Avl_Qty
         ,Decode(lng.HIDE_COST,1,D.Stk_Cost,0)Stk_Cost
         ,D.Vat_Amt
         ,D.Dis_Amt
         ,D.Othr_Amt
         ,D.Vat_Amt_Othr
         ,D.Dis_Amt_Dtl
         ,D.Dis_Amt_Dtl_Vat
         ,D.Dis_Amt_Dtl2
         ,D.Dis_Amt_Dtl2_Vat
         ,D.Dis_Amt_Dtl3
         ,D.Dis_Amt_Dtl3_Vat
         ,DECODE (LNG.HIDE_COST, 1, ROUND(Ias_Itm_Pkg.Get_Grand_Wtavg( P_Wtavg_Type =>Lng.Wtavg_Type,
																                                       P_Icode      =>M.I_Code ,
																                                       P_Wcode      =>D.W_Code),4), 0) I_Cwtavg
         ,D.I_Length
         ,D.I_Width
         ,D.I_Height
         ,D.Ac_Dtl_Typ
         ,D.C_Code
         ,   D.C_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (C_A_Name, C_E_Name), Nvl (C_E_Name, C_A_Name))
                From Customer
               Where C_Code = D.C_Code And Rownum <= 1)
             C_Nm
         ,D.V_Code
         ,   D.V_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (V_A_Name, V_E_Name), Nvl (V_E_Name, V_A_Name))
                From V_Details
               Where V_Code = D.V_Code And Rownum <= 1)
             V_Nm
         ,D.Cc_Code
         ,   D.Cc_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cc_A_Name, Cc_E_Name), Nvl (Cc_E_Name, Cc_A_Name))
                From Cost_Centers
               Where Cc_Code = D.Cc_Code And Rownum <= 1)
             Cc_Nm
         ,D.Pj_No
         ,   D.Pj_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Pj_A_Name, Pj_E_Name), Nvl (Pj_A_Name, Pj_E_Name))
                From Ias_Projects
               Where Pj_No = D.Pj_No And Rownum <= 1)
             Pj_Nm
         ,D.Actv_No
         ,   D.Actv_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Actv_A_Name, Actv_E_Name), Nvl (Actv_E_Name, Actv_A_Name))
                From Ias_Actvty
               Where Actv_No = D.Actv_No And Rownum <= 1)
             Actv_Nm
         ,Decode (D.Expire_Date, '01/01/1900', Null, D.Expire_Date) Expire_Date
         ,Decode (D.Batch_No, '0', Null, D.Batch_No) Batch_No
         ,D.Cmp_No Cmp_No
         ,   D.Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cmp_Lname, Cmp_Fname), Nvl (Cmp_Fname, Cmp_Lname))
                From S_Cmpny
               Where Cmp_No = D.Cmp_No And Rownum <= 1)
             Cmp_Nm
         ,D.Brn_No Brn_No
         ,   D.Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = D.Brn_No And Rownum <= 1)
             Brn_Nm
         ,D.Brn_Year
         ,D.Brn_Usr
         ,W.Cntry_No
         ,   W.Cntry_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cntry_A_Name, Cntry_E_Name), Nvl (Cntry_E_Name, Cntry_A_Name))
                From Cntry
               Where Cntry_No = W.Cntry_No And Rownum <= 1)
             Cntry_Nm
         ,W.Prov_No
         ,   W.Prov_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prov_A_Name, Prov_E_Name), Nvl (Prov_E_Name, Prov_A_Name))
                From Ias_Provinces
               Where Prov_No = W.Prov_No And Rownum <= 1)
             Prov_Nm
         ,W.City_No
         ,   W.City_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (City_A_Name, City_E_Name), Nvl (City_E_Name, City_A_Name))
                From Cities
               Where City_No = W.City_No And Rownum <= 1)
             City_Nm
         ,W.R_Code
         ,   W.R_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (R_A_Name, R_A_Name), Nvl (R_E_Name, R_A_Name))
                From Regions
               Where R_Code = W.R_Code And Rownum <= 1)
             R_Code_Nm
         ,M.Income_Date
         ,M.Length_Itm
         ,M.Width_Itm
         ,M.Height_Itm
         ,M.Season_Itm
         ,M.Ore_Itm
         ,M.Mark_Itm
         ,M.Company_Itm
         ,M.Country_Itm
     From (  Select D.I_Code                  
                   ,D.W_Code
                   ,D.Whg_Code                   
                   ,In_Out                                                                                               
                   ,D.Cc_Code
                   ,D.Pj_No
                   ,D.Actv_No
                   ,D.Expire_Date
                   ,D.Cmp_No
                   ,D.Brn_No
                   ,D.Brn_Year
                   ,D.Brn_Usr
                   ,D.Batch_No                    
                   ,D.Doc_Type 
                   ,D.Bill_Doc_Type                                                       
                   ,D.I_Date                  
                   ,NULL I_Length
                   ,NULL I_Width
                   ,NULL I_Height
                   ,D.Ac_Dtl_Typ
                   ,D.C_Code                   
                   ,D.V_Code
                    /* CASE WHEN D.Doc_Type = 0 THEN 
                               ( Select Open_Stock ( I_Code,
                                                     w_code,
                                                    To_Date(Ias_Gen_Pkg.Get_Frst_Day,'DD/MM/YYYY'),
                                                    NULL
                                                   ) 
                                  From Dual)  
                           ELSE */ ,Sum ( (Nvl (D.P_Qty, 0) + Nvl (D.Pf_Qty, 0)) * In_Out) 
                           --END  
                      I_Qty                   
                   , SUM( CASE WHEN D.Doc_Type IN(1,3) THEN ( (Nvl (D.P_Qty, 0) + Nvl (D.Pf_Qty, 0)) * In_Out) ELSE 0 END ) NET_SAL_QTY
                   ,Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) In_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) Out_Qty
                   ,Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0)) In_Free_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0)) Out_Free_Qty
                   ,Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0)) Net_In_Qty
                   ,Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0)) Net_Out_Qty
                   , (Sum (Decode (In_Out, 1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, 1, Nvl (D.Pf_Qty, 0), 0))) - (Sum (Decode (In_Out, -1, Nvl (D.P_Qty, 0), 0)) + Sum (Decode (In_Out, -1, Nvl (D.Pf_Qty, 0), 0))) Avl_Qty
                   ,Sum ( (Nvl (Stk_Cost, 0) / Nvl (D.P_Size, 1)) * Nvl (P_Qty, 0) * In_Out) Stk_Cost
                   ,Sum (Nvl (D.Vat_Amt, 0) * Nvl (I_Qty, 0)) Vat_Amt
                   ,Sum (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) Dis_Amt
                   ,Sum (Nvl (D.Othr_Amt, 0) * Nvl (I_Qty, 0)) Othr_Amt
                   ,Sum (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) Vat_Amt_Othr
                   ,Sum (Nvl (D.Dis_Amt_Dtl, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl
                   ,Sum (Nvl (D.Dis_Amt_Dtl_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl_Vat
                   ,Sum (Nvl (D.Dis_Amt_Dtl2, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl2
                   ,Sum (Nvl (D.Dis_Amt_Dtl2_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl2_Vat
                   ,Sum (Nvl (D.Dis_Amt_Dtl3, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl3
                   ,Sum (Nvl (D.Dis_Amt_Dtl3_Vat, 0) * Nvl (I_Qty, 0)) Dis_Amt_Dtl3_Vat
               From Ias_V_Itm_Movmnt_Yr D              
           Group By  D.I_Code                  
                   ,D.W_Code
                   ,D.Whg_Code                   
                   ,In_Out                                                                                               
                   ,D.Cc_Code
                   ,D.Pj_No
                   ,D.Actv_No
                   ,D.Expire_Date
                   ,D.Cmp_No
                   ,D.Brn_No
                   ,D.Brn_Year
                   ,D.Brn_Usr
                   ,D.Batch_No                    
                   ,D.Doc_Type 
                   ,D.Bill_Doc_Type                                                       
                   ,D.I_Date                                    
                   ,D.Ac_Dtl_Typ
                   ,D.C_Code                   
                   ,D.V_Code ) D
         ,Ias_Itm_Mst M
         ,Warehouse_Details W         
         ,Lng
    Where M.I_Code = D.I_Code And D.W_Code = W.W_Code     
    And Exists
       (Select 1
          From Privilege_Wh
         Where     Privilege_Wh.W_Code = D.W_Code               
               And View_Flag = 1
               And U_Id = LNG.P_USR_NO
               And Rownum <= 1)
       And Exists
               (Select 1
                  From Privilege_Gc
                 Where     Privilege_Gc.G_Code = M.G_CODE                      
                       And View_Flag = 1
                       And U_Id = LNG.P_USR_NO
                        And Rownum <= 1)
       AND 1= CASE WHEN D.Cc_Code Is  Null THEN 1
                 WHEN  Exists
                   (Select 1
                      From Privilege_Cc
                     Where     Privilege_Cc.Cc_Code = D.Cc_Code
                           And View_Flag = 1
                           And U_Id = LNG.P_USR_NO
                           And Rownum <= 1) THEN 1
                  ELSE  0 END 
              AND 1= CASE WHEN D.Pj_No Is  Null THEN 1
                 WHEN Exists(Select 1 From Ias_Priv_Projects
                                     Where   Ias_Priv_Projects.Pj_No= D.Pj_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
               ELSE  0 END 
             AND 1= CASE WHEN D.Actv_No Is  Null THEN 1
                 WHEN Exists(Select 1
                                      From Ias_Priv_Actvty
                                     Where     D.Actv_No = Ias_Priv_Actvty.Actv_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
               ELSE  0 END                         
             And Exists (Select 1
                                      From S_Brn_Usr_Priv
                                     Where     S_Brn_Usr_Priv.Brn_No = D.Brn_No
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1)
            AND 1= CASE WHEN D.C_Code Is  Null THEN 1
                WHEN  Exists(Select 1
                                      From Ias_Priv_Customer
                                     Where     Ias_Priv_Customer.C_Code = D.C_Code
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
             ELSE  0 END
           AND 1= CASE WHEN D.V_Code Is  Null THEN 1
                WHEN  Exists
                                   (Select 1
                                      From Ias_Priv_Vendor
                                     Where     Ias_Priv_Vendor.V_Code = D.V_Code
                                           And View_Flag = 1
                                           And U_Id = LNG.P_USR_NO
                                           And Rownum <= 1) THEN 1
             ELSE  0 END;


--
-- INV_V_REM_WHTRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_REM_WHTRNS
(TR_INOUT_TYPE, TR_TYPE, TR_NO, TR_SER, TR_DATE, 
 REF_NO, W_CODE, T_W_CODE, F_W_CODE, CC_CODE, 
 PJ_NO, ACTV_NO, TR_DESC, STK_RATE, TR_POST, 
 TR_AMT, TR_RES, LOAD_NO, ATTACH_CNT, PR_REP, 
 PROCESSED, STK_PROCESSED, PROCESSED_SI, HUNG, T_TR_TYPE, 
 TR_A_CODE, AC_CODE_DTL, AC_DTL_TYP, EXP_TYPE, EXP_AMT, 
 C_CODE, DOC_BRN_NO, AUDIT_REF, AUDIT_REF_DESC, AUDIT_REF_U_ID, 
 AUDIT_REF_DATE, LGHT_MOV_DATE, EXTERNAL_POST, F_TR_NO, F_TR_SER, 
 BOE_NO, TR_COST_TYPE, DIFF_A_CODE, DIFF_A_CY, DIFF_AMT, 
 RTN_TR, RTRN_TR_STKCOST, FIELD1, FIELD2, FIELD3, 
 DRIVER_NO, DOC_PST_SQ, SYS_DOC_ID, INSTLL_ITM_MNL, TR_NO_REF, 
 TR_SER_REF, TR_PRPRTN_ADJST, DOC_NO_REF, DOC_SER_REF, DOC_TYPE_REF, 
 AD_U_ID, AD_DATE, UP_U_ID, UP_DATE, UP_CNT, 
 POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, CMP_NO, 
 BRN_NO, BRN_YEAR, BRN_USR, AD_TRMNL_NM, UP_TRMNL_NM)
BEQUEATH DEFINER
AS 
Select "TR_INOUT_TYPE","TR_TYPE","TR_NO","TR_SER","TR_DATE","REF_NO","W_CODE","T_W_CODE","F_W_CODE","CC_CODE","PJ_NO","ACTV_NO","TR_DESC","STK_RATE","TR_POST","TR_AMT","TR_RES","LOAD_NO","ATTACH_CNT","PR_REP","PROCESSED","STK_PROCESSED","PROCESSED_SI","HUNG","T_TR_TYPE","TR_A_CODE","AC_CODE_DTL","AC_DTL_TYP","EXP_TYPE","EXP_AMT","C_CODE","DOC_BRN_NO","AUDIT_REF","AUDIT_REF_DESC","AUDIT_REF_U_ID","AUDIT_REF_DATE","LGHT_MOV_DATE","EXTERNAL_POST","F_TR_NO","F_TR_SER","BOE_NO","TR_COST_TYPE","DIFF_A_CODE","DIFF_A_CY","DIFF_AMT","RTN_TR","RTRN_TR_STKCOST","FIELD1","FIELD2","FIELD3","DRIVER_NO","DOC_PST_SQ","SYS_DOC_ID","INSTLL_ITM_MNL","TR_NO_REF","TR_SER_REF","TR_PRPRTN_ADJST","DOC_NO_REF","DOC_SER_REF","DOC_TYPE_REF","AD_U_ID","AD_DATE","UP_U_ID","UP_DATE","UP_CNT","POST_U_ID","POST_DATE","UNPOST_U_ID","UNPOST_DATE","CMP_NO","BRN_NO","BRN_YEAR","BRN_USR","AD_TRMNL_NM","UP_TRMNL_NM"
			From Ias_Whtrns_Mst Wht_Mst
			Where Tr_Inout_Type = 1
			  And  Exists (
			Select 1
			From Ias_Whtrns_Dtl
			Where F_Tr_Ser=Wht_Mst.F_Tr_Ser
			Group By F_Tr_Ser
			Having Sum(Decode(Tr_Inout_Type,1,I_Qty,(I_Qty*-1))) < 0);

COMMENT ON COLUMN IAS20261.INV_V_REM_WHTRNS.REF_NO IS '143 - —ﬁ„ «·„—Ã⁄';

