--
-- PURCHS_BILL_DTL_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.PURCHS_BILL_DTL_AI_VW
(DOC_NO, DOC_SRL, DOC_D_SQ, YR_NO, UNT_NO, 
 ITM_CODE, ITM_UNT, ITM_SZ, WRHS_CODE, EXP_DATE, 
 ITM_SGMNT_CNTCT, ITM_QTY, ITM_FREE_QTY, ITM_FREE_QTY_ADD, ITM_TOTL_FREE_QTY, 
 ITM_MN_QTY, ITM_MN_FREE_QTY, ITM_TOTL_MN_FREE_QTY, ITM_PRICE, ITM_STK_CST, 
 ITM_TAX_PRCNT, ITM_TAX_AMT, ITM_OTHR_CHRG_AMT, ITM_DSCNT_AMT, ITM_DSCNT_AMT_ADD, 
 ITM_TOTL_PRICE, ITM_TOTL_DSCNT_AMT, ITM_TOTL_OTHR_CHRG_AMT, ITM_TOTL_TAX_AMT, ITM_TOTL_DSCNT_AMT_ADD, 
 ITM_TOTL_AMT, ITM_TOTL_STK_CST, ITM_TOTL_PRICE_LOCAL, ITM_TOTL_DSCNT_AMT_LOCAL, ITM_TOTL_OTHR_AMT_LOCAL, 
 ITM_TOTL_TAX_AMT_LOCAL, ITM_DSCNT_AMT_ADD_LOCAL, ITM_TOTL_AMT_LOCAL, SUB_LDGR1_CODE, SUB_LDGR2_CODE, 
 SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, SUB_LDGR6_CODE)
BEQUEATH DEFINER
AS 
SELECT D.BILL_NO DOC_NO,
          D.BILL_SER DOC_SRL,
          D.DOC_SEQUENCE DOC_D_SQ,
          D.BRN_YEAR YR_NO,
          D.BRN_NO UNT_NO,
          D.I_CODE ITM_CODE,
          D.ITM_UNT,
          D.P_SIZE ITM_SZ,          
          D.W_CODE  WRHS_CODE,
          D.EXPIRE_DATE EXP_DATE,
          D.BATCH_NO ITM_SGMNT_CNTCT,
          NVL(D.I_QTY,0)              ITM_QTY,                    
          NVL(D.FREE_QTY,0)         ITM_FREE_QTY,
          0     ITM_FREE_QTY_ADD,
          (NVL(D.FREE_QTY,0)) ITM_TOTL_FREE_QTY,
          NVL(D.P_QTY,0)          ITM_MN_QTY, 
          (NVL(D.FREE_QTY,0)*NVL(D.P_SIZE,1))     ITM_MN_FREE_QTY,            
          ((NVL(D.FREE_QTY,0)*NVL(D.P_SIZE,1)) ) ITM_TOTL_MN_FREE_QTY,
          NVL(D.I_PRICE,0)         ITM_PRICE,
          NVL(D.STK_COST,0)       ITM_STK_CST,
          NVL(D.VAT_PER,0)     ITM_TAX_PRCNT,
          NVL(D.VAT_AMT,0)       ITM_TAX_AMT,
          NVL(D.OTHR_AMT,0)      ITM_OTHR_CHRG_AMT,
          NVL(D.DIS_AMT,0)     ITM_DSCNT_AMT,
          NVL(D.ADD_DIS_AMT_DTL,0) ITM_DSCNT_AMT_ADD,
          (NVL(D.I_QTY,0) * NVL(D.I_PRICE,0))         ITM_TOTL_PRICE,
          (NVL(D.I_QTY,0) * NVL(D.DIS_AMT,0))     ITM_TOTL_DSCNT_AMT,
          (NVL(D.I_QTY,0) * NVL(D.OTHR_AMT,0))      ITM_TOTL_OTHR_CHRG_AMT,
          (NVL(D.I_QTY,0) * NVL(D.VAT_AMT,0))       ITM_TOTL_TAX_AMT,
          (NVL(D.I_QTY,0) * NVL(D.ADD_DIS_AMT_DTL,0)) ITM_TOTL_DSCNT_AMT_ADD,
          (NVL(D.I_QTY,0) * ( NVL(D.I_PRICE,0)- NVL(D.DIS_AMT,0)+ NVL(D.OTHR_AMT,0)+ NVL(D.VAT_AMT,0))) ITM_TOTL_AMT,
          ((NVL(D.I_QTY,0)+NVL(D.FREE_QTY,0))*NVL(D.STK_COST,0)) ITM_TOTL_STK_CST,
          (NVL(D.I_QTY,0) * NVL(D.I_PRICE,0)*M.BILL_RATE)         ITM_TOTL_PRICE_LOCAL,
          (NVL(D.I_QTY,0) * NVL(D.DIS_AMT,0)*M.BILL_RATE)     ITM_TOTL_DSCNT_AMT_LOCAL,
          (NVL(D.I_QTY,0) * NVL(D.OTHR_AMT,0)*M.BILL_RATE)      ITM_TOTL_OTHR_AMT_LOCAL,
          (NVL(D.I_QTY,0) * NVL(D.VAT_AMT,0)*M.BILL_RATE)       ITM_TOTL_TAX_AMT_LOCAL,
          (NVL(D.I_QTY,0) * NVL(D.ADD_DIS_AMT_DTL,0)*M.BILL_RATE) ITM_DSCNT_AMT_ADD_LOCAL,
          (NVL(D.I_QTY,0) * ( NVL(D.I_PRICE,0)- NVL(D.DIS_AMT,0)+ NVL(D.OTHR_AMT,0)+ NVL(D.VAT_AMT,0))*M.BILL_RATE) ITM_TOTL_AMT_LOCAL,
          D.CC_CODE SUB_LDGR1_CODE,
          D.PJ_NO SUB_LDGR2_CODE,
          D.ACTV_NO SUB_LDGR3_CODE,
          NULL  SUB_LDGR4_CODE,
          NULL  SUB_LDGR5_CODE,
          NULL  SUB_LDGR6_CODE
     FROM IAS_PI_BILL_MST M,IAS_PI_BILL_DTL D
    WHERE M.BILL_SER = D.BILL_SER;


--
-- SALES_RT_BILL_MST_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SALES_RT_BILL_MST_AI_VW
(TYP_NO, DOC_NO, DOC_SRL, DOC_DATE, MNL_DATE, 
 CUR_CODE, CUR_RATE, STK_RATE, WRHS_CODE, UNT_NO, 
 PYMNT_CSH, PYMNT_BNK, PYMNT_CRDT, PYMNT_CPN, PYMNT_AC, 
 PYMNT_POINT_RPLC, PYMNT_RPLC, CSTMR_CODE, CSTMR_NM, CSTMR_MOBILE, 
 AC_CODE_DTL_SUB_CST, CSH_CODE, BNK_CODE, AC_CODE_DTL_SUB_BNK, AC_CODE, 
 AC_CODE_DTL, AC_DTL_TYP, AC_CODE_DTL_SUB, CSH_AMT, BNK_AMT, 
 CRDT_AMT, CPN_AMT, AC_AMT, RPLC_AMT, POINT_AMT_RPLC, 
 DOC_AMT, DSCNT_AMT, OTHR_AMT, TAX_AMT, DSCNT_AMT_ADD, 
 CSH_AMT_LOCAL, BNK_AMT_LOCAL, CRDT_AMT_LOCAL, CPN_AMT_LOCAL, AC_AMT_LOCAL, 
 RPLC_AMT_LOCAL, POINT_AMT_RPLC_LOCAL, TOTL_BILL_AMT, TOTL_BILL_AMT_LOCAL, SMAN_CODE, 
 MRKTR_CODE, CLCTR_CODE, EMP_CODE, DRVR_NO, RGN_NO, 
 SUB_LDGR1_CODE, SUB_LDGR2_CODE, SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, 
 SUB_LDGR6_CODE, TAX_CODE, DOC_DUE_DATE, DOC_DSC, REF_NO, 
 MNL_NO, CHQ_NOTE_NO, CHQ_NOTE_DATE, COMM_PRCNT, TAX_CTGRY_NO, 
 TAX_BILL_TYP, RESON_TYP, RESON_DESC, CLC_TAX_FREE_QTY_FLG, VRFY_FLG, 
 STNDBY_FLG, PST_FLG, YR_NO, CRT_USR, CRT_DATE)
BEQUEATH DEFINER
AS 
SELECT SR_TYPE
               TYP_NO,
           RT_BILL_NO
               DOC_NO,
           RT_BILL_SER
               DOC_SRL,
           RT_BILL_DATE
               DOC_DATE,
           RT_BILL_DATE
               MNL_DATE,
           RT_BILL_CURRENCY
               CUR_CODE,
           RT_BILL_RATE
               CUR_RATE,
           STOCK_RATE
               STK_RATE,
           W_CODE
               WRHS_CODE,
           BRN_NO
               UNT_NO,
           (CASE WHEN RT_BILL_DOC_TYPE = 1 THEN 1 ELSE 0 END)
               PYMNT_CSH,
           (CASE
                WHEN RT_BILL_DOC_TYPE IN (2,
                                          3,
                                          5,
                                          6)
                THEN
                    1
                ELSE
                    0
            END)
               PYMNT_BNK,
           (CASE WHEN RT_BILL_DOC_TYPE = 4 THEN 1 ELSE 0 END)
               PYMNT_CRDT,
           0
               PYMNT_CPN,
           (CASE WHEN RT_BILL_DOC_TYPE = 8 THEN 1 ELSE 0 END)
               PYMNT_AC,
           0
               PYMNT_POINT_RPLC,
           0
               PYMNT_RPLC,
           C_CODE
               CSTMR_CODE,
           C_NAME
               CSTMR_NM,
           C_TEL
               CSTMR_MOBILE,
           NULL
               AC_CODE_DTL_SUB_CST,
           (CASE WHEN RT_BILL_DOC_TYPE = 1 THEN CASH_NO ELSE NULL END)
               CSH_CODE,
           (CASE
                WHEN RT_BILL_DOC_TYPE IN (2,
                                          3,
                                          5,
                                          6)
                THEN
                    CASH_NO
                ELSE
                    NULL
            END)
               BNK_CODE,
           NULL
               AC_CODE_DTL_SUB_BNK,
           AC_CODE,
           AC_CODE_DTL,
           AC_DTL_TYP,
           NULL
               AC_CODE_DTL_SUB,
           (CASE
                WHEN RT_BILL_DOC_TYPE = 1
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               CSH_AMT,
           (CASE
                WHEN RT_BILL_DOC_TYPE IN (2,
                                          3,
                                          5,
                                          6)
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               BNK_AMT,
           (CASE
                WHEN RT_BILL_DOC_TYPE = 4
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               CRDT_AMT,
           0
               CPN_AMT,
           (CASE
                WHEN RT_BILL_DOC_TYPE = 8
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               AC_AMT,
           0
               RPLC_AMT,
           0
               POINT_AMT_RPLC,
           NVL (BILL_AMT, 0)
               DOC_AMT,
           NVL (DISC_AMT, 0)
               DSCNT_AMT,
           NVL (OTHR_AMT, 0)
               OTHR_AMT,
           NVL (VAT_AMT, 0)
               TAX_AMT,
           (NVL (ADD_DISC_AMT_MST, 0) + NVL (ADD_DISC_AMT_DTL, 0))
               DSCNT_AMT_ADD,
           (  (CASE
                   WHEN RT_BILL_DOC_TYPE = 1
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * RT_BILL_RATE)
               CSH_AMT_LOCAL,
           (  (CASE
                   WHEN RT_BILL_DOC_TYPE IN (2,
                                             3,
                                             5,
                                             6)
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * RT_BILL_RATE)
               BNK_AMT_LOCAL,
           (  (CASE
                   WHEN RT_BILL_DOC_TYPE = 4
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * RT_BILL_RATE)
               CRDT_AMT_LOCAL,
           0
               CPN_AMT_LOCAL,
           (  (CASE
                   WHEN RT_BILL_DOC_TYPE = 8
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * RT_BILL_RATE)
               AC_AMT_LOCAL,
           0
               RPLC_AMT_LOCAL,
           0
               POINT_AMT_RPLC_LOCAL,
           (  BILL_AMT
            - NVL (DISC_AMT, 0)
            + NVL (OTHR_AMT, 0)
            + NVL (VAT_AMT, 0)
            - NVL (DISC_AMT_AFTR_VAT, 0))
               TOTL_BILL_AMT,
           (  (  BILL_AMT
               - NVL (DISC_AMT, 0)
               + NVL (OTHR_AMT, 0)
               + NVL (VAT_AMT, 0)
               - NVL (DISC_AMT_AFTR_VAT, 0))
            * RT_BILL_RATE)
               TOTL_BILL_AMT_LOCAL,
           REP_CODE
               SMAN_CODE,
           PRM_CODE
               MRKTR_CODE,
           COL_NO
               CLCTR_CODE,
           EMP_NO
               EMP_CODE,
           DRIVER_NO
               DRVR_NO,
           R_CODE
               RGN_NO,          
           CC_CODE
               SUB_LDGR1_CODE,
           PJ_NO
               SUB_LDGR2_CODE,
           ACTV_NO
               SUB_LDGR3_CODE,
           NULL
               SUB_LDGR4_CODE,
           NULL
               SUB_LDGR5_CODE,
           NULL
               SUB_LDGR6_CODE,
           C_TAX_CODE
               TAX_CODE,
           RT_BILL_DUE_DATE
               DOC_DUE_DATE,
           A_DESC
               DOC_DSC,
           REF_NO,
           NULL
               MNL_NO,
           CHEQUE_NO
               CHQ_NOTE_NO,
           CHEQUE_DUE_DATE
               CHQ_NOTE_DATE,
           COMM_PER
               COMM_PRCNT,
           CLC_TYP_NO_TAX
               TAX_CTGRY_NO,
           TAX_BILL_TYP,
           RES_TYP
               RESON_TYP,
           RETURN_RES
               RESON_DESC,
           CLC_TAX_FREE_QTY_FLG,
           AUDIT_REF
               VRFY_FLG,
           STAND_BY
               STNDBY_FLG,
           RT_BILL_POST
               PST_FLG,
           BRN_YEAR
               YR_NO,
           AD_U_ID
               CRT_USR,
           AD_DATE
               CRT_DATE
      FROM IAS_RT_BILL_MST;

COMMENT ON COLUMN IAS20261.SALES_RT_BILL_MST_AI_VW.CSTMR_MOBILE IS '770 - —ﬁ„ «·ÃÊ«·';



--
-- S_V_SCR_CSS_PRV  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.S_V_SCR_CSS_PRV
(U_ID, USR_NM, SCR_NO, PRV_FLG, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, REC_SRC)
BEQUEATH DEFINER
AS 
Select A.C_Code,
                          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                                  1, Nvl (B.C_A_Name, B.C_E_Name),
                                  Nvl (B.C_E_Name, B.C_A_Name)
                                 ) Usr_Nm,
                          A.Scr_No, A.Inc_Flg, A.Ad_U_Id, A.Ad_Date, Null Up_U_Id,
                          Null Up_Date, 1 Rec_Src
                   From   S_Scr_Css_Prv A,
                          Customer B,
                          S_Scr_Css C
                   Where  A.C_Code = B.C_Code
                   And    A.Scr_No = C.Scr_No
                   And    A.Inc_Flg = 1
                   And    Nvl (C.Inactive, 0) = 0
                   Union
                   Select B.C_Code,
                          Decode (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_NO'),
                                  1, Nvl (B.C_A_Name, B.C_E_Name),
                                  Nvl (B.C_E_Name, B.C_A_Name)
                                 ) Usr_Nm,
                          C.Scr_No, 0 Prv_Flg, Null Ad_U_Id, Null Ad_Date, Null Up_U_Id,
                          Null Up_Date, 0 Rec_Src
                   From   Customer B,
                          S_Scr_Css C
                   Where  Nvl (C.Inactive, 0) = 0
                   And    Not Exists (
                                 Select 1
                                 From   S_Scr_Css_Prv
                                 Where  C_Code = B.C_Code And Scr_No = C.Scr_No
                                        And Rownum <= 1);

COMMENT ON COLUMN IAS20261.S_V_SCR_CSS_PRV.AD_DATE IS '759 -  «—ÌŒ «·≈œŒ«·';

COMMENT ON COLUMN IAS20261.S_V_SCR_CSS_PRV.UP_U_ID IS '760 - „⁄œ· «·”Ã·';

COMMENT ON COLUMN IAS20261.S_V_SCR_CSS_PRV.UP_DATE IS '761 -  «—ÌŒ √Œ—  ⁄œÌ·';



--
-- AUD_ARS_LOCTN_GEO_SMAN_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_ARS_LOCTN_GEO_SMAN_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.ARS_LOCTN_GEO_SMAN
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
														                 END IF;
                                                                                   
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','AD_DATE',:NEW.AD_DATE,:OLD.AD_DATE,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','AD_TRMNL_NM',:NEW.AD_TRMNL_NM,:OLD.AD_TRMNL_NM,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','AD_U_ID',:NEW.AD_U_ID,:OLD.AD_U_ID,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','CODE_NO',:NEW.CODE_NO,:OLD.CODE_NO,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','LOC_TYP',:NEW.LOC_TYP,:OLD.LOC_TYP,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','REP_CODE',:NEW.REP_CODE,:OLD.REP_CODE,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'ARS_LOCTN_GEO_SMAN','UP_TRMNL_NM',:NEW.UP_TRMNL_NM,:OLD.UP_TRMNL_NM,Nvl(:NEW.LOC_TYP,:OLD.LOC_TYP),Nvl(:NEW.CODE_NO,:OLD.CODE_NO),Nvl(:NEW.REP_CODE,:OLD.REP_CODE),NULL,NULL,NULL,NULL,NULL); 

                                        END;
/


--
-- AUD_CUSTOMER_BNK_ACCNT_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_CUSTOMER_BNK_ACCNT_TGR 
