--
-- AUD_DETAIL_OUT_BILLS_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.AUD_DETAIL_OUT_BILLS_TGR 
                                        AFTER UPDATE OR DELETE ON IAS20261.DETAIL_OUT_BILLS
                                        FOR EACH ROW
DECLARE
                                        V_OP_TYPE NUMBER;
                                        BEGIN  
                                             IF UPDATING  THEN
														                     V_OP_TYPE:=1;
														                 ELSE
														                     V_OP_TYPE:=2;
