        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_JRNL_FILE_DTL','TAX_AMT',:NEW.TAX_AMT,:OLD.TAX_AMT,Nvl(:NEW.J_SER,:OLD.J_SER),Nvl(:NEW.A_CODE,:OLD.A_CODE),Nvl(:NEW.RCRD_NO,:OLD.RCRD_NO),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.J_DOC_NO,:OLD.J_DOC_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_JRNL_FILE_DTL','TAX_PRCNT',:NEW.TAX_PRCNT,:OLD.TAX_PRCNT,Nvl(:NEW.J_SER,:OLD.J_SER),Nvl(:NEW.A_CODE,:OLD.A_CODE),Nvl(:NEW.RCRD_NO,:OLD.RCRD_NO),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.J_DOC_NO,:OLD.J_DOC_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_JRNL_FILE_DTL','V_CODE',:NEW.V_CODE,:OLD.V_CODE,Nvl(:NEW.J_SER,:OLD.J_SER),Nvl(:NEW.A_CODE,:OLD.A_CODE),Nvl(:NEW.RCRD_NO,:OLD.RCRD_NO),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.J_DOC_NO,:OLD.J_DOC_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_JRNL_FILE_DTL','WO_NO',:NEW.WO_NO,:OLD.WO_NO,Nvl(:NEW.J_SER,:OLD.J_SER),Nvl(:NEW.A_CODE,:OLD.A_CODE),Nvl(:NEW.RCRD_NO,:OLD.RCRD_NO),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.J_DOC_NO,:OLD.J_DOC_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'S_JRNL_FILE_DTL','WO_SER',:NEW.WO_SER,:OLD.WO_SER,Nvl(:NEW.J_SER,:OLD.J_SER),Nvl(:NEW.A_CODE,:OLD.A_CODE),Nvl(:NEW.RCRD_NO,:OLD.RCRD_NO),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.J_DOC_NO,:OLD.J_DOC_NO)); 

                                        END;
/


--
-- CHK_TAX_PR_BILL_MST  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.chk_tax_PR_BILL_MST
			BEFORE INSERT
			ON IAS20261.IAS_PR_BILL_MST 
			REFERENCING NEW AS New OLD AS Old
			FOR EACH ROW
BEGIN                                                                                     
			             
			     If :NEW.CLC_TYP_NO_TAX IS NULL    Then
			        Raise_application_error(-20469,'Error When insert RT BILL into IAS_PR_BILL_MST Table '||SqlErrm) ;
			     End If;
			   
			  END chk_tax_PR_BILL_MST;
/


--
-- CHK_TAX_RT_BILL_MST  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.chk_tax_RT_BILL_MST
			BEFORE INSERT
			ON IAS20261.IAS_RT_BILL_MST 
			REFERENCING NEW AS New OLD AS Old
			FOR EACH ROW
BEGIN                                                                                     
			             
			     If :NEW.CLC_TYP_NO_TAX IS NULL And Nvl(:New.Vat_Amt,0)> 0  Then
			        Raise_application_error(-20469,'Error When insert RT BILL into IAS_RT_BILL_MST Table '||SqlErrm) ;
			     End If;
			   
			  END chk_tax_RT_BILL_MST;
/


--
-- GLS_JRNLJRS_DTL_INSTLMNT_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_JRNLJRS_DTL_INSTLMNT_TRGR
BEFORE DELETE OR INSERT OR UPDATE
OF A_CY
  ,DR_AMT
  ,DR_AMT_F
  ,CR_AMT
  ,CR_AMT_F
  ,BILL_NO
  ,BILL_SER
  ,I_NO
ON IAS20261.S_JRNL_FILE_DTL 
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE 
  -- ADDED BY MURAD ALGARRASH
  -- DATE    19/02/2020
  
  V_VCHR_DATE  DATE;
  V_Stnd_By    number(1);
  Ino          Number(38):=1;  
BEGIN

IF NVL(:NEW.DOC_TYPE ,:OLD.DOC_TYPE) BETWEEN  9000 AND 9100 THEN  ----1
   
     If INSERTING  Then --(1)
       ---------Start JURNAL ---------------------------------------------------------------------------------------------------------------  
          Begin
             Select J_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
               From S_JRNL_FILE_MST 
              Where  J_Ser=:NEW.j_ser
                 AND ROWNUM<=1;
          Exception
            When Others Then
            V_Stnd_By:=0;
          End; 
                      ----------------------------------------------------------- 
                                    
              --##-------------------------------------------------------------------------------------------------------------------##--
           If :NEW.AC_DTL_TYP=3  AND nvl(V_Stnd_By,0)=0 AND :NEW.AC_CODE_DTL Is  Not Null And Nvl(:NEW.DR_AMT,0)>0  Then 	  
                BEGIN   	 	   
                     Begin 
                             Select Nvl(Max(I_No),0)+1 InTo Ino 
                              From Installment 
                              Where Bill_Ser=:NEW.J_Ser
                                And C_Code=:NEW.AC_CODE_DTL;
                         Exception
                       When Others Then
                           Ino:=1;
                     End;                                         	     
                       ias_installment_ar_pkg.insrt_installment ( P_I_No         => Ino
                                                                ,p_doc_type      =>:NEW.DOC_TYPE                              
                                                                ,p_doc_ser      => :NEW.j_ser        
                                                                ,p_doc_no       => :NEW.j_doc_no                                                                      
                                                                ,p_doc_jv_type  => :NEW.jv_type      
                                                                ,p_doc_date     => V_VCHR_DATE      
                                                                ,p_c_code       => :NEW.AC_CODE_DTL                                
                                                                ,p_cc_code      => :NEW.cc_code      
                                                                ,p_pj_no        => :NEW.pj_no      
                                                                ,p_Actv_no      => :NEW.Actv_no          
                                                                ,p_doc_due_date => :NEW.doc_due_date 
                                                                ,p_amt          => :NEW.DR_AMT        
                                                                ,p_amt_f        => Nvl(:NEW.DR_AMT_F,0)
                                                                ,p_a_cy         => :NEW.a_cy         
                                                                ,p_ac_rate      => Nvl(:NEW.ac_rate,1)     
                                                                ,p_rcrd_no      => :NEW.rcrd_no      
                                                                ,P_Ac_Code_Dtl_Sub  => :NEW.Ac_Code_Dtl_Sub  
                                                                ,P_Doc_Dsc          => :NEW.J_DESC           
                                                                ,p_REF_no       => :NEW.REF_no                                     
                                                                ,p_Lang_no      => 1             
                                                                ,p_brn_no       => :NEW.brn_no       
                                                                ,p_brn_year     => :NEW.brn_year     
                                                                ,p_cmp_no       => :NEW.cmp_no             
                                                                ,p_brn_usr      => :NEW.brn_usr     
                                                                ,P_DOC_SEQ 		  => :NEW.Doc_SEQUENCE
                                                                ,P_A_CODE       => :NEW.A_CODE);
                Exception
                   When Others Then
                    Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
                End ;

           End If ;

         ---------------------------------------------------------------------------------------------------------------  
         IF :NEW.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND :NEW.AC_CODE_DTL Is  Not Null And Nvl(:NEW.CR_AMT,0)>0 Then 
           BEGIN  	      
             Begin 
                 Select Nvl(Max(I_No),0)+1 InTo Ino 
                   From IAS_Installment_Pi 
                  Where Bill_Ser=:NEW.j_Ser
                    And V_Code=:NEW.AC_CODE_DTL;
             Exception
               When Others Then
               Ino:=1;
             End;   
               ias_installment_ap_pkg.insrt_installment ( P_I_No         => Ino													 
                                                        ,p_doc_type     => :NEW.DOC_TYPE                          
                                                        ,p_doc_ser      => :NEW.j_ser        
                                                        ,p_doc_no       => :NEW.j_doc_no                                                                      
                                                        ,p_doc_jv_type  => :NEW.jv_type      
                                                        ,P_Doc_Date     => V_VCHR_DATE      
                                                        ,p_V_code       => :NEW.AC_CODE_DTL                                
                                                        ,p_cc_code      => :NEW.cc_code       
                                                        ,p_pj_no        => :NEW.pj_no      
                                                        ,p_Actv_no      => :NEW.Actv_no          
                                                        ,p_doc_due_date => :NEW.doc_due_date 
                                                        ,p_amt          =>  :NEW.CR_AMT          
                                                        ,p_amt_f        =>  Nvl(:NEW.CR_AMT_F,0)
                                                        ,p_a_cy         => :NEW.a_cy         
                                                        ,p_ac_rate      => Nvl(:NEW.ac_rate,1)      
                                                        ,p_rcrd_no      => :NEW.rcrd_no      
                                                        ,p_REF_no      => :NEW.REF_NO                                   
                                                        ,p_Lang_no      => 1
                                                        ,p_brn_no       => :NEW.brn_no       
                                                        ,p_brn_year     => :NEW.brn_year      
                                                        ,p_cmp_no       => :NEW.cmp_no             
                                                        ,p_brn_usr     =>  :NEW.brn_usr     
                                                        ,P_DOC_SEQ 		=> :NEW.Doc_SEQUENCE
                                                        ,P_A_CODE      => :NEW.A_CODE
                                                        );
            Exception
               When Others Then
                 Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
            End ;
            --------- ---------------------------------------------------------------------------------------------------------------   
         End If ;
     --##--------------------------------------------------------------------------------------------------------##---
         
       --##------------------------------------------------------------------------------------##--

    ElsIf UPDATING Then --(1)
    ------------------------------------------------------------------------
          Begin
             Select J_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
               From MASTER_JOURNAL_V 
              Where  J_Ser=:OLD.J_Ser
                 AND ROWNUM<=1;
          Exception
            When Others Then
            V_Stnd_By:=0;
          End; 
          
          IF :OLD.AC_DTL_TYP=3  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null    Then 
             
                                                   
            If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type     =>NVL(:NEW.DOC_TYPE,:OLD.DOC_TYPE)  
                                                                  ,p_doc_ser      => :OLD.j_ser                                     
                                                                  ,p_c_code       =>NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                                  ,p_rcrd_no     => :OLD.rcrd_no) = 1   
                                                      
                  OR Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type     =>NVL(:NEW.DOC_TYPE,:OLD.DOC_TYPE)  
                                                            ,p_doc_ser      => :OLD.j_ser                                     
                                                            ,p_c_code       => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                            ,p_rcrd_no      => :OLD.rcrd_no) = 1     Then
                       Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);                                               
            End If;                                                    
            If Nvl(NVL(:NEW.DR_AMT,:OLD.DR_AMT),0)>0 Then                                                                               
              BEGIN                                          
                 Begin 
                      Select Nvl(Max(I_No),0)+1 
                        InTo Ino From Installment 
                       Where Bill_Ser=:OLD.J_Ser
                         And C_Code= NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
                 Exception
                   When Others Then
                   Ino:=1;
                 End;                                         	     
    												   
                ias_installment_ar_pkg.insrt_installment ( P_I_No           => Ino                                   
                                                        ,p_doc_type         =>NVL(:NEW.DOC_TYPE,:OLD.DOC_TYPE)                                 
                                                        ,p_doc_ser          => :OLD.j_ser           
                                                        ,p_doc_no           => :OLD.j_doc_no                                                                        
                                                        ,p_doc_jv_type      => NVL(:NEW.jv_type,:OLD.jv_type)         
                                                        ,p_doc_date         => V_VCHR_DATE          
                                                        ,p_c_code           => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                                  
                                                        ,p_cc_code          => NVL(:NEW.CC_CODE,:OLD.CC_CODE)          
                                                        ,p_pj_no            => NVL(:NEW.PJ_NO,:OLD.PJ_NO)            
                                                        ,p_Actv_no          => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)             
                                                        ,p_doc_due_date     => NVL(:NEW.doc_due_date,:OLD.doc_due_date)    
                                                        ,p_amt              => NVL(:NEW.DR_AMT,:OLD.DR_AMT)            
                                                        ,p_amt_f            => NVL(:NEW.DR_AMT_F,:OLD.DR_AMT_F)
                                                        ,p_a_cy             => NVL(:NEW.A_CY,:OLD.A_CY)            
                                                        ,p_ac_rate          => Nvl(NVL(:NEW.AC_RATE,:OLD.AC_RATE) ,1)  
                                                        ,p_rcrd_no          => :OLD.rcrd_no                                        
                                                        ,p_REF_no           => NVL(:NEW.REF_NO,:OLD.REF_no)                                 
                                                        ,P_Ac_Code_Dtl_Sub  => NVL(:NEW.Ac_Code_Dtl_Sub,:OLD.Ac_Code_Dtl_Sub)   
                                                        ,P_Doc_Dsc          => NVL(:NEW.J_DESC,:OLD.J_DESC)           
                                                        ,p_Lang_no          => 1                
                                                        ,p_brn_no           => :OLD.brn_no          
                                                        ,p_brn_year         => :OLD.brn_year        
                                                        ,p_cmp_no           => :OLD.cmp_no          
                                                        ,p_brn_usr          => :OLD.brn_usr          
                                                        ,P_DOC_SEQ 		    => :OLD.Doc_SEQUENCE 
                                                        ,P_A_CODE       => :NEW.A_CODE   );
                Exception
                   When Others Then
                   Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
                End ;
            End If;
         End If ;
    											
        --##--------------------------------------------------------------------------------------------------------##---
            -- Installment Ap
            --and Nvl(:Master_journal_v.STAND_BY,0)=0
           IF :OLD.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null  And Nvl(NVL(:NEW.CR_AMT,:OLD.CR_AMT),0)>0 Then 	  
    											   
                
                 If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  	=>	:OLD.DOC_TYPE
                                                                    ,p_doc_ser   	=> 	:OLD.j_ser                                   
                                                                    ,p_v_code    	=> 	NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                                    ,p_rcrd_no   	=> 	:OLD.rcrd_no) = 1   
                      OR  Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type    =>	:OLD.DOC_TYPE
                                                                 ,p_doc_ser     => 	:OLD.j_ser                                      
                                                                 ,p_v_code      => 	NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                                 ,p_rcrd_no     => 	:OLD.rcrd_no) = 1     Then
                       Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   			                                
                 End If;					                                
    																				                                
             	
               Begin 	   
                 Begin 
                     Select Nvl(Max(I_No),0)+1 
                       InTo Ino
                        From IAS_Installment_Pi 
                      Where Bill_Ser=:OLD.j_Ser
                        And v_Code=NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
                 Exception
                  When Others Then
                   Ino:=1;
                 End;                                         	     
                   ias_installment_ap_pkg.insrt_installment ( P_I_No            => Ino
                                                            ,p_doc_type         => NVL(:NEW.DOC_TYPE,:OLD.DOC_TYPE)                             
                                                            ,p_doc_ser          => :OLD.j_ser        
                                                            ,p_doc_no           => :OLD.j_doc_no                                                                      
                                                            ,p_doc_jv_type      => NVL(:NEW.jv_type,:OLD.jv_type)         
                                                            ,p_doc_date         => V_VCHR_DATE          
                                                            ,p_V_code           => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                                  
                                                            ,p_cc_code          => NVL(:NEW.CC_CODE,:OLD.CC_CODE)          
                                                            ,p_pj_no            => NVL(:NEW.PJ_NO,:OLD.PJ_NO)            
                                                            ,p_Actv_no          => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)    
                                                            ,p_doc_due_date     => NVL(:NEW.doc_due_date,:OLD.doc_due_date)    
                                                            ,p_amt              =>   NVL(:NEW.CR_AMT,:OLD.CR_AMT)            
                                                            ,p_amt_f            =>   NVL(:NEW.CR_AMT_F,:OLD.CR_AMT_F)
                                                            ,p_a_cy             => NVL(:NEW.A_CY,:OLD.A_CY)            
                                                            ,p_ac_rate          => Nvl(NVL(:NEW.AC_RATE,:OLD.AC_RATE) ,1)  
                                                            ,p_rcrd_no          => :OLD.rcrd_no                                        
                                                            ,p_REF_no           => NVL(:NEW.REF_NO,:OLD.REF_no)                                 
                                                            --,P_Ac_Code_Dtl_Sub  => NVL(:NEW.Ac_Code_Dtl_Sub,:OLD.Ac_Code_Dtl_Sub)   
                                                            ,P_Doc_Dsc          => NVL(:NEW.J_DESC,:OLD.J_DESC)    
                                                            ,p_Lang_no          => 1                
                                                            ,p_brn_no           => :OLD.brn_no          
                                                            ,p_brn_year         => :OLD.brn_year        
                                                            ,p_cmp_no           => :OLD.cmp_no          
                                                            ,p_brn_usr          => :OLD.brn_usr    
                                                            ,P_DOC_SEQ 		    => :OLD.Doc_SEQUENCE
                                                            ,P_A_CODE         => :OLD.A_CODE
                                                            );
                Exception
                   When Others Then
                     Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
                End ;
            End If ;
    										
          -----------------------------------------------------------
        
         
        --End If ;
    --##------------------------------------------------------------------------------------##--
    --##------------------------------------------------------------------------------------##--

    ------------------------------------------------------------------------
    ELSIf DELETING Then --(((1)
     
       -- IF :OLD.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null  And Nvl(NVL(:NEW.J_AMT,:OLD.J_AMT),0)<0  Then 	 
       if:OLD.CR_AMT > 0 then  --2  RECEIVED    
        
            If :old.Ac_code_DTL IS NOT NULL AND :old.Ac_DTL_TYP=4   Then
                Begin
                   If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  =>:OLD.DOC_TYPE,
                                                                       p_doc_ser     =>     :old.j_ser,                                      
                                                                       p_v_code      =>     :old.Ac_code_DTL ,
                                                                       p_rcrd_no     =>     :old.rcrd_no) = 1     Then
                       
                        Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
                   End If ;   
                   If Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type  =>:OLD.DOC_TYPE,
                                                              p_doc_ser     =>     :old.j_ser,                                      
                                                              p_v_code      =>     :old.Ac_code_DTL ,
                                                              p_rcrd_no     =>     :old.rcrd_no) = 1     Then
                        
                        Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
                   End If ;                
                Exception
                    When Others Then
                      Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
                End ;
            End If ;
            ---------------------------------------------------------------------------------------
                                                                          
            If :old.Ac_code_DTL IS NOT NULL THEN ---AND :old.Ac_DTL_TYP=4    Then
                Begin
                    If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => :OLD.DOC_TYPE,                    
                                                                          P_Doc_Ser   => :old.j_Ser,    
                                                                          P_Rcrd_No   => :old.rcrd_no,
                                                                          P_Paid_Type => 0                    ) = 1     Then
                      Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   
                   End If ;                                                                         
            Exception When Others Then
                      Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                End ;
            End If ;
            ---------------------------------------------------------------------------------------
            ---------------------------------------------------------------------------------------------------------
            Begin
            Delete From IAS_Installment_PI
            where Doc_Type =:OLD.DOC_TYPE
            and bill_ser = :old.j_ser
            and rcrd_no = :old.rcrd_no
            and i_py=0;
            Exception
            When Others Then
              Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
            End ;     
            -----------------------------------------------------------------------------------------------    
      ELSIF :OLD.DR_AMT > 0 then  --2    PAYMENT
        
            --============================================================================
             --# Installment     
                 If :OLD.AC_DTL_TYP=3 AND :OLD.AC_CODE_DTL Is Not Null  Then
                        Begin
                           If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type  =>:OLD.DOC_TYPE
                                                                                 ,p_doc_ser     =>     :OLD.j_ser                                      
                                                                              ,p_c_code      =>     :OLD.AC_CODE_DTL 
                                                                              ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
                               Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);    
                           End If ;   
                           If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>:OLD.DOC_TYPE
                                                                        ,p_doc_ser     =>     :OLD.j_ser                                     
                                                                     ,p_c_code      =>     :OLD.AC_CODE_DTL 
                                                                     ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
                               Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
                           End If ;                
                        Exception
                             When Others Then
                              Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
                        End ;
               End If ;
               
               If  :OLD.AC_CODE_DTL Is Not Null  Then  --:OLD.AC_DTL_TYP=3 AND
                        Begin
                           If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => :OLD.DOC_TYPE                     
                                                                                ,P_Doc_Ser   => :OLD.j_Ser
                                                                                ,P_Rcrd_No   => :OLD.rcrd_no
                                                                                ,P_Paid_Type => 1                    ) = 1     Then
                         Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1239)||SqlErrm);    
                           End If ;
                        Exception
                             When Others Then
                              Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                        end;            
               End If ;                
               ---------------------------------------------------------------------------------------------------------
                  Begin
                       Delete From Installment
                        where Doc_Type = :OLD.DOC_TYPE
                          and bill_ser = :OLD.j_ser
                          and rcrd_no = :OLD.rcrd_no
                          and i_py=0;
                  Exception
                         When Others Then
                           Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                  End ;     
                -----------------------------------------------------------------------------------------------                  
              
        
      End if;--2()*/
    End If;--(1)
END IF;--(1)
 EXCEPTION WHEN OTHERS THEN
   Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
END GLS_JRNLJRS_DTL_INSTLMNT_TRGR;
/


--
-- GLS_JRNL_DTL_INSTLMNT_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_JRNL_DTL_INSTLMNT_TRGR
      BEFORE DELETE OR INSERT OR UPDATE 
         OF A_CY
			  ,J_AMT
			  ,J_AMT_F
			  ,BILL_NO
			  ,BILL_SER
			  ,I_NO
			ON IAS20261.DETAIL_JOURNAL_V 
			REFERENCING NEW AS NEW OLD AS OLD
			FOR EACH ROW
DECLARE 
			  ------------------------------
			  
			  -- ADDED BY MURAD ALGARRASH
			  -- DATE    19/02/2020
			  
			  ------------------------------
			  V_VCHR_DATE  DATE;
			  V_Stnd_By    number(1);
			  Ino          Number(38):=1;  
        V_Cnt        number:=0;
			BEGIN
			
			  
			
			 If INSERTING  Then --(1)
			   ---------Start JURNAL ---------------------------------------------------------------------------------------------------------------  
			      Begin
			         Select J_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
			           From MASTER_JOURNAL_V 
			          Where  J_Ser=:NEW.j_ser
			             AND ROWNUM<=1;
			      Exception
			        When Others Then
			        V_Stnd_By:=0;
			      End; 
			                  ----------------------------------------------------------- 
			                                
			          --##-------------------------------------------------------------------------------------------------------------------##--
			       If :NEW.AC_DTL_TYP=3  AND nvl(V_Stnd_By,0)=0 AND :NEW.AC_CODE_DTL Is  Not Null And Nvl(:NEW.J_Amt,0)>0  Then       
			             BEGIN               
			                 Begin 
			                         Select Nvl(Max(I_No),0)+1 InTo Ino 
			                          From Installment 
			                          Where Bill_Ser=:NEW.J_Ser
			                            And C_Code=:NEW.AC_CODE_DTL;
			                     Exception
			                   When Others Then
			                       Ino:=1;
			                 End;                                                  
			                   ias_installment_ar_pkg.insrt_installment ( P_I_No         => Ino
			                                                            ,p_doc_type      => 1                              
			                                                            ,p_doc_ser      => :NEW.j_ser        
			                                                            ,p_doc_no       => :NEW.j_doc_no                                                                      
			                                                            ,p_doc_jv_type  => :NEW.jv_type      
			                                                            ,p_doc_date     => V_VCHR_DATE      
			                                                            ,p_c_code       => :NEW.AC_CODE_DTL                                
			                                                            ,p_cc_code      => :NEW.cc_code      
			                                                            ,p_pj_no        => :NEW.pj_no      
			                                                            ,p_Actv_no      => :NEW.Actv_no          
			                                                            ,p_doc_due_date => :NEW.doc_due_date 
			                                                            ,p_amt          => :NEW.J_Amt        
			                                                            ,p_amt_f        => Nvl(:NEW.j_amt_f,0)
			                                                            ,p_a_cy         => :NEW.a_cy         
			                                                            ,p_ac_rate      => Nvl(:NEW.ac_rate,1)     
			                                                            ,p_rcrd_no      => :NEW.rcrd_no      
			                                                            ,P_Ac_Code_Dtl_Sub  => :NEW.Ac_Code_Dtl_Sub  
			                                                            ,P_Doc_Dsc          => :NEW.J_DESC           
			                                                            ,p_REF_no       => :NEW.REF_no                                     
			                                                            ,p_Lang_no      => 1             
			                                                            ,p_brn_no       => :NEW.brn_no       
			                                                            ,p_brn_year     => :NEW.brn_year     
			                                                            ,p_cmp_no       => :NEW.cmp_no             
			                                                            ,p_brn_usr      => :NEW.brn_usr     
			                                                            ,P_DOC_SEQ      =>:NEW.Doc_SEQUENCE
			                                                            ,P_A_CODE       => :NEW.A_CODE);
			            Exception
			               When Others Then
			                Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
			            End ;
			
			       End If ;
			
			     ---------------------------------------------------------------------------------------------------------------  
			     IF :NEW.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND :NEW.AC_CODE_DTL Is  Not Null And Nvl(:NEW.J_Amt,0)<0  Then 
			       BEGIN            
			         Begin 
			              Select Nvl(Max(I_No),0)+1 InTo Ino 
			                From IAS_Installment_Pi 
			               Where Bill_Ser=:NEW.j_Ser
			                 And V_Code=:NEW.AC_CODE_DTL;
			          Exception
			            When Others Then
			            Ino:=1;
			          End;   
			           ias_installment_ap_pkg.insrt_installment ( P_I_No         => Ino                                                     
			                                                    ,p_doc_type     => 1                            
