			                                                    ,p_doc_no       => :NEW.j_doc_no                                                                      
			                                                    ,p_doc_jv_type  => :NEW.jv_type      
			                                                    ,P_Doc_Date     => V_VCHR_DATE      
			                                                    ,p_V_code       => :NEW.AC_CODE_DTL                                
			                                                    ,p_cc_code      => :NEW.cc_code       
			                                                    ,p_pj_no        => :NEW.pj_no      
			                                                    ,p_Actv_no      => :NEW.Actv_no          
			                                                    ,p_doc_due_date => :NEW.doc_due_date 
			                                                    ,p_amt          => -1*:NEW.J_Amt          
			                                                    ,p_amt_f        => -1*Nvl(:NEW.J_Amt_F,0)
			                                                    ,p_a_cy         => :NEW.a_cy         
			                                                    ,p_ac_rate      => Nvl(:NEW.ac_rate,1)      
			                                                    ,p_rcrd_no      => :NEW.rcrd_no      
			                                                    ,p_REF_no      => :NEW.REF_NO                                   
			                                                    ,p_Lang_no      => 1
			                                                    ,p_brn_no       => :NEW.brn_no       
			                                                    ,p_brn_year     => :NEW.brn_year      
			                                                    ,p_cmp_no       => :NEW.cmp_no             
			                                                    ,p_brn_usr     =>  :NEW.brn_usr     
			                                                    ,P_DOC_SEQ         => :NEW.Doc_SEQUENCE
			                                                    ,P_A_CODE       => :NEW.A_CODE);
			        Exception
			           When Others Then
			             Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
			        End ;
			        --------- ---------------------------------------------------------------------------------------------------------------   
			     End If ;
			 --##--------------------------------------------------------------------------------------------------------##---
			     
			   --##------------------------------------------------------------------------------------##--
			
			ElsIf UPDATING Then --(1)
			------------------------------------------------------------------------
			      Begin
			         Select J_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
			           From MASTER_JOURNAL_V 
			          Where  J_Ser=:OLD.J_Ser
			             AND ROWNUM<=1;
			      Exception
			        When Others Then
