			      End; 
			      
			      IF :OLD.AC_DTL_TYP=3  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null    Then 
			         
			                                               
			        If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type     =>1
			                                                              ,p_doc_ser      => :OLD.j_ser                                     
			                                                              ,p_c_code       =>NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
			                                                              ,p_rcrd_no     => :OLD.rcrd_no) = 1   
			                                                  
			              OR Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type     =>1
			                                                        ,p_doc_ser      => :OLD.j_ser                                     
			                                                        ,p_c_code       => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
			                                                        ,p_rcrd_no      => :OLD.rcrd_no) = 1     Then
			                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);                                               
			        End If;                                                    
			        
                    If Nvl(NVL(:NEW.J_Amt,:OLD.J_Amt),0)>0 Then                                                                               
                          BEGIN                                          
                             Begin 
                                  Select Nvl(Max(I_No),0)+1 
                                    InTo Ino From Installment 
                                   Where Bill_Ser=:OLD.J_Ser
                                     And C_Code= NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
                             Exception
                               When Others Then
                               Ino:=1;
                             End;                                                  
    			                                                   
                            ias_installment_ar_pkg.insrt_installment ( P_I_No           => Ino                                   
                                                                    ,p_doc_type         => 1                                 
                                                                    ,p_doc_ser          => :OLD.j_ser           
                                                                    ,p_doc_no           => :OLD.j_doc_no                                                                        
                                                                    ,p_doc_jv_type      => NVL(:NEW.jv_type,:OLD.jv_type)         
                                                                    ,p_doc_date         => V_VCHR_DATE          
                                                                    ,p_c_code           => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                                  
                                                                    ,p_cc_code          => NVL(:NEW.CC_CODE,:OLD.CC_CODE)          
                                                                    ,p_pj_no            => NVL(:NEW.PJ_NO,:OLD.PJ_NO)            
                                                                    ,p_Actv_no          => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)             
                                                                    ,p_doc_due_date     => NVL(:NEW.doc_due_date,:OLD.doc_due_date)    
                                                                    ,p_amt              => NVL(:NEW.J_AMT,:OLD.J_AMT)            
                                                                    ,p_amt_f            => NVL(:NEW.J_AMT_F,:OLD.J_AMT_F)
                                                                    ,p_a_cy             => NVL(:NEW.A_CY,:OLD.A_CY)            
                                                                    ,p_ac_rate          => Nvl(NVL(:NEW.AC_RATE,:OLD.AC_RATE) ,1)  
                                                                    ,p_rcrd_no          => :OLD.rcrd_no                                        
                                                                    ,p_REF_no           => NVL(:NEW.REF_NO,:OLD.REF_no)                                 
                                                                    ,P_Ac_Code_Dtl_Sub  => NVL(:NEW.Ac_Code_Dtl_Sub,:OLD.Ac_Code_Dtl_Sub)   
                                                                    ,P_Doc_Dsc          => NVL(:NEW.J_DESC,:OLD.J_DESC)           
                                                                    ,p_Lang_no          => 1                
                                                                    ,p_brn_no           => :OLD.brn_no          
                                                                    ,p_brn_year         => :OLD.brn_year        
                                                                    ,p_cmp_no           => :OLD.cmp_no          
                                                                    ,p_brn_usr          => :OLD.brn_usr          
                                                                    ,P_DOC_SEQ             => :OLD.Doc_SEQUENCE
                                                                    ,P_A_CODE       => :OLD.A_CODE    );
                            Exception
                               When Others Then
                               Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
                            End ;
                    Else 
                      V_Cnt := Ias_Gen_Pkg.Get_Cnt('Select 1 From Installment 
                                       Where nvl(i_py,0) = 0
                                         And Bill_Ser = '||:OLD.j_ser||'
                                         And C_Code   = '''||NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)||'''
                                         And Rcrd_No  = '||:OLD.rcrd_no||'                                     
                                         And RowNum<=1');                           
                      --------------------------------------------------------------------------------
                          If Nvl(V_Cnt,0)>0 Then
                             Begin    
                               Execute Immediate' Delete From Installment 
                                                    Where nvl(i_py,''0'') = 0
                                                      And Bill_Ser = '||:OLD.j_ser||'
                                                      And C_Code   = '''||NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)||'''
                                                      And Rcrd_No  = '||:OLD.rcrd_no;      
                             Exception When others then
                              Raise_application_error(-20561,'Error When Delete Document From Installment '||SqlErrm) ;
                             End;     
                          End If;       
			        End If;
			     End If ;
			                                            
			    --##--------------------------------------------------------------------------------------------------------##---
			        -- Installment Ap
			        --and Nvl(:Master_journal_v.STAND_BY,0)=0
			   IF :OLD.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null  Then
                     
                        
			                                               
			            
			             If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type      =>    1
			                                                                ,p_doc_ser       =>     :OLD.j_ser                                   
			                                                                ,p_v_code        =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
			                                                                ,p_rcrd_no       =>     :OLD.rcrd_no) = 1   
			                  OR  Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type    =>    1
			                                                             ,p_doc_ser     =>     :OLD.j_ser                                      
			                                                             ,p_v_code      =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
			                                                             ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
			                   Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);                                               
			             End If;                                                    
			                                                                                                                
			       IF Nvl(NVL(:NEW.J_AMT,:OLD.J_AMT),0)<0  Then       
