			             Begin 
			                 Select Nvl(Max(I_No),0)+1 
			                   InTo Ino
			                    From IAS_Installment_Pi 
			                  Where Bill_Ser=:OLD.j_Ser
			                    And v_Code=NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
			             Exception
			              When Others Then
			               Ino:=1;
			             End;                                                  
			               ias_installment_ap_pkg.insrt_installment ( P_I_No            => Ino
			                                                        ,p_doc_type         => 1                              
			                                                        ,p_doc_ser          => :OLD.j_ser        
			                                                        ,p_doc_no           => :OLD.j_doc_no                                                                      
			                                                        ,p_doc_jv_type      => NVL(:NEW.jv_type,:OLD.jv_type)         
			                                                        ,p_doc_date         => V_VCHR_DATE          
			                                                        ,p_V_code           => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                                  
			                                                        ,p_cc_code          => NVL(:NEW.CC_CODE,:OLD.CC_CODE)          
			                                                        ,p_pj_no            => NVL(:NEW.PJ_NO,:OLD.PJ_NO)            
			                                                        ,p_Actv_no          => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)    
			                                                        ,p_doc_due_date     => NVL(:NEW.doc_due_date,:OLD.doc_due_date)    
			                                                        ,p_amt              => -1* NVL(:NEW.J_AMT,:OLD.J_AMT)            
			                                                        ,p_amt_f            => -1* NVL(:NEW.J_AMT_F,:OLD.J_AMT_F)
			                                                        ,p_a_cy             => NVL(:NEW.A_CY,:OLD.A_CY)            
			                                                        ,p_ac_rate          => Nvl(NVL(:NEW.AC_RATE,:OLD.AC_RATE) ,1)  
			                                                        ,p_rcrd_no          => :OLD.rcrd_no                                        
			                                                        ,p_REF_no           => NVL(:NEW.REF_NO,:OLD.REF_no)                                 
			                                                        --,P_Ac_Code_Dtl_Sub  => NVL(:NEW.Ac_Code_Dtl_Sub,:OLD.Ac_Code_Dtl_Sub)   
			                                                        ,P_Doc_Dsc          => NVL(:NEW.J_DESC,:OLD.J_DESC)    
			                                                        ,p_Lang_no          => 1                
			                                                        ,p_brn_no           => :OLD.brn_no          
			                                                        ,p_brn_year         => :OLD.brn_year        
			                                                        ,p_cmp_no           => :OLD.cmp_no          
			                                                        ,p_brn_usr          => :OLD.brn_usr    
			                                                        ,P_DOC_SEQ             => :OLD.Doc_SEQUENCE
			                                                        ,P_A_CODE      		 => :OLD.A_CODE);
			            Exception
			               When Others Then
			                 Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
			            End ;
			       Else 
                      V_Cnt := Ias_Gen_Pkg.Get_Cnt('Select 1 From ias_Installment_pi 
                                       Where nvl(i_py,0) = 0
                                         And Bill_Ser = '||:OLD.j_ser||'
                                         And V_Code   = '''||NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)||'''
                                         And Rcrd_No  = '||:OLD.rcrd_no||'                                     
                                         And RowNum<=1');                           
                      --------------------------------------------------------------------------------
                          If Nvl(V_Cnt,0)>0 Then
                             Begin    
                               Execute Immediate' Delete From ias_Installment_pi 
                                                    Where nvl(i_py,''0'') = 0
                                                      And Bill_Ser = '||:OLD.j_ser||'
                                                      And V_Code   = '''||NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)||'''
                                                      And Rcrd_No  = '||:OLD.rcrd_no;      
                             Exception When others then
                              Raise_application_error(-20572,'Error When Delete Document From ias_Installment_pi '||SqlErrm) ;
                             End;     
                          End If;  
                   End If ;
			                                        
			      -----------------------------------------------------------
			     
			   End If ;
			--##------------------------------------------------------------------------------------##--
			--##------------------------------------------------------------------------------------##--
			
			------------------------------------------------------------------------
			ELSIf DELETING Then --(((1)
			 
			   -- IF :OLD.AC_DTL_TYP=4  AND nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is  Not Null  And Nvl(NVL(:NEW.J_AMT,:OLD.J_AMT),0)<0  Then      
			   if:OLD.J_AMT < 0 then  --2  RECEIVED    
			    
			        If :old.Ac_code_DTL IS NOT NULL AND :old.Ac_DTL_TYP=4   Then
			            Begin
			               If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  =>1,
			                                                                   p_doc_ser     =>     :old.j_ser,                                      
			                                                                   p_v_code      =>     :old.Ac_code_DTL ,
			                                                                   p_rcrd_no     =>     :old.rcrd_no) = 1     Then
			                   
			                    Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
			               End If ;   
			               If Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type  =>1,
			                                                          p_doc_ser     =>     :old.j_ser,                                      
			                                                          p_v_code      =>     :old.Ac_code_DTL ,
			                                                          p_rcrd_no     =>     :old.rcrd_no) = 1     Then
			                    
			                    Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
			               End If ;                
			            Exception
			                When Others Then
			                  Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
			            End ;
			        End If ;
			        ---------------------------------------------------------------------------------------
			                                                                      
			        If :old.Ac_code_DTL IS NOT NULL THEN ---AND :old.Ac_DTL_TYP=4    Then
			            Begin
			                If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 1,                    
			                                                                      P_Doc_Ser   => :old.j_Ser,    
			                                                                      P_Rcrd_No   => :old.rcrd_no,
			                                                                      P_Paid_Type => 0                    ) = 1     Then
			                  Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   
			               End If ;                                                                         
			        Exception When Others Then
			                  Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
			            End ;
			        End If ;
			        ---------------------------------------------------------------------------------------
			        ---------------------------------------------------------------------------------------------------------
			        Begin
			        Delete From IAS_Installment_PI
			        where Doc_Type = 1
			        and bill_ser = :old.j_ser
			        and rcrd_no = :old.rcrd_no
			        and i_py=0;
			        Exception
			        When Others Then
			          Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
			        End ;     
			        -----------------------------------------------------------------------------------------------    
			  ELSIF :OLD.J_AMT > 0 then  --2    PAYMENT
			    
			        --============================================================================
			         --# Installment     
			             If :OLD.AC_DTL_TYP=3 AND :OLD.AC_CODE_DTL Is Not Null  Then
			                    Begin
			                       If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type  =>1
			                                                                             ,p_doc_ser     =>     :OLD.j_ser                                      
			                                                                          ,p_c_code      =>     :OLD.AC_CODE_DTL 
			                                                                          ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
			                           Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);    
			                       End If ;   
			                       If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>1
			                                                                    ,p_doc_ser     =>     :OLD.j_ser                                     
			                                                                 ,p_c_code      =>     :OLD.AC_CODE_DTL 
			                                                                 ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
			                           Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
			                       End If ;                
			                    Exception
			                         When Others Then
			                          Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
			                    End ;
			           End If ;
			           
			           If  :OLD.AC_CODE_DTL Is Not Null  Then  --:OLD.AC_DTL_TYP=3 AND
			                    Begin
			                       If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 1                     
			                                                                            ,P_Doc_Ser   => :OLD.j_Ser
			                                                                            ,P_Rcrd_No   => :OLD.rcrd_no
			                                                                            ,P_Paid_Type => 1                    ) = 1     Then
			                     Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1239)||SqlErrm);    
			                       End If ;
			                    Exception
			                         When Others Then
			                          Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
			                    end;            
			           End If ;                
			           ---------------------------------------------------------------------------------------------------------
			              Begin
			                   Delete From Installment
			                    where Doc_Type = 1
			                      and bill_ser = :OLD.j_ser
			                      and rcrd_no = :OLD.rcrd_no
			                      and i_py=0;
			              Exception
			                     When Others Then
			                       Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
			              End ;     
			            -----------------------------------------------------------------------------------------------                  
			          
			    
			  End if;--2()*/
			End If;--(1)
			
			 EXCEPTION WHEN OTHERS THEN
			   Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
			END GLS_JRNL_DTL_INSTLMNT_TRGR;
/


--
-- GLS_VCHR_CHQTRCE_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_VCHR_ChqTrce_TRGR
    AFTER INSERT OR UPDATE OR DELETE
   OF 
     A_CODE 
    ,AC_DTL_TYP 
    ,AC_CODE_DTL       
    ,A_CODE_END
    ,AC_CODE_DTL_END         
    ,AC_DTL_TYP_END     
    ,A_CY
    ,AC_AMT
    ,AC_AMTF
    ,CHEQUE_NO 
    ,VALUE_DATE
    ,CHEQUE_VALUED 
    ,ENDRSMNT 
    ,Endrsmnt_date  
ON IAS20261.VOUCHER_DETAIL 
 REFERENCING NEW AS NEW OLD AS OLD
                                    FOR EACH ROW
DECLARE 
  -- ADDED BY MURAD ALGARRASH
  -- DATE    15/06/2020
  
  V_VCHR_DATE DATE;
  V_Stnd_By    number(1);
  V_CHEQ_TYPE  Number(1); 
  V_CNT NUMBER:=0;
  V_AUD_TYPE  NUMBER(1);
  
BEGIN

            IF INSERTING THEN   
                V_AUD_TYPE:=1;
            ELSIF   UPDATING THEN 
                V_AUD_TYPE :=2;
             ELSIF DELETING THEN
                V_AUD_TYPE :=3;
             END IF;
              --##--------------------------------------------------------------------------------------------------------##---
           Begin
             Select VOUCHER_DATE ,Stand_By ,CHEQ_TYPE InTo V_VCHR_DATE ,V_Stnd_By,V_CHEQ_TYPE
               From VOUCHERS 
              Where  V_Ser=:NEW.v_Ser
                AND ROWNUM<=1;
           Exception
                When Others Then
                V_Stnd_By:=0;
           End; 
       
If nvl(V_Stnd_By,0)=0 and :NEW.v_Ser IS NOT NULL  AND :NEW.voucher_pay_type = 2 and :NEW.CHEQUE_NO is not null  Then    ---1
           --##--------------------------------------------------------------------------------------------------------##---

          If INSERTING  OR UPDATING Then --(2)
            
         --##--------------------------------------------------------------------------------------------------------##---
         
          Begin  
                  Select 1  INTO V_CNT   
                    From IAS_CHEQ_TRACE 
                   where v_ser = :NEW.v_ser
                     and voucher_type = :NEW.voucher_type 
                     and A_CODE     = :NEW.A_CODE
                     and AC_DTL_TYP     = :NEW.AC_DTL_TYP
                     and NVL(AC_CODE_DTL,'0')     = NVL(:NEW.AC_CODE_DTL,'0')
                     and NVL(A_CODE_END,'0')     = NVL(:NEW.A_CODE_END,'0')
                     and NVL(AC_CODE_DTL_END,'0')     = NVL(:NEW.AC_CODE_DTL_END,'0')
                     and A_CY     = :NEW.A_CY
                     and AC_AMT     = :NEW.AC_AMT
                     and AC_AMTF     = :NEW.AC_AMTF
                     and CHEQUE_NO  = :NEW.CHEQUE_NO
                     and nvl(cheque_valued,0)    = nvl(:NEW.cheque_valued,0)
                     and nvl(ENDRSMNT,0)    = nvl(:NEW.ENDRSMNT,0)
                     and value_date   = TO_CHAR(:NEW.value_date,'DD/MM/RRRR')
                     and Endrsmnt_date   = TO_CHAR(:NEW.Endrsmnt_date,'DD/MM/RRRR')
                     and RowNum<=1;
     
   
          
           Exception
               When no_data_found Then
                                   
                        INSERT INTO IAS_CHEQ_TRACE (
                                                AUD_TYPE ,
                                                VOUCHER_TYPE, 
                                                VOUCHER_PAY_TYPE, 
                                                VOUCHER_NO, 
                                                CASH_NO, 
                                                V_SER, 
                                                A_CODE,
                                                AC_CODE_DTL, 
                                                AC_DTL_TYP, 
                                                A_CY, 
                                                AC_DESC, 
                                                RETURN_RES, 
                                                AC_AMT, 
                                                AC_AMTF, 
                                                CC_CODE, 
                                                CHEQ_TYPE,
                                                CHEQUE_NO, 
                                                VALUE_DATE, 
                                                CHEQUE_POST, 
                                                CHEQUE_VALUED, 
                                                NOTE_NO, 
                                                BANK_NO, 
                                                REF_NO, 
                                                RCRD_NO, 
                                                ENDRSMNT, 
                                                Endrsmnt_date,
                                                A_CODE_END, 
                                                AC_CODE_DTL_END, 
                                                AC_DTL_TYP_END, 
                                                DOC_SEQUENCE,
                                                POST_U_ID,
                                                POST_DATE,
                                                UNPOST_U_ID,
                                                UNPOST_DATE,
                                                EXTERNAL_POST, 
                                                AUD_U_ID, 
                                                AUD_DATE, 
                                                BRN_NO, 
                                                BRN_YEAR, 
                                                Cmp_No    ,
                                                Brn_Usr  )        
                                              VALUES( V_AUD_TYPE
                                                   ,:NEW.VOUCHER_TYPE
                                                   ,:NEW.VOUCHER_PAY_TYPE
                                                   ,:NEW.VOUCHER_NO
                                                   ,:NEW.CASH_NO
                                                   ,:NEW.V_SER
                                                   ,:NEW.A_CODE
                                                   ,:NEW.AC_CODE_DTL
                                                   ,:NEW.AC_DTL_TYP
                                                   ,:NEW.A_CY 
                                                   ,:NEW.AC_DESC 
                                                   ,:NEW.RETURN_RES 
                                                   ,:NEW.AC_AMT 
                                                   ,:NEW.AC_AMTF 
                                                   ,:NEW.CC_CODE 
                                                   ,V_CHEQ_TYPE
                                                   ,:NEW.CHEQUE_NO 
                                                   ,:NEW.VALUE_DATE
                                                   ,:NEW.CHEQUE_POST
                                                   ,:NEW.CHEQUE_VALUED
                                                   ,:NEW.NOTE_NO
                                                   ,:NEW.BANK_NO
                                                   ,:NEW.REF_NO 
                                                   ,:NEW.RCRD_NO
                                                   ,:NEW.ENDRSMNT 
                                                   ,:NEW.Endrsmnt_date
                                                   ,:NEW.A_CODE_END
                                                   ,:NEW.AC_CODE_DTL_END 
                                                   ,:NEW.AC_DTL_TYP_END  
                                                   ,:NEW.DOC_SEQUENCE
                                                   ,:NEW.POST_U_ID
                                                   ,:NEW.POST_DATE
                                                   ,:NEW.UNPOST_U_ID
                                                   ,:NEW.UNPOST_DATE
                                                   ,:NEW.EXTERNAL_POST
                                                   ,:NEW.AD_U_ID
                                                   ,ias_gen_pkg.get_curdate  
                                                   ,:NEW.BRN_NO 
                                                   ,:NEW.BRN_YEAR
                                                   ,:NEW.CMP_NO
                                                   ,:NEW.BRN_USR   
                                                   );
                                               
                      When Others Then
                       Null;
                End;
           --##------------------------------------------------------------------------------------##--

     --   ElsIf UPDATING Then --(2)
        ------------------------------------------------------------------------
         -- NULL;
        ------------------------------------------------------------------------
        ELSIf DELETING Then --(((2)
         ------------------------------------------------------------------------
               Begin
                Select 1  INTO V_CNT   
                    From IAS_CHEQ_TRACE 
                   where v_ser = :OLD.v_ser
                     and voucher_type = :OLD.voucher_type 
                     and A_CODE     = :OLD.A_CODE
                     and AC_DTL_TYP     = :OLD.AC_DTL_TYP
                     and NVL(AC_CODE_DTL,'0')     = NVL(:OLD.AC_CODE_DTL,'0')
                     and NVL(A_CODE_END,'0')     = NVL(:OLD.A_CODE_END,'0')
                     and NVL(AC_CODE_DTL_END,'0')     = NVL(:OLD.AC_CODE_DTL_END,'0')
                     and A_CY     = :OLD.A_CY
                     and AC_AMT     = :OLD.AC_AMT
                     and AC_AMTF     = :OLD.AC_AMTF
                     and CHEQUE_NO  = :OLD.CHEQUE_NO
                     and nvl(cheque_valued,0)    = nvl(:OLD.cheque_valued,0)
                     and nvl(ENDRSMNT,0)    = nvl(:OLD.ENDRSMNT,0)
                     and value_date   = TO_CHAR(:OLD.value_date,'DD/MM/RRRR')
                     and Endrsmnt_date   = TO_CHAR(:OLD.Endrsmnt_date,'DD/MM/RRRR')
                     and RowNum<=1;
         
             Exception
               When no_data_found Then
                                   
                        INSERT INTO IAS_CHEQ_TRACE (
                                                AUD_TYPE ,
                                                VOUCHER_TYPE, 
                                                VOUCHER_PAY_TYPE, 
                                                VOUCHER_NO, 
                                                CASH_NO, 
                                                V_SER, 
                                                A_CODE, 
                                                AC_CODE_DTL,
                                                AC_DTL_TYP,
                                                A_CY, 
                                                AC_DESC, 
                                                RETURN_RES, 
                                                AC_AMT, 
                                                AC_AMTF, 
                                                CC_CODE, 
                                                CHEQ_TYPE,
                                                CHEQUE_NO, 
                                                VALUE_DATE, 
                                                CHEQUE_POST, 
                                                CHEQUE_VALUED, 
                                                NOTE_NO, 
                                                BANK_NO, 
                                                REF_NO, 
                                                RCRD_NO, 
                                                ENDRSMNT
                                               ,Endrsmnt_date
                                               ,A_CODE_END, 
                                                AC_CODE_DTL_END, 
                                                AC_DTL_TYP_END,  
                                                DOC_SEQUENCE,
                                                POST_U_ID,
                                                POST_DATE,
                                                UNPOST_U_ID,
                                                UNPOST_DATE,
                                                EXTERNAL_POST, 
                                                AUD_U_ID, 
                                                AUD_DATE, 
                                                BRN_NO, 
                                                BRN_YEAR
                                               ,Cmp_No          
                                               ,Brn_Usr
                                                 )            
                                              VALUES( V_AUD_TYPE
                                                   ,:OLD.VOUCHER_TYPE
                                                   ,:OLD.VOUCHER_PAY_TYPE
                                                   ,:OLD.VOUCHER_NO
                                                   ,:OLD.CASH_NO
                                                   ,:OLD.V_SER
                                                   ,:OLD.A_CODE
                                                   ,:OLD.AC_CODE_DTL
                                                   ,:OLD.AC_DTL_TYP
                                                   ,:OLD.A_CY 
                                                   ,:OLD.AC_DESC 
                                                   ,:OLD.RETURN_RES 
                                                   ,:OLD.AC_AMT 
                                                   ,:OLD.AC_AMTF 
                                                   ,:OLD.CC_CODE 
                                                   ,V_CHEQ_TYPE
                                                   ,:OLD.CHEQUE_NO 
                                                   ,:OLD.VALUE_DATE
                                                   ,:OLD.CHEQUE_POST
                                                   ,:OLD.CHEQUE_VALUED
                                                   ,:OLD.NOTE_NO
                                                   ,:OLD.BANK_NO
                                                   ,:OLD.REF_NO 
                                                   ,:OLD.RCRD_NO
                                                   ,:OLD.ENDRSMNT 
                                                   ,:OLD.Endrsmnt_date
                                                   ,:OLD.A_CODE_END
                                                   ,:OLD.AC_CODE_DTL_END 
                                                   ,:OLD.AC_DTL_TYP_END  
                                                   ,:OLD.DOC_SEQUENCE
                                                   ,:OLD.POST_U_ID
                                                   ,:OLD.POST_DATE
                                                   ,:OLD.UNPOST_U_ID
                                                   ,:OLD.UNPOST_DATE
                                                   ,:OLD.EXTERNAL_POST
                                                   ,:OLD.AD_U_ID
                                                   ,ias_gen_pkg.get_curdate  
                                                   ,:OLD.BRN_NO 
                                                   ,:OLD.BRN_YEAR
                                                   ,:OLD.CMP_NO
                                                   ,:OLD.BRN_USR   
                                                   );
                                               
                  When Others Then
                       Null;
             END;          
        ------------------------------------------------------------------------ 
        
        End If;--(2)
END IF;--(1)
 EXCEPTION WHEN OTHERS THEN
   Raise_Application_Error(-20303,' Error When IAS_CHEQ_TRACE . '||SqlErrm);
END GLS_VCHR_ChqTrce_TRGR;
/


--
-- GLS_VCHR_DTL_INSTLMNT_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_VCHR_DTL_INSTLMNT_TRGR
		BEFORE DELETE OR INSERT OR UPDATE
		OF A_CY
		  ,AC_AMT
		  ,AC_AMTF
		  ,BILL_NO
		  ,BILL_SER
		  ,I_NO
		  ,CHEQUE_VALUED
		ON IAS20261.VOUCHER_DETAIL 
		REFERENCING NEW AS NEW OLD AS OLD
		FOR EACH ROW
DECLARE 
		 ----------------------------------               
     -- ALTERED by  MURAD ALGARRASH
     -- Date      08/06/2023          
     ----------------------------------
      V_POST_CST_TYP    number(1);
      V_POST_VNDR_TYP   number(1);
      V_CHEQ_TYP        number(1);  --3 
      V_VCHR_DATE DATE;
      V_Stnd_By    number(1);
      Ino  Number(38):=1;  
BEGIN


      Begin
         Select V.VOUCHER_DATE ,V.Stand_By,V.CHEQ_TYPE,P.POST_CHEQUE_TYPE,P.POST_CHEQ_TYPE_VNDR 
           InTo V_VCHR_DATE ,V_Stnd_By,V_CHEQ_TYP,V_POST_CST_TYP ,V_POST_VNDR_TYP
           From VOUCHERS V,IAS_PARA_GL P
          Where  V_Ser=:NEW.v_Ser
             AND ROWNUM<=1;
      Exception
        When Others Then
        V_POST_CST_TYP:=1;
        V_POST_VNDR_TYP:=1;
        V_CHEQ_TYP:=0;
        V_Stnd_By:=0;
      End; 

If INSERTING  Then --(1)
   ---------Start Received  voucher----------------------------------------------------------------------------------------------------------------  
   If :NEW.VOUCHER_TYPE = 1 and nvl(V_Stnd_By,0)=0 AND :NEW.AC_DTL_TYP=4 AND :NEW.AC_CODE_DTL Is Not Null   AND abs(nvl(:NEW.AC_AMT,0)) >0   Then --(3)
        ------------------------------------------------------------------------                                                  
        Begin        
            --------------------------------------------------
             Begin
                 Select Nvl(Max(I_No),0)+1 InTo Ino 
                  From IAS_Installment_Pi 
                   Where Bill_Ser=:NEW.v_Ser
                     And v_Code=:NEW.AC_CODE_DTL;
              Exception
                When Others Then
                Ino:=1;
              End;   
             -----------------------------------------------------------
               ias_installment_ap_pkg.insrt_installment ( P_I_No       => Ino,
                                                        p_doc_type     => 2,
                                                        p_doc_ser      => :NEW.V_ser ,
                                                        p_doc_no       => :NEW.Voucher_no     ,                                                                 
                                                        p_doc_jv_type  => :NEW.Voucher_pay_type      ,
                                                        p_doc_date     => V_VCHR_DATE,
                                                        p_v_code       => :NEW.AC_CODE_DTL ,                         
                                                        p_cc_code      => :NEW.cc_code  ,                         
                                                        p_pj_no        => :NEW.pj_no  ,
                                                        p_Actv_no      => :NEW.Actv_no         , 
                                                        p_doc_due_date => nvl(:NEW.value_date,V_VCHR_DATE)  ,
                                                        p_amt          => (-1*:NEW.AC_AMT) + Nvl(:NEW.OTR_AMT_L,0)       ,  
                                                        p_amt_f        => (-1*Nvl(:NEW.AC_AMTF,0))+ Nvl(:NEW.OTR_AMT_F,0),
                                                        p_a_cy         => :NEW.a_cy         ,
                                                        p_ac_rate      => Nvl(:NEW.ex_rate,1)      ,
                                                        p_rcrd_no      => :NEW.rcrd_no      ,                              
                                                        p_REF_no       => :NEW.REF_no      ,    
                                                        p_Lang_no      => 1           ,
                                                        p_brn_no       => :NEW.brn_no       ,
                                                        p_brn_year     => :NEW.brn_year    ,
                                                        p_cmp_no       => :NEW.cmp_no             ,
                                                        p_brn_usr      => :NEW.brn_usr      ,
                                                        P_DOC_SEQ      => :NEW.Doc_SEQUENCE,
                                                        P_A_CODE       => :NEW.A_CODE
                                                       );
        Exception
           When Others Then
              
            Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
        End ;
       ---------End Received  voucher---------------------------------------------------------------------------------------------------------------- 
   ----------Start Payment  voucher----------------------------------------------------------------------------------------------------------------     
   ElsIf :NEW.VOUCHER_TYPE = 2 and nvl(V_Stnd_By,0)=0 AND :NEW.AC_DTL_TYP=3 AND :NEW.AC_CODE_DTL Is Not Null   AND abs(nvl(:NEW.AC_AMT,0))+Nvl(:NEW.otr_amt_l,0) >0   Then --(3)
   --------------------------------------------------------------------------##-- 
        --------------------------------------------------
         Begin        
                --------------------------------------------------
                Begin 
                 Select Nvl(Max(I_No),0)+1 InTo Ino 
                   From Installment 
                  Where Bill_Ser=:NEW.v_Ser
                    And C_Code=:NEW.ac_code_dtl;
                Exception
                When Others Then
                Ino:=1;
                End;    
               --------------------------------------------------
               
             
               ias_installment_ar_pkg.insrt_installment ( P_I_No         => Ino                                         
                                                         ,p_doc_type     => 3                            
                                                         ,p_doc_ser      => :NEW.v_ser        
                                                         ,p_doc_no       => :NEW.Voucher_no                                                                     
                                                         ,p_doc_jv_type  => :NEW.Voucher_pay_type      
                                                         ,p_doc_date     => V_VCHR_DATE
                                                         ,p_c_code       => :NEW.ac_code_dtl                               
                                                         ,p_cc_code      => :NEW.cc_code                                
                                                         ,p_pj_no        => :NEW.pj_no 
                                                         ,p_Actv_no      => :NEW.Actv_no          
                                                         ,p_doc_due_date => Nvl(:NEW.value_date,V_VCHR_DATE) 
                                                         ,p_amt          => :NEW.ac_amt+Nvl(:NEW.otr_amt_l,0)          
                                                         ,p_amt_f        => Nvl(:NEW.ac_amtf,0)+Nvl(:NEW.otr_amt_f,0)
                                                         ,p_a_cy         => :NEW.a_cy         
                                                         ,p_ac_rate      => Nvl(:NEW.ex_rate,1)      
                                                         ,p_rcrd_no          => :NEW.rcrd_no       
                                                         ,P_Ref_No           => :NEW.REF_NO       
                                                         ,P_Ac_Code_Dtl_Sub  => :NEW.Ac_Code_Dtl_Sub   
                                                         ,P_Doc_Dsc          => :NEW.AC_DESC          
                                                         ,p_Lang_no          => 1           
                                                         ,p_brn_no           => :NEW.brn_no      
                                                         ,p_brn_year         => :NEW.brn_year    
                                                         ,p_cmp_no           => :NEW.cmp_no             
                                                         ,p_brn_usr          => :NEW.brn_usr     
                                                         ,P_DOC_SEQ          => :NEW.Doc_SEQUENCE
                                                         ,P_A_CODE           => :NEW.A_CODE);
        Exception
           When Others Then
             Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
        End ;
        ---------End Payment  voucher----------------------------------------------------------------------------------------------------------------   
   End If ;
 --##--------------------------------------------------------------------------------------------------------##---
     
   --##------------------------------------------------------------------------------------##--

ElsIf UPDATING Then --(1)
------------------------------------------------------------------------
  Begin
     Select VOUCHER_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
       From VOUCHERS 
      Where  V_Ser=:OLD.v_Ser
         AND ROWNUM<=1;
  Exception
    When Others Then
    V_Stnd_By:=0;
  End; 
              -----------------------------------------------------------
  if :OLD.VOUCHER_TYPE = 1 AND NVL(:NEW.CHEQUE_VALUED,0) <> 2 And nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_DTL_TYP,:OLD.AC_DTL_TYP)=4 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is Not Null   AND abs(nvl(:NEW.AC_AMT,:OLD.AC_AMT)) >0   Then --(3)       
       ------------------------------------------------
       If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type    =>    2
                                                         ,p_doc_ser       =>     :OLD.v_ser                                     
                                                         ,p_v_code        =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                         ,p_rcrd_no       =>     :OLD.rcrd_no) = 1 Or  
                Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type  =>    2
                                                       ,p_doc_ser   =>     :OLD.v_ser                                     
                                                       ,p_v_code    =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                       ,p_rcrd_no   =>     :OLD.rcrd_no) = 1     Then
               -- Gen_Pkg.MsgBox(1134) ; 
                 Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);                                               
                                                 
         End If;                                                
         -------------------------------------------------------------------                                                            
   
    ------------------------------------------------------------------------                                                  
        Begin        
            --------------------------------------------------
             Begin
                 Select Nvl(Max(I_No),0)+1 InTo Ino 
                  From IAS_Installment_Pi 
                   Where Bill_Ser=:OLD.v_Ser
                     And v_Code=NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
              Exception
                When Others Then
                Ino:=1;
              End;   
             --------------------------------------------------
            
               ias_installment_ap_pkg.insrt_installment ( P_I_No       => Ino
                                                        ,p_doc_type     => 2
                                                        ,p_doc_ser      => :OLD.V_ser 
                                                        ,p_doc_no       => :OLD.Voucher_no                                                                   
                                                        ,p_doc_jv_type  => NVL(:NEW.Voucher_pay_type ,:OLD.Voucher_pay_type)  
                                                        ,p_doc_date     => V_VCHR_DATE
                                                        ,p_v_code       => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                        
                                                        ,p_cc_code      => NVL(:NEW.cc_code,:OLD.cc_code)                          
                                                        ,p_pj_no        =>  NVL(:NEW.PJ_NO,:OLD.PJ_NO)   
                                                        ,p_Actv_no      => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)      
                                                        ,p_doc_due_date => nvl(NVL(:NEW.value_date,:OLD.value_date),V_VCHR_DATE) 
                                                        ,p_amt          => (-1*:NEW.AC_AMT) + Nvl(:NEW.OTR_AMT_L,0)       
                                                        ,p_amt_f        => (-1*Nvl(NVL(:NEW.AC_AMTF,:OLD.AC_AMTF),0))+ Nvl(NVL(:NEW.OTR_AMT_F,:OLD.OTR_AMT_F),0)
                                                        ,p_a_cy         => NVL(:NEW.a_cy ,:OLD.a_cy)        
                                                        ,p_ac_rate      => Nvl(NVL(:NEW.ex_rate,:OLD.ex_rate),1)      
                                                        ,p_rcrd_no      => NVL(:NEW.rcrd_no ,:NEW.rcrd_no)                                
                                                        ,p_REF_no       => NVL(:NEW.REF_no,:OLD.REF_no )       
                                                        ,P_DOC_DSC       =>NVL(:NEW.AC_DESC,:OLD.AC_DESC) 
                                                        ,p_Lang_no      => 1           
                                                        ,p_brn_no       => :OLD.brn_no       
                                                        ,p_brn_year     => :OLD.brn_year   
                                                        ,p_cmp_no       => :OLD.cmp_no            
                                                        ,p_brn_usr      => :OLD.brn_usr     
                                                        ,P_DOC_SEQ      => :OLD.Doc_SEQUENCE
                                                        ,P_A_CODE       => :OLD.A_CODE
                                                        );
        Exception
           When Others Then
              
            Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
        End ;
  -----------------------------------------------------------------------------------------------------------
  ElsIf :OLD.VOUCHER_TYPE = 2 AND NVL(:NEW.CHEQUE_VALUED,0) <> 2 And nvl(V_Stnd_By,0)=0 AND NVL(:NEW.AC_DTL_TYP,:OLD.AC_DTL_TYP)=3 AND NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) Is Not Null   AND abs(nvl(:NEW.AC_AMT,:OLD.AC_AMT)) >0   Then --(3) 
  -----------------------------------------------------------------------------------------------------------  
                                                   
        If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type      =>    3
                                                           ,p_doc_ser       =>     :OLD.v_ser                                      
                                                           ,p_c_code        =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)
                                                           ,p_rcrd_no       =>     :old.rcrd_no) = 1 Or  
            Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>    3
                                                   ,p_doc_ser   =>     :old.v_ser                                      
                                                   ,p_c_code    =>     NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL) 
                                                   ,p_rcrd_no   =>     :old.rcrd_no) = 1     Then
             Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);                                                 
        End If;                                                    
                                                                                                                        
        Declare
        Ino Number:=1;     
        Begin        
        Begin 
         Select Nvl(Max(I_No),0)+1 InTo Ino From Installment 
         Where Bill_Ser=:OLD.v_Ser 
         And C_Code=NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL);
        Exception
        When Others Then
        Ino:=1;
        End;  
        --MUR
        ias_installment_ar_pkg.insrt_installment ( P_I_No         => Ino
                                                  ,p_doc_type     => 3                              
                                                  ,p_doc_ser      => :OLD.v_ser        
                                                  ,p_doc_no       => :OLD.Voucher_no                                                                      
                                                  ,p_doc_jv_type  => NVL(:NEW.Voucher_pay_type,:OLD.Voucher_pay_type) 
                                                  ,p_doc_date     => V_VCHR_DATE
                                                  ,p_c_code       => NVL(:NEW.AC_CODE_DTL,:OLD.AC_CODE_DTL)                               
                                                  ,p_cc_code      => NVL(:NEW.cc_code,:OLD.cc_code)                                
                                                  ,p_pj_no        => NVL(:NEW.PJ_NO,:OLD.PJ_NO) 
                                                  ,p_Actv_no      => NVL(:NEW.ACTV_NO,:OLD.ACTV_NO)        
                                                  ,p_doc_due_date => nvl(NVL(:NEW.value_date,:OLD.value_date),V_VCHR_DATE) 
                                                  ,p_amt          => NVL(NVL(:NEW.ac_amt,:OLD.ac_amt),0) + Nvl(NVL(:NEW.OTR_AMT_L,:OLD.OTR_AMT_L),0)
                                                  ,p_amt_f        => NVL(NVL(:NEW.ac_amtF,:OLD.ac_amtF),0) + Nvl(NVL(:NEW.OTR_AMT_F,:OLD.OTR_AMT_F),0)
                                                  ,p_a_cy         => NVL(:NEW.a_cy ,:OLD.a_cy)
                                                  ,p_ac_rate      => Nvl(NVL(:NEW.ex_rate,:OLD.ex_rate),1)      
                                                  ,p_rcrd_no      => NVL(:NEW.rcrd_no ,:NEW.rcrd_no)                                
                                                  ,P_REF_no           => NVL(:NEW.REF_no,:OLD.REF_no ) 
                                                  ,P_Ac_Code_Dtl_Sub  => NVL(:NEW.Ac_Code_Dtl_Sub,:OLD.Ac_Code_Dtl_Sub)  
                                                  ,P_Doc_Dsc          => NVL(:NEW.AC_DESC,:OLD.AC_DESC)                                       
                                                  ,P_Lang_no          => 1
                                                  ,p_brn_no       => :OLD.brn_no       
                                                  ,p_brn_year     => :OLD.brn_year   
                                                  ,p_cmp_no       => :OLD.cmp_no            
                                                  ,p_brn_usr      => :OLD.brn_usr     
                                                  ,P_DOC_SEQ      => :OLD.Doc_SEQUENCE
                                                  ,P_A_CODE       => :OLD.A_CODE);
        Exception
        When Others Then
          Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
        End ;
                  
        --##-----------------------------------------------------------------------------------------------------------------------------##--
                  
     
  End If ;
--##------------------------------------------------------------------------------------##--
--##------------------------------------------------------------------------------------##--

------------------------------------------------------------------------
ELSIf DELETING Then --(((1)
  If :OLD.VOUCHER_TYPE = 1 then  --2  RECEIVED    
    
        If :old.Ac_code_DTL IS NOT NULL AND :old.Ac_DTL_TYP=4   Then
            Begin
               If Ias_Installment_Ap_Pkg.Check_Installment_Trans ( p_doc_Type  =>2,
                                                                   p_doc_ser     =>     :old.v_ser,                                      
                                                                   p_v_code      =>     :old.Ac_code_DTL ,
                                                                   p_rcrd_no     =>     :old.rcrd_no) = 1     Then
                   
                    Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);  
               End If ;   
               If Ias_Installment_Ap_Pkg.Check_Dr_Trans ( p_doc_Type  =>2,
                                                          p_doc_ser     =>     :old.v_ser,                                      
                                                          p_v_code      =>     :old.Ac_code_DTL ,
                                                          p_rcrd_no     =>     :old.rcrd_no) = 1     Then
                    
                    Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
               End If ;                
            Exception
                When Others Then
                  Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
            End ;
        End If ;
        ---------------------------------------------------------------------------------------
                                                                      
        If :old.Ac_code_DTL IS NOT NULL THEN ---AND :old.Ac_DTL_TYP=4    Then
            Begin
                If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 2,                    
                                                                      P_Doc_Ser   => :old.V_Ser,    
                                                                      P_Rcrd_No   => :old.rcrd_no,
                                                                      P_Paid_Type => 0                    ) = 1     Then
                  Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);   
               End If ;                                                                         
        Exception When Others Then
                  Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
            End ;
        End If ;
        ---------------------------------------------------------------------------------------
        ---------------------------------------------------------------------------------------------------------
        Begin
        Delete From IAS_Installment_PI
        where Doc_Type = 2
        and bill_ser = :old.V_ser
        and rcrd_no = :old.rcrd_no
        and i_py=0;
        Exception
        When Others Then
          Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
        End ;     
        -----------------------------------------------------------------------------------------------    
  ELSIF :OLD.VOUCHER_TYPE = 2 then  --2    PAYMENT
    
        --============================================================================
         --# Installment     
             If :OLD.AC_DTL_TYP=3 AND :OLD.AC_CODE_DTL Is Not Null  Then
                    Begin
                       If Ias_Installment_Ar_Pkg.Check_Installment_Trans ( p_doc_Type  =>3
                                                                             ,p_doc_ser     =>     :OLD.v_ser                                      
                                                                          ,p_c_code      =>     :OLD.AC_CODE_DTL 
                                                                          ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
                           Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1134)||SqlErrm);    
                       End If ;   
                       If Ias_Installment_Ar_Pkg.Check_Dr_Trans ( p_doc_Type  =>3
                                                                    ,p_doc_ser     =>     :OLD.v_ser                                     
                                                                 ,p_c_code      =>     :OLD.AC_CODE_DTL 
                                                                 ,p_rcrd_no     =>     :OLD.rcrd_no) = 1     Then
                           Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1144)||SqlErrm);   
                       End If ;                
                    Exception
                         When Others Then
                          Raise_Application_Error(-20303,' 1- Error When Deleting Installment Trans. '||SqlErrm);
                    End ;
           End If ;
           
           If  :OLD.AC_CODE_DTL Is Not Null  Then  --:OLD.AC_DTL_TYP=3 AND
                    Begin
                       If Ias_Installment_Ar_Pkg.Chk_Adj_Installmnet_Trans ( P_Doc_Type  => 3                     
                                                                            ,P_Doc_Ser   => :OLD.V_Ser
                                                                            ,P_Rcrd_No   => :OLD.rcrd_no
                                                                            ,P_Paid_Type => 1                    ) = 1     Then
                     Raise_Application_Error(-20303,YS_GEN_PKG.Get_Msg(1,1239)||SqlErrm);    
                       End If ;
                    Exception
                         When Others Then
                          Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                    end;            
           End If ;                
           ---------------------------------------------------------------------------------------------------------
                              Begin
                                   Delete From Installment
                                    where Doc_Type = 3
                                      and bill_ser = :OLD.V_ser
                                      and rcrd_no = :OLD.rcrd_no
                                      and i_py=0;
                              Exception
                                     When Others Then
                                       Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                              End ;     
            -----------------------------------------------------------------------------------------------                  
          If :OLD.AC_DTL_TYP=4 AND :OLD.AC_CODE_DTL Is Not Null  Then
                 Begin
                       Delete From IAS_PYMNT_DTL
                        where Doc_Type = 3
                          and DOC_SER = :OLD.V_ser
                          AND RCRD_NO = :OLD.RCRD_NO
                          and V_Code = :OLD.AC_CODE_DTL
                          AND a_cy = :OLD.a_cy   ;
                  Exception
                        When Others Then
                          Raise_Application_Error(-20303,' 2- Error When Deleting Installment Trans. '||SqlErrm);
                  End ;        
                        
             
          End If; 
    
  End if;--2()
End If;--(1)

 EXCEPTION WHEN OTHERS THEN
   Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
END GLS_VCHR_DTL_INSTLMNT_TRGR;
