--
-- GLS_VCHR_MSTAC_INSTLMNT_TRGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.GLS_VCHR_MSTAC_INSTLMNT_TRGR
		BEFORE DELETE OR INSERT OR UPDATE
		OF CUR_CODE
		  ,AMT_L
		  ,AMT_F
		ON IAS20261.GLS_VCHR_MST_ACCNT 
		REFERENCING NEW AS NEW OLD AS OLD
		FOR EACH ROW
DECLARE 
		 ----------------------------------
				 
		 -- Created by  MURAD ALGARRASH
		 -- Date       23/02/2020 
		 
		 ----------------------------------
		  V_VCHR_DATE DATE;
		  V_Stnd_By    number(1);
		  Ino  Number(38):=1;  
          
BEGIN

If INSERTING  Then --(1)
   ---------Start Received  voucher----------------------------------------------------------------------------------------------------------------  
      Begin
         Select VOUCHER_DATE ,Stand_By InTo V_VCHR_DATE ,V_Stnd_By
           From VOUCHERS 
          Where  V_Ser=:NEW.DOC_SRL
             AND ROWNUM<=1;
      Exception
        When Others Then
        V_Stnd_By:=0;
      End; 
                  ----------------------------------------------------------- 
   If :NEW.VCHR_TYP = 2 and nvl(V_Stnd_By,0)=0 AND :NEW.AC_DTL_TYP=4 AND :NEW.AC_CODE_DTL Is Not Null   AND abs(nvl(:NEW.AMT_L,0)) >0   Then --(3)
        ------------------------------------------------------------------------                                                  
        Begin        
            --------------------------------------------------
             Begin
                 Select Nvl(Max(I_No),0)+1 InTo Ino 
                  From IAS_Installment_Pi 
                   Where Bill_Ser=:NEW.DOC_SRL
                     And v_Code=:NEW.AC_CODE_DTL;
              Exception
                When Others Then
                Ino:=1;
              End;   
