                                                        ,p_a_cy         => :NEW.CUR_CODE         
                                                        ,p_ac_rate      => Nvl(:NEW.CUR_RATE,1)
                                                        ,p_rcrd_no      => :NEW.rcrd_no                                 
                                                        ,P_Doc_Dsc          => :NEW.DOC_DSC
                                                        ,p_REF_no       => NULL     
                                                        ,p_Lang_no      => 1           
                                                        ,p_brn_no       => :NEW.brn_no
                                                        ,p_brn_year     => :NEW.brn_year    
                                                        ,p_cmp_no       => :NEW.cmp_no
                                                        ,p_brn_usr      => :NEW.brn_usr 
                                                        ,P_DOC_SEQ      => :NEW.DOC_SEQ
                                                        ,P_A_CODE       => :NEW.AC_CODE
                                                        );
        Exception
           When Others Then
              
            Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
        End ;
