   ElsIf :NEW.VCHR_TYP = 1 and nvl(V_Stnd_By,0)=0 AND :NEW.AC_DTL_TYP=3 AND :NEW.AC_CODE_DTL Is Not Null   AND abs(nvl(:NEW.AMT_L,0))  >0   Then --(3)
   --------------------------------------------------------------------------##-- 
        --------------------------------------------------
         Begin        
                --------------------------------------------------
                Begin 
