--
-- IAS_RT_BILL_MST_CHK_SRL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_RT_BILL_MST_CHK_SRL_TRG BEFORE INSERT OR UPDATE
ON IAS20261.IAS_RT_BILL_MST
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
BEGIN
   IF NVL(:NEW.EXTERNAL_POST,0)=0 THEN
       IF INSERTING AND AR_DOC_SQ_PKG.GET_DOC_SRL (   P_DOC_TYP       => 5,
                                                      P_PAY_TYP       => :NEW.RT_BILL_DOC_TYPE,                                                      
                                                      P_BRN_YEAR      => :NEW.BRN_YEAR,
                                                      P_BRN_NO        => :NEW.BRN_NO,
                                                      P_CC_CODE       => :NEW.CC_CODE ,
                                                      P_W_CODE        => :NEW.W_CODE,
                                                      P_TYP_NO        => :NEW.SR_TYPE,
                                                      P_DOC_NO        => :NEW.RT_BILL_NO,
                                                      P_SYS_NO        => 61,
                                                      P_USR_NO        => :NEW.AD_U_ID,
                                                      P_TRMNL_NO      => NULL                 )<>:NEW.RT_BILL_SER THEN
               RAISE_APPLICATION_ERROR(-20090,'The Serial No. For Ducument Not Currect') ; 
               
         ELSIF UPDATING THEN      
               IF :OLD.RT_BILL_NO<>:NEW.RT_BILL_NO THEN 
                  RAISE_APPLICATION_ERROR(-20091,'Error .. Can Not Update Return No') ;                    
               ELSIF :OLD.RT_BILL_SER<>:NEW.RT_BILL_SER THEN 
                  RAISE_APPLICATION_ERROR(-20092,'Error .. Can Not Update Return Serial') ;
               END IF;
       END IF;
   END IF;       
END IAS_RT_BILL_MST_CHK_SRL_TRG;
/


--
-- IAS_VD_INSTALLMNT_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_VD_INSTALLMNT_Tgr
BEFORE DELETE OR INSERT OR UPDATE
OF A_CY
  ,AC_AMT
  ,AC_AMTF
  ,OTR_AMT_L
  ,OTR_AMT_F
  ,BILL_NO
  ,BILL_SER
  ,I_NO
  ,CHEQUE_VALUED
  ,DUE_DATE
ON IAS20261.VOUCHER_DETAIL 
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE 
     ----------------------------------                 
     -- ALTERED by  MURAD ALGARRASH
     -- Date      08/06/2023          
     ----------------------------------
      V_POST_CST_TYP    number(1);
      V_POST_VNDR_TYP   number(1);
      V_CHEQ_TYP        number(1);  --3 
      V_TRANSFER        number(1);
      V_USR_YEAR_BFR VARCHAR2(100):='IAS'||TO_NUMBER(substr(user,4,4)-1)||substr(user,8)||'.';
      V_USR_YEAR_AFTR VARCHAR2(100):='IAS'||TO_NUMBER(substr(user,4,4)+1)||substr(user,8)||'.';
      V_USR_YEAR      VARCHAR2(100);
     
BEGIN
-- CHANGED BY MURAD ALGARRASH ADDING PAID_DATE IN 18/07/2023
      Begin
         Select V.CHEQ_TYPE,P.POST_CHEQUE_TYPE,P.POST_CHEQ_TYPE_VNDR ,V.TRANSFER
           InTo V_CHEQ_TYP,V_POST_CST_TYP ,V_POST_VNDR_TYP,V_TRANSFER
           From VOUCHERS V,IAS_PARA_GL P
          Where  V_Ser=:NEW.v_Ser
             AND ROWNUM<=1;
      Exception
        When Others Then
        V_POST_CST_TYP:=1;
        V_POST_VNDR_TYP:=1;
        V_CHEQ_TYP:=0;
      End; 
      
      
If DELETING Then --(((1)

    If :OLD.VOUCHER_TYPE = 1 AND :OLD.BILL_SER Is Not Null AND :OLD.I_NO Is Not Null AND :OLD.AC_CODE_DTL Is Not Null  AND :OLD.AC_DTL_TYP=3 Then --(2)
    
          If  V_POST_CST_TYP=0   AND NVL(V_CHEQ_TYP,0)= 3 AND nvl(:OLD.CHEQUE_VALUED,0) <>1 THEN 
              
              Null;
         
          ELSE 
                 IF :OLD.VOUCHER_PAY_TYPE = 2  AND  NVL(V_CHEQ_TYP,0)= 3 AND V_TRANSFER=0  THEN
                 
                     UPDATE INSTALLMENT SET PAID_AMT=NVL(PAID_AMT,0)- DECODE(NVL(:OLD.AC_AMTF,0),0,ABS(nvl(:OLD.AC_AMT,0)),ABS(NVL(:OLD.AC_AMTF,0)))
                                            ,PAID_DATE=:OLD.DUE_DATE
                      WHERE C_CODE=:OLD.AC_CODE_DTL
                        AND A_CY  =:OLD.A_CY
                        AND BILL_SER =:OLD.BILL_SER
                        AND I_NO =:OLD.I_NO;
                  ----------------------------------------------------------------------------------------------------
                   --IF 1=2 THEN
                   FOR i in 1..2 loop
                       if i=1 then 
                         V_USR_YEAR:=V_USR_YEAR_BFR;
                       else
                         V_USR_YEAR:=V_USR_YEAR_AFTR;
                       end if;
                       ---------------------------------------------------------------
                       BEGIN 
                           EXECUTE IMMEDIate 'UPDATE '||V_USR_YEAR||'INSTALLMENT 
                                                 SET PAID_AMT=NVL(PAID_AMT,0)- DECODE('||NVL(:OLD.AC_AMTF,0)||',0,ABS('||NVL(:OLD.AC_AMT,0)||'),ABS('||NVL(:OLD.AC_AMTF,0)||'))
                                                    ,PAID_DATE='''||:OLD.DUE_DATE||'''
                                              WHERE C_CODE='''||:OLD.AC_CODE_DTL||'''
                                                AND A_CY  ='''||:OLD.A_CY||'''
                                                AND BILL_SER ='||:OLD.BILL_SER||'
                                                AND I_NO ='||:OLD.I_NO||'';

                        EXCEPTION WHEN  OTHERS THEN
                              NULL;
                        END;
                        ---------------------------------------------------------------
                 end loop;
                --END IF;   
                 ------------------------------------------------------------------------------------------------------------------   
                 ELSE     
                  
                      UPDATE INSTALLMENT SET PAID_AMT=NVL(PAID_AMT,0)- DECODE(NVL(:OLD.AC_AMTF,0)-NVL(:OLD.OTR_AMT_F,0),0,ABS(nvl(:OLD.AC_AMT,0)-NVL(:OLD.OTR_AMT_L,0)),ABS(NVL(:OLD.AC_AMTF,0)-NVL(:OLD.OTR_AMT_F,0)))
                                            ,PAID_DATE=:OLD.DUE_DATE
                      WHERE C_CODE=:OLD.AC_CODE_DTL
                        AND A_CY  =:OLD.A_CY
                        AND BILL_SER =:OLD.BILL_SER
                        AND I_NO =:OLD.I_NO;
                    ----------------------------------------------------------------------------------------------------
                    FOR i in 1..2 loop
                       If i=1 then 
                         V_USR_YEAR:=V_USR_YEAR_BFR;
                       Else
                         V_USR_YEAR:=V_USR_YEAR_AFTR;
                       End if;   
                        --------------------------------------------------------------- '||V_USR_YEAR||'
                       BEGIN 
                       EXECUTE IMMEDIate 'UPDATE '||V_USR_YEAR||'INSTALLMENT 
                                             SET PAID_AMT=NVL(PAID_AMT,0)- DECODE('||(NVL(:OLD.AC_AMTF,0)-NVL(:OLD.OTR_AMT_F,0))||',0,ABS('||(nvl(:OLD.AC_AMT,0)-NVL(:OLD.OTR_AMT_L,0))||'),ABS('||(NVL(:OLD.AC_AMTF,0)-NVL(:OLD.OTR_AMT_F,0))||'))
                                                ,PAID_DATE='''||:OLD.DUE_DATE||'''
