                                                    AND I_NO ='||:NEW.I_NO||'';
                        EXCEPTION WHEN  OTHERS THEN
                              NULL;
                        END;
                        ---------------------------------------------------------------   
                    End Loop;                       
            ELSE             
             BEGIN                
                 UPDATE IAS_INSTALLMENT_PI 
                    SET PAID_AMT=NVL(PAID_AMT,0) + DECODE((nvl(:NEW.AC_AMTF,0)+NVL(:NEW.OTR_AMT_F,0)),0,ABS((nvl(:NEW.AC_AMT,0)+NVL(:NEW.OTR_AMT_L,0))),ABS(nvl(:NEW.AC_AMTF,0)+NVL(:NEW.OTR_AMT_F,0)))
                       ,PAID_DATE=:NEW.DUE_DATE
                  WHERE V_CODE=:NEW.AC_CODE_DTL
                    AND A_CY  =:NEW.A_CY
                    AND BILL_SER =:NEW.BILL_SER
                    AND I_NO =:NEW.I_NO;
            EXCEPTION WHEN  OTHERS THEN
                  NULL;
            END;
            ---------------------------------------------------------------   
                    FOR i in 1..2 loop
                       If i=1 then 
                         V_USR_YEAR:=V_USR_YEAR_BFR;
                       Else
                         V_USR_YEAR:=V_USR_YEAR_AFTR;
                       End if;  
                        ---------------------------------------------------------------
                       BEGIN 
                       EXECUTE IMMEDIate 'UPDATE '||V_USR_YEAR||'IAS_INSTALLMENT_PI 
                                             SET PAID_AMT=NVL(PAID_AMT,0) + DECODE('||(nvl(:NEW.AC_AMTF,0)+NVL(:NEW.OTR_AMT_F,0))||',0,ABS('||(nvl(:NEW.AC_AMT,0)+NVL(:NEW.OTR_AMT_L,0))||'),ABS('||(nvl(:NEW.AC_AMTF,0)+NVL(:NEW.OTR_AMT_F,0))||'))
                                               ,PAID_DATE='''||:NEW.DUE_DATE||'''
                                          WHERE V_CODE='''||:NEW.AC_CODE_DTL||'''
                                            AND A_CY  ='''||:NEW.A_CY||'''
                                            AND BILL_SER ='||:NEW.BILL_SER||'
                                            AND I_NO ='||:NEW.I_NO||'';
                        
                        EXCEPTION WHEN  OTHERS THEN
                              NULL;
                        END;
                        ---------------------------------------------------------------   
                End Loop;        
            END IF;        

           -- END IF;          
         END IF;        

    End If;


End If;--(1)

 EXCEPTION WHEN OTHERS THEN
   Raise_Application_Error(-20303,' Error When Installment Trans. '||SqlErrm);
END IAS_VD_INSTALLMNT_Tgr;
/


