--
-- APS_KPI_ITM_COST_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_ITM_COST_VW
(CMP_NM, BRN_NM, W_NM, BRN_YEAR, BRN_USR, 
 PUR_TYPE, BILL_DOC_TYPE_NM, BILL_TYPE_NO, BILL_DATE, GR_DATE, 
 V_CODE, V_NM, V_E_NM, V_GRP_CODE, V_CLASS, 
 V_DEGREE, CNTRY_NM, PROV_NM, CITY_NM, R_CODE_NM, 
 ITM_CODE, ITM_NM, ITM_F_NM, ITM_DSC, ITM_F_DSC, 
 GRP_CLASS_CODE, GRP_CLASS_NM, ACTIVITY_NM, GRP_CODE, GRP_CODE_NM, 
 MNG_CODE_NM, SUBG_CODE_NM, ASSTNT_GRP_NM, DTL_GRP_NM, ALTRNTV_GRP_NM, 
 ITM_TYP_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITEM_SIZE, SIZE_ITM, AREA_ITM, WEIGHT_ITM, 
 GTIN_CODE, HSN_CODE, MANF_CODE, ALTER_CODE, INCOME_DATE, 
 LENGTH_ITM, WIDTH_ITM, HEIGHT_ITM, SEASON_ITM, ORE_ITM, 
 MARK_ITM, COMPANY_ITM, COUNTRY_ITM, ITM_UNT, ITM_P_SIZE, 
 C1, C2, C3, PUR2_EXPNS_NM, PUR1_EXPNS_NM, 
 PUR1_EXP_AMT, PUR1_BILL_EXPNS, PI_NO, GR_NO, G_SER, 
 EXPNS_RCRD_NO, LC_NO, LC_DATE, EXPIRE_DATE, BATCH_NO, 
 PI_COST_TYPE_NO, I_QTY, FREE_QTY, RCRD_NO, BILL_SER, 
 REC_NO, I_PRICE, C_PRICE, PRICE, DIS_AMT, 
 VAT_AMT, OTHR_AMT_ITM, ADD_AMT, TOTAL, BILL_AMT)
BEQUEATH DEFINER
AS 
WITH
        LNG
        AS
            (SELECT (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1) FROM DUAL)
                        LNG_NO
                   ,NVL (
                        (SELECT FLD_VAL
                           FROM S_FLD_PRV_FXD_USR
                          WHERE UPPER (FLD_NM) = UPPER ('HIDE_COST')
                                AND U_ID = NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'USER_NO'), 1)
                                AND ROWNUM <= 1)
                       ,0)
                        HIDE_COST
                   ,(SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'USER_NO'), 1) FROM DUAL)
                        P_USR_NO
               FROM DUAL)
    SELECT I.CMP_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (CMP_LNAME, CMP_FNAME)
                                               ,NVL (CMP_FNAME, CMP_LNAME))
                                   FROM S_CMPNY
                                  WHERE CMP_NO = I.CMP_NO AND ROWNUM <= 1)
               CMP_NM
          ,I.BRN_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (BRN_LNAME, BRN_FNAME)
                                               ,NVL (BRN_FNAME, BRN_LNAME))
                                   FROM S_BRN
                                  WHERE BRN_NO = I.BRN_NO AND ROWNUM <= 1)
               BRN_NM
          ,I.W_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO, 1, W_NAME, NVL (W_E_NAME, W_NAME))
                                   FROM WAREHOUSE_DETAILS
                                  WHERE W_CODE = I.W_CODE AND ROWNUM <= 1)
               W_NM
          ,I.BRN_YEAR
          ,I.BRN_USR
          ,I.PUR_TYPE || '-' || DECODE (
           I.PUR_TYPE
                                   ,1, (SELECT YS_GEN_PKG.GET_PROMPT (
           P_LNG_NO                                                 => LNG.LNG_NO
                                                  ,P_LBL_NO         => 1491)
                                          FROM DUAL)
                                   ,2, (SELECT YS_GEN_PKG.GET_PROMPT (
           P_LNG_NO                                                 => LNG.LNG_NO
                                                  ,P_LBL_NO         => 68)
                                          FROM DUAL))
               PUR_TYPE
          ,I.BILL_DOC_TYPE || ' - ' || DECODE (
           I.BILL_DOC_TYPE
                                          ,1, (SELECT FLG_DESC
                                                 FROM S_FLAGS
                                                WHERE FLG_CODE = 'TYPE_NAME'
           AND LANG_NO = LNG.LNG_NO
           AND FLG_VALUE = I.BILL_DOC_TYPE
           AND ROWNUM <= 1)
                                          ,2, (SELECT FLG_DESC
                                                 FROM S_FLAGS
                                                WHERE FLG_CODE = 'TYPE_NAME'
           AND LANG_NO = LNG.LNG_NO
           AND FLG_VALUE = I.BILL_DOC_TYPE
           AND ROWNUM <= 1)
                                          ,3, (SELECT FLG_DESC
                                                 FROM S_FLAGS
                                                WHERE FLG_CODE = 'TYPE_NAME'
           AND LANG_NO = LNG.LNG_NO
           AND FLG_VALUE = I.BILL_DOC_TYPE
           AND ROWNUM <= 1)
                                          ,4, (SELECT FLG_DESC
                                                 FROM S_FLAGS
                                                WHERE FLG_CODE = 'TYPE_NAME'
           AND LANG_NO = LNG.LNG_NO
           AND FLG_VALUE = I.BILL_DOC_TYPE
           AND ROWNUM <= 1)
                                          ,NULL)
               BILL_DOC_TYPE_NM
          ,I.BILL_TYPE_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                     ,1, A.TYPE_L_NAME
                                                     ,NVL (A.TYPE_F_NAME, A.TYPE_L_NAME))
                                         FROM IAS_AP_BILL_TYPES A
                                        WHERE A.BILL_TYPE_NO = I.BILL_TYPE_NO AND ROWNUM <= 1)
               BILL_TYPE_NO
          ,I.BILL_DATE
          ,I.GR_DATE
          ,V.V_CODE
               V_CODE
          ,V.V_CODE || ' - ' || DECODE (LNG.LNG_NO
                                       ,1, NVL (V_A_NAME, V_E_NAME)
                                       ,NVL (V_E_NAME, V_A_NAME))
               V_NM
          ,V_E_NAME
               V_E_NM
          ,V_GROUP_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                   ,1, A.V_GROUP_A_NAME
                                                   ,NVL (A.V_GROUP_E_NAME, A.V_GROUP_A_NAME))
                                       FROM VENDOR_GROUP A
                                      WHERE A.V_GROUP_CODE = V.V_GROUP_CODE AND ROWNUM <= 1)
               V_GRP_CODE
          ,V_CLASS || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                              ,1, A.V_CLASS_NAME
                                              ,NVL (A.V_CLASS_E_NAME, A.V_CLASS_NAME))
                                  FROM VENDOR_CLASS A
                                 WHERE A.V_CLASS = V.V_CLASS AND ROWNUM <= 1)
               V_CLASS
          ,V_DEGREE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, A.V_DEGREE_A_NAME
                                               ,NVL (A.V_DEGREE_E_NAME, A.V_DEGREE_A_NAME))
                                   FROM IAS_VENDOR_DEGREE A
                                  WHERE A.V_DEGREE = V.V_DEGREE AND ROWNUM <= 1)
               V_DEGREE
          ,V.CNTRY_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                 ,1, NVL (CNTRY_A_NAME, CNTRY_E_NAME)
                                                 ,NVL (CNTRY_E_NAME, CNTRY_A_NAME))
                                     FROM CNTRY
                                    WHERE CNTRY_NO = V.CNTRY_NO AND ROWNUM <= 1)
               CNTRY_NM
          ,V.PROV_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                ,1, NVL (PROV_A_NAME, PROV_E_NAME)
                                                ,NVL (PROV_E_NAME, PROV_A_NAME))
                                    FROM IAS_PROVINCES
                                   WHERE PROV_NO = V.PROV_NO AND ROWNUM <= 1)
               PROV_NM
          ,V.CITY_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                ,1, NVL (CITY_A_NAME, CITY_E_NAME)
                                                ,NVL (CITY_E_NAME, CITY_A_NAME))
                                    FROM CITIES
                                   WHERE CITY_NO = V.CITY_NO AND ROWNUM <= 1)
               CITY_NM
          ,V.R_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (R_A_NAME, R_A_NAME)
                                               ,NVL (R_E_NAME, R_A_NAME))
                                   FROM REGIONS
                                  WHERE R_CODE = V.R_CODE AND ROWNUM <= 1)
               R_CODE_NM
          ,M.I_CODE
               ITM_CODE
          ,DECODE (LNG.LNG_NO, 1, NVL (I_NAME, I_E_NAME), NVL (I_E_NAME, I_NAME))
               ITM_NM
          ,M.I_E_NAME
               ITM_F_NM
          ,DECODE (LNG.LNG_NO, 1, M.I_DESC, NVL (M.I_F_DESC, M.I_DESC))
               ITM_DSC
          ,M.I_F_DESC
               ITM_F_DSC
          ,M.GRP_CLASS_CODE
               GRP_CLASS_CODE
          ,M.GRP_CLASS_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                       ,1, A.GRP_L_NAME
                                                       ,NVL (A.GRP_F_NAME, A.GRP_L_NAME))
                                           FROM IAS_GRP_ITM_LVL A
                                          WHERE A.GRP_CODE = M.GRP_CLASS_CODE AND ROWNUM <= 1)
               GRP_CLASS_NM
          ,M.ACTIVITY_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                    ,1, A.ACTIVITY_A_NAME
                                                    ,NVL (A.ACTIVITY_E_NAME, A.ACTIVITY_A_NAME))
                                        FROM IAS_ITEMS_ACTIVITY A
                                       WHERE A.ACTIVITY_NO = M.ACTIVITY_NO AND ROWNUM <= 1)
               ACTIVITY_NM
          ,M.G_CODE
               GRP_CODE
          ,M.G_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (GRP.G_A_NAME, GRP.G_E_NAME)
                                               ,NVL (GRP.G_E_NAME, GRP.G_A_NAME))
                                            GRP_NM
                                   FROM GROUP_DETAILS GRP
                                  WHERE G_CODE = M.G_CODE AND ROWNUM <= 1)
               GRP_CODE_NM
          ,M.MNG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                 ,1, NVL (GRP.MNG_A_NAME, GRP.MNG_E_NAME)
                                                 ,NVL (GRP.MNG_E_NAME, GRP.MNG_A_NAME))
                                              GRP_NM
                                     FROM IAS_MAINSUB_GRP_DTL GRP
                                    WHERE MNG_CODE = M.MNG_CODE
           AND NVL (M.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (M.G_CODE, '0'), G_CODE)
           AND ROWNUM <= 1)
               MNG_CODE_NM
          ,M.SUBG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.SUBG_A_NAME, GRP.SUBG_E_NAME)
                                                  ,NVL (GRP.SUBG_E_NAME, GRP.SUBG_A_NAME))
                                               GRP_NM
                                      FROM IAS_SUB_GRP_DTL GRP
                                     WHERE SUBG_CODE = M.SUBG_CODE
           AND NVL (M.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (M.G_CODE, '0'), G_CODE)
           AND NVL (M.MNG_CODE, '0') =
           DECODE (NVL (MNG_CODE, '0'), '0', NVL (M.MNG_CODE, '0'), MNG_CODE)
           AND ROWNUM <= 1)
               SUBG_CODE_NM
          ,M.ASSISTANT_NO || ' - ' || (SELECT DECODE (
           LNG.LNG_NO
                                                 ,1, NVL (GRP.ASSISTANT_A_NAME
                                                         ,GRP.ASSISTANT_E_NAME)
                                                 ,NVL (GRP.ASSISTANT_E_NAME, GRP.ASSISTANT_A_NAME)
           )
                                                  GRP_NM
                                         FROM IAS_ASSISTANT_GROUP GRP
                                        WHERE ASSISTANT_NO = M.ASSISTANT_NO
           AND NVL (M.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (M.G_CODE, '0'), G_CODE)
           AND NVL (M.MNG_CODE, '0') =
           DECODE (NVL (MNG_CODE, '0'), '0', NVL (M.MNG_CODE, '0'), MNG_CODE)
           AND NVL (M.SUBG_CODE, '0') =
           DECODE (NVL (SUBG_CODE, '0'), '0', NVL (M.SUBG_CODE, '0'), SUBG_CODE)
           AND ROWNUM <= 1)
               ASSTNT_GRP_NM
          ,M.DETAIL_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.DETAIL_A_NAME, GRP.DETAIL_E_NAME)
                                                  ,NVL (GRP.DETAIL_E_NAME, GRP.DETAIL_A_NAME))
                                               GRP_NM
                                      FROM IAS_DETAIL_GROUP GRP
                                     WHERE DETAIL_NO = M.DETAIL_NO
           AND NVL (M.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (M.G_CODE, '0'), G_CODE)
           AND NVL (M.MNG_CODE, '0') =
           DECODE (NVL (MNG_CODE, '0'), '0', NVL (M.MNG_CODE, '0'), MNG_CODE)
           AND NVL (M.SUBG_CODE, '0') =
           DECODE (NVL (SUBG_CODE, '0'), '0', NVL (M.SUBG_CODE, '0'), SUBG_CODE)
           AND NVL (M.ASSISTANT_NO, '0') =
           DECODE (NVL (ASSISTANT_NO, '0'), '0', NVL (M.ASSISTANT_NO, '0'), ASSISTANT_NO)
           AND ROWNUM <= 1)
               DTL_GRP_NM
          ,M.GROUP_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                 ,1, A.GROUP_A_NAME
                                                 ,NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
                                     FROM IAS_ALTERNATIVE_GROUP A
                                    WHERE A.GROUP_NO = M.GROUP_NO AND ROWNUM <= 1)
               ALTRNTV_GRP_NM
          ,M.ITEM_TYPE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, A.IT_A_NAME
                                                  ,NVL (A.IT_E_NAME, A.IT_A_NAME))
                                      FROM ITEM_TYPES A
                                     WHERE A.TYPE_OF_ITEM = M.ITEM_TYPE AND ROWNUM <= 1)
               ITM_TYP_NM
          ,M.KIT_ITM
          ,M.USE_EXP_DATE
          ,M.USE_BATCH_NO
          ,M.USE_SERIALNO
          ,M.USE_ATTCH
          ,M.ITEM_SIZE
          ,M.SIZE_ITM
          ,M.AREA_ITM
          ,M.WEIGHT_ITM
          ,M.GTIN_CODE
          ,M.HSN_CODE
          ,M.MANF_CODE
          ,M.ALTER_CODE
          ,M.INCOME_DATE
          ,M.LENGTH_ITM
          ,M.WIDTH_ITM
          ,M.HEIGHT_ITM
          ,M.SEASON_ITM
          ,M.ORE_ITM
          ,M.MARK_ITM
          ,M.COMPANY_ITM
          ,M.COUNTRY_ITM
          ,I.UNIT
               ITM_UNT
          ,(SELECT IAS_ITM_PKG.GET_ICODE_SIZE_UNIT (P_I_CODE => M.I_CODE, P_ITM_UNT => I.UNIT)
              FROM DUAL)
               ITM_P_SIZE
          ,I.C1
          ,I.C2
          ,I.C3
          ,I.PUR2_EXPNS_NM
          ,I.PUR1_EXPNS_NO|| ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (EXPNS_L_NM, EXPNS_F_NM)
                                               ,NVL (EXPNS_F_NM, EXPNS_L_NM))
                                        FROM IAS_AP_EXPNS
                                       WHERE EXPNS_NO = I.PUR1_EXPNS_NO AND ROWNUM <= 1) PUR1_EXPNS_NM
          ,I.PUR1_EXP_AMT
          ,I.PUR1_BILL_EXPNS
          ,I.PI_NO
          ,I.GR_NO
          ,I.G_SER
          ,I.EXPNS_RCRD_NO
          ,I.LC_NO
          ,I.LC_DATE
          ,I.EXPIRE_DATE
          ,I.BATCH_NO
          ,I.PI_COST_TYPE_NO || '-' || (SELECT INV_TYPE
                                          FROM COSTING_TYPES
                                         WHERE COSTING_TYPE_NO = I.PI_COST_TYPE_NO AND ROWNUM <= 1
           )
               PI_COST_TYPE_NO
          ,I.I_QTY
          ,I.FREE_QTY
          ,I.RCRD_NO
          ,I.BILL_SER
          ,I.REC_NO
          ,DECODE (LNG.HIDE_COST, 1, I.I_PRICE, 0)
               I_PRICE
          ,DECODE (LNG.HIDE_COST, 1, I.C_PRICE, 0)
               C_PRICE
          ,DECODE (LNG.HIDE_COST, 1, I.PRICE, 0)
               PRICE
          ,DECODE (LNG.HIDE_COST, 1, I.DIS_AMT, 0)
               DIS_AMT
          ,DECODE (LNG.HIDE_COST, 1, I.VAT_AMT, 0)
               VAT_AMT
          ,DECODE (LNG.HIDE_COST, 1, I.OTHR_AMT_ITM, 0)
               OTHR_AMT_ITM
          ,DECODE (LNG.HIDE_COST, 1, I.ADD_AMT, 0)
               ADD_AMT
          ,DECODE (LNG.HIDE_COST, 1, I.TOTAL, 0)
               TOTAL
          ,DECODE (LNG.HIDE_COST, 1, I.BILL_AMT, 0) BILL_AMT    
      FROM (SELECT BDTL.BRN_YEAR
                  ,BDTL.BRN_USR
                  ,BDTL.CMP_NO
                  ,BDTL.BRN_NO
                  ,BDTL.W_CODE
                  ,BMST.PUR_TYPE
                  ,BMST.BILL_DOC_TYPE
                  ,BMST.BILL_TYPE_NO
                  ,BMST.BILL_DATE
                  ,G.GR_DATE
                  ,BDTL.I_CODE
                  ,G.ITM_UNT
                       UNIT
                  ,NULL
                       C1
                  ,NULL
                       C2
                  ,NULL
                       C3
                  ,NULL
                       PUR2_EXPNS_NM
                  ,EXPNS.EXPNS_NO
                       PUR1_EXPNS_NO
                  ,EXPNS.EXP_AMT
                       PUR1_EXP_AMT
                  ,BMST.EXP_AMT
                       PUR1_BILL_EXPNS
                  ,BDTL.BILL_NO
                       PI_NO
                  ,G.GR_NO
                  ,G.G_SER
                  ,NULL
                       EXPNS_RCRD_NO
                  ,BMST.LC_NO
                  ,NULL
                       LC_DATE
                  ,DECODE (BDTL.EXPIRE_DATE, '01/01/1900', NULL, BDTL.EXPIRE_DATE)
                       EXPIRE_DATE
                  ,DECODE (BDTL.BATCH_NO, '0', NULL, BDTL.BATCH_NO)
                       BATCH_NO
                  ,NULL
                       PI_COST_TYPE_NO
                  ,G.I_QTY
                  ,G.FREE_QTY
                  ,G.RCRD_NO
                  ,BMST.BILL_SER
                  ,G.REC_NO
                  ,G.V_CODE
                  ,G.I_PRICE
                  ,G.C_PRICE
                  ,(G.I_QTY * G.I_PRICE)
                       PRICE
                  ,G.DIS_AMT
                  ,G.VAT_AMT
                  ,(NVL (BDTL.I_QTY, 0) * NVL (BDTL.OTHR_AMT_ITM, 0))
                       OTHR_AMT_ITM
                  ,(NVL (BDTL.I_QTY, 0) * NVL (BDTL.ADD_AMT, 0))
                       ADD_AMT
                  ,((NVL (G.I_QTY, 0) + NVL (G.FREE_QTY, 0)) * NVL (G.C_PRICE, 0))
                       TOTAL
                  ,BMST.DOC_AMT BILL_AMT   
              FROM GR_DETAIL          G
                  ,IAS_PI_BILL_MST    BMST
                  ,IAS_PI_BILL_DTL    BDTL
                  ,IAS_PI_BILL_EXPND  EXPNS
             WHERE G.PI_TYPE = 2
                   AND BMST.PUR_TYPE = 1
                   AND BDTL.BILL_SER = G.DOC_SER
                   AND BMST.BILL_SER = BDTL.BILL_SER
                   AND BMST.BILL_NO = BDTL.BILL_NO
                   AND BMST.BILL_SER = EXPNS.BILL_SER(+)
                   AND BDTL.I_CODE = G.I_CODE
                   AND BDTL.EXPIRE_DATE = G.EXPIRE_DATE
                   AND BDTL.BATCH_NO = G.BATCH_NO
            UNION ALL
            SELECT BDTL.BRN_YEAR
                  ,BDTL.BRN_USR
                  ,BDTL.CMP_NO
                  ,BDTL.BRN_NO
                  ,BDTL.W_CODE
                  ,BMST.PUR_TYPE
                  ,BMST.BILL_DOC_TYPE
                  ,BMST.BILL_TYPE_NO
                  ,BMST.BILL_DATE
                  ,G.GR_DATE
                  ,BDTL.I_CODE
                  ,G.ITM_UNT
                       UNIT
                  ,C1
                  ,C2
                  ,C3
                  ,(SELECT GET_CST_NM_FUN (P_RCRD_NO        => EDTL.RCRD_NO
                                          ,P_PI_CST_TYP_NO  => PI_COST_TYPE_NO)
                      FROM DUAL)
                       PUR2_EXPNS_NM
                  ,NULL
                       PUR1_EXPNS_NO
                  ,NULL
                       PUR1_EXP_AMT
                  ,NULL
                       PUR1_BILL_EXPNS
                  ,EDTL.PI_NO
                  ,EDTL.GR_NO
                  ,EDTL.G_SER
                  ,EDTL.RCRD_NO
                       EXPNS_RCRD_NO
                  ,EMST.LC_NO
                  ,LC_DATE
                  ,DECODE (EDTL.EXPIRE_DATE, '01/01/1900', NULL, EDTL.EXPIRE_DATE)
                       EXPIRE_DATE
                  ,DECODE (EDTL.BATCH_NO, '0', NULL, EDTL.BATCH_NO)
                       BATCH_NO
                  ,PI_COST_TYPE_NO
                  ,G.I_QTY
                  ,G.FREE_QTY
                  ,G.RCRD_NO
                  ,BMST.BILL_SER
                  ,REC_NO
                  ,G.V_CODE
                  ,G.I_PRICE
                  ,G.C_PRICE
                  ,(G.I_QTY * G.I_PRICE)
                       PRICE
                  ,G.DIS_AMT
                  ,G.VAT_AMT
                  ,(NVL (BDTL.I_QTY, 0) * NVL (BDTL.OTHR_AMT_ITM, 0))
                       OTHR_AMT_ITM
                  ,(SELECT SUM (NVL (C1, 0))
                      FROM EXP_DETAILS
                     WHERE DOC_SER = BDTL.BILL_SER
                           AND G_SER = G.G_SER
                           AND PI_NO = EDTL.PI_NO
                           AND I_CODE = EDTL.I_CODE)
                       ADD_AMT
                  ,((NVL (G.I_QTY, 0) + NVL (G.FREE_QTY, 0)) * NVL (G.C_PRICE, 0))
                       TOTAL
                  ,BMST.DOC_AMT BILL_AMT        
              FROM EXP_DETAILS      EDTL
                  ,COST_MASTER      EMST
                  ,GR_DETAIL        G
                  ,IAS_PI_BILL_MST  BMST
                  ,IAS_PI_BILL_DTL  BDTL
             WHERE G.I_CODE = EDTL.I_CODE
                   AND G.PI_TYPE = 2
                   AND BMST.PUR_TYPE = 2
                   AND EDTL.GR_NO = EMST.GR_NO
                   AND EDTL.PI_NO = EMST.PI_NO
                   AND EDTL.G_SER = EMST.G_SER
                   AND EDTL.G_SER = G.G_SER
                   AND EDTL.DOC_SER = EMST.DOC_SER
                   AND G.PI_NO = EMST.PI_NO
                   AND G.GR_NO = EMST.GR_NO
                   AND G.G_SER = EMST.G_SER
                   AND EDTL.EXPIRE_DATE = G.EXPIRE_DATE
                   AND EDTL.BATCH_NO = G.BATCH_NO
                   AND NVL (EDTL.GR_RCRD_NO, G.RCRD_NO) = G.RCRD_NO
                   AND BMST.BILL_SER = BDTL.BILL_SER
                   AND BMST.BILL_NO = BDTL.BILL_NO
                   AND BDTL.BILL_SER = G.DOC_SER
                   AND BDTL.I_CODE = G.I_CODE) I
          ,IAS_ITM_MST  M
          ,V_DETAILS    V
          ,LNG
     WHERE M.I_CODE = I.I_CODE AND V.V_CODE(+) = I.V_CODE;


--
-- APS_KPI_NET_PI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_NET_PI_VW
(DOC_TYPE, DOC_TYPE_NM, SYS_NM, YR_NO, BRN_NM, 
 DOC_BRN_NM, AD_U_NM, EXPIRE_DATE, BATCH_NO, A_CODE_NM, 
 AC_CODE_DTL, CR_CARD_NM, INSRNCE_CMP_NO, INS_CMP_NM, INSRNCE_CARD_NO, 
 INSRNCE_CARD_NO_FMLY, CNTRCT_NO, STAND_BY, REF_NO, PAID_BILL, 
 PAID_U_NM, PAID_DATE, REC_INV_BILL, REC_INV_U_ID, REC_INV_DATE, 
 AUDIT_REF, C_TEL, PTNT_NO, DCTR_NO, DOC_NO_ADMSON, 
 V_CODE_CSH, BILL_DOC_TYPE, DOC_DATE, HALF_NO, QRTR_NO, 
 PRD_NM, WEEK_NO, DAY_NO, CASH_NM, CST_CODE, 
 V_CODE_NAME, ITM_CODE, ITM_NM, ITM_UNT, MAX_ITM_UNT, 
 MAX_P_SIZE, G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, 
 SUBG_CODE, SUBG_CODE_NM, ASSTNT_GRP_CODE, ASSTNT_GRP_NM, DTL_GRP_NO, 
 DTL_GRP_NM, ALTRNTV_GRP_CODE, ALTRNTV_GRP_NM, GRP_CLASS_CODE, GRP_CLASS_NM, 
 ITM_DSC, SMAN_CODE, COL_NM, DRIVER_NM, PRM_NM, 
 R_NM, CMP_NM, W_NM, CC_NM, PJ_NM, 
 ACTV_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, EXTERNAL_POST, ITM_SIZE, CUR_CODE, DOC_NO, 
 DOC_SER, RCRD_NO, SI_RCRD_NO, BILL_NO, BILL_SER, 
 P_SIZE, CUR_RATE, STOCK_RATE, STK_COST, I_PRICE, 
 I_QTY, FREE_QTY, ITM_QTY, AMT, AMT_L, 
 DSCNT_AMT, DSCNT_AMT_L, TAX_AMT, TAX_AMT_L, OTHR_AMT, 
 OTHR_AMT_L, NET_BILL_AMT, NET_BILL_AMT_L, NET_BILL_AMT_NO_TAX, NET_BILL_AMT_NO_TAXT_L, 
 NET_STK_AMT_L, NET_BILL_AMT_STK, NET_BILL_AMT_STK_NO_DISC, NET_STK_AMT_STK, NET_PROFT_AMT_STK, 
 NET_PROFT_AMT_L, AC_AMT, CHEQUE_AMT, BNK_AMT_DTL, CRDT_AMT, 
 CASH_AMT, BRN_NO, DOC_BRN_NO, AD_U_ID, A_CODE, 
 CR_CARD_NO, PAID_U_ID, BILL_DOC_TYPE_NO, CASH_NO, COL_NO, 
 DRIVER_NO, PRM_CODE, R_CODE, CMP_NO, W_CODE, 
 CC_CODE, PJ_NO, ACTV_NO, PRD_NO, SYS_NO, 
 NO_OF_DAY, V_CLASS_NM, C_GROUP_CODE_NM, C_DEGREE_NM, C_CLASS_TYP_NM, 
 ITM_TYP_NM, EMP_NO, EMP_NM, P_YEAR, P_YEAR_NM)
BEQUEATH DEFINER
AS 
WITH
        lng
        AS
            (SELECT (SELECT NVL (
                                Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                1)
                       FROM DUAL)
                        Lng_No,
                    NVL (
                        (SELECT FLD_VAL
                           FROM S_FLD_PRV_FXD_USR
                          WHERE     UPPER (FLD_NM) = UPPER ('HIDE_COST')
                                AND U_ID =
                                    NVL (
                                        Ias_Prmtr_Pkg.Getpval (
                                            P_Prmtr   => 'USER_NO'),
                                        1)
                                AND ROWNUM <= 1),
                        0)
                        HIDE_COST,
                    (SELECT NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),
                                 1)
                       FROM DUAL)
                        USR_NO
               FROM DUAL)
    SELECT Doc_Type,
           (SELECT DOC_TYPE_NAME
              FROM Ias_Sys.IAS_DOCJV_TYPE_SYSTEMS_MST
             WHERE     Lang_no = Lng.Lng_No
                   AND DOC_TYPE = M.Doc_Type
                   AND ROWNUM <= 1)
               Doc_Type_Nm,
           (SELECT (SELECT Caption_det
                      FROM Ias_Sys.IAS_LABELS
                     WHERE     lang_no = Lng.Lng_No
                           AND Label_no = Smart_Rprt_Dsgnr_Qry.Lbl_No
                           AND ROWNUM <= 1)
              FROM Smart_Rprt_Dsgnr_Qry
             WHERE Sys_No = M.Sys_No AND Scr_No_Parent = 0 AND ROWNUM <= 1)
               Sys_Nm,
           M.Yr_No,
              M.Brn_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Brn_Lname, Brn_Fname),
                              NVL (Brn_Fname, Brn_Lname))
                 FROM S_Brn
                WHERE Brn_No = M.Brn_No AND ROWNUM <= 1)
               Brn_Nm,
              M.Doc_Brn_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Brn_Lname, Brn_Fname),
                              NVL (Brn_Fname, Brn_Lname))
                 FROM S_Brn
                WHERE Brn_No = M.Doc_Brn_No AND ROWNUM <= 1)
               Doc_Brn_Nm,
              M.Ad_U_Id
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (U_A_Name, U_E_Name),
                              NVL (U_E_Name, U_A_Name))
                 FROM User_R
                WHERE U_Id = M.Ad_U_Id AND ROWNUM <= 1)
               Ad_U_Nm,
           M.Expire_Date,
           M.Batch_No,
              M.A_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (A_Name, A_Name_Eng),
                              NVL (A_Name_Eng, A_Name))
                 FROM Account
                WHERE A_Code = M.A_Code AND ROWNUM <= 1)
               A_Code_Nm,
           M.AC_CODE_Dtl,
              M.Cr_Card_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Cr_Card_Name, Cr_Card_E_Name),
                              NVL (Cr_Card_E_Name, Cr_Card_Name))
                 FROM Credit_Card_Types
                WHERE Cr_Card_No = M.Cr_Card_No AND ROWNUM <= 1)
               Cr_Card_Nm,
           M.Insrnce_Cmp_No,
              M.Insrnce_Cmp_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Ins_Cmp_L_Nm, Ins_Cmp_F_Nm),
                              NVL (Ins_Cmp_F_Nm, Ins_Cmp_L_Nm))
                 FROM Ias_Insrnce_Cmp
                WHERE Ins_Cmp_No = M.Insrnce_Cmp_No AND ROWNUM <= 1)
               Ins_Cmp_Nm,
           M.Insrnce_Card_No,
           M.Insrnce_Card_No_Fmly,
           M.Cntrct_No,
           M.Stand_By,
           M.Ref_No,
           M.Paid_Bill,
              M.Paid_U_Id
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (U_A_Name, U_E_Name),
                              NVL (U_E_Name, U_A_Name))
                 FROM User_R
                WHERE U_Id = M.Paid_U_Id AND ROWNUM <= 1)
               Paid_U_Nm,
           M.Paid_Date,
           M.Rec_Inv_Bill,
           M.Rec_Inv_U_Id,
           M.Rec_Inv_Date,
           M.Audit_Ref,
           M.C_Tel,
           M.Ptnt_No,
           M.Dctr_No,
           M.Doc_No_Admson,
           NULL
               V_CODE_Csh,
              M.Bill_Doc_Type_No
           || ' - '
           || (SELECT Flg_Desc
                 FROM S_Flags
                WHERE     Flg_Code = 'TYPE_NAME'
                      AND Lang_No = Lng.Lng_No
                      AND Flg_Value = M.Bill_Doc_Type_No
                      AND ROWNUM <= 1)
               Bill_Doc_Type,
           M.Doc_Date,
           M.Half_No,
           M.Qrtr_No,
              M.Prd_No
           || '-'
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Prd_L_Nm, Prd_F_Nm),
                              NVL (Prd_F_Nm, Prd_L_Nm))
                 FROM S_Prd_Dtl
                WHERE Prd_No = M.Prd_No AND ROWNUM <= 1)
               Prd_Nm,
           M.Week_No,
           M.Day_No,
              M.Cash_No
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Cash_Name, Cash_E_Name),
                              NVL (Cash_E_Name, Cash_Name))
                 FROM Cash_In_Hand
                WHERE Cash_No = M.Cash_No AND ROWNUM <= 1)
               Cash_Nm,
           M.Cst_Code,
           M.Cst_Code || ' - ' || M.Cst_Nm
               V_CODE_Name,
           I.I_Code
               Itm_Code,
           DECODE (Lng.Lng_No, 1, I.I_Name, NVL (I.I_E_Name, I.I_Name))
               Itm_Nm,
             (Select Itm_Unt From Ias_Itm_Dtl Where Ias_Itm_Dtl.I_Code = I.I_Code And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 And RowNum <= 1 ) Itm_Unt ,
             (SELECT ITM_UNT FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND LVL_UNIT = ( SELECT MAX (LVL_UNIT)FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1)MAX_ITM_UNT ,
             (SELECT P_SIZE  FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND ITM_UNT  = ( SELECT ITM_UNT FROM IAS_ITM_DTL WHERE     I_CODE = I.I_CODE AND LVL_UNIT = (SELECT MAX (LVL_UNIT) FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1) AND ROWNUM <= 1) MAX_P_SIZE ,               
           I.G_Code,
              I.G_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
                              1, NVL (Grp.G_A_NAME, Grp.G_E_NAME),
                              NVL (Grp.G_E_NAME, Grp.G_A_NAME))
                          Grp_Code_Nm
                 FROM GROUP_DETAILS Grp
                WHERE G_Code = I.G_Code AND ROWNUM <= 1)
               Grp_Code_Nm,
           I.Mng_Code,
              I.Mng_Code
           || ' - '
           || (SELECT DECODE (Lng.Lng_No,
