               Tax_Amt_L,
           ROUND (NVL (M.Othr_Amt, 0), 2)
               Othr_Amt,
           ROUND (NVL (M.Othr_Amt, 0) * NVL (Cur_Rate, 1), 2)
               Othr_Amt_L,
           ROUND (NVL (M.Net_Bill_Amt, 0), 2)
               Net_Bill_Amt,
           ROUND (NVL (M.Net_Bill_Amt, 0) * NVL (Cur_Rate, 1), 2)
               Net_Bill_Amt_L,
           ROUND (NVL (M.Net_Bill_Amt_No_Tax, 0), 2)
               Net_Bill_Amt_No_Tax,
           ROUND (NVL (M.Net_Bill_Amt_No_Tax, 0) * NVL (Cur_Rate, 1), 2)
               Net_Bill_Amt_No_Taxt_L,
           ROUND (NVL (M.Net_Stk_Amt_L, 0), 2)
               Net_Stk_Amt_L,
           ROUND (NVL (M.Net_Bill_Amt_Stk, 0), 2)
               Net_Bill_Amt_Stk,
           ROUND (NVL (M.Net_Bill_Amt_Stk_No_Disc, 0), 2)
               Net_Bill_Amt_Stk_No_Disc,
           ROUND (NVL (M.Net_Stk_Amt_Stk, 0), 2)
               Net_Stk_Amt_Stk,
           ROUND (
                 (  ABS (NVL (M.Net_Bill_Amt_Stk, 0))
                  - ABS (NVL (M.Net_Stk_Amt_Stk, 0)))
               * DECODE (M.DOC_TYPE, 5, -1, 1),
               2)
               Net_Proft_Amt_Stk,
           ROUND (
                 (  ABS (NVL (M.Net_Bill_Amt_Stk, 0))
                  - ABS (NVL (M.Net_Stk_Amt_Stk, 0)))
               * NVL (Cur_Rate, 1)
               * IN_OUT,
               2)
               Net_Proft_Amt_L,
           CASE
               WHEN NVL (SUM_Net_Bill_Amt, 0) <> 0
               THEN
                   ROUND ((M.AC_AMT / SUM_Net_Bill_Amt) * M.Net_Bill_AmT, 2)
               ELSE
                   0
           END
               AC_AMT,
           CASE
               WHEN NVL (SUM_Net_Bill_Amt, 0) <> 0
               THEN
