                   WHEN M.Bill_Doc_Type_No = 4
                   THEN
                         (  ABS (M.Net_Bill_Amt)
                          - ABS (
                                CASE
                                    WHEN NVL (SUM_Net_Bill_Amt, 0) <> 0
                                    THEN
                                        ROUND (
                                              (M.AC_AMT / SUM_Net_Bill_Amt)
                                            * M.Net_Bill_AmT,
                                            2)
                                    ELSE
                                        0
                                END)
                          - ABS (
                                CASE
                                    WHEN NVL (SUM_Net_Bill_Amt, 0) <> 0
                                    THEN
                                        ROUND (
                                              (  M.CHEQUE_AMT
                                               / SUM_Net_Bill_Amt)
                                            * M.Net_Bill_AmT,
                                            2)
                                    ELSE
