                               I_Price,
                           (NVL (D.P_Qty, 0))
                               I_Qty,
                           (NVL (D.Free_Qty, 0) * NVL (D.P_Size, 1))
                               Free_Qty,
                           (NVL (D.I_Price, 0) * NVL (D.I_Qty, 0))
                               Amt,
                           (NVL (D.Dis_Amt, 0) * NVL (D.I_Qty, 0))
                               Dscnt_Amt,
                           (  (NVL (D.Vat_Amt, 0) + NVL (D.Vat_Amt_Othr, 0))
                            * NVL (D.I_Qty, 0))
                               Tax_Amt,
                           (NVL (D.Othr_Amt, 0) * NVL (D.I_Qty, 0))
                               Othr_Amt,
                           ROUND (
                                 (NVL (I_Price, 0) * NVL (I_Qty, 0))
                               + (  NVL (D.Othr_Amt, 0)
                                  * DECODE (Bill_Amt,
                                            0, NVL (Free_Qty, 0),
                                            NVL (I_Qty, 0)))
                               + (  NVL (D.Vat_Amt, 0)
                                  * (  NVL (I_Qty, 0)
                                     + (  NVL (Free_Qty, 0)
                                        * NVL (Clc_Tax_Free_Qty_Flg, 0))))
                               + (NVL (D.Vat_Amt_Othr, 0) * NVL (I_Qty, 0))
                               - (  (NVL (D.Dis_Amt, 0) * NVL (I_Qty, 0))
                                  + (  NVL (D.Othr_Amt_Disc, 0)
                                     * DECODE (Bill_Amt,
                                               0, NVL (Free_Qty, 0),
                                               NVL (I_Qty, 0)))),
                               4)
                               Net_Bill_Amt,
                           ROUND (
