                               Doc_Brn_No,
                           M.Ad_U_Id,
                           D.Expire_Date,
                           D.Batch_No,
                           M.A_Code,
                           NULL
                               AV_CODE_Dtl,
                           NULL
                               Cr_Card_No,
                           NULL
                               Insrnce_Cmp_No,
                           NULL
                               Insrnce_Card_No,
                           NULL
                               Insrnce_Card_No_Fmly,
                           NULL
                               Cntrct_No,
                           NULL
                               Stand_By,
                           M.Ref_No,
                           NULL
                               Paid_Bill,
                           NULL
                               Paid_U_Id,
                           NULL
                               Paid_Date,
                           NULL
                               Rec_Inv_Bill,
                           NULL
                               Rec_Inv_U_Id,
                           NULL
                               Rec_Inv_Date,
                           M.Audit_Ref,
                           NULL
                               C_Tel,
                           NULL
                               Ptnt_No,
                           NULL
                               Dctr_No,
                           NULL
                               Doc_No_Admson,
                           NULL
                               V_CODE_Csh,
                           M.Rt_Bill_Date
                               Doc_Date,
                           ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q') / 2)
                               Half_No,
                           ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q'))
                               Qrtr_No,
                           TO_CHAR (M.Rt_Bill_Date, 'MM')
                               Prd_No,
                           TO_CHAR (M.Rt_Bill_Date, 'WW')
                               Week_No,
                           TO_CHAR (M.Rt_Bill_Date, 'DD')
                               Day_No,
                           NVL (AC_AMT, 0) * -1
                               AC_AMT,
                           NVL (CHEQUE_AMT, 0) * -1
                               CHEQUE_AMT,
                           NULL
                               BNK_AMT_DTL,
                           -1
                               IN_OUT,
                           M.Rt_Bill_Currency
                               Cur_Code,
                           M.Rt_Bill_Rate
                               Cur_Rate,
                           M.Stock_Rate,
                           NULL
                               Emp_no,
                           M.RT_BILL_NO
                               DOC_NO,
                           M.RT_BILL_SER
                               DOC_SER,
                           D.RCRD_NO,
                           D.SI_RCRD_NO
                               SI_RCRD_NO,
                           M.P_YEAR,
                           NVL (D.BILL_NO, D.RT_BILL_NO)
                               BILL_NO,
                           NVL (D.BILL_SER, D.RT_BILL_SER)
                               BILL_SER,
                           M.Cash_No,
                           M.V_CODE
                               Cst_Code,
                           M.V_Name
                               Cst_Nm,
                           D.I_Code
                               Itm_Code,
                           NULL
                               Rep_Code,
                           NULL
                               Col_No,
                           NULL
                               Driver_No,
                           NULL
                               Prm_Code,
                           NULL
                               R_Code,
                           D.Cmp_No,
                           D.W_Code,
                           D.CC_CODE,
                           D.Pj_No,
                           D.Actv_No,
                           NULL
                               External_Post,
                           1
                               Itm_Size,
                           D.P_SIZE,
                           (D.Stk_Cost / D.P_SIZE)
                               Stk_Cost,
                           (D.I_Price / D.P_SIZE)
                               I_Price,
                           (NVL (D.P_Qty, 0)) * -1
                               I_Qty,
                           (NVL (D.Free_Qty, 0) * NVL (D.P_Size, 1)) * -1
                               Free_Qty,
                           (NVL (D.I_Price, 0) * NVL (D.I_Qty, 0)) * -1
                               Amt,
                           (NVL (D.Dis_Amt, 0) * NVL (D.I_Qty, 0)) * -1
                               Dscnt_Amt,
                             (  (NVL (D.Vat_Amt, 0) + NVL (D.Vat_Amt_Othr, 0))
                              * NVL (D.I_Qty, 0))
                           * -1
                               Tax_Amt,
                           (NVL (D.Othr_Amt, 0) * NVL (D.I_Qty, 0)) * -1
                               Othr_Amt,
                             ROUND (
                                   (NVL (I_Price, 0) * NVL (I_Qty, 0))
                                 + (  NVL (D.Othr_Amt, 0)
                                    * DECODE (Bill_Amt,
                                              0, NVL (Free_Qty, 0),
                                              NVL (I_Qty, 0)))
                                 + (  NVL (D.Vat_Amt, 0)
                                    * (  NVL (I_Qty, 0)
                                       + (  NVL (Free_Qty, 0)
                                          * NVL (Clc_Tax_Free_Qty_Flg, 0))))
                                 + (NVL (D.Vat_Amt_Othr, 0) * NVL (I_Qty, 0))
                                 - (  (NVL (D.Dis_Amt, 0) * NVL (I_Qty, 0))
                                    + (  NVL (D.Othr_Amt_Disc, 0)
                                       * DECODE (Bill_Amt,
                                                 0, NVL (Free_Qty, 0),
                                                 NVL (I_Qty, 0)))),
                                 4)
                           * -1
                               Net_Bill_Amt,
                             ROUND (
                                   (NVL (I_Price, 0) * NVL (I_Qty, 0))
                                 + (  NVL (D.Othr_Amt, 0)
                                    * DECODE (Bill_Amt,
                                              0, NVL (Free_Qty, 0),
                                              NVL (I_Qty, 0)))
                                 - (  (NVL (D.Dis_Amt, 0) * NVL (I_Qty, 0))
                                    + (  NVL (D.Othr_Amt_Disc, 0)
                                       * DECODE (Bill_Amt,
                                                 0, NVL (Free_Qty, 0),
                                                 NVL (I_Qty, 0)))),
                                 4)
                           * -1
                               Net_Bill_Amt_No_Tax --,ROUND(SUM( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))))OVER(PARTITION BY M.RT_BILL_SER ),2)*-1 SUM_Net_Bill_Amt
                                                  ,
                           0
                               SUM_Net_Bill_Amt,
                             (  (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                              * NVL (D.Stk_Cost, 0)
                              * NVL (M.Stock_Rate, 1))
                           * -1
                               Net_Stk_Amt_L,
                             (  (  (  NVL (D.I_Price, 0)
                                    + NVL (D.Othr_Amt, 0)
                                    - NVL (D.Dis_Amt, 0))
                                 * NVL (D.I_Qty, 0)
                                 * NVL (M.Rt_Bill_Rate, 1))
                              / NVL (M.Stock_Rate, 1))
                           * -1
                               Net_Bill_Amt_Stk,
                             (  (  (NVL (D.I_Price, 0))
                                 * NVL (D.I_Qty, 0)
                                 * NVL (M.Rt_Bill_Rate, 1))
                              / NVL (M.Stock_Rate, 1))
                           * -1
                               Net_Bill_Amt_Stk_No_Disc,
                             (  (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                              * NVL (D.Stk_Cost, 0))
                           * -1
                               Net_Stk_Amt_Stk
                      FROM Ias_PR_Bill_Mst M, Ias_PR_Bill_DTL D
                     WHERE M.Rt_Bill_Ser = D.Rt_Bill_Ser) M) M,
           Ias_Itm_Mst  I,
           Lng,
           V_DETAILS    cst
     WHERE     M.Itm_Code = I.I_Code
           AND m.CST_CODE = cst.V_CODE(+)
           AND EXISTS
                   (SELECT 1
                      FROM Privilege_Wh
                     WHERE     Privilege_Wh.W_Code = M.W_Code
                           AND View_Flag = 1
                           AND U_Id = Lng.USR_NO
                           AND ROWNUM <= 1)
           AND EXISTS
                   (SELECT 1
                      FROM Privilege_Gc
                     WHERE     Privilege_Gc.G_Code = I.G_Code
                           AND View_Flag = 1
                           AND U_Id = Lng.USR_NO
                           AND ROWNUM <= 1)
           AND 1 =
               CASE
                   WHEN M.CC_CODE IS NULL
                   THEN
                       1
                   ELSE
                       (SELECT 1
                          FROM Privilege_Cc
                         WHERE     Privilege_Cc.CC_CODE = M.CC_CODE
                               AND View_Flag = 1
                               AND U_Id = Lng.USR_NO
                               AND ROWNUM <= 1)
               END
           AND 1 =
               CASE
                   WHEN M.Pj_No IS NULL
                   THEN
                       1
                   ELSE
                       (SELECT 1
                          FROM Ias_Priv_Projects
                         WHERE     Ias_Priv_Projects.Pj_No = M.Pj_No
                               AND View_Flag = 1
                               AND U_Id = Lng.USR_NO
                               AND ROWNUM <= 1)
               END
           AND 1 =
               CASE
                   WHEN M.Actv_No IS NULL
                   THEN
                       1
                   ELSE
                       (SELECT 1
                          FROM Ias_Priv_Actvty
                         WHERE     M.Actv_No = Ias_Priv_Actvty.Actv_No
                               AND View_Flag = 1
                               AND U_Id = Lng.USR_NO
                               AND ROWNUM <= 1)
               END
           AND EXISTS
                   (SELECT 1
                      FROM S_Brn_Usr_Priv
                     WHERE     S_Brn_Usr_Priv.Brn_No = M.Brn_No
                           AND View_Flag = 1
                           AND U_Id = Lng.USR_NO
                           AND ROWNUM <= 1)
           AND 1 =
               CASE
                   WHEN M.CST_CODE IS NULL
                   THEN
                       1
                   ELSE
                       (SELECT 1
                          FROM Ias_Priv_VENDOR
                         WHERE     Ias_Priv_VENDOR.V_CODE = M.CST_CODE
                               AND View_Flag = 1
                               AND U_Id = Lng.USR_NO
                               AND ROWNUM <= 1)
               END;


--
-- APS_KPI_NET_PRCHS_PRD_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_NET_PRCHS_PRD_VW
(YR_NO, BRN_NO, BRN_NM, PRD_NO, PRD_NM, 
 CUR_CODE, VNDR_CODE, VNDR_NM, PMAN_CODE, PMAN_NM, 
 W_CODE, W_NM, MN_GRP_CODE, SUB_GRP_CODE, UNDR_SUB_GRP_CODE, 
 ASSTNT_GRP_CODE, DTL_GRP_CODE, ALTRNTV_GRP_CODE, ITM_TYP, ITM_CLSSFCTN, 
 CC_CODE, CC_NM, PJ_NO, PJ_NM, ACTV_NO, 
 ACTV_NM, PRCHS_AMT_L, PRCHS_AMT_F, PRCHS_DSCNT_AMT_L, PRCHS_DSCNT_AMT_F, 
 PRCHS_TAX_AMT_L, PRCHS_TAX_AMT_F, PRCHS_OTHR_AMT_L, PRCHS_OTHR_AMT_F, RT_PRCHS_AMT_L, 
 RT_PRCHS_AMT_F, RT_PRCHS_DSCNT_AMT_L, RT_PRCHS_DSCNT_AMT_F, RT_PRCHS_TAX_AMT_L, RT_PRCHS_TAX_AMT_F, 
 RT_PRCHS_OTHR_AMT_L, RT_PRCHS_OTHR_AMT_F, NET_PRCHS_NOT_TAX_OTHR_AMT_L, NET_PRCHS_NOT_TAX_OTHR_AMT_F, NET_PRCHS_AMT_L, 
 NET_PRCHS_AMT_F, NET_BILL_AMT_L, NET_STK_AMT_L, NET_PROFT_AMT_L, NET_BILL_AMT_STK, 
 NET_STK_AMT_STK, NET_PROFT_AMT_STK)
BEQUEATH DEFINER
AS 
SELECT M.YR_NO,
             M.BRN_NO,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (BRN_LNAME, BRN_FNAME),
                         NVL (BRN_FNAME, BRN_LNAME))
                FROM S_BRN
               WHERE BRN_NO = M.BRN_NO)
                 BRN_NM,
             M.PRD_NO,
             (SELECT    LPAD (PRD_NO, 2, '0')
                     || '-'
                     || DECODE (
                            NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                 1),
                            1, PRD_L_NM,
                            NVL (PRD_F_NM, PRD_L_NM))
                FROM S_PRD_DTL
               WHERE PRD_NO = M.PRD_NO)
                 PRD_NM,
             --M.HALF_NO,
             --M.QRTR_NO,
             --M.WEEK_NO,
             --M.DAY_NO,
             M.CUR_CODE,
             M.VNDR_CODE,
             M.VNDR_NM,
             --M.ITM_CODE,
             --M.ITM_NM,
             M.PMAN_CODE,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (PMAN_A_NAME, PMAN_E_NAME),
                         NVL (PMAN_E_NAME, PMAN_A_NAME))
                FROM IAS_PURCHS_MAN
               WHERE PMAN_CODE = M.PMAN_CODE)
                 PMAN_NM,
             M.W_CODE,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (W_NAME, W_E_NAME),
                         NVL (W_E_NAME, W_NAME))
                FROM WAREHOUSE_DETAILS
               WHERE W_CODE = M.W_CODE)
                 W_NM,
             M.MN_GRP_CODE,
             M.SUB_GRP_CODE,
             M.UNDR_SUB_GRP_CODE,
             M.ASSTNT_GRP_CODE,
             M.DTL_GRP_CODE,
             M.ALTRNTV_GRP_CODE,
             M.ITM_TYP,
             M.ITM_CLSSFCTN,
             M.CC_CODE,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (CC_A_NAME, CC_E_NAME),
                         NVL (CC_E_NAME, CC_A_NAME))
                FROM COST_CENTERS
               WHERE CC_CODE = M.CC_CODE)
                 CC_NM,
             M.PJ_NO,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (PJ_A_NAME, PJ_E_NAME),
                         NVL (PJ_A_NAME, PJ_E_NAME))
                FROM IAS_PROJECTS
               WHERE PJ_NO = M.PJ_NO)
                 PJ_NM,
             M.ACTV_NO,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (ACTV_A_NAME, ACTV_E_NAME),
                         NVL (ACTV_E_NAME, ACTV_A_NAME))
                FROM IAS_ACTVTY
               WHERE ACTV_NO = M.ACTV_NO)
                 ACTV_NM,
             SUM (M.PRCHS_AMT_L)
                 PRCHS_AMT_L,
             SUM (M.PRCHS_AMT_F)
                 PRCHS_AMT_F,
             SUM (M.PRCHS_DSCNT_AMT_L)
                 PRCHS_DSCNT_AMT_L,
             SUM (M.PRCHS_DSCNT_AMT_F)
                 PRCHS_DSCNT_AMT_F,
             SUM (M.PRCHS_TAX_AMT_L)
                 PRCHS_TAX_AMT_L,
             SUM (M.PRCHS_TAX_AMT_F)
                 PRCHS_TAX_AMT_F,
             SUM (M.PRCHS_OTHR_AMT_L)
                 PRCHS_OTHR_AMT_L,
             SUM (M.PRCHS_OTHR_AMT_F)
                 PRCHS_OTHR_AMT_F,
             SUM (M.RT_PRCHS_AMT_L)
                 RT_PRCHS_AMT_L,
             SUM (M.RT_PRCHS_AMT_F)
                 RT_PRCHS_AMT_F,
             SUM (M.RT_PRCHS_DSCNT_AMT_L)
                 RT_PRCHS_DSCNT_AMT_L,
             SUM (M.RT_PRCHS_DSCNT_AMT_F)
                 RT_PRCHS_DSCNT_AMT_F,
             SUM (M.RT_PRCHS_TAX_AMT_L)
                 RT_PRCHS_TAX_AMT_L,
             SUM (M.RT_PRCHS_TAX_AMT_F)
                 RT_PRCHS_TAX_AMT_F,
             SUM (M.RT_PRCHS_OTHR_AMT_L)
                 RT_PRCHS_OTHR_AMT_L,
             SUM (M.RT_PRCHS_OTHR_AMT_F)
                 RT_PRCHS_OTHR_AMT_F,
             ROUND (
                   SUM ((M.PRCHS_AMT_L) - (M.PRCHS_DSCNT_AMT_L))
                 - SUM ((M.RT_PRCHS_AMT_L) - (M.RT_PRCHS_DSCNT_AMT_L)),
                 4)
                 NET_PRCHS_NOT_TAX_OTHR_AMT_L,
             ROUND (
                   SUM ((M.PRCHS_AMT_F) - (M.PRCHS_DSCNT_AMT_F))
                 - SUM ((M.RT_PRCHS_AMT_F) - (M.RT_PRCHS_DSCNT_AMT_F)),
                 4)
                 NET_PRCHS_NOT_TAX_OTHR_AMT_F,
               ROUND (
                     SUM (M.PRCHS_AMT_L)
                   - SUM (M.PRCHS_DSCNT_AMT_L)
                   + SUM (M.PRCHS_OTHR_AMT_L),
                   4)
             - ROUND (
                     SUM (M.RT_PRCHS_AMT_L)
                   - SUM (M.RT_PRCHS_DSCNT_AMT_L)
                   + SUM (M.RT_PRCHS_OTHR_AMT_L),
                   4)
                 NET_PRCHS_AMT_L,
               ROUND (
                     SUM (M.PRCHS_AMT_F)
                   - SUM (M.PRCHS_DSCNT_AMT_F)
                   + SUM (M.PRCHS_OTHR_AMT_F),
                   4)
             - ROUND (
                     SUM (M.RT_PRCHS_AMT_F)
                   - SUM (M.RT_PRCHS_DSCNT_AMT_F)
                   + SUM (M.RT_PRCHS_OTHR_AMT_F),
                   4)
                 NET_PRCHS_AMT_F,
             SUM (M.NET_BILL_AMT_L)
                 NET_BILL_AMT_L,
             SUM (M.NET_STK_AMT_L)
                 NET_STK_AMT_L,
             ROUND (SUM (M.NET_BILL_AMT_L) - SUM (M.NET_STK_AMT_L), 4)
                 NET_PROFT_AMT_L,
             SUM (M.NET_BILL_AMT_STK)
                 NET_BILL_AMT_STK,
             SUM (M.NET_STK_AMT_STK)
                 NET_STK_AMT_STK,
             ROUND (SUM (M.NET_BILL_AMT_STK) - SUM (M.NET_STK_AMT_STK), 4)
                 NET_PROFT_AMT_STK
        FROM (  SELECT M.BRN_YEAR
                           YR_NO,
                       M.BRN_NO,
                       TO_CHAR (M.BILL_DATE, 'MM')
                           PRD_NO,
                       --ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2) HALF_NO,
                       --ROUND (TO_CHAR (M.BILL_DATE, 'Q')) QRTR_NO,
                       --TO_CHAR (M.BILL_DATE, 'WW') WEEK_NO,
                       --TO_CHAR (M.BILL_DATE, 'DD') DAY_NO,
                       M.BILL_CURRENCY
                           CUR_CODE,
                       M.V_CODE
                           VNDR_CODE,
                       --NVL (M.C_NAME,IAS_CST_PKG.GET_C_NAME ( P_C_CODE => M.C_CODE,P_LNG_NO => IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'))) CST_NM,
                       M.V_NAME
                           VNDR_NM, /*
                        I.I_CODE
                            ITM_CODE,
                        DECODE (
                            NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                            1, I.I_NAME,
                            NVL (I.I_E_NAME, I.I_NAME))
                            ITM_NM,*/
                       M.PMAN_CODE
                           PMAN_CODE,
                       D.W_CODE,
                       I.G_CODE
                           MN_GRP_CODE,
                       I.MNG_CODE
                           SUB_GRP_CODE,
                       I.SUBG_CODE
                           UNDR_SUB_GRP_CODE,
                       I.ASSISTANT_NO
                           ASSTNT_GRP_CODE,
                       I.DETAIL_NO
                           DTL_GRP_CODE,
                       I.GROUP_NO
                           ALTRNTV_GRP_CODE,
                       I.ITEM_TYPE
                           ITM_TYP,
                       I.GRP_CLASS_CODE
                           ITM_CLSSFCTN,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO,
                       ROUND (
                           SUM (
                                 NVL (D.I_PRICE, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           PRCHS_AMT_L,
                       ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           PRCHS_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.DIS_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           PRCHS_DSCNT_AMT_L,
                       ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PRCHS_DSCNT_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.VAT_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           PRCHS_TAX_AMT_L,
                       ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PRCHS_TAX_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.OTHR_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           PRCHS_OTHR_AMT_L,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PRCHS_OTHR_AMT_F,
                       0
                           RT_PRCHS_AMT_L,
                       0
                           RT_PRCHS_AMT_F,
                       0
                           RT_PRCHS_DSCNT_AMT_L,
                       0
                           RT_PRCHS_DSCNT_AMT_F,
                       0
                           RT_PRCHS_TAX_AMT_L,
                       0
                           RT_PRCHS_TAX_AMT_F,
                       0
                           RT_PRCHS_OTHR_AMT_L,
                       0
                           RT_PRCHS_OTHR_AMT_F,
                       ROUND (
                           SUM (
                                 (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           NET_BILL_AMT_L,
                       ROUND (
                           SUM (
                                 (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                               * NVL (D.STK_COST, 0)
                               * NVL (M.STOCK_RATE, 1)),
                           4)
                           NET_STK_AMT_L,
                       ROUND (
                           SUM (
                                 (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                  * NVL (D.I_QTY, 0)
                                  * NVL (M.BILL_RATE, 1))
                               / NVL (M.STOCK_RATE, 1)),
                           4)
                           NET_BILL_AMT_STK,
                       ROUND (
                           SUM (
                                 (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                               * NVL (D.STK_COST, 0)),
                           4)
                           NET_STK_AMT_STK
                  FROM IAS_PI_BILL_MST M, IAS_Pi_BILL_DTL D, IAS_ITM_MST I
                 WHERE M.BILL_SER = D.BILL_SER AND D.I_CODE = I.I_CODE
              GROUP BY M.BRN_YEAR,
                       M.BRN_NO,
                       TO_CHAR (M.BILL_DATE, 'MM'),
                       --ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2),
                       --ROUND (TO_CHAR (M.BILL_DATE, 'Q')),
                       --TO_CHAR (M.BILL_DATE, 'WW'),
                       --TO_CHAR (M.BILL_DATE, 'DD'),
                       M.BILL_CURRENCY,
                       M.V_CODE,
                       --NVL (M.C_NAME,IAS_CST_PKG.GET_C_NAME ( P_C_CODE => M.C_CODE,P_LNG_NO => IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'))) ,
                       M.V_NAME,
                       M.PMAN_CODE,
                       D.W_CODE,
                       I.G_CODE,
                       I.MNG_CODE,
                       I.SUBG_CODE,
                       I.ASSISTANT_NO,
                       I.DETAIL_NO,
                       I.GROUP_NO,
                       I.ITEM_TYPE,
                       I.GRP_CLASS_CODE,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO
              UNION ALL
                SELECT M.BRN_YEAR
                           YR_NO,
                       M.BRN_NO,
                       TO_CHAR (M.RT_BILL_DATE, 'MM')
                           PRD_NO,
                       --ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2) HALF_NO,
                       --ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q')) QRTR_NO,
                       --TO_CHAR (M.RT_BILL_DATE, 'WW') WEEK_NO,
                       --TO_CHAR (M.RT_BILL_DATE, 'DD') DAY_NO,
                       M.RT_BILL_CURRENCY
                           CUR_CODE,
                       M.V_CODE
                           VNDR_CODE,
                       --NVL (M.C_NAME,IAS_CST_PKG.GET_C_NAME (P_C_CODE => M.C_CODE,P_LNG_NO => IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'))) CST_NM,
                       M.V_NAME
                           VNDR_NM, /*
                         I.I_CODE
                             ITM_CODE,
                         DECODE (
                             NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                             1, I.I_NAME,
                             NVL (I.I_E_NAME, I.I_NAME))
                             ITM_NM,*/
                       M.PMAN_CODE
                           PMAN_CODE,
                       --IAS_SMAN_PKG.GET_SMAN_NAME (P_REP_CODE => M.REP_CODE ,P_LNG_NO => IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT')) SMAN_NM,
                       D.W_CODE,
                       I.G_CODE
                           MN_GRP_CODE,
                       I.MNG_CODE
                           SUB_GRP_CODE,
                       I.SUBG_CODE
                           UNDR_SUB_GRP_CODE,
                       I.ASSISTANT_NO,
                       I.DETAIL_NO
                           DTL_GRP_CODE,
                       I.GROUP_NO
                           ALTRNTV_GRP_CODE,
                       I.ITEM_TYPE
                           ITM_TYP,
                       I.GRP_CLASS_CODE
                           ITM_CLSSFCTN,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO,
                       0
                           PRCHS_AMT_L,
                       0
                           PRCHS_AMT_F,
                       0
                           PRCHS_DSCNT_AMT_L,
                       0
                           PRCHS_DSCNT_AMT_F,
                       0
                           PRCHS_TAX_AMT_L,
                       0
                           PRCHS_TAX_AMT_F,
                       0
                           PRCHS_OTHR_AMT_L,
                       0
                           PRCHS_OTHR_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.I_PRICE, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.RT_BILL_RATE, 1)),
                           4)
                           RT_PRCHS_AMT_L,
                       ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PRCHS_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.DIS_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.RT_BILL_RATE, 1)),
                           4)
                           RT_PRCHS_DSCNT_AMT_L,
                       ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PRCHS_DSCNT_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.VAT_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.RT_BILL_RATE, 1)),
                           4)
                           RT_PRCHS_TAX_AMT_L,
                       ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PRCHS_TAX_AMT_F,
                       ROUND (
                           SUM (
                                 NVL (D.OTHR_AMT, 0)
                               * NVL (D.I_QTY, 0)
                               * NVL (M.RT_BILL_RATE, 1)),
                           4)
                           RT_PRCHS_OTHR_AMT_L,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PRCHS_OTHR_AMT_F,
                         ROUND (
                             SUM (
                                   (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                 * NVL (D.I_QTY, 0)
                                 * NVL (M.RT_BILL_RATE, 1)),
                             4)
                       * -1
                           NET_BILL_AMT_L,
                         ROUND (
                             SUM (
                                   (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                                 * NVL (D.STK_COST, 0)
                                 * NVL (M.STOCK_RATE, 1)),
                             4)
                       * -1
                           NET_STK_AMT_L,
                         ROUND (
                             SUM (
                                   (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                    * NVL (D.I_QTY, 0)
                                    * NVL (M.RT_BILL_RATE, 1))
                                 / NVL (M.STOCK_RATE, 1)),
                             4)
                       * -1
                           NET_BILL_AMT_STK,
                         ROUND (
                             SUM (
                                   (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                                 * NVL (D.STK_COST, 0)),
                             4)
                       * -1
                           NET_STK_AMT_STK
                  FROM IAS_PR_BILL_MST M, IAS_PR_BILL_DTL D, IAS_ITM_MST I
                 WHERE M.RT_BILL_SER = D.RT_BILL_SER AND D.I_CODE = I.I_CODE
              GROUP BY M.BRN_YEAR,
                       M.BRN_NO,
                       TO_CHAR (M.RT_BILL_DATE, 'MM'),
                       --ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2),
                       --ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q')),
                       --TO_CHAR (M.RT_BILL_DATE, 'WW'),
                       --TO_CHAR (M.RT_BILL_DATE, 'DD'),
                       M.RT_BILL_CURRENCY,
                       M.V_CODE,
                       --NVL (M.C_NAME,IAS_CST_PKG.GET_C_NAME (P_C_CODE => M.C_CODE,P_LNG_NO => IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'))),
                       M.V_NAME,
                       M.PMAN_CODE,
                       D.W_CODE,
                       I.G_CODE,
                       I.MNG_CODE,
                       I.SUBG_CODE,
                       I.ASSISTANT_NO,
                       I.DETAIL_NO,
                       I.GROUP_NO,
                       I.ITEM_TYPE,
                       I.GRP_CLASS_CODE,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO) M
       WHERE 1 = 1
    GROUP BY M.YR_NO,
             M.BRN_NO,
             M.PRD_NO,
             --M.HALF_NO,
             --M.QRTR_NO,
             --M.WEEK_NO,
             --M.DAY_NO,
             M.CUR_CODE,
             M.VNDR_CODE,
             M.VNDR_NM,
             --M.ITM_CODE,
             --M.ITM_NM,
             M.PMAN_CODE,
             M.W_CODE,
             M.MN_GRP_CODE,
             M.SUB_GRP_CODE,
             M.UNDR_SUB_GRP_CODE,
             M.ASSTNT_GRP_CODE,
             M.DTL_GRP_CODE,
             M.ALTRNTV_GRP_CODE,
             M.ITM_TYP,
             M.ITM_CLSSFCTN,
             M.CC_CODE,
             M.PJ_NO,
             M.ACTV_NO;


--
-- APS_KPI_NET_PURCHS_DTL_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_NET_PURCHS_DTL_VW
(YR_NO, BRN_NO, BRN_NM, BILL_DOC_TYPE, DOC_DATE, 
 HALF_NO, QRTR_NO, PRD_NO, PRD_NM, WEEK_NO, 
 DAY_NO, CUR_CODE, CASH_NO, CASH_NM, ITM_CODE, 
 ITM_NM, G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, 
 SUBG_CODE, SUBG_CODE_NM, ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, 
 ALTRNTV_GRP_NM, ITM_TYP_NM, GRP_CLASS_NM, ITM_DSC, W_CODE, 
 W_NM, V_CODE, V_NM, SMAN_CODE, SMAN_NM, 
 CC_CODE, CC_NM, PJ_NO, PJ_NM, ACTV_NO, 
 ACTV_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITM_UNT, ITM_SIZE, MAX_ITM_UNT, MAX_P_SIZE, 
 ITM_QTY, ITM_FREE_QTY, RT_ITM_QTY, RT_ITM_FREE_QTY, NET_ITM_QTY, 
 NET_ITM_FREE_QTY, PUR_AMT_L, PUR_AMT_F, PUR_DSCNT_AMT_L, PUR_DSCNT_AMT_F, 
 PUR_TAX_AMT_L, PUR_TAX_AMT_F, PUR_OTHR_AMT_L, PUR_OTHR_AMT_F, RT_PUR_AMT_L, 
 RT_PUR_AMT_F, RT_PUR_DSCNT_AMT_L, RT_PUR_DSCNT_AMT_F, RT_PUR_TAX_AMT_L, RT_PUR_TAX_AMT_F, 
 RT_PUR_OTHR_AMT_L, RT_PUR_OTHR_AMT_F, NET_PUR_AMT_L, NET_PUR_AMT_F, NET_BILL_AMT_L, 
 NET_STK_AMT_L, NET_BILL_AMT_STK, NET_STK_AMT_STK)
BEQUEATH DEFINER
AS 
WITH LNG
        AS
            (SELECT (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1) FROM DUAL)
                        LNG_NO
               FROM DUAL)
      SELECT M.YR_NO
            ,M.BRN_NO
            ,M.BRN_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME),NVL (BRN_FNAME, BRN_LNAME))
                                     FROM S_BRN
                                    WHERE BRN_NO = M.BRN_NO AND ROWNUM<=1)
                 BRN_NM
            ,M.BILL_DOC_TYPE || ' - ' || (SELECT FLG_DESC FROM S_FLAGS
                                           WHERE FLG_CODE = 'TYPE_NAME'
                                             AND LANG_NO = LNG.LNG_NO
                                             AND FLG_VALUE = M.BILL_DOC_TYPE 
                                             AND ROWNUM<=1) BILL_DOC_TYPE
            ,M.DOC_DATE
            ,M.HALF_NO
            ,M.QRTR_NO
            ,M.PRD_NO
            ,M.PRD_NO || '-' || (SELECT DECODE (LNG.LNG_NO,1, NVL (PRD_L_NM, PRD_F_NM),NVL (PRD_F_NM, PRD_L_NM))
                                                               FROM S_PRD_DTL
                                                              WHERE PRD_NO =M.PRD_NO AND ROWNUM <= 1) 
                PRD_NM
            ,M.WEEK_NO
            ,M.DAY_NO
            ,M.CUR_CODE
            ,M.CASH_NO
            ,M.CASH_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (CASH_NAME, CASH_E_NAME),NVL (CASH_E_NAME, CASH_NAME))
                                      FROM CASH_IN_HAND
                                     WHERE CASH_NO = M.CASH_NO
                                       AND ROWNUM<=1)
                 CASH_NM
            ,I.I_CODE
                 ITM_CODE
            ,DECODE (LNG.LNG_NO,1, I.I_NAME,NVL (I.I_E_NAME, I.I_NAME))
                 ITM_NM
            ,I.G_CODE
            ,I.G_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (GRP.G_A_NAME, GRP.G_E_NAME)
                                               ,NVL (GRP.G_E_NAME, GRP.G_A_NAME))
                                            GRP_NM
                                   FROM GROUP_DETAILS GRP
                                  WHERE GRP.G_CODE = I.G_CODE AND ROWNUM <= 1)
                 GRP_CODE_NM
            ,I.MNG_CODE
            ,I.MNG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                 ,1, NVL (GRP.MNG_A_NAME, GRP.MNG_E_NAME)
                                                 ,NVL (GRP.MNG_E_NAME, GRP.MNG_A_NAME))
                                              GRP_NM
                                     FROM IAS_MAINSUB_GRP_DTL GRP
                                    WHERE MNG_CODE = I.MNG_CODE
                                      AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                      AND ROWNUM <= 1)
                 MNG_CODE_NM
            ,I.SUBG_CODE
            ,I.SUBG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.SUBG_A_NAME, GRP.SUBG_E_NAME)
                                                  ,NVL (GRP.SUBG_E_NAME, GRP.SUBG_A_NAME))
                                               GRP_NM
                                      FROM IAS_SUB_GRP_DTL GRP
                                     WHERE SUBG_CODE = I.SUBG_CODE
                                       AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                       AND NVL (I.MNG_CODE, '0') =
                                       DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                       AND ROWNUM <= 1)
                 SUBG_CODE_NM
            ,I.ASSISTANT_NO
            ,I.ASSISTANT_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (GRP.ASSISTANT_A_NAME,GRP.ASSISTANT_E_NAME),NVL (GRP.ASSISTANT_E_NAME, GRP.ASSISTANT_A_NAME)) GRP_NM
                                          FROM IAS_ASSISTANT_GROUP GRP
                                         WHERE ASSISTANT_NO = I.ASSISTANT_NO
                                           AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                           AND NVL (I.MNG_CODE, '0') =
                                           DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                           AND NVL (I.SUBG_CODE, '0') =
                                           DECODE (NVL (SUBG_CODE, '0'), '0', NVL (I.SUBG_CODE, '0'), SUBG_CODE)
                                           AND ROWNUM <= 1)
                 ASSTNT_GRP_NM
            ,I.DETAIL_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.DETAIL_A_NAME, GRP.DETAIL_E_NAME)
                                                  ,NVL (GRP.DETAIL_E_NAME, GRP.DETAIL_A_NAME))
                                               GRP_NM
                                      FROM IAS_DETAIL_GROUP GRP
                                     WHERE DETAIL_NO = I.DETAIL_NO
                                       AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                       AND NVL (I.MNG_CODE, '0') =
                                       DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                       AND NVL (I.SUBG_CODE, '0') =
                                       DECODE (NVL (SUBG_CODE, '0'), '0', NVL (I.SUBG_CODE, '0'), SUBG_CODE)
                                       AND NVL (I.ASSISTANT_NO, '0') =
                                       DECODE (NVL (ASSISTANT_NO, '0'), '0', NVL (I.ASSISTANT_NO, '0'), ASSISTANT_NO)
                                       AND ROWNUM <= 1)
                 DTL_GRP_NM
            ,I.GROUP_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.GROUP_A_NAME,NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
                                       FROM IAS_ALTERNATIVE_GROUP A
                                      WHERE A.GROUP_NO = I.GROUP_NO 
                                        AND ROWNUM <= 1)
                 ALTRNTV_GRP_NM
            ,I.ITEM_TYPE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.IT_A_NAME,NVL (A.IT_E_NAME, A.IT_A_NAME))
                                        FROM ITEM_TYPES A
                                       WHERE A.TYPE_OF_ITEM = I.ITEM_TYPE 
                                         AND ROWNUM <= 1)
                 ITM_TYP_NM
            ,I.GRP_CLASS_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.GRP_L_NAME,NVL (A.GRP_F_NAME, A.GRP_L_NAME))
                                             FROM IAS_GRP_ITM_LVL A
                                            WHERE A.GRP_CODE = I.GRP_CLASS_CODE 
                                              AND ROWNUM <= 1)
                 GRP_CLASS_NM
            ,DECODE (LNG.LNG_NO,1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC))
                 ITM_DSC
            ,M.W_CODE
            ,M.W_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (W_NAME, W_E_NAME),NVL (W_E_NAME, W_NAME))
                                     FROM WAREHOUSE_DETAILS
                                    WHERE W_CODE = M.W_CODE 
                                      AND ROWNUM <= 1)
                 W_NM
            ,M.V_CODE
            ,M.V_NM
            ,M.SMAN_CODE
            ,M.SMAN_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (REPRS_A_NAME, REPRS_E_NAME),NVL (REPRS_E_NAME, REPRS_A_NAME))
                                                  FROM SALES_MAN
                                                 WHERE REPRS_CODE = M.SMAN_CODE
                                                   AND ROWNUM <= 1)
                           SMAN_NM
            ,M.CC_CODE
            ,M.CC_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                              ,1, NVL (CC_A_NAME, CC_E_NAME)
                                              ,NVL (CC_E_NAME, CC_A_NAME))
                                      FROM COST_CENTERS
                                     WHERE CC_CODE = M.CC_CODE 
                                       AND ROWNUM <= 1)
                 CC_NM
            ,M.PJ_NO
            ,M.PJ_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                            ,1, NVL (PJ_A_NAME, PJ_E_NAME)
                                            ,NVL (PJ_A_NAME, PJ_E_NAME))
                                    FROM IAS_PROJECTS
                                   WHERE PJ_NO = M.PJ_NO
                                     AND ROWNUM <= 1)
                 PJ_NM
            ,M.ACTV_NO
            ,M.ACTV_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                              ,1, NVL (ACTV_A_NAME, ACTV_E_NAME)
                                              ,NVL (ACTV_E_NAME, ACTV_A_NAME))
                                      FROM IAS_ACTVTY
                                     WHERE ACTV_NO = M.ACTV_NO
                                       AND ROWNUM <= 1)
                 ACTV_NM
            ,I.KIT_ITM
            ,I.USE_EXP_DATE
            ,I.USE_BATCH_NO
            ,I.USE_SERIALNO
            ,I.USE_ATTCH
            ,M.ITM_UNT
            ,M.ITM_SIZE
            ,(SELECT ITM_UNT
              FROM IAS_ITM_DTL
             WHERE     I_CODE = I.I_CODE
                   AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                     FROM IAS_ITM_DTL
                                    WHERE I_CODE = I.I_CODE)
                   AND ROWNUM <= 1)
               MAX_ITM_UNT
           ,(SELECT P_SIZE
              FROM IAS_ITM_DTL
             WHERE     I_CODE = I.I_CODE
                   AND ITM_UNT =
                       (SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE     I_CODE = I.I_CODE
                               AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                                 FROM IAS_ITM_DTL
                                                WHERE I_CODE = I.I_CODE)
                               AND ROWNUM <= 1)
                   AND ROWNUM <= 1)
               MAX_P_SIZE            
            ,NVL (M.ITM_QTY, 0)
                 ITM_QTY
            ,NVL (M.ITM_FREE_QTY, 0)
                 ITM_FREE_QTY
            ,NVL (M.RT_ITM_QTY, 0)
                 RT_ITM_QTY
            ,NVL (M.RT_ITM_FREE_QTY, 0)
                 RT_ITM_FREE_QTY
            ,NVL (M.ITM_QTY, 0) - NVL (M.RT_ITM_QTY, 0)
                 NET_ITM_QTY
            ,NVL (M.ITM_FREE_QTY, 0) - NVL (M.RT_ITM_FREE_QTY, 0)
                 NET_ITM_FREE_QTY
            ,M.PUR_AMT_L
                 PUR_AMT_L
            ,M.PUR_AMT_F
                 PUR_AMT_F
            ,M.PUR_DSCNT_AMT_L
                 PUR_DSCNT_AMT_L
            ,M.PUR_DSCNT_AMT_F
                 PUR_DSCNT_AMT_F
            ,M.PUR_TAX_AMT_L
                 PUR_TAX_AMT_L
            ,M.PUR_TAX_AMT_F
                 PUR_TAX_AMT_F
            ,M.PUR_OTHR_AMT_L
                 PUR_OTHR_AMT_L
            ,M.PUR_OTHR_AMT_F
                 PUR_OTHR_AMT_F
            ,M.RT_PUR_AMT_L
                 RT_PUR_AMT_L
            ,M.RT_PUR_AMT_F
                 RT_PUR_AMT_F
            ,M.RT_PUR_DSCNT_AMT_L
                 RT_PUR_DSCNT_AMT_L
            ,M.RT_PUR_DSCNT_AMT_F
                 RT_PUR_DSCNT_AMT_F
            ,M.RT_PUR_TAX_AMT_L
                 RT_PUR_TAX_AMT_L
            ,M.RT_PUR_TAX_AMT_F
                 RT_PUR_TAX_AMT_F
            ,M.RT_PUR_OTHR_AMT_L
                 RT_PUR_OTHR_AMT_L
            ,M.RT_PUR_OTHR_AMT_F
                 RT_PUR_OTHR_AMT_F
            ,ROUND (M.PUR_AMT_L - M.PUR_DSCNT_AMT_L + M.PUR_OTHR_AMT_L, 4)
             - ROUND (M.RT_PUR_AMT_L - M.RT_PUR_DSCNT_AMT_L + M.RT_PUR_OTHR_AMT_L
                     ,4)
                 NET_PUR_AMT_L
            ,ROUND (M.PUR_AMT_F - M.PUR_DSCNT_AMT_F + M.PUR_OTHR_AMT_F, 4)
             - ROUND (M.RT_PUR_AMT_F - M.RT_PUR_DSCNT_AMT_F + M.RT_PUR_OTHR_AMT_F
                     ,4)
                 NET_PUR_AMT_F
            ,M.NET_BILL_AMT_L
                 NET_BILL_AMT_L
            ,M.NET_STK_AMT_L
                 NET_STK_AMT_L
            ,M.NET_BILL_AMT_STK
                 NET_BILL_AMT_STK
            ,M.NET_STK_AMT_STK
                 NET_STK_AMT_STK
        FROM (  SELECT M.BILL_DOC_TYPE
                           BILL_DOC_TYPE
                      ,M.BRN_YEAR
                           YR_NO
                      ,M.BRN_NO
                      ,M.BILL_DATE
                           DOC_DATE
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
                           HALF_NO
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
                           QRTR_NO
                      ,( SELECT YS_GNR_PKG.GET_PRD_NO(M.BILL_DATE) FROM DUAL) PRD_NO    
                      ,TO_CHAR (M.BILL_DATE, 'WW')
                           WEEK_NO
                      ,TO_CHAR (M.BILL_DATE, 'DD')
                           DAY_NO
                      ,M.BILL_CURRENCY
                           CUR_CODE
                      ,M.CASH_NO
                      ,D.I_CODE
                           ITM_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_CODE || ' - ' || M.V_NAME
                           V_NM
                      ,M.PMAN_CODE
                           SMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
                      ,(SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE IAS_ITM_DTL.I_CODE = D.I_CODE
                           AND NVL (IAS_ITM_DTL.P_SIZE, 0) = 1
                           AND NVL (IAS_ITM_DTL.MAIN_UNIT, 0) = 1
                           AND ROWNUM <= 1)
                           ITM_UNT
                      ,1
                           ITM_SIZE
                      ,ROUND (SUM (NVL (D.P_QTY, 0)), 4)
                           ITM_QTY
                      ,ROUND (SUM (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
                           ITM_FREE_QTY
                      ,NULL
                           RT_ITM_QTY
                      ,NULL
                           RT_ITM_FREE_QTY
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_AMT_L
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_AMT_F
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_DSCNT_AMT_L
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_DSCNT_AMT_F
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_TAX_AMT_L
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_TAX_AMT_F
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_OTHR_AMT_L
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_OTHR_AMT_F
                      ,0
                           RT_PUR_AMT_L
                      ,0
                           RT_PUR_AMT_F
                      ,0
                           RT_PUR_DSCNT_AMT_L
                      ,0
                           RT_PUR_DSCNT_AMT_F
                      ,0
                           RT_PUR_TAX_AMT_L
                      ,0
                           RT_PUR_TAX_AMT_F
                      ,0
                           RT_PUR_OTHR_AMT_L
                      ,0
                           RT_PUR_OTHR_AMT_F
                      ,ROUND (
                           SUM (
                                 (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1))
                          ,4)
                           NET_BILL_AMT_L
                      ,ROUND (
                           SUM (
                                 (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                               * NVL (D.STK_COST, 0)
                               * NVL (M.STOCK_RATE, 1))
                          ,4)
                           NET_STK_AMT_L
                      ,ROUND (
                           SUM (
                                 (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                  * NVL (D.I_QTY, 0)
                                  * NVL (M.BILL_RATE, 1))
                               / NVL (M.STOCK_RATE, 1))
                          ,4)
                           NET_BILL_AMT_STK
                      ,ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4)
                           NET_STK_AMT_STK
                  FROM IAS_PI_BILL_MST M, IAS_PI_BILL_DTL D
                 WHERE M.BILL_SER = D.BILL_SER AND NVL (M.HUNG, 0) = 0
              GROUP BY M.BILL_DOC_TYPE
                      ,M.BRN_YEAR
                      ,M.BRN_NO
                      ,M.BILL_DATE
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
                      ,TO_CHAR (M.BILL_DATE, 'WW')
                      ,TO_CHAR (M.BILL_DATE, 'DD')
                      ,M.BILL_CURRENCY
                      ,M.CASH_NO
                      ,D.I_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_NAME
                      ,M.PMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
              UNION ALL
                SELECT M.RT_BILL_DOC_TYPE RT_BILL_DOC_TYPE
                      ,M.BRN_YEAR
                           YR_NO
                      ,M.BRN_NO
                      ,M.RT_BILL_DATE
                           DOC_DATE
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
                           HALF_NO
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
                           QRTR_NO
                      ,( SELECT YS_GNR_PKG.GET_PRD_NO(M.RT_BILL_DATE) FROM DUAL) PRD_NO      
                      ,TO_CHAR (M.RT_BILL_DATE, 'WW')
                           WEEK_NO
                      ,TO_CHAR (M.RT_BILL_DATE, 'DD')
                           DAY_NO
                      ,M.RT_BILL_CURRENCY
                           CUR_CODE
                      ,M.CASH_NO
                      ,D.I_CODE
                           ITM_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_CODE || ' - ' || M.V_NAME
                           V_NM
                      ,M.PMAN_CODE
                           SMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
                      ,(SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE IAS_ITM_DTL.I_CODE = D.I_CODE
                           AND NVL (IAS_ITM_DTL.P_SIZE, 0) = 1
                           AND NVL (IAS_ITM_DTL.MAIN_UNIT, 0) = 1
                           AND ROWNUM <= 1)
                           ITM_UNT
                      ,1
                           ITM_SIZE
                      ,NULL
                           ITM_QTY
                      ,NULL
                           ITM_FREE_QTY
                      ,ROUND (SUM (NVL (D.P_QTY, 0)), 4)
                           RT_ITM_QTY
                      ,ROUND (SUM (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
                           RT_ITM_FREE_QTY
                      ,0
                           PUR_AMT_L
                      ,0
                           PUR_AMT_F
                      ,0
                           PUR_DSCNT_AMT_L
                      ,0
                           PUR_DSCNT_AMT_F
                      ,0
                           PUR_TAX_AMT_L
                      ,0
                           PUR_TAX_AMT_F
                      ,0
                           PUR_OTHR_AMT_L
                      ,0
                           PUR_OTHR_AMT_F
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_AMT_L
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_AMT_F
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_DSCNT_AMT_L
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_DSCNT_AMT_F
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_TAX_AMT_L
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_TAX_AMT_F
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1))
                             ,4)
                           RT_PUR_OTHR_AMT_L
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_OTHR_AMT_F
                      ,  ROUND (
                             SUM (
                                   (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                 * NVL (D.I_QTY, 0)
                                 * NVL (M.RT_BILL_RATE, 1))
                            ,4)
                       * -1
                           NET_BILL_AMT_L
                      ,  ROUND (
                             SUM (
                                   (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                                 * NVL (D.STK_COST, 0)
                                 * NVL (M.STOCK_RATE, 1))
                            ,4)
                       * -1
                           NET_STK_AMT_L
                      ,  ROUND (
                             SUM (
                                   (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                    * NVL (D.I_QTY, 0)
                                    * NVL (M.RT_BILL_RATE, 1))
                                 / NVL (M.STOCK_RATE, 1))
                            ,4)
                       * -1
                           NET_BILL_AMT_STK
                      ,  ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0))
                               ,4)
                       * -1
                           NET_STK_AMT_STK
                  FROM IAS_PR_BILL_MST M, IAS_PR_BILL_DTL D
                 WHERE M.RT_BILL_SER = D.RT_BILL_SER AND NVL (M.HUNG, 0) = 0
              GROUP BY M.RT_BILL_DOC_TYPE
                      ,M.BRN_YEAR
                      ,M.BRN_NO
                      ,M.RT_BILL_DATE
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
                      ,TO_CHAR (M.RT_BILL_DATE, 'WW')
                      ,TO_CHAR (M.RT_BILL_DATE, 'DD')
                      ,M.RT_BILL_CURRENCY
                      ,M.CASH_NO
                      ,D.I_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_NAME
                      ,M.PMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO) M
            ,IAS_ITM_MST I,LNG
       WHERE M.ITM_CODE = I.I_CODE;


--
-- APS_KPI_NET_PURCHS_DTL_VW_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_NET_PURCHS_DTL_VW_YR
(YR_NO, BRN_NO, BRN_NM, BILL_DOC_TYPE, DOC_DATE, 
 HALF_NO, QRTR_NO, PRD_NO, PRD_NM, WEEK_NO, 
 DAY_NO, CUR_CODE, CASH_NO, CASH_NM, ITM_CODE, 
 ITM_NM, G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, 
 SUBG_CODE, SUBG_CODE_NM, ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, 
 ALTRNTV_GRP_NM, ITM_TYP_NM, GRP_CLASS_NM, ITM_DSC, W_CODE, 
 W_NM, V_CODE, V_NM, SMAN_CODE, SMAN_NM, 
 CC_CODE, CC_NM, PJ_NO, PJ_NM, ACTV_NO, 
 ACTV_NM, KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, 
 USE_ATTCH, ITM_UNT, ITM_SIZE, MAX_ITM_UNT, MAX_P_SIZE, 
 ITM_QTY, ITM_FREE_QTY, RT_ITM_QTY, RT_ITM_FREE_QTY, NET_ITM_QTY, 
 NET_ITM_FREE_QTY, PUR_AMT_L, PUR_AMT_F, PUR_DSCNT_AMT_L, PUR_DSCNT_AMT_F, 
 PUR_TAX_AMT_L, PUR_TAX_AMT_F, PUR_OTHR_AMT_L, PUR_OTHR_AMT_F, RT_PUR_AMT_L, 
 RT_PUR_AMT_F, RT_PUR_DSCNT_AMT_L, RT_PUR_DSCNT_AMT_F, RT_PUR_TAX_AMT_L, RT_PUR_TAX_AMT_F, 
 RT_PUR_OTHR_AMT_L, RT_PUR_OTHR_AMT_F, NET_PUR_AMT_L, NET_PUR_AMT_F, NET_BILL_AMT_L, 
 NET_STK_AMT_L, NET_BILL_AMT_STK, NET_STK_AMT_STK)
BEQUEATH DEFINER
AS 
WITH LNG
        AS
            (SELECT (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1) FROM DUAL)
                        LNG_NO
               FROM DUAL)
      SELECT M.YR_NO
            ,M.BRN_NO
            ,M.BRN_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME),NVL (BRN_FNAME, BRN_LNAME))
                                     FROM S_BRN
                                    WHERE BRN_NO = M.BRN_NO AND ROWNUM<=1)
                 BRN_NM
            ,M.BILL_DOC_TYPE || ' - ' || (SELECT FLG_DESC FROM S_FLAGS
                                           WHERE FLG_CODE = 'TYPE_NAME'
                                             AND LANG_NO = LNG.LNG_NO
                                             AND FLG_VALUE = M.BILL_DOC_TYPE 
                                             AND ROWNUM<=1) BILL_DOC_TYPE
            ,M.DOC_DATE
            ,M.HALF_NO
            ,M.QRTR_NO
            ,M.PRD_NO
            ,M.PRD_NO || '-' || (SELECT DECODE (LNG.LNG_NO,1, NVL (PRD_L_NM, PRD_F_NM),NVL (PRD_F_NM, PRD_L_NM))
                                                               FROM S_PRD_DTL
                                                              WHERE PRD_NO =M.PRD_NO AND ROWNUM <= 1) 
                PRD_NM
            ,M.WEEK_NO
            ,M.DAY_NO
            ,M.CUR_CODE
            ,M.CASH_NO
            ,M.CASH_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (CASH_NAME, CASH_E_NAME),NVL (CASH_E_NAME, CASH_NAME))
                                      FROM CASH_IN_HAND
                                     WHERE CASH_NO = M.CASH_NO
                                       AND ROWNUM<=1)
                 CASH_NM
            ,I.I_CODE
                 ITM_CODE
            ,DECODE (LNG.LNG_NO,1, I.I_NAME,NVL (I.I_E_NAME, I.I_NAME))
                 ITM_NM
            ,I.G_CODE
            ,I.G_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                               ,1, NVL (GRP.G_A_NAME, GRP.G_E_NAME)
                                               ,NVL (GRP.G_E_NAME, GRP.G_A_NAME))
                                            GRP_NM
                                   FROM GROUP_DETAILS GRP
                                  WHERE GRP.G_CODE = I.G_CODE AND ROWNUM <= 1)
                 GRP_CODE_NM
            ,I.MNG_CODE
            ,I.MNG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                 ,1, NVL (GRP.MNG_A_NAME, GRP.MNG_E_NAME)
                                                 ,NVL (GRP.MNG_E_NAME, GRP.MNG_A_NAME))
                                              GRP_NM
                                     FROM IAS_MAINSUB_GRP_DTL GRP
                                    WHERE MNG_CODE = I.MNG_CODE
                                      AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                      AND ROWNUM <= 1)
                 MNG_CODE_NM
            ,I.SUBG_CODE
            ,I.SUBG_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.SUBG_A_NAME, GRP.SUBG_E_NAME)
                                                  ,NVL (GRP.SUBG_E_NAME, GRP.SUBG_A_NAME))
                                               GRP_NM
                                      FROM IAS_SUB_GRP_DTL GRP
                                     WHERE SUBG_CODE = I.SUBG_CODE
                                       AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                       AND NVL (I.MNG_CODE, '0') =
                                       DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                       AND ROWNUM <= 1)
                 SUBG_CODE_NM
            ,I.ASSISTANT_NO
            ,I.ASSISTANT_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (GRP.ASSISTANT_A_NAME,GRP.ASSISTANT_E_NAME),NVL (GRP.ASSISTANT_E_NAME, GRP.ASSISTANT_A_NAME)) GRP_NM
                                          FROM IAS_ASSISTANT_GROUP GRP
                                         WHERE ASSISTANT_NO = I.ASSISTANT_NO
                                           AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                           AND NVL (I.MNG_CODE, '0') =
                                           DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                           AND NVL (I.SUBG_CODE, '0') =
                                           DECODE (NVL (SUBG_CODE, '0'), '0', NVL (I.SUBG_CODE, '0'), SUBG_CODE)
                                           AND ROWNUM <= 1)
                 ASSTNT_GRP_NM
            ,I.DETAIL_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                                  ,1, NVL (GRP.DETAIL_A_NAME, GRP.DETAIL_E_NAME)
                                                  ,NVL (GRP.DETAIL_E_NAME, GRP.DETAIL_A_NAME))
                                               GRP_NM
                                      FROM IAS_DETAIL_GROUP GRP
                                     WHERE DETAIL_NO = I.DETAIL_NO
                                       AND NVL (I.G_CODE, '0') = DECODE (NVL (G_CODE, '0'), '0', NVL (I.G_CODE, '0'), G_CODE)
                                       AND NVL (I.MNG_CODE, '0') =
                                       DECODE (NVL (MNG_CODE, '0'), '0', NVL (I.MNG_CODE, '0'), MNG_CODE)
                                       AND NVL (I.SUBG_CODE, '0') =
                                       DECODE (NVL (SUBG_CODE, '0'), '0', NVL (I.SUBG_CODE, '0'), SUBG_CODE)
                                       AND NVL (I.ASSISTANT_NO, '0') =
                                       DECODE (NVL (ASSISTANT_NO, '0'), '0', NVL (I.ASSISTANT_NO, '0'), ASSISTANT_NO)
                                       AND ROWNUM <= 1)
                 DTL_GRP_NM
            ,I.GROUP_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.GROUP_A_NAME,NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
                                       FROM IAS_ALTERNATIVE_GROUP A
                                      WHERE A.GROUP_NO = I.GROUP_NO 
                                        AND ROWNUM <= 1)
                 ALTRNTV_GRP_NM
            ,I.ITEM_TYPE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.IT_A_NAME,NVL (A.IT_E_NAME, A.IT_A_NAME))
                                        FROM ITEM_TYPES A
                                       WHERE A.TYPE_OF_ITEM = I.ITEM_TYPE 
                                         AND ROWNUM <= 1)
                 ITM_TYP_NM
            ,I.GRP_CLASS_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, A.GRP_L_NAME,NVL (A.GRP_F_NAME, A.GRP_L_NAME))
                                             FROM IAS_GRP_ITM_LVL A
                                            WHERE A.GRP_CODE = I.GRP_CLASS_CODE 
                                              AND ROWNUM <= 1)
                 GRP_CLASS_NM
            ,DECODE (LNG.LNG_NO,1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC))
                 ITM_DSC
            ,M.W_CODE
            ,M.W_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (W_NAME, W_E_NAME),NVL (W_E_NAME, W_NAME))
                                     FROM WAREHOUSE_DETAILS
                                    WHERE W_CODE = M.W_CODE 
                                      AND ROWNUM <= 1)
                 W_NM
            ,M.V_CODE
            ,M.V_NM
            ,M.SMAN_CODE
            ,M.SMAN_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO,1, NVL (REPRS_A_NAME, REPRS_E_NAME),NVL (REPRS_E_NAME, REPRS_A_NAME))
                                                  FROM SALES_MAN
                                                 WHERE REPRS_CODE = M.SMAN_CODE
                                                   AND ROWNUM <= 1)
                           SMAN_NM
            ,M.CC_CODE
            ,M.CC_CODE || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                              ,1, NVL (CC_A_NAME, CC_E_NAME)
                                              ,NVL (CC_E_NAME, CC_A_NAME))
                                      FROM COST_CENTERS
                                     WHERE CC_CODE = M.CC_CODE 
                                       AND ROWNUM <= 1)
                 CC_NM
            ,M.PJ_NO
            ,M.PJ_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                            ,1, NVL (PJ_A_NAME, PJ_E_NAME)
                                            ,NVL (PJ_A_NAME, PJ_E_NAME))
                                    FROM IAS_PROJECTS
                                   WHERE PJ_NO = M.PJ_NO
                                     AND ROWNUM <= 1)
                 PJ_NM
            ,M.ACTV_NO
            ,M.ACTV_NO || ' - ' || (SELECT DECODE (LNG.LNG_NO
                                              ,1, NVL (ACTV_A_NAME, ACTV_E_NAME)
                                              ,NVL (ACTV_E_NAME, ACTV_A_NAME))
                                      FROM IAS_ACTVTY
                                     WHERE ACTV_NO = M.ACTV_NO
                                       AND ROWNUM <= 1)
                 ACTV_NM
            ,I.KIT_ITM
            ,I.USE_EXP_DATE
            ,I.USE_BATCH_NO
            ,I.USE_SERIALNO
            ,I.USE_ATTCH
            ,M.ITM_UNT
            ,M.ITM_SIZE
            ,(SELECT ITM_UNT
              FROM IAS_ITM_DTL
             WHERE     I_CODE = I.I_CODE
                   AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                     FROM IAS_ITM_DTL
                                    WHERE I_CODE = I.I_CODE)
                   AND ROWNUM <= 1)
               MAX_ITM_UNT
           ,(SELECT P_SIZE
              FROM IAS_ITM_DTL
             WHERE     I_CODE = I.I_CODE
                   AND ITM_UNT =
                       (SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE     I_CODE = I.I_CODE
                               AND LVL_UNIT = (SELECT MAX (LVL_UNIT)
                                                 FROM IAS_ITM_DTL
                                                WHERE I_CODE = I.I_CODE)
                               AND ROWNUM <= 1)
                   AND ROWNUM <= 1)
               MAX_P_SIZE           
            ,NVL (M.ITM_QTY, 0)
                 ITM_QTY
            ,NVL (M.ITM_FREE_QTY, 0)
                 ITM_FREE_QTY
            ,NVL (M.RT_ITM_QTY, 0)
                 RT_ITM_QTY
            ,NVL (M.RT_ITM_FREE_QTY, 0)
                 RT_ITM_FREE_QTY
            ,NVL (M.ITM_QTY, 0) - NVL (M.RT_ITM_QTY, 0)
                 NET_ITM_QTY
            ,NVL (M.ITM_FREE_QTY, 0) - NVL (M.RT_ITM_FREE_QTY, 0)
                 NET_ITM_FREE_QTY
            ,M.PUR_AMT_L
                 PUR_AMT_L
            ,M.PUR_AMT_F
                 PUR_AMT_F
            ,M.PUR_DSCNT_AMT_L
                 PUR_DSCNT_AMT_L
            ,M.PUR_DSCNT_AMT_F
                 PUR_DSCNT_AMT_F
            ,M.PUR_TAX_AMT_L
                 PUR_TAX_AMT_L
            ,M.PUR_TAX_AMT_F
                 PUR_TAX_AMT_F
            ,M.PUR_OTHR_AMT_L
                 PUR_OTHR_AMT_L
            ,M.PUR_OTHR_AMT_F
                 PUR_OTHR_AMT_F
            ,M.RT_PUR_AMT_L
                 RT_PUR_AMT_L
            ,M.RT_PUR_AMT_F
                 RT_PUR_AMT_F
            ,M.RT_PUR_DSCNT_AMT_L
                 RT_PUR_DSCNT_AMT_L
            ,M.RT_PUR_DSCNT_AMT_F
                 RT_PUR_DSCNT_AMT_F
            ,M.RT_PUR_TAX_AMT_L
                 RT_PUR_TAX_AMT_L
            ,M.RT_PUR_TAX_AMT_F
                 RT_PUR_TAX_AMT_F
            ,M.RT_PUR_OTHR_AMT_L
                 RT_PUR_OTHR_AMT_L
            ,M.RT_PUR_OTHR_AMT_F
                 RT_PUR_OTHR_AMT_F
            ,ROUND (M.PUR_AMT_L - M.PUR_DSCNT_AMT_L + M.PUR_OTHR_AMT_L, 4)
             - ROUND (M.RT_PUR_AMT_L - M.RT_PUR_DSCNT_AMT_L + M.RT_PUR_OTHR_AMT_L
                     ,4)
                 NET_PUR_AMT_L
            ,ROUND (M.PUR_AMT_F - M.PUR_DSCNT_AMT_F + M.PUR_OTHR_AMT_F, 4)
             - ROUND (M.RT_PUR_AMT_F - M.RT_PUR_DSCNT_AMT_F + M.RT_PUR_OTHR_AMT_F
                     ,4)
                 NET_PUR_AMT_F
            ,M.NET_BILL_AMT_L
                 NET_BILL_AMT_L
            ,M.NET_STK_AMT_L
                 NET_STK_AMT_L
            ,M.NET_BILL_AMT_STK
                 NET_BILL_AMT_STK
            ,M.NET_STK_AMT_STK
                 NET_STK_AMT_STK
        FROM (  SELECT M.BILL_DOC_TYPE
                           BILL_DOC_TYPE
                      ,M.BRN_YEAR
                           YR_NO
                      ,M.BRN_NO
                      ,M.BILL_DATE
                           DOC_DATE
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
                           HALF_NO
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
                           QRTR_NO
                      ,( SELECT YS_GNR_PKG.GET_PRD_NO(M.BILL_DATE) FROM DUAL) PRD_NO    
                      ,TO_CHAR (M.BILL_DATE, 'WW')
                           WEEK_NO
                      ,TO_CHAR (M.BILL_DATE, 'DD')
                           DAY_NO
                      ,M.BILL_CURRENCY
                           CUR_CODE
                      ,M.CASH_NO
                      ,D.I_CODE
                           ITM_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_CODE || ' - ' || M.V_NAME
                           V_NM
                      ,M.PMAN_CODE
                           SMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
                      ,(SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE IAS_ITM_DTL.I_CODE = D.I_CODE
                           AND NVL (IAS_ITM_DTL.P_SIZE, 0) = 1
                           AND NVL (IAS_ITM_DTL.MAIN_UNIT, 0) = 1
                           AND ROWNUM <= 1)
                           ITM_UNT
                      ,1
                           ITM_SIZE
                      ,ROUND (SUM (NVL (D.P_QTY, 0)), 4)
                           ITM_QTY
                      ,ROUND (SUM (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
                           ITM_FREE_QTY
                      ,NULL
                           RT_ITM_QTY
                      ,NULL
                           RT_ITM_FREE_QTY
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_AMT_L
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_AMT_F
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_DSCNT_AMT_L
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_DSCNT_AMT_F
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_TAX_AMT_L
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_TAX_AMT_F
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
                           PUR_OTHR_AMT_L
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           PUR_OTHR_AMT_F
                      ,0
                           RT_PUR_AMT_L
                      ,0
                           RT_PUR_AMT_F
                      ,0
                           RT_PUR_DSCNT_AMT_L
                      ,0
                           RT_PUR_DSCNT_AMT_F
                      ,0
                           RT_PUR_TAX_AMT_L
                      ,0
                           RT_PUR_TAX_AMT_F
                      ,0
                           RT_PUR_OTHR_AMT_L
                      ,0
                           RT_PUR_OTHR_AMT_F
                      ,ROUND (
                           SUM (
                                 (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                               * NVL (D.I_QTY, 0)
                               * NVL (M.BILL_RATE, 1))
                          ,4)
                           NET_BILL_AMT_L
                      ,ROUND (
                           SUM (
                                 (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                               * NVL (D.STK_COST, 0)
                               * NVL (M.STOCK_RATE, 1))
                          ,4)
                           NET_STK_AMT_L
                      ,ROUND (
                           SUM (
                                 (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                  * NVL (D.I_QTY, 0)
                                  * NVL (M.BILL_RATE, 1))
                               / NVL (M.STOCK_RATE, 1))
                          ,4)
                           NET_BILL_AMT_STK
                      ,ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4)
                           NET_STK_AMT_STK
                  FROM IAS_V_PI_BILL_MST_YR M, IAS_V_PI_BILL_DTL_YR D
                 WHERE M.BILL_SER = D.BILL_SER AND NVL (M.HUNG, 0) = 0
              GROUP BY M.BILL_DOC_TYPE
                      ,M.BRN_YEAR
                      ,M.BRN_NO
                      ,M.BILL_DATE
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
                      ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
                      ,TO_CHAR (M.BILL_DATE, 'WW')
                      ,TO_CHAR (M.BILL_DATE, 'DD')
                      ,M.BILL_CURRENCY
                      ,M.CASH_NO
                      ,D.I_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_NAME
                      ,M.PMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
              UNION ALL
                SELECT M.RT_BILL_DOC_TYPE RT_BILL_DOC_TYPE
                      ,M.BRN_YEAR
                           YR_NO
                      ,M.BRN_NO
                      ,M.RT_BILL_DATE
                           DOC_DATE
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
                           HALF_NO
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
                           QRTR_NO
                      ,( SELECT YS_GNR_PKG.GET_PRD_NO(M.RT_BILL_DATE) FROM DUAL) PRD_NO      
                      ,TO_CHAR (M.RT_BILL_DATE, 'WW')
                           WEEK_NO
                      ,TO_CHAR (M.RT_BILL_DATE, 'DD')
                           DAY_NO
                      ,M.RT_BILL_CURRENCY
                           CUR_CODE
                      ,M.CASH_NO
                      ,D.I_CODE
                           ITM_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_CODE || ' - ' || M.V_NAME
                           V_NM
                      ,M.PMAN_CODE
                           SMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO
                      ,(SELECT ITM_UNT
                          FROM IAS_ITM_DTL
                         WHERE IAS_ITM_DTL.I_CODE = D.I_CODE
                           AND NVL (IAS_ITM_DTL.P_SIZE, 0) = 1
                           AND NVL (IAS_ITM_DTL.MAIN_UNIT, 0) = 1
                           AND ROWNUM <= 1)
                           ITM_UNT
                      ,1
                           ITM_SIZE
                      ,NULL
                           ITM_QTY
                      ,NULL
                           ITM_FREE_QTY
                      ,ROUND (SUM (NVL (D.P_QTY, 0)), 4)
                           RT_ITM_QTY
                      ,ROUND (SUM (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
                           RT_ITM_FREE_QTY
                      ,0
                           PUR_AMT_L
                      ,0
                           PUR_AMT_F
                      ,0
                           PUR_DSCNT_AMT_L
                      ,0
                           PUR_DSCNT_AMT_F
                      ,0
                           PUR_TAX_AMT_L
                      ,0
                           PUR_TAX_AMT_F
                      ,0
                           PUR_OTHR_AMT_L
                      ,0
                           PUR_OTHR_AMT_F
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_AMT_L
                      ,ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_AMT_F
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_DSCNT_AMT_L
                      ,ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_DSCNT_AMT_F
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
                           RT_PUR_TAX_AMT_L
                      ,ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_TAX_AMT_F
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1))
                             ,4)
                           RT_PUR_OTHR_AMT_L
                      ,ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
                           RT_PUR_OTHR_AMT_F
                      ,  ROUND (
                             SUM (
                                   (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                 * NVL (D.I_QTY, 0)
                                 * NVL (M.RT_BILL_RATE, 1))
                            ,4)
                       * -1
                           NET_BILL_AMT_L
                      ,  ROUND (
                             SUM (
                                   (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
                                 * NVL (D.STK_COST, 0)
                                 * NVL (M.STOCK_RATE, 1))
                            ,4)
                       * -1
                           NET_STK_AMT_L
                      ,  ROUND (
                             SUM (
                                   (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
                                    * NVL (D.I_QTY, 0)
                                    * NVL (M.RT_BILL_RATE, 1))
                                 / NVL (M.STOCK_RATE, 1))
                            ,4)
                       * -1
                           NET_BILL_AMT_STK
                      ,  ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0))
                               ,4)
                       * -1
                           NET_STK_AMT_STK
                  FROM IAS_V_PR_BILL_MST_YR M, IAS_V_PR_BILL_DTL_YR D
                 WHERE M.RT_BILL_SER = D.RT_BILL_SER AND NVL (M.HUNG, 0) = 0
              GROUP BY M.RT_BILL_DOC_TYPE
                      ,M.BRN_YEAR
                      ,M.BRN_NO
                      ,M.RT_BILL_DATE
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
                      ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
                      ,TO_CHAR (M.RT_BILL_DATE, 'WW')
                      ,TO_CHAR (M.RT_BILL_DATE, 'DD')
                      ,M.RT_BILL_CURRENCY
                      ,M.CASH_NO
                      ,D.I_CODE
                      ,D.W_CODE
                      ,M.V_CODE
                      ,M.V_NAME
                      ,M.PMAN_CODE
                      ,D.CC_CODE
                      ,D.PJ_NO
                      ,D.ACTV_NO) M
            ,IAS_ITM_MST I,LNG
       WHERE M.ITM_CODE = I.I_CODE;


--
-- APS_KPI_NET_PURCHS_PRD_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_KPI_NET_PURCHS_PRD_VW
(YR_NO, BRN_NO, BRN_NM, BILL_DOC_TYPE, DOC_DATE, 
 HALF_NO, QRTR_NO, PRD_NO, PRD_NM, WEEK_NO, 
 DAY_NO, CUR_CODE, CASH_NO, CASH_NM, ITM_CODE, 
 ITM_NM, ITM_UNT, MAX_ITM_UNT, MAX_P_SIZE, G_CODE, 
 GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, 
 ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, ALTRNTV_GRP_NM, ITM_TYP_NM, 
 GRP_CLASS_NM, ITM_DSC, W_CODE, W_NM, V_CODE, 
 V_NM, SMAN_CODE, SMAN_NM, CC_CODE, CC_NM, 
 PJ_NO, PJ_NM, ACTV_NO, ACTV_NM, KIT_ITM, 
 USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, USE_ATTCH, PUR_AMT_L, 
 PUR_AMT_F, PUR_DSCNT_AMT_L, PUR_DSCNT_AMT_F, PUR_TAX_AMT_L, PUR_TAX_AMT_F, 
 PUR_OTHR_AMT_L, PUR_OTHR_AMT_F, RT_PUR_AMT_L, RT_PUR_AMT_F, RT_PUR_DSCNT_AMT_L, 
 RT_PUR_DSCNT_AMT_F, RT_PUR_TAX_AMT_L, RT_PUR_TAX_AMT_F, RT_PUR_OTHR_AMT_L, RT_PUR_OTHR_AMT_F, 
 NET_PUR_AMT_L, NET_PUR_AMT_F, NET_BILL_AMT_L, NET_STK_AMT_L, NET_BILL_AMT_STK, 
 NET_STK_AMT_STK)
BEQUEATH DEFINER
AS 
SELECT M.Yr_No,
             M.Brn_No,
                M.Brn_No
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (Brn_Lname, Brn_Fname),
                            NVL (Brn_Fname, Brn_Lname))
                   FROM S_Brn
                  WHERE Brn_No = M.Brn_No)
                 Brn_Nm,
             M.Bill_Doc_Type,
             M.Doc_Date,
             M.Half_No,
             M.Qrtr_No,
             M.Prd_No,
                M.Prd_No
             || '-'
             || ys_gnr_pkg.Get_Prd_Nm (
                    NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1),
                    M.Prd_No)
                 Prd_Nm,
             M.Week_No,
             M.Day_No,
             M.Cur_Code,
             M.Cash_No,
                M.Cash_No
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (Cash_Name, Cash_E_Name),
                            NVL (Cash_E_Name, Cash_Name))
                   FROM Cash_In_Hand
                  WHERE Cash_No = M.Cash_No)
                 Cash_Nm,
             I.I_Code
                 Itm_Code,
             DECODE (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1),
                     1, I.I_Name,
                     NVL (I.I_E_Name, I.I_Name))
                 Itm_Nm,
             (Select Itm_Unt From Ias_Itm_Dtl Where Ias_Itm_Dtl.I_Code = I.I_Code And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 And RowNum <= 1 ) Itm_Unt ,
             (SELECT ITM_UNT FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND LVL_UNIT = ( SELECT MAX (LVL_UNIT)FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1)MAX_ITM_UNT ,
             (SELECT P_SIZE  FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND ITM_UNT  = ( SELECT ITM_UNT FROM IAS_ITM_DTL WHERE     I_CODE = I.I_CODE AND LVL_UNIT = (SELECT MAX (LVL_UNIT) FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1) AND ROWNUM <= 1) MAX_P_SIZE ,                 
             I.G_Code,
                I.G_Code
             || ' - '
             || Inv_Get_Grp_Nm_Fnc (
                    P_G_Code    => I.G_Code,
                    P_Grp_Typ   => 1,
                    P_Lang_No   =>
                        NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1))
                 Grp_Code_Nm,
             I.Mng_Code,
                I.Mng_Code
             || ' - '
             || Inv_Get_Grp_Nm_Fnc (
                    P_G_Code     => I.G_Code,
                    P_Mng_Code   => I.Mng_Code,
                    P_Grp_Typ    => 2,
                    P_Lang_No    =>
                        NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1))
                 Mng_Code_Nm,
             I.Subg_Code,
                I.Subg_Code
             || ' - '
             || Inv_Get_Grp_Nm_Fnc (
                    P_G_Code      => I.G_Code,
                    P_Mng_Code    => I.Mng_Code,
                    P_Subg_Code   => I.Subg_Code,
                    P_Grp_Typ     => 3,
                    P_Lang_No     =>
                        NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1))
                 Subg_Code_Nm,
             I.Assistant_No,
                I.Assistant_No
             || ' - '
             || Inv_Get_Grp_Nm_Fnc (
                    P_G_Code         => I.G_Code,
                    P_Mng_Code       => I.Mng_Code,
                    P_Subg_Code      => I.Subg_Code,
                    P_Assistant_No   => I.Assistant_No,
                    P_Grp_Typ        => 4,
                    P_Lang_No        =>
                        NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1))
                 Asstnt_Grp_Nm,
                I.Detail_No
             || ' - '
             || Inv_Get_Grp_Nm_Fnc (
                    P_G_Code         => I.G_Code,
                    P_Mng_Code       => I.Mng_Code,
                    P_Subg_Code      => I.Subg_Code,
                    P_Assistant_No   => I.Assistant_No,
                    P_Detail_No      => I.Detail_No,
                    P_Grp_Typ        => 5,
                    P_Lang_No        =>
                        NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1))
                 Dtl_Grp_Nm,
                I.Group_No
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, A.Group_A_Name,
                            NVL (A.Group_E_Name, A.Group_A_Name))
                   FROM Ias_Alternative_Group A
                  WHERE A.Group_No = I.Group_No AND ROWNUM <= 1)
                 Altrntv_Grp_Nm,
                I.Item_Type
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, A.It_A_Name,
                            NVL (A.It_E_Name, A.It_A_Name))
                   FROM Item_Types A
                  WHERE A.Type_Of_Item = I.Item_Type AND ROWNUM <= 1)
                 Itm_Typ_Nm,
                I.Grp_Class_Code
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, A.Grp_L_Name,
                            NVL (A.Grp_F_Name, A.Grp_L_Name))
                   FROM Ias_Grp_Itm_Lvl A
                  WHERE A.Grp_Code = I.Grp_Class_Code AND ROWNUM <= 1)
                 Grp_Class_Nm,
             DECODE (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1),
                     1, I.I_Desc,
                     NVL (I.I_F_Desc, I.I_Desc))
                 Itm_Dsc,
             M.W_Code,
                M.W_Code
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (W_Name, W_E_Name),
                            NVL (W_E_Name, W_Name))
                   FROM Warehouse_Details
                  WHERE W_Code = M.W_Code)
                 W_Nm,
             M.V_CODE,
             M.V_NM,
             M.SMAN_CODE,
             M.SMAN_NM,
             M.Cc_Code,
                M.Cc_Code
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (Cc_A_Name, Cc_E_Name),
                            NVL (Cc_E_Name, Cc_A_Name))
                   FROM Cost_Centers
                  WHERE Cc_Code = M.Cc_Code)
                 Cc_Nm,
             M.Pj_No,
                M.Pj_No
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (Pj_A_Name, Pj_E_Name),
                            NVL (Pj_A_Name, Pj_E_Name))
                   FROM Ias_Projects
                  WHERE Pj_No = M.Pj_No)
                 Pj_Nm,
             M.Actv_No,
                M.Actv_No
             || ' - '
             || (SELECT DECODE (
                            NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'),
                                 1),
                            1, NVL (Actv_A_Name, Actv_E_Name),
                            NVL (Actv_E_Name, Actv_A_Name))
                   FROM Ias_Actvty
                  WHERE Actv_No = M.Actv_No)
                 Actv_Nm,
             I.Kit_Itm,
             I.Use_Exp_Date,
             I.Use_Batch_No,
             I.Use_Serialno,
             I.Use_Attch,
             SUM (M.PUR_Amt_L)
                 PUR_Amt_L,
             SUM (M.PUR_Amt_F)
                 PUR_Amt_F,
             SUM (M.PUR_Dscnt_Amt_L)
                 PUR_Dscnt_Amt_L,
             SUM (M.PUR_Dscnt_Amt_F)
                 PUR_Dscnt_Amt_F,
             SUM (M.PUR_Tax_Amt_L)
                 PUR_Tax_Amt_L,
             SUM (M.PUR_Tax_Amt_F)
                 PUR_Tax_Amt_F,
             SUM (M.PUR_Othr_Amt_L)
                 PUR_Othr_Amt_L,
             SUM (M.PUR_Othr_Amt_F)
                 PUR_Othr_Amt_F,
             SUM (M.Rt_PUR_Amt_L)
                 Rt_PUR_Amt_L,
             SUM (M.Rt_PUR_Amt_F)
                 Rt_PUR_Amt_F,
             SUM (M.Rt_PUR_Dscnt_Amt_L)
                 Rt_PUR_Dscnt_Amt_L,
             SUM (M.Rt_PUR_Dscnt_Amt_F)
                 Rt_PUR_Dscnt_Amt_F,
             SUM (M.Rt_PUR_Tax_Amt_L)
                 Rt_PUR_Tax_Amt_L,
             SUM (M.Rt_PUR_Tax_Amt_F)
                 Rt_PUR_Tax_Amt_F,
             SUM (M.Rt_PUR_Othr_Amt_L)
                 Rt_PUR_Othr_Amt_L,
             SUM (M.Rt_PUR_Othr_Amt_F)
                 Rt_PUR_Othr_Amt_F,
               ROUND (
                     SUM (M.PUR_Amt_L)
                   - SUM (M.PUR_Dscnt_Amt_L)
                   + SUM (M.PUR_Othr_Amt_L),
                   4)
             - ROUND (
                     SUM (M.Rt_PUR_Amt_L)
                   - SUM (M.Rt_PUR_Dscnt_Amt_L)
                   + SUM (M.Rt_PUR_Othr_Amt_L),
                   4)
                 Net_PUR_Amt_L,
               ROUND (
                     SUM (M.PUR_Amt_F)
                   - SUM (M.PUR_Dscnt_Amt_F)
                   + SUM (M.PUR_Othr_Amt_F),
                   4)
             - ROUND (
                     SUM (M.Rt_PUR_Amt_F)
                   - SUM (M.Rt_PUR_Dscnt_Amt_F)
                   + SUM (M.Rt_PUR_Othr_Amt_F),
                   4)
                 Net_PUR_Amt_F,
             SUM (M.Net_Bill_Amt_L)
                 Net_Bill_Amt_L,
             SUM (M.Net_Stk_Amt_L)
                 Net_Stk_Amt_L,
             SUM (M.Net_Bill_Amt_Stk)
                 Net_Bill_Amt_Stk,
             SUM (M.Net_Stk_Amt_Stk)
                 Net_Stk_Amt_Stk
        FROM (  SELECT    M.Bill_Doc_Type
                       || ' - '
                       || (SELECT Flg_Desc
                             FROM S_Flags
                            WHERE     Flg_Code = 'TYPE_NAME'
                                  AND Lang_No =
                                      NVL (
                                          Ias_Prmtr_Pkg.Getpval (
                                              P_Prmtr   => 'LANG_DFLT'),
                                          1)
                                  AND Flg_Value = M.Bill_Doc_Type)
                           Bill_Doc_Type,
                       M.Brn_Year
                           Yr_No,
                       M.Brn_No,
                       M.Bill_Date
                           Doc_Date,
                       ROUND (TO_CHAR (M.Bill_Date, 'Q') / 2)
                           Half_No,
                       ROUND (TO_CHAR (M.Bill_Date, 'Q'))
                           Qrtr_No,
                       TO_CHAR (M.Bill_Date, 'MM')
                           Prd_No,
                       TO_CHAR (M.Bill_Date, 'WW')
                           Week_No,
                       TO_CHAR (M.Bill_Date, 'DD')
                           Day_No,
                       M.Bill_Currency
                           Cur_Code,
                       M.Cash_No,
                       D.I_Code
                           Itm_Code,
                       D.W_Code,
                       M.V_CODE,
                       M.V_CODE || ' - ' || M.V_NAME
                           V_NM,
                       M.PMAN_CODE
                           Sman_Code,
                          M.PMAN_CODE
                       || ' - '
                       || (SELECT DECODE (
                                      NVL (
                                          IAS_PRMTR_PKG.GETPVAL (
                                              P_PRMTR   => 'LANG_DFLT'),
                                          1),
                                      1, NVL (REPRS_A_NAME, REPRS_E_NAME),
                                      NVL (REPRS_E_NAME, REPRS_A_NAME))
                             FROM SALES_MAN
                            WHERE REPRS_CODE = M.PMAN_CODE)
                           SMAN_NM,
                       D.Cc_Code,
                       D.Pj_No,
                       D.Actv_No,
                       ROUND (
                           SUM (
                                 NVL (D.I_Price, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Bill_Rate, 1)),
                           4)
                           PUR_Amt_L,
                       ROUND (SUM (NVL (D.I_Price, 0) * NVL (D.I_Qty, 0)), 4)
                           PUR_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Dis_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Bill_Rate, 1)),
                           4)
                           PUR_Dscnt_Amt_L,
                       ROUND (SUM (NVL (D.Dis_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           PUR_Dscnt_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Vat_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Bill_Rate, 1)),
                           4)
                           PUR_Tax_Amt_L,
                       ROUND (SUM (NVL (D.Vat_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           PUR_Tax_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Othr_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Bill_Rate, 1)),
                           4)
                           PUR_Othr_Amt_L,
                       ROUND (SUM (NVL (D.Othr_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           PUR_Othr_Amt_F,
                       0
                           Rt_PUR_Amt_L,
                       0
                           Rt_PUR_Amt_F,
                       0
                           Rt_PUR_Dscnt_Amt_L,
                       0
                           Rt_PUR_Dscnt_Amt_F,
                       0
                           Rt_PUR_Tax_Amt_L,
                       0
                           Rt_PUR_Tax_Amt_F,
                       0
                           Rt_PUR_Othr_Amt_L,
                       0
                           Rt_PUR_Othr_Amt_F,
                       ROUND (
                           SUM (
                                 (NVL (D.I_Price, 0) - NVL (D.Dis_Amt, 0))
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Bill_Rate, 1)),
                           4)
                           Net_Bill_Amt_L,
                       ROUND (
                           SUM (
                                 (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                               * NVL (D.Stk_Cost, 0)
                               * NVL (M.Stock_Rate, 1)),
                           4)
                           Net_Stk_Amt_L,
                       ROUND (
                           SUM (
                                 (  (NVL (D.I_Price, 0) - NVL (D.Dis_Amt, 0))
                                  * NVL (D.I_Qty, 0)
                                  * NVL (M.Bill_Rate, 1))
                               / NVL (M.Stock_Rate, 1)),
                           4)
                           Net_Bill_Amt_Stk,
                       ROUND (
                           SUM (
                                 (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                               * NVL (D.Stk_Cost, 0)),
                           4)
                           Net_Stk_Amt_Stk
                  FROM Ias_pi_Bill_Mst M, Ias_pi_Bill_Dtl D
                 WHERE M.Bill_Ser = D.Bill_Ser AND NVL (M.HUNG, 0) = 0
              GROUP BY M.Bill_Doc_Type,
                       M.Brn_Year,
                       M.Brn_No,
                       M.Bill_Date,
                       ROUND (TO_CHAR (M.Bill_Date, 'Q') / 2),
                       ROUND (TO_CHAR (M.Bill_Date, 'Q')),
                       TO_CHAR (M.Bill_Date, 'MM'),
                       TO_CHAR (M.Bill_Date, 'WW'),
                       TO_CHAR (M.Bill_Date, 'DD'),
                       M.Bill_Currency,
                       M.Cash_No,
                       D.I_Code,
                       D.W_Code,
                       M.V_CODE,
                       M.V_NAME,
                       M.PMAN_CODE,
                       D.Cc_Code,
                       D.Pj_No,
                       D.Actv_No
              UNION ALL
                SELECT    M.Rt_Bill_Doc_Type
                       || ' - '
                       || (SELECT Flg_Desc
                             FROM S_Flags
                            WHERE     Flg_Code = 'TYPE_NAME'
                                  AND Lang_No =
                                      NVL (
                                          Ias_Prmtr_Pkg.Getpval (
                                              P_Prmtr   => 'LANG_DFLT'),
                                          1)
                                  AND Flg_Value = M.Rt_Bill_Doc_Type)
                           Rt_Bill_Doc_Type,
                       M.Brn_Year
                           Yr_No,
                       M.Brn_No,
                       M.Rt_Bill_Date
                           Doc_Date,
                       ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q') / 2)
                           Half_No,
                       ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q'))
                           Qrtr_No,
                       TO_CHAR (M.Rt_Bill_Date, 'MM')
                           Prd_No,
                       TO_CHAR (M.Rt_Bill_Date, 'WW')
                           Week_No,
                       TO_CHAR (M.Rt_Bill_Date, 'DD')
                           Day_No,
                       M.Rt_Bill_Currency
                           Cur_Code,
                       M.Cash_No,
                       D.I_Code
                           Itm_Code,
                       D.W_Code,
                       M.V_CODE,
                       M.V_CODE || ' - ' || M.V_NAME
                           V_NM,
                       M.PMAN_CODE
                           Sman_Code,
                          M.PMAN_CODE
                       || ' - '
                       || (SELECT DECODE (
                                      NVL (
                                          IAS_PRMTR_PKG.GETPVAL (
                                              P_PRMTR   => 'LANG_DFLT'),
                                          1),
                                      1, NVL (REPRS_A_NAME, REPRS_E_NAME),
                                      NVL (REPRS_E_NAME, REPRS_A_NAME))
                             FROM SALES_MAN
                            WHERE REPRS_CODE = M.PMAN_CODE)
                           SMAN_NM,
                       D.Cc_Code,
                       D.Pj_No,
                       D.Actv_No,
                       0
                           PUR_Amt_L,
                       0
                           PUR_Amt_F,
                       0
                           PUR_Dscnt_Amt_L,
                       0
                           PUR_Dscnt_Amt_F,
                       0
                           PUR_Tax_Amt_L,
                       0
                           PUR_Tax_Amt_F,
                       0
                           PUR_Othr_Amt_L,
                       0
                           PUR_Othr_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.I_Price, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Rt_Bill_Rate, 1)),
                           4)
                           Rt_PUR_Amt_L,
                       ROUND (SUM (NVL (D.I_Price, 0) * NVL (D.I_Qty, 0)), 4)
                           Rt_PUR_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Dis_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Rt_Bill_Rate, 1)),
                           4)
                           Rt_PUR_Dscnt_Amt_L,
                       ROUND (SUM (NVL (D.Dis_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           Rt_PUR_Dscnt_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Vat_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Rt_Bill_Rate, 1)),
                           4)
                           Rt_PUR_Tax_Amt_L,
                       ROUND (SUM (NVL (D.Vat_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           Rt_PUR_Tax_Amt_F,
                       ROUND (
                           SUM (
                                 NVL (D.Othr_Amt, 0)
                               * NVL (D.I_Qty, 0)
                               * NVL (M.Rt_Bill_Rate, 1)),
                           4)
                           Rt_PUR_Othr_Amt_L,
                       ROUND (SUM (NVL (D.Othr_Amt, 0) * NVL (D.I_Qty, 0)), 4)
                           Rt_PUR_Othr_Amt_F,
                         ROUND (
                             SUM (
                                   (NVL (D.I_Price, 0) - NVL (D.Dis_Amt, 0))
                                 * NVL (D.I_Qty, 0)
                                 * NVL (M.Rt_Bill_Rate, 1)),
                             4)
                       * -1
                           Net_Bill_Amt_L,
                         ROUND (
                             SUM (
                                   (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                                 * NVL (D.Stk_Cost, 0)
                                 * NVL (M.Stock_Rate, 1)),
                             4)
                       * -1
                           Net_Stk_Amt_L,
                         ROUND (
                             SUM (
                                   (  (NVL (D.I_Price, 0) - NVL (D.Dis_Amt, 0))
                                    * NVL (D.I_Qty, 0)
                                    * NVL (M.Rt_Bill_Rate, 1))
                                 / NVL (M.Stock_Rate, 1)),
                             4)
                       * -1
                           Net_Bill_Amt_Stk,
                         ROUND (
                             SUM (
                                   (NVL (D.I_Qty, 0) + NVL (D.Free_Qty, 0))
                                 * NVL (D.Stk_Cost, 0)),
                             4)
                       * -1
                           Net_Stk_Amt_Stk
                  FROM Ias_pr_bill_mst M, Ias_pr_bill_dtl D
                 WHERE M.Rt_Bill_Ser = D.Rt_Bill_Ser AND NVL (M.hung, 0) = 0
              GROUP BY M.Rt_Bill_Doc_Type,
                       M.Brn_Year,
                       M.Brn_No,
                       M.Rt_Bill_Date,
                       ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q') / 2),
                       ROUND (TO_CHAR (M.Rt_Bill_Date, 'Q')),
                       TO_CHAR (M.Rt_Bill_Date, 'MM'),
                       TO_CHAR (M.Rt_Bill_Date, 'WW'),
                       TO_CHAR (M.Rt_Bill_Date, 'DD'),
                       M.Rt_Bill_Currency,
                       M.Cash_No,
                       D.I_Code,
                       D.W_Code,
                       M.V_CODE,
                       M.V_NAME,
                       M.PMAN_CODE,
                       D.Cc_Code,
                       D.Pj_No,
                       D.Actv_No) M,
             Ias_Itm_Mst I
       WHERE M.Itm_Code = I.I_Code
    GROUP BY M.Yr_No,
             M.Brn_No,
             M.Bill_Doc_Type,
             M.Doc_Date,
             M.Half_No,
             M.Qrtr_No,
             M.Prd_No,
             M.Week_No,
             M.Day_No,
             M.Cur_Code,
             M.Cash_No,
             I.I_Code,
             DECODE (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1),
                     1, I.I_Name,
                     NVL (I.I_E_Name, I.I_Name)),
             M.W_Code,
             M.V_CODE,
             M.V_NM,
             M.SMAN_CODE,
             M.SMAN_NM,
             I.G_Code,
             I.Mng_Code,
             I.Subg_Code,
             I.Assistant_No,
             I.Detail_No,
             I.Group_No,
             I.Item_Type,
             I.Grp_Class_Code,
             DECODE (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1),
                     1, I.I_Desc,
                     NVL (I.I_F_Desc, I.I_Desc)),
             M.Cc_Code,
             M.Pj_No,
             M.Actv_No,
             I.Kit_Itm,
             I.Use_Exp_Date,
             I.Use_Batch_No,
             I.Use_Serialno,
             I.Use_Attch;


--
-- APS_V_FLLW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_FLLW
(PUR_NO, PUR_SER, APS_PR, APS_QOUT, APS_CMPR, 
 APS_FLTR, APS_GNR, APS_PO, APS_CHK, APS_INV)
BEQUEATH DEFINER
AS 
Select "PUR_NO","PUR_SER","Aps_Pr","Aps_Qout","Aps_Cmpr","Aps_Fltr","Aps_Gnr","Aps_Po","Aps_Chk","APS_INV"
    From (  Select Distinct Pur_No,PUR_SER, Doc_Typ
              From Aps_V_Trns
              Where Pur_ser Is Not Null 
          Order By Pur_No,Pur_Ser ,Doc_Typ) M 
         Pivot (Count (1)
               For Doc_Typ
               In (40  As "Aps_Pr",
                   41  As "Aps_Qout",
                   156 As "Aps_Cmpr",
                   157 As "Aps_Fltr",
                   43  As "Aps_Gnr",
                   42  As "Aps_Po",
                   116 As "Aps_Chk",
                   6 AS "APS_INV") );


--
-- APS_V_FLLW_TRNS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_FLLW_TRNS
(PUR_NO, PUR_SER, PUR_DATE, PUR_DESC, DOC_TYP, 
 V_CODE, V_NAME, W_CODE, CC_CODE, PJ_NO, 
 HRCHY_NO, PUR_TYPE, ACTV_NO, DELIVERY_DATE, APS_PR, 
 APS_QOUT, APS_CMPR, APS_FLTR, APS_PO, APS_CHK, 
 APS_GNR, APS_INV, CLS_FLG, CLS_DATE, AD_U_ID, 
 AD_DATE, UP_U_ID, UP_DATE, UP_CNT, PR_REP, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, AD_TRMNL_NM, 
 UP_TRMNL_NM, PUR_AMT, A_CY)
BEQUEATH DEFINER
AS 
SELECT 
APS_FLLW_TRNS_MST.PUR_NO, APS_FLLW_TRNS_MST.PUR_SER, PUR_DATE, 
   PUR_DESC, DOC_TYP, V_CODE, 
   V_NAME, W_CODE, CC_CODE, 
   PJ_NO,HRCHY_NO,PUR_TYPE, ACTV_NO, DELIVERY_DATE, 
    APS_PR, APS_QOUT, 
   APS_CMPR, APS_FLTR, APS_PO, 
   APS_CHK, APS_GNR, APS_INV, 
   CLS_FLG, CLS_DATE, AD_U_ID, 
   AD_DATE, UP_U_ID, UP_DATE, 
   UP_CNT, PR_REP, CMP_NO, 
   BRN_NO, BRN_YEAR, BRN_USR, 
   AD_TRMNL_NM, UP_TRMNL_NM, PUR_AMT, 
   A_CY
FROM APS_FLLW_TRNS_MST , APS_V_FLLW 
WHERE APS_FLLW_TRNS_MST.PUR_SER = APS_V_FLLW.PUR_SER;

