--
-- APS_V_P_REQST_WTH_ARS_ORDR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_P_REQST_WTH_ARS_ORDR
(ROWDTL, SO_TYPE, ORDER_NO, ORDER_DATE, C_NAME, 
 A_DESC, REF_DOC_NO, ORDER_SER, BRN_NO, I_CODE, 
 ITM_UNT, P_SIZE, P_QTY, REC_ATTCH, WT_UNT, 
 WT_QTY, ARGMNT_NO, I_LENGTH, I_WIDTH, I_HEIGHT, 
 I_NUMBER, W_CODE, REM_QTY, REQ_QTY, SALES_QTY, 
 CC_CODE, PJ_NO, ACTV_NO, BATCH_NO, DOC_SEQ, 
 RCRD_NO, PROCESED, APPROVED)
BEQUEATH DEFINER
AS 
SELECT   Order_Detail.ROWID ROWDTL,
				             Sales_Order.So_Type,
				             Sales_Order.Order_No,
				             Sales_Order.Order_Date,
				             Sales_Order.C_Name,
				             Sales_Order.A_Desc,
				             Sales_Order.Ref_Doc_No,
				             Sales_Order.Order_Ser,
				             Sales_Order.Brn_No,
				             Order_Detail.I_Code,
				             Order_Detail.itm_unt,
				             Order_Detail.P_Size,
				             Order_Detail.P_Qty,
				             Order_Detail.Rec_Attch,
				             Order_Detail.wt_unt,
				             Order_Detail.wt_qty,
				             Order_Detail.Argmnt_No,
				             Order_Detail.I_Length,
				             Order_Detail.I_Width,
				             Order_Detail.I_Height,
				             Order_Detail.I_Number,
				             Order_Detail.W_Code,
				             (  (  (NVL (SUM (Order_Detail.P_Qty), 0))
				                 / NVL (Order_Detail.P_Size, 1))
				              -   (NVL (SUM (P_Request_detail.P_Qty), 0))
				                / NVL (Order_Detail.P_Size, 1))
				                 Rem_qty,
				               (NVL (SUM (P_Request_detail.P_Qty), 0))
				             / NVL (Order_Detail.P_Size, 1)
				                 REQ_QTY,
				             (NVL (SUM (Order_Detail.P_Qty), 0)) / NVL (Order_Detail.P_Size, 1)
				                 Sales_QTY,
				             Order_Detail.cc_code,
				             Order_Detail.pj_no,
				             Order_Detail.actv_no,
				             Order_Detail.batch_no,
				             Order_Detail.DOC_SEQ,
				             Order_Detail.rcrd_no,
				             Sales_Order.PROCESED,
				             Sales_Order.APPROVED
				    FROM     Sales_Order, Order_Detail, P_Request_detail
				    WHERE        Sales_Order.Order_No = Order_Detail.Order_No
				             AND Sales_Order.Order_SER = Order_Detail.Order_SER
				             AND Order_Detail.i_code = P_Request_detail.i_code(+)
				             AND Order_Detail.Order_Ser = P_Request_detail.Out_Req_Ser(+)
				             AND Order_Detail.Rcrd_No = P_Request_detail.DOC_SEQUENCE_REF(+)
				             AND Sales_Order.Approved = 1
				    HAVING     NVL (SUM (Order_Detail.P_Qty), 0) - (NVL (SUM (P_Request_detail.P_Qty), 0)) > 0
				    GROUP BY Order_Detail.ROWID,
				             Sales_Order.So_Type,
				             Sales_Order.Order_No,
				             Sales_Order.Order_Date,
				             Sales_Order.C_Name,
				             Sales_Order.A_Desc,
				             Sales_Order.Ref_Doc_No,
				             Sales_Order.Order_Ser,
				             Sales_Order.Brn_No,
				             Order_Detail.I_Code,
				             Order_Detail.I_Qty,
				             Order_Detail.itm_unt,
				             Order_Detail.P_Size,
