--
-- APS_V_RT_NET  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.APS_V_RT_NET
(BILL_NO, BILL_SER, AMT)
BEQUEATH DEFINER
AS 
SELECT BILL_NO, BILL_SER, SUM (amt) amt
    FROM (SELECT D.BILL_NO, D.BILL_SER, (SUM (NVL (i_qty, 0) * (NVL (i_price, 0) - NVL (dis_amt, 0) - NVL (DIS_AMT_DTL_FREE_QTY, 0) + NVL (Dis_Amt_Not_Effect, 0) + NVL (D.othr_amt, 0) + NVL (Othr_Amt_Itm, 0)) * M.RT_BILL_RATE) + ROUND (SUM ((NVL (i_qty, 0) + (NVL (Free_Qty, 0) * NVL (M.Clc_Tax_Free_Qty_Flg, 0))) * (NVL (D.vat_amt, 0) + NVL (D.vat_amt_Othr, 0))), 4)) amt
          FROM Ias_Pr_Bill_mst M, Ias_Pr_Bill_Dtl D
          WHERE M.rt_bill_ser = D.rt_bill_ser
          GROUP BY D.BILL_NO, D.BILL_SER
          UNION ALL
          SELECT BILL_NO, BILL_SER, (NVL (SUM (Add_dis_amt_dtl), 0) * NVL (SUM (ADD_DIS_QTY), 0) + NVL (SUM (ADD_VAT_AMT), 0) * NVL (SUM (ADD_DIS_QTY), 0)) amt
          FROM Ias_Pi_Bill_dtl_Add_Disc
          GROUP BY BILL_NO, BILL_SER)
    GROUP BY BILL_NO, BILL_SER;


--
-- ARS_KPI_NET_PYMNT_TYP_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_KPI_NET_PYMNT_TYP_VW
(YR_NO, BRN_NO, BRN_NM, DOC_DATE, PRD_NO, 
 PRD_NM, CUR_CODE, PYMNT_TYP, PYMNT_TYP_NM, NET_PYMNT_AMT)
BEQUEATH DEFINER
AS 
SELECT M.YR_NO,
             M.BRN_NO,
             (SELECT DECODE (
                         NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                         1, NVL (BRN_LNAME, BRN_FNAME),
                         NVL (BRN_FNAME, BRN_LNAME))
                FROM S_BRN
               WHERE BRN_NO = M.BRN_NO)
                 BRN_NM,
             M.DOC_DATE,
             M.PRD_NO,
             (SELECT    LPAD (PRD_NO, 2, '0')
                     || '-'
                     || DECODE (
                            NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                 1),
                            1, PRD_L_NM,
                            NVL (PRD_F_NM, PRD_L_NM))
                FROM S_PRD_DTL
               WHERE PRD_NO = M.PRD_NO)
                 PRD_NM,
             M.CUR_CODE,
             --M.CST_CODE,
             --M.SMAN_CODE,
             M.PYMNT_TYP,
             M.PYMNT_TYP_NM,
             SUM (M.NET_PYMNT_AMT)
                 NET_PYMNT_AMT
        FROM (  SELECT M.BRN_YEAR
                           YR_NO,
                       M.BRN_NO,
                       M.BILL_DATE
                           DOC_DATE,
                       TO_CHAR (M.BILL_DATE, 'MM')
                           PRD_NO,
                       M.BILL_CURRENCY
                           CUR_CODE,
                       --M.C_CODE CST_CODE,
                       --M.REP_CODE SMAN_CODE,
                       M.BILL_DOC_TYPE
                           PYMNT_TYP,
                       YS_GEN_PKG.GET_FLG_NM (
                           P_FLG_CODE    => 'TYPE_NAME_SI',
                           P_FLG_VALUE   => M.BILL_DOC_TYPE,
                           P_LNG_NO      =>
                               NVL (
                                   IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                   1))
                           PYMNT_TYP_NM,
                       ROUND (
                           SUM (
                                 (  NVL (M.BILL_AMT, 0)
                                  + NVL (M.CHEQUE_AMT, 0)
                                  + NVL (M.CR_CARD_AMT, 0)
                                  + NVL (M.CR_CARD_AMT_SCND, 0)
                                  + NVL (M.CR_CARD_AMT_THRD, 0)
                                  + NVL (M.AC_AMT, 0)
                                  + NVL (M.CPN_AMT, 0))
                               * NVL (M.BILL_RATE, 1)),
                           4)
                           NET_PYMNT_AMT
                  FROM IAS_BILL_MST M
                 WHERE NVL (M.STAND_BY, 0) = 0
              GROUP BY M.BRN_YEAR,
                       M.BRN_NO,
                       M.BILL_DATE,
                       TO_CHAR (M.BILL_DATE, 'MM'),
                       M.BILL_CURRENCY,
                       --M.C_CODE,
                       --M.REP_CODE,
                       M.BILL_DOC_TYPE
              UNION ALL
                SELECT M.BRN_YEAR
                           YR_NO,
                       M.BRN_NO,
                       M.RT_BILL_DATE
                           DOC_DATE,
                       TO_CHAR (M.RT_BILL_DATE, 'MM')
                           PRD_NO,
                       M.RT_BILL_CURRENCY
                           CUR_CODE,
                       --M.C_CODE CST_CODE,
                       --M.REP_CODE SMAN_CODE,
                       M.RT_BILL_DOC_TYPE
                           PYMNT_TYP,
                       YS_GEN_PKG.GET_FLG_NM (
                           P_FLG_CODE    => 'TYPE_NAME_SI',
                           P_FLG_VALUE   => M.RT_BILL_DOC_TYPE,
                           P_LNG_NO      =>
                               NVL (
                                   IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                   1))
                           PYMNT_TYP_NM,
                       ROUND (
                           SUM (
                                 (  NVL (M.BILL_AMT, 0)
                                  + NVL (M.CHEQUE_AMT, 0)
                                  + NVL (M.CR_CARD_AMT, 0)
                                  + NVL (M.CR_CARD_AMT_SCND, 0)
                                  + NVL (M.CR_CARD_AMT_THRD, 0)
                                  + NVL (M.AC_AMT, 0))
                               * NVL (M.RT_BILL_RATE, 1)),
                           4)
                           NET_PYMNT_AMT
                  FROM IAS_RT_BILL_MST M
                 WHERE NVL (M.STAND_BY, 0) = 0
              GROUP BY M.BRN_YEAR,
                       M.BRN_NO,
                       M.RT_BILL_DATE,
                       TO_CHAR (M.RT_BILL_DATE, 'MM'),
                       M.RT_BILL_CURRENCY,
                       --M.C_CODE,
                       --M.REP_CODE,
                       M.RT_BILL_DOC_TYPE) M
       WHERE 1 = 1                            --AND M.PYMNT_TYP_NM IS NOT NULL
    GROUP BY M.YR_NO,
             M.BRN_NO,
             M.DOC_DATE,
             M.PRD_NO,
             M.CUR_CODE,
             --M.CST_CODE,
             --M.SMAN_CODE,
             M.PYMNT_TYP,
             M.PYMNT_TYP_NM;

COMMENT ON TABLE IAS20261.ARS_KPI_NET_PYMNT_TYP_VW IS '’«›Ì «·„»Ì⁄«  Õ”» ÿ—ﬁ «·œ›⁄';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.YR_NO IS '«·”‰…';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.BRN_NO IS '«·›—⁄';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.DOC_DATE IS ' «—ÌŒ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.PRD_NO IS '«·› —…';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.PRD_NM IS '«”„ «·› —…';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.CUR_CODE IS '«·⁄„·…';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.PYMNT_TYP IS 'ÿ—Ìﬁ… «·œ›⁄';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.PYMNT_TYP_NM IS '‰Ê⁄ ÿ—Ìﬁ… «·œ›⁄';

COMMENT ON COLUMN IAS20261.ARS_KPI_NET_PYMNT_TYP_VW.NET_PYMNT_AMT IS '’«›Ì «·„»·€ Õ”» ÿ—Ìﬁ… «·œ›⁄';



--
-- ARS_KPI_SMAN_MNTHLY_PLAN_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_KPI_SMAN_MNTHLY_PLAN_VW
(REP_CODE, REP_NM, PRD_NO, PRD_NM, TRGT_AMT, 
 ACTL_AMT)
BEQUEATH DEFINER
AS 
SELECT REP_CODE,
             REP_NAME
                 REP_NM,
             PRD_NO,
             (SELECT    LPAD (PRD_NO, 2, '0')
                     || '-'
                     || DECODE (
                            NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                 1),
                            1, PRD_L_NM,
                            NVL (PRD_F_NM, PRD_L_NM))
                FROM S_PRD_DTL
               WHERE PRD_NO = TO_NUMBER (SMAN_PLAN.PRD_NO))
                 PRD_NM,
             TRGT_AMT,
             (  NVL (
                    (SELECT SUM (
                                ROUND (
                                      (  (  NVL (MST.BILL_AMT, 0)
                                          + NVL (MST.OTHR_AMT, 0))
                                       - NVL (MST.DISC_AMT, 0))
                                    * NVL (BILL_RATE, 1),
                                    4))
                       FROM IAS_BILL_MST MST
                      WHERE     MST.REP_CODE = SMAN_PLAN.REP_CODE
                            AND TO_CHAR (MST.BILL_DATE, 'MM') =
                                SMAN_PLAN.PRD_NO
                            AND TO_CHAR (MST.BILL_DATE, 'MM') =
                                TO_CHAR (SYSDATE, 'MM')),
                    0)
              - NVL (
                    (SELECT SUM (
                                ROUND (
                                      (  (  NVL (MST.BILL_AMT, 0)
                                          + NVL (MST.OTHR_AMT, 0))
                                       - NVL (MST.DISC_AMT, 0))
                                    * NVL (RT_BILL_RATE, 1),
                                    4))
                       FROM IAS_RT_BILL_MST MST
                      WHERE     MST.REP_CODE = SMAN_PLAN.REP_CODE
                            AND TO_CHAR (MST.RT_BILL_DATE, 'MM') =
                                SMAN_PLAN.PRD_NO
                            AND TO_CHAR (MST.RT_BILL_DATE, 'MM') =
                                TO_CHAR (SYSDATE, 'MM')),
                    0))
                 ACTL_AMT
        FROM (  SELECT REP_CODE,
                       DECODE (
                           NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),
                           1, NVL (REPRS_A_NAME, REPRS_E_NAME),
                           NVL (REPRS_E_NAME, REPRS_A_NAME))
                           REP_NAME,
                       TO_CHAR (F_DATE, 'MM')
                           PRD_NO,
                       SUM (LOCAL_AMT)
                           TRGT_AMT
                  FROM IAS_SALES_PLAN_DTL DTL, SALES_MAN MST
                 WHERE     MST.REPRS_CODE = DTL.REP_CODE
                       AND MST.PLAN_NO = DTL.PLAN_NO
                       AND MST.PLAN_SER = DTL.PLAN_SER
                       AND TO_CHAR (F_DATE, 'MM') = TO_CHAR (SYSDATE, 'MM')
              GROUP BY REP_CODE,
                       DECODE (
                           NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),
                                1),
                           1, NVL (REPRS_A_NAME, REPRS_E_NAME),
                           NVL (REPRS_E_NAME, REPRS_A_NAME)),
                       TO_CHAR (F_DATE, 'MM')) SMAN_PLAN
    ORDER BY REP_CODE, PRD_NO;


--
-- ARS_V_BILL_ADVNC_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_BILL_ADVNC_DTL
(DOC_TYP, DOC_NO, DOC_SRL, A_CY, AC_RATE, 
 I_CODE, ITM_UNT, I_QTY, FREE_QTY, I_PRICE, 
 I_PRICE_VAT, DIS_AMT, VAT_PER, VAT_AMT, RCRD_NO, 
 DOC_SEQUENCE)
BEQUEATH DEFINER
AS 
SELECT 53 Doc_typ,
          M.Order_no Doc_no,
          M.Order_ser Doc_srl,
          M.Order_cur A_cy,
          M.Cur_rate,
          D.I_code,
          D.Itm_unt,
          D.I_qty,
          D.Free_qty,
          ((M.Advnc_pymnt_amt-Nvl(M.Advnc_pymnt_vat_amt,0))/Order_amt)*D.I_price I_price, 
          ((M.Advnc_pymnt_amt)/(Order_amt+M.Vat_Amt))*D.I_price_Vat I_price_vat, --D.I_price_vat,
          D.Dis_amt,
          M.Advnc_pymnt_vat_per Vat_per,
          (M.Advnc_pymnt_vat_amt/Order_amt)*D.I_price Vat_amt,
          D.Rcrd_no,
          D.Doc_seq
     From Sales_order M, Order_detail D
    WHERE M.Order_ser = D.Order_ser AND NVL (M.Advnc_pymnt_amt, 0) > 0
   UNION ALL
   SELECT 143 Doc_typ,
          M.Doc_no Doc_no,
          M.Doc_srl,
          M.Cntrct_a_cy A_cy,
          M.Cntrct_rate Cur_rate,
          D.I_code,
          D.Itm_unt,
          D.I_qty,
          D.Free_qty,
          (Select ((B.Amt-Nvl(B.Advnc_pymnt_vat_amt,0))/M.Cntrct_amt)*D.I_price From Ias_ar_cntrct_btch B Where B.Doc_srl=M.Doc_srl And Nvl(B.Advnc_pymnt, 0) = 1) I_price,--D.I_price,
          (Select ((B.Amt)/(M.Cntrct_amt+M.Vat_Amt))*D.I_Price_Vat From Ias_ar_cntrct_btch B Where B.Doc_srl=M.Doc_srl And Nvl(B.Advnc_pymnt, 0) = 1) I_Price_Vat, --D.I_price_vat,
          D.Dis_amt,
          (Select Advnc_pymnt_vat_per From Ias_ar_cntrct_btch B Where B.Doc_srl=M.Doc_srl And Nvl(B.Advnc_pymnt, 0) = 1) Vat_per,--D.Vat_per,
          (Select ((Nvl(B.Advnc_pymnt_vat_amt,0))/M.Cntrct_amt)*D.I_price From Ias_ar_cntrct_btch B Where B.Doc_srl=M.Doc_srl And Nvl(B.Advnc_pymnt, 0) = 1) Vat_amt, --D.Vat_amt,
          D.Rcrd_no,
          1 Doc_sequence
     FROM Ias_ar_cntrct_mst M, Ias_ar_cntrct_dtl D
    WHERE M.Doc_srl = D.Doc_srl 
      AND NVL (M.Advnc_pymnt_prcnt_cntrct, 0) > 0;

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.DOC_TYP IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.DOC_SRL IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.A_CY IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.ARS_V_BILL_ADVNC_DTL.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

