--
-- ARS_V_CST_SAL_DOC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_CST_SAL_DOC
(DOC_SER, DOC_NO, BRN_NO, BRN_NM, DOC_TYPE, 
 DOC_TYP_NAME, DOC_DESC, DOC_AMT, DOC_CUR, DOC_RATE, 
 DOC_DUE_DATE, DOC_DATE, REF_NO, DOC_STATE, C_CODE)
BEQUEATH DEFINER
AS 
SELECT  BILL_SER, BILL_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,4 DOC_TYPE,
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),4) docTypName,A_DESC, NVL(BILL_AMT,0)+NVL(VAT_AMT,0)+NVL(OTHR_AMT,0)-NVL(DISC_AMT,0)BILL_AMT,
bill_currency,bill_rate  ,BILL_DUE_DATE , BILL_DATE , REF_NO ,
ias_gen_pkg.get_flg_nm('ARS_BILL_STATUS',BILL_STAT_TYP,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))stat,C_CODE 
FROM IAS_BILL_MST   
