select RT_BILL_SER,rt_bill_no,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,5 DOC_TYPE,
 doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),5) ,a_desc,NVL(BILL_AMT,0)+NVL(VAT_AMT,0)+NVL(OTHR_AMT,0)-NVL(DISC_AMT,0)bill_amt,rt_bill_currency ,rt_bill_rate,rt_bill_due_date,rt_bill_date 
,ref_no, null st,C_CODE 
from ias_rt_bill_mst  
 WHERE C_CODE IS NOT NULL
UNION ALL 
select OUT_SER , OUT_NO ,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm ,13 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),13),A_DESC,NVL(OUT_AMT,0)OUT_AMT ,bill_currency ,bill_rate,OUT_DATE,OUT_DATE,REF_NO 
,NULL ST ,C_CODE 
from master_OUT_BILLS 
 WHERE C_CODE IS NOT NULL
UNION ALL 
SELECT RET_SER, RET_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,14 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),14),DOC_DESC,NVL(RET_AMT,0)RET_AMT,A_CY,AC_RATE,RET_DATE,RET_DATE,
REF_NO,NULL ST,C_CODE  
FROM IAS_RET_BILL_MST
 WHERE C_CODE IS NOT NULL
UNION ALL 
Select DOC_SER, doc_no,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,15 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),15) ,DOC_DESC,NVL(ADD_DISC_AMT_MST,0)ADD_DISC_AMT_MST,A_CY,DOC_RATE,DOC_DATE,DOC_DATE,ref_No 
,NULL stat,C_CODE
 from  IAS_BILL_MST_ADD_DISC 
 WHERE C_CODE IS NOT NULL
UNION ALL 
SELECT ORDER_SER , ORDER_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,53 DOC_TYPE,
 doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),53) docTypName,A_DESC, NVL(ORDER_AMT,0)+NVL(VAT_AMT,0)+NVL(OTHR_AMT,0)-NVL(DISC_AMT,0)ORDER_AMT,ORDER_CUR,CUR_RATE ,BILL_DUE_DATE , ORDER_DATE ,REF_DOC_NO ,
ias_gen_pkg.get_flg_nm('APPROVED',NVL(APPROVED,1),NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))STAT ,C_CODE 
FROM SALES_ORDER   
WHERE C_CODE IS NOT NULL 
UNION ALL 
SELECT QUOT_SER, QUOT_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,52 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),52) docTypName,A_DESC,NVL(QUOT_AMT,0)+NVL(VAT_AMT,0)+NVL(OTHR_AMT,0)-NVL(DISC_AMT,0) QUOT_AMT,QUOT_CUR,CUR_RATE ,QUOT_DUE_DATE , QUOT_DATE , REF_NO ,
ias_gen_pkg.get_flg_nm('APPROVED',NVL(APPROVED,1),NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))STAT ,C_CODE 
FROM QUOTATION  
 WHERE C_CODE IS NOT NULL
UNION ALL 
SELECT DOC_SRL, DOC_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,143 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),143) docTypName,CNTRCT_NOTE,NVL(CNTRCT_AMT,0)+NVL(VAT_AMT,0)-NVL(DISC_AMT,0) CNTRCT_AMT,CNTRCT_A_CY,CNTRCT_RATE ,CNTRCT_DATE , CNTRCT_DATE , REF_NO ,
ias_gen_pkg.get_flg_nm('APPROVED',NVL(APPROVED,1),NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))STAT ,C_CODE 
FROM IAS_AR_CNTRCT_MST  
WHERE C_CODE IS NOT NULL
union all 
select D.doc_No, D.doc_SER,M.BRN_NO,ias_brn_pkg.Get_Br_Nm(M.brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,123 DOC_TYPE,
 SUBSTR(doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),123),1,14)docTypName,
NVL(CPN_DSC,doc_dsc),I_PRICE,A_CY,CUR_RATE  ,DOC_DATE,DOC_DATE DOC_DUE_DATE ,
ref_no ,NULL stat ,M.C_CODE C_CODE 
 from  IAS_SAL_CPN_MST M ,IAS_SAL_CPN_DTL  D  
 WHERE M.C_CODE IS NOT NULL
UNION ALL 
SELECT DOC_SRL , DOC_NO,brn_No,ias_brn_pkg.Get_Br_Nm(brn_No,NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))brn_nm,160 DOC_TYPE, 
doc_type_name(NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1),160)docTypName,DOC_DSC,NULL AMT,A_CY,NULL CUR_RATE ,DOC_DATE,T_DATE,REF_NO,
ias_gen_pkg.get_flg_nm('APPROVED',NVL(APPROVED,1),NVL(IAS_PRMTR_PKG.GetPval (p_prmtr => 'LANG_NO'), 1))STAT ,C_CODE 
FROM IAS_RQ_CMPNS_QTY_CLC_MST
WHERE C_CODE IS NOT NULL;

COMMENT ON COLUMN IAS20261.ARS_V_CST_SAL_DOC.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.ARS_V_CST_SAL_DOC.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.ARS_V_CST_SAL_DOC.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.ARS_V_CST_SAL_DOC.DOC_TYPE IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';

