--
-- ARS_V_GLS_INSTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_GLS_INSTL
(DOC_TYP_INSTL1, DOC_TYP_INSTL2, DOC_TYP_INSTL3, DOC_TYP_INSTL4, DOC_TYP, 
 LOV_NM, TBL_NM_MST, TBL_NM_DTL, DOC_SRL, BRN_NO, 
 DOC_NO, DOC_DATE, DOC_JV_TYPE_REF, HSTR, AC_CODE, 
 AC_CODE_DTL, AC_CODE_DTL_SUB, C_NAME, CUR_CODE, CUR_RATE, 
 COL_NO, REP_CODE, DOC_BRN_NO, AC_DTL_TYP, DOC_DSC, 
 REF_NO, CC_CODE, PJ_NO, ACTV_NO, GLS_PRCSSD_FLG, 
 AD_U_ID, DOC_AMT, PAID_AMT, REM_AMT)
BEQUEATH DEFINER
AS 
WITH
        BAL_VW AS
            (  SELECT SUM (ABS (AC_AMT))  SUM_AC_AMT     ,DOC_SER_REF     ,AC_CODE_DTL     ,AC_CODE_DTL_SUB
                 FROM VOUCHER_DETAIL
             GROUP BY DOC_SER_REF, AC_CODE_DTL, AC_CODE_DTL_SUB),
        PARA AS  (SELECT NVL (NO_OF_DECIMAL, 2)  NO_OF_DECIMAL FROM IAS_PARA_GL     WHERE ROWNUM <= 1),
        CLAIM AS
            (  SELECT M.DOC_SER  ,M.BRN_NO     ,M.DOC_NO     ,M.DOC_DATE     ,M.CLAIM_TYP    ,M.C_CODE     ,D.PTNT_NO
                     ,M.A_CY     ,M.DOC_DSC    ,M.REF_NO     ,M.PROCESSED    ,M.APPROVED     ,M.AD_U_ID
                     ,SUM (D.NET_AMT)          NET_AMT
                     ,SUM (D.NET_BILL_AMT)     NET_BILL_AMT
                 FROM IAS_CST_CLAIM_MST M, IAS_CST_CLAIM_DTL D
                WHERE M.DOC_SER = D.DOC_SER
             GROUP BY M.DOC_SER
                     ,M.BRN_NO
                     ,M.DOC_NO
                     ,M.DOC_DATE
                     ,M.CLAIM_TYP
                     ,M.C_CODE
                     ,D.PTNT_NO
                     ,M.A_CY
                     ,M.DOC_DSC
                     ,M.REF_NO
                     ,M.PROCESSED
                     ,M.APPROVED
                     ,M.AD_U_ID)
    SELECT 2                                                                         DOC_TYP_INSTL1
          ,NULL                                                                      DOC_TYP_INSTL2
          ,NULL                                                                      DOC_TYP_INSTL3
          ,NULL                                                                      DOC_TYP_INSTL4
          ,103                                                                       DOC_TYP
          ,'LOV_GLS_ARS_INSTL'                                                     LOV_NM
          ,'IAS_CST_CLAIM_MST'                                                     TBL_NM_MST
          ,'IAS_CST_CLAIM_DTL'                                                     TBL_NM_DTL
          ,M.DOC_SER                                                                 DOC_SRL
          ,M.BRN_NO                                                                  BRN_NO
          ,M.DOC_NO                                                                  DOC_NO
          ,M.DOC_DATE                                                                DOC_DATE
          ,M.CLAIM_TYP                                                               DOC_JV_TYPE_REF
          ,0                                                                         HSTRY
          ,C.C_A_CODE                                                                AC_CODE
          ,M.C_CODE                                                                  AC_CODE_DTL
          ,M.PTNT_NO                                                                 AC_CODE_DTL_SUB
          ,NVL (C_A_NAME, C_E_NAME)                                                  C_NAME
          ,M.A_CY                                                                    CUR_CODE
          ,NULL                                                                      CUR_RATE
          ,NULL                                                                      COL_NO
          ,NULL                                                                      REP_CODE
          ,NULL                                                                      DOC_BRN_NO
          ,YS_AC_DTL_PKG.GET_AC_DTL_TYP (C.C_A_CODE)                                 AC_DTL_TYP
          ,M.DOC_DSC                                                                 DOC_DSC
          ,M.REF_NO
          ,NULL                                                                      CC_CODE
          ,NULL                                                                      PJ_NO
          ,NULL                                                                      ACTV_NO
          ,M.PROCESSED                                                               GLS_PRCSSD_FLG
          ,M.AD_U_ID
          ,ROUND(NVL(M.NET_AMT, 0), PARA.NO_OF_DECIMAL)                              DOC_AMT
          ,ROUND(NVL(ABS (BAL_VW.SUM_AC_AMT), 0), PARA.NO_OF_DECIMAL)                PAID_AMT
          ,ROUND(NVL(M.NET_AMT,0)-NVL(ABS(BAL_VW.SUM_AC_AMT),0),PARA.NO_OF_DECIMAL)  REM_AMT
      FROM CLAIM     M
          ,CUSTOMER  C
          ,BAL_VW
          ,PARA
     WHERE M.C_CODE = C.C_CODE 
       AND M.APPROVED = 1 
       AND M.DOC_SER = BAL_VW.DOC_SER_REF(+) 
       AND M.C_CODE = BAL_VW.AC_CODE_DTL(+) 
       AND M.PTNT_NO = BAL_VW.AC_CODE_DTL_SUB(+) 
       AND NVL (M.NET_BILL_AMT, 0) - NVL (BAL_VW.SUM_AC_AMT, 0) > 0
    UNION ALL
	   SELECT 3 doc_typ_instl1, 93 doc_typ_instl2, NULL doc_typ_instl3,
	          NULL doc_typ_instl3, 5 doc_typ, 'LOV_GLS_ARS_INSTL' lov_nm,
	          'IAS_RT_BILL_MST' tbl_nm_mst, 'IAS_RT_BILL_DTL' tbl_nm_dtl,
	          m.rt_bill_ser doc_srl, m.brn_no brn_no, m.rt_bill_no doc_no,
	          m.rt_bill_date doc_date, m.sr_type doc_jv_type_ref, 0 hstry,
	          c.c_a_code ac_code, m.c_code ac_code_dtl, m.ptnt_no ac_code_dtl_sub,
	          NVL (c_a_name, c_e_name) c_name, m.rt_bill_currency cur_code,
	          NULL cur_rate, NULL col_no, NULL rep_code, NULL doc_brn_no,
	          ys_ac_dtl_pkg.get_ac_dtl_typ (c.c_a_code) ac_dtl_typ,
	          m.a_desc doc_dsc, m.ref_no ref_no, NULL cc_code, NULL pj_no,
	          NULL actv_no, m.processed gls_prcssd_flg, m.ad_u_id ad_u_id,
	          ROUND ((  NVL (bill_amt, 0)
	                  - NVL (disc_amt_mst, 0)
	                  - NVL (disc_amt_dtl, 0)
	                  + NVL (othr_amt, 0)
	                  + NVL (vat_amt, 0)
	                  + NVL (vat_amt_othr, 0)
	                  - NVL ((SELECT SUM (NVL (i_qty, 0) * NVL (add_dis_amt, 0))
	                            FROM Ias_Rt_Bill_Dtl
	                           WHERE Rt_Bill_Ser = M.Rt_Bill_Ser),
	                         0
	                        )
	                 )
	                 ,Ias_Gen_Pkg.Get_Fld_Value ('IAS_PARA_GL',  'nvl(NO_OF_DECIMAL,2)', ' Where 1=1 ' )
	                ) doc_amt,
	         ROUND (NVL ((SELECT SUM (ABS (Case
	                                         When M.Rt_Bill_Currency =Ias_Gen_Pkg.Get_Local_Cur  Then    AMT_L
	                                         Else    Nvl (AMT_F, 0)
	                                        End))
	                         FROM GLS_V_DOC_INSTL
	                        WHERE Doc_Ser_Ref = M.Rt_Bill_Ser
	                          AND NVL (Ac_Code_Dtl, '0')     = NVL (M.C_Code, '0')
	                          AND NVL (Ac_Code_Dtl_Sub, '0') = NVL (M.Ptnt_No, '0')),
	                      0
	                     )
	                ,Ias_Gen_Pkg.Get_Fld_Value ('IAS_PARA_GL',  'nvl(NO_OF_DECIMAL,2)', ' Where 1=1 ' )
	                ) paid_AMT,
	          ROUND (  (  NVL (bill_amt, 0)
	                    - NVL (disc_amt_mst, 0)
	                    - NVL (disc_amt_dtl, 0)
	                    + NVL (othr_amt, 0)
	                    + NVL (vat_amt, 0)
	                    + NVL (vat_amt_othr, 0)
	                    - NVL ((SELECT SUM (NVL (i_qty, 0) * NVL (add_dis_amt, 0))
	                              FROM ias_rt_bill_dtl
	                             WHERE rt_bill_ser = m.rt_bill_ser),
	                           0
	                          )
	                   )
	               -  NVL ((SELECT SUM (ABS (Case
	                                         When M.Rt_Bill_Currency =Ias_Gen_Pkg.Get_Local_Cur  Then    AMT_L
	                                         Else    Nvl (AMT_F, 0)
	                                        End))
	                         FROM GLS_V_DOC_INSTL
	                        WHERE Doc_Ser_Ref = m.Rt_Bill_Ser
	                          AND NVL (Ac_Code_Dtl, '0')     = NVL (M.C_Code, '0')
	                          AND NVL (Ac_Code_Dtl_Sub, '0') = NVL (M.Ptnt_No, '0')),
	                      0
	                     )
	                ,Ias_Gen_Pkg.Get_Fld_Value ('IAS_PARA_GL',  'nvl(NO_OF_DECIMAL,2)', ' Where 1=1 ' )
	                ) rem_amt
	     FROM Ias_Rt_Bill_Mst M, Customer C
	    WHERE m.c_code = c.c_code
        AND M.RT_BILL_DOC_TYPE=4
	      AND ROUND (  (  NVL (bill_amt, 0)
	                    - NVL (disc_amt_mst, 0)
	                    - NVL (disc_amt_dtl, 0)
	                    + NVL (othr_amt, 0)
	                    + NVL (vat_amt, 0)
	                    + NVL (vat_amt_othr, 0)
	                    - NVL ((SELECT SUM (NVL (i_qty, 0) * NVL (add_dis_amt, 0))
	                              FROM ias_rt_bill_dtl
	                             WHERE rt_bill_ser = M.Rt_Bill_Ser),
	                           0
	                          )
	                   )
	                 -  NVL ((SELECT SUM (ABS (Case
	                                           When M.Rt_Bill_Currency =Ias_Gen_Pkg.Get_Local_Cur  Then    AMT_L
	                                           Else    Nvl (AMT_F, 0)
	                                           End))
	                         FROM GLS_V_DOC_INSTL
	                        WHERE Doc_Ser_Ref = M.Rt_Bill_Ser
	                          AND NVL (Ac_Code_Dtl, '0')     = NVL (M.C_Code, '0')
	                          AND NVL (AC_CODE_DTL_SUB, '0') = NVL (M.Ptnt_No, '0')),
	                      0
	                     )
	                ,Ias_Gen_Pkg.Get_Fld_Value ('IAS_PARA_GL',  'Nvl(NO_OF_DECIMAL,2)', ' Where 1=1 ' )
	                ) > 0;

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_TYP IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_SRL IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_DATE IS '1137 -  «—ÌŒ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.AC_CODE IS '129 - —ﬁ„ «·Õ”«»';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.AC_CODE_DTL IS '1041 - «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.CUR_CODE IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.COL_NO IS '1222 - —ﬁ„ «·„Õ’·';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.REP_CODE IS '395 - —ﬁ„ «·„‰œÊ»';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_BRN_NO IS '3823 - —ﬁ„ «·›—⁄ «·„” ›Ìœ';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.AC_DTL_TYP IS '3398 - ‰Ê⁄ «·Õ”«» «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.DOC_DSC IS '146 - «·»Ì«‰';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.REF_NO IS '143 - —ﬁ„ «·„—Ã⁄';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.PJ_NO IS '2452 - —ﬁ„ «·„‘—Ê⁄';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL.ACTV_NO IS '2241 - —ﬁ„ «·‰‘«ÿ';



--
-- ARS_V_GLS_INSTL_BILL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_GLS_INSTL_BILL
(DOC_TYP_INSTL1, DOC_TYP_INSTL2, DOC_TYP_INSTL3, DOC_TYP_INSTL4, DOC_TYP, 
 LOV_NM, TBL_NM_MST, TBL_NM_DTL, DOC_SRL, DOC_NO, 
 DOC_DATE, CUR_CODE, DOC_JV_TYPE, AC_CODE, AC_DTL_TYP, 
 AC_CODE_DTL, AC_CODE_DTL_SUB, C_NAME, BRN_NO, DOC_BRN_NO, 
 W_CODE, CC_CODE, PJ_NO, ACTV_NO, REP_CODE, 
 EMP_NO, COL_NO, DOC_DSC, INSRNCE_PRSON_NM, REF_NO, 
 BILL_DOC_TYPE, AD_U_ID, BILL_AMT, REM_AMT, PAID_BILL)
BEQUEATH DEFINER
AS 
SELECT 2 Doc_typ_instl1
    , 92 Doc_typ_instl2
    , NULL Doc_typ_instl3
    , NULL Doc_typ_instl4
    , 4 Doc_typ
    , 'LOV_ARS_GLS_BILL' Lov_nm
    , 'IAS_BILL_MST' Tbl_nm_mst
    , 'IAS_BILL_DTL' Tbl_nm_dtl
    , Ias_bill_mst.Bill_ser Doc_Srl
    , Ias_bill_mst.Bill_no   DOC_NO 
    , Ias_bill_mst.Bill_date  DOC_DATE
    , Ias_bill_mst.BILL_CURRENCY Cur_Code
    , Ias_bill_mst.Si_type  DOC_JV_TYPE 
    , NVL(IAS_BILL_MST.AC_CODE,IAS_BILL_MST.A_CODE) AC_CODE         ---Ias_bill_mst.A_code  Ac_Code
    , YS_AC_DTL_PKG.GET_AC_DTL_TYP (P_A_CODE =>IAS_BILL_MST.A_CODE) AC_DTL_TYP
    , NVL(IAS_BILL_MST.AC_CODE_DTL,IAS_BILL_MST.C_CODE) AC_CODE_DTL ---- Ias_bill_mst.C_code  Ac_Code_Dtl
    , Ias_bill_mst.PTNT_NO Ac_Code_Dtl_sub
    , Ias_bill_mst.C_name
    , Ias_bill_mst.Brn_no
    , Ias_bill_mst.DOC_BRN_NO
    , Ias_bill_mst.W_code
    , Ias_bill_mst.Cc_code
    , Ias_bill_mst.pj_no 
    , Ias_bill_mst.actv_no  
    , Ias_bill_mst.REP_CODE 
    , Ias_bill_mst.EMP_NO 
    , Ias_bill_mst.COL_NO 
    , Ias_bill_mst.A_DESC  doc_dsc
    , Ias_bill_mst.Insrnce_prson_nm
    , Ias_bill_mst.Ref_no
    , Ias_bill_mst.Bill_doc_type
    , Ias_bill_mst.AD_U_ID
    , ROUND (NVL (BILLS.BILL_AMT, 0), NVL (PARA.NO_OF_DECIMAL, 2))  Bill_amt
    , ROUND(((Bills.Bill_amt - NVL(Rtrn.Rtrn_amt, 0) - NVL(Add_disc.Add_vat_amt, 0)) * NVL(Ias_bill_mst.Bill_rate, 1)) - NVL(Vchr.Vchr_amt, 0)
            , NVL(Para.No_of_decimal, 2)) / NVL(Ias_bill_mst.Bill_rate, 1)    REM_AMT
    , NVL(Paid_bill, 0)       Paid_bill 
FROM Ias_bill_mst
     , Ias_para_gl Para
    ,(
           SELECT M.BILL_SER, SUM (DECODE (M.BILL_DOC_TYPE, 1, NVL (AC_AMT, 0), NVL (BILL_AMT, 0) + NVL (VAT_AMT, 0) + NVL (OTHR_AMT, 0) + NVL (VAT_AMT_OTHR, 0) - NVL (AC_AMT, 0) - NVL (DISC_AMT, 0) - NVL (M.DISC_AMT_AFTR_VAT, 0))) BILL_AMT
             FROM IAS_BILL_MST M
            WHERE (M.BILL_DOC_TYPE = 4 OR ((M.BILL_DOC_TYPE = 8 OR NVL (M.PYMNT_AC, 0) = 1) AND M.AC_DTL_TYP = 3)) AND NVL (M.STAND_BY, 0) = 0 AND NVL (M.EXTERNAL_POST, 0) IN (0, 187)
         GROUP BY M.BILL_SER
     ) BILLS ------------------------------------------ BILL
     , (
         SELECT D.Bill_ser , SUM((NVL(D.I_price, 0) * NVL(D.I_qty, 0)) + (NVL(D.Vat_amt, 0) * NVL(D.I_qty, 0)) + (NVL(D.Othr_amt, 0) * NVL(D.I_qty, 0)) + (NVL(Vat_amt_othr, 0) * NVL(D.I_qty, 0)) - (NVL(D.Dis_amt, 0) * NVL(D.I_qty, 0)) - (NVL(D.Dis_amt_aftr_vat, 0) * NVL(D.I_qty, 0))) Rtrn_amt
           FROM Ias_rt_bill_dtl D
           GROUP BY D.Bill_ser
       ) Rtrn                                       ------------------------------------------ RETURN
     , (
         SELECT D.Bill_ser, SUM(NVL(Add_vat_amt, 0) * NVL(Add_dis_qty, 0)) Add_vat_amt
           FROM Ias_bill_dtl_add_disc D
          GROUP BY D.Bill_ser
       ) Add_disc                                   ---------------------------------------- ADD DISC
     , (
         SELECT Doc_ser_ref, SUM(Vchr_amt) Vchr_amt
           FROM (   SELECT Doc_ser_ref, SUM(NVL(ABS(Ac_amt), 0)) Vchr_amt
                        FROM Voucher_detail
                       WHERE Doc_type_ref = 4 AND Voucher_type = 1
                    GROUP BY Doc_ser_ref
                    UNION ALL
                      SELECT Doc_ser_ref, SUM(NVL(ABS(J_amt), 0)) Vchr_amt
                        FROM Detail_journal_v
                       WHERE Doc_type_ref = 4 AND J_amt < 0
                    GROUP BY Doc_ser_ref
                    UNION ALL
                      SELECT D_adj.Doc_ser_ref, SUM(NVL(ABS(Paid_amt_doc), 0)) Vchr_amt
                        FROM Ias_adjst_installment_mst M_adj, Ias_adjst_installment_dtl D_adj
                       WHERE M_adj.Doc_ser = D_adj.Doc_ser AND M_adj.Doc_type_ref IN (1, 2)
                    GROUP BY D_adj.Doc_ser_ref
                )
           GROUP BY Doc_ser_ref
       ) Vchr                             ---------------------------------------- VOCHR + JRNL + ADJ
 WHERE Ias_bill_mst.Bill_ser = Bills.Bill_ser
    AND Ias_bill_mst.Bill_ser = Rtrn.Bill_ser(+)
    AND Ias_bill_mst.Bill_ser = Add_disc.Bill_ser(+)
    AND Ias_bill_mst.Bill_ser = Vchr.Doc_ser_ref(+)
    And Nvl(Ias_bill_mst.STAND_BY,0)=0  
    AND  (Ias_bill_mst.BILL_DOC_TYPE=4 Or ((Ias_bill_mst.BILL_DOC_TYPE=8 or nvl(Ias_bill_mst.pymnt_ac,0)=1) AND Ias_bill_mst.AC_CODE_DTL IS NOT NULL and Ias_bill_mst.ac_dtl_typ=3))               
    And Exists(Select 1 From INSTALLMENT WHERE BILL_SER=Ias_bill_mst.BILL_SER  AND NVL(MOVE_CY,0)=0 AND ROWNUM<=1) 
           AND ROUND(((Bills.Bill_amt - NVL(Rtrn.Rtrn_amt, 0) - NVL(Add_disc.Add_vat_amt, 0)) * NVL(Ias_bill_mst.Bill_rate, 1)) - NVL(Vchr.Vchr_amt, 0)
                      , NVL(Para.No_of_decimal, 2)) / NVL(Ias_bill_mst.Bill_rate, 1) > 0;

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.DOC_TYP IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.DOC_SRL IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.DOC_DATE IS '1137 -  «—ÌŒ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.CUR_CODE IS '8 - «·⁄„·…';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.DOC_JV_TYPE IS '4016 - ‰Ê⁄ «·ÊÀÌﬁ… «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.ARS_V_GLS_INSTL_BILL.AC_CODE IS '129 - —ﬁ„ «·Õ”«»';

