--
-- DTS_CREDIT_CARD_TYPES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_CREDIT_CARD_TYPES
(REP_CODE, CR_CARD_NO, CARD_A_NAME, CARD_E_NAME, CR_CARD_NAME, 
 CR_CARD_E_NAME, BANK_NO, BANK_AC, MACHINE_NO_BANK, CR_CARD_TYPE, 
 DUE_PERIOD, ACODE_REC_LETTER, COMM_CALC_TYPE, COMM_AC, COMM_PER, 
 MAX_COMM_AMT, A_CY_MAX_COMM, VAT_PER)
BEQUEATH DEFINER
AS 
Select Rep_Code,
          Cr_Card_No,
          Card_A_Name,
          Card_E_Name,
          Cr_Card_Name,
          Cr_Card_E_Name,
          Credit_Card_Types.Bank_No,
          Credit_Card_Types.Bank_Ac,
          Credit_Card_Types.Machine_No_Bank,
          Credit_Card_Types.Cr_Card_Type,
          Credit_Card_Types.Due_Period,
          Credit_Card_Types.Acode_Rec_Letter,
          Credit_Card_Types.Comm_Calc_Type,
          Credit_Card_Types.Comm_Ac,
          Credit_Card_Types.Comm_Per,
          Credit_Card_Types.Max_Comm_Amt,
          Credit_Card_Types.A_Cy_Max_Comm,
          Ias_Cr_Card_Types.Vat_Per
     From Credit_Card_Types,
          Ias_Cr_Card_Types,
          Ias_Machines,
          Dts_V_Sman_Info
    Where Credit_Card_Types.Cr_Card_Type = Ias_Cr_Card_Types.Cr_Card_Type
          And nvl(Dts_V_Sman_Info.W_Code,Dts_V_Sman_Info.SO_W_CODE) = Nvl (Credit_Card_Types.W_Code, Dts_V_Sman_Info.W_Code)
          And Credit_Card_Types.Machine_No_Bank = Ias_Machines.Machine_No_Bank
          And Nvl (Ias_Machines.Inactive, 0) <> 1;


--
-- DTS_RT_BILL_DTL_RQ  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_RT_BILL_DTL_RQ
(REP_CODE, RT_BILL_SER, DOC_SEQUENCE, BARCODE, I_CODE, 
 ITM_UNT, P_QTY, P_SIZE, I_QTY, FREE_QTY, 
 I_PRICE, I_PRICE_VAT, DIS_AMT, DIS_AMT_DTL, DIS_PER, 
 OTHR_AMT, VAT_AMT, VAT_PER, EXPIRE_DATE, BATCH_NO, 
 RCRD_NO, SERVICE_ITEM, USE_SERIALNO)
BEQUEATH DEFINER
AS 
SELECT  M.REP_CODE, D.RT_BILL_SER, D.DOC_SEQUENCE,  
												    D.BARCODE,I_CODE,ITM_UNT,P_QTY,P_SIZE, I_QTY, FREE_QTY, 
												    I_PRICE, I_PRICE_VAT,D.DIS_AMT, D.DIS_AMT_DTL, D.DIS_PER,
												    D.OTHR_AMT, D.VAT_AMT, D.VAT_PER,
												    EXPIRE_DATE, BATCH_NO, 
												   RCRD_NO, SERVICE_ITEM,USE_SERIALNO
												FROM IAS_RT_BILL_DTL_RQ  D,IAS_RT_BILL_MST_RQ M
												WHERE D.RT_BILL_SER=M.RT_BILL_SER
												  AND  NVL(M.PROCESSED,0)<>1
												  AND NVL(M.STAND_BY,0)<>1
												  AND NVL(M.APPROVED,0)=1;


--
-- DTS_V_ACCOUNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ACCOUNT
(REP_CODE, A_CODE, A_NAME, E_NAME, A_CY, 
 AC_DTL_TYP, AC_CODE_DTL)
BEQUEATH DEFINER
AS 
SELECT sm.rep_code, ac.a_code, ac.a_name, ac.a_name_eng e_name, acy.a_cy,
          ac_dtl_typ, '0' ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 0
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   UNION ALL
   SELECT sm.rep_code, ac.a_code, cst.c_a_name a_name, cst.c_e_name e_name,
          acy.a_cy, ac_dtl_typ, cst.c_code ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm,
          customer cst
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 3
   AND    cst.c_a_code = ac.a_code
   AND    NVL (cst.inactive, 0) = 0
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   AND    1 =
             (CASE
                 WHEN ys_gen_pkg.get_fld_value ('IAS_PARA_AR',
                                                'AR_AC_LINK_TYPE'
                                               ) = 1
                    THEN (SELECT 1
                          FROM   ias_priv_customer
                          WHERE  u_id = sm.u_id
                          AND    c_code = cst.c_code
                          AND    a_cy = acy.a_cy
                          AND    add_flag = 1
                          AND    ROWNUM <= 1)
                 ELSE (SELECT 1
                       FROM   customer_curr a,
                              ias_priv_customer b
                       WHERE  a.c_code = b.c_code
                       AND    a.a_cy = b.a_cy
                       AND    b.u_id = sm.u_id
                       AND    a.c_code = cst.c_code
                       AND    a.a_cy = acy.a_cy
                       AND    b.add_flag = 1
                       AND    ROWNUM <= 1)
              END
             )
   UNION ALL
   SELECT sm.rep_code, ac.a_code, vnd.v_a_name a_name, vnd.v_e_name e_name,
          acy.a_cy, ac_dtl_typ, vnd.v_code ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm,
          v_details vnd
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 4
   AND    vnd.v_a_code = ac.a_code
   AND    NVL (vnd.inactive, 0) = 0
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   AND    1 =
             (CASE
                 WHEN ys_gen_pkg.get_fld_value ('IAS_PARA_AP',
                                                'AP_AC_LINK_TYPE'
                                               ) = 1
                    THEN (SELECT 1
                          FROM   ias_priv_vendor
                          WHERE  u_id = sm.u_id
                          AND    v_code = vnd.v_code
                          AND    a_cy = acy.a_cy
                          AND    add_flag = 1
                          AND    ROWNUM <= 1)
                 ELSE (SELECT 1
                       FROM   vendor_curr a,
                              ias_priv_vendor b
                       WHERE  a.v_code = b.v_code
                       AND    a.a_cy = b.a_cy
                       AND    b.u_id = sm.u_id
                       AND    a.v_code = vnd.v_code
                       AND    a.a_cy = acy.a_cy
                       AND    b.add_flag = 1
                       AND    ROWNUM <= 1)
              END
             )
   UNION ALL
   SELECT sm.rep_code, ac.a_code, csh.cash_name a_name,
          csh.cash_e_name e_name, acy.a_cy, ac_dtl_typ,
          TO_CHAR (csh.cash_no) ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm,
          cash_in_hand csh,
          ias_cash_in_hand_dtl cshacy
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 1
   AND    csh.a_code = ac.a_code
   AND    csh.cash_no = cshacy.cash_no
   AND    acy.a_cy = cshacy.a_cy
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_cash
             WHERE  u_id = sm.u_id
             AND    cash_no = csh.cash_no
             AND    a_cy = cshacy.a_cy
             AND    cash_type = 1
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   UNION ALL
   SELECT sm.rep_code, ac.a_code, bnk.bank_name a_name,
          bnk.bank_e_name e_name, acy.a_cy, ac_dtl_typ,
          TO_CHAR (bnk.bank_no) ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm,
          cash_at_bank bnk,
          ias_cash_at_bank_dtl bnkacy
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 2
   AND    bnk.a_code = ac.a_code
   AND    bnk.bank_no = bnkacy.bank_no
   AND    acy.a_cy = bnkacy.a_cy
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_cash
             WHERE  u_id = sm.u_id
             AND    cash_no = bnk.bank_no
             AND    a_cy = bnkacy.a_cy
             AND    cash_type = 2
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   UNION ALL
   SELECT sm.rep_code, ac.a_code, s.emp_l_nm a_name, s.emp_f_nm e_name,
          acy.a_cy, ac_dtl_typ, TO_CHAR (s.emp_no) ac_code_dtl
   FROM   ACCOUNT ac,
          account_curr acy,
          dts_v_sman_info sm,
          s_emp s
   WHERE  ac.a_code = acy.a_code
   AND    acy.inactive = 0
   AND    ac.ac_close = 0
   AND    NVL (ac.ac_dtl_typ, 0) = 7
   AND    a_s_m IN (SELECT account_type
                    FROM   account_types
                    WHERE  affected_by_trans = 1)
   AND    EXISTS (
             SELECT 1
             FROM   priv_acc
             WHERE  u_id = sm.u_id
             AND    a_code = ac.a_code
             AND    a_cy = acy.a_cy
             AND    add_flag = 1)
   AND    EXISTS (
             SELECT 1
             FROM   s_brn_usr_priv
             WHERE  u_id = sm.u_id
             AND    brn_no = s.brn_no
             AND    add_flag = 1
             AND    ROWNUM <= 1)
   AND    1 =
             (CASE
                 WHEN ys_gen_pkg.get_fld_value ('IAS_PARA_GEN', 'EMP_PRV_TYP') =
                                                                             0
                    THEN 1
                 ELSE (SELECT 1
                       FROM   s_emp_prv
                       WHERE  u_id = sm.u_id
                       AND    empno_hrchyno =
                                 DECODE (emp_prv_typ,
                                         1, s.emp_no,
                                         2, s.hrchy_no
                                        )
                       AND    add_flag = 1
                       AND    ROWNUM <= 1)
              END
             );


--
-- DTS_V_ACTVTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ACTVTY
(REP_CODE, ACTV_NO, ACTV_A_NAME, ACTV_E_NAME)
BEQUEATH DEFINER
AS 
Select S.Rep_Code
                                 ,C.ACTV_NO
                                 ,C.ACTV_A_NAME
                                 ,C.ACTV_E_NAME
                             From IAS_ACTVTY C, Dts_V_Sman_Info S, IAS_PRIV_ACTVTY Prv
                            Where C.ACTV_NO = Prv.ACTV_NO 
                            And C.ACTV_SUB = 1
                            and  nvl(c.INACTIVE,0)=0                            
                            And Prv.U_Id = S.U_Id 
                            And Nvl (Prv.Add_Flag, 0) = 1;


--
-- DTS_V_ALL_CSTMR_BALNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ALL_CSTMR_BALNC
(C_CODE, AC_CODE_DTL, AC_DTL_TYP, A_CODE, REP_CODE, 
 DOC_DATE, DOC_TYPE, JV_TYPE, DOC_NO, DOC_SER, 
 REF_NO, DOC_DESC, A_CY, DR_AMT, DR_AMT_F, 
 AMT_F, AMT, CR_AMT, CR_AMT_F, DOC_POST, 
 BRN_NO, CC_CODE, PJ_NO, ACTV_NO)
BEQUEATH DEFINER
AS 
Select C_Code ,
                       Ac_Code_Dtl,
                       ac_dtl_typ,
                       a_code,
                       Rep_Code,
                       Doc_Date,
                       Doc_Type,
                       Jv_Type,
                       Doc_No,
                       Doc_ser,
                       Ref_No,
                       Doc_Desc,
                       A_Cy,
                       Dr_Amt,
                       Dr_Amt_f,
                       Amt_f,
                       Amt,              
                       Cr_Amt,
                       Cr_Amt_f,
                       Doc_Post,
                       brn_no,
                       CC_CODE,
                       PJ_NO,
                       ACTV_NO
                  From IAS_POST_DTL  
                  where ac_dtl_typ=3                   
                  union all                    
                Select C_Code ,
                       C_Code Ac_Code_Dtl,
                       3 ac_dtl_typ,
                       a_code,
                       Rep_Code,
                       Bill_Date Doc_Date,
                       4 Doc_Type,
                       Bill_Doc_Type Jv_Type,
                       Bill_No Doc_No,
                       Bill_ser Doc_ser,
                       Ref_No,
                       A_Desc Doc_Desc,
                       Bill_Currency A_Cy,
                       (Nvl((Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0))), 0))* Nvl(Bill_Rate, 1) Dr_Amt,
                       Decode(Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur,0, (Nvl(Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)), 0) )) Dr_Amt_f,
                       Decode(Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur,0, (Nvl(Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)), 0) )) Amt_f,
                       (Nvl((Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0))), 0))* Nvl(Bill_Rate, 1) Amt,              
                       0 Cr_Amt,
                       0 Cr_Amt_f,
                       3 Doc_Post,
                       brn_no,
                       M.CC_CODE,
                       M.PJ_NO,
                       M.ACTV_NO
                  From Ias_Bill_Mst_Br M
                 Where Nvl(External_Post, 0) = 70
                       And Nvl(Cncl_Flg, 0) = 0
                       And Bill_Doc_Type = 4
                       And Nvl(Bill_Post, 0) = 0
                       And  Not exists (Select 1
                                             From Ias_Bill_Mst I
                                            Where Nvl(External_Post, 0) = 70
                                            and Bill_Ser=m.Bill_Ser
                                            and rownum<=1 )
                Union All
                Select C_Code ,
                       C_Code Ac_Code_Dtl,
                       3 ac_dtl_typ,
                       a_code,
                       Rep_Code,
                       Rt_Bill_Date Doc_Date,
                       5 Doc_Type,
                       rt_Bill_Doc_Type Jv_Type,
                       Rt_Bill_No Doc_No,
                       rt_Bill_ser Doc_ser,
                       Ref_No,
                       A_Desc Doc_Desc,
                       Rt_Bill_Currency A_Cy,
                       0 Dr_Amt,
                       0 Dr_Amt_f,
                      Decode(rt_Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur,0, (Nvl(Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)), 0) ))*-1 Amt_f,
                       (Nvl((Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0))), 0))* Nvl(rt_Bill_Rate, 1)*-1 Amt,
                       (Nvl((Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0))), 0))* Nvl(rt_Bill_Rate, 1) cr_Amt,
                       Decode(rt_Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur,0, (Nvl(Nvl(Bill_Amt, 0) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)), 0) )) cr_Amt_f,               
                       3 Doc_Post,
                       brn_no,
                       M.CC_CODE,
                       M.PJ_NO,
                       M.ACTV_NO
                  From Ias_Rt_Bill_Mst_Br M
                 Where Nvl(External_Post, 0) = 70
                       And Nvl(Cncl_Flg, 0) = 0
                       And Rt_Bill_Doc_Type = 4
                       And Nvl(Rt_Bill_Post, 0) = 0
                       And  Not exists (Select 1
                                             From Ias_Rt_Bill_Mst I
                                            Where Nvl(External_Post, 0) = 70
                                            and Rt_Bill_Ser=m.Rt_Bill_Ser
                                            and rownum<=1 );


--
-- DTS_V_CASH_CUSTMR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_CASH_CUSTMR
(CUST_CODE, CUST_L_NM, CUST_F_NM, REP_CODE, MOBILE_NO, 
 TEL_NO, E_MAIL, R_CODE, CITY_NO, ADDRESS, 
 C_TAX_CODE)
BEQUEATH DEFINER
AS 
Select C.Cust_Code
      ,C.Cust_L_Nm
      ,C.Cust_F_Nm
      ,C.Rep_Code
      ,C.Mobile_No
      ,C.Tel_No
      ,C.E_Mail
      ,C.R_Code
      ,C.City_No      
      ,C.Address
      ,C.C_Tax_Code
  From Ias_Cash_Custmr C, Dts_V_Sman_Info S
 Where C.Rep_Code = S.Rep_Code And Nvl (C.Inactive, 0) = 0;

COMMENT ON COLUMN IAS20261.DTS_V_CASH_CUSTMR.MOBILE_NO IS '770 - —ﬁ„ «·ÃÊ«·';

COMMENT ON COLUMN IAS20261.DTS_V_CASH_CUSTMR.E_MAIL IS '520 - «·»—Ìœ «·«·ﬂ —Ê‰Ì';



--
-- DTS_V_CLC_TAX_TYPE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_CLC_TAX_TYPE
(REP_CODE, CLC_TYP_NO_TAX, CLC_TYP_L_NM, CLC_TYP_F_NM, GRP_CODE, 
 DFLT_FLG, CLC_TAX_TYP)
BEQUEATH DEFINER
AS 
Select Distinct sm.rep_code,m.Clc_Typ_No CLC_TYP_NO_TAX ,Clc_Typ_L_Nm,Clc_Typ_F_Nm ,sm.Grp_Code, decode(nvl(sm.CLC_TYP_NO_TAX,0),nvl(m.Clc_Typ_No,0),1,0) DFLT_FLG
                            ,M.CLC_TAX_TYP
                            From  Gnr_Tax_Typ_Clc_Mst M,Gnr_Tax_Typ_Clc_Brn DB,Dts_V_Sman_Info sm
                            ,Ias_para_gen  p
                           Where M.Clc_Typ_No=DB.Clc_Typ_No
                        --   and m.CLC_TAX_TYP<>4
                           and Nvl(sm.SMAN_TYP,0)in(1,3)
                           and nvl(m.INACTIVE,0)=0  
                           and nvl(p.use_vat,0)=1  
                             And DB.brn_no=Decode(Nvl(sm.Brn_No,0),0,DB.brn_no,Nvl(sm.Brn_No,0))        
                             And (M.Clc_Tax_Typ<>0 Or Exists(Select D.Clc_Typ_No
                                                             From Gnr_Tax_Typ_Clc_Dtl D, Gnr_Tax_Typ_Clc_Brn DB , Gnr_Tax_Code_Mst T
                                                            Where D.Tax_No    =T.Tax_No            
                                                              And D.Clc_Typ_No=M.Clc_Typ_No
                                                              And D.Clc_Typ_No=DB.Clc_Typ_No
                                                              And T.Clc_Doc_Typ In (1,3)
                                                              And DB.brn_no=Decode(Nvl(sm.Brn_No,0),0,DB.brn_no,Nvl(sm.Brn_No,0))
                                                              And RowNum<=1))
                                  AND ( nvl(m.Clc_Typ_No,0)=nvl(sm.CLC_TYP_NO_TAX,0)  
                                                       Or Exists (select 1 From GNR_TAX_TYP_CLC_PRV
                                                                      Where U_Id = SM.U_ID                           
                                                                        And GNR_TAX_TYP_CLC_PRV.Clc_Typ_No = M.Clc_Typ_No                                                    
                                                                        And Nvl(Add_Flag,1) = 1 
                                                                        And RowNum <=1 )  )                                                                                               
                                    Order By m.Clc_Typ_No;


--
-- DTS_V_COST_CENTER  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_COST_CENTER
(REP_CODE, CC_CODE, CC_A_NAME, CC_E_NAME)
BEQUEATH DEFINER
AS 
Select S.Rep_Code
                                 ,C.Cc_Code
                                 ,C.Cc_A_Name
                                 ,C.Cc_E_Name
                             From Cost_Centers C,COST_CENTER_TYPES T, Dts_V_Sman_Info S, Privilege_Cc Prv
                            Where C.Cc_Code = Prv.Cc_Code 
                            And C.C_S_M = t.CC_TYPE
                            And nvl(AFFECTED_BY_TRANS,0)=1
                            and  nvl(c.INACTIVE,0)=0                            
                            And Prv.U_Id = S.U_Id 
                            And Nvl (Prv.Add_Flag, 0) = 1;


--
-- DTS_V_CST_UNPSTED_SALES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_CST_UNPSTED_SALES
(C_CODE, REP_CODE, A_CY, BILL_AMT, DISC_AMT, 
 VAT_AMT, OTHR_AMT, NET_AMT, NET_AMTL)
BEQUEATH DEFINER
AS 
Select C_Code,
                                    Rep_Code,
                                    A_Cy,
                                    Sum(Nvl(Bamt, 0)) Bill_Amt,
                                    Sum(Nvl(Disc_Amt, 0)) Disc_Amt,
                                    Sum(Nvl(Vat_Amt, 0)) Vat_Amt,
                                    Sum(Nvl(Othr_Amt, 0)) Othr_Amt,
                                    Sum(Nvl(Net_Amt, 0)) Net_Amt,
                                    Sum(Nvl(Net_Amtl, 0)) Net_Amtl
                               From (  Select C_Code,
                                              Rep_Code,
                                              Bill_Currency A_Cy,
                                              Sum(Nvl(Bill_Amt, 0)) Bamt,
                                              Sum(Nvl(Disc_Amt, 0)) Disc_Amt,
                                              Sum(Nvl(Vat_Amt, 0)) Vat_Amt,
                                              Sum(Nvl(Othr_Amt, 0)) Othr_Amt,
                                              Sum(Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) ) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0))  Net_Amt,
                                              Decode(Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur,
                                                                                         Sum(Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) ) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0))
                                                                                        , Sum(Nvl((Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) ) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0) * Nvl(Bill_Rate, 1)), 0)))  Net_Amtl
                                         From Ias_Bill_Mst_Br M
                                        Where Nvl(External_Post, 0) = 70
                                              And Nvl(Cncl_Flg, 0) = 0
                                              And Bill_Doc_Type = 4
                                              And Nvl(Bill_Post, 0) = 0
                                              And  Not exists (Select 1
                                                                     From Ias_Bill_Mst I
                                                                    Where Nvl(External_Post, 0) = 70
                                                                    and Bill_Ser=m.Bill_Ser
                                                                    and rownum<=1 )
                                     Group By C_Code, Rep_Code, Bill_Currency
                                     Union
                                       Select C_Code,
                                              Rep_Code,
                                              Rt_Bill_Currency A_Cy,
                                              Nvl((Sum(Nvl(Bill_Amt, 0)) * -1), 0) Bamt,
                                              Nvl((Sum(Nvl(Disc_Amt, 0)) * -1), 0) Disc_Amt,
                                              Nvl((Sum(Nvl(Vat_Amt, 0)) * -1), 0) Vat_Amt,
                                              Nvl((Sum(Nvl(Othr_Amt, 0)) * -1), 0) Othr_Amt,
                                              Nvl((Sum(Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) )- Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0)) * -1), 0) Net_Amt,
                                              Nvl((Decode(Rt_Bill_Currency, Ys_Gen_Pkg.Get_Local_Cur, 
                                                                                                 Nvl((Sum(Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) )- Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0)) * -1), 0)
                                                                                               , Sum(Nvl((Nvl(((Nvl(Bill_Amt, 0)-(nvl(CR_CARD_AMT,0)+nvl(CR_CARD_AMT_SCND,0)+nvl(CR_CARD_AMT_THRD,0)) ) - Nvl(Disc_Amt, 0) + Nvl(Vat_Amt, 0) + Nvl(Othr_Amt, 0)), 0) * Nvl(Rt_Bill_Rate, 1)), 0))) * -1), 0) Net_Amtl
                                         From Ias_Rt_Bill_Mst_Br
                                        Where Nvl(External_Post, 0) = 70
                                              And Nvl(Cncl_Flg, 0) = 0
                                              And Rt_Bill_Doc_Type = 4
                                              And Nvl(Rt_Bill_Post, 0) = 0
                                              And  Not exists (Select 1
                                                                     From Ias_Rt_Bill_Mst I
                                                                    Where Nvl(External_Post, 0) = 70
                                                                    and Rt_Bill_Ser=Ias_Rt_Bill_Mst_Br.Rt_Bill_Ser
                                                                    and rownum<=1 ) 
                                     Group By C_Code, Rep_Code, Rt_Bill_Currency)
                           Group By C_Code, Rep_Code, A_Cy;


--
-- DTS_V_CST_UNPSTED_TRANS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_CST_UNPSTED_TRANS
(C_CODE, REP_CODE, A_CY, BAMT, BAMTF, 
 DISC_AMT_CCODE, DISC_AMTF_CCODE, TAX_AMT, TAX_AMTF, OTHRS_AMT, 
 OTHRS_AMTF, CC_CODE, PJ_NO, ACTV_NO)
BEQUEATH DEFINER
AS 
Select C_CODE , REP_CODE, A_CY, Sum(BAMT) BAmt, Sum(BAMTF) BAMTF,Sum(disc_amt_ccode) disc_amt_ccode
                   ,Sum(disc_amtf_ccode) disc_amtf_ccode, Sum(tax_amt) tax_amt, Sum(tax_amtf) tax_amtf, 
                      Sum(othrs_amt) othrs_amt , Sum(othrs_amtf) othrs_amtf,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, cc_code, NULL) cc_code,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, pj_no, NULL) pj_no,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, actv_no, NULL) actv_no
             from ( 
              SELECT   m.C_Code , m.rep_code,m.bill_Currency a_cy,SUM (NVL (i_qty, 0) * NVL (i_price, 0)) bamt,
                DECODE (m.bill_Currency,
                 YS_GEN_PKG.Get_Local_Cur, 0,
                 SUM (NVL (i_qty, 0) * NVL (i_price, 0))
                ) bamtf,
           ROUND (SUM (  (decode(nvl((NVL (i_qty, 0) *  NVL (dis_amt_mst, 0)),0),0,m.disc_amt_mst)
                        + (NVL (i_qty, 0)  * 
                              (NVL (dis_amt_dtl, 0)
                            + NVL (dis_amt_dtl2, 0)
                            + NVL (dis_amt_dtl3, 0)
                           ))
                    )),
                4
               ) disc_amt_ccode,
         ROUND (DECODE (m.bill_Currency,
                        YS_GEN_PKG.Get_Local_Cur, 0,
                        SUM (  (decode(nvl((NVL (i_qty, 0) *  NVL (dis_amt_mst, 0)),0),0,m.disc_amt_mst)
                                        + (NVL (i_qty, 0) *
                                      ( NVL (dis_amt_dtl, 0)
                                        + NVL (dis_amt_dtl2, 0)
                                        + NVL (dis_amt_dtl3, 0)
                                       ))
                                    ))
                       ),
                4
               ) disc_amtf_ccode,
         SUM (NVL (i_qty, 0) * NVL (d.vat_amt, 0)) tax_amt,
         DECODE (m.bill_Currency,
                 YS_GEN_PKG.Get_Local_Cur, 0,
                 SUM (NVL (i_qty, 0) * NVL (d.vat_amt, 0))
                ) tax_amtf,
         SUM (  DECODE (NVL (i_qty, 0), 0, NVL (free_qty, 0), NVL (i_qty, 0))
              * NVL (d.othr_amt, 0)
             ) othrs_amt,
         SUM (DECODE (m.bill_Currency,
                      YS_GEN_PKG.Get_Local_Cur, 0,
                        DECODE (NVL (i_qty, 0),
                                0, NVL (free_qty, 0),
                                NVL (i_qty, 0)
                               )
                      * NVL (d.othr_amt, 0)
                     )
             ) othrs_amtf,       
         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, d.cc_code, NULL) cc_code,
         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, d.pj_no, NULL) pj_no,
         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, d.actv_no, NULL) actv_no
                    FROM ias_bill_dtl_br  d ,ias_bill_mst_br m
                   WHERE m.bill_ser = d.BILL_ser
                      and nvl(m.external_post,0)=70
                     and (nvl(m.bill_post,0)=0 or m.bill_ser not in(select i.bill_ser from ias_bill_mst i where nvl(external_post,0)=70))
           GROUP BY  m.C_Code , m.rep_code,m.bill_Currency ,
                         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, d.cc_code, NULL),
                         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, d.pj_no, NULL),
                         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, d.actv_no, NULL)
                union
                SELECT   m.C_Code , m.rep_code,m.rt_bill_Currency a_cy ,
         nvl((SUM (NVL (i_qty, 0) * NVL (i_price, 0)) * -1),0) bamt,
         nvl((DECODE (m.rt_bill_Currency,
                 YS_GEN_PKG.Get_Local_Cur, 0,
                 SUM (NVL (i_qty, 0) * NVL (i_price, 0))
                ) * -1),0) bamtf,
         (ROUND (SUM (  (decode(nvl((NVL (i_qty, 0) *  NVL (dis_amt_mst, 0)),0),0,m.disc_amt_mst)
                        +
                        (NVL (i_qty, 0)
                      * ( NVL (dis_amt_dtl, 0)
                        + NVL (dis_amt_dtl2, 0)
                        + NVL (dis_amt_dtl3, 0)
                       ))
                    )),
                4
               ) * -1 ) disc_amt_ccode,
         (ROUND (DECODE (m.rt_bill_Currency,
                        YS_GEN_PKG.Get_Local_Cur, 0,
                        SUM (  (decode(nvl((NVL (i_qty, 0) *  NVL (dis_amt_mst, 0)),0),0,m.disc_amt_mst)
                                                +
                                                (NVL (i_qty, 0)
                                              * ( NVL (dis_amt_dtl, 0)
                                                + NVL (dis_amt_dtl2, 0)
                                                + NVL (dis_amt_dtl3, 0)
                                               ))
                                             ))
                       ),
                4
               ) * -1)disc_amtf_ccode,
         (SUM (NVL (i_qty, 0) * NVL (d.vat_amt, 0))* -1 )  tax_amt,
         (DECODE (m.rt_bill_Currency,
                 YS_GEN_PKG.Get_Local_Cur, 0,
                 SUM (NVL (i_qty, 0) * NVL (d.vat_amt, 0))
                ) * -1 )  tax_amtf,
         SUM (  DECODE (NVL (i_qty, 0), 0, NVL (free_qty, 0), NVL (i_qty, 0))
              * NVL (d.othr_amt, 0)
             )  othrs_amt,
         SUM (DECODE (m.rt_bill_Currency,
                      YS_GEN_PKG.Get_Local_Cur, 0,
                        DECODE (NVL (i_qty, 0),
                                0, NVL (free_qty, 0),
                                NVL (i_qty, 0)
                               )
                      * NVL (d.othr_amt, 0)
                     )
             ) othrs_amtf,
             DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, d.cc_code, NULL) cc_code,
         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, d.pj_no, NULL) pj_no,
         DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, d.actv_no, NULL) actv_no
                FROM ias_rt_bill_dtl_br  d ,ias_rt_bill_mst_br m
               WHERE m.rt_bill_ser = d.rt_bill_ser 
                 and nvl(m.external_post,0)=70
                 and (nvl(m.rt_bill_post,0)=0 or m.rt_bill_ser not in(select i.rt_bill_ser from ias_rt_bill_mst i where nvl(external_post,0)=70))
            GROUP BY  C_Code , rep_code,rt_bill_Currency ,
                     DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, d.cc_code, NULL),
                     DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, d.pj_no, NULL),
                     DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, d.actv_no, NULL)) 
          GROUP BY  C_Code , rep_code,A_Cy ,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_CS_TYPE',' 1=1 '), 2, cc_code, NULL) ,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_PJ_TYPE',' 1=1 '), 2, pj_no, NULL) ,
                      DECODE (YS_GEN_PKG .GET_FLD_VALUE ('IAS_PARA_AR' ,'AR_ACTV_TYPE',' 1=1 '), 2, actv_no, NULL);


--
-- DTS_V_GET_ITM_PRICE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_ITM_PRICE
(REP_CODE, LEV_NO, I_CODE, ITM_UNT, P_SIZE, 
 MIN_QTY, MAX_QTY, A_CY, CUR_RATE, BILL_DOC_TYPE, 
 I_PRICE, IS_IT_DEFLT, MIN_PRICE, MAX_PRICE, W_CODE)
BEQUEATH DEFINER
AS 
with SMAN AS( SELECT S.U_ID
                     ,S.REP_CODE
                    ,S.BRN_NO
                    ,S.W_CODE
                    ,S.GRP_CODE
                    ,L.A_CY
                    ,L.LEV_NO
                    ,S.must_not_less_thn_lprice
                    ,S.must_not_highr_thn_hprice 
                    ,nvl(V.price_type,0) price_type 
                    ,L.bill_doc_type
                    ,ias_gen_pkg.get_local_cur local_cur 
                   , Ias_Gen_Pkg.Get_Cur_Rate (P_Acy=> L.A_CY,P_Usr_No   => S.U_Id) cur_rate
                   ,ias_gen_pkg.get_stk_cur stk_cur
                  , ias_gen_pkg.get_cur_rate(p_acy => ias_gen_pkg.get_stk_cur,P_Usr_No    =>s.u_id ) STK_CUR_RATE
                    ,NVL(L.LEV_DEFLT,0) LEV_DEFLT 
                    ,NVL((Select S_fld_dflt_usr.Fld_Val                  
                          From  S_fld_dflt_usr
                         Where  S_fld_dflt_usr.U_Id    = S.U_ID
                            And S_fld_dflt_usr.Fld_NM  = 'DFLT_LVL_PRICE'
                            AND ROWNUM<=1),0) DFLT_LEV_NO                
                 FROM dts_v_sman_info s,
                    Ias_Priv_Price LPriv,
                    Ias_Pricing_Levels L,
                    ias_para_inv V
                WHERE L.LEV_NO=LPriv.LEV_NO  
                and   Nvl (LPriv.Add_Flag, 0) = 1
                and   LPRIV.U_ID=S.U_ID                 
                And   Nvl(S.Sman_Typ,0) In(1,3)   
            )
   SELECT DISTINCT s.rep_code
                  , p.lev_no
                  , p.i_code
                  , p.itm_unt
                  , p.p_size,
                   CASE S.price_type WHEN 3 THEN p.from_qty
                                      WHEN 4 THEN p.from_qty
                                      ELSE 0
                   END AS "MIN_QTY",
                   CASE S.price_type  WHEN 3  THEN p.to_qty
                                       WHEN 4 THEN p.to_qty
                                       ELSE 0
                   END AS "MAX_QTY",
                   S.a_cy, 
                   S.cur_rate,
                    NVL (S.bill_doc_type, 0) bill_doc_type,
                   NVL (p.i_price, 0) i_price,
                   CASE WHEN NVL(S.DFLT_LEV_NO,0)<>0   THEN DECODE(S.DFLT_LEV_NO,p.lev_no,1,0)
                        ELSE S.LEV_DEFLT END "IS_IT_DEFLT",
                   CASE NVL (s.must_not_less_thn_lprice, 0)
                      WHEN 1
                         THEN                             
                            NVL(P.MIN_ITM_PRICE, NVL
                                (ias_gen_pkg.get_low_price
                                    (p_icode           => p.i_code,
                                     p_itm_unt         => p.itm_unt,
                                     p_acy             => S.a_cy,
                                     p_loc_cur         => S.local_cur,
                                     p_stk_cur         => S.stk_cur,
                                     p_ac_rate         => S.cur_rate ,
                                     p_stk_rate        => S.STK_CUR_RATE,
                                     p_price_type      => S.price_type,
                                     p_w_code          => p.w_code,
                                     p_qty             => NULL,
                                     p_brn_no          => s.brn_no,
                                     p_usr_no          => s.u_id
                                    ),
                                 0
                                ))
                      ELSE 0
                   END min_price,
                   CASE NVL (s.must_not_highr_thn_hprice, 0)
                      WHEN 1
                         THEN                         
                             NVL(P.MAX_ITM_PRICE,NVL
                                (ias_gen_pkg.get_high_price
                                    (p_icode           => p.i_code,
                                     p_itm_unt         => p.itm_unt,
                                     p_acy             => S.a_cy,
                                     p_loc_cur         => S.local_cur,
                                     p_stk_cur         => S.stk_cur,
                                     p_ac_rate         => S.cur_rate ,
                                     p_stk_rate        => S.STK_CUR_RATE,
                                     p_price_type      => S.price_type,
                                     p_w_code          => p.w_code,
                                     p_qty             => NULL,
                                     p_brn_no          => s.brn_no,
                                     p_usr_no          => s.u_id
                                    ),
                                 0
                                ))
                      ELSE 0
                   END max_price,
                   CASE   WHEN S.price_type IN(2,4) THEN  p.w_code else null end  w_code
   FROM            ias_item_price p,
                   Dts_Grp_Dtl g,                                      
                   SMAN s                   
   WHERE           g.i_code = p.i_code
   AND             g.itm_unt = p.itm_unt
   AND             G.GRP_CODE=S.GRP_CODE
   AND             S.lev_no = p.lev_no 
   And Nvl (G.Inactive, 0) = 0   
   and            nvl(S.brn_no,0)=case when S.price_type=5 then nvl(p.brn_no,0) else nvl(S.brn_no,0) end 
   and            1=(CASE   WHEN S.price_type IN(2,4) THEN (SELECT 1 FROM   Dts_V_Sman_Wcode
                                                                     where rep_code=s.rep_code
                                                                     and w_code=p.w_code
                                                                     and WCODE_TYPE in(1,2,3)
                                                                     and rownum<=1)
                           Else 1 end );


--
-- DTS_V_GET_PRC_LVLS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_PRC_LVLS
(REP_CODE, U_ID, LEV_NO, LEV_A_NAME, LEV_E_NAME, 
 A_CY, CUR_RATE, MAX_LVL, MIN_LVL, DEFLT_LVL, 
 PRIC_BY_CSTMR, BILL_DOC_TYPE, W_CODE, BRN_NO, PRICE_TYPE, 
 ALLOW_MOD_PRICE, MUST_NOT_HIGHR_THN_HPRICE, MUST_NOT_LESS_THN_LPRICE)
BEQUEATH DEFINER
AS 
SELECT sm.rep_code, sm.u_id, l.lev_no, l.lev_a_name, l.lev_e_name, a_cy,
                                                                                              ex.cur_rate,
                                                                                              DECODE
                                                                                                    (ias_gen_pkg.get_high_lvl_price (p_usr_no => sm.u_id),
                                                                                                     l.lev_no, 1,
                                                                                                     0
                                                                                                    ) max_lvl,                     -- NVL (l.lev_high, 0) max_lvl,
                                                                                              DECODE (ias_gen_pkg.get_low_lvl_price (p_usr_no => sm.u_id),
                                                                                                      l.lev_no, 1,
                                                                                                      0
                                                                                                     ) min_lvl,                      --NVL (l.lev_low, 0) min_lvl,
                                                                                              DECODE
                                                                                                    (ias_gen_pkg.get_lev_dflt_prv (p_userno => sm.u_id),
                                                                                                     l.lev_no, 1,
                                                                                                     0
                                                                                                    ) deflt_lvl,                     --NVL (l.lev_low, 0) min_lvl,
                                                                                              NVL (pr.cust_price_fixed, 0) pric_by_cstmr,
                                                                                              DECODE (NVL (pr.cust_price_fixed, 0),
                                                                                                      1, 0,
                                                                                                      bill_doc_type
                                                                                                     ) bill_doc_type,
                                                                                              sm.w_code, sm.brn_no, NVL (pv.price_type, 0) price_type,
                                                                                              sm.allow_mod_price, sm.must_not_highr_thn_hprice,
                                                                                              sm.must_not_less_thn_lprice
                                                                                       FROM   ias_pricing_levels l,
                                                                                              dts_v_sman_info sm,
                                                                                              ias_priv_price pl,
                                                                                              ex_rate ex,
                                                                                              ias_para_inv pv,
                                                                                              ias_para_ar pr
                                                                                       WHERE  NVL (pl.add_flag, 0) = 1
                                                                                       AND    pl.lev_no = l.lev_no
                                                                                       AND    l.a_cy = ex.cur_code
                                                                                       AND    pl.u_id = sm.u_id;


--
-- DTS_V_GET_REP_PSTD_NET_SLS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_PSTD_NET_SLS
(DOC_DATE, C_CODE, REP_CODE, A_CY, B_AMT, 
 B_DISC_AMT, B_VAT_AMT, B_OTHR_AMT, B_TOT_AMT, B_TOT_AMT_L, 
 RT_AMT, RT_DISC_AMT, RT_VAT_AMT, RT_OTHR_AMT, RT_TOT_AMT, 
 RT_TOT_AMT_L, NET_AMT, NET_AMT_L)
BEQUEATH DEFINER
AS 
SELECT   doc_date, c_code, rep_code, a_cy, NVL (SUM (b_amt), 0) b_amt,
                                NVL (SUM (b_disc_amt), 0) b_disc_amt,
                                NVL (SUM (b_vat_amt), 0) b_vat_amt,
                                NVL (SUM (b_othr_amt), 0) b_othr_amt,
                                NVL (SUM (b_tot_amt), 0) b_tot_amt,
                                NVL (SUM (b_tot_amt_l), 0) b_tot_amt_l,
                                NVL (SUM (rt_amt), 0) rt_amt,
                                NVL (SUM (rt_disc_amt), 0) rt_disc_amt,
                                NVL (SUM (rt_vat_amt), 0) rt_vat_amt,
                                NVL (SUM (rt_othr_amt), 0) rt_othr_amt,
                                NVL (SUM (rt_tot_amt), 0) rt_tot_amt,
                                NVL (SUM (rt_tot_amt_l), 0) rt_tot_amt_l,
                                NVL ((NVL(SUM (b_tot_amt), 0) - NVL (SUM (rt_tot_amt), 0)),
                                     0
                                    ) net_amt,
                                NVL ((NVL (SUM (b_tot_amt_l), 0) - NVL (SUM (rt_tot_amt_l), 0)),
                                     0
                                    ) net_amt_l
                           FROM ( 
                              SELECT   TO_CHAR (m.bill_date, 'DD/MM/RRRR') doc_date, c_code,
                                          rep_code, bill_currency a_cy,
                                          SUM (NVL (bill_amt, 0)) b_amt,
                                          SUM (NVL (disc_amt, 0)) b_disc_amt,
                                          SUM (NVL (vat_amt, 0)) b_vat_amt,
                                          SUM (NVL (othr_amt, 0)) b_othr_amt,
                                          SUM (NVL ((  NVL (bill_amt, 0)
                                                     - NVL (disc_amt, 0)
                                                     + NVL (vat_amt, 0)
                                                     + NVL (othr_amt, 0)
                                                    ),
                                                    0
                                                   )
                                              ) b_tot_amt,
                                          DECODE (bill_currency,
                                                  ys_gen_pkg.get_local_cur,
                                                   SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                                     - NVL (disc_amt, 0)
                                                                     + NVL (vat_amt, 0)
                                                                     + NVL (othr_amt, 0)
                                                                    ),
                                                                    0
                                                                   )                                                             
                                                            ),
                                                            0
                                                           )
                                                      ),
                                                  SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                                     - NVL (disc_amt, 0)
                                                                     + NVL (vat_amt, 0)
                                                                     + NVL (othr_amt, 0)
                                                                    ),
                                                                    0
                                                                   )
                                                             * NVL (bill_rate, 1)
                                                            ),
                                                            0
                                                           )
                                                      )
                                                 ) b_tot_amt_l,
                                          0 rt_amt, 0 rt_disc_amt, 0 rt_vat_amt, 0 rt_othr_amt,
                                          0 rt_tot_amt, 0 rt_tot_amt_l
                                     FROM ias_bill_mst m
                                    WHERE  nvl(m.Stand_by,0)=0
                                 GROUP BY TO_CHAR (m.bill_date, 'DD/MM/RRRR'),
                                          c_code,
                                          rep_code,
                                          bill_currency
                                UNION ALL
                                 SELECT   TO_CHAR (rt_bill_date, 'DD/MM/RRRR') doc_date, c_code,
                                          rep_code, rt_bill_currency a_cy, 0 b_amt, 0 b_disc_amt,
                                          0 b_vat_amt, 0 b_othr_amt, 0 b_tot_amt, 0 b_tot_amt_l,
                                          NVL ((SUM (NVL (bill_amt, 0))), 0) rt_amt,
                                          SUM (NVL (disc_amt, 0)) rt_disc_amt,
                                          SUM (NVL (vat_amt, 0)) rt_vat_amt,
                                          SUM (NVL (othr_amt, 0)) rt_othr_amt,
                                          SUM (NVL ((  NVL (bill_amt, 0)
                                                     - NVL (disc_amt, 0)
                                                     + NVL (vat_amt, 0)
                                                     + NVL (othr_amt, 0)
                                                    ),
                                                    0
                                                   )
                                              ) rt_tot_amt,
                                          DECODE
                                                (rt_bill_currency,
                                                 ys_gen_pkg.get_local_cur,
                                                  SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                                    - NVL (disc_amt, 0)
                                                                    + NVL (vat_amt, 0)
                                                                    + NVL (othr_amt, 0)
                                                                   ),
                                                                   0
                                                                  )                                                            
                                                           ),
                                                           0
                                                          )
                                                     ),
                                                 SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                                    - NVL (disc_amt, 0)
                                                                    + NVL (vat_amt, 0)
                                                                    + NVL (othr_amt, 0)
                                                                   ),
                                                                   0
                                                                  )
                                                            * NVL (rt_bill_rate, 1)
                                                           ),
                                                           0
                                                          )
                                                     )
                                                ) rt_tot_amt_l
                                     FROM ias_rt_bill_mst m
                                    WHERE  nvl(m.Stand_by,0)=0
                                GROUP BY TO_CHAR (rt_bill_date, 'DD/MM/RRRR'),
                                          c_code,
                                          rep_code,
                                          rt_bill_currency
                            )
                       GROUP BY doc_date,c_code, rep_code, a_cy;


--
-- DTS_V_GET_REP_UNPSTD_NET_SLS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_UNPSTD_NET_SLS
(DOC_DATE, C_CODE, REP_CODE, A_CY, B_AMT, 
 B_DISC_AMT, B_VAT_AMT, B_OTHR_AMT, B_TOT_AMT, B_TOT_AMT_L, 
 RT_AMT, RT_DISC_AMT, RT_VAT_AMT, RT_OTHR_AMT, RT_TOT_AMT, 
 RT_TOT_AMT_L, NET_AMT, NET_AMT_L)
BEQUEATH DEFINER
AS 
SELECT  doc_date , c_code, rep_code, a_cy,
                     NVL (SUM (b_amt), 0) b_amt, NVL (SUM (b_disc_amt), 0) b_disc_amt,
                     NVL (SUM (b_vat_amt), 0) b_vat_amt,
                     NVL (SUM (b_othr_amt), 0) b_othr_amt,
                     NVL (SUM (b_tot_amt), 0) b_tot_amt,
                     NVL (SUM (b_tot_amt_l), 0) b_tot_amt_l, NVL (SUM (rt_amt), 0) rt_amt,
                     NVL (SUM (rt_disc_amt), 0) rt_disc_amt,
                     NVL (SUM (rt_vat_amt), 0) rt_vat_amt,
                     NVL (SUM (rt_othr_amt), 0) rt_othr_amt,
                     NVL (SUM (rt_tot_amt), 0) rt_tot_amt,
                     NVL (SUM (rt_tot_amt_l), 0) rt_tot_amt_l,
                     NVL ((NVL (SUM (b_tot_amt), 0) - NVL (SUM (rt_tot_amt), 0)),0) net_amt,
                      NVL ((NVL (SUM (b_tot_amt_l), 0) - NVL (SUM (rt_tot_amt_l), 0)),0) net_amt_l
                FROM (
                 SELECT   TO_CHAR (m.bill_date, 'DD/MM/RRRR') doc_date, c_code,
                               rep_code, bill_currency a_cy, SUM (NVL (bill_amt, 0)) b_amt,
                               SUM (NVL (disc_amt, 0)) b_disc_amt,
                               SUM (NVL (vat_amt, 0)) b_vat_amt,
                               SUM (NVL (othr_amt, 0)) b_othr_amt,
                               SUM (NVL ((  NVL (bill_amt, 0)
                                          - NVL (disc_amt, 0)
                                          + NVL (vat_amt, 0)
                                          + NVL (othr_amt, 0)
                                         ),
                                         0
                                        )
                                   ) b_tot_amt,
                               DECODE (bill_currency,
                                       ys_gen_pkg.get_local_cur, 
                                       SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                          - NVL (disc_amt, 0)
                                                          + NVL (vat_amt, 0)
                                                          + NVL (othr_amt, 0)
                                                         ),
                                                         0
                                                        )                                                  
                                                 ),
                                                 0
                                                )
                                           ),
                                       SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                          - NVL (disc_amt, 0)
                                                          + NVL (vat_amt, 0)
                                                          + NVL (othr_amt, 0)
                                                         ),
                                                         0
                                                        )
                                                  * NVL (bill_rate, 1)
                                                 ),
                                                 0
                                                )
                                           )
                                      ) b_tot_amt_l,
                               0 rt_amt, 0 rt_disc_amt, 0 rt_vat_amt, 0 rt_othr_amt,
                               0 rt_tot_amt, 0 rt_tot_amt_l
                          FROM ias_bill_mst_br m
                         WHERE  nvl(m.Stand_by,0)=0
                           And  NVL (external_post, 0) = 70
                           AND (   NVL (bill_post, 0) = 0
                                OR bill_ser NOT IN (SELECT i.bill_ser
                                                      FROM ias_bill_mst i
                                                     WHERE NVL (external_post, 0) = 70)
                               )
                      GROUP BY TO_CHAR (m.bill_date, 'DD/MM/RRRR'),
                               c_code,
                               rep_code,
                               bill_currency
                    UNION all
                   SELECT   TO_CHAR (rt_bill_date, 'DD/MM/RRRR') doc_date, c_code,
                               rep_code, rt_bill_currency a_cy, 0 b_amt, 0 b_disc_amt,
                               0 b_vat_amt, 0 b_othr_amt, 0 b_tot_amt, 0 b_tot_amt_l,
                               NVL ((SUM (NVL (bill_amt, 0))), 0) rt_amt,
                               SUM (NVL (disc_amt, 0)) rt_disc_amt,
                               SUM (NVL (vat_amt, 0)) rt_vat_amt,
                               SUM (NVL (othr_amt, 0)) rt_othr_amt,
                               SUM (NVL ((  NVL (bill_amt, 0)
                                          - NVL (disc_amt, 0)
                                          + NVL (vat_amt, 0)
                                          + NVL (othr_amt, 0)
                                         ),
                                         0
                                        )
                                   ) rt_tot_amt,
                               DECODE (rt_bill_currency,
                                       ys_gen_pkg.get_local_cur, 
                                        SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                          - NVL (disc_amt, 0)
                                                          + NVL (vat_amt, 0)
                                                          + NVL (othr_amt, 0)
                                                         ),
                                                         0
                                                        )                                                  
                                                 ),
                                                 0
                                                )
                                           ),
                                       SUM (NVL ((  NVL ((  NVL (bill_amt, 0)
                                                          - NVL (disc_amt, 0)
                                                          + NVL (vat_amt, 0)
                                                          + NVL (othr_amt, 0)
                                                         ),
                                                         0
                                                        )
                                                  * NVL (rt_bill_rate, 1)
                                                 ),
                                                 0
                                                )
                                           )
                                      ) rt_tot_amt_l
                          FROM ias_rt_bill_mst_br
                         WHERE  nvl(Stand_by,0)=0
                           And  NVL (external_post, 0) = 70
                           AND (   NVL (rt_bill_post, 0) = 0
                                OR rt_bill_ser NOT IN (SELECT i.rt_bill_ser
                                                         FROM ias_rt_bill_mst i
                                                        WHERE NVL (external_post, 0) = 70)
                               )
                      GROUP BY TO_CHAR (rt_bill_date, 'DD/MM/RRRR'),
                               c_code,
                               rep_code,
                               rt_bill_currency
                                             )
            GROUP BY  doc_date, c_code, rep_code, a_cy;


--
-- DTS_V_GET_VSTS_INFO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_VSTS_INFO
(REP_CODE, C_CODE, CST_TYP, PRM_CODE, PLN_DATE, 
 SUCSES_VSTS, FAILED_VSTS, VCHRS, QUOTS, CTS_ORDERS, 
 BILLS, RT_BILLS, CST_INVS, GOODS_RQST, WHTRNS_RCV, 
 SHW_ITM, QSTNR_ITM, FREE_SMPL, MARKT_VST)
BEQUEATH DEFINER
AS 
Select   
                               Rep_Code
                              ,C_Code
                              ,m.CST_TYP
                              ,m.prm_code
                              ,To_Date (Arivl_Tm, 'DD/MM/RRRR') Pln_Date
                              ,nvl(Count (distinct case when nvl(Vst_Sts,0)=1 then m.Vst_Srl else null end ) ,0) Sucses_Vsts
                              ,nvl(Count (distinct case when nvl(Vst_Sts,0)=0 then m.Vst_Srl else null end ) ,0) Failed_Vsts
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=2 then 1 else null end ) ,0)  Vchrs
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=52 then 1 else null end ) ,0) Quots
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=53 then 1 else null end ) ,0) Cts_Orders
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=4 then 1 else null end ) ,0) Bills
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=5 then 1 else null end ) ,0) Rt_Bills
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=1410 then 1 else null end ) ,0) Cst_Invs
                              ,0 Goods_Rqst
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=31 then 1 else null end ) ,0) Whtrns_Rcv
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=1406 then 1 else null end ) ,0) SHW_ITM
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=1407 then 1 else null end ) ,0) QSTNR_ITM
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=1412 then 1 else null end ) ,0) FREE_SMPL
                              ,nvl(sum ( case when nvl(Doc_Type_Ref,0)=1413 then 1 else null end ) ,0) MARKT_VST
                          From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D
                         Where M.Vst_Srl = D.Vst_Srl(+)
                         group by 
                         To_Date (Arivl_Tm, 'DD/MM/RRRR'), M.Rep_Code, M.C_Code,m.CST_TYP,m.prm_code;


--
-- DTS_V_GNR_TAX_ITEM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GNR_TAX_ITEM
(REP_CODE, I_CODE, TAX_NO, CLC_TYP_NO, AGNCY_NO, 
 TAX_CLC_ORDR, TAX_PRCNT)
BEQUEATH DEFINER
AS 
select Rep_Code,
                                   I_Code,
                                   Tax_No,
                                   Clc_Typ_No,
                                   Agncy_No,                                   
                                   TAX_CLC_ORDR,
                                   case when nvl(Max_tax_clc_ordr,0)>1 then
                                         NVL(Tax_Prcnt, 0) * ((((SUM(NVL(Tax_Prcnt, 0)) OVER (PARTITION BY Rep_Code,I_Code,Clc_Typ_No ORDER BY NVL(TAX_CLC_ORDR, 1)) - SUM(NVL(Tax_Prcnt, 0)) OVER ( PARTITION BY Rep_Code,I_Code,Clc_Typ_No,NVL(TAX_CLC_ORDR, 1)))) / 100) + 1) 
                                         Else Tax_Prcnt end Tax_Prcnt
                                   from (
                               SELECT DISTINCT m.rep_code rep_code, 
                                               d.i_code i_code, 
                                               ti.tax_no tax_no,
                                               tc.clc_typ_no clc_typ_no
                                               ,ti.agncy_no agncy_no,
                                               ti.tax_prcnt tax_prcnt,
                                                nvl(Tc.TAX_CLC_ORDR,1) TAX_CLC_ORDR,
                                                   max(nvl(Tc.TAX_CLC_ORDR,0)) over(partition by M.Rep_Code,D.I_Code,Tc.Clc_Typ_No) Max_TAX_CLC_ORDR
                               FROM            DTS_V_SMAN_INFO m,
                                               dts_grp_dtl d,
                                               gnr_tax_itm ti,
                                               gnr_tax_code_mst tm,
                                               gnr_tax_code_dtl td,
                                               gnr_tax_typ_clc_dtl tc,
                                               Ias_para_gen  p
                               WHERE           m.grp_code = d.grp_code
                               AND             d.i_code = ti.i_code
                               AND             ti.tax_no = tm.tax_no
                               AND             ti.tax_no = td.tax_no
                               AND             ti.agncy_no = td.agncy_no
                               AND             ti.tax_no = tc.tax_no
                               AND             tm.tax_no = td.tax_no
                               AND             tm.tax_no = tc.tax_no
                               AND             td.tax_no = tc.tax_no
                               AND             NVL (tm.inactive, 0) = 0
                               and             nvl(p.use_vat,0)=1  
                               AND             tc.clc_typ_no = m.clc_typ_no_tax
                                ) m
                            order by Rep_Code,I_Code,Clc_Typ_No,TAX_CLC_ORDR;


--
-- DTS_V_PROJECTS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_PROJECTS
(REP_CODE, PJ_NO, PJ_A_NAME, PJ_E_NAME)
BEQUEATH DEFINER
AS 
Select S.Rep_Code
                                 ,C.PJ_NO
                                 ,C.PJ_A_NAME
                                 ,C.PJ_E_NAME
                             From IAS_PROJECTS C, Dts_V_Sman_Info S, IAS_PRIV_PROJECTS Prv
                            Where C.PJ_NO = Prv.PJ_NO 
                            And C.PJ_SUB = 1
                            and  nvl(c.INACTIVE,0)=0                            
                            And Prv.U_Id = S.U_Id 
                            And Nvl (Prv.Add_Flag, 0) = 1;


--
-- DTS_V_REP_CST_VSTS_INFO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_REP_CST_VSTS_INFO
(REP_CODE, C_CODE, SUCSES_VSTS, FAILED_VSTS, VCHRS, 
 QUOTS, CTS_ORDERS, BILLS, RT_BILLS, CST_INVS, 
 GOODS_RQSTS, WHTRNS_RECIEVES)
BEQUEATH DEFINER
AS 
SELECT   rep_code, c_code, NVL (SUM (sucses_vst), 0) sucses_vsts,
					                        NVL (SUM (failed_vst), 0) failed_vsts,
					                        NVL (SUM (vchrs_cnt), 0) vchrs, NVL (SUM (quots_cnt), 0) quots,
					                        NVL (SUM (sal_ordrs_cnt), 0) cts_orders,
					                        NVL (SUM (bills_cnt), 0) bills,
					                        NVL (SUM (rt_bills_cnt), 0) rt_bills,
					                        NVL (SUM (cst_invs_cnt), 0) cst_invs,
					                        NVL (SUM (goods_rqst_cnt), 0) goods_rqsts,
					                        NVL (SUM (whtrns_rcv_cnt), 0) whtrns_recieves
					           FROM (SELECT   rep_code, c_code, COUNT (vst_sts) sucses_vst,
					                      0 failed_vst, 0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt,
					                      0 bills_cnt, 0 rt_bills_cnt, 0 cst_invs_cnt,
					                      0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                   FROM dts_cst_vst_mst m
					                WHERE vst_sts = 1
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst,
					                      COUNT (vst_sts) failed_vst, 0 vchrs_cnt, 0 quots_cnt,
					                      0 sal_ordrs_cnt, 0 bills_cnt, 0 rt_bills_cnt,
					                      0 cst_invs_cnt, 0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m
					                WHERE vst_sts = 0
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      COUNT (doc_no_ref) vchrs_cnt, 0 quots_cnt,
					                      0 sal_ordrs_cnt, 0 bills_cnt, 0 rt_bills_cnt,
					                      0 cst_invs_cnt, 0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 0
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, COUNT (doc_no_ref) quots_cnt,
					                      0 sal_ordrs_cnt, 0 bills_cnt, 0 rt_bills_cnt,
					                      0 cst_invs_cnt, 0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 1
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt,
					                      COUNT (doc_no_ref) sal_ordrs_cnt, 0 bills_cnt,
					                      0 rt_bills_cnt, 0 cst_invs_cnt, 0 goods_rqst_cnt,
					                      0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 2
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt,
					                      COUNT (doc_no_ref) bills_cnt, 0 rt_bills_cnt,
					                      0 cst_invs_cnt, 0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 3
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt, 0 bills_cnt,
					                      COUNT (doc_no_ref) rt_bills_cnt, 0 cst_invs_cnt,
					                      0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 4
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt, 0 bills_cnt,
					                      0 rt_bills_cnt, COUNT (doc_no_ref) cst_invs_cnt,
					                      0 goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 5
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt, 0 bills_cnt,
					                      0 rt_bills_cnt, 0 cst_invs_cnt,
					                      COUNT (doc_no_ref) goods_rqst_cnt, 0 whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 31
					             GROUP BY m.rep_code, m.c_code
					             UNION
					             SELECT   rep_code, c_code, 0 sucses_vst, 0 failed_vst,
					                      0 vchrs_cnt, 0 quots_cnt, 0 sal_ordrs_cnt, 0 bills_cnt,
					                      0 rt_bills_cnt, 0 cst_invs_cnt, 0 goods_rqst_cnt,
					                      COUNT (doc_no_ref) whtrns_rcv_cnt
					                 FROM dts_cst_vst_mst m, dts_cst_vst_dtl d
					                WHERE m.vst_srl = d.vst_srl AND doc_type_ref = 8
					             GROUP BY m.rep_code, m.c_code)
					   GROUP BY rep_code, c_code;


--
-- DTS_V_RETURN_TYPE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_RETURN_TYPE
(LANG_NO, REP_CODE, FLG_CODE, FLG_VALUE, FLG_DESC)
BEQUEATH DEFINER
AS 
Select S_Flags.Lang_No,
                      Rep_Code,
                      S_Flags.Flg_Code,
                      S_Flags.Flg_Value,
                      S_Flags.Flg_Desc
                 From S_Flags, S_Flags_Priv, Dts_V_Sman_Info
                Where S_Flags.Flg_Code = S_Flags_Priv.Flg_Code 
                And S_Flags.Flg_Value = S_Flags_Priv.Flg_Value 
                And S_Flags.Flg_Code = 'RETURN_TYPE' 
                And Nvl (Priv_Flag, 0) = 1 
                And Dts_V_Sman_Info.U_Id = S_Flags_Priv.U_Id;


--
-- DTS_V_SMAN_BANK  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_BANK
(BANK_NO, BANK_NAME, BANK_E_NAME, REP_CODE, U_ID, 
 A_CODE, BANK_SR, MEDIATOR, REC_LETTER, PAY_LETTER, 
 RCPT_SRL_TYP, BRN_NO)
BEQUEATH DEFINER
AS 
Select C.Bank_No,
                                              C.Bank_Name,
                                              C.Bank_E_Name,
                                              S.Rep_Code,
                                              S.U_Id,
                                              C.A_Code,                                              
                                              C.Bank_Sr,
                                              C.Mediator,
                                              C.Rec_Letter,
                                              C.Pay_Letter,
                                              C.Rcpt_Srl_Typ,
                                              S.Brn_No                                             
                                         From Cash_At_Bank C, Dts_V_Sman_Info S
                                        Where  Nvl (C.Inactive, 0) = 0
                                              And S.Sman_Typ In(1,3)
                                              And C.Bank_No = Decode (C.Mediator, 1, S.Bank_No, C.Bank_No)
                                              And Exists
                                                     (Select 1
                                                        From Priv_Acc
                                                       Where A_Code = C.A_Code                                                             
                                                             And U_Id = S.U_Id
                                                             And Add_Flag = 1
                                                             And Rownum <= 1)
                                              And Exists
                                                     (Select 1
                                                        From Priv_Cash
                                                       Where Cash_Type = 2
                                                             And Cash_No = C.Bank_No                                                             
                                                             And U_Id = S.U_Id
                                                             And Add_Flag = 1
                                                             And nvl(RCVD,0)=1
                                                             And Rownum <= 1);

COMMENT ON COLUMN IAS20261.DTS_V_SMAN_BANK.MEDIATOR IS 'Ê”Ìÿ';

COMMENT ON COLUMN IAS20261.DTS_V_SMAN_BANK.REC_LETTER IS 'Õ”«» √Ê—«ﬁ «·ﬁ»÷';

COMMENT ON COLUMN IAS20261.DTS_V_SMAN_BANK.PAY_LETTER IS 'Õ”«» √Ê—«ﬁ «·œ›⁄';



--
-- DTS_V_SMAN_BRN  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_BRN
(REP_CODE, BRN_NO, BRN_LNAME, BRN_FNAME)
BEQUEATH DEFINER
AS 
Select S.Rep_Code
						         ,B.Brn_No
						         ,B.Brn_Lname
						         ,B.Brn_Fname
						     From S_Brn B, Dts_V_Sman_Info S, Ias_Para_Gen
						    Where     Nvl (Use_Balanced_Brn, 0) = 1
						          And Exists
						                 (Select 1
						                    From S_Brn_Usr_Priv
						                   Where U_Id = S.U_Id And Brn_No = B.Brn_No And Nvl (Add_Bnf_Flag, 0) = 1 And Rownum <= 1);


--
-- DTS_V_SMAN_CST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_CST
(SMAN_TYP, REP_CODE, C_CODE, W_CODE, WHG_CODE, 
 CASH_NO, BANK_NO, GRP_CODE, C_CLASS, R_CODE, 
 INACTIVE, CSH_CST, C_GROUP_CODE, COL_NO, CC_CODE, 
 CST_W_CODE)
BEQUEATH DEFINER
AS 
Select Sman_Typ
                                 ,Rep_Code
                                 ,C_Code
                                 ,W_Code
                                 ,Whg_Code
                                 ,Cash_No
                                 ,Bank_No
                                 ,Grp_Code
                                 ,C_Class
                                 ,R_Code
                                 ,Nvl (Inactive, 0) Inactive
                                 ,Csh_Cst
                                 ,C_Group_Code
                                 ,COL_NO
                                 ,CC_CODE         
                                 ,(CASE WHEN AR_UNDR_DSPSL_FLG=1 THEN (select B.w_code from IAS_CST_ITM_ACTVTY  A ,WAREHOUSE_DETAILS B
                                                                               ,Privilege_Wh Pwh
                                                                              where A.W_CODE=B.W_CODE
                                                                              AND B.W_CODE=Pwh.W_CODE 
                                                                              AND A.c_code=m.c_code
                                                                              AND A.brn_no=m.brn_NO
                                                                              and M.U_Id = Pwh.U_Id
                                                                              And Nvl (Pwh.Add_Flag, 0) = 1
                                                                              AND NVL(CUS_WH_UNDR_DSPSL_FLG,0)=1
                                                                              and rownum<=1) 
                                          ELSE NULL END )CST_W_CODE       
                             /* , NVL (Unlinked, 0) Unlinked */
                             From (Select S.Sman_Typ
                                         ,S.Rep_Code
                                         ,C.C_Code
                                         ,S.W_Code
                                         ,S.Whg_Code
                                         ,S.Cash_No
                                         ,S.Bank_No
                                         ,S.Grp_Code
                                         ,C.C_Class
                                         ,C.R_Code
                                         ,0 Inactive
                                         ,Nvl (C.Csh_Cst, 0) Csh_Cst
                                         ,C.C_Group_Code
                                         ,NVL(C.COL_NO,S.COL_NO) COL_NO
                                         ,nvl(c.CC_CODE,s.CC_CODE) CC_CODE
                                         ,s.brn_no
                                         ,NVL(P.AR_UNDR_DSPSL_FLG,0) AR_UNDR_DSPSL_FLG
                                         ,S.U_Id
                                     /*    ,0 Unlinked */
                                     From Dts_V_Sman_Info S, Customer C, Ias_Para_Ar P
                                    Where     Nvl (P.Conn_Cst_Multi_Sman, 0) = 0
                                          And Nvl(S.CONN_SP_SMAN,0)<>3
                                          And S.Rep_Code = C.Rep_Code
                                          And Nvl (C.Inactive, 0) = 0
                                          And  Nvl(S.Sman_Typ,0) In(1,3)                  
                                          And 1 = (Case
                                                      When (    Nvl (P.Ar_Ac_Link_Type, 1) = 1
                                                            And Exists
                                                                   (Select 1
                                                                      From Priv_Acc
                                                                     Where U_Id = S.U_Id And A_Code = C.C_A_Code And Nvl (Add_Flag, 0) = 1 And Rownum <= 1)) Then
                                                         1
                                                      When (    Nvl (P.Ar_Ac_Link_Type, 1) = 2
                                                            And Exists
                                                                   (Select 1
                                                                      From Ias_Priv_Customer
                                                                     Where U_Id = S.U_Id And C_Code = C.C_Code And Nvl (Add_Flag, 0) = 1 And Rownum <= 1)) Then
                                                         1
                                                      Else
                                                         0
                                                   End)
                                    And 1 =( case when Nvl(S.NOT_ALLW_SAL_OUT_LOCTN_GEO,0)=0 then 1
                                                           else nvl((select 1 from ARS_LOCTN_GEO_SMAN G 
                                                                         where rep_code=s.rep_code
                                                                         and 1=case when  LOC_TYP=1 and nvl(c.CNTRY_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=2 and nvl(c.PROV_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=3 and nvl(c.CITY_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=4 and nvl(c.R_CODE,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=5 and nvl(c.ROUTE_NO,0)=G.CODE_NO then 1 
                                                                                    else 0 end 
                                                                         and rownum<=1                                                                                      
                                                                         ),0) 
                                                        end)                                                    
                                   Union
                                   Select S.Sman_Typ
                                         ,S.Rep_Code
                                         ,C.C_Code
                                         ,S.W_Code
                                         ,S.Whg_Code
                                         ,S.Cash_No
                                         ,S.Bank_No
                                         ,S.Grp_Code
                                         ,Cst.C_Class
                                         ,Cst.R_Code
                                         ,0 Inactive
                                         ,Nvl (Cst.Csh_Cst, 0) Csh_Cst
                                         ,Cst.C_Group_Code
                                         ,NVL(Cst.COL_NO,S.COL_NO) COL_NO
                                         ,nvl(Cst.CC_CODE,s.CC_CODE) CC_CODE
                                         ,s.brn_no                 
                                         ,NVL(P.AR_UNDR_DSPSL_FLG,0) AR_UNDR_DSPSL_FLG
                                         ,S.U_Id
                                     /* ,NVL (c.Unlinked, 0) Unlinked */
                                     From Dts_V_Sman_Info S
                                         ,Ias_Cst_Sman C
                                         ,Ias_Para_Ar P
                                         ,Customer Cst
                                    Where  S.Rep_Code = C.Rep_Code                  
                                          And Cst.C_Code = Nvl (C.C_Code, 0)                  
                                          And Nvl (Cst.Inactive, 0) = 0
                                          And  Nvl(S.Sman_Typ,0) In(1,3)
                                          And 1=Case when Nvl (P.Conn_Cst_Multi_Sman, 0) = 1 Then 1
                                                     When  Nvl (P.Conn_Cst_Multi_Sman, 0) = 0 And Nvl(S.CONN_SP_SMAN,0)=3 Then 1
                                                     Else 0 End 
                                          And 1 = (Case
                                                      When (    Nvl (P.Ar_Ac_Link_Type, 1) = 1
                                                            And Exists
                                                                   (Select 1
                                                                      From Priv_Acc
                                                                     Where U_Id = S.U_Id And A_Code = Cst.C_A_Code And Nvl (Add_Flag, 0) = 1 And Rownum <= 1)) Then
                                                         1
                                                      When (    Nvl (P.Ar_Ac_Link_Type, 1) = 2
                                                            And Exists
                                                                   (Select 1
                                                                      From Ias_Priv_Customer
                                                                     Where U_Id = S.U_Id And C_Code = Cst.C_Code And Nvl (Add_Flag, 0) = 1 And Rownum <= 1)) Then
                                                         1
                                                      Else
                                                         0
                                                   End)
                                           And 1 =( case when Nvl(S.NOT_ALLW_SAL_OUT_LOCTN_GEO,0)=0 then 1
                                                           else nvl((select 1 from ARS_LOCTN_GEO_SMAN G 
                                                                         where rep_code=s.rep_code
                                                                         and 1=case when  LOC_TYP=1 and nvl(Cst.CNTRY_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=2 and nvl(Cst.PROV_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=3 and nvl(Cst.CITY_NO,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=4 and nvl(Cst.R_CODE,0)=G.CODE_NO then 1 
                                                                                    when  LOC_TYP=5 and nvl(Cst.ROUTE_NO,0)=G.CODE_NO then 1 
                                                                                    else 0 end 
                                                                         and rownum<=1                                                                                      
                                                                         ),0) 
                                                        end)          
                                                   ) M;


--
-- DTS_V_SMAN_DOC_SYNC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_DOC_SYNC
(DOC_TYPE, DOC_TYPE_NAME, SYNC_METHOD, REP_CODE)
BEQUEATH DEFINER
AS 
Select Doc_Type
                                 ,Doc_Type_Name (2, Doc_Type) Doc_Type_Name
                                 ,Sync_Method
                                 ,Rep_Code
                             From (With Sman
                                        As (Select S.Rep_Code
                                                  , S.Brn_No
                                                  , Nvl (Ars_Api_Trns_Pkg.IS_USE_ETS_WEB_SRVC( P_BRN_NO  =>S.BRN_NO, P_SYS_NO =>70), 0) IS_USE_ETS
                                              From Dts_V_Sman_Info S
                                              )
                                   Select D.Doc_Type,
                                          CASE WHEN D.Doc_Type IN(4,5)  AND NVL(Sman.IS_USE_ETS,0)=1 THEN 3
                                               ELSE Decode (Nvl (P.Save_Doc_Method, 0), 1, P.Sync_Method, D.Sync_Method)
                                               END Sync_Method, 
                                          Sman.Rep_Code
                                     From Dts_Doc_Type D, Dts_Para P, Sman
                                    Where Nvl (P.Save_Doc_Method, 0) In (1, 3)
                                   Union All
                                   Select S.Doc_Type,
                                          CASE WHEN S.Doc_Type IN(4,5)  AND NVL(Sman.IS_USE_ETS,0)=1 THEN 3
                                               ELSE Nvl (S.Sync_Method, 1)
                                               END Sync_Method,                                           
                                          S.Rep_Code Rep_Code
                                     From Ias_Sman_Doc_Sync_Dts S, Dts_Para P, Sman
                                    Where S.Rep_Code = Sman.Rep_Code 
                                       And Nvl (P.Save_Doc_Method, 0) = 4
                                   Union All
                                   Select D.Doc_Type,
                                          CASE WHEN D.Doc_Type IN(4,5)  AND NVL(Sman.IS_USE_ETS,0)=1 THEN 3
                                               ELSE Nvl (S.Sync_Method, 1)
                                               END Sync_Method,                                            
                                          S.Reprs_Code Rep_Code
                                     From Dts_Doc_Type D
                                         ,Sales_Man S
                                         ,Dts_Para P
                                         ,Sman
                                    Where Nvl (P.Save_Doc_Method, 0) = 2 
                                         And S.Reprs_Code = Sman.Rep_Code);


--
-- DTS_V_SMAN_UNPSTED_SALES_DOC  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_UNPSTED_SALES_DOC
(DOC_TYPE, BILL_NO, BILL_SER, BILL_DOC_TYPE, REP_CODE, 
 C_CODE, CASH_NO, A_CY, BILL_DATE, BILL_AMT, 
 DISC_AMT, VAT_AMT, OTHR_AMT, NET_AMT, NET_AMTL)
BEQUEATH DEFINER
AS 
SELECT doc_type,
        Bill_no,
            Bill_ser,
            Bill_doc_type,
            Rep_code,
            C_code,
            Cash_No,
            Bill_currency,
            Bill_date,
            (NVL (Bill_Amt, 0)) Bill_Amt,
            (NVL (Disc_Amt, 0)) Disc_Amt,
            (NVL (Vat_Amt, 0)) Vat_Amt,
            (NVL (Othr_Amt, 0)) Othr_Amt,
            (NVL (Net_Amt, 0)) Net_Amt,
            (NVL (Net_Amtl, 0)) Net_Amtl
       FROM (  SELECT 4 doc_type,
                      Bill_no,
                      Bill_ser,
                      Bill_doc_type,
                      Rep_code,
                      C_code,
                      Cash_No,
                      Bill_currency,
                      Bill_date,
                      NVL (Bill_Amt,0) Bill_Amt,
                      NVL (Disc_Amt,0) Disc_Amt,
                      NVL (Vat_Amt,0) Vat_Amt,
                      NVL (Othr_Amt,0) Othr_Amt,
                      ( NVL (Bill_Amt,0)
                                - (  NVL (CR_CARD_AMT,0)
                                   + NVL (CR_CARD_AMT_SCND,0)
                                   + NVL (CR_CARD_AMT_THRD,0))
                             - NVL (Disc_Amt,0)
                             + NVL (Vat_Amt,0)
                             + NVL (Othr_Amt,0)) Net_Amt,
                         (( NVL (Bill_Amt,0)
                                - (  NVL (CR_CARD_AMT,0)
                                   + NVL (CR_CARD_AMT_SCND,0)
                                   + NVL (CR_CARD_AMT_THRD,0))
                             - NVL (Disc_Amt,0)
                             + NVL (Vat_Amt,0)
                             + NVL (Othr_Amt,0))
                                * NVL (Bill_Rate,1)) Net_Amtl
                 FROM Ias_Bill_Mst_Br M
                WHERE     NVL (External_Post, 0) = 70
                      AND NVL (Cncl_Flg, 0) = 0
                      AND NVL (Bill_Post, 0) = 0
                      AND NOT EXISTS
                                 (SELECT 1
                                    FROM Ias_Bill_Mst I
                                   WHERE NVL (External_Post, 0) = 70
                                         AND Bill_Ser = m.Bill_Ser
                                         AND ROWNUM <= 1)
             UNION
               SELECT 5 doc_type,
                      Rt_Bill_no,
                      Rt_Bill_ser,
                      Rt_Bill_doc_type,
                      Rep_code,
                      C_code,
                      Cash_No,
                      Rt_Bill_currency,
                      Rt_Bill_date,
                      NVL (Bill_Amt,0)*-1 Bill_Amt,
                      NVL (Disc_Amt,0)*-1 Disc_Amt,
                      NVL (Vat_Amt,0)*-1 Vat_Amt,
                      NVL (Othr_Amt,0)*-1 Othr_Amt,
                      ( NVL (Bill_Amt,0)
                                - (  NVL (CR_CARD_AMT,0)
                                   + NVL (CR_CARD_AMT_SCND,0)
                                   + NVL (CR_CARD_AMT_THRD,0))
                             - NVL (Disc_Amt,0)
                             + NVL (Vat_Amt,0)
                             + NVL (Othr_Amt,0))*-1 Net_Amt,
                         (( NVL (Bill_Amt,0)
                                - (  NVL (CR_CARD_AMT,0)
                                   + NVL (CR_CARD_AMT_SCND,0)
                                   + NVL (CR_CARD_AMT_THRD,0))
                             - NVL (Disc_Amt,0)
                             + NVL (Vat_Amt,0)
                             + NVL (Othr_Amt,0))
                                * NVL (RT_Bill_Rate,1))*-1 Net_Amtl
                 FROM Ias_Rt_Bill_Mst_Br
                WHERE     NVL (External_Post, 0) = 70
                      AND NVL (Cncl_Flg, 0) = 0
                      AND NVL (Rt_Bill_Post, 0) = 0
                      AND NOT EXISTS
                                 (SELECT 1
                                    FROM Ias_Rt_Bill_Mst I
                                   WHERE NVL (External_Post, 0) = 70
                                     AND Rt_Bill_Ser =Ias_Rt_Bill_Mst_Br.Rt_Bill_Ser
                                         AND ROWNUM <= 1));


--
-- DTS_V_VST_MVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_VST_MVMNT
(DOC_TYPE, JV_TYPE, DOC_TYPE_NM, DOC_NO, DOC_SER, 
 VST_NO, VST_SRL, VST_DATE, REP_CODE, C_CODE, 
 DOC_DATE, DOC_TYPE_REF, DOC_NO_REF, DOC_SER_REF, CNCL_FLG, 
 A_CY, DOC_AMT)
BEQUEATH DEFINER
AS 
Select 4 Doc_Type,
          Br.Bill_Doc_Type Jv_Type,
          'Sales Inv' Doc_Type_Nm,
          Br.Bill_No Doc_No,
          Br.Bill_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Bill_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          Br.Cncl_Flg,
          Br.Bill_Currency A_Cy,
          (Nvl(Bill_Amt, 0) + Nvl(Othr_Amt, 0) + Nvl(Vat_Amt_Othr, 0) + Nvl(Vat_Amt, 0)) - (Nvl(Disc_Amt_Mst, 0) + Nvl(Disc_Amt_Dtl, 0) + Nvl(Disc_Amt_Aftr_Vat, 0)) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Ias_Bill_Mst_Br Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 4
   Union All
   Select 5 Doc_Type,
          Br.Rt_Bill_Doc_Type Jv_Type,
          'Sales Return Inv' Doc_Type_Nm,
          Br.Rt_Bill_No Doc_No,
          Br.rt_Bill_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Rt_Bill_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          Br.Cncl_Flg,
          Br.Rt_Bill_Currency A_Cy,
          (Nvl(Bill_Amt, 0) + Nvl(Othr_Amt, 0) + Nvl(Vat_Amt_Othr, 0) + Nvl(Vat_Amt, 0)) - (Nvl(Disc_Amt_Mst, 0) + Nvl(Disc_Amt_Dtl, 0)) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Ias_Rt_Bill_Mst_Br Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 5
   Union All
   Select 52 Doc_Type,
          Null Jv_Type,
          'Sales Quotation' Doc_Type_Nm,
          Br.Quot_No Doc_No,
          Br.Quot_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Quot_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Br.Quot_Cur A_Cy,
          (Nvl(Quot_Amt, 0) + Nvl(Othr_Amt, 0) + Nvl(Vat_Amt_Othr, 0) + Nvl(Vat_Amt, 0)) - (Nvl(Disc_Amt_Mst, 0) + Nvl(Disc_Amt_Dtl, 0)) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Quotation Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 52
   Union All
   Select 53 Doc_Type,
          Null Jv_Type,
          'Sale Order' Doc_Type_Nm,
          Br.Order_No Doc_No,
          Br.Order_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Order_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Br.Order_Cur A_Cy,
          (Nvl(Order_Amt, 0) + Nvl(Othr_Amt, 0) + Nvl(Vat_Amt_Othr, 0) + Nvl(Vat_Amt, 0)) - (Nvl(Disc_Amt_Mst, 0) + Nvl(Disc_Amt_Dtl, 0)) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Sales_Order Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 53
   Union All
   Select 1410 Doc_Type,
          Null Jv_Type,
          'Customer W.H Stocktaking ' Doc_Type_Nm,
          Br.Doc_No Doc_No,
          Br.doc_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Doc_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Null A_Cy,
          0 Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Dts_Stk_Cst_Mst Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 1410
   Union All
   Select 2 Doc_Type,
          Br.Voucher_Pay_Type Jv_Type,
          'Recipet Voucher' Doc_Type_Nm,
          Br.Voucher_No Doc_No,
          Br.V_SER Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Voucher_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Br.A_Cy A_Cy,
          Decode(Br.A_Cy, Ias_Gen_Pkg.Get_Local_Cur, Br.Cash_Amt, Br.Cash_Amtf) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Vouchers Br
    Where M.Vst_Srl = D.Vst_Srl
          And To_Char(D.Doc_Ser_Ref) = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 2
          And Br.Voucher_Type = 1
   Union All
   Select 136 Doc_Type,
          Br.Rt_Bill_Doc_Type Jv_Type,
          'Sales Retuen Request' Doc_Type_Nm,
          Br.Rt_Bill_No Doc_No,
          Br.Rt_Bill_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Rt_Bill_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Br.Rt_Bill_Currency A_Cy,
          (Nvl(Bill_Amt, 0) + Nvl(Othr_Amt, 0) + Nvl(Vat_Amt, 0)) - (Nvl(Disc_Amt_Mst, 0) + Nvl(Disc_Amt_Dtl, 0)) Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Ias_Rt_Bill_Mst_Rq Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 136
   Union All
   Select 1406 Doc_Type,
          Null Jv_Type,
          'Show Items' Doc_Type_Nm,
          Br.Doc_No Doc_No,
          Br.doc_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Doc_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Null A_Cy,
          0 Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Dts_Itms_Shw_Mst Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 1406
   Union All
   Select 1407 Doc_Type,
          Null Jv_Type,
          'Items Questionnaire' Doc_Type_Nm,
          Br.Doc_No Doc_No,
          Br.doc_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Doc_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Null A_Cy,
          0 Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Ars_Questnnr_Mst Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 1407
   Union All
   Select 31 Doc_Type,
          Null Jv_Type,
          'Request Transfer' Doc_Type_Nm,
          Br.Out_Req_No Doc_No,
          Br.Out_Req_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.Out_Req_Date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Null A_Cy,
          0 Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, Ias_Out_Request_Mst Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 31
     Union All
   Select 1412 Doc_Type,
          Null Jv_Type,
          'Free Samples Outing' Doc_Type_Nm,
          Br.doc_no Doc_No,
          Br.doc_ser Doc_ser,
          M.Vst_No,
          M.Vst_Srl,
          To_Date(Arivl_Tm, 'DD/MM/YYYY') Vst_Date,
          M.Rep_Code,
          M.C_Code,
          Br.doc_date Doc_Date,
          D.Doc_Type_Ref,
          D.Doc_No_Ref,
          D.Doc_Ser_Ref,
          0 Cncl_Flg,
          Null A_Cy,
          0 Doc_Amt
     From Dts_Cst_Vst_Mst M, Dts_Cst_Vst_Dtl D, DTS_FREE_SMPL_MST Br
    Where M.Vst_Srl = D.Vst_Srl
          And D.Doc_Ser_Ref = Br.Doc_Ser_Extrnl(+)          
          And D.Doc_Type_Ref = 1412;


--
-- DTS_V_VST_PLAN_MVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_VST_PLAN_MVMNT
(C_CODE, C_NAME, REP_CODE, DOC_DATE, DOC_TYPE, 
 DOC_TYPE_NM, DOC_AMT, IN_PLAN, IN_PLAN_NM, EXEC_FLG, 
 EXEC_FLG_NM, VST_STS, VST_STS_NM, JV_TYPE, CST_TYPE, 
 LAT, LNG)
BEQUEATH DEFINER
AS 
WITH VST
        AS (SELECT *
              FROM (SELECT M.C_Code,
                           M.Rep_Code,
                           TO_DATE (m.ARIVL_TM, 'dd/mm/rrrr') doc_date,
                           NVL (D.Doc_Type, 0) Doc_Type,
                           NVL (ROUND (Doc_Amt, 2), 0) Doc_Amt,
                           M.VST_STS,
                           D.Jv_Type,
                           CASE WHEN PRM_CODE IS NOT NULL THEN 2 ELSE 1 END CST_TYPE
                      FROM Dts_Cst_Vst_Mst M, Dts_V_Vst_Mvmnt D
                     WHERE M.Vst_Srl = D.Vst_Srl(+))),
        PLN
        AS (SELECT d.c_code,
                   m.Rep_Code,
                   m.Doc_date,
                   DD.DOC_TYPE,
                   PLAN_TYP CST_TYPE
              FROM Dts_Plan_Sman_Dtl d, Dts_Plan_Sman_mst m, Dts_Plan_Sman_Dtl_DTL DD
             WHERE m.doc_ser = d.doc_ser AND m.doc_ser = DD.doc_ser AND d.C_code = DD.c_code AND NVL (m.APPROVED, 0) = 1 AND NVL (DD.INCLD_FLG, 0) = 1),
        MOV
        AS (SELECT M.c_code,
                   m.Rep_Code,
                   m.Doc_date,
                   M.DOC_TYPE,
                   NVL (V.Doc_Amt, 0) DOC_AMT,
                   1 IN_PLAN,
                   CASE WHEN NVL (V.DOC_TYPE, 0) > 0 THEN 1 ELSE 0 END EXEC_FLG,
                   NVL (V.VST_STS, 0) VST_STS,
                   V.Jv_Type,
                   M.CST_TYPE
              FROM PLN M, VST V
             WHERE M.C_code = V.c_code(+) AND M.REP_code = V.REP_code(+) AND M.DOC_TYPE = V.DOC_TYPE(+) AND M.DOC_DATE = V.doc_date(+)
            UNION ALL
            SELECT M.c_code,
                   m.Rep_Code,
                   m.Doc_date,
                   M.DOC_TYPE,
                   NVL (M.Doc_Amt, 0) DOC_AMT,
                   0 IN_PLAN,
                   CASE WHEN NVL (M.DOC_TYPE, 0) > 0 THEN 1 ELSE 0 END EXEC_FLG,
                   M.VST_STS,
                   M.Jv_Type,
                   M.CST_TYPE
              FROM VST M
             WHERE NOT EXISTS
                      (SELECT 1
                         FROM PLN
                        WHERE C_code = M.c_code AND REP_CODE = M.REP_CODE AND DOC_DATE = M.DOC_DATE AND DOC_TYPE = M.DOC_TYPE AND ROWNUM <= 1))
   SELECT M.c_code,
          DECODE (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), 1, NVL (C_A_NAME, C_E_NAME), NVL (C_E_NAME, C_A_NAME)) C_NAME,
          m.Rep_Code,
          m.Doc_date,
          M.DOC_TYPE,
          DECODE (NVL (M.Doc_Type, 0), 0, Ias_Gen_Pkg.Get_Prompt (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), 22241), Doc_Type_Name (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), M.Doc_Type)) DOC_TYPE_NM,
          M.DOC_AMT,
          M.IN_PLAN,
          Ias_Gen_Pkg.Get_Prompt (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), DECODE (M.IN_PLAN, 1, 17871, 5038)) IN_PLAN_NM,
          M.EXEC_FLG,
          Ias_Gen_Pkg.Get_Prompt (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), DECODE (M.EXEC_FLG, 1, 4898, 22239)) EXEC_FLG_NM,
          M.VST_STS,
          Ias_Gen_Pkg.Get_Prompt (NVL (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), DECODE (M.VST_STS, 1, 22240, 22241)) VST_STS_NM,
          M.Jv_Type,
          M.CST_TYPE,
          TO_NUMBER (NVL (Latitude, NVL ( (SUBSTR (Gps, 1, INSTR (Gps, ',') - 1)), '0'))) LAT,
          TO_NUMBER (NVL (Longitude, NVL ( (SUBSTR (Gps, INSTR (Gps, ',') + 1)), '0'))) LNG
     FROM MOV M, CUSTOMER C
    WHERE M.C_CODE = C.C_CODE;


--
-- GLS_V_CASH_FLOW_LIST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CASH_FLOW_LIST
(BRN_YEAR, FLOW_TYPE, FLOW_TYPE_NM, AC_CODE, AC_L_NM, 
 AC_F_NM, DOC_DATE, AMT)
BEQUEATH DEFINER
AS 
select brn_year,FLOW_TYPE,FLOW_TYPE_nm,ac_code,ac_l_Nm,ac_F_Nm,doc_date,Amt 
from(
select dtl.brn_year,mst.FLOW_TYPE,YS_GEN_PKG.GET_FLG_NM ('AC_FLOW_TYPE',mst.FLOW_TYPE,1) FLOW_TYPE_nm
 ,mst.AC_TREE ac_code,mst.A_NAME ac_l_Nm, mst.A_NAME_ENG ac_F_Nm,trunc(dtl.doc_date) doc_date,round(sum(dtl.amt),2) amt
from ias_acc_tree mst, ias_v_post_dtl_yr dtl --ias_v_post_dtl_opn_yr
where mst.a_code=dtl.a_code
and mst.AC_TREE=dtl.a_code
and dtl.ac_dtl_typ not in(1,2)
and  dtl.doc_type <>0   --movement balance
and mst.FLOW_TYPE is not null
group by dtl.brn_year,mst.FLOW_TYPE,mst.AC_TREE,mst.A_NAME, mst.A_NAME_ENG,trunc(dtl.doc_date) 
/*union
select dtl.brn_year,4 FLOW_TYPE ,YS_GEN_PKG.GET_PROMPT(P_Lng_no =>1 ,P_Lbl_no =>20809) FLOW_TYPE_nm
,mst.AC_TREE ac_code,mst.A_NAME ac_l_Nm, mst.A_NAME_ENG ac_F_Nm,trunc(dtl.doc_date) doc_date,round(sum(dtl.amt),2) amt
from ias_acc_tree mst, ias_v_post_dtl_yr dtl
where mst.a_code=dtl.a_code
and mst.AC_TREE=dtl.a_code
and dtl.ac_dtl_typ  in(1,2)
and  dtl.doc_type =0  --cash start  balance
group by dtl.brn_year,4,YS_GEN_PKG.GET_PROMPT(P_Lng_no =>1 ,P_Lbl_no =>20809),mst.AC_TREE,mst.A_NAME, mst.A_NAME_ENG,trunc(dtl.doc_date) */
union
select dtl.brn_year,5 FLOW_TYPE,YS_GEN_PKG.GET_PROMPT(P_Lng_no =>1 ,P_Lbl_no =>20810) FLOW_TYPE_nm
,mst.AC_TREE ac_code,mst.A_NAME ac_l_Nm, mst.A_NAME_ENG ac_F_Nm,trunc(dtl.doc_date) doc_date,round(sum(dtl.amt),2) amt
from ias_acc_tree mst, ias_v_post_dtl_yr dtl
where mst.a_code=dtl.a_code
and mst.AC_TREE=dtl.a_code
and dtl.ac_dtl_typ  in(1,2)  --cash end  balance,cash start  balance 4 FLOW_TYPE ,YS_GEN_PKG.GET_PROMPT(P_Lng_no =>1 ,P_Lbl_no =>20809) FLOW_TYPE_nm
group by dtl.brn_year,5,YS_GEN_PKG.GET_PROMPT(P_Lng_no =>1 ,P_Lbl_no =>20810),mst.AC_TREE,mst.A_NAME, mst.A_NAME_ENG,trunc(dtl.doc_date) 
) x
order by brn_year,FLOW_TYPE,ac_code,doc_date;


--
-- GLS_V_CR_AMT_RCVD  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CR_AMT_RCVD
(DOC_TYP, DOC_NO, DOC_SRL, AC_CODE, AC_CODE_DTL, 
 AC_DTL_TYP, CNTRCT_SRL, CNTRCT_NO, CNTRCT_BTCH, DOC_SER_REF, 
 DOC_TYP_REF, DOC_JV_TYP_REF, AMT_L, AMT_F)
BEQUEATH DEFINER
AS 
SELECT 2, VOUCHER_NO,
             V_SER, A_CODE,
             AC_CODE_DTL, AC_DTL_TYP,
             CNTRCT_SRL, CNTRCT_NO,
             CNTRCT_BTCH, Doc_ser_Ref,
             DOC_TYPE_REF,DOC_JV_TYPE_REF, ABS(SUM(NVL(AC_AMT, 0) + NVL(OTR_AMT_L, 0))) AMT_L,
             ABS(SUM(NVL(AC_AMTF, 0) + NVL(OTR_AMT_F, 0))) AMT_F
        FROM GLS_V_VCHR_DTL_YR
       WHERE VOUCHER_TYPE = 1 AND DOC_SER_REF IS NOT NULL
    GROUP BY 2, VOUCHER_NO,
             V_SER, A_CODE,
             AC_CODE_DTL, AC_DTL_TYP,
             CNTRCT_SRL, CNTRCT_NO,
             CNTRCT_BTCH, DOC_TYPE_REF,DOC_JV_TYPE_REF,
             Doc_Ser_Ref
    UNION ALL
      SELECT 1, J_DOC_NO,
             J_SER, A_CODE,
             AC_CODE_DTL, AC_DTL_TYP,
             CNTRCT_SRL, CNTRCT_NO,
             CNTRCT_BTCH, Doc_ser_Ref,
             DOC_TYPE_REF,DOC_JV_TYPE_REF, ABS(SUM(NVL(J_AMT, 0))) AMT,
             ABS(SUM(NVL(J_AMT_F, 0))) AMT_F
        FROM GLS_V_JRNL_DTL_YR
       WHERE NVL(J_AMT, 0) < 0 AND DOC_SER_REF IS NOT NULL
    GROUP BY 1, J_DOC_NO,
             J_SER, A_CODE,
             AC_CODE_DTL, AC_DTL_TYP,
             CNTRCT_SRL, CNTRCT_NO,
             CNTRCT_BTCH, DOC_TYPE_REF,DOC_JV_TYPE_REF,
             Doc_Ser_Ref;


--
-- GLS_V_DOC_PST_UNPST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_DOC_PST_UNPST
(DOC_TYPE, DOC_JV_TYPE, DOC_NO, DOC_SER, DOC_DATE, 
 A_CY, REF_NO, CC_CODE, W_CODE, CASH_NO, 
 DOC_POST, AD_U_ID, AD_DATE, POST_U_ID, POST_DATE, 
 UNPOST_U_ID, UNPOST_DATE, AUDIT_REF, AUDIT_REF_DESC, AUDIT_REF_U_ID, 
 AUDIT_REF_DATE, BRN_NO, BRN_YEAR, CMP_NO, BRN_USR, 
 STAND_BY)
BEQUEATH DEFINER
AS 
Select 1, JV_TYPE, J_DOC_NO, J_SER , J_DATE  , Null,REF_NO, 
					                          Null  , Null     , Null, nvl(J_POST,0), AD_U_ID, AD_DATE, 
					                          POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
					                          AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
					                          BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
					                     From Master_Journal_v
					                      Where (12=1 or Exists  ( Select 1 From jv_types_detail 
                                                              where jv_type=Master_Journal_v.jv_type 
                                                                and u_id=12 
                                                                and View_Flag=1
                                                                and RowNum<=1))
					                 Union ALL --## Vouchers
					                    Select Decode(voucher_type,1,2,2,3), Voucher_Pay_Type, voucher_no,V_SER ,Voucher_DATE, A_cy,REF_NO,
					                           Null  , Null     , TO_CHAR(Cash_No), nvl(Voucher_POST,0), AD_U_ID, AD_DATE, 
					                           POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
					                           AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
					                           BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
					                      From vouchers
					                      WHERE (12=1 or Exists (Select 1 From GLS_VCHR_TYP_PRV 
																	                         Where v_typ =vouchers.voucher_type 
																	                           AND v_typ_no=vouchers.v_type_no 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
					                  Union ALL --## cheques
					                    Select DECODE(M.Voucher_Type,1,83,2,84),M.Voucher_Pay_Type, M.voucher_no,M.V_SER , M.Voucher_DATE , D.A_cy,M.REF_NO,
					                           Null  , Null     , TO_CHAR(M.Cash_No), nvl(D.CHEQUE_POST,0), D.AD_U_ID, D.AD_DATE, 
					                           D.POST_U_ID, D.POST_DATE, D.UNPOST_U_ID, D.UNPOST_DATE, 
					                           D.AUDIT_REF,D.AUDIT_REF_DESC,D.AUDIT_REF_U_ID,D.AUDIT_REF_DATE,
					                           D.BRN_NO, D.BRN_YEAR,D.Cmp_No,D.Brn_Usr,M.stand_by
					                          From Vouchers M,Voucher_Detail D
					                         Where M.V_Ser=D.V_Ser
					                           And Nvl(M.Voucher_Pay_Type,0) = 2
					                           And M.Cheq_Type = 3
					                           And nvl(D.cheque_valued,0) In (1,2)
					                           AND (12=1 or Exists (Select 1 From GLS_VCHR_TYP_PRV 
																	                         Where v_typ =M.voucher_type 
																	                           AND v_typ_no=M.v_type_no 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
					                  Union ALL --## IIAS_EXCH_CUR_MST
					                     Select 98,TYP_NO, DOC_no, DOC_SRL , DOC_DATE , CUR_CODE,REF_NO,
					                           Null  , Null     , AC_CODE_DTL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
					                           POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
					                           AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
					                           BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
					                       From IAS_EXCH_CUR_MST 
					                   Union ALL --## IAS_BILL_MST_ADD_DISC
                                  Select 15,ADD_DISC_TYPE, DOC_No, DOC_Ser , DOC_DATE, A_Cy,REF_NO,
                                         Null  , Null     , NULL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
                                         POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                                         AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                         BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
                                    From IAS_BILL_MST_ADD_DISC  Union ALL --## Ias_Bill_Mst
                             Select 4, Bill_Doc_TYPE, Bill_No,Bill_SER ,BILL_DATE  , Null,REF_NO,
		                                Null  , Null     , Null, nvl(Bill_POST,0), AD_U_ID, AD_DATE, 
		                                POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
		                                AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
		                                BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
                               From Ias_Bill_Mst
                                WHERE (12=1 or Exists (Select 1 From IAS_PRIV_AR 
																	                         Where AR_TYPE =3 
																	                           AND S_TYPE=Ias_Bill_Mst.SI_TYPE 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
						              Union ALL --## Ias_Rt_Bill_Mst
						                 Select 5, Rt_Bill_Doc_TYPE, Rt_Bill_No, Rt_Bill_SER ,RT_BILL_DATE , Null,REF_NO,
                                    Null  , Null     , Null,nvl(Rt_Bill_POST,0), AD_U_ID, AD_DATE, 
                                    POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                                    AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                    BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,stand_by
                               From Ias_Rt_Bill_Mst
                                WHERE (12=1 or Exists (Select 1 From IAS_PRIV_AR 
																	                         Where AR_TYPE =4 
																	                           AND S_TYPE=Ias_Rt_Bill_Mst.SR_Type 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
													 Union ALL --## Master_Out_Bills 
										          Select 13, Bill_Doc_type, Out_No, Out_SER ,OUT_DATE , Null,REF_NO,
                                    Null  , Null     , Null, nvl(Out_POST,0), AD_U_ID, AD_DATE, 
                                    POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                                    AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                    BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,0
										           From Master_Out_Bills
										            WHERE (12=1 or Exists (Select 1 From IAS_PRIV_AR 
																	                         Where AR_TYPE =3 
																	                           AND S_TYPE=Master_Out_Bills.SI_TYPE 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
										       Union ALL --## Ias_Ret_bill_Mst
										          Select 14, Rt_Bill_Doc_type, Ret_No,Ret_SER ,RET_DATE , Null,REF_NO,
                                      Null  , Null     , Null, nvl(Ret_POST,0), AD_U_ID, AD_DATE, 
                                      POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                                      AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                    BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,0
                           From Ias_Ret_bill_Mst 
                            WHERE (12=1 or Exists (Select 1 From IAS_PRIV_AR 
																	                         Where AR_TYPE =4 
																	                           AND S_TYPE=Ias_Ret_bill_Mst.SR_Type 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1)) Union ALL --## Ias_Pi_Bill_Mst_Add_Disc
                        Select 16,ADD_DISC_TYPE, BILL_No, BILL_Ser ,BILL_DATE , A_Cy,REF_NO,
                                             Null  , Null     , NULL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
