                                From Ias_Pi_Bill_Mst
                                WHERE (12=1 or Exists (Select 1 From IAS_PRIV_AP 
																	                         Where AP_TYPE =4 
																	                           AND P_TYPE=Ias_Pi_Bill_Mst.BILL_TYPE_NO 																	                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
						               Union ALL --## Ias_Pr_Bill_Mst 
						                  Select 7, Rt_Bill_Doc_TYPE, Rt_Bill_No,Rt_Bill_SER , RT_BILL_DATE , Null,REF_NO,
                                      Null  , Null     , Null,nvl(Rt_Bill_POST,0), AD_U_ID, AD_DATE, 
                                      POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE,
                                      AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                      BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,HUNG
                                 From Ias_Pr_Bill_Mst  Union ALL --## Gr_Note 
                            Select 8, Incom_Type, Gr_No,G_SER ,GR_DATE , Null,REF_NO,
                                  Null  , Null     , Null,nvl(Gr_POST,0), AD_U_ID, AD_DATE, 
