                             From STK_ADJUSTMENT
                             WHERE (12=1 or Exists (Select 1 From IAS_PRIV_STK_ADJST_TYPES	
																	                           Where ADJUST_TYPE=STK_ADJUSTMENT.ADJUST_TYPE  																	                         																                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 	
																	                            and RowNum<=1))					
					               Union ALL --## Ias_WhTrns_Mst 
					                  Select DECODE(TR_INOUT_TYPE ,1,11,2,12), TR_TYPE, TR_NO,Tr_SER ,TR_DATE  , Null,REF_NO,
                                  Null  , Null     , Null, nvl(Tr_POST,0), AD_U_ID, AD_DATE, 
                                  POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE,
                                  AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                  BRN_NO, BRN_YEAR ,Cmp_No,Brn_Usr,HUNG
                             From Ias_WhTrns_Mst
                             WHERE (12=1 or Exists (Select 1 From Priv_Trnsfr_Type	
																	                           Where Tr_TYPE=Ias_WhTrns_Mst.Tr_TYPE  																	                         																                          
																	                           and U_Id= 12 
																	                           and View_Flag=1 
																	                           and RowNum<=1))
                        Union ALL --## Assemble_Kit_Items
                           Select 17,EXP_AMT_TYPE, DOC_No, DOC_Ser , DOC_DATE , NULL,REF_NO,
                                 Null  , Null     , NULL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
                                 POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                                 AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                                 BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,HUNG
                            From Assemble_Kit_Items
                     Union ALL --## DisAssemble_Kit_Items
                        Select 18,NULL, DOC_No, DOC_Ser , DOC_DATE  , NULL,REF_NO,
                               Null  , Null     , NULL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
                               POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
                               AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
                               BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,HUNG
                          From DisAssemble_Kit_Items  Union ALL --## IAS_GRNT_MST
                           Select 27,GR_TYPE, DOC_No, DOC_SRL , DOC_DATE , CUR_CODE,REF_NO,
                                 Null  , Null     , NULL,nvl(DOC_POST,0), AD_U_ID, AD_DATE, 
                                 POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
