										         POST_U_ID, POST_DATE, UNPOST_U_ID, UNPOST_DATE, 
										         AUDIT_REF,AUDIT_REF_DESC,AUDIT_REF_U_ID,AUDIT_REF_DATE,
										         BRN_NO, BRN_YEAR,Cmp_No,Brn_Usr,NULL stand_by
										       From IAS_POST_MST
										       WHERE DOC_TYPE NOT IN (1,2,3,4,5,13,14,15,83,84,98,16,6,7,8,9,10,11,12,17,18,95,96,27,28,29,500,501,502,503,504,521,525,526,603,604,605,606,607,717,757,805,1203,1204,1206,1207,
                               12502,12507,12509,12512,12513,12514,12521,12609,14509,14521);

