--
-- GNR_TAX_RT_PURCH_NO_VAT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_RT_PURCH_NO_VAT_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 A_CY, CLC_TYP_NO_TAX, VAT_TYPE, VAT_AMT, DOC_AMT)
BEQUEATH DEFINER
AS 
SELECT Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             (  DECODE (
                    NVL (Clc_Tax_Free_Qty_Flg, 0),
                    0, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * (  NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                              + NVL (Ias_Pr_Bill_Dtl.Free_Qty, 0))
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Vat_Amt,
             (  DECODE (
                    1,
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    2, SUM (
                             ((  NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                               - NVL (Ias_Pr_Bill_Dtl.Dis_Amt, 0)))
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Pr_Bill_Mst, Ias_Pr_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Pr_Bill_Mst.Rt_Bill_Ser = Ias_Pr_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Pr_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND EXISTS
                     (SELECT 1
                        FROM Ias_Pi_Bill_Mst
                       WHERE     Bill_Ser = Ias_Pr_Bill_Dtl.Bill_Ser
                             AND NVL (Pur_type, 0) <> 2)
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Pr_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (2, 3, 4)
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO
    UNION ALL
      SELECT Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             (  DECODE (
                    NVL (Clc_Tax_Free_Qty_Flg, 0),
                    0, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * (  NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                              + NVL (Ias_Pr_Bill_Dtl.Free_Qty, 0))
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Vat_Amt,
             (  DECODE (
                    1,
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    2, SUM (
                             ((  NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                               - NVL (Ias_Pr_Bill_Dtl.Dis_Amt, 0)))
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Pr_Bill_Mst, Ias_Pr_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Pr_Bill_Mst.Rt_Bill_Ser = Ias_Pr_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Pr_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Pr_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (2, 3, 4)
             AND NVL (P_Year, 0) = 1
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO
    UNION ALL
      SELECT Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             (  DECODE (
                    NVL (Clc_Tax_Free_Qty_Flg, 0),
                    0, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * (  NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                              + NVL (Ias_Pr_Bill_Dtl.Free_Qty, 0))
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Vat_Amt,
             (  DECODE (
                    1,
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    2, SUM (
                             ((  NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                               - NVL (Ias_Pr_Bill_Dtl.Dis_Amt, 0)))
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Pr_Bill_Mst, Ias_Pr_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Pr_Bill_Mst.Rt_Bill_Ser = Ias_Pr_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Pr_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Pr_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (1, 0)
             AND NVL (Ias_Pr_Bill_Dtl.Vat_Per, 0) = 0
             AND NVL (P_Year, 0) IN (1, 0)
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO
    UNION ALL
      SELECT Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ys_Tax_Pkg.Get_Tax_Typ_No (Ias_Pr_Bill_Mst.Clc_Typ_No_Tax)
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             (  DECODE (
                    NVL (Clc_Tax_Free_Qty_Flg, 0),
                    0, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.Vat_Amt, 0)
                           * (  NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                              + NVL (Ias_Pr_Bill_Dtl.Free_Qty, 0))
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Vat_Amt,
             (  DECODE (
                    1,
                    1, SUM (
                             NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)),
                    2, SUM (
                             ((  NVL (Ias_Pr_Bill_Dtl.I_Price, 0)
                               - NVL (Ias_Pr_Bill_Dtl.Dis_Amt, 0)))
                           * NVL (Ias_Pr_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Pr_Bill_Mst.Rt_Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Pr_Bill_Mst, Ias_Pr_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Pr_Bill_Mst.Rt_Bill_Ser = Ias_Pr_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Pr_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND NVL (P_Year, 0) = 2
             AND Ys_Tax_Pkg.Get_Tax_Typ_No (Ias_Pr_Bill_Mst.Clc_Typ_No_Tax) <>
                 0
    GROUP BY Clc_Tax_Free_Qty_Flg,
             Ias_Pr_Bill_Mst.Rt_Bill_Ser,
             Ias_Pr_Bill_Mst.Rt_Bill_No,
             Ias_Pr_Bill_Mst.Rt_Bill_Date,
             Ias_Pr_Bill_Mst.Rt_Bill_Currency,
             Ias_Pr_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Pr_Bill_Mst.BRN_NO,
             Ias_Pr_Bill_Mst.CMP_NO;


--
-- GNR_TAX_RT_SALES_NO_VAT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_RT_SALES_NO_VAT_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 A_CY, CLC_TYP_NO_TAX, VAT_TYPE, VAT_AMT, DOC_AMT)
BEQUEATH DEFINER
AS 
SELECT Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO,
             Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
               SUM (
                     (  NVL (Ias_Rt_Bill_Dtl.Vat_Amt, 0)
                      + NVL (Ias_Rt_Bill_Dtl.Vat_Amt_Othr, 0))
                   * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                   * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1))
             * -1
                 Vat_Amt,
             DECODE (
                 1,
                 1, SUM (
                          NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)),
                 2, SUM (
                          (  (  NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                              - (  NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Mst, 0)
                                 + NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Dtl, 0)))
                           + (NVL (Ias_Rt_Bill_Dtl.Othr_Amt, 0)))
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)))
                 Bill_Amt
        FROM Ias_Rt_Bill_Mst, Ias_Rt_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Rt_Bill_Mst.Rt_Bill_Ser = Ias_Rt_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Rt_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Rt_Bill_Mst.CLC_TYP_NO_TAX) = 0
             AND NVL (Ias_Rt_Bill_Dtl.Vat_Per, 0) = 0
    GROUP BY Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO
    UNION ALL
      SELECT Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO,
             Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
               SUM (
                     (  NVL (Ias_Rt_Bill_Dtl.Vat_Amt, 0)
                      + NVL (Ias_Rt_Bill_Dtl.Vat_Amt_Othr, 0))
                   * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                   * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1))
             * -1
                 Vat_Amt,
             DECODE (
                 1,
                 1, SUM (
                          NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)),
                 2, SUM (
                          (  (  NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                              - (  NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Mst, 0)
                                 + NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Dtl, 0)))
                           + (NVL (Ias_Rt_Bill_Dtl.Othr_Amt, 0)))
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)))
                 Bill_Amt
        FROM Ias_Rt_Bill_Mst, Ias_Rt_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Rt_Bill_Mst.Rt_Bill_Ser = Ias_Rt_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Rt_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND NVL (P_Year, 0) = 1
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Rt_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (2, 3, 4)
             AND NVL (Ias_Rt_Bill_Dtl.Vat_Per, 0) = 0
             AND EXISTS
                     (SELECT 1
                        FROM Ias_Bill_Mst
                       WHERE     Bill_Ser = Ias_Rt_Bill_Dtl.Bill_Ser
                             AND NVL (Export, 0) <> 1)
    GROUP BY Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO
    UNION ALL
      SELECT Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO,
             Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
               SUM (
                     (  NVL (Ias_Rt_Bill_Dtl.Vat_Amt, 0)
                      + NVL (Ias_Rt_Bill_Dtl.Vat_Amt_Othr, 0))
                   * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                   * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1))
             * -1
                 Vat_Amt,
             DECODE (
                 1,
                 1, SUM (
                          NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)),
                 2, SUM (
                          (  (  NVL (Ias_Rt_Bill_Dtl.I_Price, 0)
                              - (  NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Mst, 0)
                                 + NVL (Ias_Rt_Bill_Dtl.Dis_Amt_Dtl, 0)))
                           + (NVL (Ias_Rt_Bill_Dtl.Othr_Amt, 0)))
                        * NVL (Ias_Rt_Bill_Dtl.I_Qty, 0)
                        * NVL (Ias_Rt_Bill_Mst.Rt_Bill_Rate, 1)))
                 Bill_Amt
        FROM Ias_Rt_Bill_Mst, Ias_Rt_Bill_Dtl, Ias_Itm_Mst
       WHERE     Ias_Rt_Bill_Mst.Rt_Bill_Ser = Ias_Rt_Bill_Dtl.Rt_Bill_Ser
             AND Ias_Rt_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Rt_Bill_Mst.CLC_TYP_NO_TAX) = 1
             AND EXISTS
                     (SELECT 1
                        FROM Ias_Bill_Mst
                       WHERE     Bill_Ser = Ias_Rt_Bill_Dtl.Bill_Ser
                             AND YS_TAX_PKG.GET_TAX_TYP_NO (
                                     Ias_Bill_Mst.CLC_TYP_NO_TAX) =
                                 1)
    GROUP BY Ias_Rt_Bill_Mst.Rt_Bill_Ser,
             Ias_Rt_Bill_Mst.Rt_Bill_No,
             Ias_Rt_Bill_Mst.Rt_Bill_Date,
             Ias_Rt_Bill_Mst.Rt_Bill_Currency,
             Ias_Rt_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Rt_Bill_Mst.BRN_NO,
             Ias_Rt_Bill_Mst.CMP_NO;


--
-- IAS_V_ALL_BILL_MST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ALL_BILL_MST
(BILL_TYPE, BILL_NO, BILL_SER, BILL_DOC_TYPE, CC_CODE, 
 W_CODE, SI_TYPE, BRN_NO)
BEQUEATH DEFINER
AS 
Select 2 Bill_type
		         ,Bill_no
		         ,Bill_ser
		         ,Bill_doc_type
		         ,Cc_code
		         ,W_code
		         ,Si_type
		         ,Brn_no
		   From   Ias_bill_mst
		   Union All
		   Select 1 Bill_type
		         ,Bill_no
		         ,Bill_ser
		         ,Bill_doc_type
		         ,Cc_code
		         ,W_code
		         ,Si_type
		         ,Brn_no
		   From   Ias_bill_mst_br;


--
-- IAS_V_ARS_UP_INSTALLMENT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ARS_UP_INSTALLMENT
(C_CODE, BILL_NO, BILL_SER, I_NO, I_AMT, 
 P_AMT, J_AMT)
BEQUEATH DEFINER
AS 
SELECT C_CODE , BILL_NO , BILL_SER , I_NO , I_AMT, NVL(P_AMT,0) P_AMT ,  NVL(J_AMT,0) J_AMT FROM (
													SELECT C_CODE , BILL_NO , BILL_SER , I_NO , SUM(I_AMT) I_AMT,SUM(P_AMT) P_AMT , SUM(J_AMT) J_AMT
													FROM (
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,(CASE WHEN NVL(I_PY,0) = 0 THEN INS.I_AMT ELSE 0 END) I_AMT,0 P_AMT, 0 J_AMT
													FROM INSTALLMENT INS
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy,Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.J_AMT),ABS(JV.J_AMT_F)) P_AMT, 0 J_AMT
													FROM INSTALLMENT INS, DETAIL_JOURNAL_V JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy,Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.AC_AMT),ABS(JV.AC_AMTF)) P_AMT, 0 J_AMT  
													FROM INSTALLMENT INS, VOUCHER_DETAIL JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,0 P_AMT, ABS(JV.PAID_AMT_DOC) J_AMT  
													FROM INSTALLMENT INS, IAS_ADJST_INSTALLMENT_DTL JV
													WHERE INS.C_CODE = JV.C_CODE
													AND INS.BILL_SER = JV.DOC_SER_REF
													AND INS.I_NO = JV.I_NO  UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,(CASE WHEN NVL(I_PY,0) = 0 THEN INS.I_AMT ELSE 0 END) I_AMT,0 P_AMT, 0 J_AMT
													FROM IAS20241.INSTALLMENT INS
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy, IAS20241.Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.J_AMT),ABS(JV.J_AMT_F)) P_AMT, 0 J_AMT
													FROM IAS20241.INSTALLMENT INS, IAS20241.DETAIL_JOURNAL_V JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy, IAS20241.Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.AC_AMT),ABS(JV.AC_AMTF)) P_AMT, 0 J_AMT  
													FROM IAS20241.INSTALLMENT INS, IAS20241.VOUCHER_DETAIL JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,0 P_AMT, ABS(JV.PAID_AMT_DOC) J_AMT  
													FROM IAS20241.INSTALLMENT INS, IAS20241.IAS_ADJST_INSTALLMENT_DTL JV
													WHERE INS.C_CODE = JV.C_CODE
													AND INS.BILL_SER = JV.DOC_SER_REF
													AND INS.I_NO = JV.I_NO UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,(CASE WHEN NVL(I_PY,0) = 0 THEN INS.I_AMT ELSE 0 END) I_AMT,0 P_AMT, 0 J_AMT
													FROM IAS20251.INSTALLMENT INS
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy, IAS20251.Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.J_AMT),ABS(JV.J_AMT_F)) P_AMT, 0 J_AMT
													FROM IAS20251.INSTALLMENT INS, IAS20251.DETAIL_JOURNAL_V JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,Decode(JV.A_Cy, IAS20251.Ias_Gen_Pkg.Get_Local_Cur,ABS(JV.AC_AMT),ABS(JV.AC_AMTF)) P_AMT, 0 J_AMT  
													FROM IAS20251.INSTALLMENT INS, IAS20251.VOUCHER_DETAIL JV
													WHERE INS.C_CODE = JV.AC_CODE_DTL
													AND INS.BILL_SER = JV.BILL_SER
													AND INS.I_NO = JV.I_NO
													UNION ALL
													SELECT INS.BILL_NO,INS.BILL_SER,INS.C_CODE,INS.I_NO I_NO,0,0 P_AMT, ABS(JV.PAID_AMT_DOC) J_AMT  
													FROM IAS20251.INSTALLMENT INS, IAS20251.IAS_ADJST_INSTALLMENT_DTL JV
													WHERE INS.C_CODE = JV.C_CODE
													AND INS.BILL_SER = JV.DOC_SER_REF
													AND INS.I_NO = JV.I_NO	)
													GROUP BY C_CODE , BILL_NO , BILL_SER ,I_NO )
													where 1 = 1;

COMMENT ON COLUMN IAS20261.IAS_V_ARS_UP_INSTALLMENT.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';



