--
-- IAS_V_BILL_MST_BR_SRL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_BILL_MST_BR_SRL
(DOC_SER)
BEQUEATH DEFINER
AS 
SELECT DOC_SER
			     FROM (  SELECT DOC_SER, COUNT (SERIALNO)
			               FROM IAS_ITEM_SERIALNO
			              WHERE DOC_TYPE = 1
			           GROUP BY DOC_SER
			           MINUS
			             SELECT BILL_SER, SUM (NVL (I_QTY, 0) + NVL (FREE_QTY, 0))
			               FROM IAS_BILL_DTL_BR
			              WHERE NVL (USE_SERIALNO, 0) = 1
			           GROUP BY BILL_SER);

COMMENT ON COLUMN IAS20261.IAS_V_BILL_MST_BR_SRL.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';



