--
-- IAS_V_CHK_ADJ_INSTLL_AR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_CHK_ADJ_INSTLL_AR
(ADJ_AMT, DOC_SER, I_NO, C_CODE, RCRD_NO, 
 I_PY)
BEQUEATH DEFINER
AS 
Select nvl(Sum(nvl(PAID_AMT_DOC,0)),0) Adj_amt,doc_ser_ref doc_ser,i_no,c_code,nvl(rcrd_no,0) Rcrd_no,nvl(i_py,0) i_py 
 From IAS_ADJST_INSTALLMENT_DTL
 group by doc_ser_ref,i_no,c_code,nvl(rcrd_no,0),nvl(i_py,0)
 minus
Select nvl(adj_amt,0),bill_ser,i_no,c_code,nvl(rcrd_no,0),nvl(i_py,0)  
  From Installment;

COMMENT ON COLUMN IAS20261.IAS_V_CHK_ADJ_INSTLL_AR.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.IAS_V_CHK_ADJ_INSTLL_AR.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';

COMMENT ON COLUMN IAS20261.IAS_V_CHK_ADJ_INSTLL_AR.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';



--
-- IAS_V_CHK_CPQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_CHK_CPQTY
(I_CODE, W_CODE, CP_QTY)
BEQUEATH DEFINER
AS 
Select tb1.I_code I_code,tb1.w_code w_code ,tb1.Cp_qty  From Ias_Itm_Wcode, 
		          (Select gr_detail.I_code,w_code, Nvl(sum(cp_qty),0) Cp_qty
		             From gr_detail
		            Group by gr_detail.I_code,w_code) tb1
            where Ias_Itm_Wcode.I_Code=tb1.I_Code
              and Ias_Itm_Wcode.w_code=tb1.w_code
              and Round(Nvl(Cp_qty,0),32)  <> Round(Nvl(avl_qty,0),32);

COMMENT ON COLUMN IAS20261.IAS_V_CHK_CPQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_CHK_CPQTY.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



