 C_PRICE, WT_UNT, WT_QTY, ARGMNT_NO, I_LENGTH, 
 I_WIDTH, I_HEIGHT, I_NUMBER, RCRD_NO, DOC_SEQUENCE, 
 DOC_TYPE_REF, DOC_NO_REF, DOC_SER_REF, DOC_SEQUENCE_REF, REC_ATTCH, 
 REM_QTY, REM_WT_QTY)
BEQUEATH DEFINER
AS 
Select Gr_Note.Gr_No             ,  
					              Gr_Note.G_Ser             ,
					              I_Code                    ,
					              Itm_Unt                   ,					              
					              I_Qty                     ,
					              P_Size                    ,
					              P_Qty                     ,
					              Gr_Note.W_Code Wh_Code    ,
					              Gr_Detail.W_Code W_Code   ,
					              Gr_Note.Cc_Code Cntr_No   ,
					              Gr_Detail.Cc_Code Cc_Code ,					              
							          Gr_Detail.Pj_No,
							          Gr_Detail.Actv_No,
					              Expire_Date               ,
					              Batch_No                  ,
					              C_Price                   ,
					              Wt_Unt,
												 Wt_Qty,
												 Argmnt_No,
												 I_Length,
												 I_Width,
												 I_Height,
												 I_Number	,
					              Gr_Detail.Rcrd_No,Gr_Detail.Doc_Sequence,
					              Doc_Type_Ref,Doc_No_Ref,Doc_Ser_Ref,Doc_Sequence_Ref ,Rec_Attch  ,
					   (Nvl (Sum (P_Qty/P_SIZE), 0) - (Select Nvl (Sum (P_Qty/P_SIZE), 0)
                        From   Ias_V_Pi_Bill_Dtl_Yr D
                        Where  D.Doc_Ser_Ref = Gr_Note.G_Ser
                        And    D.Doc_No_Ref = Gr_Note.Gr_No
                        And    D.I_Code =Gr_Detail.I_Code 
                        And    D.Doc_Sequence_Ref = Gr_Detail.Doc_Sequence ) ) Rem_Qty,
                        (Nvl (Sum (Wt_Qty), 0) - (Select Nvl (Sum (Wt_Qty), 0)
                        From   Ias_V_Pi_Bill_Dtl_Yr D
                        Where  D.Doc_Ser_Ref = Gr_Note.G_Ser
                        And    D.Doc_No_Ref = Gr_Note.Gr_No
                        And    D.I_Code =Gr_Detail.I_Code 
                        And    D.Doc_Sequence_Ref = Gr_Detail.Doc_Sequence ) ) Rem_Wt_Qty
             From  Ias_V_Gr_Note_Yr Gr_Note ,Ias_V_Gr_Detail_Yr Gr_Detail
                        Where Gr_Note.G_Ser=Gr_Detail.G_Ser  
          Having Nvl (Sum (P_Qty/P_SIZE), 0) - (Select Nvl (Sum (P_Qty/P_SIZE), 0)
                        From   Ias_V_Pi_Bill_Dtl_Yr D
                        Where  D.Doc_Ser_Ref = Gr_Note.G_Ser
                        And    D.Doc_No_Ref = Gr_Note.Gr_No
                        And    D.I_Code =Gr_Detail.I_Code 
                        And    D.Doc_Sequence_Ref = Gr_Detail.Doc_Sequence)  > 0                                        
                        Group By Gr_Note.Gr_No             ,  
					              Gr_Note.G_Ser             ,
					              I_Code                    ,
					              Itm_Unt                   ,					              
					              I_Qty                     ,
					              P_Size                    ,
					              P_Qty                     ,
					              Gr_Note.W_Code     ,
					              Gr_Detail.W_Code    ,
					              Gr_Note.Cc_Code    ,
					              Gr_Detail.Cc_Code  ,					              
							      Gr_Detail.Pj_No,
							      Gr_Detail.Actv_No,
					              Expire_Date               ,
					              Batch_No                  ,
					              C_Price                   ,
					              Wt_Unt,
							      Wt_Qty,
							      Argmnt_No,
							      I_Length,
							      I_Width,
							      I_Height,
							      I_Number	,
					              Gr_Detail.Rcrd_No,Gr_Detail.Doc_Sequence,
					              Doc_Type_Ref,Doc_No_Ref,Doc_Ser_Ref,Doc_Sequence_Ref ,Rec_Attch;

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_PI_INCOM.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_PI_INCOM.I_QTY IS '222 - «·ﬂ„Ì…';

