--
-- IAS_V_DIFF_WTAVG_ITM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_DIFF_WTAVG_ITM
(I_CODE, WT_AVG_AFTER)
BEQUEATH DEFINER
AS 
Select I_Code,
           Round(Avg(Nvl(Wt_Avg_After, 0)) Keep (Dense_Rank Last Order By Rec_No),(Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1 )) Wt_Avg_After 
    From Gr_Detail
    Where Rec_No= Rec_No*1
    	And Not Exists ( Select 1 From Gr_Note Where Gr_Note.G_Ser = Gr_Detail.G_Ser And Nvl(Gr_Note.Pi_Type,0) = 2 And Nvl(C_Flag,0) = 0 And Rownum <= 1)
    Group By I_Code
      Minus
    Select I_Code, 
           Round(Nvl(I_Cwtavg, 0), (Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1 ))  I_Cwtavg
    From Ias_Itm_Mst;

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_WTAVG_ITM.I_CODE IS '176 - —ﬁ„ «·’‰›';



--
-- IAS_V_DIFF_WTAVG_WCODE_ITM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_DIFF_WTAVG_WCODE_ITM
(I_CODE, W_CODE, WT_AVG_AFTER)
BEQUEATH DEFINER
AS 
Select I_Code,
           W_Code,
           Round(Avg(Nvl(Wt_Avg_After, 0)) Keep (Dense_Rank Last Order By Rec_No),(Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1 )) Wt_Avg_After 
    From Gr_Detail
    Where Rec_No  =Rec_No*1
    And Not Exists ( Select 1 From Gr_Note Where Gr_Note.G_Ser = Gr_Detail.G_Ser And Nvl(Gr_Note.Pi_Type,0) = 2 And Nvl(C_Flag,0) = 0 And Rownum <= 1)
    Group By I_Code ,W_Code
      Minus
    Select I_Code  ,
           W_Code  , 
           Round(Nvl(I_Cwtavg, 0), (Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1 )) I_Cwtavg 
    From Ias_Itm_Wcode;

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_WTAVG_WCODE_ITM.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_WTAVG_WCODE_ITM.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- IAS_V_DIFF_WTAVG_WHGCODE_ITM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_DIFF_WTAVG_WHGCODE_ITM
(I_CODE, WHG_CODE, WT_AVG_AFTER)
BEQUEATH DEFINER
AS 
Select Gr.I_Code,
           Gr.Whg_Code,
           Gr.Wt_Avg_After From (
        Select I_Code,
               Whg_Code,
               Round(Avg(Nvl(Wt_Avg_After, 0)) Keep (Dense_Rank Last Order By Rec_No),(Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1)) Wt_Avg_After 
    From Gr_Detail
      Where Rec_No = Rec_No*1
      And Not Exists ( Select 1 From Gr_Note Where Gr_Note.G_Ser = Gr_Detail.G_Ser And Nvl(Gr_Note.Pi_Type,0) = 2 And Nvl(C_Flag,0) = 0 And Rownum <= 1)
       Group By I_Code ,Whg_Code ) Gr ,
    (
    Select Distinct I_Code,
                    Whg_Code, 
                    Round(Nvl(I_Cwtavg, 0), (Select Stkcost_Fraction From Ias_Para_Inv Where Rownum <= 1 )) Wt_Avg_After
     From Ias_Itm_Wcode ) Wcode
    Where Gr.I_Code        = Wcode.I_Code 
    And   Gr.Whg_Code      = Wcode.Whg_Code 
    And   Gr.Wt_Avg_After <> Wcode.Wt_Avg_After;

COMMENT ON COLUMN IAS20261.IAS_V_DIFF_WTAVG_WHGCODE_ITM.I_CODE IS '176 - —ﬁ„ «·’‰›';



