--
-- IAS_V_ITMAGING_TMP  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITMAGING_TMP
(I_CODE, DOC_NO, DOC_TYPE, DOC_JV_TYPE, DOC_SER, 
 DOC_DATE, I_QTY, W_CODE, RCRD_NO, CC_CODE, 
 PER_NO, TRMNL_NAME, BRN_NO, BRN_YEAR, CMP_NO, 
 BRN_USR)
BEQUEATH DEFINER
AS 
SELECT I_Code,Gr_No,Pi_Type,Doc_jv_Type,G_Ser,Gr_Date,
       (CASE
            WHEN Out_Qty_Frm_Op_Stk = 0
            THEN
                cp_qty
            WHEN Prv_Cp_Qty - Out_Qty_Frm_Op_Stk < 0
            THEN
                0
            ELSE
                (CASE
                     WHEN Out_Qty_Frm_Op_Stk - Prv_Cp_Qty < 0
                     THEN
                         Prv_Cp_Qty - Out_Qty_Frm_Op_Stk
                     WHEN Out_Qty_Frm_Op_Stk - Prv_Cp_Qty = 0
                     THEN
                         0
                     ELSE
                         cp_qty
                 END)
        END)    Cp_Qty,W_Code,Rcrd_No,Cc_Code,Per_No,Trmnl_Name,Brn_No,Brn_Year,Cmp_No,Brn_Usr From (
SELECT I_Code,Gr_No,Pi_Type,Doc_jv_Type,G_Ser,Gr_Date,Cp_Qty,Prv_Cp_Qty,
               (CASE
                    WHEN   NVL (LAG (NVL (Prv_Cp_Qty, 0))
                                    OVER (PARTITION BY I_Code,
                                                       Expire_Date,
                                                       Batch_No,
                                                       W_Code
                                          ORDER BY Gr_Date,Rec_No),
                                0)
                         - Out_Qty_Frm_Op_Stk > 0
                    THEN
                        0
                    ELSE
                        Out_Qty_Frm_Op_Stk
                END)    Out_Qty_Frm_Op_Stk,W_Code,Rcrd_No,Cc_Code,Per_No,Trmnl_Name,Brn_No,Brn_Year,Cmp_No,Brn_Usr From (
Select I_Code,Gr_No,Pi_Type,Doc_jv_Type,G_Ser,Gr_Date,Cp_Qty,NVL (SUM (NVL (Cp_Qty, 0)) OVER (PARTITION BY I_Code,Expire_Date,Batch_No,W_Code ORDER BY Gr_Date,Rec_No),0) Prv_Cp_Qty, (Select Sum(Out_Qty) From (  Select Sum(Nvl(P_Qty,0) - Nvl(Cp_Qty,0)) Out_Qty From  IAS20251.Gr_Detail Where Pi_Type = 0 And i_code = b.i_code And W_Code = B.W_Code AND NVL (b.Expire_Date, '01/01/1900') = NVL (Expire_Date, '01/01/1900')
                        AND NVL (b.Batch_No, '0') = NVL (Batch_No, '0') Union All  Select Sum(Nvl(P_Qty,0) - Nvl(Cp_Qty,0)) Out_Qty From  IAS20261.Gr_Detail Where Pi_Type = 0 And i_code = b.i_code And W_Code = B.W_Code AND NVL (b.Expire_Date, '01/01/1900') = NVL (Expire_Date, '01/01/1900')
                        AND NVL (b.Batch_No, '0') = NVL (Batch_No, '0') Union All  Select 0 Out_Qty From GR_DETAIL Where Pi_Type = 0 And 1 = 2  )) Out_Qty_Frm_Op_Stk, W_Code,Rcrd_No,Cc_Code,Per_No,Trmnl_Name,Brn_No,Brn_Year,Cmp_No,Brn_Usr,Rec_No,Batch_No,Expire_Date From (     SELECT b.i_code,b.Gr_No,b.Pi_type,b.doc_jv_type,b.G_ser,b.Gr_date,b.Cp_Qty,b.W_Code,b.rcrd_no,b.cc_code,b.Per_no,b.Trmnl_Name,b.brn_no,b.brn_year,b.Cmp_No,b.BRN_Usr,b.brn_year||b.Rec_No Rec_No,b.Expire_Date,b.Batch_No FROM Ias_Itm_Mst a,IAS_ITMAGING_MOVMNT_TMP b Where a.I_Code = b.I_Code   And b.Brn_No Between '1' And '1' And Exists(Select i_code From Ias_V_List_Icode Where i_code=b.i_code ) And Nvl(a.Inactive,0) = Decode(2,2,Nvl(a.Inactive,0),2) 
	                 And gr_date<='02/06/2026' And b.w_code Between '121' And '121' And 
            Exists (
                   Select 1
                     From Privilege_gc
                       Where U_Id = 1
                        And G_Code = a.G_Code
                        And Nvl(View_Flag,0) = 1 
                         )
         ) b  Where Exists ( Select 1 From ias_Itm_Wcode  Where I_Code = b.I_Code And W_Code = B.W_Code And Nvl(Avl_Qty,0) > 0 ) ));

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.DOC_NO IS '292 - —ﬁ„ «·ÊÀÌﬁÂ';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.DOC_TYPE IS '38 - ‰Ê⁄ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.DOC_JV_TYPE IS '4016 - ‰Ê⁄ «·ÊÀÌﬁ… «· Õ·Ì·Ì';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.DOC_DATE IS '1137 -  «—ÌŒ «·ÊÀÌﬁ…';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.CC_CODE IS '728 - „—ﬂ“ «· ﬂ·›…';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.BRN_YEAR IS '41 - «·”‰…';

COMMENT ON COLUMN IAS20261.IAS_V_ITMAGING_TMP.CMP_NO IS '1583 - —ﬁ„ «·‘—ﬂ…';

