--
-- IAS_V_NY_GR_INCOMING_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_NY_GR_INCOMING_DTL
(INCOM_TYPE, INC_NO, INC_SER, I_CODE, I_QTY, 
 ITM_UNT, P_SIZE, P_QTY, W_CODE, RCRD_NO, 
 BARCODE, USE_ATTCH, REC_ATTCH, I_LENGTH, I_WIDTH, 
 I_HEIGHT, I_NUMBER, ITEM_DESC, CMP_NO, BRN_NO, 
 BRN_YEAR, BRN_USR, EXPIRE_DATE, BATCH_NO)
BEQUEATH DEFINER
AS 
SELECT q.incom_type, q.inc_no, q.inc_ser, q.i_code, mov_data.i_qty,
																														          q.itm_unt, q.p_size, (mov_data.i_qty * q.p_size) p_qty, q.w_code,
																														          q.rcrd_no, q.barcode, q.use_attch, q.rec_attch, q.i_length,
																														          q.i_width, q.i_height, q.i_number, q.item_desc, q.cmp_no, q.brn_no,
																														          q.brn_year, q.brn_usr,q.Expire_Date, q.Batch_No
																														   FROM   ias_gr_incoming_dtl q,
																														          (SELECT   doc_ser, i_code, itm_unt, SUM (NVL (i_qty, 0)) i_qty
																														           FROM     (SELECT inc_ser doc_ser, i_code, itm_unt,
																														                            NVL (i_qty, 0) i_qty
																														                     FROM   ias_gr_incoming_dtl
																														                     UNION ALL
																														                     SELECT    doc_ser_ref doc_ser, i_code, itm_unt,
																														                              SUM (NVL (i_qty, 0)) * -1 i_qty
																														                     FROM     Gr_Detail
																														                     WHERE    doc_type_ref = 32
																														                     AND      doc_ser_ref IS NOT NULL                                         
																														                     GROUP BY doc_ser_ref,
																														                              i_code,
																														                              itm_unt)
																														           GROUP BY doc_ser,
																														                    i_code,
																														                    itm_unt
																														           HAVING   SUM (NVL (i_qty, 0)) > 0) mov_data
																														   WHERE  q.inc_ser = mov_data.doc_ser
																														   AND    q.i_code = mov_data.i_code
																														   AND    q.itm_unt = mov_data.itm_unt
																														   AND    NVL (mov_data.i_qty, 0) >= 0;

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.CMP_NO IS '1583 - —ﬁ„ «·‘—ﬂ…';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.BRN_YEAR IS '41 - «·”‰…';

COMMENT ON COLUMN IAS20261.IAS_V_NY_GR_INCOMING_DTL.BRN_USR IS '3300 - «·ÊÕœ… «·„Õ«”»Ì…';



