           I.DOC_JV_TYPE_REF,
           I.DOC_NO_REF,
           I.DOC_SER_REF,
           I.DOC_SEQUENCE,
           I.EXTERNAL_POST,
           I.RCRD_NO,
           I.G_CODE,
           I.WHG_CODE,
           I.TRMNL_NAME,
           I.INSTALL_TYPE,
