           I.INSRNCE_RLTN_TYP,
           I.AUDIT_REF,
           I.AUDIT_REF_DESC,
           I.AUDIT_REF_U_ID,
           I.AUDIT_REF_DATE,
           I.CNFRM,
           I.CNFRM_DESC,
           I.CNFRM_U_ID,
           I.CNFRM_DATE,
           I.POST_U_ID,
           I.POST_DATE,
           I.UNPOST_U_ID,
           I.UNPOST_DATE,
           I.DOC_SEQUENCE_REF,
           I.RCRD_NO_REF,
           I.CRD_CARD_NO,
           I.CRD_CARD_NO_REF,
           I.CR_CARD_DSC,
           I.AD_U_ID,
           I.AD_DATE,
           I.UP_U_ID,
           I.UP_DATE,
           I.UP_CNT,
           I.CMP_NO,
           I.BRN_NO,
