           I.BRN_USR,
           I.DOC_NO_MNL,
           I.DOC_DATE_MNL,
           I.SCHEMA_NM,
           I.DOC_PST_SQ
      FROM IAS_V_POST_DTL_YR  I,
           (SELECT BILL_SER
                       DOC_SER,                                          
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM IAS_V_PI_BILL_MST_YR S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)          -- AND S.C_CODE IS NOT NULL
            UNION ALL
            SELECT RT_BILL_SER,                                          
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM IAS_V_PR_BILL_MST_YR S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)          -- AND S.C_CODE IS NOT NULL
            UNION ALL
            SELECT DOC_SER
                       DOC_SER,                                          
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM Ias_Pi_Bill_Mst_Add_Disc  S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)) N    -- AND S.C_CODE IS NOT NULL) N
     WHERE     I.DOC_TYPE IN (6, 7, 16)
           AND I.AC_DTL_TYP in(1,2)
           AND I.DOC_SER = N.DOC_SER
    UNION ALL
    SELECT I.DOC_TYPE,
           I.JV_TYPE,
           I.DOC_NO,
           I.DOC_SER,
           I.W_CODE,
           I.CC_CODE,
           I.PJ_NO,
           I.ACTV_NO,
           I.CASH_NO,
           NVL (N.V_A_CODE, I.A_CODE),
           NVL (N.AC_CODE_DTL, I.AC_CODE_DTL),
           I.AC_CODE_DTL_SUB,           
           NVL (N.AC_DTL_TYP, I.AC_DTL_TYP),
           I.A_CY,
           I.DR_AMT,
           I.CR_AMT,
           I.DR_AMT_F,
           I.CR_AMT_F,
           I.AMT,
           I.AMT_F,
           I.DOC_DATE,
           I.DOC_DUE_DATE,
           I.DOC_DESC,
           I.MNTH,
           I.D_YEAR,
           I.REF_NO,
           I.DOC_POST,
           I.DOC_CLOSE,
           I.INV_CLOSE,
           I.CB_BEFORE,
           I.CB_AFTER,
           I.LC_NO,
           I.C_CODE,
           I.AC_CODE_DTL,
           I.C_V_CODE,
           I.V_C_CODE,
           I.COL_NO,
           I.REP_CODE,
           I.CR_CARD_TYPE,
           I.R_CODE,
           I.HRCHY_NO,
           I.WO_NO,
           I.WO_SER,
           I.CHEQUE_NO,
           I.NOTE_NO,
           I.CHEQUE_VALUED,
           I.DOC_TYPE_REF,
           I.DOC_JV_TYPE_REF,
           I.DOC_NO_REF,
           I.DOC_SER_REF,
           I.DOC_SEQUENCE,
           I.EXTERNAL_POST,
           I.RCRD_NO,
           I.G_CODE,
           I.WHG_CODE,
           I.TRMNL_NAME,
           I.INSTALL_TYPE,
           I.MOV_DOC_PY,
           I.FROM_CC_CODE,
           I.F_BRN_NO,
           I.DOC_BRN_NO,
           I.CASHIER_NO,
           I.INSRNCE_CMP_NO,
           I.INSRNCE_BNF_NO,
           I.INSRNCE_CARD_NO,
           I.INSRNCE_CARD_NO_FMLY,
           I.INSRNCE_RLTN_TYP,
           I.AUDIT_REF,
           I.AUDIT_REF_DESC,
           I.AUDIT_REF_U_ID,
           I.AUDIT_REF_DATE,
           I.CNFRM,
           I.CNFRM_DESC,
           I.CNFRM_U_ID,
           I.CNFRM_DATE,
           I.POST_U_ID,
           I.POST_DATE,
           I.UNPOST_U_ID,
           I.UNPOST_DATE,
           I.DOC_SEQUENCE_REF,
           I.RCRD_NO_REF,
           I.CRD_CARD_NO,
           I.CRD_CARD_NO_REF,
           I.CR_CARD_DSC,
           I.AD_U_ID,
           I.AD_DATE,
           I.UP_U_ID,
           I.UP_DATE,
           I.UP_CNT,
           I.CMP_NO,
           I.BRN_NO,
           I.BRN_YEAR,
           I.BRN_USR,
           I.DOC_NO_MNL,
           I.DOC_DATE_MNL,
           I.SCHEMA_NM,
           I.DOC_PST_SQ
      FROM IAS_V_POST_DTL_YR  I,
           (SELECT BILL_SER
                       DOC_SER,               
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM IAS_V_PI_BILL_MST_YR S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)          -- AND S.C_CODE IS NOT NULL
            UNION ALL
            SELECT RT_BILL_SER,                   
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM IAS_V_PR_BILL_MST_YR S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)          -- AND S.C_CODE IS NOT NULL
            UNION ALL
            SELECT DOC_SER
                       DOC_SER,
                   C.V_A_CODE,
                   S.V_CODE
                       AC_CODE_DTL,
                   CASE WHEN S.V_CODE IS NOT NULL THEN 4 ELSE NULL END
                       AC_DTL_TYP
              FROM Ias_Pi_Bill_Mst_Add_Disc S, V_DETAILS C
             WHERE S.V_CODE = C.V_CODE(+)) N    -- AND S.C_CODE IS NOT NULL) N
     WHERE     I.DOC_TYPE IN (6, 7, 16)
           AND I.AC_DTL_TYP in(1,2)
           AND I.DOC_SER = N.DOC_SER;


--
-- IAS_V_PR_BILL_AMT_ERR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_PR_BILL_AMT_ERR
(RT_BILL_SER, RT_BILL_AMT, DISC_AMT)
BEQUEATH DEFINER
AS 
Select rt_bill_ser,round(nvl(bill_amt,0),3) bill_amt,round(nvl(disc_amt,0),3) disc_amt
   From Ias_Pr_Bill_Mst
  where rt_bill_ser Is Not Null
    and nvl(rt_bill_post,0)=0
 Minus
 Select rt_bill_ser,round(nvl(sum(nvl(i_qty,0)*nvl(i_price,0)),0),3),round(nvl(sum(nvl(i_qty,0)*nvl(dis_amt,0)),0),3)
   From Ias_Pr_Bill_Dtl
  where rt_bill_ser Is Not Null
    group by rt_bill_ser;


--
-- IAS_V_RT_BILL_AMT_ERR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_RT_BILL_AMT_ERR
(RT_BILL_SER, RT_BILL_AMT, DISC_AMT, OTHR_AMT)
BEQUEATH DEFINER
AS 
Select Rt_bill_ser,round(nvl(bill_amt,0),3) bill_amt,round(nvl(disc_amt,0),3) disc_amt,round(nvl(othr_amt,0),3) Othr_amt
   From IAS_RT_BILL_MST
  where Rt_bill_ser Is Not Null
    and nvl(Rt_bill_post,0)=0
 Minus
 Select Rt_bill_ser,round(nvl(sum(nvl(i_qty,0)*nvl(i_price,0)),0),3),round(nvl(sum(nvl(i_qty,0)*nvl(dis_amt,0)),0),3) ,
        round(nvl(sum(nvl(i_qty,0)*nvl(othr_amt,0)),0),3)
   From IAS_RT_BILL_DTL
  where Rt_bill_ser Is Not Null
    group by Rt_bill_ser;


