--
-- IAS_V_RT_BILL_DTL_OUT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_RT_BILL_DTL_OUT
(I_CODE, ITM_UNT, P_SIZE, W_CODE, EXPIRE_DATE, 
 BATCH_NO, I_QTY, FREE_QTY, RET_QTY, RET_FREE_QTY, 
 RT_BILL_DATE)
BEQUEATH DEFINER
AS 
Select D.I_code,D.Itm_Unt,D.P_Size,D.W_Code,D.Expire_Date,D.Batch_No,D.I_Qty,D.Free_Qty,D.Ret_Qty,D.Ret_Free_Qty ,M.Rt_Bill_Date 
                From Ias_Rt_Bill_Mst M,Ias_Rt_Bill_Dtl D
               Where M.Rt_Bill_Ser = D.Rt_Bill_Ser
                 And Nvl(M.P_year,0)<>3;

COMMENT ON COLUMN IAS20261.IAS_V_RT_BILL_DTL_OUT.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_RT_BILL_DTL_OUT.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.IAS_V_RT_BILL_DTL_OUT.I_QTY IS '222 - «·ﬂ„Ì…';



--
-- IAS_V_RT_BILL_MST_BR_SRL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_RT_BILL_MST_BR_SRL
(DOC_SER)
BEQUEATH DEFINER
AS 
SELECT DOC_SER
			     FROM (  SELECT DOC_SER, COUNT (SERIALNO)
			               FROM IAS_ITEM_SERIALNO
			              WHERE DOC_TYPE = 3
			           GROUP BY DOC_SER
			           MINUS
			             SELECT RT_BILL_SER, SUM (NVL (I_QTY, 0) + NVL (FREE_QTY, 0))
			               FROM IAS_RT_BILL_DTL_BR
			              WHERE NVL (USE_SERIALNO, 0) = 1
			           GROUP BY RT_BILL_SER);

COMMENT ON COLUMN IAS20261.IAS_V_RT_BILL_MST_BR_SRL.DOC_SER IS '757 - «·„› «Õ «·√”«”Ì';



--
-- IAS_V_SALE1  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_SALE1
(ORDER_NO, ORDER_DATE, C_CODE, I_CODE, I_NAME, 
 ITM_UNT, I_QTY, I_PRICE, AMOUNT)
BEQUEATH DEFINER
AS 
Select a.Order_no,a.Order_date,a.c_code,b.i_code,c.i_name,b.Itm_Unt,b.i_qty,b.I_price, b.I_qty * b.I_price Amount From
							Sales_Order a,Order_detail b,Ias_Itm_Mst c 
							where	a.Order_no = b.Order_no and b.i_code = c.i_code;

COMMENT ON COLUMN IAS20261.IAS_V_SALE1.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';

COMMENT ON COLUMN IAS20261.IAS_V_SALE1.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_SALE1.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_SALE1.I_PRICE IS '230 - «·”⁄—';



