AS 
Select a.Order_no,a.Order_date,a.c_code,a.c_name,a.procesed,a.order_cur ,
		                 b.i_code,c.i_name,b.Itm_Unt,b.i_qty,b.i_price, a.disc_amt,b.I_qty * b.i_price Amount 
		            From Sales_Order a,Order_detail b,Ias_Itm_Mst c 
		           Where a.Order_no = b.Order_no 
		             and b.i_code = c.i_code;

COMMENT ON COLUMN IAS20261.IAS_V_SALE3.C_CODE IS '388 - —ﬁ„ «·⁄„Ì·';

COMMENT ON COLUMN IAS20261.IAS_V_SALE3.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_SALE3.I_QTY IS '222 - «·ﬂ„Ì…';

COMMENT ON COLUMN IAS20261.IAS_V_SALE3.I_PRICE IS '230 - «·”⁄—';



--
-- IAS_V_SM_MOVE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_SM_MOVE
(REP_CODE, BILL_TYPE, BILL_NO, T_NAME, BILL_DATE, 
 C_NAME, BILL_CURRENCY, BILL_AMT, COMM_AMT)
BEQUEATH DEFINER
AS 
Select REP_CODE,
				       Ias_Gen_Pkg.Get_Prompt(1,118)  bill_type ,
				       bill_no,
				       Flg_Desc T_name,
				       bill_date,
				       c_name,
				       bill_currency, 
				       (nvl(BILL_AMT,0)-nvl(DISC_AMT,0)) billamt,
				       (((nvl(BILL_AMT,0)-nvl(DISC_AMT,0))*nvl(COMM_PER,0))/100) COMM_AMT 
				from 
				      Ias_bill_Mst,s_flags
				where 
				      Ias_bill_Mst.bill_doc_type=S_FLAGS.FLG_VALUE  
					and S_FLAGS.FLG_CODE='TYPE_NAME_SI'
					and S_FLAGS.Lang_no=1
					and rep_code is not null
					and rep_code=151
				Union all
				Select Rep_Code,
				       Ias_Gen_Pkg.Get_Prompt(1,121) bill_type ,
				       rt_BILL_NO bill_no ,
				       FLG_DESC T_name, 
				       rt_BILL_DATE bill_date, 
				       c_name,
				       rt_BILL_CURRENCY bill_currency, 
				       ((nvl(BILL_AMT,0)-nvl(DISC_AMT,0))*-1) billamt,
				      ((((nvl(BILL_AMT,0)-nvl(DISC_AMT,0))*nvl(COMM_PER,0))/100)*-1) COMM_AMT
				 from Ias_rt_bill_Mst,s_flags
				where Ias_rt_bill_Mst.rt_bill_doc_type=S_FLAGS.FLG_VALUE  
					and S_FLAGS.FLG_CODE='TYPE_NAME'
					and S_FLAGS.Lang_no=1
					and rep_code is not null
					and rep_code=151;


--
-- IAS_V_SOQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_SOQTY
(ORDER_NO, I_CODE, I_QTY)
BEQUEATH DEFINER
AS 
SELECT Order_detail.ORDER_NO, Order_detail.i_code, Sum(i_qty) i_qty
FROM  Order_detail 
GROUP BY Order_detail.Order_no, Order_detail.i_code;

COMMENT ON COLUMN IAS20261.IAS_V_SOQTY.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.IAS_V_SOQTY.I_QTY IS '222 - «·ﬂ„Ì…';



--
-- INV_V_PRV_ITM_AGE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_PRV_ITM_AGE
(I_CODE, W_CODE, ITM_AGE)
BEQUEATH DEFINER
AS 
Select b.i_code,
        b.W_Code W_Code,
        Sum(Decode(b.doc_type,0,Nvl(Itm_Age,0)+(Ias_Gen_Pkg.Get_Sysdate - b.gr_date),(Ias_Gen_Pkg.Get_Sysdate
- b.gr_date))) Itm_Age
         From (
                With Adj_Sale_Cost (Bill_Type,Pi_Type,Doc_No,Doc_Ser,Gr_Date,I_Code,W_Code,P_Qty,Doc_Sequence,Gr_No,G_Ser,
Doc_Sequence_Gr,Rec_no,rcrd_no,cc_code,Itm_Age,TERMINAL,Brn_No,brn_year,Cmp_No,BRN_Usr,Expire_Date,Batch_No) As
                                    (
                                        Select Sl.Bill_Type,Gr.Pi_Type,Sl.Bill_No Doc_No, to_char(Sl.Doc_Ser) Doc_ser,
Gr.Gr_Date,Gr.I_Code,Gr.W_Code
                                            ,(Nvl(Sl.I_Qty,0) * Nvl(Sl.P_Size,0)) P_Qty,Gr.Doc_Sequence,Sl.Gr_No,Sl.G_Ser,
Sl.Doc_Sequence_Gr,Sl.Rec_no ,
                                            Gr.rcrd_no,Gr.cc_code,Gr.Itm_Age,
                                            Null TERMINAL,
                                            Gr.brn_no,
                                            Gr.brn_year,
                                            Gr.Cmp_No,
                                            Gr.BRN_Usr,
                                            Gr.Expire_Date,
                                            Gr.Batch_No  
                                        From  Gr_Detail Gr,  Sale_Cost Sl
                                        Where Gr.Gr_No = Sl.Gr_No
                                          And Gr.G_Ser = Sl.G_Ser
                                          And Gr.Doc_Sequence = Sl.Doc_Sequence_Gr
                                          And Sl.Bill_Type = 18
                                          And Sl.Pi_Type <> 17
                                        Order by Sl.Doc_Sequence
                                    ) 
                select  I_Code
                       ,Gr_No doc_no
                       ,Pi_type doc_type
                       ,Null doc_jv_type
                       ,Doc_Ser
                       ,Gr_Date
                       ,P_Qty
                       ,W_Code
                       ,rcrd_no
                       ,cc_code
                       ,Itm_Age
                       ,Null TERMINAL
                       ,brn_no
                       ,brn_year
                       ,Cmp_No
                       ,BRN_Usr  
                       ,Expire_Date
                       ,Batch_No
                       ,Doc_Sequence 
                from Adj_Sale_Cost
                Union All
                Select i_code
                       ,gr_no doc_No
                       ,pi_type doc_type
                       ,Null doc_jv_type 
                       ,to_char(g_ser) doc_ser
                       ,gr_date doc_date
                       ,Nvl((NVL(I_Qty,0)+NVL(free_qty,0))*P_Size,0) P_Qty
                       ,W_Code
                       ,rcrd_no
                       ,cc_code
                       ,Itm_Age
                       ,Null TERMINAL
                       ,brn_no
                       ,brn_year
                       ,Cmp_No
                       ,BRN_Usr 
                       ,Expire_Date
                       ,Batch_No  
                       ,Doc_Sequence
                From  Gr_Detail Gr_D
                Where Pi_Type <> 17
                      And Nvl(Cp_Qty,0) > 0
                      And Not Exists (Select 1 from Gr_note
                                            where Gr_note.G_ser=Gr_D.G_ser
                                              And Gr_note.C_Flag=0
                                              And Gr_note.Pi_Type=2
                                              And Rownum<=1 ) 
                ) B , Ias_Itm_Mst a
                WHere a.I_Code = b.I_Code 
                  And gr_date<= Ias_Gen_Pkg.Get_Sysdate
                Group by b.I_Code,W_COde
                Order by b.I_Code,W_COde;

COMMENT ON COLUMN IAS20261.INV_V_PRV_ITM_AGE.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.INV_V_PRV_ITM_AGE.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';



--
-- SALES_BILL_MST_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SALES_BILL_MST_AI_VW
(TYP_NO, DOC_NO, DOC_SRL, DOC_DATE, MNL_DATE, 
 CUR_CODE, CUR_RATE, STK_RATE, WRHS_CODE, UNT_NO, 
 PYMNT_CSH, PYMNT_BNK, PYMNT_CRDT, PYMNT_CPN, PYMNT_AC, 
 PYMNT_POINT_RPLC, PYMNT_RPLC, CSTMR_CODE, CSTMR_NM, CSTMR_MOBILE, 
 AC_CODE_DTL_SUB_CST, CSH_CODE, BNK_CODE, AC_CODE_DTL_SUB_BNK, AC_CODE, 
 AC_CODE_DTL, AC_DTL_TYP, AC_CODE_DTL_SUB, CSH_AMT, BNK_AMT, 
 CRDT_AMT, CPN_AMT, AC_AMT, RPLC_AMT, POINT_AMT_RPLC, 
 DOC_AMT, DSCNT_AMT, OTHR_AMT, TAX_AMT, DSCNT_AMT_ADD, 
 CSH_AMT_LOCAL, BNK_AMT_LOCAL, CRDT_AMT_LOCAL, CPN_AMT_LOCAL, AC_AMT_LOCAL, 
 RPLC_AMT_LOCAL, POINT_AMT_RPLC_LOCAL, TOTL_BILL_AMT, TOTL_BILL_AMT_LOCAL, SMAN_CODE, 
 MRKTR_CODE, CLCTR_CODE, EMP_CODE, DRVR_NO, RGN_NO, 
 SUB_LDGR1_CODE, SUB_LDGR2_CODE, SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, 
 SUB_LDGR6_CODE, TAX_CODE, DOC_DUE_DATE, DOC_DSC, REF_NO, 
 MNL_NO, CHQ_NOTE_NO, CHQ_NOTE_DATE, COMM_PRCNT, TAX_CTGRY_NO, 
 TAX_BILL_TYP, CLC_TAX_FREE_QTY_FLG, VRFY_FLG, STNDBY_FLG, PST_FLG, 
 YR_NO, CRT_USR, CRT_DATE)
BEQUEATH DEFINER
AS 
SELECT SI_TYPE
               TYP_NO,
           BILL_NO
               DOC_NO,
           BILL_SER
               DOC_SRL,
           BILL_DATE
               DOC_DATE,
           BILL_DATE
               MNL_DATE,
           BILL_CURRENCY
               CUR_CODE,
           BILL_RATE
               CUR_RATE,
           STOCK_RATE
               STK_RATE,
           W_CODE
               WRHS_CODE,
           BRN_NO
               UNT_NO,
           (CASE WHEN BILL_DOC_TYPE = 1 THEN 1 ELSE 0 END)
               PYMNT_CSH,
           (CASE
                WHEN BILL_DOC_TYPE IN (2,
                                       3,
                                       5,
                                       6)
                THEN
                    1
                ELSE
                    0
            END)
               PYMNT_BNK,
           (CASE WHEN BILL_DOC_TYPE = 4 THEN 1 ELSE 0 END)
               PYMNT_CRDT,
           (CASE WHEN BILL_DOC_TYPE = 7 THEN 1 ELSE 0 END)
               PYMNT_CPN,
           (CASE WHEN BILL_DOC_TYPE = 8 THEN 1 ELSE 0 END)
               PYMNT_AC,
           0
               PYMNT_POINT_RPLC,
           0
               PYMNT_RPLC,
           C_CODE
               CSTMR_CODE,
           C_NAME
               CSTMR_NM,
           MOBILE_NO
               CSTMR_MOBILE,
           NULL
               AC_CODE_DTL_SUB_CST,
           (CASE WHEN BILL_DOC_TYPE = 1 THEN CASH_NO ELSE NULL END)
               CSH_CODE,
           (CASE
                WHEN BILL_DOC_TYPE IN (2,
                                       3,
                                       5,
                                       6)
                THEN
                    CASH_NO
                ELSE
                    NULL
            END)
               BNK_CODE,
           NULL
               AC_CODE_DTL_SUB_BNK,
           AC_CODE,
           AC_CODE_DTL,
           AC_DTL_TYP,
           NULL
               AC_CODE_DTL_SUB,
           (CASE
                WHEN BILL_DOC_TYPE = 1
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               CSH_AMT,
           (CASE
                WHEN BILL_DOC_TYPE IN (2,
                                       3,
                                       5,
                                       6)
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               BNK_AMT,
           (CASE
                WHEN BILL_DOC_TYPE = 4
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               CRDT_AMT,
           (CASE
                WHEN BILL_DOC_TYPE = 7
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               CPN_AMT,
           (CASE
                WHEN BILL_DOC_TYPE = 8
                THEN
                    (  BILL_AMT
                     - NVL (DISC_AMT, 0)
                     + NVL (OTHR_AMT, 0)
                     + NVL (VAT_AMT, 0)
                     - NVL (DISC_AMT_AFTR_VAT, 0))
                ELSE
                    0
            END)
               AC_AMT,
           0
               RPLC_AMT,
           0
               POINT_AMT_RPLC,
           NVL (BILL_AMT, 0)
               DOC_AMT,
           NVL (DISC_AMT, 0)
               DSCNT_AMT,
           NVL (OTHR_AMT, 0)
               OTHR_AMT,
           NVL (VAT_AMT, 0)
               TAX_AMT,
           (NVL (ADD_DISC_AMT_MST, 0) + NVL (ADD_DISC_AMT_DTL, 0))
               DSCNT_AMT_ADD,
           (  (CASE
                   WHEN BILL_DOC_TYPE = 1
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * BILL_RATE)
               CSH_AMT_LOCAL,
           (  (CASE
                   WHEN BILL_DOC_TYPE IN (2,
                                          3,
                                          5,
                                          6)
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * BILL_RATE)
               BNK_AMT_LOCAL,
           (  (CASE
                   WHEN BILL_DOC_TYPE = 4
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * BILL_RATE)
               CRDT_AMT_LOCAL,
           (  (CASE
                   WHEN BILL_DOC_TYPE = 7
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * BILL_RATE)
               CPN_AMT_LOCAL,
           (  (CASE
                   WHEN BILL_DOC_TYPE = 8
                   THEN
                       (  BILL_AMT
                        - NVL (DISC_AMT, 0)
                        + NVL (OTHR_AMT, 0)
                        + NVL (VAT_AMT, 0)
                        - NVL (DISC_AMT_AFTR_VAT, 0))
                   ELSE
                       0
               END)
            * BILL_RATE)
               AC_AMT_LOCAL,
           0
               RPLC_AMT_LOCAL,
           0
               POINT_AMT_RPLC_LOCAL,
           (  BILL_AMT
            - NVL (DISC_AMT, 0)
            + NVL (OTHR_AMT, 0)
            + NVL (VAT_AMT, 0)
            - NVL (DISC_AMT_AFTR_VAT, 0))
               TOTL_BILL_AMT,
           (  (  BILL_AMT
               - NVL (DISC_AMT, 0)
               + NVL (OTHR_AMT, 0)
               + NVL (VAT_AMT, 0)
               - NVL (DISC_AMT_AFTR_VAT, 0))
            * BILL_RATE)
               TOTL_BILL_AMT_LOCAL,
           REP_CODE
               SMAN_CODE,
           PRM_CODE
               MRKTR_CODE,
           COL_NO
               CLCTR_CODE,
           EMP_NO
               EMP_CODE,
           DRIVER_NO
               DRVR_NO,
           R_CODE
               RGN_NO,
           CC_CODE
               SUB_LDGR1_CODE,
           PJ_NO
               SUB_LDGR2_CODE,
           ACTV_NO
               SUB_LDGR3_CODE,
           NULL
               SUB_LDGR4_CODE,
           NULL
               SUB_LDGR5_CODE,
           NULL
               SUB_LDGR6_CODE,
           C_TAX_CODE
               TAX_CODE,
           BILL_DUE_DATE
               DOC_DUE_DATE,
           A_DESC
               DOC_DSC,
           REF_NO,
           NULL
               MNL_NO,
           CHEQUE_NO
               CHQ_NOTE_NO,
           CHEQUE_DUE_DATE
               CHQ_NOTE_DATE,
           COMM_PER
               COMM_PRCNT,
           CLC_TYP_NO_TAX
               TAX_CTGRY_NO,
           TAX_BILL_TYP,
           CLC_TAX_FREE_QTY_FLG,
           AUDIT_REF
               VRFY_FLG,
           STAND_BY
               STNDBY_FLG,
           BILL_POST
               PST_FLG,
           BRN_YEAR
               YR_NO,
           AD_U_ID
               CRT_USR,
           AD_DATE
               CRT_DATE
      FROM IAS_BILL_MST;

COMMENT ON COLUMN IAS20261.SALES_BILL_MST_AI_VW.CSTMR_MOBILE IS '770 - —ﬁ„ «·ÃÊ«·';



--
-- SALES_RT_BILL_DTL_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SALES_RT_BILL_DTL_AI_VW
(DOC_NO, DOC_SRL, ITM_CODE, ITM_UNT, ITM_SZ, 
 WRHS_CODE, EXP_DATE, ITM_SGMNT_CNTCT, ITM_QTY, ITM_FREE_QTY, 
 ITM_FREE_QTY_ADD, ITM_TOTL_QTY, ITM_TOTL_FREE_QTY, ITM_MN_QTY, ITM_MN_FREE_QTY, 
 ITM_MN_FREE_QTY_ADD, ITM_TOTL_MN_QTY, ITM_MN_TOTL_MN_FREE_QTY, ITM_PRICE, ITM_STK_CST, 
 ITM_TAX_PRCNT, ITM_TAX_AMT, ITM_OTHR_CHRG_AMT, ITM_DSCNT_AMT, ITM_DSCNT_AMT_ADD, 
 ITM_TOTL_PRICE, ITM_TOTL_DSCNT_AMT, ITM_TOTL_OTHR_CHRG_AMT, ITM_TOTL_TAX_AMT, ITM_TOTL_DSCNT_AMT_ADD, 
 ITM_TOTL_AMT, ITM_TOTL_STK_CST, ITM_TOTL_PRICE_LOCAL, ITM_TOTL_DSCNT_AMT_LOCAL, ITM_TOTL_OTHR_AMT_LOCAL, 
 ITM_TOTL_TAX_AMT_LOCAL, ITM_DSCNT_AMT_ADD_LOCAL, ITM_TOTL_AMT_LOCAL, SUB_LDGR1_CODE, SUB_LDGR2_CODE, 
 SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, SUB_LDGR6_CODE, DOC_NO_REF_BILL, 
 DOC_SRL_REF_BILL, EMP_CODE, SRVC_FLG, DOC_D_SQ, UNT_NO, 
 YR_NO)
BEQUEATH DEFINER
AS 
SELECT D.RT_BILL_NO
               DOC_NO,
           D.RT_BILL_SER
               DOC_SRL,
           D.I_CODE
               ITM_CODE,
           D.ITM_UNT,
           D.P_SIZE
               ITM_SZ,
           D.W_CODE
               WRHS_CODE,
           D.EXPIRE_DATE
               EXP_DATE,
           D.BATCH_NO
               ITM_SGMNT_CNTCT,
           NVL (D.I_QTY, 0)
               ITM_QTY,
           NVL (D.FREE_QTY, 0)
               ITM_FREE_QTY,
           0
               ITM_FREE_QTY_ADD,
           (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
               ITM_TOTL_QTY,
           NVL (D.FREE_QTY, 0)
               ITM_TOTL_FREE_QTY,
           NVL (D.P_QTY, 0)
               ITM_MN_QTY,
           (NVL (D.FREE_QTY, 0) * P_SIZE)
               ITM_MN_FREE_QTY,
           0
               ITM_MN_FREE_QTY_ADD,
           ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * P_SIZE)
               ITM_TOTL_MN_QTY,
           (NVL (D.FREE_QTY, 0) * P_SIZE)
               ITM_MN_TOTL_MN_FREE_QTY,
           NVL (D.I_PRICE, 0)
               ITM_PRICE,
           NVL (D.STK_COST, 0)
               ITM_STK_CST,
           NVL (D.VAT_PER, 0)
               ITM_TAX_PRCNT,
           NVL (D.VAT_AMT, 0)
               ITM_TAX_AMT,
           NVL (D.OTHR_AMT, 0)
               ITM_OTHR_CHRG_AMT,
           NVL (D.DIS_AMT, 0)
               ITM_DSCNT_AMT,
           NVL (D.ADD_DIS_AMT, 0)
               ITM_DSCNT_AMT_ADD,
           (NVL (D.I_QTY, 0) * NVL (D.I_PRICE, 0))
               ITM_TOTL_PRICE,
           (NVL (D.I_QTY, 0) * NVL (D.DIS_AMT, 0))
               ITM_TOTL_DSCNT_AMT,
           (NVL (D.I_QTY, 0) * NVL (D.OTHR_AMT, 0))
               ITM_TOTL_OTHR_CHRG_AMT,
           (NVL (D.I_QTY, 0) * NVL (D.VAT_AMT, 0))
               ITM_TOTL_TAX_AMT,
           (NVL (D.I_QTY, 0) * NVL (D.ADD_DIS_AMT, 0))
               ITM_TOTL_DSCNT_AMT_ADD,
           (  NVL (D.I_QTY, 0)
            * (  NVL (D.I_PRICE, 0)
               - NVL (D.DIS_AMT, 0)
               + NVL (D.OTHR_AMT, 0)
               + NVL (D.VAT_AMT, 0)
               - NVL (D.DIS_AFTR_VAT_MST, 0)))
               ITM_TOTL_AMT,
           ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0))
               ITM_TOTL_STK_CST,
           (NVL (D.I_QTY, 0) * NVL (D.I_PRICE, 0) * M.RT_BILL_RATE)
               ITM_TOTL_PRICE_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.DIS_AMT, 0) * M.RT_BILL_RATE)
               ITM_TOTL_DSCNT_AMT_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.OTHR_AMT, 0) * M.RT_BILL_RATE)
               ITM_TOTL_OTHR_AMT_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.VAT_AMT, 0) * M.RT_BILL_RATE)
               ITM_TOTL_TAX_AMT_LOCAL,
           ((NVL (D.I_QTY, 0) * NVL (D.ADD_DIS_AMT, 0)) * M.RT_BILL_RATE)
               ITM_DSCNT_AMT_ADD_LOCAL,
           (  NVL (D.I_QTY, 0)
            * (  NVL (D.I_PRICE, 0)
               - NVL (D.DIS_AMT, 0)
               + NVL (D.OTHR_AMT, 0)
               + NVL (D.VAT_AMT, 0)
               - NVL (D.DIS_AFTR_VAT_MST, 0))
            * M.RT_BILL_RATE)
               ITM_TOTL_AMT_LOCAL,
           D.CC_CODE
               SUB_LDGR1_CODE,
           D.PJ_NO
               SUB_LDGR2_CODE,
           D.ACTV_NO
               SUB_LDGR3_CODE,
           NULL
               SUB_LDGR4_CODE,
           NULL
               SUB_LDGR5_CODE,
           NULL
               SUB_LDGR6_CODE,
           D.BILL_NO
               DOC_NO_REF_BILL,
           D.BILL_SER
               DOC_SRL_REF_BILL,
           D.EMP_NO
               EMP_CODE,
           D.SERVICE_ITEM
               SRVC_FLG,
           D.DOC_SEQUENCE
               DOC_D_SQ,
           D.BRN_NO
               UNT_NO,
           D.BRN_YEAR
               YR_NO
      FROM IAS_RT_BILL_MST M, IAS_RT_BILL_DTL D
     WHERE M.RT_BILL_SER = D.RT_BILL_SER;


--
-- V_GNR_RQ_TAX_ITM_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.V_GNR_RQ_TAX_ITM_MOVMNT
(DOC_TYPE, BILL_DOC_TYPE, DOC_JV_TYPE, DOC_NO, DOC_SER, 
 DOC_DATE, TAX_NO, CLC_TYP_NO, AGNCY_NO, I_CODE, 
 ITM_UNT, P_SIZE, I_PRICE, DISC_AMT, A_CODE, 
 A_CY, AC_RATE, TAX_PRCNT, TAX_AMT, W_CODE, 
 CC_CODE, PJ_NO, ACTV_NO, RCRD_NO, DOC_SEQUENCE, 
 EXTERNAL_POST, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 TAX_AMT_L, I_QTY, FREE_QTY, REF_NO)
BEQUEATH DEFINER
AS 
SELECT 52, m.quot_doc_type, m.qt_type, m.quot_no doc_no,
          m.quot_ser doc_ser, m.quot_date doc_date, td.tax_no,
          m.clc_typ_no_tax, td.agncy_no, d.i_code, d.itm_unt, d.p_size,
          d.i_price, d.dis_amt, td.ac_code_ar, m.quot_cur a_cy,
          ias_gen_pkg.get_cur_rate (m.quot_cur) ac_rate,
          NVL (d.vat_per, 0) tax_prcnt, NVL (d.vat_amt, 0) tax_amt,
          d.w_code w_code, m.cc_code cc_code, m.pj_no pj_no,
          m.actv_no actv_no, rcrd_no, d.doc_sequence,
          d.external_post external_post, m.cmp_no, m.brn_no, m.brn_year,
          m.brn_usr,
          NVL (d.vat_amt, 0)
          * ias_gen_pkg.get_cur_rate (m.quot_cur) tax_amt_l, d.i_qty,
          d.free_qty, m.ref_no
     FROM quotation m,
          quotation_detail d,
          gnr_tax_typ_clc_dtl tc,
          gnr_tax_code_dtl td,
          gnr_tax_typ_clc_brn brn
    WHERE m.quot_ser = d.quot_ser
      AND brn.clc_typ_no = tc.clc_typ_no
      AND brn.brn_no = m.brn_no
      AND m.clc_typ_no_tax = tc.clc_typ_no
      AND tc.tax_no = td.tax_no
      AND NVL (d.vat_amt, 0) > 0
   UNION
   SELECT 53, m.bill_doc_type, m.so_type, m.order_no doc_no,
          m.order_ser doc_ser, m.order_date doc_date, td.tax_no,
          m.clc_typ_no_tax, td.agncy_no, d.i_code, d.itm_unt, d.p_size,
          d.i_price, d.dis_amt, td.ac_code_ar, m.order_cur a_cy,
          ias_gen_pkg.get_cur_rate (m.order_cur) ac_rate,
          NVL (d.vat_per, 0) tax_prcnt, NVL (d.vat_amt, 0) tax_amt,
          d.w_code w_code, d.cc_code cc_code, m.pj_no pj_no,
          m.actv_no actv_no, rcrd_no, d.doc_seq,
          d.external_post external_post, m.cmp_no, m.brn_no, m.brn_year,
          m.brn_usr,
            NVL (d.vat_amt, 0)
          * ias_gen_pkg.get_cur_rate (m.order_cur) tax_amt_l, d.i_qty,
          d.free_qty, m.ref_doc_no
     FROM sales_order m,
          order_detail d,
          gnr_tax_typ_clc_dtl tc,
          gnr_tax_code_dtl td,
          gnr_tax_typ_clc_brn brn
    WHERE m.order_ser = d.order_ser
      AND brn.clc_typ_no = tc.clc_typ_no
      AND brn.brn_no = m.brn_no
      AND m.clc_typ_no_tax = tc.clc_typ_no
      AND tc.tax_no = td.tax_no
      AND NVL (d.vat_amt, 0) > 0
   UNION
   SELECT 42, NULL bill_doc_type, m.po_type, m.po_no doc_no, m.po_ser doc_ser,
          m.po_date doc_date, td.tax_no, m.clc_typ_no_tax, td.agncy_no,
          d.i_code, d.itm_unt, d.p_size, d.i_price, d.dis_amt, td.ac_code_ar,
          m.cur_code a_cy, ias_gen_pkg.get_cur_rate (m.cur_code) ac_rate,
          NVL (d.vat_per, 0) tax_prcnt, NVL (d.vat_amt, 0) tax_amt,
          d.w_code w_code, d.cc_code cc_code, d.pj_no pj_no,
          d.actv_no actv_no, rcrd_no, d.doc_sequence, 0 external_post,
          m.cmp_no, m.brn_no, m.brn_year, m.brn_usr,
          NVL (d.vat_amt, 0)
          * ias_gen_pkg.get_cur_rate (m.cur_code) tax_amt_l, d.i_qty,
          d.free_qty, m.ref_no
     FROM p_order m,
          p_order_detail d,
          gnr_tax_typ_clc_dtl tc,
          gnr_tax_code_dtl td,
          gnr_tax_typ_clc_brn brn
    WHERE m.po_ser = d.po_ser
      AND brn.clc_typ_no = tc.clc_typ_no
      AND brn.brn_no = m.brn_no
      AND m.clc_typ_no_tax = tc.clc_typ_no
      AND tc.tax_no = td.tax_no
      AND NVL (d.vat_amt, 0) > 0;

