--
-- CHK_DEL_RT_BILL_DTL  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.Chk_Del_Rt_Bill_Dtl
BEFORE DELETE
ON IAS20261.IAS_RT_BILL_DTL 
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
   V_Cnt NUMBER;
  BEGIN                                                                                     
     Begin
       Select 1 InTo V_Cnt From Item_Movement Where Doc_Ser=:Old.RT_Bill_Ser And i_Code=:Old.I_Code And Doc_Sequence=:old.Doc_Sequence And RowNum<=1;
     Exception When Others Then
       V_Cnt:=0;
       End;
       
     If Nvl(V_Cnt,0)>0 Then
        Raise_application_error(-20804,'Error When Delete Item From Ias_Rt_Bill_Dtl Table '||SqlErrm) ;
     End If;
   
  END chk_del_rt_bill_dtl;
/


--
-- CHK_TAX_BILL_MST  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.chk_tax_bill_mst
			BEFORE INSERT
			ON IAS20261.IAS_BILL_MST 
			REFERENCING NEW AS New OLD AS Old
			FOR EACH ROW
BEGIN                                                                                     
			             
			     If :NEW.CLC_TYP_NO_TAX IS NULL And Nvl(:New.Vat_Amt,0)> 0 Then
			        Raise_application_error(-20469,'Error When insert bill into Ias_Bill_mst Table '||SqlErrm) ;
			     End If;
			   
			  END chk_tax_bill_mst;
/


--
-- IAS_BILL_MST_CHK_SRL_TRG  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_BILL_MST_CHK_SRL_TRG
BEFORE INSERT OR UPDATE
ON IAS20261.IAS_BILL_MST
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN
   IF NVL(:NEW.EXTERNAL_POST,0)=0 THEN
       IF INSERTING AND AR_DOC_SQ_PKG.GET_DOC_SRL (   P_DOC_TYP       => 4,
                                                      P_PAY_TYP       => :NEW.BILL_DOC_TYPE,                                                      
                                                      P_BRN_YEAR      => :NEW.BRN_YEAR,
                                                      P_BRN_NO        => :NEW.BRN_NO,
                                                      P_CC_CODE       => :NEW.CC_CODE ,
                                                      P_W_CODE        => :NEW.W_CODE,
                                                      P_TYP_NO        => :NEW.SI_TYPE,
                                                      P_DOC_NO        => :NEW.BILL_NO,
                                                      P_SYS_NO        => 61,
                                                      P_USR_NO        => :NEW.AD_U_ID,
                                                      P_TRMNL_NO      => NULL                 )<>:NEW.BILL_SER THEN
               RAISE_APPLICATION_ERROR(-20090,'The Serial No. For Ducument Not Currect') ; 
               
         ELSIF UPDATING THEN      
               IF :OLD.BILL_NO<>:NEW.BILL_NO THEN 
                  RAISE_APPLICATION_ERROR(-20091,'Error .. Can Not Update Bill No') ;                    
               ELSIF :OLD.BILL_SER<>:NEW.BILL_SER THEN 
                  RAISE_APPLICATION_ERROR(-20092,'Error .. Can Not Update Bill Serial') ;                  
               END IF;
       END IF;
   END IF;  
END CHK_BILL_SRL_TRG;
/


--
-- IAS_SET_MAIN_PRICE_RT_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_SET_MAIN_PRICE_RT_TGR
        before INSERT ON  IAS20261.IAS_RT_BILL_DTL REFERENCING NEW AS NEW OLD AS OLD
        FOR EACH ROW
DECLARE
  Begin
     :new.I_PRICE_LEV_NO:= get_main_price(:new.i_code,:NEW.ITM_UNT);                                                 
  End;
/


--
-- IAS_SORDR_UPDT_ITM_RSVD  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_SORDR_UPDT_ITM_RSVD AFTER UPDATE 
                    ON IAS20261.SALES_ORDER REFERENCING NEW AS NEW OLD AS OLD FOR EACH ROW
BEGIN

   IF NVL(:NEW.APPROVED,0) = 2 THEN 
      BEGIN 
         UPDATE IAS_RESERVE_DTL SET RESERVED=0 WHERE DOC_TYPE_REF=53 AND DOC_SER_REF=NVL(:OLD.ORDER_SER,:NEW.ORDER_SER);
      EXCEPTION WHEN OTHERS THEN 
         NULL;
      END;
   ELSIF NVL(:OLD.APPROVED,0) = 2 AND NVL(:NEW.APPROVED,0) = 1 THEN
      BEGIN  
         UPDATE IAS_RESERVE_DTL D SET RESERVED=(SELECT RESERVED FROM ORDER_DETAIL WHERE ORDER_SER=D.DOC_SER_REF AND I_CODE=D.I_CODE AND ITM_UNT=D.ITM_UNT AND RCRD_NO=D.RCRD_NO) WHERE DOC_TYPE_REF=53 AND DOC_SER_REF=NVL(:OLD.ORDER_SER,:NEW.ORDER_SER);
      EXCEPTION WHEN OTHERS THEN 
         NULL;
      END;   
   END IF;            
END IAS_SORDR_UPDT_ITM_RSVD;
/


