--
-- ARS_KPI_NET_SALES_PRD_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_KPI_NET_SALES_PRD_VW
(YR_NO, BRN_NO, BRN_NM, DOC_DATE, HALF_NO, 
 QRTR_NO, PRD_NO, PRD_NM, WEEK_NO, DAY_NO, 
 CUR_CODE, CST_CODE, CST_NM, ITM_CODE, ITM_NM, 
 ITM_UNT, MAX_ITM_UNT, MAX_P_SIZE, MN_GRP_CODE, SUB_GRP_CODE, 
 UNDR_SUB_GRP_CODE, ASSTNT_GRP_CODE, DTL_GRP_CODE, ALTRNTV_GRP_CODE, ITM_TYP, 
 ITM_CLSSFCTN, ITM_DSC, SMAN_CODE, SMAN_NM, R_CODE, 
 W_CODE, W_NM, CC_CODE, CC_NM, PJ_NO, 
 PJ_NM, ACTV_NO, ACTV_NM, SAL_AMT_L, SAL_AMT_F, 
 SAL_DSCNT_AMT_L, SAL_DSCNT_AMT_F, SAL_TAX_AMT_L, SAL_TAX_AMT_F, SAL_OTHR_AMT_L, 
 SAL_OTHR_AMT_F, RT_SAL_AMT_L, RT_SAL_AMT_F, RT_SAL_DSCNT_AMT_L, RT_SAL_DSCNT_AMT_F, 
 RT_SAL_TAX_AMT_L, RT_SAL_TAX_AMT_F, RT_SAL_OTHR_AMT_L, RT_SAL_OTHR_AMT_F, NET_SAL_NOT_TAX_OTHR_AMT_L, 
 NET_SAL_NOT_TAX_OTHR_AMT_F, NET_SAL_AMT_L, NET_SAL_AMT_F, NET_BILL_AMT_L, NET_STK_AMT_L, 
 NET_PROFT_AMT_L, NET_BILL_AMT_STK, NET_STK_AMT_STK, NET_PROFT_AMT_STK)
BEQUEATH DEFINER
AS 
SELECT M.YR_NO,
             M.BRN_NO,
             (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (BRN_LNAME, BRN_FNAME),NVL (BRN_FNAME, BRN_LNAME)) FROM S_BRN WHERE BRN_NO = M.BRN_NO) BRN_NM,
             M.DOC_DATE,
             M.HALF_NO,
             M.QRTR_NO,
             M.PRD_NO,
             (SELECT    LPAD (PRD_NO, 2, '0')|| '-'|| DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1), 1, PRD_L_NM,NVL (PRD_F_NM, PRD_L_NM))FROM S_PRD_DTL  WHERE PRD_NO = M.PRD_NO)  PRD_NM,
             M.WEEK_NO,
             M.DAY_NO,
             M.CUR_CODE,
             M.CST_CODE,
             M.CST_NM,
             I.I_Code ITM_CODE,
             DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),1),1, I.I_NAME,NVL (I.I_E_NAME, I.I_NAME)) Itm_Nm ,
             (Select Itm_Unt From Ias_Itm_Dtl Where Ias_Itm_Dtl.I_Code = I.I_Code And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 And RowNum <= 1 ) Itm_Unt ,
             (SELECT ITM_UNT FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND LVL_UNIT = ( SELECT MAX (LVL_UNIT)FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1)MAX_ITM_UNT ,
             (SELECT P_SIZE  FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND ITM_UNT  = ( SELECT ITM_UNT FROM IAS_ITM_DTL WHERE     I_CODE = I.I_CODE AND LVL_UNIT = (SELECT MAX (LVL_UNIT) FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1) AND ROWNUM <= 1) MAX_P_SIZE ,             
             I.G_CODE         MN_GRP_CODE   ,
             I.MNG_CODE       SUB_GRP_CODE  ,
             I.SUBG_CODE      UNDR_SUB_GRP_CODE,
             I.ASSISTANT_NO   ASSTNT_GRP_CODE ,
             I.DETAIL_NO      DTL_GRP_CODE ,
             I.GROUP_NO       ALTRNTV_GRP_CODE ,
             I.ITEM_TYPE      ITM_TYP ,
             I.GRP_CLASS_CODE ITM_CLSSFCTN ,
             DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),1),1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC)) ITM_DSC ,             
             M.SMAN_CODE,
             (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (REPRS_A_NAME, REPRS_E_NAME),NVL (REPRS_E_NAME, REPRS_A_NAME)) FROM SALES_MAN WHERE REPRS_CODE = M.SMAN_CODE) SMAN_NM,
             M.R_CODE,
             M.W_CODE,
             (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (W_NAME, W_E_NAME),NVL (W_E_NAME, W_NAME)) FROM WAREHOUSE_DETAILS  WHERE W_CODE = M.W_CODE) W_NM,
             M.CC_CODE,
             (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (CC_A_NAME, CC_E_NAME),NVL (CC_E_NAME, CC_A_NAME)) FROM COST_CENTERS WHERE CC_CODE = M.CC_CODE) CC_NM,
             M.PJ_NO,
            (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (PJ_A_NAME, PJ_E_NAME),NVL (PJ_A_NAME, PJ_E_NAME)) FROM IAS_PROJECTS WHERE PJ_NO = M.PJ_NO) PJ_NM,
             M.ACTV_NO,
             (SELECT DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1),1, NVL (ACTV_A_NAME, ACTV_E_NAME),NVL (ACTV_E_NAME, ACTV_A_NAME)) FROM IAS_ACTVTY WHERE ACTV_NO = M.ACTV_NO) ACTV_NM,
             SUM (M.SAL_AMT_L)          SAL_AMT_L,
             SUM (M.SAL_AMT_F)          SAL_AMT_F,
             SUM (M.SAL_DSCNT_AMT_L)    SAL_DSCNT_AMT_L,
             SUM (M.SAL_DSCNT_AMT_F)    SAL_DSCNT_AMT_F,
             SUM (M.SAL_TAX_AMT_L)      SAL_TAX_AMT_L,
             SUM (M.SAL_TAX_AMT_F)      SAL_TAX_AMT_F,
             SUM (M.SAL_OTHR_AMT_L)     SAL_OTHR_AMT_L,
             SUM (M.SAL_OTHR_AMT_F)     SAL_OTHR_AMT_F,
             SUM (M.RT_SAL_AMT_L)       RT_SAL_AMT_L,
             SUM (M.RT_SAL_AMT_F)       RT_SAL_AMT_F,
             SUM (M.RT_SAL_DSCNT_AMT_L) RT_SAL_DSCNT_AMT_L,
             SUM (M.RT_SAL_DSCNT_AMT_F) RT_SAL_DSCNT_AMT_F,
             SUM (M.RT_SAL_TAX_AMT_L)   RT_SAL_TAX_AMT_L,
             SUM (M.RT_SAL_TAX_AMT_F)   RT_SAL_TAX_AMT_F,
             SUM (M.RT_SAL_OTHR_AMT_L)  RT_SAL_OTHR_AMT_L,
             SUM (M.RT_SAL_OTHR_AMT_F)  RT_SAL_OTHR_AMT_F,
             ROUND ( SUM ((M.SAL_AMT_L)    - (M.SAL_DSCNT_AMT_L)) - SUM ((M.RT_SAL_AMT_L) - (M.RT_SAL_DSCNT_AMT_L)),4) NET_SAL_NOT_TAX_OTHR_AMT_L,
             ROUND (SUM ((M.SAL_AMT_F)     - (M.SAL_DSCNT_AMT_F))  - SUM ((M.RT_SAL_AMT_F) - (M.RT_SAL_DSCNT_AMT_F)),4)   NET_SAL_NOT_TAX_OTHR_AMT_F, 
             ROUND (SUM (M.SAL_AMT_L)      - SUM (M.SAL_DSCNT_AMT_L) +  SUM (M.SAL_OTHR_AMT_L), 4) - ROUND ( SUM (M.RT_SAL_AMT_L) - SUM (M.RT_SAL_DSCNT_AMT_L) +  SUM (M.RT_SAL_OTHR_AMT_L),4) NET_SAL_AMT_L,
             ROUND (SUM (M.SAL_AMT_F)      - SUM (M.SAL_DSCNT_AMT_F) +  SUM (M.SAL_OTHR_AMT_F), 4) - ROUND ( SUM (M.RT_SAL_AMT_F) - SUM (M.RT_SAL_DSCNT_AMT_F) +  SUM (M.RT_SAL_OTHR_AMT_F),4) NET_SAL_AMT_F,
             SUM (M.NET_BILL_AMT_L)  NET_BILL_AMT_L,
             SUM (M.NET_STK_AMT_L)   NET_STK_AMT_L,
             ROUND (SUM (M.NET_BILL_AMT_L) - SUM (M.NET_STK_AMT_L), 4) NET_PROFT_AMT_L,
             SUM (M.NET_BILL_AMT_STK) NET_BILL_AMT_STK,
             SUM (M.NET_STK_AMT_STK)   NET_STK_AMT_STK ,
             ROUND (SUM (M.NET_BILL_AMT_STK) - SUM (M.NET_STK_AMT_STK), 4) NET_PROFT_AMT_STK
     FROM (  SELECT M.BRN_YEAR YR_NO,
                       M.BRN_NO,
                       M.BILL_DATE  DOC_DATE,
                      ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2) HALF_NO,
                      ROUND (TO_CHAR (M.BILL_DATE, 'Q')) QRTR_NO,
                      TO_CHAR (M.BILL_DATE, 'MM') PRD_NO,
                      TO_CHAR (M.BILL_DATE, 'WW') WEEK_NO,
                      TO_CHAR (M.BILL_DATE, 'DD') DAY_NO,
                      M.BILL_CURRENCY CUR_CODE,
                      M.C_CODE CST_CODE,
                      M.C_NAME CST_NM,
                      D.I_CODE ITM_CODE,
                       M.REP_CODE SMAN_CODE,
                       M.R_CODE,
                       D.W_CODE,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO,
                       ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1)),4) SAL_AMT_L,
                       ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4) SAL_AMT_F,
                       ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1)),4) SAL_DSCNT_AMT_L,
                       ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4) SAL_DSCNT_AMT_F,
                       ROUND (SUM (NVL (D.VAT_AMT, 0)* NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1)),4)  SAL_TAX_AMT_L,
                       ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4) SAL_TAX_AMT_F,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0)* NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1)),4)SAL_OTHR_AMT_L,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4) SAL_OTHR_AMT_F,
                       0  RT_SAL_AMT_L,
                       0  RT_SAL_AMT_F,
                       0  RT_SAL_DSCNT_AMT_L,
                       0  RT_SAL_DSCNT_AMT_F,
                       0  RT_SAL_TAX_AMT_L,
                       0  RT_SAL_TAX_AMT_F,
                       0  RT_SAL_OTHR_AMT_L,
                       0  RT_SAL_OTHR_AMT_F,
                       ROUND (SUM ((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1)),4) NET_BILL_AMT_L,
                       ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))* NVL (D.STK_COST, 0)* NVL (M.STOCK_RATE, 1)),4) NET_STK_AMT_L,
                       ROUND (SUM (((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0)* NVL (M.BILL_RATE, 1))/ NVL (M.STOCK_RATE, 1)),4) NET_BILL_AMT_STK,
                       ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))* NVL (D.STK_COST, 0)),4) NET_STK_AMT_STK
                  FROM IAS_BILL_MST M, IAS_BILL_DTL D        
                 WHERE M.BILL_SER = D.BILL_SER       
                   AND NVL (M.STAND_BY, 0) = 0
              GROUP BY M.BRN_YEAR,
                       M.BRN_NO,
                       M.BILL_DATE,
                       ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2),
                       ROUND (TO_CHAR (M.BILL_DATE, 'Q')),
                       TO_CHAR (M.BILL_DATE, 'MM'),
                       TO_CHAR (M.BILL_DATE, 'WW'),
                       TO_CHAR (M.BILL_DATE, 'DD'),
                       M.BILL_CURRENCY,
                       M.C_CODE,
                       M.C_NAME, 
                       D.I_CODE,
                       M.REP_CODE,
                       M.R_CODE,
                       D.W_CODE, 
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO
              UNION ALL
                SELECT M.BRN_YEAR
                       YR_NO,
                       M.BRN_NO,
                       M.RT_BILL_DATE DOC_DATE,
                       ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2) HALF_NO,
                       ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q')) QRTR_NO,
                       TO_CHAR (M.RT_BILL_DATE, 'MM') PRD_NO,
                       TO_CHAR (M.RT_BILL_DATE, 'WW') WEEK_NO,
                       TO_CHAR (M.RT_BILL_DATE, 'DD') DAY_NO,
                       M.RT_BILL_CURRENCY
                       CUR_CODE,
                       M.C_CODE
                       CST_CODE,
                       M.C_NAME
                       CST_NM,
                       D.I_CODE ITM_CODE,
                       M.REP_CODE
                       SMAN_CODE,
                       M.R_CODE,
                       D.W_CODE,
                       D.CC_CODE,
                       D.PJ_NO,
                       D.ACTV_NO,
                       0 SAL_AMT_L,
                       0 SAL_AMT_F,
                       0 SAL_DSCNT_AMT_L,
                       0 SAL_DSCNT_AMT_F,
                       0 SAL_TAX_AMT_L,
                       0 SAL_TAX_AMT_F,
                       0 SAL_OTHR_AMT_L,
                       0 SAL_OTHR_AMT_F,
                       ROUND (SUM (NVL (D.I_PRICE, 0)* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1)),4) RT_SAL_AMT_L,
                       ROUND (SUM (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4) RT_SAL_AMT_F,
                       ROUND (SUM (NVL (D.DIS_AMT, 0)* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1)),4) RT_SAL_DSCNT_AMT_L,
                       ROUND (SUM (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4) RT_SAL_DSCNT_AMT_F,
                       ROUND (SUM (NVL (D.VAT_AMT, 0)* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1)),4) RT_SAL_TAX_AMT_L,
                       ROUND (SUM (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4) RT_SAL_TAX_AMT_F,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0)* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1)),4) RT_SAL_OTHR_AMT_L,
                       ROUND (SUM (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4) RT_SAL_OTHR_AMT_F,
                       ROUND (SUM ((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1)), 4)* -1 NET_BILL_AMT_L,
                       ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)* NVL (M.STOCK_RATE, 1)),4)* -1 NET_STK_AMT_L,
                       ROUND (SUM (((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0)* NVL (M.RT_BILL_RATE, 1))/ NVL (M.STOCK_RATE, 1)),4)* -1 NET_BILL_AMT_STK,
                       ROUND (SUM ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)),4)* -1 NET_STK_AMT_STK
                  FROM IAS_RT_BILL_MST M, IAS_RT_BILL_DTL D  
                     WHERE M.RT_BILL_SER = D.RT_BILL_SER 
                      AND NVL (M.STAND_BY, 0) = 0
                  GROUP BY M.BRN_YEAR,
                           M.BRN_NO,
                           M.RT_BILL_DATE,
                           ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2),
                           ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q')),
                           TO_CHAR (M.RT_BILL_DATE, 'MM'),
                           TO_CHAR (M.RT_BILL_DATE, 'WW'),
                           TO_CHAR (M.RT_BILL_DATE, 'DD'),
                           M.RT_BILL_CURRENCY,
                           M.C_CODE,
                           M.C_NAME, 
                           D.I_CODE,
                           M.REP_CODE,
                           M.R_CODE,
                           D.W_CODE, 
                           D.CC_CODE,
                           D.PJ_NO,
                           D.ACTV_NO ) M , IAS_ITM_MST I
       WHERE  M.ITM_CODE = I.I_CODE
    GROUP BY M.YR_NO,
             M.BRN_NO,
             M.DOC_DATE,
             M.HALF_NO,
             M.QRTR_NO,
             M.PRD_NO,
             M.WEEK_NO,
             M.DAY_NO,
             M.CUR_CODE,
             M.CST_CODE,
             M.CST_NM,
             I.I_CODE,
             DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),1),1, I.I_NAME,NVL (I.I_E_NAME, I.I_NAME)),
             M.SMAN_CODE,
             M.R_CODE,
             M.W_CODE,
             I.G_CODE,
             I.MNG_CODE,
             I.SUBG_CODE,
             I.ASSISTANT_NO,
             I.DETAIL_NO,
             I.GROUP_NO,
             I.ITEM_TYPE,
             I.GRP_CLASS_CODE,
             DECODE (NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'),1),1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC)) ,
             M.CC_CODE,
             M.PJ_NO,
             M.ACTV_NO;

