--
-- ARS_KPI_NET_SALES_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_KPI_NET_SALES_VW
(DOC_TYPE, DOC_TYPE_NM, SYS_NM, YR_NO, BRN_NM, 
 DOC_BRN_NM, AD_U_NM, EXPIRE_DATE, BATCH_NO, A_CODE_NM, 
 AC_CODE_DTL, CR_CARD_NM, INSRNCE_CMP_NO, INS_CMP_NM, INSRNCE_CARD_NO, 
 INSRNCE_CARD_NO_FMLY, CNTRCT_NO, STAND_BY, REF_NO, PAID_BILL, 
 PAID_U_NM, PAID_DATE, REC_INV_BILL, REC_INV_U_ID, REC_INV_DATE, 
 AUDIT_REF, C_TEL, PTNT_NO, DCTR_NO, DOC_NO_ADMSON, 
 C_CODE_CSH, BILL_DOC_TYPE, DOC_DATE, HALF_NO, QRTR_NO, 
 PRD_NM, WEEK_NO, DAY_NO, CASH_NM, CST_CODE, 
 C_CODE_NAME, ITM_CODE, ITM_NM, ITM_F_NM, G_CODE, 
 GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, 
 ASSTNT_GRP_CODE, ASSTNT_GRP_NM, DTL_GRP_NO, DTL_GRP_NM, ALTRNTV_GRP_CODE, 
 ALTRNTV_GRP_NM, GRP_CLASS_CODE, GRP_CLASS_NM, ITM_DSC, ITM_F_DSC, 
 SMAN_NM, COL_NM, DRIVER_NM, PRM_NM, R_NM, 
 CMP_NM, W_NM, CC_NM, PJ_NM, ACTV_NM, 
 KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, USE_ATTCH, 
 EXTERNAL_POST, ITM_UNT, ITM_SIZE, MAX_ITM_UNT, MAX_P_SIZE, 
 CUR_CODE, DOC_NO, DOC_SER, RCRD_NO, SI_RCRD_NO, 
 BILL_NO, BILL_SER, P_SIZE, CUR_RATE, STOCK_RATE, 
 STK_COST, I_CWTAVG, I_PRICE, I_QTY, FREE_QTY, 
 ITM_QTY, AMT, AMT_L, DSCNT_AMT, DSCNT_AMT_L, 
 TAX_AMT, TAX_AMT_L, OTHR_AMT, OTHR_AMT_L, NET_BILL_AMT, 
 NET_BILL_AMT_L, NET_BILL_AMT_NO_TAX, NET_BILL_AMT_NO_TAXT_L, NET_STK_AMT_L, NET_BILL_AMT_STK, 
 NET_BILL_AMT_STK_NO_DISC, NET_STK_AMT_STK, NET_PROFT_AMT_STK, NET_PROFT_AMT_L, AC_AMT, 
 CHEQUE_AMT, BNK_AMT_DTL, CRDT_AMT, CASH_AMT, BRN_NO, 
 DOC_BRN_NO, AD_U_ID, A_CODE, CR_CARD_NO, PAID_U_ID, 
 BILL_DOC_TYPE_NO, CASH_NO, SMAN_CODE, COL_NO, DRIVER_NO, 
 PRM_CODE, R_CODE, CMP_NO, W_CODE, CC_CODE, 
 PJ_NO, ACTV_NO, PRD_NO, SYS_NO, NO_OF_DAY, 
 C_CLASS_NM, C_GROUP_CODE_NM, C_DEGREE_NM, C_CLASS_TYP_NM, ITM_TYP_NM, 
 EMP_NO, EMP_NM, P_YEAR, P_YEAR_NM)
BEQUEATH DEFINER
AS 
With lng  As (Select (select  Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1) from dual) Lng_No
                               ,Nvl((SELECT FLD_VAL FROM S_FLD_PRV_FXD_USR WHERE UPPER(FLD_NM)=UPPER('HIDE_COST') AND U_ID =nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1) AND ROWNUM<=1),0) HIDE_COST                 
                               ,(select Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1)  from dual) USR_NO
                               ,(SELECT WTAVG_TYPE FROM IAS_PARA_INV WHERE ROWNUM<=1) WTAVG_TYPE  From Dual                
                )  
   Select Doc_Type
         ,(  Select DOC_TYPE_NAME                     
                        From Ias_Sys.IAS_DOCJV_TYPE_SYSTEMS_MST
                    Where Lang_no  = Lng.Lng_No
                      and DOC_TYPE = M.Doc_Type
                      and rownum<=1)Doc_Type_Nm        
         , (Select  (Select Caption_det    
                           From Ias_Sys.IAS_LABELS
                          Where lang_no=Lng.Lng_No
                            and Label_no=Smart_Rprt_Dsgnr_Qry.Lbl_No
                            and RowNum<=1)
              From Smart_Rprt_Dsgnr_Qry
             Where Sys_No = M.Sys_No And Scr_No_Parent = 0
             AND ROWNUM<=1)
             Sys_Nm
         ,M.Yr_No
         ,   M.Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = M.Brn_No
               AND ROWNUM<=1)
             Brn_Nm
         ,   M.Doc_Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = M.Doc_Brn_No
               AND ROWNUM<=1)
             Doc_Brn_Nm
         ,   M.Ad_U_Id
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (U_A_Name, U_E_Name), Nvl (U_E_Name, U_A_Name))
                From User_R
               Where U_Id = M.Ad_U_Id
               AND ROWNUM<=1)
             Ad_U_Nm
         ,M.Expire_Date
         ,M.Batch_No
         ,   M.A_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (A_Name, A_Name_Eng), Nvl (A_Name_Eng, A_Name))
                From Account
               Where A_Code = M.A_Code
               AND ROWNUM<=1)
             A_Code_Nm
         ,M.Ac_Code_Dtl
         ,   M.Cr_Card_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cr_Card_Name, Cr_Card_E_Name), Nvl (Cr_Card_E_Name, Cr_Card_Name))
                From Credit_Card_Types
               Where Cr_Card_No = M.Cr_Card_No
               AND ROWNUM<=1)
             Cr_Card_Nm
         ,M.Insrnce_Cmp_No
         ,   M.Insrnce_Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Ins_Cmp_L_Nm, Ins_Cmp_F_Nm), Nvl (Ins_Cmp_F_Nm, Ins_Cmp_L_Nm))
                From Ias_Insrnce_Cmp
               Where Ins_Cmp_No = M.Insrnce_Cmp_No
               AND ROWNUM<=1)
             Ins_Cmp_Nm
         ,M.Insrnce_Card_No
         ,M.Insrnce_Card_No_Fmly
         ,M.Cntrct_No
         ,M.Stand_By
         ,M.Ref_No
         ,M.Paid_Bill
         ,   M.Paid_U_Id
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (U_A_Name, U_E_Name), Nvl (U_E_Name, U_A_Name))
                From User_R
               Where U_Id = M.Paid_U_Id
               AND ROWNUM<=1)
             Paid_U_Nm
         ,M.Paid_Date
         ,M.Rec_Inv_Bill
         ,M.Rec_Inv_U_Id
         ,M.Rec_Inv_Date
         ,M.Audit_Ref
         ,M.C_Tel
         ,M.Ptnt_No
         ,M.Dctr_No
         ,M.Doc_No_Admson
         ,M.C_Code_Csh
         ,   M.Bill_Doc_Type_No
          || ' - '
          || (Select Flg_Desc
                From S_Flags
               Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = M.Bill_Doc_Type_No and rownum<=1)
             Bill_Doc_Type
         ,M.Doc_Date
         ,M.Half_No
         ,M.Qrtr_No
         ,M.Prd_No || '-' || (Select Decode (Lng.Lng_No, 1, Nvl (Prd_L_Nm, Prd_F_Nm), Nvl (Prd_F_Nm, Prd_L_Nm))
                From S_Prd_Dtl
               Where Prd_No = M.Prd_No
               and rownum<=1)Prd_Nm
         ,M.Week_No
         ,M.Day_No
         ,   M.Cash_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cash_Name, Cash_E_Name), Nvl (Cash_E_Name, Cash_Name))
                From Cash_In_Hand
               Where Cash_No = M.Cash_No
               AND ROWNUM<=1)
             Cash_Nm
         ,M.Cst_Code
         ,' '||M.Cst_Code || ' - ' || M.Cst_Nm C_Code_Name
         ,I.I_Code Itm_Code
         ,Decode (Lng.Lng_No, 1, I.I_Name, Nvl (I.I_E_Name, I.I_Name)) Itm_Nm
         ,I.I_E_Name Itm_F_Nm
          , I.G_Code 
         ,    I.G_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.G_A_NAME, Grp.G_E_NAME), Nvl (Grp.G_E_NAME, Grp.G_A_NAME)) Grp_Code_Nm
                From GROUP_DETAILS Grp
               Where G_Code =  I.G_Code And Rownum <= 1)
             Grp_Code_Nm
         , I.Mng_Code
         ,    I.Mng_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.MNG_A_NAME, Grp.MNG_E_NAME), Nvl (Grp.MNG_E_NAME, Grp.MNG_A_NAME)) Grp_Nm
                From IAS_MAINSUB_GRP_DTL Grp
               Where  Mng_Code =  I.Mng_Code
                  AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                   And Rownum <= 1)
             Mng_Code_Nm
         , I.Subg_Code
         ,    I.Subg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.SUBG_A_NAME, Grp.SUBG_E_NAME), Nvl (Grp.SUBG_E_NAME, Grp.SUBG_A_NAME)) Grp_Nm
                From IAS_SUB_GRP_DTL Grp
               Where Subg_Code =  I.Subg_Code
               AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
               AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code) 
               And Rownum <= 1)
             Subg_Code_Nm
         , I.Assistant_No Asstnt_Grp_Code
         ,    I.Assistant_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Assistant_A_Name, Grp.Assistant_E_Name), Nvl (Grp.Assistant_E_Name, Grp.Assistant_A_Name)) Grp_Nm
                From Ias_Assistant_Group Grp
               Where Assistant_No =  I.Assistant_No 
                 AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                 AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code)
                 AND NVL( I.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL( I.Subg_Code,'0'),Subg_Code)
                 And Rownum <= 1)
             Asstnt_Grp_Nm
         , I.Detail_No Dtl_Grp_No
         ,    I.Detail_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Detail_A_Name, Grp.Detail_E_Name), Nvl (Grp.Detail_E_Name, Grp.Detail_A_Name)) Grp_Nm
                From Ias_Detail_Group Grp
               Where Detail_No= I.Detail_No
               AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                 AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code)
                 AND NVL( I.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL( I.Subg_Code,'0'),Subg_Code)
                 AND NVL( I.Assistant_No,'0')= DECODE(Nvl (Assistant_No, '0'),'0',NVL( I.Assistant_No,'0'),Assistant_No)
                 And Rownum <= 1)
             Dtl_Grp_Nm
         , I.Group_No Altrntv_Grp_Code
         ,    I.Group_No 
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Group_A_Name, Nvl (A.Group_E_Name, A.Group_A_Name))
                From Ias_Alternative_Group A
               Where A.Group_No =  I.Group_No And Rownum <= 1)
             Altrntv_Grp_Nm
       ,I.Grp_Class_Code Grp_Class_Code
         ,    I.Grp_Class_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Grp_L_Name, Nvl (A.Grp_F_Name, A.Grp_L_Name))
                From Ias_Grp_Itm_Lvl A
               Where A.Grp_Code =  I.Grp_Class_Code And Rownum <= 1)
             Grp_Class_Nm
         ,Decode (Lng.Lng_No, 1, I.I_Desc, Nvl (I.I_F_Desc, I.I_Desc)) Itm_Dsc
         ,I.I_F_Desc  Itm_F_Dsc
         ,   M.Sman_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Reprs_A_Name, Reprs_E_Name), Nvl (Reprs_E_Name, Reprs_A_Name))
                From Sales_Man
               Where Reprs_Code = M.Sman_Code
               AND ROWNUM<=1)
             Sman_Nm
         ,   M.Col_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Col_Name, Col_E_Name), Nvl (Col_E_Name, Col_Name))
                From Collerctor
               Where Col_No = M.Col_No
               AND ROWNUM<=1)
             Col_Nm
         ,   M.Driver_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Driver_A_Name, Driver_E_Name), Nvl (Driver_E_Name, Driver_A_Name))
                From Ias_Drivers
               Where Driver_No = M.Driver_No
               AND ROWNUM<=1)
             Driver_Nm
         ,   M.Prm_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prm_L_Nm, Prm_F_Nm), Nvl (Prm_F_Nm, Prm_L_Nm))
                From Ias_Promoters
               Where Prm_Code = M.Prm_Code
               AND ROWNUM<=1)
             Prm_Nm
         ,   M.R_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (R_A_Name, R_E_Name), Nvl (R_E_Name, R_A_Name))
                From Regions
               Where R_Code = M.R_Code
               AND ROWNUM<=1)
             R_Nm
         ,   M.Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cmp_Lname, Cmp_Fname), Nvl (Cmp_Fname, Cmp_Lname))
                From S_Cmpny
               Where Cmp_No = M.Cmp_No
               AND ROWNUM<=1)
             Cmp_Nm
         ,   M.W_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (W_Name, W_E_Name), Nvl (W_E_Name, W_Name))
                From Warehouse_Details
               Where W_Code = M.W_Code
               AND ROWNUM<=1)
             W_Nm
         ,   M.Cc_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cc_A_Name, Cc_E_Name), Nvl (Cc_E_Name, Cc_A_Name))
                From Cost_Centers
               Where Cc_Code = M.Cc_Code
               AND ROWNUM<=1)
             Cc_Nm
         ,   M.Pj_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Pj_A_Name, Pj_E_Name), Nvl (Pj_A_Name, Pj_E_Name))
                From Ias_Projects
               Where Pj_No = M.Pj_No
               AND ROWNUM<=1)
             Pj_Nm
         ,   M.Actv_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Actv_A_Name, Actv_E_Name), Nvl (Actv_E_Name, Actv_A_Name))
                From Ias_Actvty
               Where Actv_No = M.Actv_No
               AND ROWNUM<=1)
             Actv_Nm
         ,I.Kit_Itm
         ,I.Use_Exp_Date
         ,I.Use_Batch_No
         ,I.Use_Serialno
         ,I.Use_Attch
         ,M.External_Post
         ,(Select Itm_Unt 
                  From Ias_Itm_Dtl
                   Where Ias_Itm_Dtl.I_Code           = I.I_Code
                     And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 
                     And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 
                     And RowNum                      <= 1 )Itm_Unt
         ,M.Itm_Size
         , (SELECT ITM_UNT FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND LVL_UNIT = ( SELECT MAX (LVL_UNIT)FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1)MAX_ITM_UNT
         , (SELECT P_SIZE  FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND ITM_UNT  = ( SELECT ITM_UNT FROM IAS_ITM_DTL WHERE     I_CODE = I.I_CODE AND LVL_UNIT = (SELECT MAX (LVL_UNIT) FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1) AND ROWNUM <= 1) MAX_P_SIZE                 
         ,M.Cur_Code         
         ,M.DOC_NO
         ,M.DOC_SER
         ,M.RCRD_NO
         ,M.SI_RCRD_NO 
         ,M.BILL_NO
         ,M.BILL_SER
         ,M.P_SIZE
         ,M.CUR_Rate   
         ,M.Stock_Rate 
         ,DECODE (LNG.HIDE_COST, 1, Round (M.Stk_Cost, 4), 0) Stk_Cost
         ,DECODE (LNG.HIDE_COST, 1, ROUND(Ias_Itm_Pkg.Get_Grand_Wtavg( P_Wtavg_Type =>Lng.Wtavg_Type,
																                                       P_Icode      =>I.I_Code ,
																                                       P_Wcode      =>M.W_Code),4), 0)
          I_CWTAVG
         ,M.I_Price 
         ,Round (Nvl (M.I_Qty, 0), 2) I_Qty
         ,Round (Nvl (M.Free_Qty, 0), 2) Free_Qty
         ,Round ( (Nvl (M.I_Qty, 0)) + (Nvl (M.Free_Qty, 0)), 2) Itm_Qty
         ,Round (Nvl (M.Amt, 0), 2) Amt
         ,Round (Nvl (M.Amt, 0) * Nvl (Cur_Rate, 1), 2) Amt_L
         ,Round (Nvl (M.Dscnt_Amt, 0), 2) Dscnt_Amt
         ,Round (Nvl (M.Dscnt_Amt, 0) * Nvl (Cur_Rate, 1), 2) Dscnt_Amt_L
         ,Round (Nvl (M.Tax_Amt, 0), 2) Tax_Amt
         ,Round (Nvl (M.Tax_Amt, 0) * Nvl (Cur_Rate, 1), 2) Tax_Amt_L
         ,Round (Nvl (M.Othr_Amt, 0), 2) Othr_Amt
         ,Round (Nvl (M.Othr_Amt, 0) * Nvl (Cur_Rate, 1), 2) Othr_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt, 0), 2) Net_Bill_Amt
         ,Round (Nvl (M.Net_Bill_Amt, 0) * Nvl (Cur_Rate, 1), 2) Net_Bill_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt_No_Tax, 0), 2) Net_Bill_Amt_No_Tax
         ,Round (Nvl (M.Net_Bill_Amt_No_Tax, 0) * Nvl (Cur_Rate, 1), 2) Net_Bill_Amt_No_Taxt_L
         ,DECODE (LNG.HIDE_COST, 1, Round (Nvl (M.Net_Stk_Amt_L, 0), 2), 0)  Net_Stk_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt_Stk, 0), 2)  Net_Bill_Amt_Stk
         ,Round (Nvl (M.Net_Bill_Amt_Stk_No_Disc, 0), 2) Net_Bill_Amt_Stk_No_Disc
         ,DECODE (LNG.HIDE_COST, 1, Round(Nvl (M.Net_Stk_Amt_Stk, 0), 2), 0)  Net_Stk_Amt_Stk
         ,DECODE (LNG.HIDE_COST, 1, ROUND((ABS(Nvl (M.Net_Bill_Amt_Stk, 0))-ABS(Nvl (M.Net_Stk_Amt_Stk, 0)))*DECODE(M.DOC_TYPE,5,-1,1),2), 0)  Net_Proft_Amt_Stk
         ,DECODE (LNG.HIDE_COST, 1, ROUND((ABS(Nvl (M.Net_Bill_Amt_Stk, 0))-ABS(Nvl (M.Net_Stk_Amt_Stk, 0)))* Nvl (Cur_Rate, 1) *IN_OUT,2), 0)  Net_Proft_Amt_L          
         ,CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END AC_AMT
         ,CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END CHEQUE_AMT                     
         ,round(m.BNK_AMT_DTL,2) BNK_AMT_DTL 
         ,ROUND(CASE WHEN M.Bill_Doc_Type_No=4 THEN (ABS(M.Net_Bill_Amt)-ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END ) -ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END )-ABS(M.BNK_AMT_DTL))*IN_OUT ELSE 0 END,2) CRDT_AMT
         ,ROUND(CASE WHEN M.Bill_Doc_Type_No=1 THEN (ABS(M.Net_Bill_Amt)-ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END ) -ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END )-ABS(M.BNK_AMT_DTL))*IN_OUT ELSE 0 END,2) CASH_AMT                                                                      
         ,M.Brn_No
         ,M.Doc_Brn_No
         ,M.Ad_U_Id
         ,M.A_Code
         ,M.Cr_Card_No
         ,M.Paid_U_Id
         ,M.Bill_Doc_Type_No
         ,M.Cash_No        
         ,M.Sman_Code
         ,M.Col_No
         ,M.Driver_No
         ,M.Prm_Code
         ,M.R_Code
         ,M.Cmp_No
         ,M.W_Code
         ,M.Cc_Code
         ,M.Pj_No
         ,M.Actv_No
         ,M.Prd_No
         ,M.Sys_No
         ,to_number(to_char(m.doc_date,'DDD')) NO_OF_DAY
         ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_CLASS_NAME, C_CLASS_E_NAME), Nvl (C_CLASS_E_NAME, C_CLASS_NAME)) 
                 FROM     Customer_CLASS
                 WHERE C_CLASS=CST.C_CLASS
                 AND ROWNUM<=1)C_CLASS_NM
         ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_Group_A_Name, C_Group_E_Name), Nvl (C_Group_E_Name, C_Group_A_Name)) 
                 FROM     Customer_Group
                 WHERE C_Group_Code=CST.C_Group_Code
                 AND ROWNUM<=1) C_Group_Code_NM
          ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_DEGREE_A_NAME, C_DEGREE_E_NAME), Nvl (C_DEGREE_E_NAME, C_DEGREE_A_NAME)) 
                 FROM     CUSTOMER_DEGREE
                 WHERE C_DEGREE=CST.C_DEGREE
                 AND ROWNUM<=1)  C_DEGREE_NM
          ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_CLass_Typ_Nm, C_CLass_Typ_F_Nm), Nvl (C_CLass_Typ_F_Nm, C_CLass_Typ_Nm)) 
                 FROM     Customer_Class_Typ
                 WHERE C_CLass_Typ=CST.C_CLass_Typ
                 AND ROWNUM<=1)  C_CLass_Typ_NM 
          ,   I.Item_Type
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.It_A_Name, Nvl (A.It_E_Name, A.It_A_Name))
                From Item_Types A
               Where A.Type_Of_Item = I.Item_Type And Rownum <= 1)
             Itm_Typ_Nm
          ,M.EMP_NO    
         , M.EMP_NO
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.EMP_L_NM, Nvl (A.EMP_F_NM, A.EMP_L_NM))
                From S_EMP A
               Where EMP_NO = M.EMP_NO And Rownum <= 1)
             EMP_NM
        ,   M.P_YEAR          
       ,  (Select Flg_Desc
                From S_Flags
               Where Flg_Code = 'RETURN_TYPE' And Lang_No = Lng.Lng_No And Flg_Value = M.P_YEAR and rownum<=1)
             P_YEAR_NM                                  
     From (Select *
             From (Select 4 Doc_Type
                         ,Decode (Nvl (D.External_Post, 0), 0, 61, D.External_Post) Sys_No
                         ,M.Bill_Doc_Type Bill_Doc_Type_No
                         ,M.Brn_Year Yr_No
                         ,M.Brn_No
                         ,Nvl (M.Doc_Brn_No, M.Brn_No) Doc_Brn_No
                         ,M.Ad_U_Id
                         ,D.Expire_Date
                         ,D.Batch_No
                         ,M.A_Code
                         ,M.Ac_Code_Dtl
                         ,M.Cr_Card_No
                         ,M.Insrnce_Cmp_No
                         ,M.Insrnce_Card_No
                         ,M.Insrnce_Card_No_Fmly
                         ,M.Cntrct_No
                         ,M.Stand_By
                         ,M.Ref_No
                         ,M.Paid_Bill
                         ,M.Paid_U_Id
                         ,M.Paid_Date
                         ,M.Rec_Inv_Bill
                         ,M.Rec_Inv_U_Id
                         ,M.Rec_Inv_Date
                         ,M.Audit_Ref
                         ,M.C_Tel
                         ,M.Ptnt_No
                         ,M.Dctr_No
                         ,M.Doc_No_Admson
                         ,M.C_Code_Csh
                         ,M.Bill_Date Doc_Date
                         ,Round (To_Char (M.Bill_Date, 'Q') / 2) Half_No
                         ,Round (To_Char (M.Bill_Date, 'Q')) Qrtr_No
                         ,To_Char (M.Bill_Date, 'MM') Prd_No
                         ,To_Char (M.Bill_Date, 'WW') Week_No
                         ,To_Char (M.Bill_Date, 'DD') Day_No
                         ,NVL(AC_AMT,0) AC_AMT
                          ,NVL(CHEQUE_AMT,0) CHEQUE_AMT                                                                                                                                                    
                         ,NVL(D.BNK_AMT_DTL,0) BNK_AMT_DTL
                         ,1 IN_OUT                        
                         ,M.Bill_Currency Cur_Code
                         ,M.Bill_Rate Cur_Rate
                         ,M.Stock_Rate
                         ,M.Emp_no
                         ,M.BILL_NO DOC_NO
                         ,M.BILL_SER DOC_SER
                         ,D.RCRD_NO
                         ,D.RCRD_NO SI_RCRD_NO
                         ,5 P_YEAR 
                         ,M.BILL_NO BILL_NO
                         ,M.BILL_SER BILL_SER                       
                         ,M.Cash_No
                         ,M.C_Code Cst_Code
                         ,M.C_Name Cst_Nm
                         ,D.I_Code Itm_Code
                         ,M.Rep_Code Sman_Code
                         ,M.Col_No
                         ,M.Driver_No
                         ,M.Prm_Code
                         ,M.R_Code
                         ,D.Cmp_No
                         ,D.W_Code
                         ,D.Cc_Code
                         ,D.Pj_No
                         ,D.Actv_No
                         ,D.External_Post
                         ,1 Itm_Size
                          ,D.P_SIZE
                         ,(D.Stk_Cost/D.P_SIZE)Stk_Cost
                         ,(D.I_Price/D.P_SIZE) I_Price
                         , (Nvl (D.P_Qty, 0)) I_Qty
                         , (Nvl (D.Free_Qty, 0) * Nvl (D.P_Size, 1)) Free_Qty
                         , (Nvl (D.I_Price, 0) * Nvl (D.I_Qty, 0)) Amt
                         , (Nvl (D.Dis_Amt, 0) * Nvl (D.I_Qty, 0)) Dscnt_Amt
                         , ( (Nvl (D.Vat_Amt, 0) + Nvl (D.Vat_Amt_Othr, 0)) * Nvl (D.I_Qty, 0)) Tax_Amt
                         , (Nvl (D.Othr_Amt, 0) * Nvl (D.I_Qty, 0)) Othr_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Net_Bill_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Net_Bill_Amt_No_Tax
                        -- ,ROUND(SUM( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))))OVER(PARTITION BY M.BILL_SER ),2) SUM_Net_Bill_Amt
                         ,0 SUM_Net_Bill_Amt
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0) * Nvl (M.Stock_Rate, 1)) Net_Stk_Amt_L
                         , ( ( (Nvl (D.I_Price, 0) +Nvl (D.Othr_Amt, 0)- Nvl (D.Dis_Amt, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) Net_Bill_Amt_Stk
                         , ( ( (Nvl (D.I_Price, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) Net_Bill_Amt_Stk_No_Disc                         
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0)) Net_Stk_Amt_Stk
                     From Ias_Bill_Mst M, Ias_Bill_Dtl D
                    Where M.Bill_Ser = D.Bill_Ser 
                   Union All
                   Select 5 Doc_Type
                         ,Decode (Nvl (D.External_Post, 0), 0, 61, D.External_Post) Sys_No
                         ,M.Rt_Bill_Doc_Type Bill_Doc_Type_No
                         ,M.Brn_Year Yr_No
                         ,M.Brn_No
                         ,Nvl (M.Doc_Brn_No, M.Brn_No) Doc_Brn_No
                         ,M.Ad_U_Id
                         ,D.Expire_Date
                         ,D.Batch_No
                         ,M.A_Code
                         ,M.Ac_Code_Dtl
                         ,M.Cr_Card_No
                         ,M.Insrnce_Cmp_No
                         ,M.Insrnce_Card_No
                         ,M.Insrnce_Card_No_Fmly
                         ,Null Cntrct_No
                         ,M.Stand_By
                         ,M.Ref_No
                         ,Null Paid_Bill
                         ,M.Paid_U_Id
                         ,M.Paid_Date
                         ,Null Rec_Inv_Bill
                         ,M.Rec_Inv_U_Id
                         ,M.Rec_Inv_Date
                         ,M.Audit_Ref
                         ,M.C_Tel
                         ,M.Ptnt_No
                         ,M.Dctr_No
                         ,M.Doc_No_Admson
                         ,M.C_Code_Csh
                         ,M.Rt_Bill_Date Doc_Date
                         ,Round (To_Char (M.Rt_Bill_Date, 'Q') / 2) Half_No
                         ,Round (To_Char (M.Rt_Bill_Date, 'Q')) Qrtr_No
                         ,To_Char (M.Rt_Bill_Date, 'MM') Prd_No
                         ,To_Char (M.Rt_Bill_Date, 'WW') Week_No
                         ,To_Char (M.Rt_Bill_Date, 'DD') Day_No
                         ,NVL(AC_AMT,0)*-1 AC_AMT
                         ,NVL(CHEQUE_AMT,0)*-1 CHEQUE_AMT                                                                           
                         ,NVL(D.BNK_AMT_DTL,0)*-1 BNK_AMT_DTL
                          ,-1 IN_OUT 
                         ,M.Rt_Bill_Currency Cur_Code
                         ,M.Rt_Bill_Rate Cur_Rate
                         ,M.Stock_Rate
                         ,M.Emp_no
                         ,M.RT_BILL_NO DOC_NO
                         ,M.RT_BILL_SER DOC_SER
                         ,D.RCRD_NO
                         ,D.SI_RCRD_NO SI_RCRD_NO
                         ,M.P_YEAR
                         ,NVL(D.BILL_NO,D.RT_BILL_NO) BILL_NO
                         ,NVL(D.BILL_SER,D.RT_BILL_SER) BILL_SER
                         ,M.Cash_No
                         ,M.C_Code Cst_Code
                         ,M.C_Name Cst_Nm
                         ,D.I_Code Itm_Code
                         ,M.Rep_Code Sman_Code
                         ,M.Col_No
                         ,M.Driver_No
                         ,M.Prm_Code
                         ,M.R_Code
                         ,D.Cmp_No
                         ,D.W_Code
                         ,D.Cc_Code
                         ,D.Pj_No
                         ,D.Actv_No
                         ,D.External_Post
                         ,1 Itm_Size
                          ,D.P_SIZE
                         ,(D.Stk_Cost/D.P_SIZE) Stk_Cost
                         ,(D.I_Price/D.P_SIZE) I_Price
                         , (Nvl (D.P_Qty, 0)) * -1 I_Qty
                         , (Nvl (D.Free_Qty, 0) * Nvl (D.P_Size, 1)) * -1 Free_Qty
                         , (Nvl (D.I_Price, 0) * Nvl (D.I_Qty, 0)) * -1 Amt
                         , (Nvl (D.Dis_Amt, 0) * Nvl (D.I_Qty, 0)) * -1 Dscnt_Amt
                         , ( (Nvl (D.Vat_Amt, 0) + Nvl (D.Vat_Amt_Othr, 0)) * Nvl (D.I_Qty, 0)) * -1 Tax_Amt
                         , (Nvl (D.Othr_Amt, 0) * Nvl (D.I_Qty, 0)) * -1 Othr_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) * -1 Net_Bill_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) * -1 Net_Bill_Amt_No_Tax
                         --,ROUND(SUM( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))))OVER(PARTITION BY M.RT_BILL_SER ),2)*-1 SUM_Net_Bill_Amt
                         ,0 SUM_Net_Bill_Amt
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0) * Nvl (M.Stock_Rate, 1)) * -1 Net_Stk_Amt_L
                         , ( ( (Nvl (D.I_Price, 0)+Nvl (D.Othr_Amt, 0) - Nvl (D.Dis_Amt, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Rt_Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) * -1 Net_Bill_Amt_Stk
                         , ( ( (Nvl (D.I_Price, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Rt_Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) * -1 Net_Bill_Amt_Stk_No_Disc
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0)) * -1 Net_Stk_Amt_Stk
                     From Ias_Rt_Bill_Mst M, Ias_Rt_Bill_Dtl D
                    Where M.Rt_Bill_Ser = D.Rt_Bill_Ser) M) M
         ,Ias_Itm_Mst I
         ,Lng,customer cst
    Where M.Itm_Code = I.I_Code
    and m.CST_CODE=cst.c_code(+)
  AND   
            Exists
            (Select 1
                    From Privilege_Wh
                    Where     Privilege_Wh.W_Code = M.W_Code                    
                    And View_Flag = 1
                    And U_Id =Lng.USR_NO
                    And Rownum <= 1)
            And Exists
            (Select 1
                From Privilege_Gc
                Where     Privilege_Gc.G_Code = I.G_Code           
                And View_Flag = 1
                And U_Id = Lng.USR_NO
                 And Rownum <= 1)                 
            And 1=CASE WHEN  M.CC_CODE IS NULL THEN 1
                        ELSE(Select 1
                                    From Privilege_Cc
                                    Where     Privilege_Cc.Cc_Code = M.CC_CODE
                                    And View_Flag = 1
                                    And U_Id = Lng.USR_NO
                                    And Rownum <= 1)END
            And 1=CASE WHEN M.Pj_No IS NULL THEN 1                                     
                        ELSE (Select 1
                                    From Ias_Priv_Projects
                                    Where     Ias_Priv_Projects.Pj_No= M.Pj_No
                                    And View_Flag = 1
                                    And U_Id = Lng.USR_NO
                                    And Rownum <= 1) END                                                     
            And 1=CASE  WHEN M.Actv_No IS  NULL THEN 1 
            ELSE   (Select 1
                        From Ias_Priv_Actvty
                        Where     M.Actv_No = Ias_Priv_Actvty.Actv_No
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1) END
            And Exists
                        (Select 1
                        From S_Brn_Usr_Priv
                        Where     S_Brn_Usr_Priv.Brn_No = M.Brn_No
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1)                                                   
            AND 1=CASE   WHEN M.CST_CODE IS NULL  THEN 1
                        ELSE ( Select 1
                        From Ias_Priv_Customer
                        Where     Ias_Priv_Customer.C_Code = M.CST_CODE
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1) END;


--
-- ARS_KPI_NET_SALES_VW_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_KPI_NET_SALES_VW_YR
(DOC_TYPE, DOC_TYPE_NM, SYS_NM, YR_NO, BRN_NM, 
 DOC_BRN_NM, AD_U_NM, EXPIRE_DATE, BATCH_NO, A_CODE_NM, 
 AC_CODE_DTL, CR_CARD_NM, INSRNCE_CMP_NO, INS_CMP_NM, INSRNCE_CARD_NO, 
 INSRNCE_CARD_NO_FMLY, CNTRCT_NO, STAND_BY, REF_NO, PAID_BILL, 
 PAID_U_NM, PAID_DATE, REC_INV_BILL, REC_INV_U_ID, REC_INV_DATE, 
 AUDIT_REF, C_TEL, PTNT_NO, DCTR_NO, DOC_NO_ADMSON, 
 C_CODE_CSH, BILL_DOC_TYPE, DOC_DATE, HALF_NO, QRTR_NO, 
 PRD_NM, WEEK_NO, DAY_NO, CASH_NM, CST_CODE, 
 C_CODE_NAME, ITM_CODE, ITM_NM, ITM_F_NM, G_CODE, 
 GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, SUBG_CODE, SUBG_CODE_NM, 
 ASSTNT_GRP_CODE, ASSTNT_GRP_NM, DTL_GRP_NO, DTL_GRP_NM, ALTRNTV_GRP_CODE, 
 ALTRNTV_GRP_NM, GRP_CLASS_CODE, GRP_CLASS_NM, ITM_DSC, ITM_F_DSC, 
 SMAN_NM, COL_NM, DRIVER_NM, PRM_NM, R_NM, 
 CMP_NM, W_NM, CC_NM, PJ_NM, ACTV_NM, 
 KIT_ITM, USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, USE_ATTCH, 
 EXTERNAL_POST, ITM_UNT, ITM_SIZE, MAX_ITM_UNT, MAX_P_SIZE, 
 CUR_CODE, DOC_NO, DOC_SER, RCRD_NO, SI_RCRD_NO, 
 BILL_NO, BILL_SER, P_SIZE, CUR_RATE, STOCK_RATE, 
 STK_COST, I_CWTAVG, I_PRICE, I_QTY, FREE_QTY, 
 ITM_QTY, AMT, AMT_L, DSCNT_AMT, DSCNT_AMT_L, 
 TAX_AMT, TAX_AMT_L, OTHR_AMT, OTHR_AMT_L, NET_BILL_AMT, 
 NET_BILL_AMT_L, NET_BILL_AMT_NO_TAX, NET_BILL_AMT_NO_TAXT_L, NET_STK_AMT_L, NET_BILL_AMT_STK, 
 NET_BILL_AMT_STK_NO_DISC, NET_STK_AMT_STK, NET_PROFT_AMT_STK, NET_PROFT_AMT_L, AC_AMT, 
 CHEQUE_AMT, BNK_AMT_DTL, CRDT_AMT, CASH_AMT, BRN_NO, 
 DOC_BRN_NO, AD_U_ID, A_CODE, CR_CARD_NO, PAID_U_ID, 
 BILL_DOC_TYPE_NO, CASH_NO, SMAN_CODE, COL_NO, DRIVER_NO, 
 PRM_CODE, R_CODE, CMP_NO, W_CODE, CC_CODE, 
 PJ_NO, ACTV_NO, PRD_NO, SYS_NO, NO_OF_DAY, 
 C_CLASS_NM, C_GROUP_CODE_NM, C_DEGREE_NM, C_CLASS_TYP_NM, ITM_TYP_NM, 
 EMP_NO, EMP_NM, P_YEAR, P_YEAR_NM)
BEQUEATH DEFINER
AS 
With lng  As (Select (select  Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1) from dual) Lng_No
                               ,Nvl((SELECT FLD_VAL FROM S_FLD_PRV_FXD_USR WHERE UPPER(FLD_NM)=UPPER('HIDE_COST') AND U_ID =nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1) AND ROWNUM<=1),0) HIDE_COST                 
                               ,(select Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'USER_NO'),1)  from dual) USR_NO
                               ,(SELECT WTAVG_TYPE FROM IAS_PARA_INV WHERE ROWNUM<=1) WTAVG_TYPE From Dual                
                )  
   Select Doc_Type
         ,(  Select DOC_TYPE_NAME                     
                        From Ias_Sys.IAS_DOCJV_TYPE_SYSTEMS_MST
                    Where Lang_no  = Lng.Lng_No
                      and DOC_TYPE = M.Doc_Type
                      and rownum<=1)Doc_Type_Nm        
         , (Select  (Select Caption_det    
                           From Ias_Sys.IAS_LABELS
                          Where lang_no=Lng.Lng_No
                            and Label_no=Smart_Rprt_Dsgnr_Qry.Lbl_No
                            and RowNum<=1)
              From Smart_Rprt_Dsgnr_Qry
             Where Sys_No = M.Sys_No And Scr_No_Parent = 0
             AND ROWNUM<=1)
             Sys_Nm
         ,M.Yr_No
         ,   M.Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = M.Brn_No
               AND ROWNUM<=1)
             Brn_Nm
         ,   M.Doc_Brn_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Brn_Lname, Brn_Fname), Nvl (Brn_Fname, Brn_Lname))
                From S_Brn
               Where Brn_No = M.Doc_Brn_No
               AND ROWNUM<=1)
             Doc_Brn_Nm
         ,   M.Ad_U_Id
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (U_A_Name, U_E_Name), Nvl (U_E_Name, U_A_Name))
                From User_R
               Where U_Id = M.Ad_U_Id
               AND ROWNUM<=1)
             Ad_U_Nm
         ,M.Expire_Date
         ,M.Batch_No
         ,   M.A_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (A_Name, A_Name_Eng), Nvl (A_Name_Eng, A_Name))
                From Account
               Where A_Code = M.A_Code
               AND ROWNUM<=1)
             A_Code_Nm
         ,M.Ac_Code_Dtl
         ,   M.Cr_Card_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cr_Card_Name, Cr_Card_E_Name), Nvl (Cr_Card_E_Name, Cr_Card_Name))
                From Credit_Card_Types
               Where Cr_Card_No = M.Cr_Card_No
               AND ROWNUM<=1)
             Cr_Card_Nm
         ,M.Insrnce_Cmp_No
         ,   M.Insrnce_Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Ins_Cmp_L_Nm, Ins_Cmp_F_Nm), Nvl (Ins_Cmp_F_Nm, Ins_Cmp_L_Nm))
                From Ias_Insrnce_Cmp
               Where Ins_Cmp_No = M.Insrnce_Cmp_No
               AND ROWNUM<=1)
             Ins_Cmp_Nm
         ,M.Insrnce_Card_No
         ,M.Insrnce_Card_No_Fmly
         ,M.Cntrct_No
         ,M.Stand_By
         ,M.Ref_No
         ,M.Paid_Bill
         ,   M.Paid_U_Id
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (U_A_Name, U_E_Name), Nvl (U_E_Name, U_A_Name))
                From User_R
               Where U_Id = M.Paid_U_Id
               AND ROWNUM<=1)
             Paid_U_Nm
         ,M.Paid_Date
         ,M.Rec_Inv_Bill
         ,M.Rec_Inv_U_Id
         ,M.Rec_Inv_Date
         ,M.Audit_Ref
         ,M.C_Tel
         ,M.Ptnt_No
         ,M.Dctr_No
         ,M.Doc_No_Admson
         ,M.C_Code_Csh
         ,   M.Bill_Doc_Type_No
          || ' - '
          || (Select Flg_Desc
                From S_Flags
               Where Flg_Code = 'TYPE_NAME' And Lang_No = Lng.Lng_No And Flg_Value = M.Bill_Doc_Type_No and rownum<=1)
             Bill_Doc_Type
         ,M.Doc_Date
         ,M.Half_No
         ,M.Qrtr_No
         ,M.Prd_No || '-' || (Select Decode (Lng.Lng_No, 1, Nvl (Prd_L_Nm, Prd_F_Nm), Nvl (Prd_F_Nm, Prd_L_Nm))
                From S_Prd_Dtl
               Where Prd_No = M.Prd_No
               and rownum<=1)Prd_Nm
         ,M.Week_No
         ,M.Day_No
         ,   M.Cash_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cash_Name, Cash_E_Name), Nvl (Cash_E_Name, Cash_Name))
                From Cash_In_Hand
               Where Cash_No = M.Cash_No
               AND ROWNUM<=1)
             Cash_Nm
         ,M.Cst_Code
         ,' '||M.Cst_Code || ' - ' || M.Cst_Nm C_Code_Name
         ,I.I_Code Itm_Code
         ,Decode (Lng.Lng_No, 1, I.I_Name, Nvl (I.I_E_Name, I.I_Name)) Itm_Nm
         ,I.I_E_Name Itm_F_Nm
          , I.G_Code 
         ,    I.G_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.G_A_NAME, Grp.G_E_NAME), Nvl (Grp.G_E_NAME, Grp.G_A_NAME)) Grp_Code_Nm
                From GROUP_DETAILS Grp
               Where G_Code =  I.G_Code And Rownum <= 1)
             Grp_Code_Nm
         , I.Mng_Code
         ,    I.Mng_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.MNG_A_NAME, Grp.MNG_E_NAME), Nvl (Grp.MNG_E_NAME, Grp.MNG_A_NAME)) Grp_Nm
                From IAS_MAINSUB_GRP_DTL Grp
               Where  Mng_Code =  I.Mng_Code
                  AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                   And Rownum <= 1)
             Mng_Code_Nm
         , I.Subg_Code
         ,    I.Subg_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.SUBG_A_NAME, Grp.SUBG_E_NAME), Nvl (Grp.SUBG_E_NAME, Grp.SUBG_A_NAME)) Grp_Nm
                From IAS_SUB_GRP_DTL Grp
               Where Subg_Code =  I.Subg_Code
               AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
               AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code) 
               And Rownum <= 1)
             Subg_Code_Nm
         , I.Assistant_No Asstnt_Grp_Code
         ,    I.Assistant_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Assistant_A_Name, Grp.Assistant_E_Name), Nvl (Grp.Assistant_E_Name, Grp.Assistant_A_Name)) Grp_Nm
                From Ias_Assistant_Group Grp
               Where Assistant_No =  I.Assistant_No 
                 AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                 AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code)
                 AND NVL( I.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL( I.Subg_Code,'0'),Subg_Code)
                 And Rownum <= 1)
             Asstnt_Grp_Nm
         , I.Detail_No Dtl_Grp_No
         ,    I.Detail_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Grp.Detail_A_Name, Grp.Detail_E_Name), Nvl (Grp.Detail_E_Name, Grp.Detail_A_Name)) Grp_Nm
                From Ias_Detail_Group Grp
               Where Detail_No= I.Detail_No
               AND NVL( I.G_Code,'0')= DECODE(Nvl (G_Code, '0'),'0',NVL( I.G_Code,'0'),G_Code) 
                 AND NVL( I.Mng_Code,'0')= DECODE(Nvl (Mng_Code, '0'),'0',NVL( I.Mng_Code,'0'),Mng_Code)
                 AND NVL( I.Subg_Code,'0')= DECODE(Nvl (Subg_Code, '0'),'0',NVL( I.Subg_Code,'0'),Subg_Code)
                 AND NVL( I.Assistant_No,'0')= DECODE(Nvl (Assistant_No, '0'),'0',NVL( I.Assistant_No,'0'),Assistant_No)
                 And Rownum <= 1)
             Dtl_Grp_Nm
         , I.Group_No Altrntv_Grp_Code
         ,    I.Group_No 
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Group_A_Name, Nvl (A.Group_E_Name, A.Group_A_Name))
                From Ias_Alternative_Group A
               Where A.Group_No =  I.Group_No And Rownum <= 1)
             Altrntv_Grp_Nm
       ,I.Grp_Class_Code Grp_Class_Code
         ,    I.Grp_Class_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.Grp_L_Name, Nvl (A.Grp_F_Name, A.Grp_L_Name))
                From Ias_Grp_Itm_Lvl A
               Where A.Grp_Code =  I.Grp_Class_Code And Rownum <= 1)
             Grp_Class_Nm
         ,Decode (Lng.Lng_No, 1, I.I_Desc, Nvl (I.I_F_Desc, I.I_Desc)) Itm_Dsc
         ,I.I_F_Desc  Itm_F_Dsc   
         ,   M.Sman_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Reprs_A_Name, Reprs_E_Name), Nvl (Reprs_E_Name, Reprs_A_Name))
                From Sales_Man
               Where Reprs_Code = M.Sman_Code
               AND ROWNUM<=1)
             Sman_Nm
         ,   M.Col_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Col_Name, Col_E_Name), Nvl (Col_E_Name, Col_Name))
                From Collerctor
               Where Col_No = M.Col_No
               AND ROWNUM<=1)
             Col_Nm
         ,   M.Driver_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Driver_A_Name, Driver_E_Name), Nvl (Driver_E_Name, Driver_A_Name))
                From Ias_Drivers
               Where Driver_No = M.Driver_No
               AND ROWNUM<=1)
             Driver_Nm
         ,   M.Prm_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Prm_L_Nm, Prm_F_Nm), Nvl (Prm_F_Nm, Prm_L_Nm))
                From Ias_Promoters
               Where Prm_Code = M.Prm_Code
               AND ROWNUM<=1)
             Prm_Nm
         ,   M.R_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (R_A_Name, R_E_Name), Nvl (R_E_Name, R_A_Name))
                From Regions
               Where R_Code = M.R_Code
               AND ROWNUM<=1)
             R_Nm
         ,   M.Cmp_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cmp_Lname, Cmp_Fname), Nvl (Cmp_Fname, Cmp_Lname))
                From S_Cmpny
               Where Cmp_No = M.Cmp_No
               AND ROWNUM<=1)
             Cmp_Nm
         ,   M.W_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (W_Name, W_E_Name), Nvl (W_E_Name, W_Name))
                From Warehouse_Details
               Where W_Code = M.W_Code
               AND ROWNUM<=1)
             W_Nm
         ,   M.Cc_Code
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Cc_A_Name, Cc_E_Name), Nvl (Cc_E_Name, Cc_A_Name))
                From Cost_Centers
               Where Cc_Code = M.Cc_Code
               AND ROWNUM<=1)
             Cc_Nm
         ,   M.Pj_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Pj_A_Name, Pj_E_Name), Nvl (Pj_A_Name, Pj_E_Name))
                From Ias_Projects
               Where Pj_No = M.Pj_No
               AND ROWNUM<=1)
             Pj_Nm
         ,   M.Actv_No
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, Nvl (Actv_A_Name, Actv_E_Name), Nvl (Actv_E_Name, Actv_A_Name))
                From Ias_Actvty
               Where Actv_No = M.Actv_No
               AND ROWNUM<=1)
             Actv_Nm
         ,I.Kit_Itm
         ,I.Use_Exp_Date
         ,I.Use_Batch_No
         ,I.Use_Serialno
         ,I.Use_Attch
         ,M.External_Post
         ,(Select Itm_Unt 
                  From Ias_Itm_Dtl
                   Where Ias_Itm_Dtl.I_Code           = I.I_Code
                     And Nvl(Ias_Itm_Dtl.P_Size,0)    = 1 
                     And Nvl(Ias_Itm_Dtl.Main_Unit,0) = 1 
                     And RowNum                      <= 1 )Itm_Unt
         ,M.Itm_Size
         , (SELECT ITM_UNT FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND LVL_UNIT = ( SELECT MAX (LVL_UNIT)FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1)MAX_ITM_UNT
         , (SELECT P_SIZE  FROM IAS_ITM_DTL WHERE  I_CODE = I.I_CODE AND ITM_UNT  = ( SELECT ITM_UNT FROM IAS_ITM_DTL WHERE     I_CODE = I.I_CODE AND LVL_UNIT = (SELECT MAX (LVL_UNIT) FROM IAS_ITM_DTL WHERE I_CODE = I.I_CODE) AND ROWNUM <= 1) AND ROWNUM <= 1) MAX_P_SIZE                 
         ,M.Cur_Code         
         ,M.DOC_NO
         ,M.DOC_SER
         ,M.RCRD_NO
         ,M.SI_RCRD_NO 
         ,M.BILL_NO
         ,M.BILL_SER
         ,M.P_SIZE
         ,M.CUR_Rate   
         ,M.Stock_Rate 
         ,DECODE (LNG.HIDE_COST, 1, Round (M.Stk_Cost, 4), 0) Stk_Cost
         ,DECODE (LNG.HIDE_COST, 1, ROUND(Ias_Itm_Pkg.Get_Grand_Wtavg( P_Wtavg_Type =>Lng.Wtavg_Type,
																                                       P_Icode      =>I.I_Code ,
																                                       P_Wcode      =>M.W_Code),4), 0)
               I_CWTAVG
         ,M.I_Price 
         ,Round (Nvl (M.I_Qty, 0), 2) I_Qty
         ,Round (Nvl (M.Free_Qty, 0), 2) Free_Qty
         ,Round ( (Nvl (M.I_Qty, 0)) + (Nvl (M.Free_Qty, 0)), 2) Itm_Qty
         ,Round (Nvl (M.Amt, 0), 2) Amt
         ,Round (Nvl (M.Amt, 0) * Nvl (Cur_Rate, 1), 2) Amt_L
         ,Round (Nvl (M.Dscnt_Amt, 0), 2) Dscnt_Amt
         ,Round (Nvl (M.Dscnt_Amt, 0) * Nvl (Cur_Rate, 1), 2) Dscnt_Amt_L
         ,Round (Nvl (M.Tax_Amt, 0), 2) Tax_Amt
         ,Round (Nvl (M.Tax_Amt, 0) * Nvl (Cur_Rate, 1), 2) Tax_Amt_L
         ,Round (Nvl (M.Othr_Amt, 0), 2) Othr_Amt
         ,Round (Nvl (M.Othr_Amt, 0) * Nvl (Cur_Rate, 1), 2) Othr_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt, 0), 2) Net_Bill_Amt
         ,Round (Nvl (M.Net_Bill_Amt, 0) * Nvl (Cur_Rate, 1), 2) Net_Bill_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt_No_Tax, 0), 2) Net_Bill_Amt_No_Tax
         ,Round (Nvl (M.Net_Bill_Amt_No_Tax, 0) * Nvl (Cur_Rate, 1), 2) Net_Bill_Amt_No_Taxt_L
         ,DECODE (LNG.HIDE_COST, 1, Round (Nvl (M.Net_Stk_Amt_L, 0), 2), 0)  Net_Stk_Amt_L
         ,Round (Nvl (M.Net_Bill_Amt_Stk, 0), 2)  Net_Bill_Amt_Stk
         ,Round (Nvl (M.Net_Bill_Amt_Stk_No_Disc, 0), 2) Net_Bill_Amt_Stk_No_Disc
         ,DECODE (LNG.HIDE_COST, 1, Round (Nvl (M.Net_Stk_Amt_Stk, 0), 2), 0)  Net_Stk_Amt_Stk
         ,DECODE (LNG.HIDE_COST, 1,ROUND( (ABS(Nvl (M.Net_Bill_Amt_Stk, 0))-ABS(Nvl (M.Net_Stk_Amt_Stk, 0))) *DECODE(M.DOC_TYPE,5,-1,1),2), 0)  Net_Proft_Amt_Stk
         ,DECODE (LNG.HIDE_COST, 1,ROUND( (ABS(Nvl (M.Net_Bill_Amt_Stk, 0))-ABS(Nvl (M.Net_Stk_Amt_Stk, 0)))* Nvl (Cur_Rate, 1) *IN_OUT,2), 0)  Net_Proft_Amt_L          
         ,CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END AC_AMT
         ,CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END CHEQUE_AMT                     
         ,round(m.BNK_AMT_DTL,2) BNK_AMT_DTL 
         ,ROUND(CASE WHEN M.Bill_Doc_Type_No=4 THEN (ABS(M.Net_Bill_Amt)-ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END ) -ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END )-ABS(M.BNK_AMT_DTL))*IN_OUT ELSE 0 END,2) CRDT_AMT
         ,ROUND(CASE WHEN M.Bill_Doc_Type_No=1 THEN (ABS(M.Net_Bill_Amt)-ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.AC_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END ) -ABS(CASE WHEN NVL(SUM_Net_Bill_Amt,0)<>0 THEN ROUND((M.CHEQUE_AMT/SUM_Net_Bill_Amt)*M.Net_Bill_AmT,2) ELSE 0 END )-ABS(M.BNK_AMT_DTL))*IN_OUT ELSE 0 END,2) CASH_AMT                                                                      
         ,M.Brn_No
         ,M.Doc_Brn_No
         ,M.Ad_U_Id
         ,M.A_Code
         ,M.Cr_Card_No
         ,M.Paid_U_Id
         ,M.Bill_Doc_Type_No
         ,M.Cash_No        
         ,M.Sman_Code
         ,M.Col_No
         ,M.Driver_No
         ,M.Prm_Code
         ,M.R_Code
         ,M.Cmp_No
         ,M.W_Code
         ,M.Cc_Code
         ,M.Pj_No
         ,M.Actv_No
         ,M.Prd_No
         ,M.Sys_No
         ,to_number(to_char(m.doc_date,'DDD')) NO_OF_DAY
         ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_CLASS_NAME, C_CLASS_E_NAME), Nvl (C_CLASS_E_NAME, C_CLASS_NAME)) 
                 FROM     Customer_CLASS
                 WHERE C_CLASS=CST.C_CLASS
                 AND ROWNUM<=1)C_CLASS_NM
         ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_Group_A_Name, C_Group_E_Name), Nvl (C_Group_E_Name, C_Group_A_Name)) 
                 FROM     Customer_Group
                 WHERE C_Group_Code=CST.C_Group_Code
                 AND ROWNUM<=1) C_Group_Code_NM
          ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_DEGREE_A_NAME, C_DEGREE_E_NAME), Nvl (C_DEGREE_E_NAME, C_DEGREE_A_NAME)) 
                 FROM     CUSTOMER_DEGREE
                 WHERE C_DEGREE=CST.C_DEGREE
                 AND ROWNUM<=1)  C_DEGREE_NM
          ,(SELECT   Decode (Lng.Lng_No, 1, Nvl (C_CLass_Typ_Nm, C_CLass_Typ_F_Nm), Nvl (C_CLass_Typ_F_Nm, C_CLass_Typ_Nm)) 
                 FROM     Customer_Class_Typ
                 WHERE C_CLass_Typ=CST.C_CLass_Typ
                 AND ROWNUM<=1)  C_CLass_Typ_NM 
          ,   I.Item_Type
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.It_A_Name, Nvl (A.It_E_Name, A.It_A_Name))
                From Item_Types A
               Where A.Type_Of_Item = I.Item_Type And Rownum <= 1)
             Itm_Typ_Nm
          ,M.EMP_NO    
         , M.EMP_NO
          || ' - '
          || (Select Decode (Lng.Lng_No, 1, A.EMP_L_NM, Nvl (A.EMP_F_NM, A.EMP_L_NM))
                From S_EMP A
               Where EMP_NO = M.EMP_NO And Rownum <= 1)
             EMP_NM
        ,   M.P_YEAR          
       ,  (Select Flg_Desc
                From S_Flags
               Where Flg_Code = 'RETURN_TYPE' And Lang_No = Lng.Lng_No And Flg_Value = M.P_YEAR and rownum<=1)
             P_YEAR_NM                                  
     From (Select *
             From (Select 4 Doc_Type
                         ,Decode (Nvl (D.External_Post, 0), 0, 61, D.External_Post) Sys_No
                         ,M.Bill_Doc_Type Bill_Doc_Type_No
                         ,M.Brn_Year Yr_No
                         ,M.Brn_No
                         ,Nvl (M.Doc_Brn_No, M.Brn_No) Doc_Brn_No
                         ,M.Ad_U_Id
                         ,D.Expire_Date
                         ,D.Batch_No
                         ,M.A_Code
                         ,M.Ac_Code_Dtl
                         ,M.Cr_Card_No
                         ,M.Insrnce_Cmp_No
                         ,M.Insrnce_Card_No
                         ,M.Insrnce_Card_No_Fmly
                         ,M.Cntrct_No
                         ,M.Stand_By
                         ,M.Ref_No
                         ,M.Paid_Bill
                         ,M.Paid_U_Id
                         ,M.Paid_Date
                         ,M.Rec_Inv_Bill
                         ,M.Rec_Inv_U_Id
                         ,M.Rec_Inv_Date
                         ,M.Audit_Ref
                         ,M.C_Tel
                         ,M.Ptnt_No
                         ,M.Dctr_No
                         ,M.Doc_No_Admson
                         ,M.C_Code_Csh
                         ,M.Bill_Date Doc_Date
                         ,Round (To_Char (M.Bill_Date, 'Q') / 2) Half_No
                         ,Round (To_Char (M.Bill_Date, 'Q')) Qrtr_No
                         ,To_Char (M.Bill_Date, 'MM') Prd_No
                         ,To_Char (M.Bill_Date, 'WW') Week_No
                         ,To_Char (M.Bill_Date, 'DD') Day_No
                         ,NVL(AC_AMT,0) AC_AMT
                          ,NVL(CHEQUE_AMT,0) CHEQUE_AMT                                                                                                                                                    
                         ,NVL(D.BNK_AMT_DTL,0) BNK_AMT_DTL
                         ,1 IN_OUT                        
                         ,M.Bill_Currency Cur_Code
                         ,M.Bill_Rate Cur_Rate
                         ,M.Stock_Rate
                         ,M.Emp_no
                         ,M.BILL_NO DOC_NO
                         ,M.BILL_SER DOC_SER
                         ,D.RCRD_NO
                         ,D.RCRD_NO SI_RCRD_NO
                         ,5 P_YEAR 
                         ,M.BILL_NO BILL_NO
                         ,M.BILL_SER BILL_SER                       
                         ,M.Cash_No
                         ,M.C_Code Cst_Code
                         ,M.C_Name Cst_Nm
                         ,D.I_Code Itm_Code
                         ,M.Rep_Code Sman_Code
                         ,M.Col_No
                         ,M.Driver_No
                         ,M.Prm_Code
                         ,M.R_Code
                         ,D.Cmp_No
                         ,D.W_Code
                         ,D.Cc_Code
                         ,D.Pj_No
                         ,D.Actv_No
                         ,D.External_Post
                         ,1 Itm_Size
                          ,D.P_SIZE
                         ,(D.Stk_Cost/D.P_SIZE)Stk_Cost
                         ,(D.I_Price/D.P_SIZE) I_Price
                         , (Nvl (D.P_Qty, 0)) I_Qty
                         , (Nvl (D.Free_Qty, 0) * Nvl (D.P_Size, 1)) Free_Qty
                         , (Nvl (D.I_Price, 0) * Nvl (D.I_Qty, 0)) Amt
                         , (Nvl (D.Dis_Amt, 0) * Nvl (D.I_Qty, 0)) Dscnt_Amt
                         , ( (Nvl (D.Vat_Amt, 0) + Nvl (D.Vat_Amt_Othr, 0)) * Nvl (D.I_Qty, 0)) Tax_Amt
                         , (Nvl (D.Othr_Amt, 0) * Nvl (D.I_Qty, 0)) Othr_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Net_Bill_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Net_Bill_Amt_No_Tax
                        -- ,ROUND(SUM( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))))OVER(PARTITION BY M.BILL_SER ),2) SUM_Net_Bill_Amt
                         ,0 SUM_Net_Bill_Amt
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0) * Nvl (M.Stock_Rate, 1)) Net_Stk_Amt_L
                         , ( ( (Nvl (D.I_Price, 0) +Nvl (D.Othr_Amt, 0)- Nvl (D.Dis_Amt, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) Net_Bill_Amt_Stk
                         , ( ( (Nvl (D.I_Price, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) Net_Bill_Amt_Stk_No_Disc                         
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0)) Net_Stk_Amt_Stk
                     From Ias_V_Bill_Mst_Yr M, Ias_V_Bill_Dtl_Yr D
                    Where M.Bill_Ser = D.Bill_Ser 
                   Union All
                   Select 5 Doc_Type
                         ,Decode (Nvl (D.External_Post, 0), 0, 61, D.External_Post) Sys_No
                         ,M.Rt_Bill_Doc_Type Bill_Doc_Type_No
                         ,M.Brn_Year Yr_No
                         ,M.Brn_No
                         ,Nvl (M.Doc_Brn_No, M.Brn_No) Doc_Brn_No
                         ,M.Ad_U_Id
                         ,D.Expire_Date
                         ,D.Batch_No
                         ,M.A_Code
                         ,M.Ac_Code_Dtl
                         ,M.Cr_Card_No
                         ,M.Insrnce_Cmp_No
                         ,M.Insrnce_Card_No
                         ,M.Insrnce_Card_No_Fmly
                         ,Null Cntrct_No
                         ,M.Stand_By
                         ,M.Ref_No
                         ,Null Paid_Bill
                         ,M.Paid_U_Id
                         ,M.Paid_Date
                         ,Null Rec_Inv_Bill
                         ,M.Rec_Inv_U_Id
                         ,M.Rec_Inv_Date
                         ,M.Audit_Ref
                         ,M.C_Tel
                         ,M.Ptnt_No
                         ,M.Dctr_No
                         ,M.Doc_No_Admson
                         ,M.C_Code_Csh
                         ,M.Rt_Bill_Date Doc_Date
                         ,Round (To_Char (M.Rt_Bill_Date, 'Q') / 2) Half_No
                         ,Round (To_Char (M.Rt_Bill_Date, 'Q')) Qrtr_No
                         ,To_Char (M.Rt_Bill_Date, 'MM') Prd_No
                         ,To_Char (M.Rt_Bill_Date, 'WW') Week_No
                         ,To_Char (M.Rt_Bill_Date, 'DD') Day_No
                         ,NVL(AC_AMT,0)*-1 AC_AMT
                         ,NVL(CHEQUE_AMT,0)*-1 CHEQUE_AMT                                                                           
                         ,NVL(D.BNK_AMT_DTL,0)*-1 BNK_AMT_DTL
                          ,-1 IN_OUT 
                         ,M.Rt_Bill_Currency Cur_Code
                         ,M.Rt_Bill_Rate Cur_Rate
                         ,M.Stock_Rate
                         ,M.Emp_no
                         ,M.RT_BILL_NO DOC_NO
                         ,M.RT_BILL_SER DOC_SER
                         ,D.RCRD_NO
                         ,D.SI_RCRD_NO SI_RCRD_NO
                         ,M.P_YEAR
                         ,NVL(D.BILL_NO,D.RT_BILL_NO) BILL_NO
                         ,NVL(D.BILL_SER,D.RT_BILL_SER) BILL_SER
                         ,M.Cash_No
                         ,M.C_Code Cst_Code
                         ,M.C_Name Cst_Nm
                         ,D.I_Code Itm_Code
                         ,M.Rep_Code Sman_Code
                         ,M.Col_No
                         ,M.Driver_No
                         ,M.Prm_Code
                         ,M.R_Code
                         ,D.Cmp_No
                         ,D.W_Code
                         ,D.Cc_Code
                         ,D.Pj_No
                         ,D.Actv_No
                         ,D.External_Post
                         ,1 Itm_Size
                          ,D.P_SIZE
                         ,(D.Stk_Cost/D.P_SIZE) Stk_Cost
                         ,(D.I_Price/D.P_SIZE) I_Price
                         , (Nvl (D.P_Qty, 0)) * -1 I_Qty
                         , (Nvl (D.Free_Qty, 0) * Nvl (D.P_Size, 1)) * -1 Free_Qty
                         , (Nvl (D.I_Price, 0) * Nvl (D.I_Qty, 0)) * -1 Amt
                         , (Nvl (D.Dis_Amt, 0) * Nvl (D.I_Qty, 0)) * -1 Dscnt_Amt
                         , ( (Nvl (D.Vat_Amt, 0) + Nvl (D.Vat_Amt_Othr, 0)) * Nvl (D.I_Qty, 0)) * -1 Tax_Amt
                         , (Nvl (D.Othr_Amt, 0) * Nvl (D.I_Qty, 0)) * -1 Othr_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) * -1 Net_Bill_Amt
                         ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) * -1 Net_Bill_Amt_No_Tax
                         --,ROUND(SUM( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))))OVER(PARTITION BY M.RT_BILL_SER ),2)*-1 SUM_Net_Bill_Amt
                         ,0 SUM_Net_Bill_Amt
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0) * Nvl (M.Stock_Rate, 1)) * -1 Net_Stk_Amt_L
                         , ( ( (Nvl (D.I_Price, 0)+Nvl (D.Othr_Amt, 0) - Nvl (D.Dis_Amt, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Rt_Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) * -1 Net_Bill_Amt_Stk
                         , ( ( (Nvl (D.I_Price, 0)) * Nvl (D.I_Qty, 0) * Nvl (M.Rt_Bill_Rate, 1)) / Nvl (M.Stock_Rate, 1)) * -1 Net_Bill_Amt_Stk_No_Disc
                         , ( (Nvl (D.I_Qty, 0) + Nvl (D.Free_Qty, 0)) * Nvl (D.Stk_Cost, 0)) * -1 Net_Stk_Amt_Stk
                     From Ias_V_Rt_Bill_Mst_Yr M, Ias_V_Rt_Bill_Dtl_Yr D
                    Where M.Rt_Bill_Ser = D.Rt_Bill_Ser) M) M
         ,Ias_Itm_Mst I
         ,Lng,customer cst
    Where M.Itm_Code = I.I_Code
    and m.CST_CODE=cst.c_code(+)
  AND   
            Exists
            (Select 1
                    From Privilege_Wh
                    Where     Privilege_Wh.W_Code = M.W_Code                    
                    And View_Flag = 1
                    And U_Id =Lng.USR_NO
                    And Rownum <= 1)
            And Exists
            (Select 1
                From Privilege_Gc
                Where     Privilege_Gc.G_Code = I.G_Code           
                And View_Flag = 1
                And U_Id = Lng.USR_NO
                 And Rownum <= 1)                 
            And 1=CASE WHEN  M.CC_CODE IS NULL THEN 1
                        ELSE(Select 1
                                    From Privilege_Cc
                                    Where     Privilege_Cc.Cc_Code = M.CC_CODE
                                    And View_Flag = 1
                                    And U_Id = Lng.USR_NO
                                    And Rownum <= 1)END
            And 1=CASE WHEN M.Pj_No IS NULL THEN 1                                     
                        ELSE (Select 1
                                    From Ias_Priv_Projects
                                    Where     Ias_Priv_Projects.Pj_No= M.Pj_No
                                    And View_Flag = 1
                                    And U_Id = Lng.USR_NO
                                    And Rownum <= 1) END                                                     
            And 1=CASE  WHEN M.Actv_No IS  NULL THEN 1 
            ELSE   (Select 1
                        From Ias_Priv_Actvty
                        Where     M.Actv_No = Ias_Priv_Actvty.Actv_No
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1) END
            And Exists
                        (Select 1
                        From S_Brn_Usr_Priv
                        Where     S_Brn_Usr_Priv.Brn_No = M.Brn_No
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1)                                                   
            AND 1=CASE   WHEN M.CST_CODE IS NULL  THEN 1
                        ELSE ( Select 1
                        From Ias_Priv_Customer
                        Where     Ias_Priv_Customer.C_Code = M.CST_CODE
                        And View_Flag = 1
                        And U_Id = Lng.USR_NO
                        And Rownum <= 1) END;


--
-- ARS_V_BILLS_ADVNC_PYMNT_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_V_BILLS_ADVNC_PYMNT_YR
BEQUEATH DEFINER
AS 
SELECT 
		                                      RCRD_NO, BILL_NO, BILL_SER, DOC_TYP_REF, DOC_NO_REF, DOC_SRL_REF, ADVNC_PYMNT_AMT, ADVNC_PYMNT_PER, ADVNC_PYMNT_VAT_AMT, ADVNC_PYMNT_VAT_PER, DOC_SRL_ADVNC, DOC_NO_ADVNC
		                                      FROM ARS_BILLS_ADVNC_PYMNT
		                                      Union All 
		                                      SELECT 
		                                      RCRD_NO, BILL_NO, BILL_SER, DOC_TYP_REF, DOC_NO_REF, DOC_SRL_REF, ADVNC_PYMNT_AMT, ADVNC_PYMNT_PER, ADVNC_PYMNT_VAT_AMT, ADVNC_PYMNT_VAT_PER, DOC_SRL_ADVNC, DOC_NO_ADVNC
		                                      FROM IAS20251.ARS_BILLS_ADVNC_PYMNT;


--
-- ARS_XLS_KPI_SALES_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_XLS_KPI_SALES_VW
(YR_NO, BRN_NO, BRN_NM, DOC_BRN_NO, DOC_BRN_NM, 
 BILL_DOC_TYPE_NO, BILL_DOC_TYPE, DOC_DATE, HALF_NO, QRTR_NO, 
 PRD_NO, PRD_NM, WEEK_NO, DAY_NO, CUR_CODE, 
 CASH_NO, CASH_NM, CST_CODE, C_CODE_NAME, ITM_CODE, 
 ITM_NM, G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, 
 SUBG_CODE, SUBG_CODE_NM, ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, 
 ALTRNTV_GRP_NM, ITM_TYP_NM, GRP_CLASS_NM, ITM_DSC, SMAN_CODE, 
 SMAN_NM, COL_NO, COL_NM, DRIVER_NO, DRIVER_NM, 
 PRM_CODE, PRM_NM, R_CODE, R_NM, CMP_NO, 
 CMP_NM, W_CODE, W_NM, CC_CODE, CC_NM, 
 PJ_NO, PJ_NM, ACTV_NO, ACTV_NM, KIT_ITM, 
 USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, USE_ATTCH, EXTERNAL_POST, 
 ITM_UNT, ITM_SIZE, ITM_QTY, ITM_FREE_QTY, RT_ITM_QTY, 
 RT_ITM_FREE_QTY, NET_ITM_QTY, NET_ITM_FREE_QTY, SYS_NM, AD_U_ID, 
 AD_U_NM, EXPIRE_DATE, BATCH_NO, CNTRCT_NO, STAND_BY, 
 REF_NO, A_CODE, A_CODE_NM, AC_CODE_DTL, CR_CARD_NO, 
 CR_CARD_NM, INSRNCE_CMP_NO, INS_CMP_NM, INSRNCE_CARD_NO, INSRNCE_CARD_NO_FMLY, 
 PAID_BILL, PAID_U_ID, PAID_U_NM, PAID_DATE, REC_INV_BILL, 
 REC_INV_U_ID, REC_INV_DATE, AUDIT_REF, C_TEL, PTNT_NO, 
 DCTR_NO, DOC_NO_ADMSON, C_CODE_CSH, SAL_AMT_L, SAL_AMT_F, 
 SAL_DSCNT_AMT_L, SAL_DSCNT_AMT_F, SAL_TAX_AMT_L, SAL_TAX_AMT_F, SAL_OTHR_AMT_L, 
 SAL_OTHR_AMT_F, RT_SAL_AMT_L, RT_SAL_AMT_F, RT_SAL_DSCNT_AMT_L, RT_SAL_DSCNT_AMT_F, 
 RT_SAL_TAX_AMT_L, RT_SAL_TAX_AMT_F, RT_SAL_OTHR_AMT_L, RT_SAL_OTHR_AMT_F, NET_SAL_NOT_TAX_OTHR_AMT_L, 
 NET_SAL_NOT_TAX_OTHR_AMT_F, NET_SAL_AMT_L, NET_SAL_AMT_F, NET_BILL_AMT_L, NET_STK_AMT_L, 
 NET_PROFT_AMT_L, NET_BILL_AMT_STK, NET_STK_AMT_STK, NET_PROFT_AMT_STK)
BEQUEATH DEFINER
AS 
WITH TLNG
										    AS
										        (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1)     LNG_NO
										           FROM DUAL)                              
										SELECT  M.YR_NO,
										        M.BRN_NO,
										        M.BRN_NO    ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME), NVL (BRN_FNAME, BRN_LNAME))
										                                 FROM S_BRN
										                                WHERE BRN_NO = M.BRN_NO) BRN_NM,
										        M.DOC_BRN_NO,
										        M.DOC_BRN_NO || ' - ' || (SELECT DECODE (TLNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME)
										                                                 ,NVL (BRN_FNAME, BRN_LNAME))
										                                         FROM S_BRN
										                                        WHERE BRN_NO = M.DOC_BRN_NO) DOC_BRN_NM ,                       
										        M.BILL_DOC_TYPE_NO ,                       
										        M.BILL_DOC_TYPE_NO || ' - ' || (SELECT FLG_DESC
										                                        FROM S_FLAGS
										                                       WHERE FLG_CODE = 'TYPE_NAME'
										                                         AND LANG_NO = TLNG.LNG_NO
										                                         AND FLG_VALUE = M.BILL_DOC_TYPE_NO) BILL_DOC_TYPE,
										        M.DOC_DATE,
										        M.HALF_NO,
										        M.QRTR_NO,
										        M.PRD_NO,
										        (SELECT M.PRD_NO||'-'||NVL( PRD_L_NM,PRD_F_NM) PRD_NM FROM S_PRD_DTL
										                       WHERE M.DOC_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NM,
										        M.WEEK_NO,
										        M.DAY_NO,
										        M.CUR_CODE,
										        M.CASH_NO,
										        M.CASH_NO ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CASH_NAME, CASH_E_NAME), NVL (CASH_E_NAME, CASH_NAME))
										                              FROM CASH_IN_HAND
										                             WHERE CASH_NO = M.CASH_NO) CASH_NM,
										        M.CST_CODE,
										        M.CST_CODE || ' - ' || M.CST_NM C_CODE_NAME,
										        I.I_CODE ITM_CODE,
										        DECODE (TLNG.LNG_NO,1, I.I_NAME, NVL (I.I_E_NAME, I.I_NAME)) ITM_NM,
										        I.G_CODE,
										        I.G_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM))
										                                                  FROM INV_V_GRP_DATA GRP
										                                                 WHERE GRP_TYP = 1 
										                                                   AND GRP.GRP_CODE = I.G_CODE   
										                                                   AND ROWNUM <= 1 ) GRP_CODE_NM,
										        I.MNG_CODE,
										        I.MNG_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                  FROM INV_V_GRP_DATA GRP
										                                                 WHERE GRP_TYP = 2 
										                                                   AND GRP.GRP_CODE = I.MNG_CODE
										                                                   AND ROWNUM <= 1) MNG_CODE_NM,
										        I.SUBG_CODE,
										        I.SUBG_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE  GRP_TYP = 3 
										                                                  AND GRP.GRP_CODE = I.SUBG_CODE 
										                                                  AND ROWNUM <= 1 ) SUBG_CODE_NM,
										        I.ASSISTANT_NO,
										        I.ASSISTANT_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE GRP_TYP = 4 
										                                                  AND GRP.GRP_CODE = I.ASSISTANT_NO
										                                                  AND ROWNUM <= 1   ) ASSTNT_GRP_NM,
										        I.DETAIL_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE  GRP_TYP = 5 
										                                                  AND GRP.GRP_CODE    = I.DETAIL_NO
										                                                  AND ROWNUM <= 1 ) DTL_GRP_NM,
										        I.GROUP_NO|| ' - '||(SELECT DECODE (TLNG.LNG_NO,1, A.GROUP_A_NAME,NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
										                                                   FROM IAS_ALTERNATIVE_GROUP A
										                                                  WHERE A.GROUP_NO = I.GROUP_NO AND ROWNUM <= 1) ALTRNTV_GRP_NM,  
										        I.ITEM_TYPE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, A.IT_A_NAME,NVL (A.IT_E_NAME, A.IT_A_NAME))
										                               FROM ITEM_TYPES A
										                              WHERE A.TYPE_OF_ITEM = I.ITEM_TYPE AND ROWNUM <= 1) ITM_TYP_NM,
										        I.GRP_CLASS_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, A.GRP_L_NAME, NVL (A.GRP_F_NAME, A.GRP_L_NAME))
										                                      FROM IAS_GRP_ITM_LVL A
										                                     WHERE A.GRP_CODE = I.GRP_CLASS_CODE AND ROWNUM <= 1) GRP_CLASS_NM,
										        DECODE (TLNG.LNG_NO,1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC)) ITM_DSC,
										        M.SMAN_CODE,
										        M.SMAN_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (REPRS_A_NAME, REPRS_E_NAME),NVL (REPRS_E_NAME, REPRS_A_NAME))
										                                 FROM SALES_MAN
										                                WHERE REPRS_CODE = M.SMAN_CODE) SMAN_NM,
										        M.COL_NO,
										        M.COL_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (COL_NAME, COL_E_NAME),NVL (COL_E_NAME, COL_NAME))
										                              FROM COLLERCTOR
										                             WHERE COL_NO = M.COL_NO)COL_NM,
										        M.DRIVER_NO,
										        M.DRIVER_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (DRIVER_A_NAME, DRIVER_E_NAME),NVL (DRIVER_E_NAME, DRIVER_A_NAME))
										                                 FROM IAS_DRIVERS
										                                WHERE DRIVER_NO = M.DRIVER_NO) DRIVER_NM,
										        M.PRM_CODE,
										        M.PRM_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (PRM_L_NM, PRM_F_NM),NVL (PRM_F_NM, PRM_L_NM))
										                                FROM IAS_PROMOTERS
										                               WHERE PRM_CODE = M.PRM_CODE) PRM_NM,
										        M.R_CODE,
										        M.R_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (R_A_NAME, R_E_NAME),NVL (R_E_NAME, R_A_NAME))
										                              FROM REGIONS
										                             WHERE R_CODE = M.R_CODE) R_NM,
										        M.CMP_NO,
										        M.CMP_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CMP_LNAME, CMP_FNAME),NVL (CMP_FNAME, CMP_LNAME))
										                              FROM S_CMPNY
										                             WHERE CMP_NO = M.CMP_NO) CMP_NM,
										        M.W_CODE,
										        M.W_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (W_NAME, W_E_NAME), NVL (W_E_NAME, W_NAME))
										                              FROM WAREHOUSE_DETAILS
										                             WHERE W_CODE = M.W_CODE) W_NM,
										        M.CC_CODE,
										        M.CC_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CC_A_NAME, CC_E_NAME),NVL (CC_E_NAME, CC_A_NAME))
										                               FROM COST_CENTERS
										                              WHERE CC_CODE = M.CC_CODE) CC_NM,
										        M.PJ_NO,
										        M.PJ_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (PJ_A_NAME, PJ_E_NAME),NVL (PJ_A_NAME, PJ_E_NAME))
										                             FROM IAS_PROJECTS
										                            WHERE PJ_NO = M.PJ_NO) PJ_NM,
										        M.ACTV_NO,
										        M.ACTV_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (ACTV_A_NAME, ACTV_E_NAME), NVL (ACTV_E_NAME, ACTV_A_NAME))
										                               FROM IAS_ACTVTY
										                              WHERE ACTV_NO = M.ACTV_NO) ACTV_NM,
										        I.KIT_ITM,
										        I.USE_EXP_DATE,
										        I.USE_BATCH_NO,
										        I.USE_SERIALNO,
										        I.USE_ATTCH,
										        M.EXTERNAL_POST ,
										        M.ITM_UNT,
										        M.ITM_SIZE,
										        NVL(M.ITM_QTY,0) ITM_QTY,
										        NVL(M.ITM_FREE_QTY,0)  ITM_FREE_QTY,
										        NVL(M.RT_ITM_QTY,0) RT_ITM_QTY ,
										        NVL(M.RT_ITM_FREE_QTY,0) RT_ITM_FREE_QTY,
										        (NVL(M.ITM_QTY,0) - NVL(M.RT_ITM_QTY,0)) NET_ITM_QTY,
										        (NVL(M.ITM_FREE_QTY,0) - NVL(M.RT_ITM_FREE_QTY,0)) NET_ITM_FREE_QTY,
										        CASE NVL (M.EXTERNAL_POST, 0)
										             WHEN 0
										             THEN
										                 'ERP - Erp Systems'
										             ELSE
										                 (SELECT SYS_NO || ' - ' || SYS_CODE || ' - ' || NOTES
										                    FROM S_ERP_SYSTEM
										                   WHERE SYS_NO = M.EXTERNAL_POST)
										        END  SYS_NM,                                                                   
										        M.AD_U_ID,
										        M.AD_U_ID   ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (U_A_NAME, U_E_NAME), NVL (U_E_NAME, U_A_NAME))
										                                 FROM USER_R
										                                WHERE U_ID = M.AD_U_ID) AD_U_NM ,
										        M.EXPIRE_DATE,
										        M.BATCH_NO,
										        M.CNTRCT_NO,
										        M.STAND_BY,
										        M.REF_NO,
										        M.A_CODE, 
										        M.A_CODE    ||' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (A_NAME, A_NAME_ENG), NVL (A_NAME_ENG, A_NAME))
										                                        FROM ACCOUNT
										                                       WHERE A_CODE = M.A_CODE) A_CODE_NM,
										        M.AC_CODE_DTL,
										        M.CR_CARD_NO,
										        M.CR_CARD_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CR_CARD_NAME, CR_CARD_E_NAME),NVL (CR_CARD_E_NAME, CR_CARD_NAME))
										              FROM CREDIT_CARD_TYPES
										             WHERE CR_CARD_NO = M.CR_CARD_NO) CR_CARD_NM,
										        M.INSRNCE_CMP_NO,
										        M.INSRNCE_CMP_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (INS_CMP_L_NM, INS_CMP_F_NM),NVL (INS_CMP_F_NM, INS_CMP_L_NM))
										                                      FROM IAS_INSRNCE_CMP
										                                     WHERE INS_CMP_NO = M.INSRNCE_CMP_NO) INS_CMP_NM,
										        M.INSRNCE_CARD_NO,
										        M.INSRNCE_CARD_NO_FMLY,
										        M.PAID_BILL,
										        M.PAID_U_ID,
										        M.PAID_U_ID|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (U_A_NAME, U_E_NAME),NVL (U_E_NAME, U_A_NAME))
										                                 FROM USER_R
										                                WHERE U_ID = M.PAID_U_ID) PAID_U_NM,
										        M.PAID_DATE,
										        M.REC_INV_BILL,
										        M.REC_INV_U_ID,
										        M.REC_INV_DATE,
										        M.AUDIT_REF,
										        M.C_TEL,
										        M.PTNT_NO,
										        M.DCTR_NO,
										        M.DOC_NO_ADMSON,
										        M.C_CODE_CSH,
										        M.SAL_AMT_L,
										        M.SAL_AMT_F,
										        M.SAL_DSCNT_AMT_L,
										        M.SAL_DSCNT_AMT_F,
										        M.SAL_TAX_AMT_L,
										        M.SAL_TAX_AMT_F,
										        M.SAL_OTHR_AMT_L,
										        M.SAL_OTHR_AMT_F,
										        M.RT_SAL_AMT_L,
										        M.RT_SAL_AMT_F,
										        M.RT_SAL_DSCNT_AMT_L,
										        M.RT_SAL_DSCNT_AMT_F,
										        M.RT_SAL_TAX_AMT_L,
										        M.RT_SAL_TAX_AMT_F,
										        M.RT_SAL_OTHR_AMT_L,
										        M.RT_SAL_OTHR_AMT_F,
										        ((M.SAL_AMT_L) - (M.SAL_DSCNT_AMT_L))
										             - ((M.RT_SAL_AMT_L) - (M.RT_SAL_DSCNT_AMT_L))
										             NET_SAL_NOT_TAX_OTHR_AMT_L,
										        ((M.SAL_AMT_F) - (M.SAL_DSCNT_AMT_F))
										             - ((M.RT_SAL_AMT_F) - (M.RT_SAL_DSCNT_AMT_F))
										             NET_SAL_NOT_TAX_OTHR_AMT_F,
										        ((M.SAL_AMT_L)
										           - (M.SAL_DSCNT_AMT_L)
										           + (M.SAL_TAX_AMT_L)
										           + (M.SAL_OTHR_AMT_L))
										        - ((M.RT_SAL_AMT_L)
										           - (M.RT_SAL_DSCNT_AMT_L)
										           + (M.RT_SAL_TAX_AMT_L)
										           + (M.RT_SAL_OTHR_AMT_L))      NET_SAL_AMT_L,
										        ((M.SAL_AMT_F)
										           - (M.SAL_DSCNT_AMT_F)
										           + (M.SAL_TAX_AMT_F)
										           + (M.SAL_OTHR_AMT_F))
										        -((M.RT_SAL_AMT_F)
										            - (M.RT_SAL_DSCNT_AMT_F)
										            + (M.RT_SAL_TAX_AMT_F)
										            + (M.RT_SAL_OTHR_AMT_F))      NET_SAL_AMT_F,
										        M.NET_BILL_AMT_L   NET_BILL_AMT_L,
										        M.NET_STK_AMT_L   NET_STK_AMT_L,
										        M.NET_BILL_AMT_L - M.NET_STK_AMT_L    NET_PROFT_AMT_L,
										        M.NET_BILL_AMT_STK,
										        M.NET_STK_AMT_STK,
										        M.NET_BILL_AMT_STK - M.NET_STK_AMT_STK  NET_PROFT_AMT_STK
										    FROM (SELECT M.BILL_DOC_TYPE
										             BILL_DOC_TYPE_NO
										        ,M.BRN_YEAR
										             YR_NO
										        ,M.BRN_NO
										        ,NVL (M.DOC_BRN_NO, M.BRN_NO)
										             DOC_BRN_NO
										        ,M.AD_U_ID
										        ,D.EXPIRE_DATE
										        ,D.BATCH_NO
										        ,M.A_CODE
										        ,M.AC_CODE_DTL
										        ,M.CR_CARD_NO
										        ,M.INSRNCE_CMP_NO
										        ,M.INSRNCE_CARD_NO
										        ,M.INSRNCE_CARD_NO_FMLY
										        ,M.CNTRCT_NO
										        ,M.STAND_BY
										        ,M.REF_NO
										        ,M.PAID_BILL
										        ,M.PAID_U_ID
										        ,M.PAID_DATE
										        ,M.REC_INV_BILL
										        ,M.REC_INV_U_ID
										        ,M.REC_INV_DATE
										        ,M.AUDIT_REF
										        ,M.C_TEL
										        ,M.PTNT_NO
										        ,M.DCTR_NO
										        ,M.DOC_NO_ADMSON
										        ,M.C_CODE_CSH
										        ,M.BILL_DATE DOC_DATE
										        ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
										             HALF_NO
										        ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
										             QRTR_NO
										        ,(SELECT PRD_NO FROM S_PRD_DTL
										                       WHERE M.BILL_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NO
										        ,TO_CHAR (M.BILL_DATE, 'WW')
										             WEEK_NO
										        ,TO_CHAR (M.BILL_DATE, 'DD')
										             DAY_NO
										        ,M.BILL_CURRENCY
										             CUR_CODE
										        ,M.CASH_NO
										        ,M.C_CODE
										             CST_CODE
										        ,M.C_NAME
										             CST_NM
										        ,D.I_CODE
										             ITM_CODE
										        ,M.REP_CODE
										             SMAN_CODE
										        ,M.COL_NO
										        ,M.DRIVER_NO
										        ,M.PRM_CODE
										        ,M.R_CODE
										        ,D.CMP_NO
										        ,D.W_CODE
										        ,D.CC_CODE
										        ,D.PJ_NO
										        ,D.ACTV_NO
										        ,D.EXTERNAL_POST
										        ,IAS_ITM_PKG.GET_ICODE_MIN_UNIT (D.I_CODE)
										             ITM_UNT
										        ,1
										             ITM_SIZE
										        ,ROUND (NVL (D.P_QTY, 0), 4)
										             ITM_QTY
										        ,ROUND (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1), 4)
										             ITM_FREE_QTY
										        ,0
										             RT_ITM_QTY
										        ,0
										             RT_ITM_FREE_QTY
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_AMT_L
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_AMT_F
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_DSCNT_AMT_L
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_DSCNT_AMT_F
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_TAX_AMT_L
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_TAX_AMT_F
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_OTHR_AMT_L
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_OTHR_AMT_F
										        ,0
										             RT_SAL_AMT_L
										        ,0
										             RT_SAL_AMT_F
										        ,0
										             RT_SAL_DSCNT_AMT_L
										        ,0
										             RT_SAL_DSCNT_AMT_F
										        ,0
										             RT_SAL_TAX_AMT_L
										        ,0
										             RT_SAL_TAX_AMT_F
										        ,0
										             RT_SAL_OTHR_AMT_L
										        ,0
										             RT_SAL_OTHR_AMT_F
										        ,ROUND (((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0)) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)) ,4)
										             NET_BILL_AMT_L
										        ,ROUND (((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))* NVL (D.STK_COST, 0)* NVL (M.STOCK_RATE, 1)) ,4)
										             NET_STK_AMT_L
										        ,ROUND (((  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)) / NVL (M.STOCK_RATE, 1)) ,4)
										             NET_BILL_AMT_STK
										        ,ROUND ( ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4)
										             NET_STK_AMT_STK
										    FROM IAS_BILL_MST M, IAS_BILL_DTL D 
										   WHERE M.BILL_SER = D.BILL_SER         
										UNION ALL
										  SELECT M.RT_BILL_DOC_TYPE
										             BILL_DOC_TYPE_NO
										        ,M.BRN_YEAR
										             YR_NO
										        ,M.BRN_NO
										        ,NVL (M.DOC_BRN_NO, M.BRN_NO)
										             DOC_BRN_NO
										        ,M.AD_U_ID
										        ,D.EXPIRE_DATE
										        ,D.BATCH_NO
										        ,M.A_CODE
										        ,M.AC_CODE_DTL
										        ,M.CR_CARD_NO
										        ,M.INSRNCE_CMP_NO
										        ,M.INSRNCE_CARD_NO
										        ,M.INSRNCE_CARD_NO_FMLY
										        ,NULL
										             CNTRCT_NO
										        ,M.STAND_BY
										        ,M.REF_NO
										        ,NULL
										             PAID_BILL
										        ,M.PAID_U_ID
										        ,M.PAID_DATE
										        ,NULL
										             REC_INV_BILL
										        ,M.REC_INV_U_ID
										        ,M.REC_INV_DATE
										        ,M.AUDIT_REF
										        ,M.C_TEL
										        ,M.PTNT_NO
										        ,M.DCTR_NO
										        ,M.DOC_NO_ADMSON
										        ,M.C_CODE_CSH
										        ,M.RT_BILL_DATE
										             DOC_DATE
										        ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
										             HALF_NO
										        ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
										             QRTR_NO
										        ,(SELECT PRD_NO FROM S_PRD_DTL
										                       WHERE M.RT_BILL_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NO
										        ,TO_CHAR (M.RT_BILL_DATE, 'WW')
										             WEEK_NO
										        ,TO_CHAR (M.RT_BILL_DATE, 'DD')
										             DAY_NO
										        ,M.RT_BILL_CURRENCY
										             CUR_CODE
										        ,M.CASH_NO
										        ,M.C_CODE
										             CST_CODE
										        ,M.C_NAME
										             CST_NM
										        ,D.I_CODE
										             ITM_CODE
										        ,M.REP_CODE
										             SMAN_CODE
										        ,M.COL_NO
										        ,M.DRIVER_NO
										        ,M.PRM_CODE
										        ,M.R_CODE
										        ,D.CMP_NO
										        ,D.W_CODE
										        ,D.CC_CODE
										        ,D.PJ_NO
										        ,D.ACTV_NO
										        ,D.EXTERNAL_POST
										        ,IAS_ITM_PKG.GET_ICODE_MIN_UNIT (D.I_CODE)
										             ITM_UNT
										        ,1
										             ITM_SIZE
										        ,0
										             ITM_QTY
										        ,0
										             ITM_FREE_QTY
										        ,ROUND ((NVL (D.P_QTY, 0)), 4)
										             RT_ITM_QTY
										        ,ROUND ((NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
										             RT_ITM_FREE_QTY
										        ,0
										             SAL_AMT_L
										        ,0
										             SAL_AMT_F
										        ,0
										             SAL_DSCNT_AMT_L
										        ,0
										             SAL_DSCNT_AMT_F
										        ,0
										             SAL_TAX_AMT_L
										        ,0
										             SAL_TAX_AMT_F
										        ,0
										             SAL_OTHR_AMT_L
										        ,0
										             SAL_OTHR_AMT_F
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_AMT_L
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_AMT_F
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_DSCNT_AMT_L
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_DSCNT_AMT_F
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_TAX_AMT_L
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_TAX_AMT_F
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_OTHR_AMT_L
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_OTHR_AMT_F
										        ,  ROUND (
										                (
										                     (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
										                   * NVL (D.I_QTY, 0)
										                   * NVL (M.RT_BILL_RATE, 1))
										              ,4)
										         * -1
										             NET_BILL_AMT_L
										        ,  ROUND (
										                (
										                     (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
										                   * NVL (D.STK_COST, 0)
										                   * NVL (M.STOCK_RATE, 1))
										              ,4)
										         * -1
										             NET_STK_AMT_L
										        ,  ROUND (
										                (
										                     (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
										                      * NVL (D.I_QTY, 0)
										                      * NVL (M.RT_BILL_RATE, 1))
										                   / NVL (M.STOCK_RATE, 1))
										              ,4)
										         * -1
										             NET_BILL_AMT_STK
										        ,ROUND ( ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4) * -1
										             NET_STK_AMT_STK
										    FROM IAS_RT_BILL_MST M, IAS_RT_BILL_DTL D 
										   WHERE M.RT_BILL_SER = D.RT_BILL_SER ) M,TLNG,
										         IAS_ITM_MST I
										   WHERE M.ITM_CODE = I.I_CODE;


--
-- ARS_XLS_KPI_SALES_VW_YR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.ARS_XLS_KPI_SALES_VW_YR
(YR_NO, BRN_NO, BRN_NM, DOC_BRN_NO, DOC_BRN_NM, 
 BILL_DOC_TYPE_NO, BILL_DOC_TYPE, DOC_DATE, HALF_NO, QRTR_NO, 
 PRD_NO, PRD_NM, WEEK_NO, DAY_NO, CUR_CODE, 
 CASH_NO, CASH_NM, CST_CODE, C_CODE_NAME, ITM_CODE, 
 ITM_NM, G_CODE, GRP_CODE_NM, MNG_CODE, MNG_CODE_NM, 
 SUBG_CODE, SUBG_CODE_NM, ASSISTANT_NO, ASSTNT_GRP_NM, DTL_GRP_NM, 
 ALTRNTV_GRP_NM, ITM_TYP_NM, GRP_CLASS_NM, ITM_DSC, SMAN_CODE, 
 SMAN_NM, COL_NO, COL_NM, DRIVER_NO, DRIVER_NM, 
 PRM_CODE, PRM_NM, R_CODE, R_NM, CMP_NO, 
 CMP_NM, W_CODE, W_NM, CC_CODE, CC_NM, 
 PJ_NO, PJ_NM, ACTV_NO, ACTV_NM, KIT_ITM, 
 USE_EXP_DATE, USE_BATCH_NO, USE_SERIALNO, USE_ATTCH, EXTERNAL_POST, 
 ITM_UNT, ITM_SIZE, ITM_QTY, ITM_FREE_QTY, RT_ITM_QTY, 
 RT_ITM_FREE_QTY, NET_ITM_QTY, NET_ITM_FREE_QTY, SYS_NM, AD_U_ID, 
 AD_U_NM, EXPIRE_DATE, BATCH_NO, CNTRCT_NO, STAND_BY, 
 REF_NO, A_CODE, A_CODE_NM, AC_CODE_DTL, CR_CARD_NO, 
 CR_CARD_NM, INSRNCE_CMP_NO, INS_CMP_NM, INSRNCE_CARD_NO, INSRNCE_CARD_NO_FMLY, 
 PAID_BILL, PAID_U_ID, PAID_U_NM, PAID_DATE, REC_INV_BILL, 
 REC_INV_U_ID, REC_INV_DATE, AUDIT_REF, C_TEL, PTNT_NO, 
 DCTR_NO, DOC_NO_ADMSON, C_CODE_CSH, SAL_AMT_L, SAL_AMT_F, 
 SAL_DSCNT_AMT_L, SAL_DSCNT_AMT_F, SAL_TAX_AMT_L, SAL_TAX_AMT_F, SAL_OTHR_AMT_L, 
 SAL_OTHR_AMT_F, RT_SAL_AMT_L, RT_SAL_AMT_F, RT_SAL_DSCNT_AMT_L, RT_SAL_DSCNT_AMT_F, 
 RT_SAL_TAX_AMT_L, RT_SAL_TAX_AMT_F, RT_SAL_OTHR_AMT_L, RT_SAL_OTHR_AMT_F, NET_SAL_NOT_TAX_OTHR_AMT_L, 
 NET_SAL_NOT_TAX_OTHR_AMT_F, NET_SAL_AMT_L, NET_SAL_AMT_F, NET_BILL_AMT_L, NET_STK_AMT_L, 
 NET_PROFT_AMT_L, NET_BILL_AMT_STK, NET_STK_AMT_STK, NET_PROFT_AMT_STK)
BEQUEATH DEFINER
AS 
WITH TLNG
										    AS
										        (SELECT NVL (IAS_PRMTR_PKG.GETPVAL (P_PRMTR => 'LANG_DFLT'), 1)     LNG_NO
										           FROM DUAL)                              
										SELECT  M.YR_NO,
										        M.BRN_NO,
										        M.BRN_NO    ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME), NVL (BRN_FNAME, BRN_LNAME))
										                                 FROM S_BRN
										                                WHERE BRN_NO = M.BRN_NO) BRN_NM,
										        M.DOC_BRN_NO,
										        M.DOC_BRN_NO || ' - ' || (SELECT DECODE (TLNG.LNG_NO,1, NVL (BRN_LNAME, BRN_FNAME)
										                                                 ,NVL (BRN_FNAME, BRN_LNAME))
										                                         FROM S_BRN
										                                        WHERE BRN_NO = M.DOC_BRN_NO) DOC_BRN_NM ,                       
										        M.BILL_DOC_TYPE_NO ,                       
										        M.BILL_DOC_TYPE_NO || ' - ' || (SELECT FLG_DESC
										                                        FROM S_FLAGS
										                                       WHERE FLG_CODE = 'TYPE_NAME'
										                                         AND LANG_NO = TLNG.LNG_NO
										                                         AND FLG_VALUE = M.BILL_DOC_TYPE_NO) BILL_DOC_TYPE,
										        M.DOC_DATE,
										        M.HALF_NO,
										        M.QRTR_NO,
										        M.PRD_NO,
										        (SELECT M.PRD_NO||'-'||NVL( PRD_L_NM,PRD_F_NM) PRD_NM FROM S_PRD_DTL
										                       WHERE M.DOC_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NM,
										        M.WEEK_NO,
										        M.DAY_NO,
										        M.CUR_CODE,
										        M.CASH_NO,
										        M.CASH_NO ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CASH_NAME, CASH_E_NAME), NVL (CASH_E_NAME, CASH_NAME))
										                              FROM CASH_IN_HAND
										                             WHERE CASH_NO = M.CASH_NO) CASH_NM,
										        M.CST_CODE,
										        M.CST_CODE || ' - ' || M.CST_NM C_CODE_NAME,
										        I.I_CODE ITM_CODE,
										        DECODE (TLNG.LNG_NO,1, I.I_NAME, NVL (I.I_E_NAME, I.I_NAME)) ITM_NM,
										        I.G_CODE,
										        I.G_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM))
										                                                  FROM INV_V_GRP_DATA GRP
										                                                 WHERE GRP_TYP = 1 
										                                                   AND GRP.GRP_CODE = I.G_CODE   
										                                                   AND ROWNUM <= 1 ) GRP_CODE_NM,
										        I.MNG_CODE,
										        I.MNG_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                  FROM INV_V_GRP_DATA GRP
										                                                 WHERE GRP_TYP = 2 
										                                                   AND GRP.GRP_CODE = I.MNG_CODE
										                                                   AND ROWNUM <= 1) MNG_CODE_NM,
										        I.SUBG_CODE,
										        I.SUBG_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE  GRP_TYP = 3 
										                                                  AND GRP.GRP_CODE = I.SUBG_CODE 
										                                                  AND ROWNUM <= 1 ) SUBG_CODE_NM,
										        I.ASSISTANT_NO,
										        I.ASSISTANT_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE GRP_TYP = 4 
										                                                  AND GRP.GRP_CODE = I.ASSISTANT_NO
										                                                  AND ROWNUM <= 1   ) ASSTNT_GRP_NM,
										        I.DETAIL_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (GRP.GRP_L_NM, GRP.GRP_F_NM), NVL (GRP.GRP_F_NM, GRP.GRP_L_NM)) 
										                                                 FROM INV_V_GRP_DATA GRP
										                                                WHERE  GRP_TYP = 5 
										                                                  AND GRP.GRP_CODE    = I.DETAIL_NO
										                                                  AND ROWNUM <= 1 ) DTL_GRP_NM,
										        I.GROUP_NO|| ' - '||(SELECT DECODE (TLNG.LNG_NO,1, A.GROUP_A_NAME,NVL (A.GROUP_E_NAME, A.GROUP_A_NAME))
										                                                   FROM IAS_ALTERNATIVE_GROUP A
										                                                  WHERE A.GROUP_NO = I.GROUP_NO AND ROWNUM <= 1) ALTRNTV_GRP_NM,  
										        I.ITEM_TYPE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, A.IT_A_NAME,NVL (A.IT_E_NAME, A.IT_A_NAME))
										                               FROM ITEM_TYPES A
										                              WHERE A.TYPE_OF_ITEM = I.ITEM_TYPE AND ROWNUM <= 1) ITM_TYP_NM,
										        I.GRP_CLASS_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, A.GRP_L_NAME, NVL (A.GRP_F_NAME, A.GRP_L_NAME))
										                                      FROM IAS_GRP_ITM_LVL A
										                                     WHERE A.GRP_CODE = I.GRP_CLASS_CODE AND ROWNUM <= 1) GRP_CLASS_NM,
										        DECODE (TLNG.LNG_NO,1, I.I_DESC,NVL (I.I_F_DESC, I.I_DESC)) ITM_DSC,
										        M.SMAN_CODE,
										        M.SMAN_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (REPRS_A_NAME, REPRS_E_NAME),NVL (REPRS_E_NAME, REPRS_A_NAME))
										                                 FROM SALES_MAN
										                                WHERE REPRS_CODE = M.SMAN_CODE) SMAN_NM,
										        M.COL_NO,
										        M.COL_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (COL_NAME, COL_E_NAME),NVL (COL_E_NAME, COL_NAME))
										                              FROM COLLERCTOR
										                             WHERE COL_NO = M.COL_NO)COL_NM,
										        M.DRIVER_NO,
										        M.DRIVER_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (DRIVER_A_NAME, DRIVER_E_NAME),NVL (DRIVER_E_NAME, DRIVER_A_NAME))
										                                 FROM IAS_DRIVERS
										                                WHERE DRIVER_NO = M.DRIVER_NO) DRIVER_NM,
										        M.PRM_CODE,
										        M.PRM_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (PRM_L_NM, PRM_F_NM),NVL (PRM_F_NM, PRM_L_NM))
										                                FROM IAS_PROMOTERS
										                               WHERE PRM_CODE = M.PRM_CODE) PRM_NM,
										        M.R_CODE,
										        M.R_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (R_A_NAME, R_E_NAME),NVL (R_E_NAME, R_A_NAME))
										                              FROM REGIONS
										                             WHERE R_CODE = M.R_CODE) R_NM,
										        M.CMP_NO,
										        M.CMP_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CMP_LNAME, CMP_FNAME),NVL (CMP_FNAME, CMP_LNAME))
										                              FROM S_CMPNY
										                             WHERE CMP_NO = M.CMP_NO) CMP_NM,
										        M.W_CODE,
										        M.W_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (W_NAME, W_E_NAME), NVL (W_E_NAME, W_NAME))
										                              FROM WAREHOUSE_DETAILS
										                             WHERE W_CODE = M.W_CODE) W_NM,
										        M.CC_CODE,
										        M.CC_CODE|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CC_A_NAME, CC_E_NAME),NVL (CC_E_NAME, CC_A_NAME))
										                               FROM COST_CENTERS
										                              WHERE CC_CODE = M.CC_CODE) CC_NM,
										        M.PJ_NO,
										        M.PJ_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (PJ_A_NAME, PJ_E_NAME),NVL (PJ_A_NAME, PJ_E_NAME))
										                             FROM IAS_PROJECTS
										                            WHERE PJ_NO = M.PJ_NO) PJ_NM,
										        M.ACTV_NO,
										        M.ACTV_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (ACTV_A_NAME, ACTV_E_NAME), NVL (ACTV_E_NAME, ACTV_A_NAME))
										                               FROM IAS_ACTVTY
										                              WHERE ACTV_NO = M.ACTV_NO) ACTV_NM,
										        I.KIT_ITM,
										        I.USE_EXP_DATE,
										        I.USE_BATCH_NO,
										        I.USE_SERIALNO,
										        I.USE_ATTCH,
										        M.EXTERNAL_POST ,
										        M.ITM_UNT,
										        M.ITM_SIZE,
										        NVL(M.ITM_QTY,0) ITM_QTY,
										        NVL(M.ITM_FREE_QTY,0)  ITM_FREE_QTY,
										        NVL(M.RT_ITM_QTY,0) RT_ITM_QTY ,
										        NVL(M.RT_ITM_FREE_QTY,0) RT_ITM_FREE_QTY,
										        (NVL(M.ITM_QTY,0) - NVL(M.RT_ITM_QTY,0)) NET_ITM_QTY,
										        (NVL(M.ITM_FREE_QTY,0) - NVL(M.RT_ITM_FREE_QTY,0)) NET_ITM_FREE_QTY,
										        CASE NVL (M.EXTERNAL_POST, 0)
										             WHEN 0
										             THEN
										                 'ERP - Erp Systems'
										             ELSE
										                 (SELECT SYS_NO || ' - ' || SYS_CODE || ' - ' || NOTES
										                    FROM S_ERP_SYSTEM
										                   WHERE SYS_NO = M.EXTERNAL_POST)
										        END  SYS_NM,                                                                   
										        M.AD_U_ID,
										        M.AD_U_ID   ||' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (U_A_NAME, U_E_NAME), NVL (U_E_NAME, U_A_NAME))
										                                 FROM USER_R
										                                WHERE U_ID = M.AD_U_ID) AD_U_NM ,
										        M.EXPIRE_DATE,
										        M.BATCH_NO,
										        M.CNTRCT_NO,
										        M.STAND_BY,
										        M.REF_NO,
										        M.A_CODE, 
										        M.A_CODE    ||' - '|| (SELECT DECODE (TLNG.LNG_NO, 1, NVL (A_NAME, A_NAME_ENG), NVL (A_NAME_ENG, A_NAME))
										                                        FROM ACCOUNT
										                                       WHERE A_CODE = M.A_CODE) A_CODE_NM,
										        M.AC_CODE_DTL,
										        M.CR_CARD_NO,
										        M.CR_CARD_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (CR_CARD_NAME, CR_CARD_E_NAME),NVL (CR_CARD_E_NAME, CR_CARD_NAME))
										              FROM CREDIT_CARD_TYPES
										             WHERE CR_CARD_NO = M.CR_CARD_NO) CR_CARD_NM,
										        M.INSRNCE_CMP_NO,
										        M.INSRNCE_CMP_NO|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (INS_CMP_L_NM, INS_CMP_F_NM),NVL (INS_CMP_F_NM, INS_CMP_L_NM))
										                                      FROM IAS_INSRNCE_CMP
										                                     WHERE INS_CMP_NO = M.INSRNCE_CMP_NO) INS_CMP_NM,
										        M.INSRNCE_CARD_NO,
										        M.INSRNCE_CARD_NO_FMLY,
										        M.PAID_BILL,
										        M.PAID_U_ID,
										        M.PAID_U_ID|| ' - '|| (SELECT DECODE (TLNG.LNG_NO,1, NVL (U_A_NAME, U_E_NAME),NVL (U_E_NAME, U_A_NAME))
										                                 FROM USER_R
										                                WHERE U_ID = M.PAID_U_ID) PAID_U_NM,
										        M.PAID_DATE,
										        M.REC_INV_BILL,
										        M.REC_INV_U_ID,
										        M.REC_INV_DATE,
										        M.AUDIT_REF,
										        M.C_TEL,
										        M.PTNT_NO,
										        M.DCTR_NO,
										        M.DOC_NO_ADMSON,
										        M.C_CODE_CSH,
										        M.SAL_AMT_L,
										        M.SAL_AMT_F,
										        M.SAL_DSCNT_AMT_L,
										        M.SAL_DSCNT_AMT_F,
										        M.SAL_TAX_AMT_L,
										        M.SAL_TAX_AMT_F,
										        M.SAL_OTHR_AMT_L,
										        M.SAL_OTHR_AMT_F,
										        M.RT_SAL_AMT_L,
										        M.RT_SAL_AMT_F,
										        M.RT_SAL_DSCNT_AMT_L,
										        M.RT_SAL_DSCNT_AMT_F,
										        M.RT_SAL_TAX_AMT_L,
										        M.RT_SAL_TAX_AMT_F,
										        M.RT_SAL_OTHR_AMT_L,
										        M.RT_SAL_OTHR_AMT_F,
										        ((M.SAL_AMT_L) - (M.SAL_DSCNT_AMT_L))
										             - ((M.RT_SAL_AMT_L) - (M.RT_SAL_DSCNT_AMT_L))
										             NET_SAL_NOT_TAX_OTHR_AMT_L,
										        ((M.SAL_AMT_F) - (M.SAL_DSCNT_AMT_F))
										             - ((M.RT_SAL_AMT_F) - (M.RT_SAL_DSCNT_AMT_F))
										             NET_SAL_NOT_TAX_OTHR_AMT_F,
										        ((M.SAL_AMT_L)
										           - (M.SAL_DSCNT_AMT_L)
										           + (M.SAL_TAX_AMT_L)
										           + (M.SAL_OTHR_AMT_L))
										        - ((M.RT_SAL_AMT_L)
										           - (M.RT_SAL_DSCNT_AMT_L)
										           + (M.RT_SAL_TAX_AMT_L)
										           + (M.RT_SAL_OTHR_AMT_L))      NET_SAL_AMT_L,
										        ((M.SAL_AMT_F)
										           - (M.SAL_DSCNT_AMT_F)
										           + (M.SAL_TAX_AMT_F)
										           + (M.SAL_OTHR_AMT_F))
										        -((M.RT_SAL_AMT_F)
										            - (M.RT_SAL_DSCNT_AMT_F)
										            + (M.RT_SAL_TAX_AMT_F)
										            + (M.RT_SAL_OTHR_AMT_F))      NET_SAL_AMT_F,
										        M.NET_BILL_AMT_L   NET_BILL_AMT_L,
										        M.NET_STK_AMT_L   NET_STK_AMT_L,
										        M.NET_BILL_AMT_L - M.NET_STK_AMT_L    NET_PROFT_AMT_L,
										        M.NET_BILL_AMT_STK,
										        M.NET_STK_AMT_STK,
										        M.NET_BILL_AMT_STK - M.NET_STK_AMT_STK  NET_PROFT_AMT_STK
										    FROM (SELECT M.BILL_DOC_TYPE
										             BILL_DOC_TYPE_NO
										        ,M.BRN_YEAR
										             YR_NO
										        ,M.BRN_NO
										        ,NVL (M.DOC_BRN_NO, M.BRN_NO)
										             DOC_BRN_NO
										        ,M.AD_U_ID
										        ,D.EXPIRE_DATE
										        ,D.BATCH_NO
										        ,M.A_CODE
										        ,M.AC_CODE_DTL
										        ,M.CR_CARD_NO
										        ,M.INSRNCE_CMP_NO
										        ,M.INSRNCE_CARD_NO
										        ,M.INSRNCE_CARD_NO_FMLY
										        ,M.CNTRCT_NO
										        ,M.STAND_BY
										        ,M.REF_NO
										        ,M.PAID_BILL
										        ,M.PAID_U_ID
										        ,M.PAID_DATE
										        ,M.REC_INV_BILL
										        ,M.REC_INV_U_ID
										        ,M.REC_INV_DATE
										        ,M.AUDIT_REF
										        ,M.C_TEL
										        ,M.PTNT_NO
										        ,M.DCTR_NO
										        ,M.DOC_NO_ADMSON
										        ,M.C_CODE_CSH
										        ,M.BILL_DATE DOC_DATE
										        ,ROUND (TO_CHAR (M.BILL_DATE, 'Q') / 2)
										             HALF_NO
										        ,ROUND (TO_CHAR (M.BILL_DATE, 'Q'))
										             QRTR_NO
										        ,(SELECT PRD_NO FROM S_PRD_DTL
										                       WHERE M.BILL_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NO
										        ,TO_CHAR (M.BILL_DATE, 'WW')
										             WEEK_NO
										        ,TO_CHAR (M.BILL_DATE, 'DD')
										             DAY_NO
										        ,M.BILL_CURRENCY
										             CUR_CODE
										        ,M.CASH_NO
										        ,M.C_CODE
										             CST_CODE
										        ,M.C_NAME
										             CST_NM
										        ,D.I_CODE
										             ITM_CODE
										        ,M.REP_CODE
										             SMAN_CODE
										        ,M.COL_NO
										        ,M.DRIVER_NO
										        ,M.PRM_CODE
										        ,M.R_CODE
										        ,D.CMP_NO
										        ,D.W_CODE
										        ,D.CC_CODE
										        ,D.PJ_NO
										        ,D.ACTV_NO
										        ,D.EXTERNAL_POST
										        ,IAS_ITM_PKG.GET_ICODE_MIN_UNIT (D.I_CODE)
										             ITM_UNT
										        ,1
										             ITM_SIZE
										        ,ROUND (NVL (D.P_QTY, 0), 4)
										             ITM_QTY
										        ,ROUND (NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1), 4)
										             ITM_FREE_QTY
										        ,0
										             RT_ITM_QTY
										        ,0
										             RT_ITM_FREE_QTY
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_AMT_L
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_AMT_F
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_DSCNT_AMT_L
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_DSCNT_AMT_F
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_TAX_AMT_L
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_TAX_AMT_F
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)), 4)
										             SAL_OTHR_AMT_L
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             SAL_OTHR_AMT_F
										        ,0
										             RT_SAL_AMT_L
										        ,0
										             RT_SAL_AMT_F
										        ,0
										             RT_SAL_DSCNT_AMT_L
										        ,0
										             RT_SAL_DSCNT_AMT_F
										        ,0
										             RT_SAL_TAX_AMT_L
										        ,0
										             RT_SAL_TAX_AMT_F
										        ,0
										             RT_SAL_OTHR_AMT_L
										        ,0
										             RT_SAL_OTHR_AMT_F
										        ,ROUND (((NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0)) * NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)) ,4)
										             NET_BILL_AMT_L
										        ,ROUND (((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))* NVL (D.STK_COST, 0)* NVL (M.STOCK_RATE, 1)) ,4)
										             NET_STK_AMT_L
										        ,ROUND (((  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))* NVL (D.I_QTY, 0) * NVL (M.BILL_RATE, 1)) / NVL (M.STOCK_RATE, 1)) ,4)
										             NET_BILL_AMT_STK
										        ,ROUND ( ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4)
										             NET_STK_AMT_STK
										    FROM IAS_V_BILL_MST_YR M, IAS_V_BILL_DTL_YR D 
										   WHERE M.BILL_SER = D.BILL_SER         
										UNION ALL
										  SELECT M.RT_BILL_DOC_TYPE
										             BILL_DOC_TYPE_NO
										        ,M.BRN_YEAR
										             YR_NO
										        ,M.BRN_NO
										        ,NVL (M.DOC_BRN_NO, M.BRN_NO)
										             DOC_BRN_NO
										        ,M.AD_U_ID
										        ,D.EXPIRE_DATE
										        ,D.BATCH_NO
										        ,M.A_CODE
										        ,M.AC_CODE_DTL
										        ,M.CR_CARD_NO
										        ,M.INSRNCE_CMP_NO
										        ,M.INSRNCE_CARD_NO
										        ,M.INSRNCE_CARD_NO_FMLY
										        ,NULL
										             CNTRCT_NO
										        ,M.STAND_BY
										        ,M.REF_NO
										        ,NULL
										             PAID_BILL
										        ,M.PAID_U_ID
										        ,M.PAID_DATE
										        ,NULL
										             REC_INV_BILL
										        ,M.REC_INV_U_ID
										        ,M.REC_INV_DATE
										        ,M.AUDIT_REF
										        ,M.C_TEL
										        ,M.PTNT_NO
										        ,M.DCTR_NO
										        ,M.DOC_NO_ADMSON
										        ,M.C_CODE_CSH
										        ,M.RT_BILL_DATE
										             DOC_DATE
										        ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q') / 2)
										             HALF_NO
										        ,ROUND (TO_CHAR (M.RT_BILL_DATE, 'Q'))
										             QRTR_NO
										        ,(SELECT PRD_NO FROM S_PRD_DTL
										                       WHERE M.RT_BILL_DATE BETWEEN F_DATE AND T_DATE AND ROWNUM <=1) PRD_NO
										        ,TO_CHAR (M.RT_BILL_DATE, 'WW')
										             WEEK_NO
										        ,TO_CHAR (M.RT_BILL_DATE, 'DD')
										             DAY_NO
										        ,M.RT_BILL_CURRENCY
										             CUR_CODE
										        ,M.CASH_NO
										        ,M.C_CODE
										             CST_CODE
										        ,M.C_NAME
										             CST_NM
										        ,D.I_CODE
										             ITM_CODE
										        ,M.REP_CODE
										             SMAN_CODE
										        ,M.COL_NO
										        ,M.DRIVER_NO
										        ,M.PRM_CODE
										        ,M.R_CODE
										        ,D.CMP_NO
										        ,D.W_CODE
										        ,D.CC_CODE
										        ,D.PJ_NO
										        ,D.ACTV_NO
										        ,D.EXTERNAL_POST
										        ,IAS_ITM_PKG.GET_ICODE_MIN_UNIT (D.I_CODE)
										             ITM_UNT
										        ,1
										             ITM_SIZE
										        ,0
										             ITM_QTY
										        ,0
										             ITM_FREE_QTY
										        ,ROUND ((NVL (D.P_QTY, 0)), 4)
										             RT_ITM_QTY
										        ,ROUND ((NVL (D.FREE_QTY, 0) * NVL (D.P_SIZE, 1)), 4)
										             RT_ITM_FREE_QTY
										        ,0
										             SAL_AMT_L
										        ,0
										             SAL_AMT_F
										        ,0
										             SAL_DSCNT_AMT_L
										        ,0
										             SAL_DSCNT_AMT_F
										        ,0
										             SAL_TAX_AMT_L
										        ,0
										             SAL_TAX_AMT_F
										        ,0
										             SAL_OTHR_AMT_L
										        ,0
										             SAL_OTHR_AMT_F
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_AMT_L
										        ,ROUND ( (NVL (D.I_PRICE, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_AMT_F
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_DSCNT_AMT_L
										        ,ROUND ( (NVL (D.DIS_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_DSCNT_AMT_F
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_TAX_AMT_L
										        ,ROUND ( (NVL (D.VAT_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_TAX_AMT_F
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0) * NVL (M.RT_BILL_RATE, 1)), 4)
										             RT_SAL_OTHR_AMT_L
										        ,ROUND ( (NVL (D.OTHR_AMT, 0) * NVL (D.I_QTY, 0)), 4)
										             RT_SAL_OTHR_AMT_F
										        ,  ROUND (
										                (
										                     (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
										                   * NVL (D.I_QTY, 0)
										                   * NVL (M.RT_BILL_RATE, 1))
										              ,4)
										         * -1
										             NET_BILL_AMT_L
										        ,  ROUND (
										                (
										                     (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
										                   * NVL (D.STK_COST, 0)
										                   * NVL (M.STOCK_RATE, 1))
										              ,4)
										         * -1
										             NET_STK_AMT_L
										        ,  ROUND (
										                (
										                     (  (NVL (D.I_PRICE, 0) - NVL (D.DIS_AMT, 0))
										                      * NVL (D.I_QTY, 0)
										                      * NVL (M.RT_BILL_RATE, 1))
										                   / NVL (M.STOCK_RATE, 1))
										              ,4)
										         * -1
										             NET_BILL_AMT_STK
										        ,ROUND ( ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0)), 4) * -1
										             NET_STK_AMT_STK
										    FROM IAS_V_RT_BILL_MST_YR M, IAS_V_RT_BILL_DTL_YR D 
										   WHERE M.RT_BILL_SER = D.RT_BILL_SER ) M,TLNG,
										         IAS_ITM_MST I
										   WHERE M.ITM_CODE = I.I_CODE;


--
-- DTS_CST_LMT_SAL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_CST_LMT_SAL
(REP_CODE, C_CODE, F_DATE, T_DATE, LMT_AMT, 
 SALE_AMT)
BEQUEATH DEFINER
AS 
Select S.Rep_Code
         ,C.C_Code
         ,C.F_Date
         ,C.T_Date
         ,C.Amt Lmt_Amt
         ,DTS_GEN_PKG.GET_CST_ALL_SALES_AMT(  P_C_Code=>C.C_CODE ,P_F_DATE =>C.F_Date, P_T_DATE =>C.T_Date) Sale_Amt
     From Ias_Cst_Lmt_Sal C, Dts_V_Sman_Cst S
    Where     C.C_Code = S.C_Code
          And S.Rep_Code = Nvl (Dts_Prmtr_Pkg.Getpval ('REP_CODE'), S.Rep_Code)
          And Exists
                 (Select 1
                    From User_R U, Privilege_Fixed F
                   Where F.U_Id = U.U_Id 
                   And U.Rep_Code = S.Rep_Code 
                   And Nvl (Allw_Excd_Lmt_Sal_Itm, 0) = 0 
                   And Rownum <= 1);


--
-- DTS_GET_CST_CRDT_PRD  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_GET_CST_CRDT_PRD
(SMAN_TYP, REP_CODE, C_CODE, A_CY, U_ID, 
 CHECK_CREDIT_PERIOD, CR_LIMIT, BAL_AMT, V_MIN_IDATE, CRDT_PRD, 
 ALLOW_PRD_AFTR_DUE, F_ACTVDATE, T_ACTV_DATE, AR_ALLOW_SALES_PRV_DR, MAX_BILL_DISC_PER, 
 MAX_BILL_ITM_DISC_PER, PAID_INSTLLMNT_MAN, CRDT_SLS_LEV_NO, CSH_SLS_LEV_NO)
BEQUEATH DEFINER
AS 
SELECT sman_typ, u.rep_code, sm.c_code, ccy.a_cy, u.u_id,
                                      pr.check_credit_period,
                                      dts_gen_pkg.get_cst_lmt (p_c_code      => sm.c_code,
                                                               p_acy         => ccy.a_cy
                                                              ) cr_limit,
                                      (DTS_GEN_PKG.Get_Cst_Trns_bal( P_Bal_Typ =>4,
                                                                      P_C_Code  => ccy.c_code     ,                                                      
                                                                      P_Acy     =>ccy.a_cy   ,
                                                                      P_Rep_Code    =>u.rep_code,                                                       
                                                                      P_Due_Amt_Typ=>0)) bal_amt,
                                      TO_DATE (dts_chk_crdt_prd (sm.c_code,
                                                                 TO_DATE (SYSDATE, 'DD/MM/RRRR'),
                                                                 u.rep_code
                                                                ),
                                               'DD/MM/RRRR'
                                              ) v_min_idate,
                                      Nvl(C.Credit_Period, 0) Crdt_Prd,
                                      DECODE (NVL (pr.ar_chk_prd_aftr_due, 0),
                                              1, NVL (allow_prd_aftr_due, 0),
                                              0
                                             ) allow_prd_aftr_due,
                                      NVL (f_actv_date,
                                           TO_DATE (ys_gen_pkg.get_frst_day, 'DD/MM/RRRR')
                                          ) f_actvdate,
                                      NVL (t_actv_date,
                                           TO_DATE (ys_gen_pkg.get_final_day, 'DD/MM/RRRR')
                                          ) t_actv_date,
                                      (CASE WHEN Nvl (Pr.Ar_Allow_Sales_Prv_Dr, 0)=1 AND Nvl (C.Cst_Allow_Sales_Prv_Dr, 0)=0 THEN 0
                                               ELSE Nvl (Pr.Ar_Allow_Sales_Prv_Dr, 0) END) Ar_Allow_Sales_Prv_Dr,
                                       Case when C.DISC_PER is not null and NVL (pr.inv_dis_lmt, 0)>0 Then Least(nvl(c.DISC_PER,0),NVL (pr.inv_dis_lmt, 0))
                                        else nvl(C.DISC_PER,NVL (pr.inv_dis_lmt,0))  end  max_bill_disc_per,
                                      NVL (inv_dis_lmt_itm, 0) max_bill_itm_disc_per,
                                      NVL (paid_instllmnt_man, 0) paid_instllmnt_man,
                                      ccy.LEV_NO Crdt_Sls_Lev_No,
                                      ccy.LEV_NO_CSH Csh_Sls_Lev_No
                               FROM   customer c,
                                      privilege_fixed pr,
                                      customer_curr ccy,
                                      user_r u,
                                      dts_v_sman_cst sm,
                                      ias_para_ar p
                               WHERE  c.c_code = sm.c_code
                               And Nvl(SM.Sman_Typ,0) In(1,3)
                               AND    u.u_id = NVL (pr.u_id, 0)
                               AND    u.rep_code IS NOT NULL
                               AND    sm.rep_code = u.rep_code
                               AND    ccy.c_code = sm.c_code
                               AND    NVL (ccy.inactive, 0) <> 1
                                AND 1= (CASE WHEN ( NVL(P.Ar_Ac_Link_Type,1) = 1 AND EXISTS(SELECT 1
                                                                     FROM PRIV_ACC
                                                                    WHERE U_ID = U.U_ID
                                                                      AND A_CODE = C.C_A_CODE
                                                                      AND A_CY=ccy.a_cy
                                                                      AND NVL(ADD_FLAG, 0) = 1
                                                                      AND ROWNUM <= 1) ) THEN 1
                                            WHEN (NVL(P.Ar_Ac_Link_Type,1)= 2 AND EXISTS(
                                                                                           SELECT 1
                                                                                             FROM IAS_PRIV_CUSTOMER
                                                                                            WHERE U_ID = U.U_ID
                                                                                              AND C_CODE = C.C_CODE
                                                                                              AND A_CY=ccy.a_cy
                                                                                              AND NVL(ADD_FLAG, 0) = 1
                                                                                              AND ROWNUM <= 1)) THEN 1
                                          ELSE 0
                                          END);


--
-- DTS_MAP_CSTMR_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_MAP_CSTMR_VW
(C_CODE, C_NAME, C_GROUP_CODE, C_GROUP_CODE_NM, C_CLASS_TYP, 
 C_CLASS_TYP_NM, CNTRY_NO, CNTRY_NM, PROV_NO, PROV_NM, 
 CITY_NO, CITY_NM, C_CLASS, C_CLASS_NM, ROUTE_NO, 
 ROUTE_NM, SORTINROUTE, REP_CODE, REP_NM, R_CODE, 
 R_NM, LAT, LNG, CST_TYP, AMT)
BEQUEATH DEFINER
AS 
select "C_CODE","C_NAME","C_GROUP_CODE","C_GROUP_CODE_NM","C_CLASS_TYP","C_CLASS_TYP_NM","CNTRY_NO","CNTRY_NM","PROV_NO","PROV_NM","CITY_NO","CITY_NM","C_CLASS","C_CLASS_NM","ROUTE_NO","ROUTE_NM","SORTINROUTE","REP_CODE","REP_NM","R_CODE","R_NM","LAT","LNG","CST_TYP","AMT"
     FROM (SELECT C.C_Code,
                  NVL (C_A_Name, '') C_NAME,
                  c.C_GROUP_CODE,
                  C.C_GROUP_CODE || '_' || (SELECT C_GROUP_A_NAME
                                              FROM CUSTOMER_GROUP
                                             WHERE C_GROUP_CODE = c.C_GROUP_CODE AND ROWNUM <= 1)
                     C_GROUP_CODE_NM,
                  c.C_CLASS_TYP,
                  C.C_CLASS_TYP || '_' || (SELECT C_CLASS_TYP_NM
                                             FROM CUSTOMER_CLASS_TYP
                                            WHERE C_CLASS_TYP = c.C_CLASS_TYP AND ROWNUM <= 1)
                     C_CLASS_TYP_NM,
                  C.Cntry_No,
                  C.Cntry_No || '_' || (SELECT CNTRY_A_NAME
                                          FROM CNTRY
                                         WHERE Cntry_No = c.Cntry_No AND ROWNUM <= 1)
                     Cntry_NM,
                  C.Prov_No,
                  Prov_No || '_' || (SELECT PROV_A_NAME
                                       FROM IAS_PROVINCES
                                      WHERE Prov_No = c.Prov_No AND ROWNUM <= 1)
                     Prov_NM,
                  C.City_No,
                  C.City_No || '_' || (SELECT CITY_A_NAME
                                         FROM CITIES
                                        WHERE City_No = c.City_No AND ROWNUM <= 1)
                     City_NM,
                  C.C_Class,
                  C.C_Class || '_' || (SELECT C_CLASS_NAME
                                         FROM CUSTOMER_CLASS
                                        WHERE C_Class = c.C_Class AND ROWNUM <= 1)
                     C_Class_NM,
                  C.Route_No,
                  C.Route_No || '_' || (SELECT ROUTE_A_NAME
                                          FROM IAS_ROUTE_MST
                                         WHERE Route_No = c.Route_No AND ROWNUM <= 1)
                     Route_NM,
                  C.Sortinroute,
                  S.Rep_Code,
                  S.Rep_Code || '_' || (SELECT REPRS_A_NAME
                                          FROM sales_man
                                         WHERE reprs_code = s.rep_code AND ROWNUM <= 1)
                     Rep_NM,
                  C.R_CODE,
                  C.R_CODE || '_' || (SELECT R_A_NAME
                                        FROM REGIONS
                                       WHERE R_CODE = C.R_CODE AND ROWNUM <= 1)
                     R_NM,
                  TO_NUMBER (NVL (Latitude, NVL ( (SUBSTR (Gps, 1, INSTR (Gps, ',') - 1)), '0'))) lat,
                  TO_NUMBER (NVL (Longitude, NVL ( (SUBSTR (Gps, INSTR (Gps, ',') + 1)), '0'))) lng,
                  1 cst_typ,
                  0 AMT
             FROM Customer C, Dts_V_Sman_Cst S
            WHERE C.C_Code = S.C_Code AND NVL (C.Inactive, 0) = 0 AND S.Rep_Code IS NOT NULL --:P_WHR_INTL
                                                                                            )
    WHERE lat <> 0 AND lng <> 0;


--
-- DTS_V_ALL_TAX_ITM  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ALL_TAX_ITM
(REP_CODE, I_CODE, TAX_NO, CLC_TYP_NO, AGNCY_NO, 
 TAX_CLC_ORDR, TAX_PRCNT)
BEQUEATH DEFINER
AS 
Select 
                                   Rep_Code,
                                   I_Code,
                                   Tax_No,
                                   Clc_Typ_No,
                                   Agncy_No,                                   
                                   TAX_CLC_ORDR,
                                   case when nvl(Max_tax_clc_ordr,0)>1 then
                                         NVL(Tax_Prcnt, 0) * ((((SUM(NVL(Tax_Prcnt, 0)) OVER (PARTITION BY Rep_Code,I_Code,Clc_Typ_No ORDER BY NVL(TAX_CLC_ORDR, 1)) - SUM(NVL(Tax_Prcnt, 0)) OVER ( PARTITION BY Rep_Code,I_Code,Clc_Typ_No,NVL(TAX_CLC_ORDR, 1)))) / 100) + 1) 
                                         Else Tax_Prcnt end Tax_Prcnt
                                   from (
                                   Select Distinct M.Rep_Code Rep_Code,
                                                   D.I_Code I_Code,
                                                   Ti.Tax_No Tax_No,
                                                   Tc.Clc_Typ_No Clc_Typ_No,
                                                   Ti.Agncy_No Agncy_No,
                                                   Ti.Tax_Prcnt Tax_Prcnt,
                                                   nvl(Tc.TAX_CLC_ORDR,1) TAX_CLC_ORDR,
                                                   max(nvl(Tc.TAX_CLC_ORDR,0)) over(partition by M.Rep_Code,D.I_Code,Tc.Clc_Typ_No) Max_TAX_CLC_ORDR
                                     From DTS_V_CLC_TAX_TYPE M,
                                          Dts_Grp_Dtl D,
                                          Gnr_Tax_Itm Ti,
                                          Gnr_Tax_Code_Mst Tm,
                                          Gnr_Tax_Code_Dtl Td,
                                          Gnr_Tax_Typ_Clc_Dtl Tc,
                                          Ias_para_gen  p
                                    Where M.Grp_Code = D.Grp_Code
                                          And D.I_Code = Ti.I_Code
                                          And Ti.Tax_No = Tm.Tax_No
                                          And Ti.Tax_No = Td.Tax_No
                                          And Ti.Agncy_No = Td.Agncy_No
                                          And Ti.Tax_No = Tc.Tax_No
                                          And Tm.Tax_No = Td.Tax_No
                                          And Tm.Tax_No = Tc.Tax_No
                                          And Td.Tax_No = Tc.Tax_No
                                          And Nvl (Tm.Inactive, 0) = 0
                                          And Tc.Clc_Typ_No = M.Clc_Typ_No_Tax
                                          and nvl(p.use_vat,0)=1
                                          ) m
                                          order by Rep_Code,I_Code,Clc_Typ_No,TAX_CLC_ORDR;


--
-- DTS_V_GET_CUSTOMER  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_CUSTOMER
(C_CODE, C_A_NAME, C_E_NAME, C_ADDRESS, CNTRY_NO, 
 PROV_NO, CITY_NO, C_CLASS, C_PHONE, C_MOBILE, 
 R_CODE, C_PERSON, CUSTFLLOW, ROUTE_NO, SORTINROUTE, 
 REP_CODE, LATITUDE, LONGITUDE, GPS_COLOR, COL_NO, 
 C_A_CODE, C_TAX_CODE, DRIVER_NO, CREDIT_PERIOD, CSH_CST, 
 CRDT_SLS_LEV_NO, CSH_SLS_LEV_NO, VST_OPN_TYP, C_BARCODE, C_GROUP_CODE, 
 C_DEGREE, CST_EXCPT_QT_PRM_FLG, C_E_MAIL, SEND_MSG, CLC_TYP_NO_TAX, 
 CLC_VAT_PRICE_TYP, CC_CODE, CR_NO, INACTIVE_SALES, ALLOW_UPD_FIXED_PRICE, 
 C_CLASS_VAT, CST_TYP, LMT_ITM_QTY_TYP, PRD_DAY, RPT_QTY_LMT_CNT, 
 DOC_BRN_NO, CST_W_CODE, PJ_NO, ACTV_NO, SND_VRFCT_MSG_FOR_CRDT_BILL)
BEQUEATH DEFINER
AS 
Select C.C_Code,
                          Nvl(C_A_Name, '') C_A_Name,
                          Nvl(C_E_Name, '') C_E_Name,
                          Nvl(C_Address, '') C_Address,
                          Cntry_No,
                          Prov_No,
                          City_No,
                          C.C_Class,
                          Nvl(C_Phone, '') C_Phone,
                          Nvl(C_Mobile, '') C_Mobile,
                          C.R_Code,
                          Nvl(C_Person, '') C_Person,
                          1 Custfllow,
                          Route_No,
                          Sortinroute,
                          S.Rep_Code,
                          Nvl(Latitude, Nvl((Substr(Gps, 1, Instr(Gps, ',') - 1)), '0')) Latitude,
                          Nvl(Longitude, Nvl((Substr(Gps, Instr(Gps, ',') + 1)), '0')) Longitude,
                          '0' Gps_Color,
                          S.Col_No Col_No,
                          C_A_Code,
                          C_Tax_Code,
                          Nvl(Driver_No, 0) Driver_No,
                          Nvl(Credit_Period, 0) Credit_Period,
                          C.Csh_Cst,                          
                          Null  Crdt_Sls_Lev_No,
                          Null Csh_Sls_Lev_No,
                          Nvl(C.Vst_Opn_Typ, -1) Vst_Opn_Typ,
                          C.C_Barcode C_Barcode,
                          Nvl(C.C_Group_Code, 0) C_Group_Code,
                          Nvl(C.C_Degree, 0) C_Degree,
                          Nvl(C.Cst_Excpt_Qt_Prm_Flg, 0) Cst_Excpt_Qt_Prm_Flg,
                          Nvl(C.C_E_Mail, '') C_E_Mail,
                          Nvl(C.Send_Msg, 0) Send_Msg,
                          Decode(Nvl(G.Use_Vat, 0), 1, C.Clc_Typ_No_Tax, Null) Clc_Typ_No_Tax,
                          Decode(Nvl(G.Use_Price_Include_Vat, 0), 1, C.Clc_Vat_Price_Typ, 1) Clc_Vat_Price_Typ,
                          S.CC_CODE,                          
                          c.CR_NO,
                          nvl(c.INACTIVE_SALES,0)INACTIVE_SALES,
                          Decode (R.Cust_Price_Fixed, 1, nvl(Allow_Upd_Fixed_Price,0), 1) Allow_Upd_Fixed_Price,
                          DECODE( NVL(C_CLASS_VAT,1),2,2,3,2,1) C_CLASS_VAT , 
                          1 CST_TYP,
                          Nvl(C.Lmt_Itm_Qty_Typ,0) Lmt_Itm_Qty_Typ,
                          Nvl (C.Prd_Day, 0) Prd_Day,
                          Nvl(C.Rpt_Qty_Lmt_Cnt,1)Rpt_Qty_Lmt_Cnt ,
                          c.CONN_BRN_NO  DOC_BRN_NO,
                          S.CST_W_CODE, 
                          C.PJ_NO  ,
                          null ACTV_NO  ,
                          Nvl(C.SND_VRFCT_MSG_FOR_CRDT_BILL,0)SND_VRFCT_MSG_FOR_CRDT_BILL                                        
                     From Customer C,
                          Dts_V_Sman_Cst S,
                          Ias_Para_Ar R,
                          Ias_Para_Gen G
                    Where C.C_Code = S.C_Code
                          And Nvl(C.Inactive, 0) = 0                          
                          And S.Rep_Code Is Not Null
                         --- And C.C_Class Is Not Null
            UNION ALL            
              SELECT Distinct
                   P.PRM_CODE C_Code,
                   PRM_L_NM  C_A_Name,
                   PRM_F_NM C_E_Name,
                   P.PRM_ADDRESS C_Address,
                   P.Cntry_No,
                   NULL Prov_No,
                   P.City_No,
                   NULL C_Class,
                   P.PRM_PHONE C_Phone,
                   P.PRM_MOBILE C_Mobile,
                   C.R_Code,
                   NULL C_Person,
                   NULL Custfllow,
                   P.Route_No,
                   P.Sortinroute,
                   S.Rep_Code,
                   Nvl(P.Latitude, Nvl((Substr(P.Gps, 1, Instr(P.Gps, ',') - 1)), '0')) Latitude,
                   Nvl(P.Longitude, Nvl((Substr(P.Gps, Instr(P.Gps, ',') + 1)), '0')) Longitude,
                   NULL Gps_Color,
                   NULL Col_No,
                   NULL C_A_Code,
                   NULL C_Tax_Code,
                   NULL Driver_No,
                   NULL Credit_Period,
                   NULL Csh_Cst,
                   NULL Crdt_Sls_Lev_No,
                   NULL Csh_Sls_Lev_No,
                   NULL Vst_Opn_Typ,
                   NULL C_Barcode,
                   NULL C_Group_Code,
                   NULL C_Degree,
                   NULL Cst_Excpt_Qt_Prm_Flg,
                   NULL C_E_Mail,
                   0 Send_Msg,
                   NULL Clc_Typ_No_Tax,
                   NULL Clc_Vat_Price_Typ,
                   NULL CC_CODE,                   
                   NULL CR_NO,
                   NULL INACTIVE_SALES,
                   0 ALLOW_UPD_FIXED_PRICE,
                   NULL C_CLASS_VAT,
                   2 CST_TYP,
                   0 Lmt_Itm_Qty_Typ,
                   0 Prd_Day,
                   0 Rpt_Qty_Lmt_Cnt,
                   null DOC_BRN_NO,
                   NULL CST_W_CODE,
                   null PJ_NO  ,
                  null ACTV_NO ,
                   Null SND_VRFCT_MSG_FOR_CRDT_BILL
                FROM Dts_V_Sman_Info S,IAS_PROMOTERS P ,IAS_RGN_SMAN C,IAS_PRM_RGN PR
                   WHERE S.REP_CODE=C.REP_CODE
                    AND PR.PRM_CODE=P.PRM_CODE
                   AND C.R_Code=PR.R_Code 
                   AND NVL(P.INACTIVE,0)=0
                   And nvl(p.CONN_SP_SMAN,0)=1
                    And Nvl(S.Sman_Typ,0) In(2,3);

COMMENT ON COLUMN IAS20261.DTS_V_GET_CUSTOMER.C_PHONE IS '2740 - —ﬁ„ «·Â« ›';

COMMENT ON COLUMN IAS20261.DTS_V_GET_CUSTOMER.C_MOBILE IS '770 - —ﬁ„ «·ÃÊ«·';

COMMENT ON COLUMN IAS20261.DTS_V_GET_CUSTOMER.C_E_MAIL IS '520 - «·»—Ìœ «·«·ﬂ —Ê‰Ì';



--
-- DTS_V_GET_ITM_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_ITM_DTL
(GRP_CODE, REP_CODE, I_CODE, I_NAME, ITM_UNT, 
 BARCODE, I_E_NAME, G_CODE, P_SIZE, FREE_QTY_PER, 
 DISC_PER, VAT_PER, ALLOW_DISC, ALLOW_FREE_QTY, USE_QTY_FRACTION, 
 USE_BATCH_NO, USE_EXP_DATE, USE_SERIALNO, SRVC_ITM, MAIN_UNIT, 
 SALE_UNIT, MNG_CODE, SUBG_CODE, ASSISTANT_NO, DETAIL_NO, 
 GROUP_NO, GRP_CLASS_CODE, ITEM_TYPE, I_IMG, I_DESC, 
 I_F_DESC, I_CWTAVG, LAST_UPD, NO_RETURN_SALE, RETURN_PERIOD, 
 W_CODE, ITM_TYP, LMT_QTY_SAL_CST, ITM_SAL_LMT_PRD_DAY, VAT_TYPE, 
 DAY_ITM_EXPIRE, ITM_UNT_L_DSC, ITM_UNT_F_DSC, ACTIVITY_NO, ALLW_UPDT_PRICE)
BEQUEATH DEFINER
AS 
SELECT  
                                                grp_code,
                                                rep_code,
                                                i_code,
                                                i_name,
                                                itm_unt,
                                                barcode,
                                                i_e_name,
                                                g_code,
                                                p_size,
                                                free_qty_per,
                                                disc_per,
                                                vat_per,
                                                allow_disc,
                                                allow_free_qty,
                                                use_qty_fraction,
                                                use_batch_no,
                                                use_exp_date,
                                                Use_Serialno,
                                                srvc_itm,
                                                main_unit,
                                                sale_unit,
                                                MNG_CODE,
                                                SUBG_CODE,
                                                ASSISTANT_NO,
                                                DETAIL_NO,
                                                GROUP_NO,
                                                GRP_CLASS_CODE,
                                                ITEM_TYPE,
                                                I_IMG,
                                                I_DESC,
                                                I_F_DESC ,
                                                (CASE CHK_STK_COST_IN_INVOICE WHEN 1 THEN (CASE WHEN  Costing_Type=2 THEN 
                                                                                                       Ias_Itm_Pkg.Get_Grand_Wtavg ( P_Wtavg_Type =>Wtavg_Type,
                                                                                                                                     P_Icode      =>i_code,                                                     
                                                                                                                                     P_Wcode      => W_code)*NVL(P_sIZE,1)
                                                                                                    ELSE
                                                                                                     Last_Incoming_Price ( P_Wtavg_Type => Wtavg_Type,
                                                                                                                           P_Icode      => I_code,
                                                                                                                           P_Psize      => P_sIZE, 
                                                                                                                           P_Wcode      => w_code, 
                                                                                                                           P_Type       => 1)
                                                                                                       END                                                         
                                                                                              )
                                                                                ELSE 0 END)I_CWTAVG,
                                                LAST_UPD,
                                                NO_RETURN_SALE,
                                                RETURN_PERIOD, 
                                                W_CODE ,                                             
                                                ITM_TYP ,
                                                Lmt_Qty_Sal_Cst , 
                                                ITM_SAL_LMT_PRD_DAY ,
                                                VAT_TYPE  ,
                                                DAY_ITM_EXPIRE ,
                                                ITM_UNT_L_DSC ,
                                                ITM_UNT_F_DSC ,
                                                ACTIVITY_NO  ,
                                                ALLW_UPDT_PRICE                         
                                                FROM (
   SELECT g.grp_code grp_code, s.reprs_code rep_code, g.i_code i_code,
          NVL (mi.i_name, 'NO NAME') i_name,
          NVL (g.itm_unt, 'NO NAME') itm_unt,
          decode(USE_ONE_BARCODE_FOR_ITM,1,di.barcode,null) barcode,
          NVL (mi.i_e_name, 'NO NAME') i_e_name, mi.g_code g_code,
          di.p_size p_size, 
          mi.free_qty_per ,
          mi.disc_per ,
          NVL ((SELECT SUM (tax_prcnt)
                FROM   dts_v_gnr_tax_item tx
                WHERE  tx.rep_code = s.reprs_code AND tx.i_code = g.i_code),
               0
              ) vat_per,
          NVL (mi.allow_disc, 0) allow_disc,
          NVL (mi.allow_free_qty, 0) allow_free_qty,
          NVL (mi.use_qty_fraction, 0) use_qty_fraction,
          NVL (mi.use_batch_no, 0) use_batch_no,
          NVL (mi.use_exp_date, 0) use_exp_date,
          NVL (mi.use_serialno, 0) Use_Serialno, NVL (service_itm, 0) srvc_itm,
          NVL (di.main_unit, 0) main_unit, NVL (di.sale_unit, 0) sale_unit,
          MI.MNG_CODE,
          MI.SUBG_CODE,
          MI.ASSISTANT_NO,
          MI.DETAIL_NO,
          MI.GROUP_NO,
          MI.GRP_CLASS_CODE,
          MI.ITEM_TYPE,
          MI.I_IMG,
          mi.I_DESC,
          mi.I_F_DESC ,
          S.W_CODE,
          PINV.Costing_Type,
          PINV.Wtavg_Type,
          PDTS.CHK_STK_COST_IN_INVOICE, 
          NVL(MI.UP_DATE,MI.AD_DATE)LAST_UPD ,
          nvl(mi.NO_RETURN_SALE,0) NO_RETURN_SALE,
          mi.RETURN_PERIOD,
          1 ITM_TYP  ,
          Nvl(mi.Lmt_Qty_Sal_Cst,0) Lmt_Qty_Sal_Cst , 
          Nvl(mi.ITM_SAL_LMT_PRD_DAY, 0) ITM_SAL_LMT_PRD_DAY,
          nvl(mi.VAT_TYPE,0) VAT_TYPE ,
          MI.DAY_ITM_EXPIRE,
          DI.ITM_UNT_L_DSC ,
          DI.ITM_UNT_F_DSC ,
          MI.ACTIVITY_NO ,
          NVL(MI.ALLW_UPDT_PRICE,0) ALLW_UPDT_PRICE 
   FROM   dts_grp_dtl g,
          ias_itm_mst mi,
          ias_itm_dtl di,
          sales_man s,
          IAS_PARA_INV PINV,
          DTS_PARA PDTS
   WHERE  g.i_code = mi.i_code
   AND    di.i_code = mi.i_code
   AND    g.i_code = di.i_code
   AND    g.itm_unt = di.itm_unt
   And    S.Reprs_Code = Nvl (DTS_PRMTR_PKG.Getpval ('REP_CODE'), S.Reprs_Code) 
   AND    s.grp_code = g.grp_code   
   AND    Nvl(G.INACTIVE,0)  =0
   AND    Nvl(MI.INACTIVE,0)=0
   AND    Nvl(DI.INACTIVE,0)=0
   And    Nvl(s.Conn_Sp_Sman,0) In(0,2,3)
   UNION ALL
   SELECT NULL grp_code, 
          s.rep_code , 
          MI.i_code i_code,
          NVL (mi.i_name, 'NO NAME') i_name,
          NVL (DI.itm_unt, 'NO NAME') itm_unt,
          decode(USE_ONE_BARCODE_FOR_ITM,1,di.barcode,null) barcode,
          NVL (mi.i_e_name, 'NO NAME') i_e_name, 
          mi.g_code g_code,
          di.p_size p_size, 
          mi.free_qty_per, 
          mi.disc_per,
          0 vat_per,
          NVL (mi.allow_disc, 0) allow_disc,
          NVL (mi.allow_free_qty, 0) allow_free_qty,
          NVL (mi.use_qty_fraction, 0) use_qty_fraction,
          NVL (mi.use_batch_no, 0) use_batch_no,
          NVL (mi.use_exp_date, 0) use_exp_date,
          NVL (mi.use_serialno, 0) Use_Serialno, NVL (service_itm, 0) srvc_itm,
          NVL (di.main_unit, 0) main_unit, 
          NVL (di.sale_unit, 0) sale_unit,
          MI.MNG_CODE,
          MI.SUBG_CODE,
          MI.ASSISTANT_NO,
          MI.DETAIL_NO,
          MI.GROUP_NO,
          MI.GRP_CLASS_CODE,
          MI.ITEM_TYPE,
          MI.I_IMG,
          mi.I_DESC,
          mi.I_F_DESC ,
          S.W_CODE,
          PINV.Costing_Type,
          PINV.Wtavg_Type,
          0 CHK_STK_COST_IN_INVOICE, 
          NVL(MI.UP_DATE,MI.AD_DATE)LAST_UPD ,
          nvl(mi.NO_RETURN_SALE,0) NO_RETURN_SALE,
          mi.RETURN_PERIOD,
          2 ITM_TYP,
          Nvl(mi.Lmt_Qty_Sal_Cst,0) Lmt_Qty_Sal_Cst , 
          Nvl(mi.ITM_SAL_LMT_PRD_DAY, 0) ITM_SAL_LMT_PRD_DAY,
          nvl(mi.VAT_TYPE,0) VAT_TYPE  ,
          mi.DAY_ITM_EXPIRE, 
          DI.ITM_UNT_L_DSC ,
          DI.ITM_UNT_F_DSC  ,
          MI.ACTIVITY_NO   ,
          NVL(MI.ALLW_UPDT_PRICE,0) ALLW_UPDT_PRICE 
   FROM   ias_itm_mst mi,
          ias_itm_dtl di,
          Dts_V_Sman_Info s,
          IAS_PARA_AR PAR , 
          IAS_PARA_INV PINV         
   WHERE  di.i_code = mi.i_code          
   And    S.Rep_Code = Nvl (DTS_PRMTR_PKG.Getpval ('REP_CODE'), S.Rep_Code)    
   AND    NVL(S.Sman_Typ,0) In(2,3)    
   AND    Nvl(MI.INACTIVE,0)=0
   AND    Nvl(DI.INACTIVE,0)=0
   AND (MI.I_Code,S.Rep_Code)in 
                            (SELECT Distinct I_Code, Rep_Code
                                FROM   Inv_Itm_Free_Smpl_Mvmnt )
 UNION ALL
   SELECT NULL grp_code, 
          s.rep_code , 
          MI.i_code i_code,
          NVL (mi.i_name, 'NO NAME') i_name,
          NVL (DI.itm_unt, 'NO NAME') itm_unt,
          decode(USE_ONE_BARCODE_FOR_ITM,1,di.barcode,null) barcode,
          NVL (mi.i_e_name, 'NO NAME') i_e_name, 
          mi.g_code g_code,
          di.p_size p_size, 
          mi.free_qty_per,
          mi.disc_per,
          0 vat_per,
          NVL (mi.allow_disc, 0) allow_disc,
          NVL (mi.allow_free_qty, 0) allow_free_qty,
          NVL (mi.use_qty_fraction, 0) use_qty_fraction,
          NVL (mi.use_batch_no, 0) use_batch_no,
          NVL (mi.use_exp_date, 0) use_exp_date,
          NVL (mi.use_serialno, 0) Use_Serialno, NVL (service_itm, 0) srvc_itm,
          NVL (di.main_unit, 0) main_unit, 
          NVL (di.sale_unit, 0) sale_unit,
          MI.MNG_CODE,
          MI.SUBG_CODE,
          MI.ASSISTANT_NO,
          MI.DETAIL_NO,
          MI.GROUP_NO,
          MI.GRP_CLASS_CODE,
          MI.ITEM_TYPE,
          MI.I_IMG,
          mi.I_DESC,
          mi.I_F_DESC ,
          S.W_CODE,
          PINV.Costing_Type,
          PINV.Wtavg_Type,
          0 CHK_STK_COST_IN_INVOICE, 
          NVL(MI.UP_DATE,MI.AD_DATE)LAST_UPD ,
          nvl(mi.NO_RETURN_SALE,0) NO_RETURN_SALE,
          mi.RETURN_PERIOD,
          3 ITM_TYP,
          Nvl(mi.Lmt_Qty_Sal_Cst,0) Lmt_Qty_Sal_Cst , 
          Nvl(mi.ITM_SAL_LMT_PRD_DAY, 0) ITM_SAL_LMT_PRD_DAY,
          nvl(mi.VAT_TYPE,0) VAT_TYPE ,
          mi.DAY_ITM_EXPIRE,
          DI.ITM_UNT_L_DSC ,
          DI.ITM_UNT_F_DSC  ,
          MI.ACTIVITY_NO  ,
          NVL(MI.ALLW_UPDT_PRICE,0) ALLW_UPDT_PRICE   
   FROM   ias_itm_mst mi,
          ias_itm_dtl di,
          Dts_V_Sman_Info s,
          IAS_PARA_AR PAR , 
          IAS_PARA_INV PINV         
   WHERE  di.i_code = mi.i_code   
   And    nvl(mi.USE_IN_SCNTFC_OFFICE,0)=1      
   And    S.Rep_Code = Nvl (DTS_PRMTR_PKG.Getpval ('REP_CODE'), S.Rep_Code)    
   AND    NVL(S.Sman_Typ,0) In(2,3)       
   AND    Nvl(MI.INACTIVE,0)=0
   AND    Nvl(DI.INACTIVE,0)=0
   AND (MI.I_Code,S.Rep_Code)in 
                            (SELECT Distinct I_Code, Rep_Code
                                FROM   IAS_ITM_SMAN )                  
   );


--
-- DTS_V_GET_ITM_SRLNO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_ITM_SRLNO
(REP_CODE, GRP_CODE, I_CODE, ITM_UNT, P_SIZE, 
 SRL_NO, W_CODE, AVL_QTY)
BEQUEATH DEFINER
AS 
(
															SELECT   REP_CODE, GRP_CODE, I_CODE,ITM_UNT,P_SIZE,SRL_NO,W_CODE,NVL (SUM (AVL_QTY),0) AVL_QTY
															FROM 
															(SELECT   S.REP_CODE, S.GRP_CODE, 
                                       DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.I_CODE, '0'),G.I_CODE) "I_CODE",
                                       DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT) "ITM_UNT",
                                       DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.SERIALNO, '0'),NULL)  SRL_NO,S.W_CODE,
                                       NVL (SUM ( M.IN_OUT),0) AVL_QTY,DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.P_SIZE, '0'),G.P_SIZE) "P_SIZE"
                                  FROM IAS_ITEM_SERIALNO M,
                                       DTS_V_GET_ITM_DTL G,
                                       DTS_V_SMAN_INFO S,
                                       DTS_PARA P
                                 WHERE DECODE (YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_INV', 'USE_SERIALNO',' WHERE 1=1 '),1,1,0)=1
                                   AND NVL (G.Use_Serialno, 0) =1
                                   AND NVL (S.SMAN_TYP,0) in(1,3)
                                   AND G.I_CODE   = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.I_CODE, '0'),G.I_CODE)
                                   AND G.ITM_UNT  = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT)
                                   AND G.GRP_CODE = S.GRP_CODE
                                   AND S.REP_CODE = G.REP_CODE
                                   AND S.W_CODE   = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.W_CODE, 0),S.W_CODE)
                          GROUP BY S.REP_CODE,S.GRP_CODE,S.W_CODE, 
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.I_CODE, '0'),G.I_CODE) ,
                                   DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT) ,
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.SERIALNO, '0'),NULL) ,
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.P_SIZE, '0'),G.P_SIZE)
                  UNION ALL
                  SELECT   S.REP_CODE, S.GRP_CODE, 
                                       DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.I_CODE, '0'),G.I_CODE) "I_CODE",
                                       DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT) "ITM_UNT",
                                       DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.SERIALNO, '0'),NULL)  SRL_NO,S.W_CODE,
                                       NVL (SUM ( M.IN_OUT),0) AVL_QTY,DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.P_SIZE, '0'),G.P_SIZE) "P_SIZE"
                                  FROM IAS_ITEM_SERIALNO_BR M,
                                       DTS_V_GET_ITM_DTL G,
                                       DTS_V_SMAN_INFO S,
                                       DTS_PARA P
                                 WHERE DECODE (YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_INV', 'USE_SERIALNO',' WHERE 1=1 '),1,1,0)=1
                                   AND NVL (G.Use_Serialno, 0) =1
                                   AND NVL (S.SMAN_TYP,0) in(1,3)
                                   AND (DOC_TYPE,DOC_SER,SERIALNO) NOT IN(SELECT DOC_TYPE,DOC_SER,SERIALNO FROM IAS_ITEM_SERIALNO)
                                   AND G.I_CODE   = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.I_CODE, '0'),G.I_CODE)
                                   AND G.ITM_UNT  = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT)
                                   AND G.GRP_CODE = S.GRP_CODE
                                   AND S.REP_CODE = G.REP_CODE
                                   AND S.W_CODE   = DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.W_CODE, 0),S.W_CODE)
                          GROUP BY S.REP_CODE,S.GRP_CODE,S.W_CODE, 
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.I_CODE, '0'),G.I_CODE) ,
                                   DECODE (P.USE_DTS_WITHOUT_INV,0, NVL (M.ITM_UNT, '0'),G.ITM_UNT) ,
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.SERIALNO, '0'),NULL) ,
                                   DECODE(P.USE_DTS_WITHOUT_INV,0, NVL(M.P_SIZE, '0'),G.P_SIZE)
                                                            )
												GROUP BY REP_CODE, GRP_CODE, I_CODE,ITM_UNT,P_SIZE,SRL_NO,W_CODE   
												 );


--
-- DTS_V_GET_REP_CST_GEO_GPS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_CST_GEO_GPS
(REP_CODE, C_CODE, CST_L_NM, CST_F_NM, CNTRY_NO, 
 PROV_NO, CITY_NO, RGN_NO, ROUTE_NO, SORTINROUTE, 
 GPS, LATITUDE, LONGITUDE)
BEQUEATH DEFINER
AS 
SELECT   m.rep_code, m.c_code, NVL (c.c_a_name, 'no local name') cst_l_nm,
                            NVL (c.c_e_name, 'no foreign name') cst_f_nm, c.cntry_no,c.PROV_NO,
                            c.city_no, c.r_code rgn_no, c.route_no, c.sortinroute, c.gps,
                            SUBSTR (c.gps, 1, (NVL (INSTR (c.gps, ','), 0) - 1)) latitude,
                            SUBSTR (c.gps,(NVL (INSTR (c.gps, ','), 0) + 1),(NVL (INSTR (c.gps, ',', 2), 0) - 1)) longitude
                       FROM customer c, dts_v_sman_cst m
                      WHERE  m.c_code = c.c_code
                          and c.cntry_no is not null
                          and c.PROV_NO  is not null
                          and c.city_no  is not null
                          and c.r_code   is not null
                          and c.route_no is not null
                   ORDER BY c.sortinroute, m.c_code;


--
-- DTS_V_GET_REP_NET_SLS  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_NET_SLS
(DOC_DATE, C_CODE, REP_CODE, A_CY, B_AMT, 
 B_DISC_AMT, B_VAT_AMT, B_OTHR_AMT, B_TOT_AMT, B_TOT_AMT_L, 
 RT_AMT, RT_DISC_AMT, RT_VAT_AMT, RT_OTHR_AMT, RT_TOT_AMT, 
 RT_TOT_AMT_L, NET_AMT, NET_AMT_L)
BEQUEATH DEFINER
AS 
SELECT      To_DATE(DOC_DATE,'DD/MM/RRRR') Doc_Date, C_CODE, REP_CODE, A_CY, 
                 Sum(B_AMT),Sum(B_DISC_AMT), Sum(B_VAT_AMT), Sum(B_OTHR_AMT), Sum(B_TOT_AMT),Sum(B_TOT_AMT_L), 
                 Sum(RT_AMT),Sum(RT_DISC_AMT), Sum(RT_VAT_AMT), Sum(RT_OTHR_AMT), Sum(RT_TOT_AMT),Sum(RT_TOT_AMT_L), 
                 Sum(NET_AMT), Sum(NET_AMT_L)      
            FROM (SELECT      To_DATE(DOC_DATE,'DD/MM/RRRR') Doc_Date, C_CODE, REP_CODE, 
                               A_CY, B_AMT, B_DISC_AMT, 
                               B_VAT_AMT, B_OTHR_AMT, B_TOT_AMT, 
                               B_TOT_AMT_L, RT_AMT, RT_DISC_AMT, 
                               RT_VAT_AMT, RT_OTHR_AMT, RT_TOT_AMT, 
                               RT_TOT_AMT_L, NET_AMT, NET_AMT_L
                            FROM DTS_V_GET_REP_PSTD_NET_SLS
                     Union
                      SELECT     To_DATE(DOC_DATE,'DD/MM/RRRR') doc_date, C_CODE, REP_CODE, 
                               A_CY, B_AMT, B_DISC_AMT, 
                               B_VAT_AMT, B_OTHR_AMT, B_TOT_AMT, 
                               B_TOT_AMT_L, RT_AMT, RT_DISC_AMT, 
                               RT_VAT_AMT, RT_OTHR_AMT, RT_TOT_AMT, 
                               RT_TOT_AMT_L, NET_AMT, NET_AMT_L
                            FROM DTS_V_GET_REP_UnPSTD_NET_SLS  
                      )     
            group by 
                   To_DATE(DOC_DATE,'DD/MM/RRRR') ,REP_CODE,  C_CODE , A_CY;


--
-- DTS_V_GET_REP_STORAGE  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_STORAGE
(REP_CODE, GRP_CODE, I_CODE, I_NAME, I_E_NAME, 
 W_CODE, AVL_QTY, EXPIRE_DATE, BATCH_NO)
BEQUEATH DEFINER
AS 
(SELECT   REP_CODE, GRP_CODE, I_CODE, I_NAME, I_E_NAME, W_CODE,
                             NVL (SUM (NVL (AVL_QTY, 0)), 0) AVL_QTY, EXPIRE_DATE, BATCH_NO
                        FROM (SELECT   S.REPRS_CODE REP_CODE, S.GRP_CODE, M.I_CODE, MI.I_NAME,
                                       MI.I_E_NAME, S.W_CODE,
                                       NVL ((SUM (  (  (NVL (M.P_QTY, 0) + NVL (M.PF_QTY, 0))
                                                     * M.IN_OUT
                                                    )
                                                  / DI.P_SIZE
                                                 )
                                            ),
                                            0
                                           ) AVL_QTY,
                                       M.EXPIRE_DATE, M.BATCH_NO
                                  FROM ITEM_MOVEMENT M,
                                       IAS_ITM_MST MI,
                                       IAS_ITM_DTL DI,
                                       DTS_V_GET_ITM_DTL G,
                                       SALES_MAN S
                                 WHERE M.I_CODE = MI.I_CODE
                                   AND M.I_CODE = DI.I_CODE
                                   AND M.I_CODE = G.I_CODE
                                   AND MI.I_CODE = DI.I_CODE
                                   AND MI.I_CODE = G.I_CODE
                                   AND DI.I_CODE = G.I_CODE
                                   AND G.GRP_CODE = S.GRP_CODE
                                   AND S.REPRS_CODE = G.REP_CODE
                                   AND M.W_CODE = S.W_CODE
                                   AND NVL (DI.MAIN_UNIT, 0) = 1
                              GROUP BY S.REPRS_CODE,
                                       S.GRP_CODE,
                                       M.I_CODE,
                                       MI.I_NAME,
                                       MI.I_E_NAME,
                                       S.W_CODE,
                                       M.EXPIRE_DATE,
                                       M.BATCH_NO
                              UNION
                              SELECT S.REPRS_CODE REP_CODE, S.GRP_CODE, G.I_CODE, MI.I_NAME,
                                     MI.I_E_NAME, S.W_CODE, 0 AVL_QTY,
                                     TO_DATE ('01/01/1900', 'DD/MM/YYYY') EXPIRE_DATE,
                                     '0' BATCH_NO
                                FROM IAS_ITM_WCODE M,
                                     IAS_ITM_MST MI,
                                     DTS_V_GET_ITM_DTL G,
                                     SALES_MAN S,
                                     DTS_PARA P
                               WHERE MI.I_CODE =
                                        DECODE (P.USE_DTS_WITHOUT_INV,
                                                0, NVL (M.I_CODE, '0'),
                                                G.I_CODE
                                               )
                                 AND MI.I_CODE = G.I_CODE
                                 AND G.GRP_CODE = S.GRP_CODE
                                 AND S.REPRS_CODE = G.REP_CODE
                                 AND S.W_CODE =
                                        DECODE (P.USE_DTS_WITHOUT_INV,
                                                0, NVL (M.W_CODE, 0),
                                                S.W_CODE
                                               )
                                 AND G.I_CODE =
                                        DECODE (P.USE_DTS_WITHOUT_INV,
                                                0, NVL (M.I_CODE, '0'),
                                                MI.I_CODE
                                               ))
                    GROUP BY REP_CODE,
                             GRP_CODE,
                             I_CODE,
                             I_NAME,
                             I_E_NAME,
                             W_CODE,
                             EXPIRE_DATE,
                             BATCH_NO);


--
-- DTS_V_GET_REP_STORAGE_BR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_REP_STORAGE_BR
(ITM_TYP, REP_CODE, GRP_CODE, I_CODE, I_NAME, 
 I_E_NAME, W_CODE, EXPIRE_DATE, BATCH_NO, AVL_QTY)
BEQUEATH DEFINER
AS 
With Sman
                                            As (Select Rep_Code
                                                      ,U_Id  
                                                      ,Brn_No
                                                      ,W_Code
                                                      ,Grp_Code
                                                      ,Wcode_Type
                                                      ,NVL(USE_RQ_TRANSFER_AVLQTY,0) USE_RQ_TRANSFER_AVLQTY
                                                      ,NVL(USE_OUT_BILLS,0) USE_OUT_BILLS                                                      
                                                  From Dts_V_Sman_Wcode,DTS_PARA,IAS_PARA_AR
                                                 Where Wcode_Type In (1, 2, 3))
                                           ,Itm
                                            As (Select Distinct Mi.I_Code
                                                               ,I_Name
                                                               ,I_E_Name
                                                               ,G.Grp_Code
                                                  From Dts_Grp_Dtl G, Ias_Itm_Mst Mi
                                                 Where G.I_Code = Mi.I_Code And Nvl (G.Inactive, 0) = 0)
                                         Select Itm_Typ
                                               ,Rep_Code
                                               ,Grp_Code
                                               ,I_Code
                                               ,I_Name
                                               ,I_E_Name
                                               ,W_Code
                                               ,Expire_Date
                                               ,Batch_No
                                               ,Sum (Avl_Qty) Avl_Qty
                                           From (  Select 1 Itm_Typ
                                                         ,Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,M.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,M.W_Code
                                                         ,M.Expire_Date
                                                         ,M.Batch_No
                                                         ,Nvl ( (Sum ( ( (Nvl (M.P_Qty, 0) + Nvl (M.Pf_Qty, 0)) * M.In_Out))), 0) Avl_Qty
                                                     From Item_Movement M, Itm, Sman
                                                    Where M.I_Code = Itm.I_Code And M.W_Code = Sman.W_Code And Itm.Grp_Code = Sman.Grp_Code
                                                 Group By Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,M.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,M.W_Code
                                                         ,M.Expire_Date
                                                         ,M.Batch_No
                                                 Union All
                                                   Select 1 Itm_Typ
                                                         ,Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                         , (-1 * Nvl ( (Sum ( ( (Nvl (D.P_Qty, 0) + (Nvl (D.Free_Qty, 0) * D.P_Size))))), 0)) Avl_Qty
                                                     From Ias_Bill_Dtl_Br D
                                                         ,Ias_Bill_Mst_Br M
                                                         ,Itm
                                                         ,Sman
                                                    Where M.Bill_Ser = D.Bill_Ser 
                                                    And Sman.Grp_Code = Itm.Grp_Code 
                                                    And Sman.W_Code = D.W_Code 
                                                    And Nvl (M.Bill_Post, 0) = 0 
                                                    And Nvl (M.Cncl_Flg, 0) = 0 
                                                    And D.I_Code = Itm.I_Code
                                                 Group By Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                 Union All
                                                   Select 1 Itm_Typ
                                                         ,Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                         , (Nvl ( (Sum ( ( (Nvl (D.P_Qty, 0) + (Nvl (D.Free_Qty, 0) * D.P_Size))))), 0)) Avl_Qty
                                                     From Ias_Rt_Bill_Dtl_Br D
                                                         ,Ias_Rt_Bill_Mst_Br M
                                                         ,Itm
                                                         ,Sman
                                                    Where M.Rt_Bill_Ser = D.Rt_Bill_Ser And Sman.Grp_Code = Itm.Grp_Code And Sman.W_Code = D.W_Code And Nvl (M.Rt_Bill_Post, 0) = 0 And Nvl (M.Cncl_Flg, 0) = 0 And D.I_Code = Itm.I_Code
                                                 Group By Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                 Union All
                                                 Select 1 Itm_Typ
                                                         ,Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                         , (-1 * Nvl(Sum(Nvl(CP_Qty,0)),0)) Avl_Qty
                                                     From Ias_Reserve_Dtl D
                                                         ,Itm
                                                         ,Sman
                                                    Where D.I_Code = Itm.I_Code
                                                    And Sman.Grp_Code = Itm.Grp_Code 
                                                    And Sman.W_Code = D.W_Code 
                                                    And Nvl(D.Reserved,0)     = 1 
                                                    And Nvl(d.Cp_Qty,0)      >= 0
                                                    And T_Date             >= to_date(sysdate,'DD/MM/RRRR')
                                                    Group By Sman.Rep_Code
                                                         ,Itm.Grp_Code
                                                         ,Itm.I_Code
                                                         ,Itm.I_Name
                                                         ,Itm.I_E_Name
                                                         ,D.W_Code
                                                         ,D.Expire_Date
                                                         ,D.Batch_No
                                                         Union All
                                                 Select 1 Itm_Typ
                                                       ,Sman.Rep_Code
                                                       ,Itm.Grp_Code
                                                       ,Itm.I_Code
                                                       ,Itm.I_Name
                                                       ,Itm.I_E_Name
                                                       ,Sman.W_Code
                                                       ,To_Date ('01/01/1900', 'DD/MM/YYYY') Expire_Date
                                                       ,'0' Batch_No
                                                       ,0 Avl_Qty
                                                   From Itm, Sman
                                                  Where     Itm.Grp_Code = Sman.Grp_Code
                                                        And Wcode_Type = 1
                                                        And Not Exists
                                                               (Select 1
                                                                  From Ias_Itm_Wcode
                                                                 Where I_Code = Itm.I_Code And W_Code = Sman.W_Code And Rownum <= 1)
                                             UNION ALL
                                             SELECT  1 Itm_Typ
                                                     ,Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,D.Expire_Date
                                                     ,D.Batch_No, nvl(SUM((NVL(D.I_QTY,0)+NVL(D.FREE_QTY,0))*D.P_SIZE)-SUM((NVL(D.OUT_QTY,0)+NVL(D.OUT_FREE_QTY,0))*D.P_SIZE),0)*-1 i_qty                                          
                                                   FROM IAS_BILL_mst M, IAS_BILL_DTL D,Itm,Sman
                                            Where M.Bill_Ser = D.Bill_Ser
                                            AND Sman.USE_RQ_TRANSFER_AVLQTY=1
                                            AND Sman.USE_OUT_BILLS=1  
                                            And Sman.Grp_Code = Itm.Grp_Code 
                                            And Sman.W_Code = D.W_Code
                                            And d.I_Code = Itm.I_Code 
                                            AND Sman.Wcode_Type=1
                                              Group By Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,D.Expire_Date
                                                     ,D.Batch_No 
                                              union all
                                            SELECT  1 Itm_Typ
                                                     ,Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,D.Expire_Date
                                                     ,D.Batch_No, nvl(SUM((NVL(D.I_QTY,0)+NVL(D.FREE_QTY,0))*D.P_SIZE)-SUM((NVL(D.ret_QTY,0)+NVL(D.ret_FREE_QTY,0))*D.P_SIZE),0) i_qty                                          
                                                   FROM IAS_rt_BILL_mst M, IAS_rt_BILL_DTL D,Itm,Sman
                                            Where M.RT_Bill_Ser = D.RT_Bill_Ser
                                            AND Sman.USE_RQ_TRANSFER_AVLQTY=1
                                            AND Sman.USE_OUT_BILLS=1 
                                            And Sman.Grp_Code = Itm.Grp_Code 
                                            And Sman.W_Code = D.W_Code 
                                            And d.I_Code = Itm.I_Code
                                            AND Sman.Wcode_Type=1
                                              Group By Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,D.Expire_Date
                                                     ,D.Batch_No 
                                            union all         
                                            SELECT  1 Itm_Typ
                                                     ,Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,NVL(D.Expire_Date,To_Date ('01/01/1900', 'DD/MM/YYYY')) Expire_Date
                                                     ,NVL(D.Batch_No,'0')Batch_No
                                                     , nvl(SUM(NVL(D.I_QTY,0)*D.P_SIZE),0) i_qty                                          
                                                   FROM IAS_OUT_REQUEST_MST M, IAS_OUT_REQUEST_DTL D,REQUEST_TYPES RQ,Itm,Sman
                                            Where M.OUT_REQ_SER=D.OUT_REQ_SER
                                            AND RQ.REQ_TYPE=M.OUT_REQ_TYPE
                                            AND RQ.OUT_TRNSFR IN(2,3)
                                            AND Sman.USE_RQ_TRANSFER_AVLQTY=1
                                            AND Sman.USE_OUT_BILLS=1 
                                            And Sman.Grp_Code = Itm.Grp_Code 
                                            And Sman.W_Code = D.W_Code 
                                            And d.I_Code = Itm.I_Code
                                            AND Sman.Wcode_Type=1
                                             AND NVL(M.APPROVED,0)=1
                                              AND NVL(PROCESSED,0)=0
                                              AND NVL(INACTIVE,0)=0 
                                              Group By Sman.Rep_Code
                                                     ,Itm.Grp_Code
                                                     ,Itm.I_Code
                                                     ,Itm.I_Name
                                                     ,Itm.I_E_Name
                                                     ,D.W_Code
                                                     ,D.Expire_Date
                                                     ,D.Batch_No                    )
                                       Group By Itm_Typ
                                               ,Rep_Code
                                               ,Grp_Code
                                               ,I_Code
                                               ,I_Name
                                               ,I_E_Name
                                               ,W_Code
                                               ,Expire_Date
                                               ,Batch_No
                                       Union All
                                         Select 2 Itm_Typ
                                               ,Itm.Rep_Code
                                               ,Itm.Grp_Code
                                               ,M.I_Code
                                               ,Itm.I_Name
                                               ,Itm.I_E_Name
                                               ,Itm.W_Code
                                               ,M.Expire_Date
                                               ,M.Batch_No
                                               ,Nvl (Sum (Nvl (M.P_Qty, 0) * M.In_Out), 0) Avl_Qty
                                           From Inv_Itm_Free_Smpl_Mvmnt M,(SELECT  DISTINCT                                                                            
                                                                                    Rep_Code
                                                                                   ,Grp_Code
                                                                                   ,I_Code
                                                                                   ,I_Name
                                                                                   ,I_E_Name
                                                                                   ,W_Code
                                                                                   FROM   Dts_V_Get_Itm_Dtl
                                                                             WHERE Itm_Typ = 2  )Itm
                                          Where M.I_Code = Itm.I_Code And M.Rep_Code = Itm.Rep_Code 
                                       Group By Itm.Rep_Code
                                               ,Itm.Grp_Code
                                               ,M.I_Code
                                               ,Itm.I_Name
                                               ,Itm.I_E_Name
                                               ,Itm.W_Code
                                               ,M.Expire_Date
                                               ,M.Batch_No;


--
-- DTS_V_IAS_QUT_PRM_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_IAS_QUT_PRM_DTL
(REP_CODE, QUOT_NO, QUOT_SER, I_CODE, ITM_UNT, 
 P_SIZE, I_PRICE, RCRD_NO, BARCODE, F_QTY, 
 T_QTY, F_AMT, T_AMT, DISC_TYPE, DISC_AMT_PER, 
 QT_I_CODE, FREE_QTY, QT_ITM_UNT, QT_QTY, W_CODE, 
 WHG_CODE, CNTRY_NO, PROV_NO, CITY_NO, R_CODE, 
 CARD_AMT, COMP_QTY, CMP_NO, BRN_NO, BRN_YEAR, 
 BRN_USR, UP_CNT, EXPIRE_DATE, BATCH_NO, C_CODE, 
 C_GROUP_CODE, C_CLASS, C_DEGREE, G_CODE, MNG_CODE, 
 SUBG_CODE, ASSISTANT_NO, DETAIL_NO, GROUP_NO, ITEM_TYPE, 
 GRP_CLASS_CODE, PRM_GRP_NO, BANK_NO, MAX_QT_QTY_DOC, QT_PRM_GRP_NO, 
 BILL_QTY)
BEQUEATH DEFINER
AS 
Select sm.Rep_Code
         ,D.Quot_No
         ,D.Quot_Ser
         ,D.I_Code
         ,D.Itm_Unt
         ,D.P_Size
         ,D.I_Price
         ,D.Rcrd_No
         ,D.Barcode
         ,D.F_Qty
         ,D.T_Qty
         ,D.F_Amt
         ,D.T_Amt
         ,D.Disc_Type
         ,D.Disc_Amt_Per
         ,D.Qt_I_Code
         ,D.Free_Qty
         ,D.Qt_Itm_Unt
         ,D.Qt_Qty
         ,D.W_Code
         ,D.Whg_Code
         ,D.Cntry_No
         ,D.Prov_No
         ,D.City_No
         ,D.R_Code
         ,D.Card_Amt
         ,D.Comp_Qty
         ,D.Cmp_No
         ,D.Brn_No
         ,D.Brn_Year
         ,D.Brn_Usr
         ,D.Up_Cnt
         ,D.Expire_Date
         ,D.Batch_No
         ,D.C_Code
         ,D.C_Group_Code
         ,D.C_Class
         ,D.C_Degree
         ,D.G_Code
         ,D.Mng_Code
         ,D.Subg_Code
         ,D.Assistant_No
         ,D.Detail_No
         ,D.Group_No
         ,D.Item_Type
         ,D.Grp_Class_Code
         ,D.Prm_Grp_No
         ,D.Bank_No
         ,D.Max_Qt_Qty_Doc
         ,D.QT_PRM_GRP_NO
         ,Nvl ( (Select Sum (Nvl (B.I_Qty, 0) + Nvl (Free_Qty, 0))
                   From Ias_Bill_Dtl B
                  Where D.Quot_Ser = B.Qt_Prm_Ser And D.Rcrd_No = B.Qt_Prm_Rcrd_No)
              ,0)
             Bill_Qty
     From Ias_Qut_Prm_Dtl D, Dts_V_Sman_Info Sm,Ias_Qut_Prm_mst M
    Where M.QUOT_SER=D.QUOT_SER 
    AND NVL(M.USE_QTN_PRM_IN_DTS_SYS_FLG,0)=1
    And  nvl(m.APPROVED,0)=1
    AND 1 = Case
                 When D.I_Code Is Not Null Then
                    (Select 1
                       From Dts_V_Get_Itm_Dtl
                      Where Rep_Code = Sm.Rep_Code And I_Code = D.I_Code And Itm_Unt = D.Itm_Unt And Rownum <= 1)
                 Else
                    1
              End
    AND 1 = Case
                 When D.W_Code Is Not Null Then
                    (Select 1
                       From Dts_V_Sman_Wcode
                      Where Rep_Code = Sm.Rep_Code And W_Code = D.W_Code And nvl(Wcode_Type,0)<>4 And Rownum <= 1)
                 Else
                    1
              End;


--
-- DTS_V_IAS_QUT_PRM_SUB_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_IAS_QUT_PRM_SUB_DTL
(REP_CODE, RCRD_NO, QUOT_NO, QUOT_SER, I_CODE, 
 FREE_QTY, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 UP_CNT, ITM_UNT, P_SIZE)
BEQUEATH DEFINER
AS 
Select Distinct SM.Rep_Code
                                                  ,D.Rcrd_No
                                                  ,D.Quot_No
                                                  ,D.Quot_Ser
                                                  ,D.I_Code
                                                  ,D.Free_Qty
                                                  ,D.Cmp_No
                                                  ,D.Brn_No
                                                  ,D.Brn_Year
                                                  ,D.Brn_Usr
                                                  ,D.Up_Cnt
                                                  ,D.Itm_Unt
                                                  ,D.P_Size
                                     From Ias_Qut_Prm_Sub_Dtl D, Dts_V_Sman_Info Sm, Dts_V_Get_Itm_Dtl I,Ias_Qut_Prm_mst M
                                    Where M.QUOT_SER=D.QUOT_SER 
                                    AND NVL(M.USE_QTN_PRM_IN_DTS_SYS_FLG,0)=1
                                    And  nvl(m.APPROVED,0)=1
                                    AND I.I_Code = D.I_Code
                                    And I.Itm_Unt = D.Itm_Unt 
                                    And I.Rep_Code = SM.Rep_Code;


--
-- DTS_V_ITM_MARKT_PROPERTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_ITM_MARKT_PROPERTY
(REP_CODE, CODE_NO, CODE_L_NAME, CODE_F_NAME, I_CODE, 
 CODE_DESC, CODE_PER)
BEQUEATH DEFINER
AS 
Select distinct Sm.Rep_Code
                                     ,M.Code_No
                                     ,G.Sub_L_Name Code_L_Name
                                     ,G.Sub_F_Name Code_F_Name
                                     ,M.I_Code
                                     ,M.Code_Desc
                                     ,M.Code_Per
                                 From Dts_Itm_Markt_Property M, Dts_V_Get_Itm_Dtl Sm, Ias_Gnr_Code_Dtl G
                                Where M.I_Code = Sm.I_Code 
                                And M.Code_No = G.Sub_No 
                                And G.Main_Code = 19 
                                And Nvl (M.Inactive, 0) = 0;


--
-- DTS_V_SALES_ITEM_SERIALNO  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SALES_ITEM_SERIALNO
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, DOC_SER, I_CODE, 
 ITM_UNT, SERIALNO, W_CODE, EXPIRE_DATE, BATCH_NO, 
 IN_OUT, BILL_COST, RCRD_NO, RCRD_NO_DOC)
BEQUEATH DEFINER
AS 
Select Doc_type
         ,Bill_doc_type
         ,Doc_no
         ,Doc_ser
         ,I_code
         ,Itm_unt
         ,Serialno
         ,W_code
         ,Expire_date
         ,Batch_no
         ,In_out
         ,Bill_cost
         ,Rcrd_no
         ,Rcrd_no_doc
   From   (Select Doc_type
                 ,Bill_doc_type
                 ,Doc_no
                 ,Doc_ser
                 ,I_code
                 ,Itm_unt
                 ,Serialno
                 ,W_code
                 ,Expire_date
                 ,Batch_no
                 ,In_out
                 ,Bill_cost
                 ,Rcrd_no
                 ,Rcrd_no_doc
           From   Ias_item_serialno
           Where  Doc_type = 1
           Union
           Select Doc_type
                 ,Bill_doc_type
                 ,Doc_no
                 ,Doc_ser
                 ,I_code
                 ,Itm_unt
                 ,Serialno
                 ,W_code
                 ,Expire_date
                 ,Batch_no
                 ,In_out
                 ,Bill_cost
                 ,Rcrd_no
                 ,Rcrd_no_doc
           From   Ias_item_serialno_br
           Where  Doc_type = 1) S
   Where  Exists(Select 1
                 From   Dts_v_get_itm_dtl
                 Where  I_code = S.I_code And Nvl(Use_Serialno, 0) = 1) 
     And Exists(Select 1
                     From   Dts_v_sman_info
                     Where  W_code = S.W_code);


--
-- DTS_V_SMAN_GPS_VST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_GPS_VST
(C_CODE, C_NAME, REP_CODE, GPS_LNGT_X, GPS_LAT_Y, 
 GPS, ARIVL_TM, VST_DATE, VST_STS)
BEQUEATH DEFINER
AS 
Select V.C_Code C_Code
										   ,Decode (Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), 1, Nvl (A.C_A_Name, A.C_E_Name), Nvl (A.C_E_Name, A.C_A_Name)) C_Name
										   ,V.Rep_Code
										   ,Substr (Gps, 1, (To_Number (Instr (Gps, ',', 1)) - 1)) Gps_Lngt_X
										   ,Substr (Gps, (To_Number (Instr (Gps, ',', 1)) + 1)) Gps_Lat_Y
										   ,A.Gps
										   ,Min (Arivl_Tm) Arivl_Tm
										   ,To_Date (Arivl_Tm, 'DD/MM/RRRR') Vst_Date
										   ,'  '||Listagg (Doc_Type_Nm , ',') Within Group (Order By Doc_Type_Nm) Vst_Sts
										From (Select M.Arivl_Tm
										           ,M.C_Code
										           ,M.Rep_Code
										           ,Decode (D.Doc_Type, Null
										                               , Ias_Gen_Pkg.Get_Prompt (Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), 7079)||' '||Ys_Gen_Pkg.Get_Flg_Nm('DTS_VST_STS', M.Vst_Sts,Nvl(Ias_Prmtr_Pkg.Getpval(P_Prmtr =>'LANG_DFLT'),1))
										                               , Dts_Doc_Type_Name (Nvl(Ias_Prmtr_Pkg.Getpval (P_Prmtr =>'LANG_DFLT'), 1), D.Doc_Type, D.Jv_Type)||'=' || round(Doc_Amt,2)) Doc_Type_Nm
										       From Dts_Cst_Vst_Mst M, Dts_V_Vst_Mvmnt D
										      Where M.Vst_Srl = D.Vst_Srl(+)) V
										   ,Customer A
										Where A.C_Code = V.C_Code
										Group By V.C_Code
										   ,Decode (Nvl (Ias_Prmtr_Pkg.Getpval (P_Prmtr => 'LANG_DFLT'), 1), 1, Nvl (A.C_A_Name, A.C_E_Name), Nvl (A.C_E_Name, A.C_A_Name))
										   ,V.Rep_Code
										   ,To_Date (Arivl_Tm, 'DD/MM/RRRR')
										   ,Gps;


--
-- DTS_V_SMAN_ITM_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_ITM_MOVMNT
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, I_CODE, I_QTY, 
 FREE_QTY, ITM_UNT, P_SIZE, P_QTY, PF_QTY, 
 DOC_DATE, I_PRICE, W_CODE, WHG_CODE, STK_COST, 
 DIS_AMT, CUR_CODE, CUR_RATE, STOCK_RATE, CC_CODE, 
 PJ_NO, ACTV_NO, EXPIRE_DATE, BATCH_NO, RCRD_NO, 
 DOC_SER, DOC_SEQUENCE, IN_OUT, AUDIT_REF, AMT, 
 DOC_POST, INV_FLG, REP_CODE, C_CODE, A_CODE, 
 C_NAME, DOC_SER_EXTRNL, EXTERNAL_POST, TYP_NO, AD_U_ID, 
 CASH_NO, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 ADDRESS, MOBILE_NO, TEL, DOC_DESC, R_CODE, 
 VAT_AMT, OTHR_AMT, AMT_LOC, AMT_NO_TAX, AMT_LOC_NO_TAX, 
 HALF_NO, QRTR_NO, PRD_NO, MNTH, WEEK_NO, 
 DAY_NO, SMAN_TYPE, REP_CODE_PARENT, PRM_CODE, PRM_TYPE, 
 PRM_DEGREE, ROUTE_NO)
BEQUEATH DEFINER
AS 
SELECT M."DOC_TYPE",M."BILL_DOC_TYPE",M."DOC_NO",M."I_CODE",M."I_QTY",M."FREE_QTY",M."ITM_UNT",M."P_SIZE",M."P_QTY",M."PF_QTY",M."DOC_DATE",M."I_PRICE",M."W_CODE",M."WHG_CODE",M."STK_COST",M."DIS_AMT",M."CUR_CODE",M."CUR_RATE",M."STOCK_RATE",M."CC_CODE",M."PJ_NO",M."ACTV_NO",M."EXPIRE_DATE",M."BATCH_NO",M."RCRD_NO",M."DOC_SER",M."DOC_SEQUENCE",M."IN_OUT",M."AUDIT_REF",M."AMT",M."DOC_POST",M."INV_FLG",M."REP_CODE",M."C_CODE",M."A_CODE",M."C_NAME",M."DOC_SER_EXTRNL",M."EXTERNAL_POST",M."TYP_NO",M."AD_U_ID",M."CASH_NO",M."CMP_NO",M."BRN_NO",M."BRN_YEAR",M."BRN_USR",M."ADDRESS",M."MOBILE_NO",M."TEL",M."DOC_DESC",M."R_CODE",M."VAT_AMT",M."OTHR_AMT"
,(NVL(Cur_Rate,1)*NVL(Amt,0)) AMT_LOC
,(NVL(Amt,0)-NVL(VAT_AMT,0)) AMT_NO_TAX
,(NVL(Cur_Rate,1)*(NVL(Amt,0)-NVL(VAT_AMT,0))) AMT_LOC_NO_TAX
,Round (To_Char (M.Doc_Date, 'Q') / 2) Half_No
,Round (To_Char (M.Doc_Date, 'Q')) Qrtr_No
,To_Char (M.Doc_Date, 'MM') Prd_No
,To_Char (M.Doc_Date, 'MM') MNTH
,To_Char (M.Doc_Date, 'WW') Week_No
,To_Char (M.Doc_Date, 'DD') Day_No
 ,s.SMAN_TYPE
 ,s.REP_CODE_PARENT
 ,null PRM_code 
 ,null PRM_TYPE
 ,null PRM_DEGREE
 ,c.ROUTE_NO 
FROM (
   --SALES   
   Select 4 Doc_Type
         ,M.Bill_Doc_Type
         ,M.Bill_No DOC_NO
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.Bill_Date Doc_Date
         ,D.I_Price I_Price
         ,D.W_Code W_Code
         ,Post_Code Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.Bill_Currency Cur_Code
         ,M.Bill_Rate Cur_Rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.Bill_Ser Doc_Ser
         ,Doc_Sequence
         ,-1 In_Out
         ,M.Audit_Ref
        , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,1 doc_post
         ,1 inv_flg
         ,m.rep_code
         ,m.c_code
         ,M.A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SI_TYPE TYP_NO
         ,M.AD_U_ID  
         ,M.CASH_NO       
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,M.C_ADDRESS ADDRESS
         ,M.MOBILE_NO 
         ,M.C_TEL  TEL
         ,M.a_DESC DOC_DESC
         ,m.R_code
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT
     From Ias_Bill_Mst M, Ias_Bill_Dtl D
    Where     M.Bill_Ser = D.Bill_Ser        
    Union All
   --SALES
   Select 4 Doc_Type
         ,M.Bill_Doc_Type
         ,M.Bill_No
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.Bill_Date Doc_Date
         ,D.I_Price i_price
         ,D.W_Code W_Code
         ,Post_Code Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.Bill_Currency cur_code
         ,M.Bill_Rate cur_rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.Bill_Ser Doc_Ser
         ,Doc_Sequence
         ,-1 In_Out
         ,M.Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,0 doc_post
         ,1 inv_flg
         ,m.rep_code
         ,m.c_code
         ,M.A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SI_TYPE TYP_NO
         ,M.AD_U_ID
         ,M.CASH_NO
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,M.C_ADDRESS ADDRESS
         ,to_char(M.MOBILE_NO) MOBILE_NO
         ,M.C_TEL  TEL
         ,M.a_DESC DOC_DESC
         ,m.R_code
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT 
     From Ias_Bill_Mst_br M, Ias_Bill_Dtl_br D
    Where     M.Bill_Ser = D.Bill_Ser  
    and nvl(bill_post,0)=0
    and nvl(cncl_flg,0)=0                
   --RT SALES
   union all
   Select 5 Doc_Type
         ,M.Rt_Bill_Doc_Type Bill_Doc_Type
         ,M.Rt_Bill_No doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.Rt_Bill_Date Doc_Date
         ,D.I_Price i_price
         ,D.W_Code W_Code
         ,Post_Code Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.Rt_Bill_Currency cur_code
         ,M.Rt_Bill_Rate cur_rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.Rt_Bill_Ser Doc_Ser
         ,Doc_Sequence
         ,1 In_Out
         ,M.Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,1 doc_post
         ,1 inv_flg
         ,m.rep_code
         ,m.c_code
         ,M.A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SR_TYPE TYP_NO
         ,M.AD_U_ID
         ,M.CASH_NO
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,Null ADDRESS
         , Null MOBILE_NO 
         ,M.C_TEL  TEL
         ,M.a_DESC  DOC_DESC
         ,m.R_code 
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT
     From Ias_Rt_Bill_Mst M, Ias_Rt_Bill_Dtl D
    Where     M.Rt_Bill_Ser = D.Rt_Bill_Ser     
    union all
   Select 5 Doc_Type
         ,M.Rt_Bill_Doc_Type Bill_Doc_Type
         ,M.Rt_Bill_No doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.Rt_Bill_Date Doc_Date
         ,D.I_Price I_Price
         ,D.W_Code W_Code
         ,Post_Code Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.Rt_Bill_Currency cur_code
         ,M.Rt_Bill_Rate cur_rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.Rt_Bill_Ser Doc_Ser
         ,Doc_Sequence
         ,1 In_Out
         ,M.Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,0 doc_post
         ,1 inv_flg
         ,m.rep_code
         ,m.c_code
         ,M.A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SR_TYPE TYP_NO
         ,M.AD_U_ID
         ,M.CASH_NO
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,Null ADDRESS
         , Null MOBILE_NO 
         ,Null  TEL
         ,M.a_DESC doc_desc
         ,m.R_code
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ) ,4)OTHR_AMT 
     From Ias_Rt_Bill_Mst_br M, Ias_Rt_Bill_Dtl_br D
    Where     M.Rt_Bill_Ser = D.Rt_Bill_Ser 
    and nvl(rt_bill_post,0)=0
    and nvl(cncl_flg,0)=0     
    --Ias_Rt_Bill_Mst_rq
     union all     
   Select 136 Doc_Type
         ,M.Rt_Bill_Doc_Type Bill_Doc_Type
         ,M.Rt_Bill_No doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.Rt_Bill_Date Doc_Date
         ,D.I_Price i_price
         ,D.W_Code W_Code
         ,Post_Code Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.Rt_Bill_Currency cur_code
         ,M.Rt_Bill_Rate cur_rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.Rt_Bill_Ser Doc_Ser
         ,Doc_Sequence
         ,0 In_Out
         ,0 Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,1 doc_post
         ,0 inv_flg
         ,m.rep_code
         ,m.c_code
         ,M.A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SR_TYPE TYP_NO
         ,M.AD_U_ID
         ,M.CASH_NO
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
        , null ADDRESS
         ,null MOBILE_NO 
         ,Null  TEL
         ,M.A_DESC DOC_DESC
         ,m.R_code
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT 
     From Ias_Rt_Bill_Mst_rq M, Ias_Rt_Bill_Dtl_rq D
    Where     M.Rt_Bill_Ser = D.Rt_Bill_Ser                          
   Union All
   --SALES order   
   Select 53 Doc_Type
         ,M.Bill_Doc_Type
         ,M.order_no doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.order_Date Doc_Date
         ,D.I_Price I_Price
         ,D.W_Code W_Code
         ,null Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.ORDER_CUR cur_code
         ,M.Cur_Rate
         ,M.Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.order_Ser Doc_Ser
         ,doc_seq Doc_Sequence
         ,0 In_Out
         ,0 Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(Order_amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(Order_amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,1 doc_post
         ,0 inv_flg
         ,m.rep_code
         ,m.c_code
         ,NULL A_CODE
         ,m.c_name
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.SO_TYPE TYP_NO
         ,M.AD_U_ID
         ,NULL CASH_NO
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,M.C_ADDRESS ADDRESS
         ,M.MOBILE_NO 
         ,null  TEL
         ,M.A_DESC DOC_DESC
         ,m.R_code 
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Order_amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Order_amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT
     From sales_order M, order_detail D
    Where     M.order_Ser = D.order_Ser    
    Union All
   ---QUOTATION      
   Select 52 Doc_Type
         ,M.QUOT_DOC_TYPE Bill_Doc_Type
         ,M.QUOT_no doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         , (D.Free_Qty * D.P_Size) Pf_Qty
         ,M.QUOT_DATE Doc_Date
         ,D.I_Price I_Price
         ,D.W_Code W_Code
         ,null Whg_Code
         ,D.Stk_Cost Stk_Cost
         ,D.Dis_Amt Dis_Amt
         ,M.QUOT_cur cur_code
         ,M.Cur_Rate
         ,0 Stock_Rate
         ,D.Cc_Code Cc_Code
         ,D.Pj_No Pj_No
         ,D.Actv_No Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.QUOT_ser Doc_Ser
         ,Doc_Sequence Doc_Sequence
         ,0 In_Out
         ,0 Audit_Ref
         , Round( (NVL(I_PRICE,0) * NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT,0)* Decode(QUOT_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))
        +(NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))
        +(NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0))
        -( (NVL(D.DIS_AMT,0)* NVL(I_QTY,0))
        +(NVL(D.OTHR_AMT_DISC,0)*Decode(QUOT_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) )
        +(NVL(D.Dis_Amt_Aftr_Vat,0)* NVL(I_QTY,0))
        ),4) Amt
         ,1 doc_post
         ,0 inv_flg
         ,m.rep_code
         ,m.c_code
         ,NULL A_CODE
         ,m.c_name 
         ,m.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,M.QT_TYPE TYP_NO
         ,M.AD_U_ID  
         ,NULL CASH_NO      
         ,M.Cmp_No Cmp_No
         ,M.Brn_No Brn_No
         ,M.Brn_Year Brn_Year
         ,M.Brn_Usr Brn_Usr
         ,Null ADDRESS
         ,null MOBILE_NO 
         ,null   TEL
         ,M.a_desc DOC_DESC
         ,Null R_code 
         ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
         ,ROUND((NVL(D.OTHR_AMT,0)* Decode(QUOT_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(QUOT_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT
     From QUOTATION M, QUOTATION_DETAIL D
    Where     M.QUOT_ser = D.QUOT_SER
    --Ias_Out_Reques
    UNION ALL
    Select 31 Doc_Type
         ,NULL Bill_Doc_Type
         ,M.OUT_REQ_NO doc_no
         ,D.I_Code
         ,D.I_Qty I_Qty
         ,0 Free_Qty
         ,D.Itm_Unt Itm_Unt
         ,D.P_Size
         , (D.I_Qty * D.P_Size) P_Qty
         ,0 Pf_Qty
         ,M.OUT_REQ_DATE Doc_Date
         ,0 I_Price
         ,D.W_Code W_Code
         ,null Whg_Code
         ,0 Stk_Cost
         ,0 Dis_Amt
         ,Ias_Gen_Pkg.Get_Local_CUR cur_code
         ,1 Cur_Rate
         ,0 Stock_Rate
         ,NULL Cc_Code
         ,NULL Pj_No
         ,NULL Actv_No
         ,Expire_Date
         ,Batch_No
         ,Rcrd_No
         ,M.OUT_REQ_SER Doc_Ser
         ,Doc_Sequence Doc_Sequence
         ,0 In_Out
         ,0 Audit_Ref
