     From Ias_Out_Request_Mst M, Ias_Out_Request_DTL D ,SALES_MAN S
    Where     M.OUT_REQ_SER = D.OUT_REQ_SER  
    AND S.W_CODE=M.W_CODE
    --DTS_STK_CST 
    UNION ALL    
    Select 1410 Doc_Type
         ,NULL Bill_Doc_Type
         ,M.DOC_NO doc_no
