         ,M.doc_desc DOC_DESC
         ,Null R_code 
         ,0 VAT_AMT
         ,0 OTHR_AMT
     From DTS_STK_CST_MST M, DTS_STK_CST_DTL D,SALES_MAN S 
    Where    M.DOC_SER = D.DOC_SER  
    AND M.REP_CODE=S.REPRS_CODE
    --Dts_Free_Smpl 
