     From Dts_Free_Smpl_Mst M, Dts_Free_Smpl_DTL D
    Where    M.DOC_SER = D.DOC_SER
    --Ars_Questnnr
    UNION ALL
    Select 1407 Doc_Type
         ,NULL Bill_Doc_Type
         ,M.DOC_NO doc_no
         ,D.I_Code
         ,0  I_Qty
         ,0 Free_Qty
         ,NULL Itm_Unt
         ,1 P_Size
         , 0 P_Qty
         ,0 Pf_Qty
         ,M.DOC_DATE Doc_Date
         ,0 I_Price
         ,NULL W_Code
         ,null Whg_Code
         ,0 Stk_Cost
         ,0 Dis_Amt
         ,Ias_Gen_Pkg.Get_Local_CUR cur_code
         ,1 Cur_Rate
         ,0 Stock_Rate
         ,NULL Cc_Code
         ,NULL Pj_No
         ,NULL Actv_No
         ,NULL Expire_Date
         ,NULL Batch_No
         ,Rcrd_No
         ,M.DOC_SER Doc_Ser
         ,0 Doc_Sequence
         ,0 In_Out
         ,0 Audit_Ref
         , 0 Amt
         ,1 doc_post
         ,2 inv_flg
         ,M.rep_code
         ,m.c_code
         ,NULL A_CODE
         ,NULL c_name 
         ,m.DOC_SER_EXTRNL
         ,70 EXTERNAL_POST
         ,NULL TYP_NO
