--
-- DTS_V_SP_SMAN_ITM_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SP_SMAN_ITM_MOVMNT
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, I_CODE, I_QTY, 
 FREE_QTY, ITM_UNT, P_SIZE, P_QTY, PF_QTY, 
 DOC_DATE, I_PRICE, W_CODE, WHG_CODE, STK_COST, 
 DIS_AMT, CUR_CODE, CUR_RATE, STOCK_RATE, CC_CODE, 
 PJ_NO, ACTV_NO, EXPIRE_DATE, BATCH_NO, RCRD_NO, 
 DOC_SER, DOC_SEQUENCE, IN_OUT, AUDIT_REF, AMT, 
 DOC_POST, INV_FLG, C_CODE, A_CODE, C_NAME, 
 DOC_SER_EXTRNL, EXTERNAL_POST, TYP_NO, AD_U_ID, CASH_NO, 
 CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, ADDRESS, 
 MOBILE_NO, TEL, DOC_DESC, R_CODE, REP_CODE, 
 PRM_CODE, SI_CMPNS, CODE_NO, F_TIME, T_TIME, 
 VST_STS, PRM_STS, VST_RSLT, VST_PURPOSE, ITM_VST_PURPOSE, 
 NOTES, RECOM, PRM_OPIN, PRM_NOTES, VAT_AMT, 
 OTHR_AMT, HALF_NO, QRTR_NO, PRD_NO, MNTH, 
 WEEK_NO, DAY_NO, PRD_DAY, SMAN_TYPE, REP_CODE_PARENT, 
 PRM_TYPE, PRM_DEGREE, ROUTE_NO, PIVOT_CODE, BILL_I_QTY, 
 BILL_FREE_QTY, BILL_AMT, BILL_AMT_NO_TAX, RT_I_QTY, RT_FREE_QTY, 
 RT_BILL_AMT, RT_BILL_AMT_NO_TAX, NET_I_QTY, NET_FREE_QTY, NET_AMT, 
 NET_AMT_NO_TAX, CMPNS_QTY, CMPNS_AMT, SMPL_QTY, CNT_VST, 
 CNT_PRM, VIST_DATE, AMT_LOC, AMT_NO_TAX, AMT_LOC_NO_TAX, 
 CNT_PLN_VST)
BEQUEATH DEFINER
AS 
Select M."DOC_TYPE",M."BILL_DOC_TYPE",M."DOC_NO",M."I_CODE",M."I_QTY",M."FREE_QTY",M."ITM_UNT",M."P_SIZE",M."P_QTY",M."PF_QTY",M."DOC_DATE",M."I_PRICE",M."W_CODE",M."WHG_CODE",M."STK_COST",M."DIS_AMT",M."CUR_CODE",M."CUR_RATE",M."STOCK_RATE",M."CC_CODE",M."PJ_NO",M."ACTV_NO",M."EXPIRE_DATE",M."BATCH_NO",M."RCRD_NO",M."DOC_SER",M."DOC_SEQUENCE",M."IN_OUT",M."AUDIT_REF",M."AMT",M."DOC_POST",M."INV_FLG",M."C_CODE",M."A_CODE",M."C_NAME",M."DOC_SER_EXTRNL",M."EXTERNAL_POST",M."TYP_NO",M."AD_U_ID",M."CASH_NO",M."CMP_NO",M."BRN_NO",M."BRN_YEAR",M."BRN_USR",M."ADDRESS",M."MOBILE_NO",M."TEL",M."DOC_DESC",M."R_CODE",M."REP_CODE",M."PRM_CODE",M."SI_CMPNS",M."CODE_NO",M."F_TIME",M."T_TIME",M."VST_STS",M."PRM_STS",M."VST_RSLT",M."VST_PURPOSE",M."ITM_VST_PURPOSE",M."NOTES",M."RECOM",M."PRM_OPIN",M."PRM_NOTES",M."VAT_AMT",M."OTHR_AMT"                                               
         ,Round (To_Char (M.Doc_Date, 'Q') / 2) Half_No
         ,Round (To_Char (M.Doc_Date, 'Q')) Qrtr_No
         ,To_Char (M.Doc_Date, 'MM') Prd_No
         ,To_Char (M.Doc_Date, 'MM') MNTH
         ,To_Char (M.Doc_Date, 'WW') WEEK_NO
         ,To_Char (M.Doc_Date, 'DD') Day_No
         ,to_char(TO_DATE(F_Time,'HH24:MI:SS'),'AM') PRD_DAY
         ,s.SMAN_TYPE
         ,s.REP_CODE_PARENT 
         ,d.PRM_TYPE
         ,d.PRM_DEGREE
         ,D.ROUTE_NO 
         ,CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=0 THEN 'SAL'
               WHEN DOC_TYPE=5 AND NVL(SI_CMPNS,0)=0 THEN 'RT_SAL' 
               WHEN DOC_TYPE IN(4,5) AND NVL(SI_CMPNS,0)=1 THEN 'CMPNS'
               WHEN DOC_TYPE=1412  THEN 'SMPLS'
               WHEN DOC_TYPE=1413  THEN 'VSTS'
               ELSE NULL END  PIVOT_CODE       
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=0 THEN NVL(P_QTY,0) ELSE NULL END ) BILL_I_QTY
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=0 THEN NVL(PF_QTY,0) ELSE NULL END ) BILL_FREE_QTY
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=0 THEN NVL(AMT,0) ELSE NULL END ) BILL_AMT
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=0 THEN (NVL(AMT,0)-NVL(VAT_AMT,0)) ELSE NULL END ) BILL_AMT_NO_TAX
          ,(CASE WHEN DOC_TYPE=5 AND NVL(SI_CMPNS,0)=0 THEN NVL(P_QTY,0) ELSE NULL END ) RT_I_QTY
          ,(CASE WHEN DOC_TYPE=5 AND NVL(SI_CMPNS,0)=0 THEN NVL(PF_QTY,0) ELSE NULL END ) RT_FREE_QTY
          ,(CASE WHEN DOC_TYPE=5 AND NVL(SI_CMPNS,0)=0 THEN NVL(AMT,0) ELSE NULL END ) RT_BILL_AMT
          ,(CASE WHEN DOC_TYPE=5 AND NVL(SI_CMPNS,0)=0 THEN (NVL(AMT,0)-NVL(VAT_AMT,0)) ELSE NULL END ) RT_BILL_AMT_NO_TAX
          ,(CASE WHEN DOC_TYPE IN(4,5) AND NVL(SI_CMPNS,0)=0 THEN NVL(P_QTY,0)*IN_OUT ELSE NULL END ) NET_I_QTY
          ,(CASE WHEN DOC_TYPE IN(4,5) AND NVL(SI_CMPNS,0)=0 THEN NVL(PF_QTY,0)*IN_OUT ELSE NULL END ) NET_FREE_QTY
          ,(CASE WHEN DOC_TYPE IN(4,5) AND NVL(SI_CMPNS,0)=0 THEN NVL(AMT,0)*IN_OUT ELSE NULL END ) NET_AMT
          ,(CASE WHEN DOC_TYPE IN(4,5) AND NVL(SI_CMPNS,0)=0 THEN (NVL(AMT,0)-NVL(VAT_AMT,0))*IN_OUT ELSE NULL END ) NET_AMT_NO_TAX
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=1 THEN NVL(P_QTY,0) ELSE NULL END ) CMPNS_QTY
          ,(CASE WHEN DOC_TYPE=4 AND NVL(SI_CMPNS,0)=1 THEN NVL(I_QTY,0)*I_PRICE ELSE NULL END ) CMPNS_AMT
          ,(CASE WHEN DOC_TYPE=1412  THEN NVL(I_QTY,0) ELSE NULL END ) SMPL_QTY      
          ,( CASE WHEN DOC_TYPE=1413  THEN 1 ELSE NULL END ) CNT_VST
          ,( CASE WHEN DOC_TYPE=1413  and M.PRM_CODE Is Not Null THEN 1 ELSE NULL END ) CNT_PRM
          ,( CASE WHEN DOC_TYPE=1413  THEN DOC_DATE ELSE NULL END ) VIST_DATE              
         , (Nvl (Cur_Rate, 1) * Nvl (Amt, 0)) Amt_Loc  
         ,(NVL(Amt,0)-NVL(VAT_AMT,0)) AMT_NO_TAX
         ,(NVL(Cur_Rate,1)*(NVL(Amt,0)-NVL(VAT_AMT,0))) AMT_LOC_NO_TAX 
          ,( CASE WHEN DOC_TYPE=1401  and M.C_CODE Is Not Null THEN 1 ELSE NULL END ) CNT_PLN_VST     
     From ( --SALES     
           Select 4 Doc_Type
                 ,M.Bill_Doc_Type
                 ,M.Bill_No Doc_No
                 ,D.I_Code
                 ,D.I_Qty   
                 ,Free_Qty                 
                 ,D.Itm_Unt Itm_Unt
                 ,D.P_Size
                 , (D.I_Qty * D.P_Size) P_Qty
                 , (D.Free_Qty * D.P_Size)Pf_Qty                
                 ,M.Bill_Date Doc_Date
                 ,D.I_Price I_Price
                 ,D.W_Code W_Code
                 ,Post_Code Whg_Code
                 ,D.Stk_Cost Stk_Cost
                 ,D.Dis_Amt Dis_Amt
                 ,M.Bill_Currency Cur_Code
                 ,M.Bill_Rate Cur_Rate
                 ,M.Stock_Rate
                 ,D.Cc_Code Cc_Code
                 ,D.Pj_No Pj_No
                 ,D.Actv_No Actv_No
                 ,Expire_Date
                 ,Batch_No
                 ,Rcrd_No
                 ,M.Bill_Ser Doc_Ser
                 ,Doc_Sequence
                 ,1 In_Out
                 ,M.Audit_Ref
                 ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Amt
                 ,1 Doc_Post
                 ,1 Inv_Flg                 
                 ,M.C_Code
                 ,M.A_Code
                 ,M.C_Name
                 ,M.Doc_Ser_Extrnl
                 ,M.External_Post
                 ,M.Si_Type Typ_No
                 ,M.Ad_U_Id
                 ,M.Cash_No
                 ,M.Cmp_No Cmp_No
                 ,M.Brn_No Brn_No
                 ,M.Brn_Year Brn_Year
                 ,M.Brn_Usr Brn_Usr
                 ,M.C_Address Address
                 ,M.Mobile_No
                 ,M.C_Tel Tel
                 ,M.A_Desc Doc_Desc
                 ,M.R_Code
                 ,D.REP_CODE_SP REP_CODE
                 ,D.PRM_CODE_OUT  PRM_CODE                
                 ,s.SI_CMPNS
                 ,null CODE_NO
                 ,null F_TIME
                 ,null T_TIME
                 ,null VST_STS
                 ,null PRM_STS
                  ,null VST_RSLT
                 ,null VST_PURPOSE
                 ,null ITM_VST_PURPOSE
                 ,null NOTES
                 ,null RECOM
                 ,null PRM_OPIN 
                 ,null PRM_NOTES
                  ,ROUND((NVL(D.VAT_AMT,0)* (NVL(I_QTY,0)+(NVL(FREE_QTY,0)*NVL(CLC_TAX_FREE_QTY_FLG,0))))+ (NVL(D.Vat_Amt_Othr,0)* NVL(I_QTY,0)),4) VAT_AMT
                ,ROUND((NVL(D.OTHR_AMT,0)* Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)))+(NVL(D.OTHR_AMT_DISC,0)*Decode(Bill_Amt,0,NVL(FREE_QTY,0),NVL(I_QTY,0)) ),4 )OTHR_AMT
             From Ias_Bill_Mst M, Ias_Bill_Dtl D,IAS_SALES_TYPES S
            Where M.Bill_Ser = D.Bill_Ser
            and m.SI_TYPE=s.SI_TYPE
            and D.REP_CODE_SP is Not Null            
           Union All
           --SALES
           Select 4 Doc_Type
                 ,M.Bill_Doc_Type
                 ,M.Bill_No Doc_No
                 ,D.I_Code
                 ,D.I_Qty   
                 ,Free_Qty                
                 ,D.Itm_Unt Itm_Unt
                 ,D.P_Size
                  , (D.I_Qty * D.P_Size) P_Qty
                 , (D.Free_Qty * D.P_Size)Pf_Qty                 
                 ,M.Bill_Date Doc_Date
                 ,D.I_Price I_Price
                 ,D.W_Code W_Code
                 ,Post_Code Whg_Code
                 ,D.Stk_Cost Stk_Cost
                 ,D.Dis_Amt Dis_Amt
                 ,M.Bill_Currency Cur_Code
                 ,M.Bill_Rate Cur_Rate
                 ,M.Stock_Rate
                 ,D.Cc_Code Cc_Code
                 ,D.Pj_No Pj_No
                 ,D.Actv_No Actv_No
                 ,Expire_Date
                 ,Batch_No
                 ,Rcrd_No
                 ,M.Bill_Ser Doc_Ser
                 ,Doc_Sequence
                 ,1 In_Out
                 ,M.Audit_Ref
                 ,Round ( (Nvl (I_Price, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Vat_Amt, 0) * (Nvl (I_Qty, 0) + (Nvl (Free_Qty, 0) * Nvl (Clc_Tax_Free_Qty_Flg, 0)))) + (Nvl (D.Vat_Amt_Othr, 0) * Nvl (I_Qty, 0)) - ( (Nvl (D.Dis_Amt, 0) * Nvl (I_Qty, 0)) + (Nvl (D.Othr_Amt_Disc, 0) * Decode (Bill_Amt, 0, Nvl (Free_Qty, 0), Nvl (I_Qty, 0))) + (Nvl (D.Dis_Amt_Aftr_Vat, 0) * Nvl (I_Qty, 0))), 4) Amt
                 ,0 Doc_Post
                 ,1 Inv_Flg                 
                 ,M.C_Code
                 ,M.A_Code
                 ,M.C_Name
                 ,M.Doc_Ser_Extrnl
                 ,M.External_Post
                 ,M.Si_Type Typ_No
                 ,M.Ad_U_Id
                 ,M.Cash_No
                 ,M.Cmp_No Cmp_No
                 ,M.Brn_No Brn_No
                 ,M.Brn_Year Brn_Year
                 ,M.Brn_Usr Brn_Usr
                 ,M.C_Address Address
                 ,M.Mobile_No
                 ,M.C_Tel Tel
                 ,M.A_Desc Doc_Desc
                 ,M.R_Code
                 ,D.REP_CODE_SP REP_CODE
