--
-- GLS_V_CASH_FLOW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GLS_V_CASH_FLOW
(FLOW_TYPE, AC_CODE, AMT)
BEQUEATH DEFINER
AS 
SELECT FLOW_TYPE, AC_CODE, SUM (AMT)
        FROM GLS_V_CASH_FLOW_LIST
    GROUP BY ROLLUP (FLOW_TYPE, AC_CODE);


--
-- GNR_TAX_SALES_NO_VAT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_SALES_NO_VAT_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 A_CY, CLC_TYP_NO_TAX, VAT_TYPE, VAT_AMT, DOC_AMT)
BEQUEATH DEFINER
AS 
SELECT Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             SUM (
                   (  NVL (Ias_Bill_Dtl.Vat_Amt, 0)
                    + NVL (Ias_Bill_Dtl.Vat_Amt_Othr, 0))
                 * NVL (Ias_Bill_Dtl.I_Qty, 0)
                 * NVL (Ias_Bill_Mst.Bill_Rate, 1))
                 Vat_Amt,
             (  DECODE (
                    CALC_VAT_AMT_TYPE,
                    1, SUM (
                             NVL (Ias_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)),
                    2, SUM (
                             (  (  NVL (Ias_Bill_Dtl.I_Price, 0)
                                 - (  NVL (Ias_Bill_Dtl.Dis_Amt_Mst, 0)
                                    + NVL (Ias_Bill_Dtl.Dis_Amt_Dtl, 0)))
                              + (NVL (Ias_Bill_Dtl.Othr_Amt, 0)))
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Bill_Mst,
             Ias_Bill_Dtl,
             Ias_Itm_Mst,
             IAS_PARA_AR
       WHERE     Ias_Bill_Mst.Bill_Ser = Ias_Bill_Dtl.Bill_Ser
             AND Ias_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Bill_Mst.CLC_TYP_NO_TAX) = 0
             AND NVL (Ias_Bill_Dtl.Vat_Per, 0) = 0
    GROUP BY Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             CALC_VAT_AMT_TYPE
    UNION ALL
      SELECT Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             SUM (
                   (  NVL (Ias_Bill_Dtl.Vat_Amt, 0)
                    + NVL (Ias_Bill_Dtl.Vat_Amt_Othr, 0))
                 * NVL (Ias_Bill_Dtl.I_Qty, 0)
                 * NVL (Ias_Bill_Mst.Bill_Rate, 1))
                 Vat_Amt,
             (  DECODE (
                    CALC_VAT_AMT_TYPE,
                    1, SUM (
                             NVL (Ias_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)),
                    2, SUM (
                             (  (  NVL (Ias_Bill_Dtl.I_Price, 0)
                                 - (  NVL (Ias_Bill_Dtl.Dis_Amt_Mst, 0)
                                    + NVL (Ias_Bill_Dtl.Dis_Amt_Dtl, 0)))
                              + (NVL (Ias_Bill_Dtl.Othr_Amt, 0)))
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Bill_Mst,
             Ias_Bill_Dtl,
             Ias_Itm_Mst,
             IAS_PARA_AR
       WHERE     Ias_Bill_Mst.Bill_Ser = Ias_Bill_Dtl.Bill_Ser
             AND Ias_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Bill_Mst.CLC_TYP_NO_TAX) IN
                     (2, 3, 4)
    GROUP BY Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             CALC_VAT_AMT_TYPE
    UNION ALL
      SELECT Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax
                 Clc_Typ_No_Tax,
                 IAS_ITM_MST.VAT_TYPE,
             SUM (
                   (  NVL (Ias_Bill_Dtl.Vat_Amt, 0)
                    + NVL (Ias_Bill_Dtl.Vat_Amt_Othr, 0))
                 * NVL (Ias_Bill_Dtl.I_Qty, 0)
                 * NVL (Ias_Bill_Mst.Bill_Rate, 1))
                 Vat_Amt,
             (  DECODE (
                    CALC_VAT_AMT_TYPE,
                    1, SUM (
                             NVL (Ias_Bill_Dtl.I_Price, 0)
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)),
                    2, SUM (
                             (  (  NVL (Ias_Bill_Dtl.I_Price, 0)
                                 - (  NVL (Ias_Bill_Dtl.Dis_Amt_Mst, 0)
                                    + NVL (Ias_Bill_Dtl.Dis_Amt_Dtl, 0)))
                              + (NVL (Ias_Bill_Dtl.Othr_Amt, 0)))
                           * NVL (Ias_Bill_Dtl.I_Qty, 0)
                           * NVL (Ias_Bill_Mst.Bill_Rate, 1)))
              * -1)
                 Bill_Amt
        FROM Ias_Bill_Mst,
             Ias_Bill_Dtl,
             Ias_Itm_Mst,
             IAS_PARA_AR
       WHERE     Ias_Bill_Mst.Bill_Ser = Ias_Bill_Dtl.Bill_Ser
             AND Ias_Bill_Dtl.I_Code = Ias_Itm_Mst.I_Code
             AND YS_TAX_PKG.GET_TAX_TYP_NO (Ias_Bill_Mst.CLC_TYP_NO_TAX) = 1
    GROUP BY Ias_Bill_Mst.Bill_Ser,
             Ias_Bill_Mst.Bill_No,
             Ias_Bill_Mst.Bill_Date,
             Ias_Bill_Mst.Bill_Currency,
             Ias_Bill_Mst.Clc_Typ_No_Tax,
             IAS_ITM_MST.VAT_TYPE,
             Ias_Bill_Mst.BRN_NO,
             Ias_Bill_Mst.CMP_NO,
             CALC_VAT_AMT_TYPE;


--
-- IAS_V_ARS_ALL_TRANS_PAID  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ARS_ALL_TRANS_PAID
BEQUEATH DEFINER
AS 
Select * From (
							Select Ac_Code_Dtl C_Code , Voucher_Detail.Bill_No , Voucher_Detail.Bill_Ser, I_Amt, Ias_V_Ars_Up_Installment.I_No,'Voucher' Type, Voucher_No , Brn_Year, Abs(Ac_Amt) Amt
							From Voucher_Detail , Ias_V_Ars_Up_Installment
							Where 1 = 1
							And Voucher_Detail.Ac_Code_Dtl = Ias_V_Ars_Up_Installment.C_Code
							And Voucher_Detail.Bill_Ser = Ias_V_Ars_Up_Installment.Bill_Ser 
							And Ias_V_Ars_Up_Installment.I_No = Voucher_Detail.I_No
							--and I_AMT < P_AMT + J_AMT 
							Union All                                        
							Select Ac_Code_Dtl C_Code , Voucher_Detail.Bill_No , Voucher_Detail.Bill_Ser, I_Amt, Ias_V_Ars_Up_Installment.I_No,'Voucher' Type, Voucher_No , Brn_Year, Abs(Ac_Amt) Amt
							From IAS20271.Voucher_Detail , Ias_V_Ars_Up_Installment
							Where 1 = 1
							And Voucher_Detail.Ac_Code_Dtl = Ias_V_Ars_Up_Installment.C_Code
							And Voucher_Detail.Bill_Ser = Ias_V_Ars_Up_Installment.Bill_Ser 
							And Ias_V_Ars_Up_Installment.I_No = Voucher_Detail.I_No
							--and I_AMT < P_AMT + J_AMT 
							Union All
							Select  Ias_V_Ars_Up_Installment.C_Code , Bill_No , Bill_Ser, Ias_V_Ars_Up_Installment.I_Amt , Ias_V_Ars_Up_Installment.I_No,'CST' Typ , Doc_No , Brn_Year , Abs(Paid_Amt_Doc) Amt 
							From Ias_Adjst_Installment_Dtl , Ias_V_Ars_Up_Installment
							Where Ias_Adjst_Installment_Dtl.C_Code = Ias_V_Ars_Up_Installment.C_Code
							And Ias_Adjst_Installment_Dtl.Doc_Ser_Ref =  Ias_V_Ars_Up_Installment.Bill_Ser
							And Ias_V_Ars_Up_Installment.I_No = Ias_Adjst_Installment_Dtl.I_No
							--AND Ias_V_Ars_Up_Installment.I_AMT < P_AMT + Ias_V_Ars_Up_Installment.J_AMT
							Union All
							Select Ias_V_Ars_Up_Installment.C_Code , Bill_No , Bill_Ser, Ias_V_Ars_Up_Installment.I_Amt , Ias_V_Ars_Up_Installment.I_No, 'CST' Typ , Doc_No , Brn_Year , Abs(Paid_Amt_Doc) Amt 
							From IAS20271.Ias_Adjst_Installment_Dtl , Ias_V_Ars_Up_Installment
							Where Ias_Adjst_Installment_Dtl.C_Code = Ias_V_Ars_Up_Installment.C_Code
							And Ias_Adjst_Installment_Dtl.Doc_Ser_Ref =  Ias_V_Ars_Up_Installment.Bill_Ser
							And Ias_V_Ars_Up_Installment.I_No = Ias_Adjst_Installment_Dtl.I_No
							--AND Ias_V_Ars_Up_Installment.I_AMT < P_AMT + Ias_V_Ars_Up_Installment.J_AMT
							Union All
							             Select Ias_V_Ars_Up_Installment.C_Code,
							                    Detail_Journal_V.Bill_No,
							                    Detail_Journal_V.Bill_Ser,
							                    Ias_V_Ars_Up_Installment.I_Amt,
							                    Ias_V_Ars_Up_Installment.I_No,
							                    'JV' Typ,
							                    J_Doc_No,
							                    Brn_Year,
							                    Abs (Detail_Journal_V.J_Amt) Amt
							               From Detail_Journal_V, Ias_V_Ars_Up_Installment
							              Where     Detail_Journal_V.Ac_Code_Dtl =
							                           Ias_V_Ars_Up_Installment.C_Code
							                    And Detail_Journal_V.Bill_Ser =
							                           Ias_V_Ars_Up_Installment.Bill_Ser 
							                           And Ias_V_Ars_Up_Installment.I_No = Detail_Journal_V.I_No
							                           Union All
							                           Select Ias_V_Ars_Up_Installment.C_Code,
							                    Detail_Journal_V.Bill_No,
							                    Detail_Journal_V.Bill_Ser,
							                    Ias_V_Ars_Up_Installment.I_Amt,
							                    Ias_V_Ars_Up_Installment.I_No,
							                    'JV' Typ,
							                    J_Doc_No,
							                    Brn_Year,
							                    Abs (Detail_Journal_V.J_Amt) Amt
							               From IAS20271.Detail_Journal_V, Ias_V_Ars_Up_Installment
							              Where     Detail_Journal_V.Ac_Code_Dtl =
							                           Ias_V_Ars_Up_Installment.C_Code
							                    And Detail_Journal_V.Bill_Ser =
							                           Ias_V_Ars_Up_Installment.Bill_Ser 
							                           And Ias_V_Ars_Up_Installment.I_No = Detail_Journal_V.I_No
							)
							Order By 1,2;


--
-- IAS_V_BILL_AMT_ERR  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_BILL_AMT_ERR
(BILL_SER, BILL_AMT, DISC_AMT, OTHR_AMT)
BEQUEATH DEFINER
AS 
Select bill_ser,round(nvl(bill_amt,0),3) bill_amt,round(nvl(disc_amt,0),3) disc_amt,round(nvl(othr_amt,0),3) Othr_amt
   From IAS_BILL_MST
  where bill_ser Is Not Null
    and nvl(bill_post,0)=0
 Minus
 Select bill_ser,round(nvl(sum(nvl(i_qty,0)*nvl(i_price,0)),0),3),round(nvl(sum(nvl(i_qty,0)*nvl(dis_amt,0)),0),3) ,
        round(nvl(sum(nvl(i_qty,0)*nvl(othr_amt,0)),0),3)
   From IAS_BILL_DTL
  where bill_ser Is Not Null
    group by bill_ser;


