--
-- IAS_V_ITM_WCODE_ONLINE_OLD  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_ITM_WCODE_ONLINE_OLD
(I_CODE, I_NAME, ITM_UNT, G_CODE, W_CODE, 
 EXPIRE_DATE, BATCH_NO, AVL_QTY, RSRV_QTY, NOT_OUT_QTY, 
 NOT_RTRN_QTY, I_PRICE, DIS_AMT, DIS_PER, QUT_AMT, 
 QUT_PER, CUR_CODE, CONN_BRN_NO, I_IMG, SHO_SYS_TYP, 
 LAST_UPDATE, USE_GRANT, GRANT_PERIOD, SHO_I_CODE, SHO_W_CODE, 
 PRDCT_ID, CLC_VAT_PRICE_TYP, CLC_TYP_NO_TAX, VAT_PER, FIELD1, 
 FIELD2, FIELD3, FIELD4, FIELD5, FIELD6, 
 FIELD7, FIELD8, FIELD9, FIELD10, FIELD11, 
 FIELD12, FIELD13, FIELD14, FIELD15, FIELD16, 
 FIELD17, FIELD18, FIELD19, FIELD20)
BEQUEATH DEFINER
AS 
SELECT 
           M.I_CODE,
           M.I_NAME,
           D.ITM_UNT,
           M.G_Code,
           MOV.W_CODE,
           NVL (MOV.EXPIRE_DATE, TO_DATE ('01/01/1900', 'DD/MM/YYYY'))
               EXPIRE_DATE,
           NVL (MOV.BATCH_NO, '0')
               BATCH_NO,
           (MOV.AVL_QTY / D.P_SIZE)
               AVL_QTY,
           (SELECT NVL (SUM (NVL (CP_QTY, 0)), 0) / NVL (D.P_SIZE, 1)
              FROM IAS_RESERVE_DTL
             WHERE     I_CODE = M.I_CODE
                   AND NVL (W_CODE, 0) = MOV.W_CODE
                   AND T_DATE >= SYSDATE
                   AND NVL (RESERVED, 0) = 1
                   AND NVL (CP_QTY, 0) >= 0)
               RSRV_QTY,
           DECODE (
               AR.USE_OUT_BILLS,
               0, 0,
               (SELECT SUM (
                             (  (NVL (DB.I_Qty, 0) - NVL (DB.Out_Qty, 0))
                              + (  NVL (DB.Free_Qty, 0)
                                 - NVL (DB.Out_Free_Qty, 0)))
                           * NVL (DB.P_Size, 1))
                  FROM Ias_Bill_Mst MB, Ias_Bill_Dtl DB
                 WHERE     MB.Bill_Ser = DB.Bill_Ser
                       AND DB.I_Code = M.I_CODE
                       AND DB.W_Code = MOV.W_CODE
                       AND DB.Expire_Date =
                           NVL (MOV.EXPIRE_DATE, DB.Expire_Date)
                       AND DB.Batch_No = NVL (MOV.BATCH_NO, DB.Batch_No)))
               NOT_OUT_QTY,
           DECODE (
               AR.USE_OUT_BILLS,
               0, 0,
               (SELECT SUM (
                             (  (NVL (DB.I_Qty, 0) - NVL (DB.Ret_Qty, 0))
                              + (  NVL (DB.Free_Qty, 0)
                                 - NVL (DB.Ret_Free_Qty, 0)))
                           * NVL (DB.P_Size, 1))
                  FROM Ias_Rt_Bill_Mst MB, Ias_Rt_Bill_Dtl DB
                 WHERE     MB.Rt_Bill_Ser = DB.Rt_Bill_Ser
                       AND DB.I_Code = M.I_CODE
                       AND DB.W_Code = MOV.W_CODE
                       AND DB.Expire_Date =
                           NVL (MOV.EXPIRE_DATE, DB.Expire_Date)
                       AND DB.Batch_No = NVL (MOV.BATCH_NO, DB.Batch_No)))
               NOT_RTRN_QTY,
           DECODE (L.A_CY,
                    P.CUR_CODE, I.I_PRICE,
                   (  I.I_PRICE
                    * (SELECT CUR_RATE
                         FROM EX_RATE
                        WHERE CUR_CODE = L.A_CY)
                    / E.CUR_RATE))
               I_PRICE,
           NVL ((SELECT DECODE (VD.CUR_CODE,
                                P.CUR_CODE, VD.DIS_AMT,
                                (  VD.DIS_AMT
                                 * (SELECT CUR_RATE
                                      FROM EX_RATE
                                     WHERE CUR_CODE = VD.CUR_CODE)
                                 / E.CUR_RATE))
                            DIS_AMT
                   FROM IAS_V_ITM_DISC_ONLINE VD
                  WHERE O.I_CODE = I_CODE AND O.ITM_UNT = ITM_UNT
                  And Rownum<=1 ),
                0)
               DIS_AMT,
           NVL ((SELECT DIS_PER
                   FROM IAS_V_ITM_DISC_ONLINE
                  WHERE O.I_CODE = I_CODE AND O.ITM_UNT = ITM_UNT And Rownum<=1),
                0)
               DIS_PER,
           NVL ((SELECT DECODE (VQ.QUOT_CUR,
                                 P.CUR_CODE, VQ.QUT_AMT,
                                (  VQ.QUT_AMT
                                 * (SELECT CUR_RATE
                                      FROM EX_RATE
                                     WHERE CUR_CODE = VQ.QUOT_CUR)
                                 / E.CUR_RATE))
                            QUT_AMT
                   FROM IAS_V_ITM_DIS_QUT_ONLINE VQ
                  WHERE O.I_CODE = I_CODE AND O.ITM_UNT = ITM_UNT AND SHO.SHO_NO=SHO_NO
                  And Rownum<=1),
                0)
               QUT_AMT,
           NVL ((SELECT QUT_PER
                   FROM IAS_V_ITM_DIS_QUT_ONLINE
                  WHERE O.I_CODE = I_CODE AND O.ITM_UNT = ITM_UNT  AND SHO.SHO_NO=SHO_NO
                  And Rownum<=1),
                0)
               QUT_PER,
           P.CUR_CODE CUR_CODE,
           WH.CONN_BRN_NO,
           M.I_IMG,
           SHO.SHO_NO SHO_SYS_TYP,
           V.LAST_UPDATE,
           NVL(M.USE_GRANT,0),
           NVL(M.GRANT_PERIOD,0),
           O.SHO_I_CODE,
           SHO.SHO_W_CODE,
           O.PRDCT_ID,
           P.CLC_VAT_PRICE_TYP,
           P.CLC_TYP_NO_TAX,
           NVL((SELECT Ys_Tax_Pkg.Get_Itm_Tax_Prcnt (P_Clc_Typ_No => P.CLC_TYP_NO_TAX, P_I_Code => O.I_CODE, P_Clc_Usd_Itm => 1) FROM DUAL),0) VAT_PER ,
           M.Field1      ,
           M.Field2      ,
           M.Field3      ,
           M.Field4      ,
           M.Field5      ,
           M.Field6      ,
           M.Field7      ,
           M.Field8      ,
           M.Field9      ,
           M.Field10     ,
           M.Field11     ,
           M.Field12     ,
           M.Field13     ,
           M.Field14     ,
           M.Field15     ,
           M.Field16     ,
           M.Field17     ,
           M.Field18     ,
           M.Field19     ,
           M.Field20       
      FROM IAS_ITM_MST                    M,
           IAS_ITM_DTL                    D,
           IAS_V_ITM_MOV_EXP_BTCH_AVLQTY  MOV,
           IAS_ITEM_PRICE                 I,
           WAREHOUSE_DETAILS              WH,
           IAS_ITM_ONLINE                 O,
           IAS_V_LAST_UPD_ITM             V,
           EX_RATE                        E,
           IAS_PARA_ONLINE                P,
           IAS_PRICING_LEVELS             L,
           IAS_PARA_AR                    AR,
           IAS_PARA_INV                   INV,
           SHO_CONN_WC                    SHO
     WHERE     M.I_CODE = D.I_CODE
           AND M.I_CODE = MOV.I_CODE
           AND MOV.W_CODE = WH.W_CODE
           AND M.I_CODE = I.I_CODE
           AND M.I_CODE = V.I_CODE
           AND D.I_CODE = MOV.I_CODE
           AND D.I_CODE = I.I_CODE
           AND D.ITM_UNT = I.ITM_UNT
           AND MOV.I_CODE = I.I_CODE
           AND M.I_CODE = O.I_CODE
           AND D.I_CODE = O.I_CODE
           AND D.I_CODE = V.I_CODE
           AND MOV.I_CODE = O.I_CODE
           AND I.I_CODE = O.I_CODE
           AND D.ITM_UNT = O.ITM_UNT
           AND MOV.I_CODE = V.I_CODE
           AND I.I_CODE = V.I_CODE
           AND O.I_CODE = V.I_CODE
           AND SHO.W_CODE =WH.W_CODE
           AND SHO.W_CODE =MOV.W_CODE
           AND SHO.SHO_NO = O.SHO_SYS_TYP
           AND SHO.SHO_NO = P.SHO_SYS_TYP
           AND P.SHO_SYS_TYP = O.SHO_SYS_TYP
           AND O.SHO_SYS_TYP = P.SHO_SYS_TYP
           And P.Lev_No = L.Lev_No
           And P.Lev_No = I.Lev_No
           AND L.LEV_NO = I.LEV_NO
           AND E.CUR_CODE =  P.CUR_CODE
           AND DECODE (NVL (INV.PRICE_TYPE, 1),
                       2, Nvl(P.Brn_Wh_Con_Prc,Wh.W_Code),
                       5, Nvl(P.Brn_Wh_Con_Prc,Wh.Conn_Brn_No),
                       1) =
               DECODE (NVL (INV.PRICE_TYPE, 1),
                       2, I.W_CODE,
                       5, I.BRN_NO,
                       1)
           AND DECODE (NVL (O.BATCH_NO, '0'),
                       '0', '0',
                       NVL (MOV.BATCH_NO, '0')) =
               NVL (O.BATCH_NO, '0')
           AND DECODE (
                   NVL (O.EXPIRE_DATE, TO_DATE ('01/01/1900', 'DD/MM/YYYY')),
                   TO_DATE ('01/01/1900', 'DD/MM/YYYY'), TO_DATE (
                                                             '01/01/1900',
                                                             'DD/MM/YYYY'),
                   NVL (MOV.EXPIRE_DATE,
                        TO_DATE ('01/01/1900', 'DD/MM/YYYY'))) =
               NVL (O.EXPIRE_DATE, TO_DATE ('01/01/1900', 'DD/MM/YYYY'))
           AND NVL (WH.SHO_WC_TYP, 0) <> 0;


--
-- IAS_V_NY_ORDER_DETAIL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.IAS_V_NY_ORDER_DETAIL
(SO_TYPE, ORDER_NO, ORDER_SER, I_CODE, I_QTY, 
 FREE_QTY, P_SIZE, P_QTY, I_PRICE, RES_DATE, 
 RES_QTY, W_CODE, RESERVED, RCRD_NO, BARCODE, 
 USE_ATTCH, REC_ATTCH, ITEM_DESC, EXTERNAL_POST, CANCELED, 
 EXPIRE_DATE, BATCH_NO, VAT_PER, VAT_AMT, I_LENGTH, 
 I_WIDTH, I_HEIGHT, I_NUMBER, FIELD_DTL1, FIELD_DTL2, 
 FIELD_DTL3, CMP_NO, BRN_NO, BRN_YEAR, BRN_USR, 
 UP_CNT, ITM_UNT, WT_QTY, WT_UNT, DIS_PER, 
 DIS_AMT_DTL, DIS_PER2, DIS_AMT_DTL2, DIS_PER3, DIS_AMT_DTL3, 
 DIS_AMT, DIS_AMT_MST, EMP_NO, SUB_C_CODE, DIS_AMT_DTL_VAT, 
 DIS_AMT_MST_VAT, VAT_AMT_DIS_DTL_VAT, VAT_AMT_AFTR_DIS, VAT_AMT_BFR_DIS, VAT_AMT_DIS_MST_VAT, 
 DOC_SEQ, PKG_UNT, PKG_UNT_SIZE, PKG_QTY, PKG_LENGTH, 
 PKG_WIDTH, PKG_HEIGHT, PKG_SIZE, PKG_WEIGHT, SI_TYPE, 
 OTHR_AMT, INSRNCE_LOAD_PER, INSRNCE_LOAD_AMT, INSRNCE_ADD_LMT, INSRNCE_APPRVD_CODE, 
 I_PRICE_VAT, MEASUR_PRICE, DOC_TYPE_REF, DOC_NO_REF, DOC_SER_REF, 
 DOC_SEQUENCE_REF, CC_CODE, PJ_NO, ACTV_NO, STK_COST, 
 USED_ITM, ARGMNT_NO, OTHR_AMT_DISC, VAT_AMT_OTHR, F_TIME, 
 T_TIME, DIS_AMT_AFTR_VAT, DIS_AMT_DTL2_VAT, DIS_AMT_DTL3_VAT, VAT_AMT_DIS_DTL2_VAT, 
 VAT_AMT_DIS_DTL3_VAT, PO_NO, PO_SER, FIELD_DTL4, FIELD_DTL5, 
 FIELD_DTL6, FIELD_DTL7, FIELD_DTL8, FIELD_DTL9, FIELD_DTL10, 
 LEV_NO, I_PRICE_LEV_NO, BILL_DOC_TYPE)
BEQUEATH DEFINER
AS 
Select O.SO_TYPE, O.ORDER_NO, O.ORDER_SER, 
               O.I_CODE, Mov_Data.I_Qty, Mov_Data.Free_Qty,
               O.P_Size, (Mov_Data.I_Qty*O.P_Size) P_Qty, O.I_Price,
               O.RES_DATE, O.RES_QTY, O.W_CODE, 
               O.RESERVED, O.RCRD_NO, O.BARCODE, 
               O.USE_ATTCH, O.REC_ATTCH, O.ITEM_DESC, 
               O.EXTERNAL_POST, O.CANCELED, O.EXPIRE_DATE, 
               O.BATCH_NO, O.VAT_PER, O.VAT_AMT, 
               O.I_LENGTH, O.I_WIDTH, O.I_HEIGHT, 
               O.I_NUMBER, O.FIELD_DTL1, O.FIELD_DTL2, 
               O.FIELD_DTL3, O.CMP_NO, O.BRN_NO, 
               O.BRN_YEAR, O.BRN_USR, O.UP_CNT, 
               O.ITM_UNT, O.WT_QTY, O.WT_UNT, 
               O.DIS_PER, O.DIS_AMT_DTL, O.DIS_PER2, 
               O.DIS_AMT_DTL2, O.DIS_PER3, O.DIS_AMT_DTL3, 
               O.DIS_AMT, O.DIS_AMT_MST, O.EMP_NO, 
               O.SUB_C_CODE, 
               Dis_Amt_Dtl_Vat, Dis_Amt_Mst_Vat, Vat_Amt_Dis_Dtl_Vat, 
                Vat_Amt_Aftr_Dis, Vat_Amt_Bfr_Dis, Vat_Amt_Dis_Mst_Vat, 
                O.Doc_Seq,   
                Pkg_Unt, Pkg_Unt_Size, Pkg_Qty, 
                Pkg_Length, Pkg_Width, Pkg_Height, 
                Pkg_Size, Pkg_Weight,  
                  Si_Type, 
                Othr_Amt, Insrnce_Load_Per, Insrnce_Load_Amt, 
                Insrnce_Add_Lmt, Insrnce_Apprvd_Code, I_Price_Vat, 
                Measur_Price, Doc_Type_Ref, Doc_No_Ref, 
                Doc_Ser_Ref, Doc_Sequence_Ref, Cc_Code, 
                Pj_No, Actv_No, Stk_Cost, 
                Used_Itm,    Argmnt_No, 
                 Othr_Amt_Disc, Vat_Amt_Othr, 
                F_Time, T_Time, Dis_Amt_Aftr_Vat, 
                Dis_Amt_Dtl2_Vat, Dis_Amt_Dtl3_Vat, Vat_Amt_Dis_Dtl2_Vat, 
                Vat_Amt_Dis_Dtl3_Vat, Po_No, Po_Ser, 
                Field_Dtl4, Field_Dtl5, Field_Dtl6, 
                Field_Dtl7, Field_Dtl8, Field_Dtl9, 
                Field_Dtl10, Lev_no, I_price_lev_no, Bill_doc_type
            From Order_Detail O,(Select Doc_Ser,I_Code,Doc_Seq,Sum(Nvl(I_Qty,0)) I_Qty,Sum(Nvl(Free_Qty,0)) Free_Qty 
                                  From( Select Order_Ser Doc_Ser,I_Code,Doc_Seq Doc_Seq,Nvl(I_Qty,0) I_Qty,Nvl(Free_Qty,0) Free_Qty
                                          From Order_Detail 
                                        Union All
                                        Select Doc_Ser_Ref Doc_Ser,I_Code,DOC_SEQUENCE_REF Doc_Seq,Sum(Nvl(I_Qty,0))*-1 I_Qty,Sum(Nvl(Free_Qty,0))*-1 Free_Qty
                                          From Ias_Bill_Dtl
                                         Where Doc_Type_Ref=53
                                           And Doc_Ser_Ref Is Not Null
                                           And DOC_SEQUENCE_REF Is Not Null
                                         Group By Doc_Ser_Ref,I_Code,DOC_SEQUENCE_REF
                                         Union All
                                        Select Doc_Ser_Ref Doc_Ser,I_Code,DOC_SEQUENCE_REF Doc_Seq,Sum(Nvl(I_Qty,0))*-1 I_Qty,0 Free_Qty
                                          From IAS_OUTGOING_DTL
                                         Where Doc_Type_Ref=53
                                           And Doc_Ser_Ref Is Not Null
                                           And DOC_SEQUENCE_REF Is Not Null
                                         Group By Doc_Ser_Ref,I_Code,DOC_SEQUENCE_REF
                                           )
                                Group By Doc_Ser,I_Code,Doc_Seq
                                Having Sum(Nvl(I_Qty,0))+Sum(Nvl(Free_Qty,0))>0) Mov_Data
            Where O.Order_Ser=Mov_Data.Doc_Ser
            And O.I_Code=Mov_Data.I_Code
            And O.Doc_Seq=Mov_Data.Doc_Seq 
            And Nvl(Canceled,0)=0  
            And Nvl(Mov_Data.I_Qty,0)>=0
            And Nvl(Mov_Data.Free_Qty,0)>=0;

