LMT_AMT_LOC_DOC","POINT_CALC_TYP_NO","POINT_CNT","POINT_CNT_ALL","POINT_RPLC_AMT","POINT_RPLC_CNT","POINT_TYP_NO","MOBILE_NO","DIFF_ACUTL_WGHT_SO_QTY","TARE_WGHT","TARE_WGHT_DATE","TARE_WGHT_U_ID","GROSS_WGHT","GROSS_WGHT_DATE","GROSS_WGHT_U_ID","C_CODE_CSH","C_ADDRESS","C_MOBILE","C_TAX_CODE","NT_TRANSFR_PATH","LATITUDE","LONGITUDE","CR_CARD_AMT","CR_CARD_COMM_PER","CR_CARD_MAX_COMM_AMT","CREDIT_CARD","A_CODE","DELIVERY_TIME","CR_CARD_CST_NO","CR_CARD_NO_SCND","CR_CARD_NO_THRD","CR_CARD_AMT_SCND","CR_CARD_AMT_THRD","CR_VALUED","CR_VALUED_SCND","CR_VALUED_THRD","CR_DOC_NO_REF","CR_DOC_NO_REF_SCND","CR_DOC_NO_REF_THRD","CR_VALUE_DATE","CR_VALUE_DATE_SCND","CR_VALUE_DATE_THRD","CR_CARD_COMM_PER_SCND","CR_CARD_COMM_PER_THRD","CR_CARD_MAX_COMM_AMT_SCND","CR_CARD_MAX_COMM_AMT_THRD","CR_CARD_CST_NO_SCND","CR_CARD_CST_NO_THRD","CR_CARD_DOC_NO_REF","CR_CARD_DOC_NO_REF_SCND","CR_CARD_DOC_NO_REF_THRD","CR_CARD_DSC","CR_CARD_DSC_SCND","CR_CARD_DSC_THRD","AC_AMT","PYMNT_AC","MANUALLY_CLOSED","MTHD_DEDCT_ADVNC_PYMNT","SYS_DOC_ID","W_CODE_WHTRNS","RCPNT_CMPNY","RCPNT_NAME","RCPNT_EMAIL","RCPNT_ADDREES","RCPNT_CITY","RCPNT_POST_CODE","RCPNT_STATE","RCPNT_CNTRY","RCPNT_CNTRY_CODE","OTHR_AMT_AC","OTHR_AMT_DISC_AC","VAT_AMT_OTHR_AC","PYMNT_PER","PYMNT_TYP","TRL_PRCSSD_FLG","AD_U_ID","AD_DATE","AD_DATE_CLK","UP_U_ID","UP_DATE","UP_CNT","PR_REP","CMP_NO","BRN_NO","BRN_YEAR","BRN_USR","AD_TRMNL_NM","UP_TRMNL_NM" From Sales_Order Where Order_Ser In (Select Order_Ser From Ias_V_Ny_Order_Detail);

