--
-- INV_V_SRVC_ITM_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.INV_V_SRVC_ITM_MOVMNT
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, I_CODE, I_QTY, 
 FREE_QTY, ITM_UNT, P_SIZE, P_QTY, PF_QTY, 
 I_DATE, I_COST, W_CODE, WHG_CODE, STK_COST, 
 DIS_AMT, A_CY, AC_RATE, STOCK_RATE, CC_CODE, 
 PJ_NO, ACTV_NO, EXPIRE_DATE, BATCH_NO, RCRD_NO, 
 DOC_SER, DOC_SEQUENCE, IN_OUT, AUDIT_REF, CMP_NO, 
 BRN_NO, BRN_YEAR, BRN_USR)
BEQUEATH DEFINER
AS 
SELECT 0 doc_type,
          NULL bill_doc_type,
          0 doc_no,
          i_code,
          i_qty i_qty,
          0 free_qty,
          itm_unt,
          p_size,
          (i_qty * p_size) p_qty,
          0 pf_qty,
          ias_gen_pkg.get_frst_day doc_date,
          stk_cost i_cost,
          w_code w_code,
          TO_CHAR (whg_code) whg_code,
          stk_cost,
          NULL dis_amt,
          (SELECT cur_code
             FROM ex_rate
            WHERE stock_cur = 1)
             a_cy,
          0 ac_rate,
          1 stock_rate,
          NULL cc_code,
          NULL pj_no,
          NULL actv_no,
          expire_date,
          batch_no,
          rcrd_no,
          0 doc_ser,
          doc_sequence,
          1 in_out,
          NULL audit_ref,
          cmp_no,
          brn_no,
          brn_year,
          brn_usr
     FROM ias_open_stock Tbl
        Where Exists ( Select 1 From Ias_Itm_Mst Where Ias_Itm_Mst.I_Code = Tbl.I_Code And Nvl(Ias_Itm_Mst.Service_Itm,0) = 1 And Rownum <=1 )
   UNION ALL
   --SALES
   SELECT 1 doc_type,
          m.bill_doc_type,
          m.bill_no,
          d.i_code,
          d.i_qty i_qty,
          free_qty,
          d.itm_unt itm_unt,
          d.p_size,
          (d.i_qty * d.p_size) p_qty,
          (d.free_qty * d.p_size) pf_qty,
          m.bill_date doc_date,
          d.i_price i_cost,
          d.w_code w_code,
          post_code whg_code,
          d.stk_cost stk_cost,
          d.dis_amt dis_amt,
          m.bill_currency,
          m.bill_rate,
          m.stock_rate,
          d.cc_code cc_code,
          d.pj_no pj_no,
          d.actv_no actv_no,
          expire_date,
          batch_no,
          rcrd_no,
          m.bill_ser doc_ser,
          doc_sequence,
          -1 in_out,
          m.audit_ref,
          m.cmp_no cmp_no,
          m.brn_no brn_no,
          m.brn_year brn_year,
          m.brn_usr brn_usr
     FROM ias_bill_mst m, ias_bill_dtl d
    WHERE     m.bill_ser = d.bill_ser
          And Exists ( Select 1 From Ias_Itm_Mst Where Ias_Itm_Mst.I_Code = D.I_Code And Nvl(Ias_Itm_Mst.Service_Itm,0) = 1 And Rownum <=1 )
          AND (SELECT use_out_bills FROM ias_para_ar) = 0
   UNION ALL
   SELECT 1 doc_type,
          m.bill_doc_type,
          m.out_no,
          d.i_code,
          d.i_qty i_qty,
          free_qty,
          d.itm_unt itm_unt,
          d.p_size,
          (d.i_qty * d.p_size) p_qty,
          (d.free_qty * d.p_size) pf_qty,
          m.out_date doc_date,
          d.i_price i_cost,
          d.w_code w_code,
          post_code whg_code,
          d.stk_cost stk_cost,
          d.dis_amt dis_amt,
          m.bill_currency,
          m.bill_rate,
          m.stock_rate,
          d.cc_code cc_code,
          d.pj_no pj_no,
          d.actv_no actv_no,
          expire_date,
          batch_no,
          rcrd_no,
          m.out_ser doc_ser,
          doc_sequence,
          -1 in_out,
          m.audit_ref,
          m.cmp_no cmp_no,
          m.brn_no brn_no,
          m.brn_year brn_year,
          m.brn_usr brn_usr
     FROM master_out_bills m, detail_out_bills d
    WHERE     m.out_ser = d.out_ser
          And  Exists ( Select 1 From Ias_Itm_Mst Where Ias_Itm_Mst.I_Code = D.I_Code And Nvl(Ias_Itm_Mst.Service_Itm,0) = 1 And Rownum <=1 )
          AND (SELECT use_out_bills FROM ias_para_ar) = 1
   UNION ALL
   --PURCHES
   SELECT 2 doc_type,
          m.bill_doc_type,
          m.bill_no,
          d.i_code,
          d.i_qty i_qty,
          free_qty,
          d.itm_unt itm_unt,
          d.p_size,
          (d.i_qty * d.p_size) p_qty,
          (d.free_qty * d.p_size) pf_qty,
          m.bill_date doc_date,
          d.i_price i_cost,
          d.w_code w_code,
          post_code whg_code,
          d.stk_cost stk_cost,
          d.dis_amt dis_amt,
          m.bill_currency,
          m.bill_rate,
          m.stock_rate,
          d.cc_code cc_code,
          d.pj_no pj_no,
          d.actv_no actv_no,
          expire_date,
          batch_no,
          rcrd_no,
          m.bill_ser doc_ser,
          doc_sequence,
          1 in_out,
          m.audit_ref,
          m.cmp_no cmp_no,
          m.brn_no brn_no,
          m.brn_year brn_year,
          m.brn_usr brn_usr
     FROM ias_pi_bill_mst m, ias_pi_bill_dtl d
    WHERE     m.bill_ser = d.bill_ser
          And Exists ( Select 1 From Ias_Itm_Mst Where Ias_Itm_Mst.I_Code = D.I_Code And Nvl(Ias_Itm_Mst.Service_Itm,0) = 1 And Rownum <=1 )
          AND m.pur_type = 1
   UNION ALL
   SELECT 2 doc_type,
          m.pi_doc_type bill_doc_type,
          m.pi_no,
          d.i_code,
          d.i_qty i_qty,
          0 free_qty,
          d.itm_unt itm_unt,
          d.p_size,
          (d.i_qty * d.p_size) p_qty,
          (d.free_qty * d.p_size) pf_qty,
          m.gr_date doc_date,
          d.i_price i_cost,
          d.w_code w_code,
          post_code whg_code,
          d.stk_cost stk_cost,
          dis_amt,
          m.a_cy,
          m.ac_rate,
          m.stk_rate,
          d.cc_code cc_code,
          d.pj_no pj_no,
          d.actv_no actv_no,
          expire_date,
          batch_no,
          rcrd_no,
