--
-- SALES_BILL_DTL_AI_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SALES_BILL_DTL_AI_VW
(DOC_NO, DOC_SRL, ITM_CODE, ITM_UNT, ITM_SZ, 
 WRHS_CODE, EXP_DATE, ITM_SGMNT_CNTCT, ITM_QTY, ITM_FREE_QTY, 
 ITM_FREE_QTY_ADD, ITM_TOTL_QTY, ITM_TOTL_FREE_QTY, ITM_MN_QTY, ITM_MN_FREE_QTY, 
 ITM_MN_FREE_QTY_ADD, ITM_TOTL_MN_QTY, ITM_MN_TOTL_MN_FREE_QTY, ITM_PRICE, ITM_STK_CST, 
 ITM_TAX_PRCNT, ITM_TAX_AMT, ITM_OTHR_CHRG_AMT, ITM_DSCNT_AMT, ITM_DSCNT_AMT_ADD, 
 ITM_TOTL_PRICE, ITM_TOTL_DSCNT_AMT, ITM_TOTL_OTHR_CHRG_AMT, ITM_TOTL_TAX_AMT, ITM_TOTL_DSCNT_AMT_ADD, 
 ITM_TOTL_AMT, ITM_TOTL_STK_CST, ITM_TOTL_PRICE_LOCAL, ITM_TOTL_DSCNT_AMT_LOCAL, ITM_TOTL_OTHR_AMT_LOCAL, 
 ITM_TOTL_TAX_AMT_LOCAL, ITM_DSCNT_AMT_ADD_LOCAL, ITM_TOTL_AMT_LOCAL, SUB_LDGR1_CODE, SUB_LDGR2_CODE, 
 SUB_LDGR3_CODE, SUB_LDGR4_CODE, SUB_LDGR5_CODE, SUB_LDGR6_CODE, EMP_CODE, 
 SRVC_FLG, DOC_D_SQ, UNT_NO, YR_NO)
BEQUEATH DEFINER
AS 
SELECT D.BILL_NO
               DOC_NO,
           D.BILL_SER
               DOC_SRL,
           D.I_CODE
               ITM_CODE,
           D.ITM_UNT,
           D.P_SIZE
               ITM_SZ,
           D.W_CODE
               WRHS_CODE,
           D.EXPIRE_DATE
               EXP_DATE,
           D.BATCH_NO
               ITM_SGMNT_CNTCT,
           NVL (D.I_QTY, 0)
               ITM_QTY,
           NVL (D.FREE_QTY, 0)
               ITM_FREE_QTY,
           0
               ITM_FREE_QTY_ADD,
           (NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0))
               ITM_TOTL_QTY,
           NVL (D.FREE_QTY, 0)
               ITM_TOTL_FREE_QTY,
           NVL (D.P_QTY, 0)
               ITM_MN_QTY,
           (NVL (D.FREE_QTY, 0) * P_SIZE)
               ITM_MN_FREE_QTY,
           0
               ITM_MN_FREE_QTY_ADD,
           ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * P_SIZE)
               ITM_TOTL_MN_QTY,
           (NVL (D.FREE_QTY, 0) * P_SIZE)
               ITM_MN_TOTL_MN_FREE_QTY,
           NVL (D.I_PRICE, 0)
               ITM_PRICE,
           NVL (D.STK_COST, 0)
               ITM_STK_CST,
           NVL (D.VAT_PER, 0)
               ITM_TAX_PRCNT,
           NVL (D.VAT_AMT, 0)
               ITM_TAX_AMT,
           NVL (D.OTHR_AMT, 0)
               ITM_OTHR_CHRG_AMT,
           NVL (D.DIS_AMT, 0)
               ITM_DSCNT_AMT,
           (NVL (D.ADD_DIS_AMT_MST, 0) + NVL (D.ADD_DIS_AMT_DTL, 0))
               ITM_DSCNT_AMT_ADD,
           (NVL (D.I_QTY, 0) * NVL (D.I_PRICE, 0))
               ITM_TOTL_PRICE,
           (NVL (D.I_QTY, 0) * NVL (D.DIS_AMT, 0))
               ITM_TOTL_DSCNT_AMT,
           (NVL (D.I_QTY, 0) * NVL (D.OTHR_AMT, 0))
               ITM_TOTL_OTHR_CHRG_AMT,
           (NVL (D.I_QTY, 0) * NVL (D.VAT_AMT, 0))
               ITM_TOTL_TAX_AMT,
           (  NVL (D.I_QTY, 0)
            * (NVL (D.ADD_DIS_AMT_MST, 0) + NVL (D.ADD_DIS_AMT_DTL, 0)))
               ITM_TOTL_DSCNT_AMT_ADD,
           (  NVL (D.I_QTY, 0)
            * (  NVL (D.I_PRICE, 0)
               - NVL (D.DIS_AMT, 0)
               + NVL (D.OTHR_AMT, 0)
               + NVL (D.VAT_AMT, 0)
               - NVL (D.DIS_AFTR_VAT_MST, 0)))
               ITM_TOTL_AMT,
           ((NVL (D.I_QTY, 0) + NVL (D.FREE_QTY, 0)) * NVL (D.STK_COST, 0))
               ITM_TOTL_STK_CST,
           (NVL (D.I_QTY, 0) * NVL (D.I_PRICE, 0) * M.BILL_RATE)
               ITM_TOTL_PRICE_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.DIS_AMT, 0) * M.BILL_RATE)
               ITM_TOTL_DSCNT_AMT_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.OTHR_AMT, 0) * M.BILL_RATE)
               ITM_TOTL_OTHR_AMT_LOCAL,
           (NVL (D.I_QTY, 0) * NVL (D.VAT_AMT, 0) * M.BILL_RATE)
               ITM_TOTL_TAX_AMT_LOCAL,
           (  NVL (D.I_QTY, 0)
            * (NVL (D.ADD_DIS_AMT_MST, 0) + NVL (D.ADD_DIS_AMT_DTL, 0))
            * M.BILL_RATE)
               ITM_DSCNT_AMT_ADD_LOCAL,
           (  NVL (D.I_QTY, 0)
            * (  NVL (D.I_PRICE, 0)
               - NVL (D.DIS_AMT, 0)
               + NVL (D.OTHR_AMT, 0)
               + NVL (D.VAT_AMT, 0)
               - NVL (D.DIS_AFTR_VAT_MST, 0))
            * M.BILL_RATE)
               ITM_TOTL_AMT_LOCAL,
           D.CC_CODE
               SUB_LDGR1_CODE,
           D.PJ_NO
               SUB_LDGR2_CODE,
           D.ACTV_NO
               SUB_LDGR3_CODE,
           NULL
               SUB_LDGR4_CODE,
           NULL
               SUB_LDGR5_CODE,
           NULL
               SUB_LDGR6_CODE,
           D.EMP_NO
               EMP_CODE,
           D.SERVICE_ITEM
               SRVC_FLG,
           D.DOC_SEQUENCE
               DOC_D_SQ,
           D.BRN_NO
               UNT_NO,
           D.BRN_YEAR
               YR_NO
      FROM IAS_BILL_MST M, IAS_BILL_DTL D
     WHERE M.BILL_SER = D.BILL_SER;


--
-- SHO_V_IAS_QUT_PRM_DTL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.SHO_V_IAS_QUT_PRM_DTL
(QUOT_NO, QUOT_SER, F_DATE, T_DATE, I_CODE, 
 ITM_UNT, P_SIZE, I_PRICE, RCRD_NO, BARCODE, 
 F_QTY, T_QTY, F_AMT, T_AMT, DISC_TYPE, 
 DISC_AMT_PER, QT_I_CODE, FREE_QTY, QT_ITM_UNT, QT_QTY, 
 W_CODE, WHG_CODE, CNTRY_NO, PROV_NO, CITY_NO, 
 R_CODE, CARD_AMT, COMP_QTY, CMP_NO, BRN_NO, 
 BRN_YEAR, BRN_USR, UP_CNT, EXPIRE_DATE, BATCH_NO, 
 C_CODE, C_GROUP_CODE, C_CLASS, C_DEGREE, G_CODE, 
 MNG_CODE, SUBG_CODE, ASSISTANT_NO, DETAIL_NO, GROUP_NO, 
 ITEM_TYPE, GRP_CLASS_CODE, PRM_GRP_NO, BANK_NO, MAX_QT_QTY_DOC, 
 BILL_QTY, SHO_NO, QT_PRM_TYPE, QT_PRM_METHOD)
BEQUEATH DEFINER
AS 
SELECT D.Quot_No,
          D.Quot_Ser,
          M.F_DATE,
          M.T_DATE,
          D.I_Code,
          D.Itm_Unt,
          D.P_Size,
          D.I_Price,
          D.Rcrd_No,
          D.Barcode,
          D.F_Qty,
          D.T_Qty,
          D.F_Amt,
          D.T_Amt,
          D.Disc_Type,
          D.Disc_Amt_Per,
          D.Qt_I_Code,
          D.Free_Qty,
          D.Qt_Itm_Unt,
          D.Qt_Qty,
          D.W_Code,
          D.Whg_Code,
          D.Cntry_No,
          D.Prov_No,
          D.City_No,
          D.R_Code,
          D.Card_Amt,
          D.Comp_Qty,
          D.Cmp_No,
          D.Brn_No,
          D.Brn_Year,
          D.Brn_Usr,
          D.Up_Cnt,
          D.Expire_Date,
          D.Batch_No,
          D.C_Code,
          D.C_Group_Code,
          D.C_Class,
          D.C_Degree,
          D.G_Code,
          D.Mng_Code,
          D.Subg_Code,
          D.Assistant_No,
          D.Detail_No,
          D.Group_No,
          D.Item_Type,
          D.Grp_Class_Code,
          D.Prm_Grp_No,
          D.Bank_No,
          D.Max_Qt_Qty_Doc,
          NVL (
             (SELECT SUM (NVL (b.i_qty, 0) + NVL (FREE_QTY, 0))
                FROM ias_bill_dtl b
               WHERE     D.quot_ser = b.qt_prm_ser
                     AND D.rcrd_no = b.qt_prm_rcrd_no),
             0)
             bill_qty,
             Sho_No,
             M.Qt_Prm_Type,
             M.Qt_Prm_Method
     FROM Ias_Qut_Prm_Mst M, Ias_Qut_Prm_Dtl D ,Sho_Quot_Prm s
    WHERE     S.Quot_Ser = D.Quot_Ser
          And S.Quot_Ser = M.Quot_Ser  
          And M.Quot_Ser = D.Quot_Ser
          AND D.Prm_grp_no IS NULL
          AND TO_DATE(YS_GEN_PKG.GET_CURDATE,'DD/MM/RRRR')<=TO_DATE(M.T_DATE,'DD/MM/RRRR')
          AND NVL(M.INACTIVE,0)=0
           And Nvl(M.APPROVED,0)=1
          AND NVL( M.USE_QTN_PRM_IN_SHO_SYS_FLG,0) = 1
          AND 1 =
                 (CASE
                     WHEN D.I_Code IS NOT NULL
                     THEN
                        (SELECT 1
                           FROM IAS_ITM_ONLINE
                          WHERE     I_Code = D.I_Code
                                AND ITM_UNT = D.ITM_UNT
                                AND ROWNUM <= 1)
                     ELSE
                        1
                  END)
   UNION ALL
   SELECT D.Quot_No,
          D.Quot_Ser,
          M.F_DATE,
          M.T_DATE,
          G.I_Code,
          G.Itm_Unt,
          G.P_Size,
          D.I_Price,
          D.Rcrd_No,
          D.Barcode,
          D.F_Qty,
          D.T_Qty,
          D.F_Amt,
          D.T_Amt,
          D.Disc_Type,
          D.Disc_Amt_Per,
          D.Qt_I_Code,
          D.Free_Qty,
          D.Qt_Itm_Unt,
          D.Qt_Qty,
          D.W_Code,
          D.Whg_Code,
          D.Cntry_No,
          D.Prov_No,
          D.City_No,
          D.R_Code,
          D.Card_Amt,
          D.Comp_Qty,
          D.Cmp_No,
          D.Brn_No,
          D.Brn_Year,
          D.Brn_Usr,
          D.Up_Cnt,
          D.Expire_Date,
          D.Batch_No,
          D.C_Code,
          D.C_Group_Code,
          D.C_Class,
          D.C_Degree,
          D.G_Code,
          D.Mng_Code,
          D.Subg_Code,
          D.Assistant_No,
          D.Detail_No,
          D.Group_No,
          D.Item_Type,
          D.Grp_Class_Code,
          D.Prm_Grp_No,
          D.Bank_No,
          D.Max_Qt_Qty_Doc,
          NVL (
             (SELECT SUM (NVL (b.i_qty, 0) + NVL (FREE_QTY, 0))
                FROM ias_bill_dtl b
               WHERE     D.quot_ser = b.qt_prm_ser
                     AND D.rcrd_no = b.qt_prm_rcrd_no),
             0)
             bill_qty,
             Sho_No ,
             M.Qt_Prm_Type,
             M.Qt_Prm_Method
     FROM Ias_Qut_Prm_Mst M,
          Ias_Qut_Prm_Dtl D,
          Ias_Qut_Prm_Grp_Dtl G,
          IAS_ITM_ONLINE O,
          Sho_Quot_Prm  S
    WHERE  
              S.Quot_Ser = D.Quot_Ser
          And S.Quot_Ser = M.Quot_Ser
          AND M.Quot_Ser = D.Quot_Ser
          AND D.Prm_grp_no = G.Prm_grp_no
          AND TO_DATE(YS_GEN_PKG.GET_CURDATE,'DD/MM/RRRR')<=TO_DATE(M.T_DATE,'DD/MM/RRRR')
          AND NVL(M.INACTIVE,0)=0
          And Nvl(M.APPROVED,0)=1
          AND NVL( M.USE_QTN_PRM_IN_SHO_SYS_FLG,0) = 1
          AND NVL (Comp_qty, 0) = 1
          AND G.I_Code  = O.I_Code
          AND G.itm_unt = O.itm_unt;

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.I_CODE IS '176 - —ﬁ„ «·’‰›';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.I_PRICE IS '230 - «·”⁄—';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.RCRD_NO IS '1971 - —ﬁ„ «·”Ã·';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.W_CODE IS '193 - —ﬁ„ «·„Œ“‰';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.CNTRY_NO IS '1389 - —ﬁ„ «·œÊ·…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.PROV_NO IS '1959 - —ﬁ„ «·Ê·«Ì…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.CITY_NO IS '1386 - —ﬁ„ «·„œÌ‰…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.R_CODE IS '393 - —ﬁ„ «·„‰ÿﬁÂ';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.CMP_NO IS '1583 - —ﬁ„ «·‘—ﬂ…';

COMMENT ON COLUMN IAS20261.SHO_V_IAS_QUT_PRM_DTL.BRN_NO IS '50 - —ﬁ„ «·›—⁄';

