        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'IAS_BILL_DTL','WT_QTY',:NEW.WT_QTY,:OLD.WT_QTY,Nvl(:NEW.I_CODE,:OLD.I_CODE),Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BILL_SER,:OLD.BILL_SER),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.BILL_NO,:OLD.BILL_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'IAS_BILL_DTL','WT_UNT',:NEW.WT_UNT,:OLD.WT_UNT,Nvl(:NEW.I_CODE,:OLD.I_CODE),Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BILL_SER,:OLD.BILL_SER),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.BILL_NO,:OLD.BILL_NO)); 
        IAS_AUD_SYS_PKG.ADD_HIST( V_OP_TYPE,'IAS_BILL_DTL','W_CODE',:NEW.W_CODE,:OLD.W_CODE,Nvl(:NEW.I_CODE,:OLD.I_CODE),Nvl(:NEW.W_CODE,:OLD.W_CODE),Nvl(:NEW.BILL_SER,:OLD.BILL_SER),NVL(:NEW.CMP_NO,:OLD.CMP_NO),NVL(:NEW.BRN_NO,:OLD.BRN_NO),NVL(:NEW.BRN_USR,:OLD.BRN_USR),NVL(:NEW.BRN_YEAR,:OLD.BRN_YEAR),NVL(:NEW.BILL_NO,:OLD.BILL_NO)); 

                                        END;
/


--
-- CHK_DEL_BILL_DTL  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.chk_del_bill_dtl
BEFORE DELETE
ON IAS20261.IAS_BILL_DTL 
REFERENCING NEW AS New OLD AS Old
FOR EACH ROW
DECLARE
   V_Cnt NUMBER;
  BEGIN                                                                                     
     Begin
       Select 1 InTo V_Cnt From Item_Movement Where Doc_Ser=:Old.Bill_Ser And i_Code=:Old.I_Code And Doc_Sequence=:old.Doc_Sequence And RowNum<=1;
     Exception When Others Then
       V_Cnt:=0;
       End;
       
     If Nvl(V_Cnt,0)>0 Then
        Raise_application_error(-20804,'Error When Delete Item From Ias_Bill_Dtl Table '||SqlErrm) ;
     End If;
   
  END chk_del_bill_dtl;
/


--
-- IAS_SET_MAIN_PRICE_TGR  (Trigger) 
--
CREATE OR REPLACE TRIGGER IAS20261.IAS_SET_MAIN_PRICE_TGR
        before INSERT ON  IAS20261.IAS_BILL_DTL REFERENCING NEW AS NEW OLD AS OLD
        FOR EACH ROW
DECLARE
  Begin
     :new.I_PRICE_LEV_NO:= get_main_price(:new.i_code,:NEW.ITM_UNT);                                                 
  End;
/


--
-- DTS_CST_ITM_LMT_SAL  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_CST_ITM_LMT_SAL
(REP_CODE, C_CODE, I_CODE, ITM_UNT, LMT_ITM_QTY_TYP, 
 PRD_DAY, LMT_QTY)
BEQUEATH DEFINER
AS 
Select c.rep_code
      ,C.C_Code
      ,I.I_Code
      ,I.ITM_UNT
      ,C.Lmt_Itm_Qty_Typ
      ,Nvl (C.Prd_Day, 0) Prd_Day
      ,(Nvl (I.Lmt_Qty_Sal_Cst,0) *Nvl(C.Rpt_Qty_Lmt_Cnt,1)) Lmt_Qty
  From Dts_V_Get_Customer c, dts_v_get_itm_dtl I
 Where Nvl (C.Lmt_Itm_Qty_Typ, 0) = 1
 and I.Rep_Code=C.Rep_Code 
 and CST_TYP=1
 and I.ITM_TYP=1
 And nvl(I.Lmt_Qty_Sal_Cst,0)>0   
 UNION ALL  
     Select c.rep_code
          ,C.C_Code
          ,I.I_Code
          ,I.ITM_UNT
          ,C.Lmt_Itm_Qty_Typ
          ,Nvl (L.Prd_Day, 0) Prd_Day
          ,(Nvl (L.I_Qty, Nvl (I.Lmt_Qty_Sal_Cst, 0)) * Nvl (L.Rpt_Qty_Cnt, 1)) Lmt_Qty
      From Dts_V_Get_Customer c, dts_v_get_itm_dtl I,Ias_Cst_Itm_Lmt_Sal L
     Where i.i_code=L.i_code
     And I.ITM_UNT=L.ITM_UNT
     and c.c_code=l.c_code
     and I.Rep_Code=C.Rep_Code 
     and Nvl (C.Lmt_Itm_Qty_Typ, 0) = 2 
     and CST_TYP=1
     and I.ITM_TYP=1
     And nvl(Nvl(L.I_Qty, I.Lmt_Qty_Sal_Cst),0)>0
 UNION ALL 
 Select c.rep_code
      ,C.C_Code
      ,I.I_Code
      ,I.ITM_UNT
      ,C.Lmt_Itm_Qty_Typ
      ,Nvl (I.ITM_SAL_LMT_PRD_DAY, 0) Prd_Day
      ,Nvl (I.Lmt_Qty_Sal_Cst,0) Lmt_Qty
  From Dts_V_Get_Customer c, dts_v_get_itm_dtl I
 Where Nvl (C.Lmt_Itm_Qty_Typ, 0) = 2
 and I.Rep_Code=C.Rep_Code  
 and CST_TYP=1
 and I.ITM_TYP=1
 And nvl(I.Lmt_Qty_Sal_Cst,0)>0
 And Not Exists
          (Select 1
             From Ias_Cst_Itm_Lmt_Sal
            Where C_Code = c.C_Code 
              And I_Code = i.I_Code 
              And Rownum <= 1);


--
-- DTS_V_GET_ALL_STK_AVLQTY  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_GET_ALL_STK_AVLQTY
(W_CODE, I_CODE, ITM_UNT, AVL_QTY, EXPIRE_DATE, 
 BATCH_NO)
BEQUEATH DEFINER
AS 
(SELECT   W_CODE, I_CODE, IAS_ITM_PKG.GET_ICODE_MIN_UNIT (I_CODE) ITM_UNT,
				             NVL (SUM (NVL (AVL_QTY, 0)), 0) AVL_QTY, EXPIRE_DATE, BATCH_NO
				        FROM (SELECT   M.W_CODE, M.I_CODE,
				                       NVL ((SUM (  (  (NVL (M.P_QTY, 0) + NVL (M.PF_QTY, 0))
				                                     * M.IN_OUT
				                                    )
				                                  / G.P_SIZE
				                                 )
				                            ),
				                            0
				                           ) AVL_QTY,
				                       M.EXPIRE_DATE, M.BATCH_NO
				                  FROM ITEM_MOVEMENT M,
				                       DTS_V_GET_ITM_DTL G,
				                       DTS_V_SMAN_INFO S,
				                       DTS_V_REP_INPT_PRIV W,
				                       DTS_PARA P
				                 WHERE DECODE (NVL (SHW_QTY_IN_ALL_WRHS, 0),
				                               1, 1,
				                               DECODE (S.W_CODE, M.W_CODE, 1, 0)
				                              ) = 1
				                   AND W.INPT_TYP = 'WCODE'
				                   AND NVL (W.VIEW_FLAG, 0) = 1
				                   AND W.U_ID = S.U_ID
				                   AND M.I_CODE = G.I_CODE
				                   AND G.GRP_CODE = S.GRP_CODE
				                   AND S.REP_CODE = G.REP_CODE
				                   AND NVL (G.MAIN_UNIT, 0) = 1
				              GROUP BY M.I_CODE, M.W_CODE, M.EXPIRE_DATE, M.BATCH_NO
				              UNION ALL
				              SELECT   D.W_CODE, D.I_CODE,
				                       (-1* NVL((SUM(((NVL (D.P_QTY,0) + (NVL(D.FREE_QTY,0)*D.P_SIZE))/ G.P_SIZE))),0)) AVL_QTY,
												       D.EXPIRE_DATE, D.BATCH_NO
				                  FROM IAS_BILL_DTL_BR D,
				                       IAS_BILL_MST_BR M,
				                       DTS_V_GET_ITM_DTL G,
				                       DTS_V_SMAN_INFO S,
				                       DTS_V_REP_INPT_PRIV W,
				                       DTS_PARA P
				                 WHERE M.BILL_SER = D.BILL_SER
				                   AND DECODE (NVL (SHW_QTY_IN_ALL_WRHS, 0),
				                               1, 1,
				                               DECODE (S.W_CODE, D.W_CODE, 1, 0)
				                              ) = 1
				                   AND W.INPT_TYP = 'WCODE'
				                   AND NVL (W.VIEW_FLAG, 0) = 1
				                   AND W.U_ID = S.U_ID
				                   AND NVL (M.BILL_POST, 0) = 0
				                   AND NVL (m.CNCL_FLG, 0) = 0
				                   AND D.I_CODE = G.I_CODE
				                   AND G.GRP_CODE = S.GRP_CODE
				                   AND G.REP_CODE = S.REP_CODE
				                   AND NVL (G.MAIN_UNIT, 0) = 1
				              GROUP BY D.I_CODE, D.W_CODE, D.EXPIRE_DATE, D.BATCH_NO
				              UNION ALL
				              SELECT   D.W_CODE, D.I_CODE,
				                       (1* NVL((SUM(((NVL (D.P_QTY,0) + (NVL(D.FREE_QTY,0)*D.P_SIZE))/ G.P_SIZE))),0)) AVL_QTY,
												       D.EXPIRE_DATE, D.BATCH_NO
				                  FROM IAS_RT_BILL_MST_BR M,
				                       IAS_RT_BILL_DTL_BR D,
				                       DTS_V_GET_ITM_DTL G,
				                       DTS_V_REP_INPT_PRIV W,
				                       DTS_V_SMAN_INFO S,
				                       DTS_PARA P
				                 WHERE M.RT_BILL_SER = D.RT_BILL_SER
				                   AND DECODE (NVL (SHW_QTY_IN_ALL_WRHS, 0),
				                               1, 1,
				                               DECODE (S.W_CODE, D.W_CODE, 1, 0)
				                              ) = 1
				                   AND W.INPT_TYP = 'WCODE'
				                   AND NVL (W.VIEW_FLAG, 0) = 1
				                   AND W.U_ID = S.U_ID
				                   AND NVL (M.RT_BILL_POST, 0) = 0
				                   AND NVL (m.CNCL_FLG, 0) = 0
				                   AND D.I_CODE = G.I_CODE
				                   AND G.GRP_CODE = S.GRP_CODE
				                   AND G.REP_CODE = S.REP_CODE
				                   AND NVL (G.MAIN_UNIT, 0) = 1
				              GROUP BY D.I_CODE, D.W_CODE, D.EXPIRE_DATE, D.BATCH_NO)
				    GROUP BY I_CODE, W_CODE, EXPIRE_DATE, BATCH_NO);


--
-- DTS_V_SMAN_DOC_MOVMNT  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.DTS_V_SMAN_DOC_MOVMNT
(DOC_TYPE, BILL_DOC_TYPE, DOC_NO, DOC_SER, DOC_DATE, 
 CUR_CODE, CUR_RATE, INV_FLG, REP_CODE, C_CODE, 
 A_CODE, C_NAME, DOC_SER_EXTRNL, EXTERNAL_POST, TYP_NO, 
 AD_U_ID, CASH_NO, CMP_NO, BRN_NO, BRN_YEAR, 
 AMT, AMT_LOC, DOC_POST, ADDRESS, MOBILE_NO, 
 TEL, DOC_DESC, R_CODE, REP_CODE_PARENT, HALF_NO, 
 QRTR_NO, PRD_NO, WEEK_NO, DAY_NO)
BEQUEATH DEFINER
AS 
SELECT DOC_TYPE        
         ,BILL_DOC_TYPE
         ,DOC_NO
         ,DOC_SER                                  
         ,DOC_DATE              
         ,CUR_CODE
         ,CUR_RATE                                            
         ,INV_FLG
         ,REP_CODE         
         ,C_CODE
         ,A_CODE
         ,C_NAME
         ,DOC_SER_EXTRNL
         ,EXTERNAL_POST
         ,TYP_NO
         ,AD_U_ID
         ,CASH_NO         
         ,Cmp_No
         ,Brn_No
         ,Brn_Year 
         ,SUM(NVL(AMT,0))  AMT
         ,SUM(NVL(AMT_LOC,0))  AMT_LOC
         ,DOC_POST
         ,ADDRESS
         ,MOBILE_NO
         ,TEL
         ,DOC_DESC 
         ,R_code
         ,REP_CODE_PARENT  
        ,Half_No
        ,Qrtr_No
        ,Prd_No
        ,Week_No
        ,Day_No           
         FROM DTS_V_SMAN_ITM_MOVMNT
         WHERE REP_CODE IS NOT NULL
         GROUP BY 
         DOC_TYPE        
         ,BILL_DOC_TYPE
         ,DOC_NO 
         ,DOC_SER                                   
         ,DOC_DATE              
         ,CUR_CODE
         ,CUR_RATE                                            
         ,INV_FLG
         ,REP_CODE         
         ,C_CODE
         ,A_CODE
         ,C_NAME
         ,DOC_SER_EXTRNL
         ,EXTERNAL_POST
         ,TYP_NO
         ,AD_U_ID
         ,CASH_NO        
         ,Cmp_No
         ,Brn_No
         ,Brn_Year 
         ,DOC_POST
         ,ADDRESS
         ,MOBILE_NO
         ,TEL
         ,DOC_DESC
         , R_code 
         ,REP_CODE_PARENT
         ,Half_No
        ,Qrtr_No
        ,Prd_No
        ,Week_No
        ,Day_No          
         UNION ALL         
  SELECT 2 DOC_TYPE        
         ,D.VOUCHER_PAY_TYPE BILL_DOC_TYPE
         ,D.VOUCHER_NO DOC_NO
         ,M.V_SER DOC_SER                                  
         ,M.VOUCHER_DATE DOC_DATE              
         ,D.A_CY CUR_CODE
         ,D.EX_RATE CUR_RATE                                            
         ,1 INV_FLG
         ,D.REP_CODE         
         ,D.AC_CODE_DTL C_CODE
         ,D.A_CODE 
         ,NULL C_NAME
         ,M.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,D.VOUCHER_PAY_TYPE TYP_NO
         ,M.AD_U_ID  
         ,M.CASH_NO       
         ,M.Cmp_No
         ,M.Brn_No
         ,M.Brn_Year 
         ,ROUND(SUM(DECODE(Ias_Gen_Pkg.Get_Local_CUR,D.A_CY,NVL(AC_AMT,0),NVL(AC_AMTF,0))),4) AMT        
         ,SUM(NVL(AC_AMT,0))  AMT_LOC 
         ,1 DOC_POST
         ,Null ADDRESS
         ,Null MOBILE_NO
         ,Null TEL
         ,Null DOC_DESC
         ,Null R_code 
         ,S.REP_CODE_PARENT 
         ,Round (To_Char (M.VOUCHER_DATE, 'Q') / 2) Half_No
        ,Round (To_Char (M.VOUCHER_DATE, 'Q')) Qrtr_No
        ,To_Char (M.VOUCHER_DATE, 'MM') Prd_No
        ,To_Char (M.VOUCHER_DATE, 'WW') Week_No
        ,To_Char (M.VOUCHER_DATE, 'DD') Day_No           
         FROM VOUCHER_DETAIL D,VOUCHERS M,sales_man s        
         WHERE M.V_SER=D.V_SER
         AND D.VOUCHER_TYPE=1
         AND NVL(D.AC_DTL_TYP,0)=3
         AND D.rep_code=s.REPRS_CODE
         AND D.REP_CODE IS NOT NULL
         GROUP BY 
         D.VOUCHER_PAY_TYPE 
         ,D.VOUCHER_NO 
         ,M.V_SER                                   
         ,M.VOUCHER_DATE               
         ,D.A_CY 
         ,D.EX_RATE                                                     
         ,D.REP_CODE         
         ,D.AC_CODE_DTL
         ,D.A_CODE          
         ,M.DOC_SER_EXTRNL
         ,M.EXTERNAL_POST
         ,D.VOUCHER_PAY_TYPE 
         ,S.REP_CODE_PARENT
         ,M.AD_U_ID  
         ,M.CASH_NO       
         ,M.Cmp_No
         ,M.Brn_No
         ,M.Brn_Year;

COMMENT ON COLUMN IAS20261.DTS_V_SMAN_DOC_MOVMNT.MOBILE_NO IS '770 - —ﬁ„ «·ÃÊ«·';



--
-- GNR_TAX_ALL_MOVMNT_VW  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.GNR_TAX_ALL_MOVMNT_VW
(BRN_NO, CMP_NO, DOC_SER, DOC_NO, DOC_DATE, 
 PRD_NO, PRD_NM, F_DATE, T_DATE, DOC_TYPE, 
 DOC_JV_TYPE, BILL_DOC_TYPE, CLC_TYP_NO, TAX_NO, A_CY, 
 DOC_DSC, VAT_AMT, DOC_AMT)
BEQUEATH DEFINER
AS 
SELECT BRN_NO,
           CMP_NO,
           Doc_Ser,
           Doc_No,
           Doc_Date,
           Prd_No,
           Prd_Nm,
           F_Date,
           T_Date,
           Doc_Type,
           Doc_Jv_Type,
           Bill_Doc_Type,
           Clc_Typ_no,
           Tax_No,
           A_Cy,
           Doc_Dsc,
           Vat_Amt,
           DOC_Amt
      FROM (SELECT BRN_NO,
                   CMP_NO,
                   Doc_No,
                   Doc_Ser,
                   Doc_Type,
                   Bill_Doc_Type,
                   Clc_Typ_NO,
                   Tax_No,
                   Doc_Date,
                   A_Cy,
                   Doc_Dsc,
                   Doc_Jv_Type,
                   DOC_AMT,
                   Vat_Amt,
                   Net_Amt,
                   Prd_No,
                   Prd_Nm,
                   F_Date,
                   T_Date
              FROM (  SELECT BRN_NO,
                             CMP_NO,
                             Doc_No
                                 Doc_No,
                             Gnr_Tax_Movmnt_Vw.Doc_Ser
                                 Doc_Ser,
                             NVL (Gnr_Tax_Movmnt_Vw.Doc_Jv_Type, 1)
                                 Doc_Jv_Type,
                             Gnr_Tax_Movmnt_Vw.Doc_Type
                                 Doc_Type,
                             YS_GEN_PKG.GET_DOCTYP_NM (
                                 P_DOC_TYP   => Gnr_Tax_Movmnt_Vw.Doc_Type,
                                 P_LNG_NO    =>
                                     NVL (
                                         IAS_PRMTR_PKG.GETPVAL (
                                             P_PRMTR   => 'LANG_DFLT'),
                                         1))
                                 Bill_Doc_Type,
                             Clc_Typ_no,
                             Tax_No,
                             Doc_Date
                                 Doc_Date,
                             A_Cy,
                             NULL
                                 Doc_Dsc,
                             ROUND (
                                 Sum(DOC_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 DOC_AMT,
                             ROUND (
                                 SUM (NVL (Tax_Amt_L, 0)),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 Vat_Amt,
                             0
                                 Net_Amt,
                             NULL
                                 Prd_No,
                             NULL
                                 Prd_Nm,
                             NULL
                                 F_Date,
                             NULL
                                 T_Date
                        FROM Gnr_Tax_Movmnt_Vw
                    GROUP BY Doc_No,
                             Gnr_Tax_Movmnt_Vw.Doc_Ser,
                             Gnr_Tax_Movmnt_Vw.Doc_Type,
                             Clc_Typ_no,
                             Tax_No,
                             NVL (Gnr_Tax_Movmnt_Vw.Doc_Jv_Type, 1),
                             Doc_Date,
                             A_Cy,
                             BRN_NO,
                             CMP_NO
                    UNION
                      SELECT BRN_NO,
                             CMP_NO,
                             Doc_No,
                             Doc_Ser,
                             1
                                 Doc_Jv_Type,
                             4
                                 Doc_Type,
                             YS_GEN_PKG.GET_DOCTYP_NM (
                                 P_DOC_TYP   => 4,
                                 P_LNG_NO    =>
                                     NVL (
                                         IAS_PRMTR_PKG.GETPVAL (
                                             P_PRMTR   => 'LANG_DFLT'),
                                         1))
                                 Bill_Doc_Type,
                             Clc_Typ_No_Tax,
                             Null Tax_No,
                             Doc_Date,
                             A_Cy,
                             NULL
                                 Doc_Dsc,
                             ROUND (
                                 SUM (DOC_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 DOC_Amt,
                             ROUND (
                                 SUM (Vat_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 VAt_Amt,
                             NULL
                                 Net_Amt,
                             NULL
                                 Prd_No,
                             NULL
                                 Prd_Nm,
                             NULL
                                 F_Date,
                             NULL
                                 T_Date
                        FROM GNR_TAX_SALES_NO_VAT_VW
                    GROUP BY Doc_Ser,
                             Doc_No,
                             Clc_Typ_No_Tax,
                             Doc_Date,
                             A_cy,
                             BRN_NO,
                             CMP_NO
                    UNION
                      SELECT BRN_NO,
                             CMP_NO,
                             Doc_No,
                             Doc_Ser,
                             1
                                 Doc_Jv_Type,
                             5
                                 Doc_Type,
                             YS_GEN_PKG.GET_DOCTYP_NM (
                                 P_DOC_TYP   => 5,
                                 P_LNG_NO    =>
                                     NVL (
                                         IAS_PRMTR_PKG.GETPVAL (
                                             P_PRMTR   => 'LANG_DFLT'),
                                         1))
                                 Bill_Doc_Type,
                             Clc_Typ_No_Tax,
                             Null Tax_No,
                             Doc_Date,
                             A_Cy,
                             NULL
                                 Doc_Dsc,
                             ROUND (
                                 SUM (DOC_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 DOC_Amt,
                             ROUND (
                                 SUM (Vat_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 VAt_Amt,
                             NULL
                                 Net_Amt,
                             NULL
                                 Prd_No,
                             NULL
                                 Prd_Nm,
                             NULL
                                 F_Date,
                             NULL
                                 T_Date
                        FROM GNR_TAX_RT_SALES_NO_VAT_VW
                    GROUP BY Doc_Ser,
                             Doc_No,
                             Clc_Typ_No_Tax,
                             Doc_Date,
                             A_cy,
                             BRN_NO,
                             CMP_NO
                    UNION
                      SELECT BRN_NO,
                             CMP_NO,
                             Doc_No,
                             Doc_Ser,
                             1
                                 Doc_Jv_Type,
                             6
                                 Doc_Type,
                             YS_GEN_PKG.GET_DOCTYP_NM (
                                 P_DOC_TYP   => 6,
                                 P_LNG_NO    =>
                                     NVL (
                                         IAS_PRMTR_PKG.GETPVAL (
                                             P_PRMTR   => 'LANG_DFLT'),
                                         1))
                                 Bill_Doc_Type,
                             Clc_Typ_No_Tax,
                             Null Tax_No,
                             Doc_Date,
                             A_Cy,
                             NULL
                                 Doc_Dsc,
                             ROUND (
                                 SUM (DOC_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 DOC_Amt,
                             ROUND (
                                 SUM (Vat_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 VAt_Amt,
                             NULL
                                 Net_Amt,
                             NULL
                                 Prd_No,
                             NULL
                                 Prd_Nm,
                             NULL
                                 F_Date,
                             NULL
                                 T_Date
                        FROM GNR_TAX_Purch_NO_VAT_VW
                    GROUP BY Doc_Ser,
                             Doc_No,
                             Clc_Typ_No_Tax,
                             Doc_Date,
                             A_cy,
                             BRN_NO,
                             CMP_NO
                    UNION
                      SELECT BRN_NO,
                             CMP_NO,
                             Doc_No,
                             Doc_Ser,
                             1
                                 Doc_Jv_Type,
                             7
                                 Doc_Type,
                             YS_GEN_PKG.GET_DOCTYP_NM (
                                 P_DOC_TYP   => 7,
                                 P_LNG_NO    =>
                                     NVL (
                                         IAS_PRMTR_PKG.GETPVAL (
                                             P_PRMTR   => 'LANG_DFLT'),
                                         1))
                                 Bill_Doc_Type,
                             Clc_Typ_No_Tax,
                             Null Tax_No,
                             Doc_Date,
                             A_Cy,
                             NULL
                                 Doc_Dsc,
                             ROUND (
                                 SUM (DOC_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 DOC_Amt,
                             ROUND (
                                 SUM (Vat_Amt),
                                 YS_GEN_PKG.GET_FLD_VALUE ('IAS_PARA_GL',
                                                           'No_Of_Decimal'))
                                 VAt_Amt,
                             NULL
                                 Net_Amt,
                             NULL
                                 Prd_No,
                             NULL
                                 Prd_Nm,
                             NULL
                                 F_Date,
                             NULL
                                 T_Date
                        FROM GNR_TAX_RT_Purch_NO_VAT_VW
                    GROUP BY Doc_Ser,
                             Doc_No,
                             Clc_Typ_No_Tax,
                             Doc_Date,
                             A_cy,
                             BRN_NO,
                             CMP_NO) Gnr_Tax_Movmnt_Vw);


--
-- V_CHK_CLC_TYP_NO_TAX  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS20261.V_CHK_CLC_TYP_NO_TAX
(TABLE_NAME, ERR_TYPE, RCRD_CNT)
BEQUEATH DEFINER
AS 
SELECT 'GNR_TAX_SLICE' table_name, 'error when insert TAX SLICE' err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT slice_prcnt
             FROM gnr_tax_slice
           MINUS
           SELECT DISTINCT vat_per
                      FROM ias_itm_mst
                     WHERE vat_type = 1)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_CODE_DTL' table_name,
          'error when insert into GNR_TAX_CODE_DTL from interface_acc'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT ac_code_ar, ac_code_ap
             FROM gnr_tax_code_dtl
           MINUS
           SELECT vat_ac, vat_pur_a_code
             FROM interface_acc
            WHERE vat_ac || vat_pur_a_code IS NOT NULL)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_TYP_CLC_MST' table_name,
          'records in GNR_TAX_TYP_CLC_MST have CLC_TAX_TYP=0 must equal to records in GNR_TAX_CODE_mst'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT clc_typ_no
             FROM gnr_tax_typ_clc_mst
            WHERE clc_tax_typ = 0
           MINUS
           SELECT tax_no
             FROM gnr_tax_code_mst)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_TYP_CLC_MST' table_name,
          'records in GNR_TAX_TYP_CLC_MST have CLC_TAX_TYP<>0 must equal to records in flags'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT clc_tax_typ
             FROM gnr_tax_typ_clc_mst
            WHERE clc_tax_typ <> 0
           MINUS
           SELECT flg_value clc_tax_typ
             FROM s_flags
            WHERE UPPER (flg_code) = 'VAT_TYP_SI'
              AND flg_st = 1
              AND lang_no = 1
              AND flg_value <> 0)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_TYP_CLC_DTL' table_name,
          'CLC_TYP_NO in GNR_TAX_TYP_CLC_DTL must equal to  TAX_NO in GNR_TAX_TYP_CLC_DTL '
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT clc_typ_no, tax_no
             FROM gnr_tax_typ_clc_dtl
           MINUS
           SELECT clc_typ_no, clc_typ_no
             FROM gnr_tax_typ_clc_mst
            WHERE clc_tax_typ = 0)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_TYP_CLC_BRN' table_name,
          'branches must connect with tax_no that connected with same accounts in INTERFACE_ACC'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT clc_typ_no, brn_no
             FROM gnr_tax_typ_clc_brn
           MINUS
           SELECT clc_typ_no, brn_no
             FROM (SELECT clc_typ_no, brn_no
                     FROM gnr_tax_typ_clc_mst, s_brn
                    WHERE clc_tax_typ > 0
                   UNION
                   SELECT clc_typ_no, i.brn_no
                     FROM gnr_tax_code_dtl t,
                          interface_acc i,
                          gnr_tax_typ_clc_dtl d
                    WHERE t.tax_no = d.tax_no
                      AND NVL (i.vat_ac, 0) = NVL (t.ac_code_ar, 0)
                      AND NVL (i.vat_pur_a_code, 0) = NVL (t.ac_code_ap, 0)))
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_ITM' table_name,
          'there are some difreent between items that use vat and  GNR_TAX_ITM'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT i_code, vat_per, vat_type
             FROM ias_itm_mst
            WHERE NVL (vat_type, 0) = 1 AND vat_per IS NOT NULL
           MINUS
           SELECT i_code, tax_prcnt, tax_no
             FROM gnr_tax_itm)
   HAVING COUNT (*) > 0
   UNION
   SELECT 'GNR_TAX_ITM' table_name,
          'there are some difreent between items that use vat and  GNR_TAX_ITM'
                                                                     err_type,
          COUNT (*) rcrd_cnt
     FROM (SELECT i_code, tax_prcnt, tax_no
             FROM  gnr_tax_itm
            WHERE tax_no = 1 AND NVL (tax_prcnt, 0) > 0
           MINUS
           SELECT i_code, vat_per, vat_type
             FROM  ias_itm_mst
            WHERE NVL (vat_type, 0) = 1 AND vat_per IS NOT NULL)
   HAVING COUNT (*) > 0
   UNION
------------check  Clc_Typ_No_Tax------------
   SELECT table_name, 'Clc_Typ_No_Tax Is Null' err_type, rcrd_cnt
     FROM (SELECT 'Ias_Bill_Mst_Add_Disc_Rq' table_name, COUNT (*) rcrd_cnt
             FROM ias_bill_mst_add_disc_rq
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Bill_Mst_Add_Disc' table_name, COUNT (*) rcrd_cnt
             FROM ias_bill_mst_add_disc
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Sales_Order' table_name, COUNT (*) rcrd_cnt
             FROM sales_order
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Rt_Bill_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_rt_bill_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Rt_Bill_Mst_Rq' table_name, COUNT (*) rcrd_cnt
             FROM ias_rt_bill_mst_rq
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Pi_Bill_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_pi_bill_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Pr_Bill_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_pr_bill_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Ar_Cntrct_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_ar_cntrct_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Pi_Bill_Mst_Add_Disc' table_name, COUNT (*) rcrd_cnt
             FROM ias_pi_bill_mst_add_disc
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'P_Order' table_name, COUNT (*) rcrd_cnt
             FROM p_order
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Pr_Req_Bill_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_pr_req_bill_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Vnd_Quot_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_vnd_quot_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Ap_Cntrct_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_ap_cntrct_mst
            WHERE clc_typ_no_tax IS NULL
           UNION
           SELECT 'Ias_Bill_Mst' table_name, COUNT (*) rcrd_cnt
             FROM ias_bill_mst
            WHERE clc_typ_no_tax IS NULL)
    WHERE rcrd_cnt > 0
   UNION
   SELECT table_name, 'clc_typ_no_tax must allowed from vat' err_type,
