               FROM v_gnr_rq_tax_itm_movmnt
             MINUS
             SELECT doc_type, bill_doc_type, doc_jv_type, doc_no, doc_ser,
                    doc_date, tax_no, clc_typ_no, agncy_no, i_code, itm_unt,
                    p_size, i_price, disc_amt, a_code, a_cy, ac_rate,
