--
-- YS_V_DATA_FILES  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS_SYS.YS_V_DATA_FILES
(FILE_NAME, FILE_ID, TABLESPACE_NAME, BYTES, BLOCKS, 
 STATUS, RELATIVE_FNO, AUTOEXTENSIBLE, MAXBYTES, MAXBLOCKS, 
 INCREMENT_BY, USER_BYTES, USER_BLOCKS, ONLINE_STATUS, FREE_BYTES)
BEQUEATH DEFINER
AS 
select a.FILE_NAME FILE_NAME,
									a.FILE_ID FILE_ID ,
									a.TABLESPACE_NAME TABLESPACE_NAME,
									a.BYTES BYTES,
									a.BLOCKS BLOCKS, 
									a.STATUS STATUS,
									a.RELATIVE_FNO RELATIVE_FNO,
									a.AUTOEXTENSIBLE AUTOEXTENSIBLE,
									a.MAXBYTES MAXBYTES,
									a.MAXBLOCKS MAXBLOCKS,
									a.INCREMENT_BY INCREMENT_BY,
									a.USER_BYTES USER_BYTES,
									a.USER_BLOCKS USER_BLOCKS,
									a.ONLINE_STATUS ONLINE_STATUS,
									sum(b.bytes) FREE_BYTES from sys.dba_data_files a , SYS.DBA_FREE_SPACE b
									where a.file_id=b.file_id
									group by  a.FILE_NAME,
									a.FILE_ID,
									a.TABLESPACE_NAME,
									a.BYTES,
									a.BLOCKS,
									a.STATUS ,
									a.RELATIVE_FNO,
									a.AUTOEXTENSIBLE,
									a.MAXBYTES,
									a.MAXBLOCKS,
									a.INCREMENT_BY,
									a.USER_BYTES,
									a.USER_BLOCKS,
									a.ONLINE_STATUS 
									 Union all
									SELECT FILE_NAME,NULL,TABLESPACE_NAME,BYTES,NULL,'TEMP FILE',
									NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL FROM dba_temp_files;


