--
-- YS_V_TBLSP_ST  (View) 
--
CREATE OR REPLACE FORCE VIEW IAS_SYS.YS_V_TBLSP_ST
(TABLESPACE_NAME, TABLESPACE_SIZE, USED_SPACE, TABLESPACE_FREE, COLLECTION_DATE, 
 USED_PERCENT, T_LARGEST, T_MAX_SIZE, T_PCT_MAX_USED, T_EXTENT_MAN, 
 T_SEGEMENT)
BEQUEATH DEFINER
AS 
SELECT (SELECT tablespace_name
					             FROM dba_tablespaces
					            WHERE tablespace_name = b.tablespace_name)
					             TABLESPACE_NAME,
					          ROUND (kbytes_alloc / 1024, 2) TABLESPACE_SIZE,
					          ROUND ( (kbytes_alloc - NVL (kbytes_free, 0)) / 1024, 2) USED_SPACE,
					          ROUND (NVL (kbytes_free, 0) / 1024, 2) TABLESPACE_FREE,
					          SYSDATE COLLECTION_DATE,
					          ROUND (
					             ( (kbytes_alloc - NVL (kbytes_free, 0)) / kbytes_alloc) * 100,
					             2)
					             USED_PERCENT,
					          ROUND (NVL (largest, 0) / 1024, 2) T_LARGEST,
					          ROUND (NVL (kbytes_max, kbytes_alloc) / 1024, 2) T_MAX_SIZE,
					          ROUND (
					             DECODE (
					                kbytes_max,
					                0,
					                0,
					                ( (kbytes_alloc - NVL (kbytes_free, 0)) / kbytes_max) * 100),
					             2)
					             T_PCT_MAX_USED,
					          (SELECT extent_management
					             FROM dba_tablespaces
					            WHERE tablespace_name = b.tablespace_name)
					             T_EXTENT_MAN,
					          (SELECT segment_space_management
					             FROM dba_tablespaces
					            WHERE tablespace_name = b.tablespace_name)
					             T_SEGEMENT
					     FROM (  SELECT SUM (bytes) / 1024 Kbytes_free,
					                    MAX (bytes) / 1024 largest,
					                    tablespace_name
					               FROM sys.dba_free_space
					           GROUP BY tablespace_name) a,
					          (  SELECT SUM (bytes) / 1024 Kbytes_alloc,
					                    SUM (maxbytes) / 1024 Kbytes_max,
					                    tablespace_name
					               FROM sys.dba_data_files
					           GROUP BY tablespace_name
					           UNION ALL
					             SELECT SUM (bytes) / 1024 Kbytes_alloc,
					                    SUM (maxbytes) / 1024 Kbytes_max,
					                    tablespace_name
					               FROM sys.dba_temp_files
					           GROUP BY tablespace_name) b
					    WHERE a.tablespace_name = b.tablespace_name
					   UNION ALL
					   SELECT TABLESPACE_NAME,
					          ROUND (BYTES / 1024 / 1024, 2),
					          ROUND (BYTES / 1024 / 1024, 2),
					          NULL,
					          NULL,
					          NULL,
					          NULL,
					          NULL,
					          NULL,
					          NULL,
					          NULL
					     FROM sys.dba_temp_files
					   ORDER BY 2;


